This section contains the contents of the repository's files.name: PokeMod — Tests + APK

on:
  push:
    branches: ["main", "arena/**"]
    paths: ["web/**", "android/**", "tools/**", "content/**", "docs/**", "Scripts_corregido/**", "pokemon_fire_ash/**", "package.json", "package-lock.json", ".github/workflows/build-apk.yml"]
  pull_request:
    branches: ["main"]
    paths: ["web/**", "android/**", "tools/**", "content/**", "docs/**", "Scripts_corregido/**", "pokemon_fire_ash/**", "package.json", "package-lock.json", ".github/workflows/build-apk.yml"]
  workflow_dispatch: {}
  release:
    types: [created]

jobs:
  test:
    name: Tests JS (Marshal/PBS/Table)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: "22"
      - name: Instalar dependencias reproducibles
        run: npm ci
      - name: Preparar derivados del material de referencia
        # Los mosaicos fuente (Mapas/Crepypastas) sí están versionados, pero los recortes
        # (slices/), los tilesets deducidos y las hojas origen son artefactos ignorados por
        # git: se regeneran aquí para que la verificación tenga contra qué comparar.
        run: npm run dn:preparar
      - name: Construir el paquete de la Expansión Multiversal
        # Fire_Ash_Expansion_Multiversal.zip es un artefacto generado (.gitignore lo excluye,
        # igual que a los recortes de referencia): se construye aquí para que la auditoría
        # pueda compararlo con el juego. La carpeta Expansion_Multiversal/ sí está versionada.
        run: npm run build:expansion:package
      - name: Construir el paquete de Ciudad Teckel / Isla Paraíso
        # Fire_Ash_Ciudad_Teckel_Paraiso.zip también es artefacto ignorado por git:
        # verify:teckel lo audita, así que se regenera aquí antes de verify:all.
        run: npm run build:teckel
      - name: Pruebas y auditoría completa de paquetes y mapas
        run: npm run verify:all
      - name: Pipeline narrativo con compuertas externas
        run: node tools/atlas_narrative_pipeline.mjs --qa content/atlas_tier1_blueprints_approved.json
      - name: Sintaxis de todos los módulos
        run: |
          for f in web/js/*.js tools/*.mjs tools/lib/*.mjs; do
            case "$f" in *.test.mjs) continue;; esac
            node --check "$f" || exit 1
          done
          echo "Todos los módulos OK"

  build-apk:
    name: Compilar APK (debug)
    runs-on: ubuntu-latest
    needs: test
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: "17"
      - name: SDK Android (el runner ya lo trae; verificar)
        run: |
          echo "ANDROID_HOME=$ANDROID_HOME"
          echo "ANDROID_SDK_ROOT=$ANDROID_SDK_ROOT"
          ls "$ANDROID_HOME" || ls "$ANDROID_SDK_ROOT"
          yes | sdkmanager --licenses > /dev/null || true
          sdkmanager "platforms;android-34" "build-tools;34.0.0" || echo "SDK ya presente, sigo"
      - name: Instalar Gradle 8.7
        run: |
          curl -sL https://services.gradle.org/distributions/gradle-8.7-bin.zip -o /tmp/gradle.zip
          unzip -q /tmp/gradle.zip -d /tmp
          echo "/tmp/gradle-8.7/bin" >> $GITHUB_PATH
          /tmp/gradle-8.7/bin/gradle --version
      - name: Compilar APK (debug)
        run: |
          cd android
          gradle assembleDebug --stacktrace > /tmp/gradle.log 2>&1
          GRADLE_EXIT=$?
          tail -n 40 /tmp/gradle.log
          exit "$GRADLE_EXIT"
      - name: Publicar log si falla (diagnóstico)
        if: failure()
        run: |
          tail -c 48000 /tmp/gradle.log > /tmp/tail.txt || echo "(sin log)" > /tmp/tail.txt
          python3 - <<'PYEOF'
          data = open('/tmp/tail.txt', 'rb').read().decode('utf-8', 'replace')
          data = data.replace('%', '%25').replace('\r', '%0D').replace('\n', '%0A')
          for i in range(0, len(data), 8000):
              print(f"::error title=gradle-log-{i // 8000}::{data[i:i+8000]}")
          PYEOF
      - name: Renombrar APK
        run: |
          ls android/app/build/outputs/apk/debug/
          cp android/app/build/outputs/apk/debug/app-debug.apk \
             android/app/build/outputs/apk/debug/PokeMod-Studio-FireAsh.apk
      - uses: actions/upload-artifact@v4
        with:
          name: PokeMod-Studio-FireAsh-APK
          path: android/app/build/outputs/apk/debug/PokeMod-Studio-FireAsh.apk
          if-no-files-found: error
      - name: Adjuntar a la Release
        if: github.event_name == 'release'
        uses: softprops/action-gh-release@v2
        with:
          files: android/app/build/outputs/apk/debug/PokeMod-Studio-FireAsh.apkadsatextpackage com.pokemod.fireash

import android.net.Uri
import android.os.Bundle
import android.util.Base64
import android.webkit.JavascriptInterface
import android.webkit.WebSettings
import android.webkit.WebView
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.documentfile.provider.DocumentFile
import org.json.JSONArray
import org.json.JSONObject

/**
 * PokeMod Studio — Fire Ash Edition (APK).
 * WebView sin conexión que carga la app de assets + puente SAF para editar
 * la carpeta de Fire Ash (la misma que usa Kirin). Sin NDK → APK universal
 * compatible con ARM64 (Kirin/Snapdragon/Exynos), ARMv7 y x86_64.
 */
class MainActivity : AppCompatActivity() {

    private lateinit var web: WebView
    private var treeUri: Uri? = null

    private val pickFolder = registerForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        if (uri != null) {
            contentResolver.takePersistableUriPermission(
                uri, android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION or android.content.Intent.FLAG_GRANT_WRITE_URI_PERMISSION
            )
            treeUri = uri
            getSharedPreferences("pokemod", MODE_PRIVATE).edit().putString("tree", uri.toString()).apply()
            val name = root()?.name ?: "carpeta"
            web.evaluateJavascript("window.__pmResolveFolder && window.__pmResolveFolder(${JSONObject.quote(name)})", null)
        } else {
            web.evaluateJavascript("window.__pmResolveFolder && window.__pmResolveFolder('')", null)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        getSharedPreferences("pokemod", MODE_PRIVATE).getString("tree", null)?.let {
            try { treeUri = Uri.parse(it) } catch (_: Exception) { }
        }
        web = WebView(this)
        setContentView(web)
        with(web.settings) {
            javaScriptEnabled = true
            domStorageEnabled = true
            allowFileAccess = true
            mediaPlaybackRequiresUserGesture = false
            cacheMode = WebSettings.LOAD_DEFAULT
        }
        web.addJavascriptInterface(Bridge(), "PokeModBridge")
        web.loadUrl("file:///android_asset/web/index.html")
    }

    private fun root(): DocumentFile? {
        val u = treeUri ?: return null
        return DocumentFile.fromTreeUri(this, u)
    }

    /** Busca hijo con caja exacta o aproximada (¡clave! Windows perdona, Android no). */
    private fun childOf(dir: DocumentFile, name: String, wantDir: Boolean? = null): DocumentFile? {
        dir.findFile(name)?.let { if (wantDir == null || it.isDirectory == wantDir) return it }
        for (f in dir.listFiles()) {
            if (f.name?.equals(name, ignoreCase = true) == true) {
                if (wantDir == null || f.isDirectory == wantDir) return f
            }
        }
        return null
    }

    private fun resolve(rel: String): DocumentFile? {
        var cur = root() ?: return null
        val parts = rel.split("/").filter { it.isNotEmpty() && it != "." }
        for (p in parts) {
            cur = childOf(cur, p) ?: return null
        }
        return cur
    }

    private fun mimeFor(name: String): String = when (name.substringAfterLast('.', "").lowercase()) {
        "png" -> "image/png"
        "jpg", "jpeg" -> "image/jpeg"
        "bmp" -> "image/bmp"
        "txt", "ini", "json", "rb" -> "text/plain"
        else -> "application/octet-stream"
    }

    inner class Bridge {

        @JavascriptInterface
        fun pmHasFolder(): String = if (root() != null) "1" else "0"

        @JavascriptInterface
        fun pmPickFolder() {
            runOnUiThread { pickFolder.launch(null) }
        }

        @JavascriptInterface
        fun pmFolderName(): String = root()?.name ?: ""

        @JavascriptInterface
        fun pmExists(rel: String): String = if (resolve(rel) != null) "1" else "0"

        @JavascriptInterface
        fun pmSize(rel: String): String = resolve(rel)?.length()?.toString() ?: "-1"

        @JavascriptInterface
        fun pmList(rel: String): String {
            val dir = (if (rel.isEmpty()) root() else resolve(rel))
                ?: throw IllegalArgumentException("No existe: $rel")
            val arr = JSONArray()
            for (f in dir.listFiles()) {
                val o = JSONObject()
                o.put("n", f.name ?: "")
                o.put("d", f.isDirectory)
                o.put("s", if (f.isDirectory) 0 else f.length())
                arr.put(o)
            }
            return arr.toString()
        }

        @JavascriptInterface
        fun pmRead(rel: String): String {
            val f = resolve(rel) ?: throw IllegalArgumentException("No existe: $rel")
            val bytes = contentResolver.openInputStream(f.uri)?.use { it.readBytes() }
                ?: throw IllegalStateException("No se pudo leer: $rel")
            return Base64.encodeToString(bytes, Base64.NO_WRAP)
        }

        @JavascriptInterface
        fun pmReadChunk(rel: String, off: Int, len: Int): String {
            val f = resolve(rel) ?: throw IllegalArgumentException("No existe: $rel")
            contentResolver.openInputStream(f.uri)?.use { ins ->
                var toSkip = off.toLong()
                while (toSkip > 0) {
                    val s = ins.skip(toSkip)
                    if (s <= 0) break
                    toSkip -= s
                }
                val buf = ByteArray(len)
                var got = 0
                while (got < len) {
                    val r = ins.read(buf, got, len - got)
                    if (r < 0) break
                    got += r
                }
                return Base64.encodeToString(buf.copyOf(got), Base64.NO_WRAP)
            } ?: throw IllegalStateException("No se pudo leer: $rel")
        }

        @JavascriptInterface
        fun pmWrite(rel: String, b64: String): String {
            val data = Base64.decode(b64, Base64.DEFAULT)
            val parts = rel.split("/").filter { it.isNotEmpty() && it != "." }
            if (parts.isEmpty()) throw IllegalArgumentException("Ruta vacía")
            var dir = root() ?: throw IllegalStateException("Sin carpeta")
            for (p in parts.dropLast(1)) {
                dir = childOf(dir, p, true) ?: dir.createDirectory(p)
                    ?: throw IllegalStateException("No se pudo crear: $p")
            }
            val name = parts.last()
            var file = childOf(dir, name, false)
            if (file == null) {
                file = dir.createFile(mimeFor(name), name)
                    ?: throw IllegalStateException("No se pudo crear: $name")
            }
            contentResolver.openOutputStream(file.uri, "wt")?.use { it.write(data) }
                ?: throw IllegalStateException("No se pudo escribir: $rel")
            return "ok"
        }

        @JavascriptInterface
        fun pmDelete(rel: String): String {
            val f = resolve(rel) ?: throw IllegalArgumentException("No existe: $rel")
            if (!f.delete()) throw IllegalStateException("No se pudo borrar: $rel")
            return "ok"
        }

        @JavascriptInterface
        fun pmMkdir(rel: String): String {
            var dir = root() ?: throw IllegalStateException("Sin carpeta")
            for (p in rel.split("/").filter { it.isNotEmpty() && it != "." }) {
                dir = childOf(dir, p, true) ?: dir.createDirectory(p)
                    ?: throw IllegalStateException("No se pudo crear: $p")
            }
            return "ok"
        }

        @JavascriptInterface
        fun pmWalk(rel: String, max: Int): String {
            val out = JSONArray()
            var count = 0
            fun rec(dir: DocumentFile, prefix: String) {
                if (count >= max) return
                for (f in dir.listFiles()) {
                    if (count >= max) return
                    val p = if (prefix.isEmpty()) (f.name ?: "") else prefix + "/" + (f.name ?: "")
                    if (f.isDirectory) rec(f, p)
                    else {
                        out.put(p)
                        count++
                    }
                }
            }
            val start = if (rel.isEmpty()) root() else resolve(rel)
            if (start != null && start.isDirectory) rec(start, rel.trim('/'))
            // pmWalk("") debe devolver rutas relativas a la raíz:
            if (rel.isEmpty()) {
                val fixed = JSONArray()
                for (i in 0 until out.length()) fixed.put(out.getString(i).trimStart('/'))
                return fixed.toString()
            }
            return out.toString()
        }
    }
