  "rutas": [
    {
      "de": 2200, "a": 2260,
      "nombre": "Senda de las Afueras",
      "texto": ["Un sendero de nieve apelmazada sube hacia las afueras.", "La nieve cruje distinto aquí: como si el suelo estuviera hueco por debajo."]
    },
    { "de": 2260, "a": 2261, "nombre": "Camino a Lerucean", "texto": ["El camino se ensancha y aparecen las primeras casas."] },
    {
      "de": 2260, "a": 2262, "nombre": "Boca de la Glaciar",
      "texto": ["Una grieta azulada en la roca. Sale vaho de dentro, lento y constante.", "No hay sol ahí abajo. No lo ha habido nunca."]
    },
    { "de": 2260, "a": 2265, "nombre": "Casa del Pescador", "texto": ["La puerta está sin cerrar. Dentro huele a sopa."] },
    { "de": 2261, "a": 2263, "nombre": "Centro Pokémon", "texto": ["Empujas la puerta y el contraste de calor te empaña las gafas."] },
    { "de": 2261, "a": 2264, "nombre": "Tienda de Lerucean", "texto": ["Una campanilla suena al entrar."] },
    {
      "de": 2210, "a": 2270,
      "nombre": "Senda Luminosa",
      "texto": ["El sendero sube entre acantilados y el mar se queda abajo, muy azul.", "Aquí la luz no es la de Kanto: es más limpia, como recién lavada."]
    },
    { "de": 2270, "a": 2271, "nombre": "Camino a Ciudad Platino", "texto": ["El camino baja hacia el puerto."] },
    {
      "de": 2270, "a": 2272, "nombre": "Entrada de la Zona Safari",
      "texto": ["Una cancela verde y un cartel: «Se entra por parejas. Se sale cuando se quiera»."]
    },
    { "de": 2271, "a": 2273, "nombre": "Centro Pokémon", "texto": ["El Centro de Platino tiene las ventanas abiertas al mar."] },
    { "de": 2271, "a": 2274, "nombre": "Tienda de Platino", "texto": ["Todo reluce. Incluso el suelo."] },
    {
      "de": 2271, "a": 2275,
      "nombre": "Laboratorio del Fragmento",
      "texto": ["Un cartel manuscrito: «Si el Fragmento parpadea, no lo toquéis. Avidadme»."]
    },
    {
      "de": 2220, "a": 2280,
      "nombre": "Escollera interior",
      "texto": ["Bajas por una escalera de hierro y el ruido de la base se vuelve mecánico.", "Ash se guarda la gorra en la mochila. Desde aquí, no es Ash Ketchum: es el Recluta 447."]
    },
    { "de": 2280, "a": 2281, "nombre": "Puerta del vestíbulo", "texto": ["Un recepcionista ni levanta la vista. Señala el pasillo con dos dedos."] },
    { "de": 2281, "a": 2282, "nombre": "Pasillo de tuberías", "texto": ["Las tuberías corren por el techo y gotean a un ritmo constante."] },
    { "de": 2282, "a": 2283, "nombre": "Sala de Máquinas", "texto": ["El calor aquí es bestial. Alguien ha dejado un ventilador apuntando a la pared."] },
    { "de": 2282, "a": 2284, "nombre": "Almacén", "texto": ["Cajas hasta el techo, todas con el mismo logotipo."] },
    { "de": 2282, "a": 2285, "nombre": "Enfermería", "texto": ["El pasillo se enfría de golpe. Aquí se habla bajo."] },
