    "equipo": ["PERSIAN", "NIDOKING", "NIDOQUEEN", "DRAPION", "TOXICROAK", "BISHARP"],
    "intro": [
      "Un tipo con el uniforme impecable espera apoyado en la pared.",
      "Rival: Yo subí más rápido que tú. Y no me paré a curar a nadie."
    ],
    "victoria": "Rival: Me has ganado… y has subido igual. Entonces era mentira lo de que hay que pisar a alguien.",
    "derrota": "Rival: Ya hablaremos cuando te decidas a ser duro. Yo sigo esperando."
  },
  "medalla": {
    "id": "ROCKETINSIGNIA",
    "nombre": "Insignia del Infiltrado",
    "base": "BOULDERBADGE"
  }
