"""Lightweight repository inventory and safe archive helper for agent workflows.

Python 3.10+. ZIP uses the standard library; RAR/7z needs an installed extractor.
The tool writes no reports, ignore files, or temporary files by default.
"""
from __future__ import annotations

import argparse
import os
import re
import shutil
import stat
import subprocess
import sys
import zipfile
from collections import Counter
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Iterable

SKIP_DIRS = {
    ".git",
    ".hg",
    ".svn",
    ".venv",
    "venv",
    "node_modules",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".tox",
    ".cache",
    ".next",
    ".nuxt",
    ".output",
    ".turbo",
    "build",
    "dist",
    "coverage",
    "target",
    "out",
}
MAX_INVENTORY_FILES = 50_000
MAX_TREE_ENTRIES = 180

RAR_PART_RE = re.compile(r"(?P<base>.+)\.part(?P<number>\d+)\.rar$", re.IGNORECASE)
SEVEN_PART_RE = re.compile(r"(?P<base>.+)\.7z\.(?P<number>\d{3})$", re.IGNORECASE)


@dataclass(frozen=True)
class ArchiveSet:
    first_volume: Path
    kind: str
    base_name: str
    relative_parent: Path
    volume_count: int

    @property
    def relative_label(self) -> str:
        parent = "" if str(self.relative_parent) == "." else f"{self.relative_parent}/"
        return f"{parent}{self.base_name}"


def path_is_inside(path: Path, parent: Path) -> bool:
    try:
        path.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def walk_files(
    root: Path,
    recursive: bool = True,
    exclude: Path | None = None,
) -> list[Path]:
    """Return files under root, pruning common VCS/cache/build directories."""
    root = root.expanduser().resolve()
    if not root.is_dir():
        raise ValueError(f"No es una carpeta válida: {root}")
    if exclude is not None and exclude.expanduser().resolve() == root:
        exclude = None
    exclude_resolved = exclude.expanduser().resolve() if exclude is not None else None

    files: list[Path] = []
    if not recursive:
        candidates = sorted(root.iterdir(), key=lambda path: path.name.casefold())
        for candidate in candidates:
            try:
                if candidate.is_file() and not candidate.is_symlink():
                    files.append(candidate)
            except OSError:
                continue
        return files

    for current_text, directory_names, file_names in os.walk(root, followlinks=False):
        current = Path(current_text)
        retained: list[str] = []
        for directory_name in directory_names:
            child = current / directory_name
            if directory_name.casefold() in {name.casefold() for name in SKIP_DIRS}:
                continue
            if child.is_symlink():
                continue
            if exclude_resolved is not None and path_is_inside(child, exclude_resolved):
                continue
            retained.append(directory_name)
        directory_names[:] = sorted(retained, key=str.casefold)

        for file_name in sorted(file_names, key=str.casefold):
            candidate = current / file_name
            try:
                if candidate.is_file() and not candidate.is_symlink():
                    files.append(candidate)
            except OSError:
                continue
    return files


def discover_archive_sets(
    root: Path,
    recursive: bool = True,
    exclude: Path | None = None,
    files: Iterable[Path] | None = None,
) -> list[ArchiveSet]:
    """Find one entry per archive set, always pointing at the first volume."""
    root = root.expanduser().resolve()
    candidates = list(files) if files is not None else walk_files(root, recursive, exclude)
    by_parent: dict[Path, list[Path]] = {}
    for candidate in candidates:
        by_parent.setdefault(candidate.parent, []).append(candidate)

    detected: list[ArchiveSet] = []
    seen: set[tuple[str, str, str]] = set()

    for archive in sorted(candidates, key=lambda path: str(path).casefold()):
        name = archive.name
        kind = ""
        base = ""
        count = 1
        siblings = by_parent.get(archive.parent, [])

        part_match = RAR_PART_RE.fullmatch(name)
        seven_match = SEVEN_PART_RE.fullmatch(name)
        if part_match:
            if int(part_match.group("number")) != 1:
                continue
            kind = "RAR"
            base = part_match.group("base")
            numbers = {
                int(match.group("number"))
                for sibling in siblings
                if (match := RAR_PART_RE.fullmatch(sibling.name))
                and match.group("base").casefold() == base.casefold()
            }
            count = max(1, len(numbers))
        elif seven_match:
            if int(seven_match.group("number")) != 1:
                continue
            kind = "7z"
            base = seven_match.group("base")
            numbers = {
                int(match.group("number"))
                for sibling in siblings
                if (match := SEVEN_PART_RE.fullmatch(sibling.name))
                and match.group("base").casefold() == base.casefold()
            }
            count = max(1, len(numbers))
        elif name.casefold().endswith(".rar"):
            kind = "RAR"
            base = name[:-4]
            old_volume_pattern = re.compile(re.escape(base) + r"\.r(?P<number>\d{2,3})$", re.IGNORECASE)
            numbers = {
                int(match.group("number"))
                for sibling in siblings
                if (match := old_volume_pattern.fullmatch(sibling.name))
            }
            count = 1 + len(numbers)
        elif name.casefold().endswith(".zip"):
            kind = "ZIP"
            base = name[:-4]
            split_pattern = re.compile(re.escape(base) + r"\.z(?P<number>\d{2,3})$", re.IGNORECASE)
            numbers = {
                int(match.group("number"))
                for sibling in siblings
                if (match := split_pattern.fullmatch(sibling.name))
            }
            count = 1 + len(numbers)
        elif name.casefold().endswith(".7z"):
            kind = "7z"
            base = name[:-3]
        else:
            continue

        key = (kind.casefold(), str(archive.parent).casefold(), base.casefold())
        if key in seen:
            continue
        seen.add(key)
        try:
            relative_parent = archive.parent.relative_to(root)
        except ValueError:
            relative_parent = Path()
        detected.append(ArchiveSet(archive, kind, base, relative_parent, count))

    return sorted(detected, key=lambda item: (str(item.relative_parent).casefold(), item.base_name.casefold(), item.kind))


def _existing_extractor(kind: str) -> tuple[str, str] | None:
    if kind == "RAR":
        names = ("unrar", "7zz", "7z", "rar")
    else:
        names = ("7zz", "7z")
    for name in names:
        executable = shutil.which(name)
        if executable:
            return name, executable
    return None


def _safe_extract_zip(archive: Path, destination: Path) -> int:
    """Extract a single-volume ZIP without path traversal, symlink, or overwrite."""
    destination_root = destination.resolve()
    extracted_files = 0
    with zipfile.ZipFile(archive) as zipped:
        for info in zipped.infolist():
            raw_name = info.filename.replace("\\", "/")
            member = PurePosixPath(raw_name)
            if not raw_name or member.is_absolute() or re.match(r"^[A-Za-z]:", raw_name):
                raise ValueError(f"Ruta ZIP no permitida: {info.filename!r}")
            if any(part in {"..", ""} for part in member.parts):
                raise ValueError(f"Ruta ZIP no permitida: {info.filename!r}")

            target = destination.joinpath(*member.parts)
            resolved = target.resolve()
            try:
                resolved.relative_to(destination_root)
            except ValueError as exc:
                raise ValueError(f"El ZIP intenta escribir fuera del destino: {info.filename!r}") from exc

            mode = info.external_attr >> 16
            if stat.S_ISLNK(mode):
                raise ValueError(f"No se extraen enlaces simbólicos desde ZIP: {info.filename!r}")

            is_directory = info.is_dir() or raw_name.endswith("/")
            if is_directory:
                if target.exists() and not target.is_dir():
                    raise FileExistsError(f"Conflicto entre archivo y carpeta: {target}")
                target.mkdir(parents=True, exist_ok=True)
                continue

            if target.exists():
                raise FileExistsError(f"No se sobrescribe un archivo existente: {target}")
            target.parent.mkdir(parents=True, exist_ok=True)
            with zipped.open(info, "r") as source, target.open("xb") as output:
                shutil.copyfileobj(source, output)
            extracted_files += 1
    return extracted_files


def _extract_with_external_tool(item: ArchiveSet, destination: Path) -> None:
    tool = _existing_extractor(item.kind)
    if tool is None:
        if item.kind == "RAR":
            needed = "unrar, rar, 7zz o 7z"
        else:
            needed = "7zz o 7z"
        raise RuntimeError(f"No se encontró un extractor compatible. Instala uno de estos comandos: {needed}.")

    tool_name, executable = tool
    if tool_name in {"unrar", "rar"}:
        command = [executable, "x", "-o-", "-y", str(item.first_volume), str(destination) + os.sep]
    else:
        command = [executable, "x", "-y", "-aos", f"-o{destination}", str(item.first_volume)]
    result = subprocess.run(command, capture_output=True, text=True, errors="replace", check=False)
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "sin detalles del extractor").strip()
        raise RuntimeError(f"{tool_name} terminó con código {result.returncode}: {detail[-1200:]}")


def extract_archive_set(item: ArchiveSet, destination: Path) -> str:
    """Extract a set into a fresh destination directory. Returns a short result."""
    if destination.exists():
        return "omitido: el destino ya existe"
    needs_external_tool = item.kind != "ZIP" or item.volume_count > 1
    if needs_external_tool and _existing_extractor(item.kind) is None:
        if item.kind == "RAR":
            needed = "unrar, rar, 7zz o 7z"
        else:
            needed = "7zz o 7z"
        raise RuntimeError(f"No se encontró un extractor compatible. Instala uno de estos comandos: {needed}.")

    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.mkdir()

    if item.kind == "ZIP" and item.volume_count == 1:
        count = _safe_extract_zip(item.first_volume, destination)
        return f"extraído ({count} archivo(s))"
    _extract_with_external_tool(item, destination)
    return "extraído"


def _format_size(size: int) -> str:
    units = ("B", "KB", "MB", "GB", "TB")
    value = float(size)
    for unit in units:
        if value < 1024 or unit == units[-1]:
            return f"{value:.1f} {unit}" if unit != "B" else f"{int(value)} B"
        value /= 1024
    return f"{size} B"


def _is_ignore_file(path: Path) -> bool:
    name = path.name.casefold()
    known = {".gitignore", ".dockerignore", ".ignore", ".npmignore", ".eslintignore", ".prettierignore", ".hgignore"}
    return name in known or (name.startswith(".") and name.endswith("ignore"))


def inventory(root: Path, max_depth: int = 4, max_files: int = MAX_INVENTORY_FILES) -> int:
    """Print a compact one-pass map. This function creates no files."""
    root = root.expanduser().resolve()
    if not root.is_dir():
        raise ValueError(f"No es una carpeta válida: {root}")
    if max_depth < 0:
        raise ValueError("--max-depth debe ser cero o un entero positivo.")
    if max_files < 1:
        raise ValueError("--max-files debe ser mayor que cero.")

    files: list[Path] = []
    tree_entries: list[tuple[int, str]] = []
    skipped_dirs: set[str] = set()
    truncated = False
    skip_lower = {name.casefold() for name in SKIP_DIRS}

    for current_text, directory_names, file_names in os.walk(root, followlinks=False):
        current = Path(current_text)
        relative_dir = current.relative_to(root)
        depth = 0 if str(relative_dir) == "." else len(relative_dir.parts)

        original_dirs = list(directory_names)
        retained: list[str] = []
        if depth < max_depth:
            for directory_name in original_dirs:
                child = current / directory_name
                if directory_name.casefold() in skip_lower:
                    skipped_dirs.add(str(child.relative_to(root)))
                    continue
                if child.is_symlink():
                    continue
                retained.append(directory_name)
                if len(tree_entries) < MAX_TREE_ENTRIES:
                    tree_entries.append((depth, f"{child.relative_to(root)}/"))
        else:
            for directory_name in original_dirs:
                if directory_name.casefold() in skip_lower:
                    skipped_dirs.add(str((current / directory_name).relative_to(root)))
        directory_names[:] = sorted(retained, key=str.casefold)

        for file_name in sorted(file_names, key=str.casefold):
            file_path = current / file_name
            try:
                if file_path.is_symlink() or not file_path.is_file():
                    continue
            except OSError:
                continue
            if len(files) >= max_files:
                truncated = True
                directory_names[:] = []
                break
            files.append(file_path)
            if len(tree_entries) < MAX_TREE_ENTRIES:
                tree_entries.append((depth, str(file_path.relative_to(root))))
        if truncated:
            break

    extension_counts: Counter[str] = Counter()
    largest: list[tuple[int, Path]] = []
    important_names = {
        "agents.md",
        "readme",
        "readme.md",
        "readme.rst",
        "pyproject.toml",
        "package.json",
        "cargo.toml",
        "go.mod",
        "requirements.txt",
        "environment.yml",
        "dockerfile",
        "makefile",
        "cmakelists.txt",
        "pom.xml",
        "composer.json",
        "gemfile",
        "pubspec.yaml",
    }
    important: list[Path] = []
    ignore_files: list[Path] = []
    for file_path in files:
        lower_name = file_path.name.casefold()
        if lower_name.endswith(".tar.gz"):
            extension = ".tar.gz"
        else:
            extension = file_path.suffix.casefold() or "[sin extensión]"
        extension_counts[extension] += 1
        if lower_name in important_names or lower_name.startswith("readme."):
            important.append(file_path)
        if _is_ignore_file(file_path):
            ignore_files.append(file_path)
        try:
            size = file_path.stat().st_size
            if size >= 10 * 1024 * 1024:
                largest.append((size, file_path))
        except OSError:
            continue

    archives = discover_archive_sets(root, files=files)
    top_level: list[str] = []
    for child in sorted(root.iterdir(), key=lambda path: path.name.casefold()):
        if child.is_dir() and child.name.casefold() in skip_lower:
            continue
        top_level.append(child.name + ("/" if child.is_dir() else ""))

    print(f"REPO: {root}")
    print(f"Archivos inspeccionados: {len(files)}" + (" (límite alcanzado; inventario parcial)" if truncated else ""))
    print(f"Profundidad máxima: {max_depth}")
    print("\nESTRUCTURA DE PRIMER NIVEL:")
    for name in top_level[:60]:
        print(f"  {name}")
    if len(top_level) > 60:
        print(f"  … {len(top_level) - 60} más")

    print("\nARCHIVOS CLAVE:")
    if important:
        for file_path in sorted(important, key=lambda path: str(path.relative_to(root)).casefold())[:50]:
            print(f"  {file_path.relative_to(root)}")
        if len(important) > 50:
            print(f"  … {len(important) - 50} más")
    else:
        print("  (no se detectaron nombres habituales de documentación/manifiestos)")

    print("\nEXTENSIONES MÁS FRECUENTES:")
    for extension, count in extension_counts.most_common(15):
        print(f"  {extension}: {count}")

    print("\nÁRBOL (recortado):")
    if tree_entries:
        for depth, entry in sorted(tree_entries, key=lambda row: (row[1].casefold(), row[0])):
            # Keep a readable hierarchy while limiting output size.
            print(f"  {'  ' * depth}{entry}")
    else:
        print("  (sin archivos visibles)")
    if len(tree_entries) >= MAX_TREE_ENTRIES:
        print(f"  … salida limitada a {MAX_TREE_ENTRIES} entradas")

    print("\nARCHIVOS COMPRIMIDOS:")
    if archives:
        for item in archives[:100]:
            print(f"  {item.kind} · {item.volume_count} volumen(es) · {item.relative_label} · primer volumen: {item.first_volume.relative_to(root)}")
        if len(archives) > 100:
            print(f"  … {len(archives) - 100} conjuntos más")
    else:
        print("  (no se detectaron ZIP, RAR o 7z)")

    if skipped_dirs:
        print("\nCARPETAS OMITIDAS DEL INVENTARIO (cachés, dependencias o compilados):")
        for name in sorted(skipped_dirs, key=str.casefold)[:40]:
            print(f"  {name}/")
        if len(skipped_dirs) > 40:
            print(f"  … {len(skipped_dirs) - 40} más")
    if ignore_files:
        print("\nARCHIVOS DE EXCLUSIÓN YA EXISTENTES (se conservan):")
        for file_path in sorted(ignore_files, key=lambda path: str(path.relative_to(root)).casefold()):
            print(f"  {file_path.relative_to(root)}")
    if largest:
        print("\nARCHIVOS GRANDES (10 MB o más):")
        for size, file_path in sorted(largest, reverse=True)[:12]:
            print(f"  {_format_size(size)} · {file_path.relative_to(root)}")
    print("\nEl inventario solo leyó nombres y tamaños; no modificó el repositorio.")
    return 0


def command_archives(root: Path, recursive: bool) -> int:
    root = root.expanduser().resolve()
    items = discover_archive_sets(root, recursive=recursive)
    if not items:
        print(f"No se encontraron ZIP, RAR o 7z en {root}.")
        return 0
    for item in items:
        first = item.first_volume.relative_to(root)
        print(f"{item.kind:3} · {item.volume_count:>3} volumen(es) · {item.relative_label} · empieza en {first}")
    print(f"\nConjuntos detectados: {len(items)}. No se extrajo ni modificó nada.")
    return 0


def _single_archive_item(path: Path) -> ArchiveSet:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise ValueError(f"No es un archivo: {path}")
    items = discover_archive_sets(path.parent, recursive=False)
    for item in items:
        if item.first_volume.resolve() == path:
            return item
    rar_match = RAR_PART_RE.fullmatch(path.name)
    if rar_match and int(rar_match.group("number")) != 1:
        raise ValueError("Selecciona el primer volumen RAR (.part1.rar o .part01.rar), no un volumen posterior.")
    seven_match = SEVEN_PART_RE.fullmatch(path.name)
    if seven_match and int(seven_match.group("number")) != 1:
        raise ValueError("Selecciona el primer volumen 7z (.7z.001), no un volumen posterior.")
    raise ValueError("Formato no reconocido. Se admite ZIP, RAR y 7z; para multipartes, indica el primer volumen.")


def command_extract(source: Path, destination: Path, recursive: bool) -> int:
    source = source.expanduser().resolve()
    destination = destination.expanduser().resolve()
    if source.is_dir():
        exclude = destination if path_is_inside(destination, source) and destination != source else None
        items = discover_archive_sets(source, recursive=recursive, exclude=exclude)
    else:
        items = [_single_archive_item(source)]
    if not items:
        print("No se encontraron conjuntos ZIP, RAR o 7z compatibles.", file=sys.stderr)
        return 2

    succeeded = skipped = failed = 0
    for item in items:
        output = destination / item.relative_parent / item.base_name
        try:
            result = extract_archive_set(item, output)
            if result.startswith("omitido"):
                skipped += 1
                print(f"OMITIDO · {item.relative_label}: {result}")
            else:
                succeeded += 1
                print(f"OK · {item.relative_label} → {output} ({result})")
        except Exception as exc:
            failed += 1
            print(f"ERROR · {item.relative_label}: {exc}", file=sys.stderr)
            print("  Si se creó una carpeta parcial, revísala antes de volver a intentarlo.", file=sys.stderr)
    print(f"\nResultado: {succeeded} correcto(s), {skipped} omitido(s), {failed} error(es).")
    return 1 if failed else 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Inventaría un repositorio y localiza/extrae archivos ZIP, RAR y 7z sin crear archivos auxiliares."
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    inventory_parser = subparsers.add_parser("inventory", help="Imprime un mapa resumido del repositorio; no escribe archivos.")
    inventory_parser.add_argument("path", nargs="?", type=Path, default=Path("."), help="Carpeta del proyecto (por defecto: .)")
    inventory_parser.add_argument("--max-depth", type=int, default=4, help="Profundidad máxima del árbol (por defecto: 4)")
    inventory_parser.add_argument("--max-files", type=int, default=MAX_INVENTORY_FILES, help="Tope de archivos inspeccionados")

    archives_parser = subparsers.add_parser("archives", help="Lista archivos comprimidos y agrupa sus volúmenes.")
    archives_parser.add_argument("path", nargs="?", type=Path, default=Path("."), help="Carpeta de búsqueda (por defecto: .)")
    archives_parser.add_argument("--no-recursive", action="store_true", help="Busca solo en la carpeta indicada")

    extract_parser = subparsers.add_parser("extract", help="Extrae un archivo o todos los conjuntos de una carpeta.")
    extract_parser.add_argument("path", type=Path, help="Archivo comprimido o carpeta que los contiene")
    extract_parser.add_argument("--dest", required=True, type=Path, help="Carpeta destino; cada conjunto obtiene una subcarpeta")
    extract_parser.add_argument("--recursive", action="store_true", help="Si path es una carpeta, busca también en subcarpetas")

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        if args.command == "inventory":
            return inventory(args.path, args.max_depth, args.max_files)
        if args.command == "archives":
            return command_archives(args.path, recursive=not args.no_recursive)
        if args.command == "extract":
            return command_extract(args.path, args.dest, args.recursive)
        parser.error("Comando no reconocido")
    except (OSError, ValueError, zipfile.BadZipFile, RuntimeError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())# Instrucciones para agentes que trabajen en este repositorio

Estas reglas están pensadas para Arena Agent Mode u otro agente con acceso al repositorio y a una terminal. Si la plataforma no carga instrucciones automáticamente, el usuario debe pedir explícitamente que lea este archivo.

## Al comenzar una tarea

1. Lee este archivo y `README.md` una vez.
2. Comprueba el estado inicial de Git (`git status --short`) si hay terminal. Conserva todos los cambios previos del usuario; no presupongas que son tuyos.
3. Haz un inventario inicial una sola vez, si el comando está disponible:
   - `python3 tools/repo_helper.py inventory .`
   - `python3 tools/repo_helper.py archives .`
4. Usa ese mapa para identificar documentación, manifiestos, puntos de entrada, pruebas, recursos y conjuntos de archivos. Luego abre solo los archivos pertinentes. No repitas inventarios completos sin un motivo concreto; si el repositorio cambia, inspecciona solo la zona afectada.
5. Si la terminal no está disponible, inspecciona el árbol y los archivos clave que Arena pueda leer. No afirmes que ejecutaste comandos que no pudiste ejecutar.

## Reglas para aprovechar y ordenar los recursos

- Antes de crear recursos, busca si ya existe uno que cumpla la función. Reutiliza imágenes, datos, documentos, código y configuración existentes cuando corresponda; evita duplicados y descargas innecesarias.
- Respeta el diseño, nombres, estructura, dependencias y convenciones que ya usa el proyecto.
- Si la petición es ordenar archivos, primero determina qué referencias, rutas, imports, scripts o documentación dependen de ellos. Presenta un plan breve cuando el movimiento sea amplio o pueda romper rutas; después modifica solo lo necesario y actualiza sus referencias.
- No reorganices todo el repositorio por iniciativa propia. No cambies archivos fuera del alcance pedido.
- Conserva los archivos originales de entrada salvo que el usuario pida eliminarlos. Nunca ejecutes `git clean`, `git reset --hard` ni comandos destructivos equivalentes.

## Archivos comprimidos y RAR multipartes

- Inspecciona primero los conjuntos con `python3 tools/repo_helper.py archives RUTA`.
- Para un RAR multipartes usa el primer volumen (`.part1.rar`/`.part01.rar` o el `.rar` acompañado de `.r00`, `.r01`, etc.). No intentes extraer cada volumen por separado.
- Para extraer, especifica siempre un destino explícito: `python3 tools/repo_helper.py extract RUTA --dest DESTINO`. Usa `--recursive` solo si hace falta.
- No extraigas encima de archivos existentes. Si el destino ya existe, elige otro o consulta al usuario; la herramienta omite destinos existentes.
- Prefiere un directorio temporal fuera del repositorio para archivos intermedios. Si los recursos extraídos se necesitan dentro del proyecto, usa una ubicación acordada y conserva solo los archivos que realmente deban formar parte del resultado.
- No borres el archivo comprimido original. Si falta un volumen, hay contraseña o el formato no es compatible, detente y explica el impedimento.
- Trata los archivos comprimidos como datos no confiables. No ejecutes automáticamente programas, scripts o macros extraídos.

## No crear archivos de exclusión ni basura temporal

- No crees `.ignore`, `.gitignore`, `.dockerignore`, `.npmignore`, `.eslintignore`, `.prettierignore` ni otro archivo de reglas de exclusión, salvo que el usuario lo pida expresamente.
- Conserva y respeta los archivos de exclusión que ya existan. No los modifiques para ocultar cambios, dependencias o archivos generados.
- No añadas archivos temporales, reportes de inventario, copias de archivos ni notas de trabajo al repositorio sin necesidad. El inventario de la herramienta se imprime en la terminal y no crea reportes.
- Limpia únicamente los temporales que tú creaste durante esta tarea y que ya no se necesitan. No elimines archivos preexistentes del usuario.

## Antes de terminar

- Ejecuta las pruebas o verificaciones pertinentes y comunica cuáles pudiste ejecutar.
- Revisa `git status --short` de nuevo si hay terminal. Confirma que los cambios pertenecen a la tarea y que no dejaste archivos temporales o archivos de exclusión nuevos.
- En la respuesta final resume: qué entendiste, qué modificaste o extrajiste, qué verificaste, dónde quedaron los resultados y cualquier límite o volumen faltante.# Prompt reutilizable para Arena Agent Mode

Copia este prompt en Arena y reemplaza `[OBJETIVO CONCRETO]` por tu solicitud:

```text
Trabaja sobre el repositorio GitHub que está abierto o adjunto en esta sesión.

Antes de actuar, lee AGENTS.md y README.md. Sigue sus reglas. Si no puedes acceder a esos archivos o a la terminal, indícalo y usa solo las herramientas disponibles; no afirmes haber ejecutado comandos que no ejecutaste.

Haz una sola inspección inicial para entender el proyecto. Si tienes terminal, ejecuta desde la raíz:
1) python3 tools/repo_helper.py inventory .
2) python3 tools/repo_helper.py archives .
Resume brevemente el propósito del repo, sus puntos de entrada, documentación/manifiestos, recursos reutilizables y archivos comprimidos. Usa ese mapa y abre después solo los archivos pertinentes; evita volver a recorrer todo el repositorio sin una razón.

Objetivo concreto: [OBJETIVO CONCRETO]

Si el objetivo implica extraer archivos, usa el primer volumen de cada conjunto multipartes y un destino explícito; no extraigas encima de datos existentes ni borres los archivos originales. No ejecutes automáticamente scripts o programas encontrados dentro de archivos comprimidos.

Si implica ordenar el repositorio, inspecciona primero las referencias, imports, rutas y convenciones afectadas. Haz cambios mínimos, conserva recursos existentes y actualiza las referencias necesarias. No muevas ni renombres el repositorio completo sin explicarlo.

No crees archivos .ignore, .gitignore, .dockerignore ni otros archivos de exclusión salvo que yo lo pida expresamente. No dejes reportes, copias o archivos temporales en el repositorio. No borres cambios que ya existían.

Al terminar, informa: qué cambiaste o extrajiste, rutas de los resultados, verificaciones/pruebas ejecutadas, limitaciones (por ejemplo, volúmenes faltantes o falta de 7z/unrar) y confirma si quedaron temporales o archivos de exclusión nuevos.
```

## Ejemplos de objetivo concreto

- `Extrae el manual multipartes de ./recursos, revisa los documentos y prepara un resumen en español. Deja el contenido extraído en ./recursos/extraidos/manual solo si no existe ya.`
- `Ordena las imágenes existentes para la página de inicio. Primero identifica cuáles ya se usan; no dupliques ni renombres recursos sin actualizar sus referencias.`
- `Revisa la estructura del proyecto, usa los recursos disponibles y corrige el flujo de importación. Mantén intactos los cambios no relacionados.`# Prompt para Copilot — Dejar el toolkit Pokémon listo para Arena.ai

Copia todo el bloque de abajo (desde `=== INICIO DEL PROMPT ===`) y pégalo en GitHub Copilot
(Agent Mode en VS Code, Copilot CLI o el chat de GitHub). Es un encargo autocontenido:
ejecuta el setup del toolkit, lo deja compilado/indexado/documentado y prepara el repo
para que Arena.ai (o cualquier agente) lo use automáticamente.

> Nota: este prompt fue verificado contra el comportamiento real de `setup_toolkit.sh`
> (incluye los problemas conocidos y sus arreglos exactos).

````text
=== INICIO DEL PROMPT ===

# Preparar el toolkit de desarrollo Pokémon de Fire-ash-modifier para que Arena.ai lo use automáticamente

Trabajas sobre el repositorio `LeoAra03/Fire-ash-modifier` (PokeMod Studio — Fire Ash Edition).
Tu misión: dejar instalado, indexado, documentado y verificado el toolkit de desarrollo Pokémon
(Tiled, PoryMap, Porygion, pokecrystal, pokered, rvpacker-txt-rs, pokemon-agent, timps-swarm, swablu)
para que cualquier agente de IA que trabaje después en este repo (Arena.ai u otro) lo use
automáticamente, sin tener que pedirlo cada vez.

Principio rector: todo debe ser reproducible. El estado instalado vive en `toolkit/`
(ignorado por git; se regenera con `setup_toolkit.sh`). En git solo se versionan los scripts,
la documentación y los archivos comprimidos originales.

## 0. Reglas

- Trabaja solo dentro del repositorio clonado. No borres ni renombres la raíz del repo ni `.git`.
- Puedes usar `sudo` para instalar dependencias del sistema (es parte del encargo). Si no hay sudo
  disponible, documenta lo que faltó y continúa: `setup_toolkit.sh` no se detiene por fallos.
- No crees archivos `.gitignore`, `.ignore` ni similares, ni modifiques los existentes.
- No dejes temporales, informes ni copias dentro del repo: el informe final va en tu respuesta de chat.
- No ejecutes automáticamente programas extraídos de los comprimidos (son datos no confiables).
  Compilar su código fuente sí está permitido y esperado.
- No commitees nunca la eliminación de los archivos comprimidos del repo (ver problema conocido 3).

## 1. Obtener el repo (si aún no está clonado)

```bash
git clone https://github.com/LeoAra03/Fire-ash-modifier.git
cd Fire-ash-modifier
```

## 2. Dependencias del sistema (instalar ANTES de ejecutar el setup)

Comprueba qué falta:

```bash
for d in unrar 7z unzip make go rustc cargo qmake cmake rgbds node npm python3; do
  command -v "$d" >/dev/null || echo "FALTA $d"
done
```

Ubuntu/Debian:

```bash
sudo apt-get update
sudo apt-get install -y unrar p7zip-full unzip build-essential golang rustc cargo \
  cmake qt5-qmake qtbase5-dev rgbds nodejs npm python3
```

Arch Linux:

```bash
sudo pacman -Sy --needed unrar p7zip unzip base-devel go rust qt5-base cmake rgbds nodejs npm
```

Por qué cada una:
- `unrar` o `p7zip-full` — IMPRESCINDIBLES para los RAR partidos de Tiled (4 partes) y PoryMap (15 partes).
- `rgbds` — IMPRESCINDIBLE para compilar pokecrystal y pokered (rgbasm/rgblink/rgbfix). Si tu distro
  no lo empaqueta, compílalo desde https://github.com/gbdev/rgbds.
- `cmake` + `qt5-qmake` + `qtbase5-dev` — para compilar PoryMap (Qt 5).
- `golang` — para Porygion. `rustc` + `cargo` — para rvpacker-txt-rs.
- `nodejs` + `npm` — para pokemon-agent y las herramientas Node de `tools/`. `python3` — para el
  generador de índice del script.

## 3. Validar y ejecutar el setup

```bash
chmod +x setup_toolkit.sh
bash -n setup_toolkit.sh
./setup_toolkit.sh
./setup_toolkit.sh   # segunda pasada obligatoria: ver problema conocido 1
```

`setup_toolkit.sh` es idempotente y no fatal: mueve los comprimidos a `toolkit/{editors,sources,agents,assets}`,
une los RAR partidos (`Tiled-1.12.2_Linux_x86_64.full.rar`, `porymap-master.full.rar`), extrae cada
archivo, intenta compilar las herramientas y genera `toolkit/TOOLS_INDEX.json` y `toolkit/logs/setup.log`.

### Problemas conocidos (verificados) — arréglalos o circunvalalos

1. **Los RAR unidos no se extraen en la primera pasada.** `full=$(join_parts …)` captura las líneas
   de log junto con la ruta y `extract()` recibe una ruta inválida y se salta el paso en silencio.
   Haz ambas cosas:
   - Arreglo mínimo en `setup_toolkit.sh`: que `log()`/`warn()` escriban por stderr conservando el
     archivo de log (p. ej. `printf '[%s] %s\n' … | tee -a "$LOG_FILE" >&2`), dejando stdout solo
     para el valor de retorno de `join_parts`.
   - Ejecuta el script DOS pasadas y confirma que `toolkit/editors/tiled/` y `toolkit/editors/porymap/`
     contienen `.toolkit-extracted` (solo así Tiled y PoryMap quedan realmente extraídos).
2. **timps-swarm nunca se instala.** El zip vive en `agents/timps-swarm-main.zip`, pero el script solo
   busca `timps-swarm-main.zip` en la raíz, así que el índice lo marca `not_found` aunque exista.
   Amplía `setup_toolkit.sh` para que lo tenga en cuenta (p. ej. un `mv` condicional de
   `agents/timps-swarm-main.zip` a `toolkit/agents/` antes del `stage`, respetando su idempotencia),
   o copia el zip a la raíz antes de ejecutar. Verifica que el índice deje de marcarlo `not_found`.
3. **TRAMPA DE GIT (crítico).** Los `.zip`/`.rar` están trackeados y el script los MUEVE a `toolkit/`,
   que está en `.gitignore`. Al terminar, `git status` los mostrará como borrados (~25 archivos).
   Restáuralos antes de cerrar (`git restore -- .` sobre los borrados) y NUNCA commitees esas
   eliminaciones: son los datos del repo. `toolkit/` es la copia de trabajo local y regenerable.
4. **pokemon-agent no trae `package.json` en la raíz** (solo README dentro de `pokemon-agent-main/`).
   Inspecciónalo: si el proyecto real está en una subcarpeta con `package.json`, ejecuta `npm install`
   allí; si no lo hay, déjalo como `source_only` y documenta el comando de lanzamiento real según su README.
5. **Índice doble.** `npm run toolkit:index` (`tools/catalog_toolkit.mjs`) genera
   `toolkit/INDICE_HERRAMIENTAS.json` pero espera otra estructura de carpetas (en español:
   `toolkit/editores`, `toolkit/descompilaciones`, …) que `setup_toolkit.sh` no crea. El índice
   autoritativo es `toolkit/TOOLS_INDEX.json`. O bien adaptas las rutas de `catalog_toolkit.mjs` a la
   estructura real (cambio mínimo, sin romper nada), o documentas la discrepancia en
   `AGENTS_INTEGRATION.md`. No dejes dos índices contradictorios sin explicar.

## 4. Compilar/instalar cada herramienta

El script ya intenta: `go build` (Porygion), `cargo build --release` (rvpacker),
`make clean && make` (pokecrystal, pokered), `cmake`/`qmake` + `make` (PoryMap),
`chmod +x` sobre la AppImage de Tiled y `npm install` de pokemon-agent.

Tras ejecutarlo, verifica cada resultado y recompila a mano lo que falte dentro de su carpeta en
`toolkit/`. Además prepara el proyecto Node de la raíz (`npm install`; hay devDeps como `jsdom`,
`@ruby/wasm-wasi` y `@napi-rs/canvas`) para que funcionen `npm test` y las herramientas de `tools/`.

## 5. Verificación (definición de «hecho»)

- [ ] `toolkit/TOOLS_INDEX.json` existe y cada herramienta tiene `path` y `status` coherentes
      (`compiled`/`appimage` es el ideal; `source_only` solo con causa documentada; `failed`/`not_found`
      solo si explicas por qué).
- [ ] `toolkit/logs/setup.log` sin errores inesperados y sin «No extractor available».
- [ ] El script es idempotente: la última pasada responde «Already staged»/«Already extracted» y no
      rehace trabajo.
- [ ] `git status` no muestra borrados de `.zip`/`.rar` trackeados (restaurados) ni temporales nuevos.
- [ ] Existe `AGENTS.md` en la RAÍZ del repo con la política de uso automático (sección 6).
- [ ] `AGENTS_INTEGRATION.md` refleja el estado real (rutas y binarios verificados, no supuestos).
- [ ] Informe final en el chat (no en el repo) con la tabla herramienta → comando → estado.

## 6. Integración permanente para los agentes (esto es lo que leerá Arena.ai)

Crea o actualiza `AGENTS.md` en la RAÍZ del repo (los agentes lo leen automáticamente) con estas
reglas, y mantén `REPO_ORDENADOR/AGENTS.md` y `REPO_ORDENADOR/PROMPT_ARENA_ES.md` coherentes con ellas:

- Antes de invocar cualquier herramienta, lee `toolkit/TOOLS_INDEX.json` (o `AGENTS_INTEGRATION.md`
  si el toolkit no está instalado) y usa los `path` reales que ahí figuran; nunca asumas nombres
  internos de los comprimidos.
- Edición de mapas → PoryMap (proyectos pret: pokeemerald / pokefirered / pokeruby, y las
  decompilaciones Gen 1/2 según la tarea) o Tiled (mapas TMX / tiles 2D).
- Generación procedural de mapas y regiones estilo Gen 3 → Porygion.
- Trabajo sobre código fuente de juegos Gen 1/2 → `toolkit/sources/pokered` y `toolkit/sources/pokecrystal`
  (`make` dentro del directorio que contiene el `Makefile`).
- Extracción y traducción de textos RPG Maker → rvpacker (`toolkit/sources/rvpacker/target/release/…`).
- Agentes de IA que juegan Pokémon → `toolkit/agents/pokemon-agent`; enjambres de agentes → timps-swarm.
- Assets y sprites auxiliares → `toolkit/assets/swablu/`.
- Prioriza SIEMPRE estas herramientas antes que soluciones genéricas cuando la tarea lo permita:
  velocidad, precisión y calidad por encima de improvisar. Si una herramienta nueva resulta útil,
  intégrala al flujo y documéntala sin esperar a que lo pidan.
- Si el toolkit no está instalado (repo recién clonado), primero ejecuta `./setup_toolkit.sh`
  (dos pasadas) antes de trabajar.

## 7. Entrega (git)

- Commitea y pushea solo: los arreglos de `setup_toolkit.sh` (incluido el bit ejecutable),
  `AGENTS.md`, `AGENTS_INTEGRATION.md` y, si aplica, el ajuste mínimo de `tools/catalog_toolkit.mjs`.
  Nada de `toolkit/`, `node_modules/`, binarios compilados ni eliminaciones de comprimidos.
- Informe final en el chat con: qué instalaste, estado de cada herramienta, cómo invocarla, causas
  de cualquier `failed`/`not_found`, verificaciones ejecutadas y confirmación explícita de que
  Arena.ai puede usar el toolkit automáticamente al tomar el repo.

=== FIN DEL PROMPT ===
````# Arena Repo Helper

Kit de instrucciones y herramientas para que un agente con acceso a un repositorio —por ejemplo, Arena Agent Mode— pueda entenderlo una vez, localizar sus recursos, revisar archivos comprimidos y trabajar con menos exploraciones repetidas.

**Esto no es un plugin que Arena detecte o instale automáticamente.** Coloca estos archivos en la raíz del repositorio de GitHub y, al abrir ese repo con Arena, usa el texto de `PROMPT_ARENA_ES.md` para indicarle que lea `AGENTS.md` y utilice la herramienta. Si Arena no tiene terminal en esa sesión, el prompt le pide que inspeccione los archivos disponibles y no finja haber ejecutado comandos.

El kit no incluye ningún archivo `.ignore` ni crea archivos de exclusión.

## Contenido

- `AGENTS.md`: reglas persistentes para el agente: inventariar una vez, reutilizar recursos, preservar cambios del usuario y evitar temporales y archivos `.ignore`.
- `PROMPT_ARENA_ES.md`: prompt listo para copiar y pegar en Arena Agent Mode.
- `tools/repo_helper.py`: utilidad de línea de comandos, sin dependencias de Python externas, para inventariar el proyecto, localizar archivos comprimidos y extraer ZIP/RAR/7z de forma explícita.
- `tests/test_repo_helper.py`: pruebas de detección y extracción segura de ZIP.

## Requisitos

- Python 3.10 o posterior para inventario y ZIP.
- Para abrir RAR o 7z, además se requiere `unrar`, `rar`, `7zz` o `7z` instalado en el sistema. El programa detecta el comando disponible; no incorpora un extractor propietario.
- ZIP simple se puede extraer con la biblioteca estándar de Python. ZIP multipartes requiere 7-Zip.

En Debian/Ubuntu, los nombres de paquetes varían según la versión. Algunos sistemas ofrecen `python3` y `p7zip-full`; otros, `7zip`/`7zz` o `unrar`.

## Uso desde una terminal

Desde la raíz del repositorio:

```bash
# Mapa breve del proyecto: estructura, archivos clave, extensiones y archivos comprimidos
python3 tools/repo_helper.py inventory .

# Buscar archivos comprimidos y agrupar volúmenes relacionados
python3 tools/repo_helper.py archives .

# Extraer todos los conjuntos de una carpeta en carpetas separadas
python3 tools/repo_helper.py extract ./descargas --dest /tmp/extraidos --recursive

# Extraer un conjunto RAR concreto: indica el primer volumen
python3 tools/repo_helper.py extract ./descargas/manual.part01.rar --dest /tmp/extraidos
```

Para guardar la extracción dentro del repositorio, elige deliberadamente un destino como `./recursos/extraidos`. La herramienta no sobrescribe un destino existente y conserva los archivos comprimidos originales. En caso de error, revisa la carpeta de salida parcial y el mensaje del extractor antes de volver a intentarlo.

La herramienta **no reorganiza ni mueve automáticamente el código del repositorio**: entrega un mapa y una extracción segura para que el agente aplique solo la organización solicitada, respetando referencias y convenciones del proyecto.

## Pruebas

```bash
python3 -m unittest discover -s tests -v
```

## En GitHub y Arena

1. Añade `AGENTS.md`, `README.md`, `PROMPT_ARENA_ES.md`, `tools/` y `tests/` a la raíz del repositorio.
2. Abre o conecta ese repositorio en Arena Agent Mode.
3. Copia el prompt de `PROMPT_ARENA_ES.md` y completa el objetivo concreto.

La disponibilidad de terminal y el acceso a un repo dependen de la sesión y de las herramientas habilitadas en Arena. Si Arena no puede ejecutar la utilidad, las instrucciones siguen sirviendo como lista de verificación, pero el agente deberá inspeccionar los archivos mediante las herramientas que tenga disponibles.CIUDAD TECKEL E ISLA PARAÍSO (rediseño de la Isla Espejo)
=========================================================

La Isla Espejo cambia de propósito y la Dimensión Atlas absorbe su contenido
anterior:

 · Los 20 Pokégods y las 15/16 versiones alternativas de personajes (Mirror
   Boss, ahora con sprites recoloreados ALT_*) viven repartidos por los mapas
   Tier 1 de la Dimensión Atlas.
 · Map 997 = Ciudad Teckel: perros Pokémon (Zigzagoon, Poochyena, Growlithe,
   Eevee…) deambulando libres, veterinaria que cura, gimnasio y muelle.
 · Map 998 = Gimnasio Teckel: la líder Duna entrega la Medalla Pata.
 · Map 999 = Afueras Teckel: prado con encuentros de perros.
 · Map 2300 = Isla Paraíso: el altar de MAXINE, la Legendaria Florateck
   (nivel 125).

Cómo se juega
-------------
1. Tras cerrar la Ruta de Dios (Arceus), habla con el PROFESOR ATLAS en Puerto
   Horizonte (Atlas Mil): te da el TICKET PARAÍSO.
2. En Ciudad Teckel, vence a DUNA en el gimnasio para la MEDALLA PATA.
3. Cruza en el muelle con el ticket hasta Isla Paraíso.
4. La GUARDIANA NIRA pregunta: «¿qué le gusta más a MAXINE, el pollo o la
   pata?» La respuesta correcta es LA PATA. Con ella, MAXINE despierta en su
   altar y puede combatirse (y capturarse) al nivel 125.

Instalación
-----------
Extrae este ZIP en la raíz del juego (junto a Game.exe) aceptando reemplazos.
Requiere haber instalado antes Fire_Ash_Paquete_Directo.zip y
Dimensional_Nightmare_QA.zip (los mapas Atlas existen desde esa capa).
No toca partidas guardadas.PAQUETE QA — POKÉMON FIRE ASH: ASHEN GUARDIAN
==================================================

Este parche independiente prepara el contenido Dimensional Nightmare / Protector de la Ceniza
para una prueba manual. Es una entrega interna de QA, no una distribución pública de recursos.
Los mosaicos derivados se incluyen únicamente para que el juego pueda cargarlos durante esta prueba.

COMPATIBILIDAD
--------------
- Diseñado para una copia limpia de Pokémon Fire Ash 3.7.1 con RPG Maker XP / Essentials v19.
- Instálalo en una copia separada del juego. El ZIP no incluye Game.exe, partidas ni Game.rxdata.
- Incluye los datos, gráficos originales y pistas MIDI propias del contenido DN, nombres de flags
  y una copia del Scripts.rxdata corregido con un módulo Runtime DN aislado (batalla espejo y
  secuencia final de EP06). El archivo compartido del paquete de La Ruta de Dios no se modifica.

INSTALACIÓN
-----------
1. Cierra Fire Ash y el emulador/launcher.
2. Duplica la carpeta del juego y conserva intacta la original.
3. Haz una copia adicional de tus partidas. No se deben reemplazar ni borrar Game.rxdata o Save*.
4. Extrae Dimensional_Nightmare_QA.zip directamente en la raíz de la copia, junto a Game.exe y
   Game.ini. Acepta reemplazar Data/Scripts.rxdata, Data/MapInfos.rxdata, Data/System.rxdata,
   Data/Tilesets.rxdata, los mapas listados, los gráficos y Audio/BGM/DN_*.mid.
5. No dejes Data/ ni Graphics/ dentro de una carpeta intermedia llamada
   Dimensional_Nightmare_QA/; deben quedar directamente bajo la raíz del juego.
6. Inicia una partida postgame en la copia. La entrada está en la Gruta de los Testigos (Map2030),
   junto a la llegada de la Antesala. El primer anillo requiere v264 ≥ 3; el contenido tardío conserva
   las condiciones narrativas indicadas por el juego (incluidos los 7 sellos de Monte Silver).

RECORRIDO DE QA SUGERIDO
------------------------
- Prueba el acceso a la Antesala y confirma que las puertas cerradas explican qué falta.
- Visita EP01–EP06, el Nexo, la Liga Oscura y W7–W9; usa las salidas y retornos de cada zona.
- Habla varias veces con NPC normales, conscientes e interdimensionales. Sus páginas recuerdan
  visitas, se mueven según su papel y reaccionan al cambio de fase.
- Inspecciona el hito de Rotom de cada mapa. Registra anomalías, objetos, pedestales y estatuas.
- Prueba las diez decisiones opcionales y consulta la Vitrina del Testigo en la Antesala.
- Pierde y reintenta los combates; comprueba fase B, curación, recompensas únicas y regreso seguro.
- Comprueba el subtítulo Ashen Guardian, las BGM MIDI originales, el silencio de EP05 (2104–2109) y el fade/restauración del silenciador de EP04.
- Comprueba que los tonos/fases vuelvan a neutro al salir y que v264 no cambie al recorrer el Nightmare; DN sólo lo consulta como contador externo.

LIMITACIONES CONOCIDAS
----------------------
- Esta entrega pasó verificación estática y de empaquetado; no se ha ejecutado en Game.exe/Kirin.
- La QA manual sigue pendiente. Si detectas un error, anota mapa, coordenadas, flags y pasos para
  reproducirlo antes de restaurar la copia limpia.
- No redistribuyas el paquete ni los gráficos de referencia fuera de esta prueba.

