  def pbStartBattleSendOut(*args); end
  def pbRun(*args); 0; end
  def pbSwitchInBetween(*args); end
  def pbCalculatePriority(*args); []; end
  # R12: ventanas de elección, música y party dentro del combate.
  attr_accessor :comando_script, :comando_log, :bgm_log
  def pbShowCommands(msg, commands, canCancel = true)
    # Réplica fiel del contrato de la escena (Scene_Battle:203): el 3er
    # argumento se usa como `defaultValue>=0`, así que DEBE ser entero. Un
    # booleano aquí lanza NoMethodError en el juego real; lo reproducimos para
    # que ninguna firma mal puesta vuelva a pasar la QA.
    raise NoMethodError, "undefined method `>=' for #{canCancel.inspect}" if !canCancel.is_a?(Integer)
    @comando_log ||= []
    @comando_log << (commands || []).dup
    c = @comando_script
    c = c.call(commands) if c.respond_to?(:call)
    c.nil? ? 0 : c.to_i
  end
  def pbBGMPlay(param, volume = nil, pitch = nil)
    @bgm_log ||= []
    @bgm_log << param
    nil
  end
  def pbParty(idxBattler = 0)
    # En el motor pbParty devuelve objetos Pokemon (no battlers): la merced de
    # Arceus usa .species/.fainted?/.heal de Pokemon. R15c: ruta_side_split
    # permite bando rival de varios Pokémon (la Orden Divina alinea cuatro).
    split = @ruta_side_split.to_i
    split = 1 if split < 1
    split = @battlers.length - 1 if split > @battlers.length - 1
    lado = idxBattler.to_i == pbPlayer ? @battlers[0...(@battlers.length - split)] : @battlers[(@battlers.length - split)..-1].to_a
    lado.compact.map { |b| b.pokemon }.compact
  end
  # R15c — réplica fiel de PokeBattle_Battle#pbPartyStarts / pbAbleTeamCounts
  # (sección 182:354 del motor): el redimensionado salvaje de Battle_StartAndEnd
  # lee estos conteos y con 4 divinos volvía el campo 4v4.
  def pbPartyStarts(side)
    side.to_i == pbPlayer ? (@party1starts || [0]) : (@party2starts || [0])
  end
  def pbAbleTeamCounts(side)
    party = pbParty(side)
    partyStarts = pbPartyStarts(side)
    ret = []
    idxTeam = -1
    nextStart = 0
    party.each_with_index do |pkmn, i|
      if i >= nextStart
        idxTeam += 1
        nextStart = (idxTeam < partyStarts.length - 1) ? partyStarts[idxTeam + 1] : party.length
      end
      next if !pkmn || !pkmn.able?
      ret[idxTeam] = 0 if !ret[idxTeam]
      ret[idxTeam] += 1
    end
    ret
  end
  # El override del guion (R15c) llama a _ruta_arceus_original_able_team_counts;
  # en el sandbox la línea `alias` del generador no se extrae (sólo viajan los
  # def), así que el preludio deja el alias listo.
  alias _ruta_arceus_original_able_team_counts pbAbleTeamCounts unless method_defined?(:_ruta_arceus_original_able_team_counts)
  # Réplica fiel de PokeBattle_Battle#pbStartWeather (730380:679): escribe el
  # clima y LO LEE con GameData::BattleWeather.try_get en la misma llamada.
  def pbStartWeather(user, newWeather, fixedDuration = false, showAnim = true, customDuration = 5)
    return if @field.weather == newWeather
    @field.weather = newWeather
    duration = (fixedDuration) ? customDuration : -1
    @field.weatherDuration = duration
    weather_data = GameData::BattleWeather.try_get(@field.weather)
    pbCommonAnimation(weather_data.animation) if showAnim && weather_data
  end
  def defaultWeather=(value)
    @field.defaultWeather = value
    @field.weather = value
    @field.weatherDuration = -1
  end
  # ── "Originales" del motor que los alias instalados envuelven ──
  def _ruta_arceus_original_pb_player; 0; end
  def _ruta_arceus_original_pb_random(n); 0; end
  def _ruta_arceus_original_calculate_priority(*args); []; end
  def _ruta_arceus_original_command_loop(*args); end
  def _ruta_arceus_original_start_send_out(*args); end
  def _ruta_arceus_original_pbRun(*args); 0; end
  def _ruta_arceus_original_pbSwitchInBetween(*args); true; end
end

module PokeBattle_BattleCommon
  def pbCaptureCalc(*args); 0; end
end

# La fase de fin de ronda del motor (505186:60) lee el campo con try_get: es la
# línea exacta que reventaba en Kirin cuando el campo quedaba sucio.
class Battle_Phase_EndOfRound
  def initialize(battle = nil); @battle = battle; end
  def start_phase
    weather_data = GameData::BattleWeather.try_get(@battle.field.weather)
    @battle.pbCommonAnimation(weather_data.animation) if weather_data
    terrain_data = GameData::Terrain.try_get(@battle.field.terrain)
    @battle.pbCommonAnimation(terrain_data.animation) if terrain_data
  end
end

$game_switches = {}
$game_screen = nil
$PokemonBag = nil
$PokemonTemp = nil# ============================================================================
# arceus_fuzz_scenarios.rb
#
# Un millón de escenarios deterministas (semilla fija) sobre el código REAL
# instalado de PokeMod_RutaDeDios + PokeMod_CanonArceus, ejecutados por
# tools/qa/arceus_fuzz_harness.mjs dentro de CRuby 3.3 (WebAssembly). Cada
# familia vive en su propio método: el arnés lanza un VM por familia porque el
# heap de WASM no tolera las cuatro tandas acumuladas en un solo eval.
#
#   F1 · 590 240 · micro-fuzz de la guardia anti-KO (tope variable hasta 48%).
#   F5 · ~200 000 · sistemas R12: mazos sin repetición, daño variable, música,
#                   invocaciones funcionales, minijuegos, merced de equipo y
#                   copia segura de movimientos.
#   F2 · 150 000 · clima/terreno sucios + pbStartWeather con basura + fin de
#                  ronda parcheado + batalla_clima del canon.
#   F3 ·   6 000 · duelos completos aleatorios: seis barras, umbral rojo,
#                  Mega Arceus de los Mil Brazos, bajas y captura.
#   F4 ·  44 000 · barrido de las seis fases del canon sobre campos sucios.
# ============================================================================

CAP = RUTA_ARCEUS_HIT_CAP_RATIO
MIL_BRAZOS = [:FURYSWIPES, :COMETPUNCH, :PINMISSILE, :ARMTHRUST]
BASURA = [5, 0, -3, 3.5, true, :RAINDANCE, :SUNNYDAY, :FOGMOVE, "Sun", "7",
          :Sun, :Rain, :Sandstorm, :Hail, :Fog, :None, :HarshSun, :ShadowSky].freeze

class FuzzMon < PokeBattle_Battler
  # En el motor los PS del battler y del Pokémon van sincronizados: la merced
  # de Arceus (pkmn.heal) y el recuento de "queda 1 en pie" lo exigen.
  def hp=(value)
    @hp = value
    @pokemon.hp = value if @pokemon
  end

  def initialize(index, side, species, totalhp)
    super(index, side)
    @pokemon = Pokemon.new(species, 100)
    @totalhp = totalhp
    @hp = totalhp
    @pokemon.hp = totalhp
    @pokemon.totalhp = totalhp
  end
end

def fuzz_divine_battle(party_n, boss_hp = 1000)
  boss = FuzzMon.new(1, 1, :ARCEUS, boss_hp)
  boss.pokemon.instance_variable_set(:@ruta_arceus_divine, true)
  boss.pokemon.instance_variable_set(:@ruta_arceus_phase, 1)
  boss.pokemon.instance_variable_set(:@ruta_arceus_restores, 0)
  boss.pokemon.instance_variable_set(:@ruta_arceus_capture_ready, false)
  boss.pokemon.instance_variable_set(:@ruta_arceus_bars_depleted, 0)
  boss.pokemon.instance_variable_set(:@ruta_arceus_redline_healed_phase, 0)
  especies_party = [:METAGROSS, :CHARIZARD, :PIKACHU, :MEW, :DIALGA, :PALKIA]
  golpes_party = [:METEORMASH, :EXTREMESPEED, :PSYCHIC, :AURASPHERE, :SHADOWFORCE, :VCREATE]
  party = (0...party_n).map do |i|
    mon = FuzzMon.new(0, 0, especies_party[i % especies_party.length], 400 + (i * 37) % 200)
    mon.pokemon.moves = [Pokemon::Move.new(golpes_party[i % golpes_party.length])]
    mon
  end
  boss.item = :LEGENDPLATE # el jefe divino real porta la Tabla Leyenda
  battle = PokeBattle_Battle.new(party + [boss])
  battle.instance_variable_set(:@arceus_divine, true)
  battle.turnCount = 1
  [battle, party, boss]
end

def fuzz_invocation_battle(player_hp = 400)
  player_a = FuzzMon.new(0, 0, :METAGROSS, 400)
  player_b = FuzzMon.new(2, 0, :PIKACHU, 420)
  boss = FuzzMon.new(1, 1, :ARCEUS, 1000)
  slot = FuzzMon.new(3, 1, :GIRATINA, 600)
  player_a.hp = player_hp
  player_a.pokemon.moves = [Pokemon::Move.new(:METEORMASH)]
  player_b.pokemon.moves = [Pokemon::Move.new(:EXTREMESPEED)]
  slot.pokemon.moves = [Pokemon::Move.new(:SHADOWCLAW)]
  slot.instance_variable_set(:@pokemonIndex, 1)
  boss.pokemon.instance_variable_set(:@ruta_arceus_divine, true)
  boss.pokemon.instance_variable_set(:@ruta_arceus_phase, 2)
  boss.pokemon.instance_variable_set(:@ruta_arceus_capture_ready, false)
  boss.pokemon.instance_variable_set(:@ruta_arceus_bars_depleted, 0)
  boss.item = :LEGENDPLATE
  battle = PokeBattle_Battle.new([player_a, player_b, boss, slot])
  battle.ruta_side_split = 2
  battle.sideSizes = [2, 2]
  battle.instance_variable_set(:@arceus_divine, true)
  battle.instance_variable_set(:@arceus_phase, 2)
  battle.turnCount = 10
  [battle, [player_a, player_b], boss, slot]
end

# ── F1 · micro-fuzz de la guardia anti-KO ───────────────────────────────────
def fuzz_f1(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  battle1, party1, boss1 = fuzz_divine_battle(2, 1000)
  objetivo = party1[0]
  f1 = 0
  590_240.times do
    total = 1 + rng.rand(3000)
    hp0 = 1 + rng.rand(total)
    lost = 1 + rng.rand(total + 100)
    objetivo.totalhp = total
    objetivo.hp = hp0
    ds = objetivo.damageState
    ds.hpLost = lost
    ds.totalHPLost = lost
    ds.substitute = false
    ds.endured = false
    battle1.turnCount = 1 + (f1 % 37)
    begin
      battle1.ruta_arceus_apply_ohko_guard(boss1, objetivo)
    rescue StandardError => e
      notar.call("F1 excepción #{e.class}: #{e.message.to_s[0, 60]}")
      f1 += 1
      next
    end
    cap = (total * CAP).round
    cap = 1 if cap < 1
    notar.call("F1 tope violado: hp0=#{hp0} cap=#{cap} aplicado=#{ds.hpLost}") if hp0 > cap && ds.hpLost > cap
    notar.call("F1 daño negativo") if ds.hpLost < 0
    notar.call("F1 endured sin golpe letal") if ds.endured && lost < hp0
    f1 += 1
    GC.start if (f1 % 200_000).zero?
  end
  f1
end

# ── F2 · clima y terreno sucios, fin de ronda parcheado ─────────────────────
def fuzz_f2(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  battle2, = fuzz_divine_battle(1, 800)
  f2 = 0
  150_000.times do
    valor = BASURA[rng.rand(BASURA.length)]
    begin
      case rng.rand(5)
      when 0 then battle2.pbStartWeather(nil, valor)
      when 1 then battle2.defaultWeather = valor
      when 2 then battle2.field.weather = valor
      when 3 then battle2.field.terrain = valor
      when 4 then CanonArceus.batalla_clima(battle2, rng.rand(12))
      end
    rescue StandardError => e
      notar.call("F2 excepción escapada #{e.class}: #{e.message.to_s[0, 70]}")
    end
    begin
      RutaCampoSeguro.sanitizar!(battle2)
      Battle_Phase_EndOfRound.new(battle2).start_phase
      clima_ok = !GameData::BattleWeather.try_get(battle2.field.weather).nil?
      terreno_ok = !GameData::Terrain.try_get(battle2.field.terrain).nil?
      notar.call("F2 campo inválido tras el fin de ronda: #{battle2.field.weather.inspect}/#{battle2.field.terrain.inspect}") if !clima_ok || !terreno_ok
    rescue StandardError => e
      notar.call("F2 fin de ronda #{e.class}: #{e.message.to_s[0, 70]}")
    end
    f2 += 1
    GC.start if (f2 % 50_000).zero?
  end
  f2
end

# ── F3 · duelos completos aleatorios ────────────────────────────────────────
def fuzz_f3(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  f3 = 0
  victorias = 0
  primigenias = 0
  duelos_exigentes = 0
  victorias_exigentes = 0
  derrotas_exigentes = 0
  3_000.times do
    party_n = 1 + rng.rand(6)
    prop = [0.05, 0.09, 0.12, 0.2, 0.35][rng.rand(5)]
    golpe = [0.2, 0.33, 0.5, 0.9, 1.6][rng.rand(5)]
    falla = [nil, 3, 2][rng.rand(3)]
    battle, party, boss = fuzz_divine_battle(party_n, 1000)
    battle.define_singleton_method(:pbRandom) { |x| x.to_i > 0 ? rng.rand(x) : 0 }
    battle.comando_script = lambda { |cmds| cmds && !cmds.empty? ? rng.rand(cmds.length) : 0 }
    move = PokeBattle_Move.new(battle, :METEORMASH)
    idx = 0
    bajas = 0
    turno = 0
    gano = false
    perdio = false
    mega = false
    mega_pool = false
    copia = false
    prim = false
    erro = nil
    begin
      60.times do |i|
        turno = i + 1
        battle.turnCount = turno
        battle.lastMoveUser = 0
        battle.lastMoveUsed = :METEORMASH
        # R12: el turno divino (música por fase, apertura con sprites, merced
        # del último Pokémon, juegos e invocaciones) cuelga del cálculo de
        # prioridad, que en el motor corre cada ronda.
        battle.pbCalculatePriority
        if !falla || (turno % falla != 0)
          boss.damageState.hpLost = (boss.totalhp * prop).round
          boss.damageState.totalHPLost = boss.damageState.hpLost
          move.pbInflictHPDamage(boss)
        end
        if battle.instance_variable_get(:@arceus_capture_ready)
          gano = true
          break
        end
        if battle.instance_variable_get(:@ruta_arceus_mega_visto) && !mega_pool
          # El motor arma el pool de la fase en pbArceusPhase (línea 2561 del
          # guion): pbArceusSetMoves(battler, RUTA_ARCEUS_MOVE_SETS[indice]).
          # El sandbox no carga pbArceusPhase (escena y Species reales), así
          # que se replica aquí esa única llamada con los datos instalados.
          mega_pool = true
          battle.pbArceusSetMoves(boss, RUTA_ARCEUS_MOVE_SETS[5])
        end
        if battle.instance_variable_get(:@arceus_phase).to_i >= 4 && !copia
          copia = true
          battle.ruta_arceus_copiar_equipo(boss)
          ids_copia = (boss.pokemon.moves || []).map { |m| m.id }
          permitidos = (party.flat_map { |pm| (pm.pokemon.moves || []).map { |m| m.id } } + [:JUDGMENT]).uniq
          notar.call("F3 copia de equipo con golpes ajenos: #{ids_copia.inspect}") if (ids_copia - permitidos).length > 0
          notar.call("F3 copia de equipo vacía") if ids_copia.empty?
        end
        mega = true if battle.instance_variable_get(:@ruta_arceus_mega_visto)
        prim = true if battle.instance_variable_get(:@ruta_arceus_primigenia_visto)
        cur = party[idx]
        break if !cur
        if !cur.fainted?
          perdido = (cur.totalhp * golpe).round
          cur.damageState.hpLost = perdido
          cur.damageState.totalHPLost = perdido
          cur.damageState.substitute = false
          cur.damageState.endured = false
          hp_antes = cur.hp
          cap = (cur.totalhp * CAP).round
          cap = 1 if cap < 1
          battle.ruta_arceus_apply_ohko_guard(boss, cur)
          aplicado = cur.damageState.hpLost
          notar.call("F3 tope violado en duelo: aplicado=#{aplicado} cap=#{cap}") if hp_antes > cap && aplicado > cap
          cur.hp = hp_antes - aplicado
          if cur.fainted?
            bajas += 1
            idx += 1
          end
        end
        battle.pbArceusRedlineHeal(boss)
        # La Primigenia despierta dentro del umbral rojo de fin de turno: se
        # lee aquí, porque el turno siguiente puede cerrar con la captura.
        prim = true if battle.instance_variable_get(:@ruta_arceus_primigenia_visto)
        if idx >= party.length
          perdio = true
          break
        end
      end
    rescue StandardError => e
      erro = e
      notar.call("F3 excepción #{e.class}: #{e.message.to_s[0, 90]}")
    end
    if !erro
      exigente = (party_n == 6 && prop >= 0.09 && falla != 2)
      if exigente
        duelos_exigentes += 1
        if gano
          victorias_exigentes += 1
        elsif perdio
          # Perder con un equipo aleatorio es un resultado permitido y buscado:
          # la dificultad no debe convertir al jefe en una victoria automática.
          derrotas_exigentes += 1
        else
          notar.call("F3 duelo exigente excedió 60 turnos sin resultado")
        end
      end
      primigenias += 1 if prim
      if gano
        victorias += 1
        notar.call("F3 victoria sin música divina") if battle.bgm_log.to_a.empty?
        notar.call("F3 victoria sin megaevolución visible") if !mega
        ids = (boss.pokemon.moves || []).map { |m| m.id }
        if prim
          notar.call("F3 Forma Primigenia sin la Tabla soltada") if !boss.item.nil?
          notar.call("F3 Forma Primigenia sin pool primigenio: #{ids.inspect}") if (ids & RUTA_ARCEUS_PRIMIGENIA_MOVES).empty?
        else
          notar.call("F3 última barra sin pool de mil brazos: #{ids.inspect}") if (ids & MIL_BRAZOS).empty?
        end
      end
    end
    f3 += 1
    GC.start if (f3 % 300).zero?
  end
  notar.call("F3 no generó duelos exigentes") if duelos_exigentes.zero?
  notar.call("F3 no hubo victorias entre equipos exigentes") if victorias_exigentes.zero?
  notar.call("F3 no hubo derrotas posibles entre equipos exigentes") if derrotas_exigentes.zero?
  [f3, victorias, primigenias, derrotas_exigentes]
end

# ── F4 · barrido de fases del canon sobre campos sucios ─────────────────────
def fuzz_f4(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  battle4, party4, boss4 = fuzz_divine_battle(2, 800)
  f4 = 0
  44_000.times do
    fase = 1 + rng.rand(6)
    battle4.field.weather = [5, :None, :Rain, nil, 0, :Fog][rng.rand(6)]
    battle4.field.terrain = [3, :None, :Misty, nil][rng.rand(4)]
    battle4.turnCount = 1 + rng.rand(40)
    begin
      CanonArceus.efecto_fase(battle4, boss4, fase)
      RutaCampoSeguro.sanitizar!(battle4)
      notar.call("F4 clima inválido tras la fase #{fase}: #{battle4.field.weather.inspect}") if GameData::BattleWeather.try_get(battle4.field.weather).nil?
      notar.call("F4 terreno inválido tras la fase #{fase}") if GameData::Terrain.try_get(battle4.field.terrain).nil?
      notar.call("F4 PS negativos del jefe") if boss4.hp < 0
      # R11: cada fase debe dejar SUS efectos visibles; un sub-efecto abortado
      # en silencio (rescue que se traga la mitad de la fase) ahora es un fallo.
      fx = battle4.field.effects
      case fase
      when 1
        notar.call("F4 fase 1 sin sello de mochila o Sala Mágica") if $game_switches[CanonArceus::SW_SELLO] != true || fx[:MagicRoom].to_i <= 0
      when 2
        notar.call("F4 fase 2 sin clima sembrado o sin Gravedad") if battle4.field.weather == :None || fx[:Gravity].to_i <= 0
      when 3
        notar.call("F4 fase 3 sin silencio de talentos") if party4[0].effects[:GastroAcid] != true || fx[:MagicRoom].to_i <= 0
        notar.call("F4 fase 3 sin velo de la suerte") if battle4.sides[1].effects[:LuckyChant].to_i <= 0
      when 4
        notar.call("F4 fase 4 sin salas invertidas") if fx[:TrickRoom].to_i <= 0 || fx[:WonderRoom].to_i <= 0
      when 5
        notar.call("F4 fase 5 sin tablilla puesta") if boss4.item.nil?
      when 6
        notar.call("F4 fase 6 sin cartel de los Mil Brazos") if !battle4.messages.any? { |m| m.to_s.include?("MIL BRAZOS") }
      end
    rescue StandardError => e
      notar.call("F4 excepción #{e.class}: #{e.message.to_s[0, 70]}")
    end
    f4 += 1
    GC.start if (f4 % 20_000).zero?
  end
  f4
end

# ── F5 · sistemas R12: mazos, ratio variable, música, invocaciones, juegos ──
def fuzz_f5(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  f5 = 0

  # (a) Mazos de diálogo: ninguna línea se repite hasta agotar el mazo y el
  #     ciclo completo cubre todo el pool de la categoría.
  battle_a, _pa, _ba = fuzz_divine_battle(2, 1000)
  battle_a.define_singleton_method(:pbRandom) { |x| x.to_i > 0 ? rng.rand(x) : 0 }
  1_200.times do
    RUTA_ARCEUS_DIALOGOS.each_key do |cat|
      pool = RUTA_ARCEUS_DIALOGOS[cat]
      vistos = {}
      pool.length.times do
        linea = battle_a.ruta_arceus_dialogo(cat)
        f5 += 1
        notar.call("F5 mazo #{cat} sacó nil") if linea.nil?
        notar.call("F5 mazo #{cat} repitió antes de agotarse") if vistos[linea]
        vistos[linea] = true
      end
      notar.call("F5 mazo #{cat} no cubrió todo su pool") if vistos.length != pool.length
    end
    GC.start if (f5 % 40_000) < 60
  end

  # (b) Ratio divino variable: nunca fijo ni mayor al 48%, con piso más alto
  #     en fases tardías y en la Forma Mega.
  battle_b, _pb, _bb = fuzz_divine_battle(2, 1000)
  distintos = {}
  75_000.times do |i|
    fase = 1 + rng.rand(6)
    mega = (fase == 6 && rng.rand(2) == 1)
    prim = (mega && rng.rand(4) == 0)
    battle_b.turnCount = 1 + rng.rand(40)
    battle_b.lastMoveUser = rng.rand(2)
    battle_b.lastMoveUsed = [:METEORMASH, :JUDGMENT, :PSYCHIC][rng.rand(3)]
    battle_b.instance_variable_set(:@arceus_phase, fase)
    battle_b.instance_variable_set(:@ruta_arceus_mega_visto, mega)
    battle_b.instance_variable_set(:@ruta_arceus_primigenia_visto, prim)
    r = battle_b.ruta_arceus_divine_ratio
    f5 += 1
    notar.call("F5 ratio sobre el tope del 48%: #{r}") if r > RUTA_ARCEUS_HIT_CAP_RATIO + 0.0001
    piso = fase >= 4 ? RUTA_ARCEUS_HIT_CAP_MIN_TARDIO : RUTA_ARCEUS_HIT_CAP_MIN
    piso += RUTA_ARCEUS_HIT_CAP_MEGA_EXTRA if mega
    notar.call("F5 ratio bajo su piso: #{r} < #{piso} (fase #{fase}, mega=#{mega})") if r < piso - 0.0001
    distintos[r.round(3)] = true
    GC.start if (i % 20_000).zero? && i > 0
  end
  notar.call("F5 el daño divino sería fijo: sólo #{distintos.length} ratios distintos") if distintos.length < 20

  # (c) Música por fase: pista correcta, idempotente y distinta entre fases.
  battle_c, _pc, _bc = fuzz_divine_battle(2, 1000)
  10_000.times do
    fase = 1 + rng.rand(6)
    prim = rng.rand(6) == 0
    battle_c.instance_variable_set(:@arceus_phase, fase)
    battle_c.instance_variable_set(:@ruta_arceus_primigenia_visto, prim)
    battle_c.instance_variable_set(:@ruta_arceus_bgm_actual, nil)
    battle_c.bgm_log = []
    battle_c.ruta_arceus_musica_fase(fase)
    battle_c.ruta_arceus_musica_fase(fase)
    f5 += 1
    notar.call("F5 fase #{fase} no estrenó música exactamente una vez") if battle_c.bgm_log.to_a.length != 1
    esperada = prim ? RUTA_ARCEUS_BGM_PRIMIGENIA : RUTA_ARCEUS_BGM_POR_FASE[fase]
    notar.call("F5 pista equivocada en fase #{fase}: #{battle_c.bgm_log.first}") if battle_c.bgm_log.first != esperada
  end
  todas = RUTA_ARCEUS_BGM_POR_FASE.values + [RUTA_ARCEUS_BGM_PRIMIGENIA]
  notar.call("F5 hay fases que comparten música") if todas.uniq.length != todas.length

  # (d) Invocaciones reales: ocupan el hueco aliado, registran un movimiento
  #     dañino en la cola normal y protegen al jefe hasta retirarse.
  filas = RUTA_ARCEUS_INVOCACIONES
  40.times do
    filas.each do |fila|
      [2, 150, 1000].each do |hp_inicial|
        battle_d, party_d, boss_d, slot_d = fuzz_invocation_battle(hp_inicial)
        original_pokemon = slot_d.pokemon
        original_index = slot_d.pokemonIndex
        boss_hp = boss_d.hp
        result = battle_d.pbArceusOrdenDivina(boss_d, fila[0], fila[1], fila[3])
        f5 += 1
        notar.call("F5 invocación #{fila[0]} no se materializó") if !result
        state = battle_d.instance_variable_get(:@ruta_arceus_invocation_state)
        if state
          notar.call("F5 invocación #{fila[0]} no ocupó el hueco 3") if state[:slot_index].to_i != 3
          notar.call("F5 invocación #{fila[0]} no sustituyó el sprite/battler") if slot_d.pokemon.species != fila[0]
          notar.call("F5 invocación #{fila[0]} no marcó pokemonIndex=-1") if slot_d.pokemonIndex != -1
          notar.call("F5 Arceus no quedó protegido durante la invocación #{fila[0]}") if !boss_d.instance_variable_get(:@ruta_arceus_retired_for_summon)
          boss_d.damageState.hpLost = 100
          PokeBattle_Move.new(battle_d, :METEORMASH).pbInflictHPDamage(boss_d)
          notar.call("F5 invocación #{fila[0]} permitió daño a Arceus") if boss_d.hp != boss_hp
          ok = battle_d.pbArceusInvocationAction(slot_d.index, slot_d)
          notar.call("F5 invocación #{fila[0]} no registró una acción real") if !ok
          choice = battle_d.choices[slot_d.index]
          move = slot_d.moves[choice[1].to_i] if choice && choice[0] == :UseMove
          notar.call("F5 invocación #{fila[0]} registró un ataque vacío") if !move || !move.damagingMove?
          if move
            objetivo = party_d[0]
            objetivo.hp = hp_inicial
            move_damage = [hp_inicial - 1, 1].max
            objetivo.damageState.hpLost = move_damage
            objetivo.damageState.totalHPLost = move_damage
            before = objetivo.hp
            move.pbInflictHPDamage(objetivo)
            if hp_inicial > 1
              notar.call("F5 invocación #{fila[0]} no ejecutó daño por la ruta real del motor") if objetivo.hp >= before
            end
          end
          dismissed = battle_d.pbArceusDismissInvocation(boss_d)
          notar.call("F5 invocación #{fila[0]} no se retiró") if !dismissed || battle_d.instance_variable_get(:@ruta_arceus_invocation_state)
          notar.call("F5 invocación #{fila[0]} no devolvió el aliado original") if !slot_d.pokemon.equal?(original_pokemon)
          notar.call("F5 invocación #{fila[0]} no restauró pokemonIndex") if slot_d.pokemonIndex != original_index
          notar.call("F5 invocación #{fila[0]} dejó a Arceus retirado") if boss_d.instance_variable_get(:@ruta_arceus_retired_for_summon)
        end
        notar.call("F5 invocación #{fila[0]} dejó clima inválido") if GameData::BattleWeather.try_get(battle_d.field.weather).nil?
        party_d.each do |ally|
          ally.stages.each_value do |value|
            notar.call("F5 invocación #{fila[0]} dejó un stat bajo -6") if value.to_i < -6
          end
        end
      end
    end
    GC.start
  end

  # (e) Bono del Juicio Ciego: parte el tope en dos y se consume por acción.
  battle_e, party_e, boss_e = fuzz_divine_battle(2, 1000)
  30_000.times do |i|
    objetivo = party_e[0]
    total = 100 + rng.rand(900)
    objetivo.totalhp = total
    objetivo.hp = total
    objetivo.damageState.substitute = false
    battle_e.turnCount = i + 1
    battle_e.lastMoveUser = 1
    battle_e.lastMoveUsed = :JUDGMENT
    perdido = (total * 0.9).round
    objetivo.damageState.hpLost = perdido
    objetivo.damageState.totalHPLost = perdido
    battle_e.instance_variable_set(:@arceus_phase, 1 + rng.rand(6))
    con_bono = (i % 2 == 0)
    battle_e.instance_variable_set(:@ruta_juego_bono_acciones, con_bono ? 2 : 0)
    battle_e.instance_variable_set(:@ruta_juego_bono_key, nil)
    battle_e.ruta_arceus_apply_ohko_guard(boss_e, objetivo)
    f5 += 1
    techo = (total * RUTA_ARCEUS_HIT_CAP_RATIO).round
    techo = [(techo / 2.0).round, 1].max if con_bono
    notar.call("F5 bono roto: #{objetivo.damageState.hpLost} > #{techo}") if objetivo.damageState.hpLost > techo + 1
    if con_bono && battle_e.instance_variable_get(:@ruta_juego_bono_acciones) != 1
      notar.call("F5 el bono del juego no se consumió por acción")
    end
    GC.start if (i % 10_000).zero? && i > 0
  end

  # (f) Merced del último Pokémon: se ofrece una sola vez por batalla, cura
  #     vida + estado + PP de TODO el equipo si se acepta, y no cura si no.
  10_000.times do |i|
    battle_f, party_f, boss_f = fuzz_divine_battle(6, 1000)
    acepto = (i % 2 == 0)
    battle_f.comando_script = lambda { |_cmds| acepto ? 0 : 1 }
    battle_f.turnCount = 5
    party_f.each { |pm| (pm.pokemon.moves || []).each { |m| m.pp = 3 } }
    party_f[0, 5].each { |pm| pm.hp = 0 }
    party_f[5].hp = (party_f[5].totalhp / 2)
    battle_f.ruta_arceus_ofrenda(boss_f)
    f5 += 1
    notar.call("F5 la merced no se ofreció") if battle_f.comando_log.to_a.empty?
    notar.call("F5 la merced no quedó marcada") if battle_f.instance_variable_get(:@ruta_ofrenda_hecha) != true
    if acepto
      vivos = party_f.select { |pm| pm.pokemon.hp.to_i > 0 }
      notar.call("F5 merced aceptada dejó a alguien caído") if vivos.length != 6
      party_f.each do |pm|
        notar.call("F5 merced aceptada no curó del todo") if pm.pokemon.hp.to_i != pm.pokemon.totalhp.to_i
        (pm.pokemon.moves || []).each do |m|
          notar.call("F5 merced aceptada no restauró PP") if m.pp.to_i != m.total_pp.to_i
        end
      end
    else
      notar.call("F5 merced rechazada curó igual") if party_f[0].pokemon.hp.to_i != 0
    end
    antes = battle_f.comando_log.to_a.length
    battle_f.ruta_arceus_ofrenda(boss_f)
    notar.call("F5 la merced se ofreció dos veces") if battle_f.comando_log.to_a.length != antes
    GC.start if (i % 2_000).zero? && i > 0
  end

  # (g) Copia del equipo: sólo golpes que Ash enseñó (+Juicio), máximo 4,
  #     una sola vez por batalla.
  7_600.times do
    battle_g, party_g, boss_g = fuzz_divine_battle(1 + rng.rand(6), 1000)
    battle_g.instance_variable_set(:@arceus_phase, 4)
    battle_g.define_singleton_method(:pbRandom) { |x| x.to_i > 0 ? rng.rand(x) : 0 }
    battle_g.ruta_arceus_copiar_equipo(boss_g)
    ids = (boss_g.pokemon.moves || []).map { |m| m.id }
    f5 += 1
    permitidos = (party_g.flat_map { |pm| (pm.pokemon.moves || []).map { |m| m.id } } + [:JUDGMENT]).uniq
    notar.call("F5 copia con golpes ajenos: #{ids.inspect}") if (ids - permitidos).length > 0
    notar.call("F5 copia con más de cuatro golpes") if ids.length > 4
    notar.call("F5 copia vacía") if ids.empty?
    notar.call("F5 copia sin el Juicio") if !ids.include?(:JUDGMENT)
    battle_g.ruta_arceus_copiar_equipo(boss_g)
    ids2 = (boss_g.pokemon.moves || []).map { |m| m.id }
    notar.call("F5 la copia se hizo dos veces") if ids2 != ids
    GC.start if (f5 % 30_000) < 20
  end

  f5
end

"FAMILIAS LISTAS"


# ── F7 · R15c: la escena de objetivos nunca ve un lado de 4+ ─────────────────
# Replica exacta de la aritmética de PokeBattle_SceneMenus:463-489 y del
# redimensionado salvaje de Battle_StartAndEnd:33-40, sobre configuraciones
# aleatorias del duelo divino (1-6 Pokémon por bando, bajas mezcladas, todos los
# modos de batalla). Ninguna combinación puede producir un índice fuera de los
# arreglos de botones (nil) ni un campo mayor a 3 por lado.
def fuzz_f7(rng, fallos)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  f7 = 0
  10_000.times do |i|
    modos = [[1, 1], [2, 2], [2, 1], [1, 2], [3, 3], [3, 1], [1, 3], [2, 3], [3, 2]]
    sizes = modos[rng.rand(modos.length)].dup
    n_player = 1 + rng.rand(6)
    n_foe = 1 + rng.rand(6)
    party = (0...n_player).map do |k|
      mon = FuzzMon.new(k, 0, :PIKACHU, 400 + (k * 37) % 200)
      mon.hp = rng.rand(4) == 0 ? 0 : mon.totalhp
      mon
    end
    foes = (0...n_foe).map do |k|
      mon = FuzzMon.new(k, 1, :ARCEUS, 1000)
      mon.hp = rng.rand(4) == 0 ? 0 : mon.totalhp
      mon.pokemon.instance_variable_set(:@ruta_arceus_divine, true) if k == 0
      mon
    end
    party[0].hp = party[0].totalhp if party.all? { |p| p.fainted? }
    foes[0].hp = foes[0].totalhp if foes.all? { |p| p.fainted? }
    battle = PokeBattle_Battle.new(party + foes)
    battle.ruta_side_split = n_foe
    battle.sideSizes = sizes
    battle.instance_variable_set(:@arceus_divine, true)
    battle.party2starts = [0]
    # 1) el tope divino: los conteos del bando salvaje nunca exceden su lado
    counts = battle.pbAbleTeamCounts(1)
    notar.call("F7 conteos divinos #{counts.inspect} exceden el lado #{sizes[1]}") if counts.compact.max.to_i > sizes[1]
    # 2) redimensionado salvaje tal cual el motor (Battle_StartAndEnd:33-40)
    redim = sizes.dup
    if battle.wildBattle? && counts[0].to_i != redim[1]
      if redim[0] == redim[1]
        redim = [counts[0].to_i, counts[0].to_i]
      else
        redim[1] = counts[0].to_i
      end
    end
    notar.call("F7 campo redimensionado a #{redim.inspect}: un lado mayor a 3 revienta SceneMenus:485") if redim.compact.max.to_i > 3
    # 3) cinturón del canon: topa a 3 cualquier tamaño que llegue a la escena
    seguros = redim.map { |n| n = n.to_i; n = 3 if n > 3; n = 1 if n < 1; n }
    notar.call("F7 cinturón ineficaz: #{seguros.inspect}") if seguros.max > 3 || seguros.min < 1
    # 4) aritmética exacta de los botones (SceneMenus:463-489) sin nil
    small = seguros.max > 2
    maxIndex = (seguros[0] > seguros[1]) ? (seguros[0] - 1) * 2 : seguros[1] * 2 - 1
    (0..maxIndex).each do |b|
      numButtons = seguros[b % 2]
      next if numButtons <= b / 2
      x = small ? [0, 82, 166][numButtons - 1] : [0, 116][numButtons - 1]
      notar.call("F7 botón #{b} con numButtons=#{numButtons}: índice nil en SceneMenus:485") if x.nil?
    end
    f7 += 1
    GC.start if (f7 % 500).zero?
  end
  # R15d: el relevo divino probado de verdad sobre el motor extraído: un divino
  # caído cede su hueco al siguiente de la cola (especie, PS llenos, sin
  # excepción), y con la cola vacía no pasa nada.
  1_000.times do |k|
    especies = RUTA_ARCEUS_SEQUITO.map { |fila| fila[0] }
    orden = especies.dup
    orden.sort_by! { |_e| rng.rand(1000) } if rng.rand(2) == 0
    boss = FuzzMon.new(1, 1, :ARCEUS, 1000)
    boss.pokemon.instance_variable_set(:@ruta_arceus_divine, true)
    en_campo = FuzzMon.new(3, 1, orden[0], 800)
    en_campo.hp = 0
    battle = PokeBattle_Battle.new([FuzzMon.new(0, 0, :PIKACHU, 400), boss, en_campo])
    battle.instance_variable_set(:@arceus_divine, true)
    cola = [Pokemon.new(orden[1], 100), Pokemon.new(orden[2], 100)]
    cola.each { |m| m.calc_stats }
    $ruta_arceus_relevo_cola = cola
    battle.pbArceusRelevoDivino
    notar.call("F7 relevo #{k}: el hueco no cambió de especie (#{en_campo.pokemon.species})") if en_campo.pokemon.species != orden[1]
    notar.call("F7 relevo #{k}: entró con PS #{en_campo.hp}/#{en_campo.totalhp}") if en_campo.hp != en_campo.totalhp || en_campo.fainted?
    notar.call("F7 relevo #{k}: la cola no avanzó") if $ruta_arceus_relevo_cola.length != 1
    # con la cola vacía, un segundo caído no debe hacer nada ni levantar errores
    en_campo.hp = 0
    $ruta_arceus_relevo_cola = []
    battle.pbArceusRelevoDivino
    notar.call("F7 relevo #{k}: con cola vacía tocó al battler") if en_campo.hp != 0
    f7 += 1
  end
  f7
end

# ── F6 · 10 000 · arranque del duelo divino completo y entradas R14 ─────────
# R14b: el reporte de partida mostró un NameError de constante anidada que sólo
# aparece al ejecutar Object#pbStartArceusDivineBattle de verdad. Esta familia
# corre el starter completo (prólogo, bucle de decisiones, merced, rendición,
# captura y rollback del sandbox) diez mil veces con colas de decisión
# aleatorias, más las entradas nuevas de R14 (Orden Divina, fondos, mil brazos
# del capturado y construcción del séquito). Cualquier NameError, NoMethodError
# o ArgumentError de un recurso inexistente revienta aquí, no en el juego.
module SaveData
  def self.compile_save_hash
    {}
  end
end unless SaveData.respond_to?(:compile_save_hash)

class RutaTempStub
  def initialize; @rules = {}; end
  def clearBattleRules; @rules = {}; nil; end
  def recordBattleRule(k, v = nil); @rules[k.to_s] = v; nil; end
  def battleRules; @rules; end
end

class RutaGlobalStub
  attr_accessor :nextBattleBGM, :nextBattleBack, :nextBattleME,
                :nextBattleCaptureME, :partner
end

class RutaTrainerStub
  attr_accessor :party, :name
  def initialize(party); @party = party; @name = "Ash"; end
  def able_pokemon_count; @party.count { |p| p && p.hp.to_i > 0 }; end
  def pokemon_count; @party.compact.length; end
end

def pbWildBattleCore(*args)
  # R15d: el duelo presenta exactamente dos Pokémon salvajes (el Creador y un
  # divino). Con cuatro, el motor apila paneles y funde sprites: se exige aquí
  # para que ningún regreso al 4v4 vuelva a pasar el fuzz.
  raise "F6: el duelo presentó #{args.length} Pokémon salvajes y deben ser 2 (el Creador y un divino)" if args.length != 2
  cola = $ruta_f6_cola
  raise "F6: cola de decisiones vacía" if cola.empty?
  return cola.shift
end

def pbStartOver
  $ruta_f6_startover = ($ruta_f6_startover || 0) + 1
  nil
end

def pbMessage(msg, *rest)
  return $ruta_f6_eleccion if rest[0].is_a?(Array)
  nil
end

def pbBattleAnimation(*args)
  yield if block_given?
  1
end

# R14b: las tres batallas CPU del prólogo usan el pipeline completo del motor
# (escena, pbStartBattle, switches de enemigos): desproporcionado para wasm. Se
# stubean aquí; el resto del prólogo (textos, caminatas, tonos) corre de verdad.
def pbArceusCinematicCpuBattle(trainer_specs, boss_moves, battle_size)
  $ruta_f6_cpu = ($ruta_f6_cpu || 0) + 1
  1
end

def pbAddPokemonSilent(pkmn)
  $Trainer.party.push(pkmn) if $Trainer
  true
end

COLAS_F6 = [[4], [1], [2, 4], [2, 2, 4], [2, 2, 2], [5], [3], [2, 5], [2, 1], [2, 2, 5]].freeze

def fuzz_f6_rango(rng, fallos, desde, hasta)
  notar = lambda { |m| fallos << m if fallos.length < 30 }
  f6 = 0
  especies_sequito = RUTA_ARCEUS_SEQUITO.map { |fila| fila[0] }
  nombres_invoc = RUTA_ARCEUS_INVOCACIONES.map { |fila| fila[0] }
  (desde...hasta).each do |i|
    cola_base = COLAS_F6[rng.rand(COLAS_F6.length)]
    $ruta_f6_cola = cola_base.dup
    prologo = (i % 10).zero? # el prólogo completo corre 1 000 veces: sus tres
    $ruta_f6_eleccion = prologo ? 0 : 1 # batallas CPU ya pesan como F3 entero
    $ruta_f6_startover = 0
    $game_switches = {}
    $game_switches[881] = true unless prologo
    $PokemonTemp = RutaTempStub.new
    $PokemonGlobal = RutaGlobalStub.new
    tam = 1 + rng.rand(6)
    party = (0...tam).map { |k| mon = Pokemon.new(:PIKACHU, 50 + rng.rand(51)); mon.calc_stats; mon }
    party.each { |p| p.hp = rng.rand(2) == 0 ? 0 : p.totalhp }
    party[0].hp = 0 # garantiza candidato para la merced del Rotom
    $Trainer = RutaTrainerStub.new(party)
    # Oráculo fiel al starter: la merced del Rotom ocurre UNA vez (switch 869),
    # así que el primer 2 de la cola reintenta el duelo y el segundo 2 termina
    # en rendición (decisión 2) sin consumir el resto de la cola.
    esperado = nil
    merced_usada = false
    $ruta_f6_cola.each do |d|
      if d == 2
        if merced_usada
          esperado = 2
          break
        end
        merced_usada = true
      else
        esperado = d
        break
      end
    end
    decision = nil
    begin
      decision = pbStartArceusDivineBattle
    rescue StandardError => e
      notar.call("F6 arranque #{i} (cola #{cola_base.inspect}) lanzó #{e.class}: #{e.message} BT=#{(e.backtrace || []).first(8).join(" <- ")}")
    end
    f6 += 1
    if decision
      notar.call("F6 arranque #{i} devolvió #{decision} fuera de 1..5") if ![1, 2, 3, 4, 5].include?(decision)
      notar.call("F6 arranque #{i}: la cola pedía #{esperado} y volvió #{decision}") if decision != esperado
      if decision == 4 && $game_switches[874] != true
        notar.call("F6 arranque #{i}: captura sin switch 874 firmado")
      end
      if decision == 2 && $ruta_f6_startover.to_i < 1
        notar.call("F6 arranque #{i}: rendición sin pbStartOver")
      end
    end
    # Entradas R14 con entradas aleatorias: ninguna puede levantar NameError ni
    # NoMethodError ni ArgumentError. Corre en mitad de los escenarios para
    # manter el presupuesto de memoria wasm (5 000 tandas x 2 campos).
    next unless (i % 2).zero?
    begin
      battle, party_b, boss = fuzz_divine_battle(2, 1000)
      battle.instance_variable_set(:@arceus_phase, 1 + rng.rand(6))
      battle.turnCount = 3 + rng.rand(20)
      battle.define_singleton_method(:pbRandom) { |x| rng.rand(x.to_i > 0 ? x : 1) }
      especie = (rng.rand(2) == 0 ? especies_sequito : nombres_invoc)[rng.rand(3) % 3] || :DIALGA
      battle.pbArceusOrdenDivina(boss, especie, :JUDGMENT, "prueba")
      battle.pbArceusPosesionFin(boss) if rng.rand(2) == 0
      batalla2, _p2, _b2 = fuzz_divine_battle(2, 800)
      batalla2.pbArceusFondo(["genesis1", "genesis2", "genesis3", "inexistente"][rng.rand(4)])
      pkmn_leg = pbArceusBuildLegendario(especies_sequito[rng.rand(3)], [:JUDGMENT], 1 + rng.rand(200))
      notar.call("F6 sequto #{i} devolvió nil") if pkmn_leg.nil?
      if rng.rand(2) == 0
        capt = FuzzMon.new(0, 0, :ARCEUS, 500)
        capt.pokemon.instance_variable_set(:@ruta_arceus_captured_god, true)
        capt.hp = 100 + rng.rand(100)
        batalla2.pbArceusMilibrazosDespertar(capt)
      end
      f6 += 0
    rescue StandardError => e
      notar.call("F6 entradas R14 #{i} lanzaron #{e.class}: #{e.message}")
    end
    GC.start if (i % 100).zero?
  end
  f6
end

# R14b: tres tandas con VM fresca (el arranque completo asigna mucho y la
# memoria wasm no se devuelve): 3 334 + 3 333 + 3 333 = 10 000 escenarios.
def fuzz_f6a(rng, fallos); fuzz_f6_rango(rng, fallos, 0, 3334); end
def fuzz_f6b(rng, fallos); fuzz_f6_rango(rng, fallos, 3334, 6667); end
def fuzz_f6c(rng, fallos); fuzz_f6_rango(rng, fallos, 6667, 10000); end#!/usr/bin/env node
/**
 * QA ejecutable del repertorio de Arceus y las invocaciones de La Ruta de Dios.
 * Extrae métodos Ruby de la sección compilada y los corre con CRuby/WASM, usando
 * los moves.dat/species.dat reales del juego para que el filtro no sea una lista
 * de prueba desconectada del contenido instalado.
 *
 * Comprueba: autodaño y huidas excluidos (también al copiar golpes del equipo),
 * rutas de función para cada movimiento del catálogo, puntaje/selección de apoyos
 * y ataques, invocaciones no capturables, y Dragon Tail/Circle Throw sin terminar
 * el wild battle del jefe. No sustituye una partida en RPG Maker: valida el Ruby
 * real, pero sigue necesitando confirmación en el juego para sprites/animación.
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { marshalLoad } from "../../web/js/marshal.js";
import { ROOT, stringValue, symbolName, symbolicRecords } from "../lib/fire_ash_registry.mjs";

const require = createRequire(import.meta.url);
const SECTION = "PokeMod_RutaDeDios";
const scriptsFile = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(ROOT, "pokemon_fire_ash/Data/Scripts.rxdata");
const wasmCandidates = [
  path.join(ROOT, "node_modules/@ruby/3.3-wasm-wasi/dist/ruby+stdlib.wasm"),
  path.join(ROOT, "node_modules/@ruby/wasm-wasi/dist/ruby+stdlib.wasm"),
];
const wasmPath = wasmCandidates.find((candidate) => fs.existsSync(candidate));
if (!wasmPath) {
  console.error("Falta el runtime Ruby/WASM. Instálalo sin modificar package.json:");
  console.error("  npm i --no-save @ruby/3.3-wasm-wasi");
  process.exit(2);
}
let DefaultRubyVM;
try {
  ({ DefaultRubyVM } = require("@ruby/wasm-wasi/dist/node"));
} catch (error) {
  console.error(`No se pudo cargar @ruby/wasm-wasi: ${error.message}`);
  process.exit(2);
}

function readSection(file, name = SECTION) {
  assert(fs.existsSync(file), `Falta ${path.relative(ROOT, file)}`);
  const rows = marshalLoad(fs.readFileSync(file));
  const row = rows.find((entry) => (entry[1]?.text ?? String(entry[1])) === name);
  assert(row, `Falta la sección ${name} en ${path.relative(ROOT, file)}`);
  return zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8");
}

function parseSimpleSymbolArray(ruby, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const block = ruby.match(new RegExp(`^${escaped}\\s*=\\s*\\[([^\\]]*)\\](?:\\.freeze)?`, "ms"))?.[1];
  assert(block, `No se pudo leer la constante ${name}`);
  return [...block.matchAll(/:([A-Z0-9_]+)/g)].map((match) => match[1]);
}

function parseFunctionArray(ruby, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const block = ruby.match(new RegExp(`^${escaped}\\s*=\\s*%w\\[([\\s\\S]*?)\\]\\.freeze`, "m"))?.[1];
  assert(block, `No se pudo leer la constante ${name}`);
  return block.trim().split(/\s+/).filter(Boolean);
}

function parsePhaseSets(ruby) {
  const block = ruby.match(/^RUTA_ARCEUS_MOVE_SETS\s*=\s*\[([\s\S]*?)^\]/m)?.[1];
  assert(block, "No se pudo leer RUTA_ARCEUS_MOVE_SETS");
  const rows = [...block.matchAll(/\[([^\[\]]*)\]/g)].map((match) =>
    [...match[1].matchAll(/:([A-Z0-9_]+)/g)].map((move) => move[1]));
  assert.equal(rows.length, 6, "El catálogo debe contener las seis fases");
  return rows;
}

function rubySymbols(values) {
  return `[${values.map((value) => `:${value}`).join(", ")}]`;
}

function rubyNestedSymbols(rows) {
  return `[${rows.map((row) => rubySymbols(row)).join(",\n  ")}]`;
}

const routeRuby = readSection(scriptsFile);
const phaseSets = parsePhaseSets(routeRuby);
const selfDamageMoves = parseSimpleSymbolArray(routeRuby, "RUTA_ARCEUS_SELF_DAMAGING_MOVES");
const selfDamageFunctions = parseFunctionArray(routeRuby, "RUTA_ARCEUS_SELF_DAMAGING_FUNCTIONS");
const scriptBreakingMoves = parseSimpleSymbolArray(routeRuby, "RUTA_ARCEUS_SCRIPT_BREAKING_MOVES");
const scriptBreakingFunctions = parseFunctionArray(routeRuby, "RUTA_ARCEUS_SCRIPT_BREAKING_FUNCTIONS");
const milBrazos = parseSimpleSymbolArray(routeRuby, "RUTA_ARCEUS_MIL_BRAZOS");
const primigeniaMoves = parseSimpleSymbolArray(routeRuby, "RUTA_ARCEUS_PRIMIGENIA_MOVES");
const stageCount = Number(routeRuby.match(/^RUTA_ARCEUS_STAGE_COUNT\s*=\s*(\d+)/m)?.[1]);
assert.equal(stageCount, 6, "El duelo debe mantener seis barras/fases");

const moveRows = symbolicRecords("moves.dat").map(({ id, value }) => ({
  id,
  function_code: stringValue(value.getIvar("function_code")),
  base_damage: Number(value.getIvar("base_damage") ?? 0),
  type: symbolName(value.getIvar("type")) || null,
  accuracy: Number(value.getIvar("accuracy") ?? 100),
  priority: Number(value.getIvar("priority") ?? 0),
  name: stringValue(value.getIvar("name")) || id,
}));
const speciesRow = symbolicRecords("species.dat").find(({ id }) => id === "ARCEUS");
assert(speciesRow, "No existe ARCEUS en species.dat");
const levelMoves = (speciesRow.value.getIvar("moves") ?? []).map((entry) => [
  Number(entry?.[0] ?? 1), symbolName(entry?.[1]),
]).filter((entry) => entry[1]);
const tutorMoves = (speciesRow.value.getIvar("tutor_moves") ?? []).map(symbolName).filter(Boolean);

// Cobertura del dispatcher del motor: toda función que puede recibir Arceus o
// su séquito debe tener clase PokeBattle_Move_XXX instalada en Scripts.rxdata.
const scripts = marshalLoad(fs.readFileSync(scriptsFile));
const moveClasses = new Set();
for (const row of scripts) {
  try {
    const text = zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8");
    for (const match of text.matchAll(/class\s+PokeBattle_Move_([0-9A-F]{3,4})\b/g)) moveClasses.add(match[1]);
  } catch {
    // Algunas secciones pueden no ser Ruby/zlib; no forman parte del dispatcher.
  }
}
const movesById = new Map(moveRows.map((move) => [move.id, move]));
const routeMoveIds = new Set([
  ...levelMoves.map((entry) => entry[1]),
  ...tutorMoves,
  ...phaseSets.flat(),
  ...milBrazos,
  ...primigeniaMoves,
]);
const missingMoveData = [...routeMoveIds].filter((id) => !movesById.has(id));
assert.deepEqual(missingMoveData, [], "Hay movimientos de Arceus sin fila en moves.dat");
const missingMoveClasses = [...routeMoveIds]
  .map((id) => movesById.get(id).function_code)
  .filter((code) => code && !moveClasses.has(code));
assert.deepEqual([...new Set(missingMoveClasses)], [], "Falta una clase de efecto de movimiento usada por el repertorio");

// Comprueba que los movimientos peligrosos de su learnset/tutor están realmente
// clasificados, y que las tres rutas de huida del motor no pasan por el catálogo.
const learnable = new Set([...levelMoves.map((entry) => entry[1]), ...tutorMoves]);
const selfDamagingLearnable = [...learnable].filter((id) => {
  const data = movesById.get(id);
  return selfDamageMoves.includes(id) || selfDamageFunctions.includes(data.function_code.toUpperCase());
});
assert.deepEqual(new Set(selfDamagingLearnable), new Set(["HEALINGWISH", "PERISHSONG", "CURSE", "SUBSTITUTE"]),
  "Cambió el conjunto de movimientos de autodaño del learnset/tutor: vuelve a auditar moves.dat");
for (const [id, code] of [["TELEPORT", "0EA"], ["ROAR", "0EB"], ["WHIRLWIND", "0EB"]]) {
  assert(movesById.has(id), `Falta el movimiento ${id}`);
  assert(scriptBreakingMoves.includes(id) && scriptBreakingFunctions.includes(code),
    `${id} ya no está excluido aunque el motor puede cerrar el wild battle`);
  assert.equal(movesById.get(id).function_code.toUpperCase(), code, `Cambió la ruta de ${id}; reaudita su efecto`);
}
for (const id of ["DRAGONTAIL", "CIRCLETHROW"]) {
  assert.equal(movesById.get(id)?.function_code.toUpperCase(), "0EC", `${id} cambió de ruta`);
  assert(routeRuby.includes("class PokeBattle_Move_0EC"), `${id} puede terminar la batalla sin la protección 0EC`);
}

const extraction = String.raw`
require "base64"
require "json"
SRC = Base64.decode64("__B64__")
WANTED = {
  "" => ["pbArceusSelfDamagingMove?", "pbArceusScriptBreakingMove?", "pbArceusSafeMoveIds"],
  "PokeBattle_Battle" => ["pbArceusMoveCatalogIds", "pbArceusStatusMoveScore",
                           "pbArceusAttackScore", "pbArceusScoreMove",
                           "pbArceusChooseSmartMove", "history_resistido?",
                           "pbArceusRememberMove", "pbArceusSmartAction"],
  "PokeBattle_BattleCommon" => ["pbCaptureCalc"],
  "PokeBattle_Move_0EC" => ["pbEffectAgainstTarget"]
}
lines = SRC.split("\n")
found = {}
stack = []
walk = nil
walk = lambda do |node|
  next if !node.is_a?(RubyVM::AbstractSyntaxTree::Node)
  case node.type
  when :CLASS, :MODULE
    named = node.children[0]
    label = named.is_a?(RubyVM::AbstractSyntaxTree::Node) ? named.children.compact.map(&:to_s).join("::") : named.to_s
    stack.push(label)
    node.children.each { |child| walk.call(child) }
    stack.pop
    next
  when :SCLASS
    stack.push("<sclass>")
    node.children.each { |child| walk.call(child) }
    stack.pop
    next
  when :DEFN
    scope = stack.join("::")
    found["#{scope}##{node.children[0]}"] = [node.first_lineno, node.last_lineno]
  end
  node.children.each { |child| walk.call(child) }
end
walk.call(RubyVM::AbstractSyntaxTree.parse(SRC))
missing = []
methods = {}
WANTED.each do |scope, names|
  names.each do |name|
    key = "#{scope}##{name}"
    range = found[key]
    if !range
      missing << key
    else
      methods[key] = lines[(range[0] - 1)..(range[1] - 1)].join("\n")
    end
  end
end
missing.empty? ? JSON.generate(methods) : "MISSING:#{missing.join(",")}"`;

const { vm } = await DefaultRubyVM(await WebAssembly.compile(fs.readFileSync(wasmPath)));
const extracted = vm.eval(extraction.replace("__B64__", Buffer.from(routeRuby).toString("base64"))).toString();
assert(!extracted.startsWith("MISSING:"), `No se pudieron extraer métodos reales: ${extracted}`);
const methods = JSON.parse(extracted);
const method = (scope, name) => methods[`${scope}#${name}`];

const rubyConstants = `
RUTA_ARCEUS_SELF_DAMAGING_MOVES = ${rubySymbols(selfDamageMoves)}.freeze
RUTA_ARCEUS_SELF_DAMAGING_FUNCTIONS = %w[${selfDamageFunctions.join(" ")}].freeze
RUTA_ARCEUS_SCRIPT_BREAKING_MOVES = ${rubySymbols(scriptBreakingMoves)}.freeze
RUTA_ARCEUS_SCRIPT_BREAKING_FUNCTIONS = %w[${scriptBreakingFunctions.join(" ")}].freeze
RUTA_ARCEUS_MOVE_SETS = ${rubyNestedSymbols(phaseSets)}
RUTA_ARCEUS_MIL_BRAZOS = ${rubySymbols(milBrazos)}.freeze
RUTA_ARCEUS_PRIMIGENIA_MOVES = ${rubySymbols(primigeniaMoves)}.freeze
RUTA_ARCEUS_STAGE_COUNT = ${stageCount}
`;
const dataPayload = Buffer.from(JSON.stringify({ moves: moveRows, levelMoves, tutorMoves })).toString("base64");
const objectMethods = [
  method("", "pbArceusSelfDamagingMove?"),
  method("", "pbArceusScriptBreakingMove?"),
  method("", "pbArceusSafeMoveIds"),
].join("\n\n");
const battleMethods = [
  method("PokeBattle_Battle", "pbArceusMoveCatalogIds"),
  method("PokeBattle_Battle", "pbArceusStatusMoveScore"),
  method("PokeBattle_Battle", "pbArceusAttackScore"),
  method("PokeBattle_Battle", "pbArceusScoreMove"),
  method("PokeBattle_Battle", "pbArceusChooseSmartMove"),
  method("PokeBattle_Battle", "history_resistido?"),
  method("PokeBattle_Battle", "pbArceusRememberMove"),
  method("PokeBattle_Battle", "pbArceusSmartAction"),
].join("\n\n");

const prelude = String.raw`
require "base64"
require "json"
QA_DATA = JSON.parse(Base64.decode64("__DATA__"))

def _INTL(text, *args); text; end

module GameData
  MoveEntry = Struct.new(:id, :function_code, :base_damage, :type, :accuracy, :priority, :name)
  SpeciesEntry = Struct.new(:moves, :tutor_moves)
  class Move
    def self.all
      @all ||= QA_DATA.fetch("moves").each_with_object({}) do |row, result|
        id = row.fetch("id").to_sym
        result[id] = MoveEntry.new(id, row["function_code"].to_s,
          row["base_damage"].to_i, row["type"] && row["type"].to_sym,
          row["accuracy"].to_i, row["priority"].to_i, row["name"].to_s)
      end
    end
    def self.exists?(id); all.key?(id.to_sym); end
    def self.get(id); all.fetch(id.to_sym); end
  end
  class Species
    def self.get(id)
      raise "QA sólo contiene el learnset de Arceus" if id.to_sym != :ARCEUS
      levels = QA_DATA.fetch("levelMoves").map { |level, move| [level.to_i, move.to_sym] }
      tutors = QA_DATA.fetch("tutorMoves").map(&:to_sym)
      SpeciesEntry.new(levels, tutors)
    end
  end
end

module Pokemon
  MAX_MOVES = 4
end
module Effectiveness
  NORMAL_EFFECTIVE = 8
  def self.calculate(_attack, _type1, _type2 = nil, _type3 = nil); NORMAL_EFFECTIVE; end
end

class QAPokemon
  attr_reader :species
  def initialize(species); @species = species; end
end
class QAMove
  attr_reader :id, :name, :type
  def initialize(id)
    data = GameData::Move.get(id)
    @id = data.id
    @name = data.name
    @type = data.type
  end
  def damagingMove?; GameData::Move.get(@id).base_damage.to_i > 0; end
  def statusMove?; !damagingMove?; end
end
class QABattler
  attr_accessor :index, :side, :moves, :stages, :hp, :totalhp, :pokemon, :allow_status
  def initialize(index, side, species)
    @index = index; @side = side; @pokemon = QAPokemon.new(species)
    @moves = []; @stages = Hash.new(0); @hp = 300; @totalhp = 400
    @allow_status = true
  end
  def opposes?; @side == 1; end
  def fainted?; @hp <= 0; end
  def pbHasType?(_type); false; end
  def pbTypes(_real = true); [:NORMAL, nil, nil]; end
  def pbCanInflictStatus?(_status, _user = nil, _show = false, _move = nil); @allow_status; end
  def pbCanLowerStatStage?(*_args); @allow_status; end
  def pbThis(*_args); @pokemon.species.to_s; end
end
`;

const battleTail = String.raw`
  attr_reader :registered_move, :registered_target, :messages
  def initialize(battlers)
    @battlers = battlers
    @arceus_phase = 1
    @turnCount = 7
    @ruta_arceus_move_history = []
    @ruta_repertorio_fase = 1
    @ruta_repertorio_objetivos = "PIKACHU"
    @ruta_repertorio_turno = 7
    @messages = []
  end
  def arceus_battler; @battlers.find { |b| b.pokemon && b.pokemon.species == :ARCEUS }; end
  def arceus_state(_battler); true; end
  def arceus_cinematic_adaptive?; false; end
  def pbArceusRedlineHeal(*_args); false; end
  def pbCanChooseMove?(*_args); true; end
  def pbRegisterMove(index, move_index, *_args); @registered_move = [index, move_index]; true; end
  def pbRegisterTarget(index, target_index); @registered_target = [index, target_index]; end
  def pbDisplayPaused(message); @messages << message; end
  def pbArceusBattleCommentary(*_args); true; end
  def pbArceusAdaptTypeToRival(*_args); true; end
  def pbAutoChooseMove(*_args); true; end
  def pbRandom(_max); 0; end
  def arceus_divine?; true; end
  def ruta_arceus_primigenia?; false; end
`;

const captureMethod = method("PokeBattle_BattleCommon", "pbCaptureCalc");
const knockbackMethod = method("PokeBattle_Move_0EC", "pbEffectAgainstTarget");
const rubyProgram = [
  `# Datos marshal reales convertidos a filas QA\n${prelude.replace("__DATA__", dataPayload)}`,
  rubyConstants,
  `class Object\n${objectMethods}\nend`,
  `class PokeBattle_Battle\n${battleMethods}\n${battleTail}\nend`,
  String.raw`
module PokeBattle_BattleCommon
  def pbCaptureCalc(_pkmn, _battler, _catch_rate, _ball)
    @qa_original_capture_calls = @qa_original_capture_calls.to_i + 1
    4
  end
  alias _ruta_arceus_original_capture_calc pbCaptureCalc
` + captureMethod + String.raw`
end
class QACapturePokemon
  attr_reader :species
  def initialize(species); @species = species; end
end
class QACaptureBattler
  attr_reader :index, :pokemon
  def initialize(index, species); @index = index; @pokemon = QACapturePokemon.new(species); end
end
class QACaptureBattle
  include PokeBattle_BattleCommon
  attr_reader :messages
  def initialize(slot)
    @ruta_arceus_invocation_state = { :slot_index => slot }
    @messages = []
    @qa_original_capture_calls = 0
  end
  def arceus_divine?; false; end
  def pbDisplay(message); @messages << message; end
  def original_capture_calls; @qa_original_capture_calls; end
end

class QAKnockbackBattle
  attr_accessor :decision
  attr_reader :messages
  def initialize(divine)
    @divine = divine; @messages = []; @decision = nil
  end
  def arceus_divine?; @divine; end
  def wildBattle?; true; end
  def canRun; true; end
  def pbDisplay(message); @messages << message; end
end
class QAKnockbackUser
  def initialize(divine); @divine = divine; end
  def ruta_arceus_divine_boss?; @divine; end
  def pbThis; "Arceus"; end
end
class PokeBattle_Move_0EC
  def initialize(battle); @battle = battle; end
  def pbEffectAgainstTarget(_user, _target)
    @battle.decision = 3 if @battle.wildBattle? && @battle.canRun
  end
  alias _ruta_arceus_original_wild_knockback pbEffectAgainstTarget
` + knockbackMethod + String.raw`
end
`,
  String.raw`
# 1) Catálogo seguro calculado con moves.dat y el learnset/tutor reales.
battle = PokeBattle_Battle.new([QABattler.new(0, 0, :PIKACHU), QABattler.new(1, 1, :ARCEUS)])
boss = battle.instance_variable_get(:@battlers)[1]
party = battle.instance_variable_get(:@battlers)[0]
catalog = battle.pbArceusMoveCatalogIds
raise "catalog is empty" if catalog.empty?
[:CALMMIND, :JUDGMENT].each { |id| raise "safe move missing: #{id}" unless catalog.include?(id) }
[:HEALINGWISH, :PERISHSONG, :CURSE, :SUBSTITUTE, :ROAR, :WHIRLWIND, :TELEPORT].each do |id|
  raise "unsafe move leaked into catalog: #{id}" if catalog.include?(id)
end

battle.instance_variable_set(:@ruta_arceus_equipo_move_ids, [:EXPLOSION, :TELEPORT, :TACKLE, :DRAGONTAIL])
copied_catalog = battle.pbArceusMoveCatalogIds
raise "copied self-KO leaked" if copied_catalog.include?(:EXPLOSION)
raise "copied escape leaked" if copied_catalog.include?(:TELEPORT)
raise "safe copied move missing" unless copied_catalog.include?(:TACKLE)
raise "Dragon Tail was incorrectly filtered from a copied moveset" unless copied_catalog.include?(:DRAGONTAIL)

sample = pbArceusSafeMoveIds([:TACKLE, :HEALINGWISH, :PERISHSONG, :CURSE, :SUBSTITUTE,
                               :ROAR, :WHIRLWIND, :TELEPORT, :DRAGONTAIL, :NO_SUCH_MOVE])
raise "safe move filter mismatch: #{sample.inspect}" unless sample == [:TACKLE, :DRAGONTAIL]

# 2) La puntuación detecta apoyo propio y un estado aplicable al objetivo.
calm = QAMove.new(:CALMMIND)
raise "Calm Mind not scored" unless battle.pbArceusStatusMoveScore(calm, boss) == [42.0, -1]
thunder = QAMove.new(:THUNDERWAVE)
raise "Thunder Wave target missing" unless battle.pbArceusStatusMoveScore(thunder, boss) == [34.0, party.index]
party.allow_status = false
raise "immune target was selected for status" unless battle.pbArceusStatusMoveScore(thunder, boss) == [0.0, -1]
party.allow_status = true

# 3) El selector real puede registrar un apoyo con objetivo propio (índice -1)
#    y sigue pudiendo registrar un ataque con un objetivo enemigo válido.
boss.moves = [QAMove.new(:CALMMIND), QAMove.new(:TACKLE)]
raise "smart action rejected legal status move" unless battle.pbArceusSmartAction(1, boss)
raise "smart action did not register Calm Mind" unless battle.registered_move == [1, 0]
raise "self-support was given an enemy target" unless battle.registered_target.nil?

battle2 = PokeBattle_Battle.new([QABattler.new(0, 0, :PIKACHU), QABattler.new(1, 1, :ARCEUS)])
boss2 = battle2.instance_variable_get(:@battlers)[1]
boss2.moves = [QAMove.new(:TACKLE)]
raise "smart action rejected a damaging move" unless battle2.pbArceusSmartAction(1, boss2)
raise "damaging move not registered" unless battle2.registered_move == [1, 0]
raise "damaging move has no target" unless battle2.registered_target == [1, 0]

# 4) pokemonIndex=-1 de una invocación no puede llegar a pbRemoveFromParty:
#    la captura falla antes de llamar al cálculo normal (y tampoco bloquea otro slot).
capture = QACaptureBattle.new(3)
result = capture.pbCaptureCalc(nil, QACaptureBattler.new(3, :DIALGA), nil, :POKEBALL)
raise "invocation capture should fail" unless result == 0
raise "normal capture calc was reached for invocation" unless capture.original_capture_calls == 0
raise "invocation capture warning missing" if capture.messages.empty?
result_other = capture.pbCaptureCalc(nil, QACaptureBattler.new(1, :DIALGA), nil, :POKEBALL)
raise "a different slot was blocked" unless result_other == 4 && capture.original_capture_calls == 1

# 5) El efecto de Dragon Tail/Circle Throw no cambia decision=3 en el jefe,
#    pero conserva la ruta original fuera de ese combate.
ash = Object.new
move_battle = QAKnockbackBattle.new(true)
PokeBattle_Move_0EC.new(move_battle).pbEffectAgainstTarget(QAKnockbackUser.new(true), ash)
raise "0EC let the divine wild battle escape" unless move_battle.decision.nil?
move_battle_normal = QAKnockbackBattle.new(false)
PokeBattle_Move_0EC.new(move_battle_normal).pbEffectAgainstTarget(QAKnockbackUser.new(false), ash)
raise "0EC changed normal wild behavior" unless move_battle_normal.decision == 3

"ARCEUS_MOVES_QA_OK: #{catalog.length} movimientos seguros; autodaño/huida filtrados; apoyo y ataques seleccionables; invocación no capturable; 0EC no cierra el duelo."
`,
].join("\n\n");

const program = rubyProgram.replace("__DATA__", dataPayload);
let report;
try {
  report = vm.eval(program).toString();
} catch (error) {
  console.error("FALLO en la QA dinámica de movimientos/invocaciones:");
  const detail = String(error?.message ?? error);
  console.error(detail.split("\n").slice(0, 20).join("\n"));
  const rubyLine = Number(detail.match(/eval:(\d+)/)?.[1] ?? 0);
  if (rubyLine > 0) {
    console.error(program.split("\n").slice(Math.max(0, rubyLine - 7), rubyLine + 6)
      .map((line, index) => `${Math.max(1, rubyLine - 6) + index}: ${line}`).join("\n"));
  }
  process.exit(1);
}
console.log(report);
if (!report.includes("ARCEUS_MOVES_QA_OK")) process.exit(1);// Sonda de ALCANCE REAL (AST): dónde viven realmente cada def y cada constante
// de la sección instalada. La indentación NO define ámbito en Ruby: sólo las
// palabras class/module/end. Esta sonda revela defs "col 0" que en verdad están
// atrapados dentro de un class...end.
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { createRequire } from "node:module";
import { marshalLoad } from "../../web/js/marshal.js";
import { ROOT } from "../lib/fire_ash_registry.mjs";


function wasmBinaryPath() {
  for (const p of [
    path.join(ROOT, "node_modules/@ruby/3.3-wasm-wasi/dist/ruby+stdlib.wasm"),
    path.join(ROOT, "node_modules/@ruby/wasm-wasi/dist/ruby+stdlib.wasm"),
  ]) if (fs.existsSync(p)) return p;
  return null;
}
const require = createRequire(import.meta.url);
const { DefaultRubyVM } = require("@ruby/wasm-wasi/dist/node");

const posicionales = process.argv.slice(2).filter((a) => !a.startsWith("--"));
const scripts = marshalLoad(fs.readFileSync(path.join(ROOT, posicionales[0] || "pokemon_fire_ash/Data/Scripts.rxdata")));
const nombre = posicionales[1] || "PokeMod_RutaDeDios";
const entrada = scripts.find(([, t]) => t && t.text === nombre);
const src = zlib.inflateSync(Buffer.from(entrada[2].bytes)).toString("utf8");

const { vm } = await DefaultRubyVM(await WebAssembly.compile(fs.readFileSync(wasmBinaryPath())));
const ruby = `
require "json"
src = Base64.decode64("__B64__").force_encoding("UTF-8")
raiz = RubyVM::AbstractSyntaxTree.parse(src)
salida = []
pila = []
walk = lambda do |nodo|
  break if nodo.nil?
  case nodo.type
  when :CLASS, :MODULE
    nombre = nodo.children[0]
    etiqueta = nombre.respond_to?(:children) ? nombre.children.compact.map(&:to_s).join("::") : nombre.to_s
    pila.push(etiqueta)
    nodo.children.each { |h| walk.call(h) if h.is_a?(RubyVM::AbstractSyntaxTree::Node) }
    pila.pop
    break
  when :SCLASS
    pila.push("<sclass>")
    nodo.children.each { |h| walk.call(h) if h.is_a?(RubyVM::AbstractSyntaxTree::Node) }
    pila.pop
    break
  when :DEFN
    salida << [pila.dup, nodo.children[0].to_s, nodo.first_lineno, "def"]
  when :DEFS
    salida << [pila.dup, nodo.children[1].to_s, nodo.first_lineno, "def"]
  when :CDECL, :CASGN
    nombre_const = nodo.type == :CDECL ? nodo.children[0] : nodo.children[1]
    salida << [pila.dup, nombre_const.to_s, nodo.first_lineno, "const"]
  end
  nodo.children.each { |h| walk.call(h) if h.is_a?(RubyVM::AbstractSyntaxTree::Node) }
end
walk.call(raiz)
JSON.generate(salida)
`.replace("__B64__", Buffer.from(src, "utf8").toString("base64"));
const json = JSON.parse(vm.eval(`require "base64"; require "json"; ` + ruby).toString());
const lineas = src.split("\n");
const MANDATORIOS_TOP = [
  "pbStartArceusDivineBattle", "pbArceusBuildLegendario", "pbArceusMoveIds",
  "pbArceusRotomMercy", "pbArceusSurrenderSequence", "pbArceusNormalizeCaptured",
  "pbArceusCinematicPrelude", "pbArceusCinematicCpuBattle",
  "RUTA_ARCEUS_SEQUITO", "RUTA_ARCEUS_INVOCACIONES", "RUTA_ARCEUS_MOVE_SETS",
];
if (process.argv.includes("--audit")) {
  const violaciones = [];
  for (const [scope, name, line, kind] of json) {
    const intencionTop = /^\S/.test(lineas[line - 1] || "");
    if (scope.length > 0 && intencionTop) {
      violaciones.push(`${kind} ${name} (línea ${line}) parece de nivel superior pero vive dentro de ${scope.join(" > ")}`);
    }
  }
  if (nombre === "PokeMod_RutaDeDios") {
    for (const obligatorio of MANDATORIOS_TOP) {
      const item = json.find(([, n]) => n === obligatorio);
      if (!item) violaciones.push(`falta por completo: ${obligatorio}`);
      else if (item[0].length > 0) violaciones.push(`${obligatorio} debe vivir al nivel superior y vive en ${item[0].join(" > ")}`);
    }
  }
  if (violaciones.length) {
    console.log(`✘ ALCANCE R15b (${nombre}): ${violaciones.length} violaciones`);
    for (const v of violaciones) console.log(`  · ${v}`);
    process.exit(1);
  }
  console.log(`✔ ALCANCE R15b (${nombre}): ${json.length} defs/constantes; todo lo que parece de nivel superior lo es de verdad.`);
  process.exit(0);
}
const anidados = json.filter(([scope]) => scope.length > 0);
console.log(`sección ${nombre}: ${json.length} defs/constantes · ${anidados.length} ANIDADOS`);
for (const [scope, name, line, kind] of anidados) {
  console.log(`  ${kind} ${name} (línea ${line}) dentro de: ${scope.join(" > ")}`);
}
const top = json.filter(([scope]) => scope.length === 0 && (name => /BuildLegendario|SEQUITO/.test(name))(json[0][1]) );
for (const [scope, name, line, kind] of json) {
  if (/BuildLegendario|SEQUITO|StartArceusDivineBattle/.test(name)) {
    console.log(`  >> ${kind} ${name} línea ${line} scope=[${scope.join(" > ")}]`);
  }
}#!/usr/bin/env node
/**
 * arceus_shield_harness.mjs
 *
 * QA *en vivo* de las protecciones de Arceus de La Ruta de Dios. El resto de
 * verificadores del repositorio son estáticos (leen el Ruby instalado y buscan
 * cadenas); este ejecuta el código real dentro de un CRuby (Ruby 3.3 compilado a
 * WebAssembly) sobre clases de prueba que imitan las rutas de daño del motor:
 *
 *   · `PokeBattle_Battler#hp=`            (escrituras directas de PS)
 *   · `PokeBattle_Battler#pbReduceHP`     (granizo, retroceso, daño indirecto)
 *   · `PokeBattle_Move#pbInflictHPDamage` (target.hp -= hpLost de los movimientos)
 *   · `PokeBattle_Battler#pbFaint`
 *   · `PokeBattle_Move_DF08#pbAttackingTurnEffect` (Ball Breaker, el movimiento de
 *     dos turnos del Metagross de Steven, que exigía `selfProtected?`/`sideProtected?`)
 *
 * Con eso se comprueba que ni el granizo de la cumbre, ni un Metagross, ni una
 * ruta externa (habilidad, movimiento custom, plugin) pueden lastimar al Arceus
 * de las cinemáticas ni derrotar al Arceus divino del duelo de Ash, y que el
 * Arceus capturado o cualquier otro Arceus conserva las reglas normales.
 *
 * Uso:
 *   npm i --no-save @ruby/3.3-wasm-wasi      # dependencia opcional de QA
 *   node tools/qa/arceus_shield_harness.mjs  # lee pokemon_fire_ash/Data/Scripts.rxdata
 *   node tools/qa/arceus_shield_harness.mjs ruta/a/Scripts.rxdata
 *
 * No forma parte de `npm test` porque el binario de Ruby (~36 MB) se descarga
 * aparte; úsalo al tocar la sección PokeMod_RutaDeDios.
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { marshalLoad } from "../../web/js/marshal.js";

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const SECTION = "PokeMod_RutaDeDios";

function wasmBinaryPath() {
  const candidates = [
    path.join(ROOT, "node_modules/@ruby/3.3-wasm-wasi/dist/ruby+stdlib.wasm"),
    path.join(ROOT, "node_modules/@ruby/wasm-wasi/dist/ruby+stdlib.wasm"),
  ];
  return candidates.find((candidate) => fs.existsSync(candidate)) || null;
}

function readSection(file, name = SECTION) {
  const scripts = marshalLoad(fs.readFileSync(file));
  const row = scripts.find((entry) => (entry[1]?.text ?? String(entry[1])) === name);
  if (!row) throw new Error(`No se encontró la sección ${name} en ${file}`);
  return zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8");
}

const DF08_SECTION = "Despacito Despair";

const wasm = wasmBinaryPath();
if (!wasm) {
  console.error("Falta el runtime de Ruby para la QA en vivo. Instálalo sin tocar package.json:");
  console.error("  npm i --no-save @ruby/3.3-wasm-wasi");
  process.exit(2);
}
let DefaultRubyVM;
try {
  ({ DefaultRubyVM } = require("@ruby/wasm-wasi/dist/node"));
} catch {
  console.error("No se pudo cargar @ruby/wasm-wasi. Vuelve a ejecutar:");
  console.error("  npm i --no-save @ruby/3.3-wasm-wasi");
  process.exit(2);
}

const scriptsFile = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(ROOT, "pokemon_fire_ash/Data/Scripts.rxdata");
const modRuby = readSection(scriptsFile);
const df08Ruby = readSection(scriptsFile, DF08_SECTION);
if (!modRuby.includes("class PokeBattle_Move_DF08")) {
