function cmd(code, parameters = [], indent = 0) {
  return new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", parameters]]);
}
function eventCondition(selfSwitch = "") {
  return new RObject("RPG::Event::Page::Condition", [
