  record.setIvar("tutor_moves", ["CHARGEBEAM", "DAZZLINGGLEAM", "LIGHTSCREEN", "PSYCHIC", "SHADOWBALL", "THUNDERBOLT", "THUNDERWAVE"].map(Sym));
