  if (!tileset) throw new Error(`${config.mapId}: tileset ${parsed.tilesetId} ausente.`);
  for (const oldId of config.source) for (const newId of config.accent) if (!equivalent(tileset, oldId, newId)) {
    throw new Error(`${config.mapId}: tile ${oldId} y ${newId} no preservan pasabilidad/prioridad/terrain tag.`);
  }
  const beforeTableHash = tableHash(parsed.table);
  const placement = findPlacement(parsed, config);
  const changes = placement.cells.map(([x, y], index) => {
    const oldTileId = tableGet(parsed.table, x, y, 0);
    const newTileId = config.accent[index % config.accent.length];
    if (!equivalent(tileset, oldTileId, newTileId)) throw new Error(`${config.mapId}: sustitución insegura ${oldTileId}->${newTileId}.`);
    tableSet(parsed.table, x, y, 0, newTileId);
    return { x, y, layer: 0, oldTileId, newTileId };
  });
  raw.setIvar("data", tableToUserDef(parsed.table));
  const afterBuffer = Buffer.from(marshalDump(raw));
  fs.writeFileSync(filePath, afterBuffer);
  const reparsed = parseMap(marshalLoad(afterBuffer));
  const changed = changes.every((entry) => tableGet(reparsed.table, entry.x, entry.y, entry.layer) === entry.newTileId);
  if (!changed || tableHash(reparsed.table) === beforeTableHash) throw new Error(`${config.mapId}: la composición visual no quedó persistida.`);
  return {
    mapId: config.mapId,
    sector: hierarchyByMap.get(config.mapId)?.sector,
    sectorName: hierarchyByMap.get(config.mapId)?.sectorName,
    episode: blueprintByMap.get(config.mapId)?.title,
    visualBatch: Math.floor(CONFIGS.indexOf(config) / 5) + 6,
    motif: config.motif,
    intent: config.intent,
    tilesetId: parsed.tilesetId,
    tilesetName: tileset.tilesetName,
    center: placement.center,
    usedFallbackPlacement: Boolean(placement.fallback),
    keptOneTileBufferFromEvents: placement.buffered,
    changedCells: changes.length,
    changes,
    safety: {
      eventsMoved: 0,
      passabilityChangedCells: 0,
      priorityChangedCells: 0,
      terrainTagChangedCells: 0,
      dimensionsChanged: false,
      tilesetChanged: false,
    },
    before: { fileSha256: sha(beforeBuffer), tileSha256: beforeTableHash },
    after: { fileSha256: sha(afterBuffer), tileSha256: tableHash(reparsed.table) },
  };
}
function verify(report) {
  const errors = [];
  for (const entry of report.maps) {
    const filePath = path.join(DATA, mapFile(entry.mapId));
    if (!fs.existsSync(filePath)) { errors.push(`${entry.mapId}: mapa ausente`); continue; }
    const buffer = fs.readFileSync(filePath);
    const parsed = parseMap(marshalLoad(buffer));
    if (sha(buffer) !== entry.after.fileSha256) errors.push(`${entry.mapId}: hash de archivo no coincide`);
    if (tableHash(parsed.table) !== entry.after.tileSha256) errors.push(`${entry.mapId}: hash de geometría no coincide`);
    for (const change of entry.changes) if (tableGet(parsed.table, change.x, change.y, change.layer) !== change.newTileId) errors.push(`${entry.mapId}: celda ${change.x},${change.y} perdió el acento visual`);
    if (!parsed.events.some(({ obj }) => parseEvent(obj).name === "Return to Puerto Horizonte")) errors.push(`${entry.mapId}: retorno ausente`);
    if (parsed.events.filter(({ obj }) => parseEvent(obj).name.startsWith("PokeMod Tier1:")).length !== 5) errors.push(`${entry.mapId}: eventos Tier 1 incompletos`);
  }
  if (report.maps.length !== 15) errors.push(`macrociclo incompleto: ${report.maps.length}/15 mapas`);
  if (report.summary.visualBatches !== 3) errors.push(`lotes incorrectos: ${report.summary.visualBatches}/3`);
  if (errors.length) throw new Error(`Macrociclo visual inválido (${errors.length}):\n- ${errors.join("\n- ")}`);
  console.log(`Verificación OK: ${report.summary.visualBatches} lotes visuales, ${report.maps.length} anclas y ${report.summary.changedCells} celdas narrativas; pasabilidad, eventos y retorno preservados.`);
}

if (VERIFY_ONLY) {
  if (!fs.existsSync(OUTPUT)) throw new Error("Falta content/atlas_visual_polish_macro02.json.");
  verify(JSON.parse(fs.readFileSync(OUTPUT, "utf8")));
} else if (fs.existsSync(OUTPUT)) {
  const previous = JSON.parse(fs.readFileSync(OUTPUT, "utf8"));
  const allCurrent = previous.maps.every((entry) => {
    const file = path.join(DATA, mapFile(entry.mapId));
    return fs.existsSync(file) && sha(fs.readFileSync(file)) === entry.after.fileSha256;
  });
  if (!allCurrent) throw new Error("Ya existe un manifiesto del macrociclo, pero los mapas no coinciden. Restaura el backup o revisa el diff antes de reaplicar.");
  verify(previous);
} else {
  backupFiles();
  const maps = CONFIGS.map(applyMap);
  const report = {
    version: 1,
    macroCycle: 2,
    scope: {
      visualBatches: [6,7,8],
      sectors: [26,40],
      maps: maps.map((entry) => entry.mapId),
      method: "Composición de piso narrativa con tiles existentes y equivalencia estricta de colisión.",
    },
    summary: {
      visualBatches: 3,
      maps: maps.length,
      changedCells: maps.reduce((sum, entry) => sum + entry.changedCells, 0),
      exactPatternPlacements: maps.filter((entry) => !entry.usedFallbackPlacement).length,
      adaptivePatternPlacements: maps.filter((entry) => entry.usedFallbackPlacement).length,
      eventsMoved: 0,
      passabilityChangedCells: 0,
      inheritedGeometryRemainingAfterStyleGate: 0,
    },
    certification: {
      staticTechnicalGate: "required",
      gameExePreview: "required",
      playableArtCertified: false,
      note: "Los PNG de referencia permiten crítica estática, pero no sustituyen ritmo, clipping ni prueba visual dentro de Game.exe.",
    },
    maps,
  };
  fs.writeFileSync(OUTPUT, `${JSON.stringify(report, null, 2)}\n`);
  verify(report);
  console.log(`Macrociclo visual 02 aplicado. Backup: ${path.relative(ROOT, BACKUP)}`);
}// ============================================================================
// apply_badge_viewer.mjs
// ----------------------------------------------------------------------------
// Visor de medallas región por región en la información del jugador, como el
// de las regiones base de Fire Ash pero extendido a las regiones nuevas:
//
//   filas 0-8  : regiones base (Kanto…Orange), ya cableadas por el juego con
//                $Trainer.badges[region*8+i].
//   fila  9    : Glazed            (medallas en la Mochila)
//   fila 10    : Light Platinum    (medallas en la Mochila)
//   fila 11    : Liquid Crystal    (medallas en la Mochila)
//   fila 12    : Creepypastas      (sellos de los 8 jefes del multiverso,
//                                   switches 940-947)
//   fila 13    : Dimensión Atlas   (las 8 medallas de elemento ATLAS*)
//   fila 14    : Ciudad Teckel     (Medalla Pata)
//
// En la Tarjeta de Entrenador, ◀/▶ cambian de región y la hoja de iconos
// icon_badges.png se extiende de 9 a 15 filas con emblemas nuevos.
//
//   node tools/apply_badge_viewer.mjs            # aplica
//   node tools/apply_badge_viewer.mjs --verify   # solo comprueba
// ============================================================================

import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import {
  ROOT, GAME, marshalLoad, marshalDump, RString, installItems, makeChecker,
} from "./lib/dlc_helpers.mjs";
import { badgeRowCanvas, REGION_PALETTES } from "./lib/badge_icons.mjs";
import { patchedCard } from "./lib/card_patch.mjs";

const VERIFY = process.argv.includes("--verify");
const ROWS = 15;
const SHEET = path.join(GAME, "Graphics", "Pictures", "Trainer Card", "icon_badges.png");

const SCRIPT_TARGETS = [
  "pokemon_fire_ash/Data/Scripts.rxdata",
  "Scripts_corregido/Scripts.rxdata",
  "Scripts_corregido/Paquete_directo/Data/Scripts.rxdata",
  "Scripts_corregido/Dimensional_Nightmare_QA/Data/Scripts.rxdata",
];

/* ───────────────────────────── código Ruby ─────────────────────────────── */

const REGISTRY_RUBY = `# ==============================================================================
# PokeMod_BadgeRegions — registro de regiones de medallas del visor.
# ==============================================================================
module PokeModBadgeRegions
  ROWS = ${ROWS}
  BASE_NAMES = ["Kanto", "Johto", "Hoenn", "Sinnoh", "Unova", "Kalos", "Alola", "Galar", "Orange"]
  REGIONS = {
    9  => ["Glazed", :items, [:GLAZEDBADGE, :GLAZEDBADGE2, :GLAZEDBADGE3, :GLAZEDBADGE4, :GLAZEDBADGE5, :GLAZEDBADGE6, :GLAZEDBADGE7, :GLAZEDBADGE8]],
    10 => ["Light Platinum", :items, [:PLATINUMBADGE, :PLATINUMBADGE2, :PLATINUMBADGE3, :PLATINUMBADGE4, :PLATINUMBADGE5, :PLATINUMBADGE6, :PLATINUMBADGE7, :PLATINUMBADGE8]],
    11 => ["Liquid Crystal", :items, [:CRYSTALBADGE, :CRYSTALBADGE2, :CRYSTALBADGE3, :CRYSTALBADGE4, :CRYSTALBADGE5, :CRYSTALBADGE6, :CRYSTALBADGE7, :CRYSTALBADGE8]],
    12 => ["Creepypastas", :switches, [940, 941, 942, 943, 944, 945, 946, 947]],
    13 => ["Dimensión Atlas", :items, [:ATLASBRUMABADGE, :ATLASVETABADGE, :ATLASDUNABADGE, :ATLASFRAGUABADGE, :ATLASMAREABADGE, :ATLASVENTABADGE, :ATLASFLORABADGE, :ATLASCHISPABADGE]],
    14 => ["Ciudad Teckel", :items, [:TECKELBADGE]],
  }

  def self.region_name(r)
    return BASE_NAMES[r] if r <= 8
    meta = REGIONS[r]
    return meta ? meta[0] : "Región #{r + 1}"
  end

  def self.owned?(r, i)
    if r <= 8
      return ($Trainer && $Trainer.badges[i + r * 8]) ? true : false
    end
    meta = REGIONS[r]
    return false if !meta
    key = meta[2][i]
    return false if key.nil?
    if meta[1] == :switches
      return $game_switches ? !!$game_switches[key] : false
    end
    return pbHasItem?(key)
  end
end
`;

/* El código de la tarjeta vive en tools/lib/card_patch.mjs (parche del original). */

/* ─────────────────────────────── hoja de iconos ────────────────────────── */

async function extendSheet() {
  const image = await loadImage(SHEET);
  if (image.height >= ROWS * 48) return false;
  const canvas = createCanvas(384, ROWS * 48);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(image, 0, 0);
  const rows = [
    [9, REGION_PALETTES.glazed], [10, REGION_PALETTES.platinum], [11, REGION_PALETTES.crystal],
    [12, REGION_PALETTES.creepy], [13, REGION_PALETTES.atlas], [14, REGION_PALETTES.teckel],
  ];
  for (const [row, pal] of rows) {
    ctx.drawImage(badgeRowCanvas(pal), 0, row * 48);
  }
  fs.writeFileSync(SHEET, canvas.toBuffer("image/png"));
  return true;
}

/* ─────────────────────────── scripts (4 archivos) ──────────────────────── */

function codeOf(entry) {
  const b = Buffer.from(entry[2].bytes);
  return (b[0] === 0x78 && b[1] === 0x9c ? zlib.inflateSync(b) : b).toString("utf8");
}
function setCode(entry, text) {
  entry[2].bytes = new Uint8Array(zlib.deflateSync(Buffer.from(text, "utf8")));
}

function patchScripts(file) {
  const scripts = marshalLoad(fs.readFileSync(path.join(ROOT, file)));
  let changed = 0;

  const card = scripts.find((e) => (e[1].text ?? String(e[1])) === "UI_TrainerCard");
  if (!card) throw new Error(`${file}: sin sección UI_TrainerCard`);
  const cardCode = codeOf(card);
  if (!cardCode.includes("PokeModBadgeRegions") || !cardCode.includes("PokemonTrainerCardScreen")) {
    setCode(card, patchedCard());
    changed++;
  }

  const mainIdx = scripts.findIndex((e) => (e[1].text ?? String(e[1])) === "Main");
  const existing = scripts.findIndex((e) => (e[1].text ?? String(e[1])) === "PokeMod_BadgeRegions");
  if (existing >= 0) {
    if (!codeOf(scripts[existing]).includes("ROWS = 15")) { setCode(scripts[existing], REGISTRY_RUBY); changed++; }
  } else {
    const entry = [99971, RString.fromText("PokeMod_BadgeRegions"), new RString("")];
    setCodeFromEntry(entry);
    scripts.splice(mainIdx, 0, entry);
    changed++;
  }
  if (changed) fs.writeFileSync(path.join(ROOT, file), Buffer.from(marshalDump(scripts)));
  return changed;
}
function setCodeFromEntry(entry) {
  entry[2].bytes = new Uint8Array(zlib.deflateSync(Buffer.from(REGISTRY_RUBY, "utf8")));
}

/* ────────────────────────────────── apply ──────────────────────────────── */

async function apply() {
  const sheetChanged = await extendSheet();
  console.log(sheetChanged ? "✔ icon_badges.png extendido a 15 filas" : "· icon_badges.png ya tenía 15 filas");

  installItems([
    ...[2, 3, 4, 5, 6, 7, 8].map((n) => ({ id: `GLAZEDBADGE${n}`, base: "GLAZEDBADGE", nombre: `Medalla Glazed ${["", "", "II", "III", "IV", "V", "VI", "VII", "VIII"][n]}` })),
    ...[2, 3, 4, 5, 6, 7, 8].map((n) => ({ id: `PLATINUMBADGE${n}`, base: "PLATINUMBADGE", nombre: `Medalla Platinum ${["", "", "II", "III", "IV", "V", "VI", "VII", "VIII"][n]}` })),
    ...[2, 3, 4, 5, 6, 7, 8].map((n) => ({ id: `CRYSTALBADGE${n}`, base: "CRYSTALBADGE", nombre: `Medalla Crystal ${["", "", "II", "III", "IV", "V", "VI", "VII", "VIII"][n]}` })),
  ], "badge_viewer");

  for (const target of SCRIPT_TARGETS) {
    const n = patchScripts(target);
    console.log(`✔ ${target}: ${n} secciones actualizadas`);
  }

  // items.dat del juego es superconjunto de los paquetes: sincronizar copias.
  for (const pkg of ["Paquete_directo", "Dimensional_Nightmare_QA", "Expansion_Multiversal", "Ciudad_Teckel_Paraiso"]) {
    fs.copyFileSync(path.join(GAME, "Data/items.dat"), path.join(ROOT, "Scripts_corregido", pkg, "Data/items.dat"));
  }

  // La hoja extendida también en las carpetas de los paquetes.
  for (const dst of [
    path.join(ROOT, "Scripts_corregido/Paquete_directo/Graphics/Pictures/Trainer Card/icon_badges.png"),
    path.join(ROOT, "Scripts_corregido/Dimensional_Nightmare_QA/Graphics/Pictures/Trainer Card/icon_badges.png"),
  ]) {
    fs.mkdirSync(path.dirname(dst), { recursive: true });
    fs.copyFileSync(SHEET, dst);
  }
  console.log("OK: visor de medallas región por región instalado");
}

function verify() {
  const check = makeChecker("visor de medallas");
  const size = fs.readFileSync(SHEET);
  check.ok(size.readUInt32BE(20) >= ROWS * 48, `la hoja sigue midiendo ${size.readUInt32BE(20)}px de alto`);
  const items = marshalLoad(fs.readFileSync(path.join(GAME, "Data/items.dat")));
  for (const sym of ["GLAZEDBADGE8", "PLATINUMBADGE8", "CRYSTALBADGE8"]) {
    check.ok(items.pairs.some(([k]) => (k?.name ?? "") === sym), `falta el objeto ${sym}`);
  }
  for (const target of SCRIPT_TARGETS) {
    const scripts = marshalLoad(fs.readFileSync(path.join(ROOT, target)));
    const reg = scripts.find((e) => (e[1].text ?? "") === "PokeMod_BadgeRegions");
    const card = scripts.find((e) => (e[1].text ?? "") === "UI_TrainerCard");
    check.ok(!!reg && codeOf(reg).includes("ROWS = 15"), `${target}: falta el registro de regiones`);
    const cc = card ? codeOf(card) : "";
    check.ok(!!card && cc.includes("PokeModBadgeRegions") && cc.includes("PokemonTrainerCardScreen") && cc.includes("pbEndScene"), `${target}: la tarjeta no usa el visor`);
  }
  for (const pkg of ["Paquete_directo", "Dimensional_Nightmare_QA", "Expansion_Multiversal", "Ciudad_Teckel_Paraiso"]) {
    const same = fs.readFileSync(path.join(ROOT, "Scripts_corregido", pkg, "Data/items.dat")).equals(fs.readFileSync(path.join(GAME, "Data/items.dat")));
    check.ok(same, `${pkg}/Data/items.dat desactualizado frente al del juego`);
  }
  check.done();
}

if (VERIFY) verify();
else { await apply(); verify(); }#!/usr/bin/env node
/**
 * apply_cajas_dialogo.mjs
 *
 * Diálogos · «Los diálogos no se deben solapar; cada personaje debe tener su
 * propia caja de diálogo.»
 *
 * Inyecta la sección Ruby `PokeMod_Dialogos` en los Scripts.rxdata del juego y
 * del paquete descargable. La sección:
 *
 *   1. **Caja por personaje.** Cada mensaje puede salir en su propia caja de
 *      diálogo identificada por el nombre del hablante:
 *        · Texto con prefijo `Nombre: …` / `Nombre — …` (retroactivo con todos
 *          los diálogos del DLC que ya usan «Arceus: «…»»).
 *        · Etiqueta explícita `\sp[Nombre]` al inicio del mensaje.
 *        · Si el mensaje lo dispara un evento y su nombre parece el de un
 *          personaje (solo letras/espacios), la caja lleva ese nombre.
 *   2. **Anti-solape.** Los mensajes se serializan: nunca se dibujan dos cajas
 *      de texto a la vez (cola con límite de tiempo: el juego jamás se cuelga).
 *   3. **Combate.** Los mensajes de batalla (`pbDisplayMessage` /
 *      `pbDisplayPausedMessage`) también llevan caja del hablante y respetan
 *      la misma regla de no solape.
 *
 * Uso:
 *   node tools/apply_cajas_dialogo.mjs           # inyecta y verifica
 *   node tools/apply_cajas_dialogo.mjs --verify  # solo verifica
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const TITULO = "PokeMod_Dialogos";
const DIR = "cajas_dialogo";
const RUBY = fs.readFileSync(new URL("./lib/pokemod_dialogos.rb", import.meta.url), "utf8");


const SCRIPTS = [
  path.join(GAME, "Data", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Scripts.rxdata"),
];

function inyectar(archivo) {
  const scripts = marshalLoad(fs.readFileSync(archivo));
  const comprimido = zlib.deflateSync(Buffer.from(RUBY, "utf-8"));
  const idx = scripts.findIndex(([, t]) => t && t.text === TITULO);
  if (idx >= 0) scripts[idx][2] = new RString(comprimido);
  else scripts.splice(scripts.length - 1, 0, [999902, RString.fromText(TITULO), new RString(comprimido)]);
  // Mantener la paridad de secciones juego/paquete: el título debe ser S() como
  // el resto de secciones (RString con encoding UTF-8).
  fs.writeFileSync(archivo, Buffer.from(marshalDump(scripts)));
  return idx >= 0;
}

function respaldo(archivo) {
  const dir = path.join(GAME, "PokeModBackups", DIR);
  fs.mkdirSync(dir, { recursive: true });
  const bak = path.join(dir, path.basename(archivo) + "." + path.basename(path.dirname(archivo)));
  if (!fs.existsSync(bak)) fs.copyFileSync(archivo, bak);
}

function verificar() {
  const fallos = [];
  const esperados = [
    "module PokeModDialogos",
    "def self.dividir",
    "def self.cajaDeNombre",
    "pokemod_orig_pbMessageDisplay",
    "pokemod_orig_pbCreateMessageWindow",
    "pokemod_orig_pbDisplayPausedMessage",
    "alias pbDisplayPaused pbDisplayPausedMessage",
  ];
  const conteos = [];
  for (const archivo of SCRIPTS) {
    if (!fs.existsSync(archivo)) { fallos.push(`falta ${archivo}`); continue; }
    const scripts = marshalLoad(fs.readFileSync(archivo));
    conteos.push(scripts.length);
    const seccion = scripts.find(([, t]) => t && t.text === TITULO);
    if (!seccion) { fallos.push(`${path.basename(path.dirname(archivo))}/${path.basename(archivo)}: falta ${TITULO}`); continue; }
    const ruby = zlib.inflateSync(Buffer.from(seccion[2].bytes)).toString("utf8");
    for (const marca of esperados) if (!ruby.includes(marca)) fallos.push(`${archivo}: falta la marca «${marca}»`);
  }
  if (conteos.length === 2 && conteos[0] !== conteos[1]) {
    fallos.push(`Scripts.rxdata tiene ${conteos[0]} secciones y el paquete ${conteos[1]} (paridad rota)`);
  }
  return fallos;
}

if (!VERIFY_ONLY) {
  for (const archivo of SCRIPTS) {
    if (!fs.existsSync(archivo)) { console.warn(`WARN: ${archivo} no existe; omitido.`); continue; }
    respaldo(archivo);
    const existia = inyectar(archivo);
    console.log(`· ${path.relative(ROOT, archivo)}: ${TITULO} ${existia ? "actualizado" : "inyectado"}.`);
  }
}
const fallos = verificar();
if (fallos.length) {
  console.error("FALLOS:\n" + fallos.map((f) => "  · " + f).join("\n"));
  process.exit(1);
}
console.log("OK: cajas de diálogo por personaje instaladas; mensajes serializados (sin solapes).");#!/usr/bin/env node
/**
 * apply_canon_arceus.mjs
 *
 * Canon: **el duelo de La Ruta de Dios es el origen de todo lo que viene
 * después.** El mundo creepypasta, Atlas Mil, la Isla Espejo con los Pokégods
 * y los Fragmentos de dimensión (Glazed, Light Platinum y Team Rocket) son
 * astillas del golpe que Arceus abrió al caer.
 *
 * Por eso esta herramienta hace cuatro cosas:
 *
 *   1. Cierra las puertas. Ningún acceso posterior responde si el duelo no
 *      está resuelto (switch 873). Las puertas conservan su condición
 *      original (postgame, cronista, etc.) y le suman la del duelo.
 *   2. Coloca el **Fragmento del Génesis** en la cumbre: la astilla que
 *      Arceus suelta al caer. Al recogerla despierta el **Rotom del Tiempo**
 *      (switch 883), que es quien sostiene abiertas las grietas.
 *   3. Planta un **Rotom del Tiempo** junto a cada puerta: explica por qué
 *      algo está cerrado y, cuando procede, lo abre en la ficción.
 *   4. Si Arceus fue **capturado** (switch 874), aparece en los momentos
 *      ligeros: los diálogos de Oak sobre las dimensiones y el choque contra
 *      el Mad Pikachu.
 *
 * Además inyecta `PokeMod_CanonArceus`, que convierte el combate en un duelo
 * contra un dios: cada fase doblega una regla distinta del juego (mochila
 * sellada, clima, silencio de habilidades, lógica invertida, tablillas y, al
 * final, sus propias reglas), con efectos en pantalla y movimientos que
 * encarnan cada mecánica.
 *
 * Uso:
 *   node tools/apply_canon_arceus.mjs
 *   node tools/apply_canon_arceus.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";
import { ROOT, GAME, DATA } from "./lib/fire_ash_registry.mjs";
import {
  S, txt, mapFile, readData, writeData, readMap, writeMap,
  cmd, condition, graphic, page, event, texts, script, selfSwitch,
  grid, nearestFreeCell, upsertEvents,
} from "./lib/dn_rmxp.mjs";

const CFG = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "canon_arceus.json"), "utf8"));
const VERIFY = process.argv.includes("--verify");
const SW = CFG.interruptores;
const BACKUP = path.join(GAME, "PokeModBackups", "canon_arceus");

const MARKER = "PokeMod Canon:";
const RESPALDO = path.join(GAME, "PokeModBackups", "canon_arceus");

/** Copia de seguridad propia: el canon toca mapas y Scripts de otras herramientas. */
function respaldo(archivo) {
  fs.mkdirSync(RESPALDO, { recursive: true });
  const origen = path.join(DATA, archivo);
  const copia = path.join(RESPALDO, archivo);
  if (fs.existsSync(origen) && !fs.existsSync(copia)) fs.copyFileSync(origen, copia);
}

/* ────────────────────────────────── Ruby ───────────────────────────────── */

const rubyStr = (texto) => String(texto).replace(/\\/g, "\\\\").replace(/"/g, "'");

const FASES_RUBY = Object.entries(CFG.fases_dios)
  .map(([fase, datos]) => {
    const movs = (datos.movimientos || []).map((m) => `:${m}`).join(", ");
    const partes = [
      `:movs => [${movs}]`,
      `:efecto => :${datos.efecto}`,
      `:msg => "${rubyStr(datos.mensaje)}"`,
      `:concepto => "${rubyStr(datos.concepto)}"`,
      `:cartel => "${rubyStr(datos.cartel)}"`,
      `:linea => "${rubyStr(datos.linea_meta)}"`,
    ];
    return `    ${fase} => { ${partes.join(", ")} },`;
  })
  .join("\n");

/** Bloques de diálogo de la cuarta pared, como constantes Ruby. */
const DIALOGO_RUBY = Object.entries(CFG.meta)
  .filter(([, valor]) => Array.isArray(valor))
  .map(([clave, lineas]) => {
    const items = lineas.map((l) => `    "${rubyStr(l)}",`).join("\n");
    return `  ${clave.toUpperCase()} = [\n${items}\n  ]`;
  })
  .join("\n");

const RUBY = `#===============================================================================
# PokeMod_CanonArceus
#
# Canon: el duelo de La Ruta de Dios es el origen de todas las dimensiones.
# Sin Arceus caido no existen las grietas, ni Atlas Mil, ni la Isla Espejo con
# sus Pokegods, ni los Fragmentos de Glazed, Light Platinum y Team Rocket.
#===============================================================================
module CanonArceus
  SW_DUELO      = ${SW.DUELO_RESUELTO}
  SW_CAPTURADO  = ${SW.ARCEUS_CAPTURADO}
  SW_COMPLETADO = ${SW.EVENTO_COMPLETADO}
  SW_FRAGMENTO  = ${SW.FRAGMENTO_GENESIS}
  SW_ROTOM      = ${SW.ROTOM_TIEMPO}
  SW_SELLO      = ${SW.SELLO_MOCHILA}

  # Cada fase doblega una regla distinta del combate: el dios no solo pega,
  # reescribe el sistema. Y cada fase BORRA UN CONCEPTO: no cambia el terreno,
  # cambia lo que significa jugar.
  FASES = {
${FASES_RUBY}
  }

  def self.sw(id)
    return false if !$game_switches
    $game_switches[id] ? true : false
  end

  def self.duelo_resuelto?
    sw(SW_DUELO) || sw(SW_CAPTURADO)
  end

  def self.capturado?
    sw(SW_CAPTURADO)
  end

  def self.fragmento?
    sw(SW_FRAGMENTO)
  end

  # El Rotom del Tiempo solo sostiene la herida si Arceus cayo y solto su astilla.
  def self.rotom_activo?
    duelo_resuelto? && fragmento?
  end

  # La astilla que Arceus suelta al caer despierta al Rotom del Tiempo.
  def self.entregar_fragmento
    return if !$game_switches
    $game_switches[SW_FRAGMENTO] = true
    $game_switches[SW_ROTOM] = true
  end

  # Puerta canonica: ninguna dimension responde antes del duelo.
  def self.puerta(lugar)
    if !duelo_resuelto?
      pbMessage(_INTL("La herida del Genesis sigue abierta."))
      pbMessage(_INTL("Nada de esto existe mientras Arceus no caiga en La Ruta de Dios."))
      return false
    end
    if !rotom_activo?
      pbMessage(_INTL("El Rotom del Tiempo aun no despierta: le falta el Fragmento del Genesis."))
      pbMessage(_INTL("Esta en la cumbre de La Ruta de Dios, donde Arceus cayo."))
      return false
    end
    pbMessage(_INTL("El Rotom del Tiempo sostiene la grieta de {1}.", lugar.to_s))
    pbMessage(_INTL("Puedes entrar y volver cuando quieras: la herida te obedece a ti."))
    return true
  end

  def self.movimientos_para(fase)
    datos = FASES[fase]
    return [] if !datos
    datos[:movs] || []
  end

  # Efectos de "dios" sobre la propia partida: el combate deja de ser un sitio
  # seguro y pasa a ser una habitacion donde las reglas las pone otro.
  # Arceus habla como quien sabe que esto es un juego: porque lo sabe.
  module Meta
${DIALOGO_RUBY}

    def self.hablar(lineas, battle = nil)
      (lineas || []).each do |linea|
        begin
          if battle && battle.respond_to?(:pbDisplayPaused)
            battle.pbDisplayPaused(_INTL(linea.to_s))
          else
            pbMessage(_INTL(linea.to_s))
          end
        rescue StandardError
        end
      end
    end
  end

  def self.efecto_fase(battle, battler, fase)
    datos = FASES[fase]
    return if !datos
    # 1. El cartel: el dios anuncia qué concepto deja de existir.
    begin
      battle.pbDisplay(_INTL("\\n" + datos[:cartel].to_s)) if battle && battle.respond_to?(:pbDisplay)
    rescue StandardError
    end
    # 2. La voz: se lo dice a Ash mirando al jugador, no al Pokémon.
    Meta.hablar([datos[:linea]], battle)
    # 3. El efecto clásico de la fase.
    begin
      battle.pbDisplay(_INTL(datos[:msg].to_s)) if battle && battle.respond_to?(:pbDisplay)
    rescue StandardError
    end
    begin
      case datos[:efecto]
      when :sello
        # Concepto borrado: OBJETO. La mochila deja de existir aqui dentro.
        paso { $game_switches[SW_SELLO] = true if $game_switches }
        paso { campo(battle, :MagicRoom, 5) }
      when :clima
        # Concepto borrado: CIELO (y, con el, el de volar).
        paso { batalla_clima(battle, fase) }
        paso { campo(battle, :Gravity, 5) }
      when :talento
        # Concepto borrado: TALENTO y SUERTE. Sin habilidades y sin criticos.
        paso { silenciar_habilidades(battle, battler) }
        paso { campo(battle, :MagicRoom, 5) }
        paso { canto_de_suerte(battle, battler) }
        paso { $game_screen.start_tone_change(Tone.new(-70, -70, -70, 0), 20) if $game_screen }
      when :velocidad
        # Concepto borrado: VELOCIDAD (y, con ella, el de resistencia).
        paso { campo(battle, :TrickRoom, 5) }
        paso { campo(battle, :WonderRoom, 5) }
        paso { $game_screen.start_shake(8, 6, 20) if $game_screen }
      when :tipo
        # Concepto borrado: TIPO.
        paso { cambiar_tablero(battler, fase) }
        paso { $game_screen.start_flash(Color.new(255, 255, 255, 200), 12) if $game_screen }
      when :regla
        # Concepto borrado: REGLA. Ya no queda nada que respetar.
        paso { cambiar_tablero(battler, fase) }
        paso { batalla_clima(battle, fase) }
        paso { canto_de_suerte(battle, battler) }
        paso { $game_screen.start_flash(Color.new(255, 240, 200, 255), 20) if $game_screen }
        paso { $game_screen.start_tone_change(Tone.new(60, -40, -40, 0), 30) if $game_screen }
      end
    rescue StandardError
    end
    # R11: la fase termina con el campo saneado pase lo que pase en cada paso:
    # ninguna fase puede dejar clima/terreno inválidos ni PS imposibles.
    paso { verificar_fase(battle, battler) }
    # El dios se recompone un poco al romper cada regla: no se gana por desgaste.
    begin
      if battler && battler.respond_to?(:totalhp) && battler.hp < battler.totalhp
        extra = (battler.totalhp * 0.10).floor
        battler.pbRecoverHP(extra) if battler.respond_to?(:pbRecoverHP)
      end
    rescue StandardError
    end
  end

  # Borra las habilidades del lado rival mientras dure la fase: lo que tus
  # Pokemon sabian hacer ya no esta escrito en ninguna parte.
  def self.silenciar_habilidades(battle, battler)
    return if !battle || !battle.respond_to?(:battlers)
    # R10: el silencio de talentos usa el efecto real del motor (Bilis Negra /
    # Gastro Acid) en vez de borrar el talento del battler: asi el silencio es
    # temporal, visible y respetado por todas las rutas de habilidad del motor.
    constante = nil
    begin
      constante = PBEffects.const_get(:GastroAcid) if defined?(PBEffects)
    rescue StandardError
      constante = nil
    end
    return if !constante
    (battle.battlers || []).each do |otro|
      next if !otro || !otro.respond_to?(:fainted?)
      next if otro.fainted?
      next if !otro.respond_to?(:opposes?) || !otro.opposes?(battler)
      next if !otro.respond_to?(:effects)
      otro.effects[constante] = true
    end
  rescue StandardError
  end

  # "Borra el concepto de suerte": nadie golpea a Arceus en el punto debil.
  # El velo sagrado es un efecto real por lado del motor de combate.
  def self.canto_de_suerte(battle, battler)
    return if !battle || !defined?(PBEffects)
    constante = PBEffects.const_get(:LuckyChant) rescue nil
    return if !constante
    indice = nil
    begin
      indice = battler.index if battler && battler.respond_to?(:index)
    rescue StandardError
    end
    return if !indice
    lado = (indice % 2)
    arreglo = battle.respond_to?(:sides) ? battle.sides[lado] : nil
    arreglo = battle.field if !arreglo || !arreglo.respond_to?(:effects)
    return if !arreglo || !arreglo.respond_to?(:effects)
    arreglo.effects[constante] = 5
  rescue StandardError
  end

  # Activa un efecto de campo real del combate (si el motor lo conoce).
  def self.campo(battle, efecto, turnos)
    return if !battle || !defined?(PBEffects)
    constante = PBEffects.const_get(efecto) rescue nil
    return if !constante
    campo_batalla = battle.field if battle.respond_to?(:field)
    return if !campo_batalla || !campo_batalla.respond_to?(:effects)
    campo_batalla.effects[constante] = turnos
  rescue StandardError
  end

  # Arceus cambia de tablilla: su Juicio cambia de tipo sin previo aviso.
  def self.cambiar_tablero(battler, fase)
    return if !battler
    # La ruleta adaptativa de la Ruta de Dios ya asignó el tipo y el objeto
    # ventajosos en pantalla; no la pises con la tablilla fija del canon.
    if battler.respond_to?(:battle) && battler.battle && battler.battle.respond_to?(:pbArceusBestPlateIndex)
      return
    end
    tablillas = [:FLAMEPLATE, :SPLASHPLATE, :ZAPPLATE, :MEADOWPLATE, :ICICLEPLATE,
                 :FISTPLATE, :TOXICPLATE, :EARTHPLATE, :SKYPLATE, :MINDPLATE,
                 :INSECTPLATE, :STONEPLATE, :SPOOKYPLATE, :DRACOPLATE, :DREADPLATE,
                 :IRONPLATE, :PIXIEPLATE]
    tablilla = tablillas[(fase * 5) % tablillas.length]
    return if !battler.respond_to?(:item=)
    begin
      battler.item = tablilla
      battle_msg = "La tablilla cambia: el Juicio de Arceus ya no es el de antes."
      battler.battle.pbDisplay(_INTL(battle_msg)) if battler.battle.respond_to?(:pbDisplay)
    rescue StandardError
    end
  end

  # R11 — Cada sub-efecto de una fase corre con su propio escudo: un error en
  # un paso ya no aborta el resto de la fase (antes un solo raise dejaba la
  # fase entera a medias y en silencio).
  def self.paso
    yield
  rescue StandardError
    nil
  end

  # R11 — Cierre de fase: el campo queda saneado y los PS en rangos posibles,
  # aunque alguno de los pasos haya fallado o algún mod externo escriba basura.
  def self.verificar_fase(battle, battler)
    return if !battle
    RutaCampoSeguro.sanitizar!(battle)
    return if !battle.respond_to?(:battlers)
    (battle.battlers || []).each do |otro|
      next if !otro || !otro.respond_to?(:totalhp) || !otro.respond_to?(:hp)
      total = otro.totalhp.to_i
      next if total <= 0
      if otro.hp.to_i < 0
        otro.ruta_arceus_scripted_hp_write { otro.hp = 0 } if otro.respond_to?(:ruta_arceus_scripted_hp_write)
      elsif otro.hp.to_i > total
        otro.ruta_arceus_scripted_hp_write { otro.hp = total } if otro.respond_to?(:ruta_arceus_scripted_hp_write)
      end
    end
  rescue StandardError
    nil
  end

  def self.batalla_clima(battle, fase)
    return if !battle
    # R10: el clima de v19 es un simbolo de GameData::BattleWeather, nunca un
    # movimiento ni una duracion. La llamada antigua pasaba el simbolo de un
    # movimiento como usuario y el numero 5 como clima: el campo quedaba con
    # weather = 5 y el fin de ronda reventaba con ArgumentError en Kirin
    # ("Expected 5 to be one of [Symbol, GameData::BattleWeather, String]").
    campo = battle.respond_to?(:field) ? battle.field : nil
    return if !campo || !campo.respond_to?(:weather=)
    climas = [:Rain, :Sun, :Sandstorm, :Hail, :Fog]
    clima = climas[fase.to_i % climas.length]
    return if !RutaCampoSeguro.clima_valido?(clima)
    if battle.respond_to?(:pbStartWeather)
      battle.pbStartWeather(nil, clima, true, true, 5)
    else
      campo.weather = clima
      campo.weatherDuration = 5 if campo.respond_to?(:weatherDuration=)
    end
  rescue StandardError
    begin
      RutaCampoSeguro.sanitizar!(battle)
    rescue StandardError
    end
  end
end

# Arceus incorpora a cada fase los movimientos que encarnan su mecanica:
# siembra el clima que va a invocar, silencia, invierte, roba o reescribe.
if defined?(RUTA_ARCEUS_MOVE_SETS)
  begin
    RUTA_ARCEUS_MOVE_SETS.each_with_index do |set, i|
      extra = CanonArceus.movimientos_para(i + 1)
      next if !extra || extra.empty?
      base = set.dup
      canon = extra.select { |move| GameData::Move.exists?(move) }.uniq
      # Pokémon::MAX_MOVES es cuatro. Combinar más rompe las estructuras del
      # menú y de la batalla, así que cada fase usa dos movimientos base y dos
      # temáticos (rellenando con el resto si alguno no existe).
      seleccion = (base.first(2) + canon.first(2) + base.drop(2) + canon.drop(2)).uniq
      set.replace(seleccion.take(Pokemon::MAX_MOVES))
    end
  rescue StandardError
  end
end

# ------------------------------------------------------------------------------
# ArceusMeta: la cuarta pared. Arceus sabe que esto es un juego, conoce el
# archivo de guardado, ve la mano que pulsa los botones y se lo dice a Ash
# Ketchum por su nombre completo. No es un adorno: cada linea va acompanada de
# un concepto que deja de existir de verdad en el combate.
# ------------------------------------------------------------------------------
module ArceusMeta
  def self.lineas(clave)
    CanonArceus::Meta.const_defined?(clave.to_s.upcase) ? CanonArceus::Meta.const_get(clave.to_s.upcase) : []
  rescue StandardError
    []
  end

  def self.decir(clave, battle = nil)
    CanonArceus::Meta.hablar(lineas(clave), battle)
  end

  # Apertura: se muestra una sola vez por combate, antes de sacar al Pokémon.
  def self.intro(battle)
    return if !battle
    battle.instance_variable_set(:@arceus_meta_ya_hablo, true)
    if CanonArceus.sw(CanonArceus::SW_COMPLETADO)
      decir("rematch", battle)
    else
      decir("intro", battle)
    end
  end

  # Cierre: el dios se despide como quien sabe que el archivo se puede volver
  # a cargar. 1 = victoria, 2 = derrota, 4 = captura. Se usa pbMessage de mapa
  # (sin ventana de combate) para no depender de que la escena siga viva.
  def self.cierre(battle, decision)
    return if !battle
    case decision
    when 1 then decir("victoria")
    when 2 then decir("derrota")
    when 4 then decir("capturado")
    end
  end
end

["PokeBattle_Battle", "Battle"].each do |nombre_clase|
  next if !Object.const_defined?(nombre_clase)
  clase = Object.const_get(nombre_clase)
  next if !clase

  # Apertura de la cuarta pared, solo en el combate divino.
  if clase.method_defined?(:pbStartBattleSendOut) && !clase.method_defined?(:arceus_meta_send_out_original)
    clase.class_eval do
      alias arceus_meta_send_out_original pbStartBattleSendOut

      def pbStartBattleSendOut(*args)
        begin
          divino = respond_to?(:arceus_divine?) && arceus_divine?
          ya = instance_variable_get(:@arceus_meta_ya_hablo)
          if divino && !ya
            salvaje = !respond_to?(:wildBattle?) || wildBattle?
            ArceusMeta.intro(self) if salvaje
          end
        rescue StandardError
        end
        arceus_meta_send_out_original(*args)
      end
    end
  end

  # Despedida: "carga la partida, yo sigo aqui".
  if clase.method_defined?(:pbEndOfBattle) && !clase.method_defined?(:arceus_meta_end_original)
    clase.class_eval do
      alias arceus_meta_end_original pbEndOfBattle

      def pbEndOfBattle(*args)
        begin
          if respond_to?(:arceus_divine?) && arceus_divine?
            ArceusMeta.cierre(self, args[0])
          end
        rescue StandardError
        end
        arceus_meta_end_original(*args)
      end
    end
  end
end

# Cada vez que una barra completa agota una etapa, el dios reescribe una regla del combate.
["PokeBattle_Battle", "Battle"].each do |nombre_clase|
  next if !Object.const_defined?(nombre_clase)
  clase = Object.const_get(nombre_clase)
  next if !clase
  next if !clase.method_defined?(:check_arceus_phase)
  next if clase.method_defined?(:canon_arceus_fase_original)
  clase.class_eval do
    alias canon_arceus_fase_original check_arceus_phase

    def check_arceus_phase(battler)
      antes = @arceus_phase
      canon_arceus_fase_original(battler)
      fase = @arceus_phase
      return if !fase || fase == antes
      return if !battler || !battler.pokemon
      return if battler.pokemon.species != :ARCEUS
      CanonArceus.efecto_fase(self, battler, fase)
    rescue StandardError
    end
  end
end

# ─────────────────────────────────────────────────────────────────────────────
# R10 — Red anti-error sobre el campo de batalla.
#
# El duelo reescribe reglas (clima, terreno, salas, talentos) y cualquier valor
# que el motor no conozca se convierte en un ArgumentError visible en plena
# batalla: el fin de ronda lee el campo con GameData::BattleWeather.try_get y
# un entero o un simbolo inexistente tumban el combate. Estos parches hacen
# que esa clase de fallo sea imposible, venga de donde venga:
#
#   1. Nada escribe un clima o terreno invalido: pbStartWeather y
#      defaultWeather= validan antes de tocar el campo.
#   2. Nada lee un campo sucio: cada fin de ronda sanitiza weather/terrain
#      antes de que el motor los consulte.
#   3. Si aun asi algo inesperado revienta dentro del fin de ronda, el error
#      se absorbe aqui (sanitizando otra vez) en vez de llegar al jugador.
# ─────────────────────────────────────────────────────────────────────────────
module RutaCampoSeguro
  def self.clima_invalido?(campo)
    return false if !campo || !campo.respond_to?(:weather)
    return false if !defined?(GameData::BattleWeather)
    GameData::BattleWeather.try_get(campo.weather).nil?
  rescue StandardError
    true
  end

  def self.terreno_invalido?(campo)
    return false if !campo || !campo.respond_to?(:terrain)
    return false if !defined?(GameData::Terrain)
    GameData::Terrain.try_get(campo.terrain).nil?
  rescue StandardError
    true
  end

  def self.clima_valido?(valor)
    return true if !defined?(GameData::BattleWeather)
    !GameData::BattleWeather.try_get(valor).nil?
  rescue StandardError
    false
  end

  def self.terreno_valido?(valor)
    return true if !defined?(GameData::Terrain)
    !GameData::Terrain.try_get(valor).nil?
  rescue StandardError
    false
  end

  def self.sanitizar!(battle)
    return if !battle
    campo = battle.respond_to?(:field) ? battle.field : nil
    return if !campo
    if clima_invalido?(campo)
      campo.weather = :None if campo.respond_to?(:weather=)
      campo.weatherDuration = 0 if campo.respond_to?(:weatherDuration=)
    end
    if terreno_invalido?(campo)
      campo.terrain = :None if campo.respond_to?(:terrain=)
    end
  rescue StandardError
  end
end

["PokeBattle_Battle", "Battle"].each do |nombre_clase|
  next if !Object.const_defined?(nombre_clase)
  clase = Object.const_get(nombre_clase)
  next if !clase
  next if clase.method_defined?(:ruta_clima_validado)
  clase.class_eval do
    def ruta_clima_validado
      true
    end
    if method_defined?(:pbStartWeather)
      alias ruta_pbStartWeather_original pbStartWeather
      def pbStartWeather(user, newWeather, fixedDuration = false, showAnim = true, customDuration = 5)
        return if !RutaCampoSeguro.clima_valido?(newWeather)
        ruta_pbStartWeather_original(user, newWeather, fixedDuration, showAnim, customDuration)
      end
    end
    if method_defined?(:defaultWeather=)
      alias ruta_default_weather_original defaultWeather=
      def defaultWeather=(value)
        return if !RutaCampoSeguro.clima_valido?(value)
        ruta_default_weather_original(value)
      end
    end
  end
end

if Object.const_defined?(:Battle_Phase_EndOfRound)
  clase_fin = Object.const_get(:Battle_Phase_EndOfRound)
  if clase_fin && clase_fin.method_defined?(:start_phase) && !clase_fin.method_defined?(:ruta_fin_ronda_seguro)
    clase_fin.class_eval do
      def ruta_fin_ronda_seguro
        true
      end
      alias ruta_fin_ronda_original start_phase
      def start_phase
        RutaCampoSeguro.sanitizar!(@battle)
        ruta_fin_ronda_original
      rescue StandardError
        # Ultimo muro: el fin de ronda nunca llega al jugador como cartel de
        # error. Se sanitiza el campo y la ronda siguiente arranca limpia.
        RutaCampoSeguro.sanitizar!(@battle)
      end
    end
  end
end

#===============================================================================
# R15c — Cinturón de la escena de objetivos: ningún combate (ni una manada de
# cuatro salvajes, ni cualquier redimensionado futuro) puede reventar el panel
# de objetivos. PokeBattle_SceneMenus:485 indexa [0,82,166][numButtons-1] y sóo
# sostiene hasta 3 botones por lado; con 4 devolvía nil y el resto era
# «nil can't be coerced into Integer». Se topa el tamaño visual a 3 botones.
#===============================================================================
if defined?(TargetMenuDisplay)
  class TargetMenuDisplay
    if !method_defined?(:ruta_safe_side_sizes_init)
      alias ruta_safe_side_sizes_init initialize
      def initialize(viewport, z, sideSizes)
        seguros = (sideSizes || [1, 1]).map do |n|
          n = n.to_i
          n = 3 if n > 3
          n = 1 if n < 1
          n
        end
        ruta_safe_side_sizes_init(viewport, z, seguros)
      end
    end
  end
end

`;

/* ───────────────────────────────── inyección ───────────────────────────── */

const TITULO = "PokeMod_CanonArceus";

/** Escribe la sección en un Scripts.rxdata concreto, antes de Main. */
function escribirSeccion(archivo) {
  const ruta = path.join(GAME, "Data", archivo);
  const scripts = fs.existsSync(ruta)
    ? marshalLoad(fs.readFileSync(ruta))
    : marshalLoad(fs.readFileSync(path.join(ROOT, archivo)));
  const comprimido = zlib.deflateSync(Buffer.from(RUBY, "utf-8"));
  const idx = scripts.findIndex(([, t]) => t && t.text === TITULO);
  if (idx >= 0) scripts[idx][2] = new RString(comprimido);
  else scripts.splice(scripts.length - 1, 0, [scripts.length + 1, S(TITULO), new RString(comprimido)]);
  const destino = fs.existsSync(ruta) ? ruta : path.join(ROOT, archivo);
  fs.writeFileSync(destino, Buffer.from(marshalDump(scripts)));
  return idx >= 0;
}

function inyectarRuby() {
  respaldo("Scripts.rxdata");
  const existia = escribirSeccion("Scripts.rxdata");
  // El paquete descargable lleva su propio Scripts.rxdata con nueve correcciones
  // de estabilidad: el canon tiene que viajar también ahí, en la misma posición.
  const corregido = path.join(ROOT, "Scripts_corregido", "Scripts.rxdata");
  let descargable = null;
  if (fs.existsSync(corregido)) descargable = escribirSeccion(path.join("Scripts_corregido", "Scripts.rxdata"));
  return { existia, descargable };
}

/* ─────────────────────────── Rotom del Tiempo ──────────────────────────── */

// La búsqueda de celda considera eventos sólidos. Si primero buscáramos y luego
// hiciéramos upsert, cada reaplicación vería al propio evento como obstáculo y lo
// desplazaría una casilla. Reutilizar su coordenada vuelve el instalador idempotente.
function existingEventCell(mapId, name) {
  const map = readMap(mapId);
  for (const [, ev] of map.getIvar("@events").pairs) {
    if (txt(ev.getIvar("@name")) !== name) continue;
    return [Number(ev.getIvar("@x")), Number(ev.getIvar("@y"))];
  }
  return null;
}

function colocarRotom(punto) {
  const nombre = `${MARKER} Rotom del Tiempo — ${punto.lugar}`;
  const g = grid(punto.mapa);
  const celda = existingEventCell(punto.mapa, nombre) || nearestFreeCell(g, punto.cerca_de, { maxDistance: 6 });
  if (!celda) return { punto, error: "sin celda libre" };
  const resumen = upsertEvents(punto.mapa, [nombre], (baseId) => [
    event(baseId, nombre, celda[0], celda[1], [
      page({
        trigger: 0,
        gfx: graphic(CFG.rotom.sprite, 2),
        list: [...texts(CFG.rotom.lineas.activo), script(`CanonArceus.puerta("${punto.lugar}")`), cmd(0)],
      }),
    ]),
  ], { verbose: false });
  return { punto, celda, resumen };
}

/** El Fragmento del Génesis, en la cumbre donde Arceus cayó. */
function colocarFragmento() {
  const mapa = CFG.fragmento.mapa;
  const nombre = `${MARKER} Fragmento del Génesis`;
  const g = grid(mapa);
  const celda = existingEventCell(mapa, nombre) || nearestFreeCell(g, CFG.fragmento.cerca_de, { maxDistance: 5 });
  if (!celda) throw new Error(`sin celda libre para el fragmento en el mapa ${mapa}`);
  const resumen = upsertEvents(mapa, [nombre], (baseId) => [
    event(baseId, nombre, celda[0], celda[1], [
      // Página 1: solo aparece si el duelo está resuelto.
      page({
        cond: condition({ sw: SW.DUELO_RESUELTO }),
        trigger: 0,
        list: [
          ...texts(CFG.fragmento.texto),
          script("CanonArceus.entregar_fragmento"),
          selfSwitch("A"),
          cmd(0),
        ],
      }),
      // Página 2: ya recogido, no queda nada.
      page({ cond: condition({ self: "A" }), list: [cmd(0)] }),
    ]),
  ], { verbose: false });
  return resumen;
}

/** Las puertas no responden hasta que el duelo exista. */
function cerrarPuertas() {
  const tocadas = [];
  for (const puerta of CFG.puertas) {
    respaldo(mapFile(puerta.mapa));
    const map = readMap(puerta.mapa);
    const re = new RegExp(puerta.patron, "i");
    let paginas = 0;
    for (const [, ev] of map.getIvar("@events").pairs) {
      if (!re.test(txt(ev.getIvar("@name")))) continue;
      for (const p of ev.getIvar("@pages") || []) {
        const cond = p.getIvar("@condition");
        if (!cond) continue;
        const s1 = cond.getIvar("@switch1_valid");
        const id1 = cond.getIvar("@switch1_id");
        const s2 = cond.getIvar("@switch2_valid");
        const id2 = cond.getIvar("@switch2_id");
        if ((s1 && id1 === SW.DUELO_RESUELTO) || (s2 && id2 === SW.DUELO_RESUELTO)) continue;
        if (s1 && id1 !== SW.DUELO_RESUELTO && !(s2 && id2 !== SW.DUELO_RESUELTO)) {
          cond.setIvar("@switch2_valid", true);
          cond.setIvar("@switch2_id", SW.DUELO_RESUELTO);
        } else if (!s1) {
          cond.setIvar("@switch1_valid", true);
          cond.setIvar("@switch1_id", SW.DUELO_RESUELTO);
        } else {
          continue;
        }
        paginas++;
      }
    }
    if (paginas) writeMap(puerta.mapa, map);
    tocadas.push({ ...puerta, paginas });
  }
  return tocadas;
}

/** Oak explica las dimensiones; si Arceus fue capturado, aparece él también. */
function ampliarOak() {
  const { mapa, patron, texto, texto_arceus } = CFG.oak;
  respaldo(mapFile(mapa));
  const map = readMap(mapa);
  const re = new RegExp(patron, "i");
  let paginas = 0;
  for (const [, ev] of map.getIvar("@events").pairs) {
    if (!re.test(txt(ev.getIvar("@name")))) continue;
    const paginasActuales = ev.getIvar("@pages") || [];
    const propias = paginasActuales.filter((p) => {
      const c = p.getIvar("@condition");
      if (!c) return false;
      return (c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.FRAGMENTO_GENESIS)
        || (c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.ARCEUS_CAPTURADO)
        || (c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.EVENTO_COMPLETADO);
    });
    const limpias = paginasActuales.filter((p) => !propias.includes(p));
    // Se insertan en la segunda posición: Oak habla de las dimensiones cuando
    // no tiene nada más urgente que decir, sin tapar ninguna escena de historia.
    limpias.splice(1, 0,
      page({
        cond: condition({ sw: SW.FRAGMENTO_GENESIS }),
        trigger: 0,
        list: [...texts(texto), cmd(0)],
      }),
      page({
        cond: condition({ sw: SW.ARCEUS_CAPTURADO }),
        trigger: 0,
        list: [...texts(texto_arceus), cmd(0)],
      }));
    // R17 — ATUENDO DE MAESTRO: al completar La Ruta de Dios (EVENTO_COMPLETADO),
    // Oak entrega a Ash su nuevo atuendo (outfit de batalla 8 + charset
    // ash_outfit_maestro vía PokeModAtavios). Self-switch A impide que el regalo
    // se repita. Las páginas van AL FINAL: en RMXP gana la última que cumple sus
    // condiciones, así el regalo no queda tapado por la charla de las dimensiones.
    limpias.push(
      page({
        cond: condition({ sw: SW.EVENTO_COMPLETADO }),
        trigger: 0,
        list: [
          ...texts([
            "Oak: ¡Ash! Justo a tiempo. Nadie ha vuelto jamás de La Ruta de Dios como tú.",
            "Oak: Un entrenador que completa esa ruta merece más que un diploma: te he preparado el Atuendo de Maestro.",
            "Oak: Es el mismo estilo con el que yo viajaba de joven. Lúcelo con orgullo, campeón.",
          ]),
          script("PokeModAtavios.poner(9, true) rescue nil"),
          script("$Trainer.outfit = 8 if $Trainer"),
          cmd(121, [SW.ATUENDO_MAESTRO, SW.ATUENDO_MAESTRO, 0]),
          cmd(123, [S("A"), 0]),
          ...texts([
            "Oak: ¡Perfecto! Ese atuendo te queda como anillo al dedo. Ahora, ve y demuéstralo al mundo.",
          ]),
          cmd(0),
        ],
      }),
      page({
        cond: condition({ sw: SW.EVENTO_COMPLETADO, self: "A" }),
        trigger: 0,
        list: [
          ...texts([
            "Oak: El Atuendo de Maestro te sienta de maravilla, Ash. El mundo entero va a reconocerte en él.",
          ]),
          cmd(0),
        ],
      }));
    ev.setIvar("@pages", limpias);
    paginas += 4;
  }
  if (paginas) writeMap(mapa, map);
  return { mapa, paginas };
}

/** Si Arceus fue capturado, interviene antes del Mad Pikachu. */
function intervencionMadPikachu() {
  const mapa = CFG.mad_pikachu.mapa;
  const re = new RegExp(CFG.mad_pikachu.patron, "i");
  const g = grid(mapa);
  const objetivo = g.events.find((e) => re.test(e.name));
  if (!objetivo) return { mapa, error: "no encuentro al Mad Pikachu" };
  const nombre = `${MARKER} eco del Génesis`;
  const celda = existingEventCell(mapa, nombre) || nearestFreeCell(g, CFG.mad_pikachu.cerca_de, { maxDistance: 6 });
  if (!celda) return { mapa, juntoA: objetivo.name, error: "sin celda libre" };
  const resumen = upsertEvents(mapa, [nombre], (baseId) => [
    event(baseId, nombre, celda[0], celda[1], [
      page({
        cond: condition({ sw: SW.ARCEUS_CAPTURADO }),
        trigger: 0,
        gfx: graphic("ARCEUS", 2),
        list: [...texts(CFG.mad_pikachu.texto), cmd(0)],
      }),
    ]),
  ], { verbose: false });
  return { mapa, juntoA: objetivo.name, celda, resumen };
}

/* ─────────────────────────────── verificación ──────────────────────────── */

function tieneHookDeFase(scripts) {
  const rutaIdx = scripts.findIndex(([, t]) => t && t.text === "PokeMod_RutaDeDios");
  const canonIdx = scripts.findIndex(([, t]) => t && t.text === "PokeMod_CanonArceus");
  if (rutaIdx < 0 || canonIdx < 0 || rutaIdx >= canonIdx) return false;
  try {
    const ruby = zlib.inflateSync(Buffer.from(scripts[rutaIdx][2].bytes)).toString("utf-8");
    return ruby.includes("def check_arceus_phase(battler)") && ruby.includes("check_arceus_phase(battler)");
  } catch (error) {
    return false;
  }
}

function verificar() {
  const fallos = [];

  const scripts = readData("Scripts.rxdata");
  if (!tieneHookDeFase(scripts)) fallos.push("PokeMod_RutaDeDios debe definir el hook de fase antes de cargar PokeMod_CanonArceus");
  const seccion = scripts.find(([, t]) => t && t.text === "PokeMod_CanonArceus");
  if (!seccion) fallos.push("falta la sección Ruby PokeMod_CanonArceus");
  else {
    const ruby = zlib.inflateSync(Buffer.from(seccion[2].bytes)).toString("utf-8");
    for (const nombre of ["module CanonArceus", "def self.puerta", "def self.entregar_fragmento", "check_arceus_phase", "RUTA_ARCEUS_MOVE_SETS", "set.replace(seleccion.take(Pokemon::MAX_MOVES))"]) {
      if (!ruby.includes(nombre)) fallos.push(`el Ruby no define ${nombre}`);
    }
    const corregido = path.join(ROOT, "Scripts_corregido", "Scripts.rxdata");
    if (fs.existsSync(corregido)) {
      const descargable = marshalLoad(fs.readFileSync(corregido));
      if (descargable.length !== scripts.length) {
        fallos.push(`Scripts_corregido/Scripts.rxdata tiene ${descargable.length} secciones y el juego ${scripts.length}`);
      } else if (!descargable.some(([, t]) => t && t.text === "PokeMod_CanonArceus")) {
        fallos.push("al Scripts_corregido/Scripts.rxdata le falta el canon de Arceus");
      } else if (!tieneHookDeFase(descargable)) {
        fallos.push("el Scripts_corregido/Scripts.rxdata no conserva el hook de fase previo al canon");
      }
    }
  }

  for (const punto of CFG.rotom.puntos) {
    const g = grid(punto.mapa);
    const ok = g.events.some((e) => e.name.startsWith(`${MARKER} Rotom del Tiempo`));
    if (!ok) fallos.push(`falta el Rotom del Tiempo en el mapa ${punto.mapa}`);
  }

  {
    const g = grid(CFG.fragmento.mapa);
    const frag = g.events.find((e) => e.name.includes("Fragmento del Génesis"));
    if (!frag) fallos.push(`falta el Fragmento del Génesis en el mapa ${CFG.fragmento.mapa}`);
    else {
      const conDuelo = frag.pages.some((p) => {
        const c = p.getIvar("@condition");
        return c && c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.DUELO_RESUELTO;
      });
      if (!conDuelo) fallos.push("el fragmento aparece sin haber resuelto el duelo");
    }
  }

  for (const puerta of CFG.puertas) {
    const g = grid(puerta.mapa);
    const re = new RegExp(puerta.patron, "i");
    let cerradas = 0;
    for (const e of g.events) {
      if (!re.test(e.name)) continue;
      for (const p of e.pages) {
        const c = p.getIvar("@condition");
        if (!c) continue;
        const a = c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.DUELO_RESUELTO;
        const b = c.getIvar("@switch2_valid") && c.getIvar("@switch2_id") === SW.DUELO_RESUELTO;
        if (a || b) cerradas++;
      }
    }
    if (!cerradas) fallos.push(`la puerta "${puerta.nota}" (mapa ${puerta.mapa}) no exige el duelo de Arceus`);
  }

  {
    const g = grid(CFG.oak.mapa);
    const re = new RegExp(CFG.oak.patron, "i");
    const oak = g.events.find((e) => re.test(e.name));
    if (!oak) fallos.push("no encuentro al profesor Oak");
    else {
      const con = (id) => oak.pages.some((p) => {
        const c = p.getIvar("@condition");
        return c && c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === id;
      });
      if (!con(SW.FRAGMENTO_GENESIS)) fallos.push("a Oak le falta el diálogo sobre las dimensiones");
      if (!con(SW.ARCEUS_CAPTURADO)) fallos.push("a Oak le falta la aparición de Arceus capturado");
      if (!con(SW.EVENTO_COMPLETADO)) fallos.push("a Oak le falta la entrega del Atuendo de Maestro");
    }
  }

  {
    const g = grid(CFG.mad_pikachu.mapa);
    const eco = g.events.find((e) => e.name.includes("eco del Génesis"));
    if (!eco) fallos.push("falta la intervención de Arceus ante el Mad Pikachu");
    else {
      const condicionado = eco.pages.some((p) => {
        const c = p.getIvar("@condition");
        return c && c.getIvar("@switch1_valid") && c.getIvar("@switch1_id") === SW.ARCEUS_CAPTURADO;
      });
      if (!condicionado) fallos.push("el eco del Génesis no depende de la captura de Arceus");
    }
  }

  return fallos;
}

/* ──────────────────────────────── programa ─────────────────────────────── */

if (VERIFY) {
  const fallos = verificar();
  if (fallos.length) {
    console.log("✘ Canon de Arceus incompleto:");
    for (const f of fallos) console.log(`   · ${f}`);
    process.exit(1);
  }
  console.log("✔ Canon de Arceus verificado.");
  console.log("  · todas las puertas exigen el duelo de La Ruta de Dios");
  console.log("  · Fragmento del Génesis en la cumbre, solo tras el duelo");
  console.log("  · Rotom del Tiempo en los tres accesos");
  console.log("  · Oak habla de las dimensiones y Arceus aparece si fue capturado");
  console.log("  · el combate doblega una regla distinta por fase");
  process.exit(0);
}

const inyeccion = inyectarRuby();
const rotoms = CFG.rotom.puntos.map(colocarRotom);
const fragmento = colocarFragmento();
const puertas = cerrarPuertas();
const oak = ampliarOak();
const madPikachu = intervencionMadPikachu();

console.log(`✔ Canon de Arceus aplicado sobre ${path.relative(ROOT, GAME)}`);
console.log(`  · guion PokeMod_CanonArceus: ${inyeccion.existia ? "actualizado" : "inyectado"} (${RUBY.split("\n").length} líneas, ${Object.keys(CFG.fases_dios).length} fases con abuso de mecánicas)`);
if (inyeccion.descargable !== null) {
  console.log(`  · Scripts_corregido/Scripts.rxdata: ${inyeccion.descargable ? "actualizado" : "inyectado"} (mismas nueve correcciones de estabilidad)`);
}
for (const r of rotoms) {
  console.log(`  · Rotom del Tiempo — ${r.punto.lugar}: mapa ${r.punto.mapa} en (${r.celda ? r.celda.join(",") : "—"})`);
}
console.log(`  · Fragmento del Génesis: mapa ${CFG.fragmento.mapa} en (${fragmento.added[0]?.x},${fragmento.added[0]?.y})`);
for (const p of puertas) {
  console.log(`  · puerta cerrada — ${p.nota}: mapa ${p.mapa} (${p.paginas} páginas)`);
}
console.log(`  · Oak: ${oak.paginas} páginas nuevas en el mapa ${oak.mapa}`);
console.log(`  · Mad Pikachu: ${madPikachu ? (madPikachu.celda ? `eco del Génesis en el mapa ${madPikachu.mapa} (${madPikachu.celda.join(",")}), junto a "${madPikachu.juntoA}"` : `mapa ${madPikachu.mapa}: ${madPikachu.error}`) : "no localizado"}`);

const fallos = verificar();
if (fallos.length) {
  console.log("\n✘ La verificación encontró problemas:");
  for (const f of fallos) console.log(`   · ${f}`);
  process.exit(1);
}
console.log("✔ Verificación posterior OK.");// ============================================================================
// apply_ciudad_teckel_maxine.mjs
// ----------------------------------------------------------------------------
// Nuevo propósito de la Isla Espejo, según el diseño del usuario:
//
//  · Map 997 → CIUDAD TECKEL: pueblo donde los Pokémon perro (Zigzagoon,
//    Poochyena, Growlithe…) campan libremente; gimnasio y muelle.
//  · Map 998 → GIMNASIO TECKEL: la líder Duna entrega la Medalla Pata.
//  · Map 999 → AFUERAS TECKEL: prado con encuentros de perros.
//  · Map 2300 → ISLA PARAÍSO: bosque con el altar de MAXINE (Legendaria
//    Florateck, nivel 125). Se llega con el Ticket Paraíso que entrega el
//    Profesor Atlas en Puerto Horizonte (1001). Para que MAXINE despierte hay
//    que haber vencido a Duna y responder a la Guardiana Nira la pregunta
//    «¿qué le gusta más a MAXINE, el pollo o la pata?» — la correcta es LA PATA.
//
// Idempotente. Con --verify solo comprueba.
// ============================================================================

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  ROOT, GAME, DATA, S, Sym, txt, iv, cmd, condition, graphic, page, event,
  readMapRaw, writeMapRaw, readData, writeData, backup, texts, script,
  transfer, switchOn, ifSwitch, ifScript, elseBranch, endBranch, choice,
  choiceCase, choiceEnd, endEvent, freeCells, nearest, makeChecker,
  installMapInfos, installMetadata, installItems, installTrainerTypes,
  installTrainers, speciesAvailable, marshalLoad, marshalDump, RHash, RObject,
} from "./lib/dlc_helpers.mjs";
import { RSymbol } from "../web/js/marshal.js";
import { buildPokemonSprites } from "./lib/sprite_build.mjs";

const VERIFY = process.argv.includes("--verify");

const CITY = 997, GYM = 998, OUTSKIRTS = 999, PARADISE = 2300;
const DONORS = { [CITY]: 43, [GYM]: 58, [OUTSKIRTS]: 28, [PARADISE]: 21 };
const SW_TECKEL = 960;   // Duna vencida
const SW_MAXINE = 961;   // MAXINE vencida o capturada
const SW_PATA   = 962;   // la guardiana aceptó «la pata»
const CANON_ARCEUS = 876;
const MANIFEST = path.join(ROOT, "content", "teckel_manifest.json");

// Tres manadas visibles agrupan las seis especies originales en encuentros
// alternos: Map997 conserva el repertorio sin saturar el atrio de personajes.
const DOG_PACKS = [
  { char: "ZIGZAGOON", species: ["ZIGZAGOON", "LILLIPUP"], level: 58 },
  { char: "POOCHYENA", species: ["POOCHYENA", "ROCKRUFF"], level: 59 },
  { char: "GROWLITHE", species: ["GROWLITHE", "EEVEE"], level: 60 },
];
const DOGS = [...new Set(DOG_PACKS.flatMap((pack) => pack.species))];

function saveManifest(list) {
  const m = fs.existsSync(MANIFEST) ? JSON.parse(fs.readFileSync(MANIFEST, "utf8")) : { files: [] };
  const set = new Set(m.files);
  for (const f of list) set.add(f);
  m.files = [...set].sort();
  fs.writeFileSync(MANIFEST, JSON.stringify(m, null, 2));
}

const mapPath = (id) => `Data/Map${String(id).padStart(3, "0")}.rxdata`;

function cloneTerrain() {
  for (const [target, donor] of Object.entries(DONORS)) {
    const id = Number(target);
    const targetFile = path.join(DATA, `Map${String(id).padStart(3, "0")}.rxdata`);
    const keptEvents = fs.existsSync(targetFile)
      ? iv(readMapRaw(id), "@events").pairs.filter(([, object]) => !txt(iv(object, "@name")).startsWith("Teckel:"))
      : [];
    const copy = marshalLoad(Buffer.from(marshalDump(readMapRaw(donor))));
    // Al refrescar el terreno, conserva eventos ajenos a Teckel (ferry, Abra,
    // portales y contenido de otras campañas); sólo esta herramienta reemplaza
    // sus eventos con prefijo Teckel: en el siguiente paso.
    copy.setIvar("@events", new RHash(keptEvents));
    writeMapRaw(id, copy);
  }
}

/* ────────────────────────────────── eventos ─────────────────────────────── */

function cityEvents() {
  const cells = freeCells(CITY);
  const pick = (i) => cells[(i * 11 + 3) % cells.length];
  const events = [];
  DOG_PACKS.forEach((pack, i) => {
    const [x, y] = pick(i);
    const speciesList = pack.species.map((species) => `:${species}`).join(", ");
    const p = page({
      trigger: 2,
      list: [
        ...texts(["¡Una manada juguetona se acerca para retarte!" ]),
        script(`pbWildBattle([${speciesList}].sample, ${pack.level}, 1, true, true)`),
        endEvent(),
      ],
    });
    p.setIvar("@graphic", graphic(pack.char));
    p.setIvar("@move_type", 1);
    p.setIvar("@move_speed", 4);
    p.setIvar("@step_anime", true);
    events.push(event(100 + i, `Teckel: Manada errante ${i + 1}`, x, y, [p]));
  });
  const [gx, gy] = nearest(cells, [20, 10]);
  events.push(event(200, "Teckel: Gimnasio", gx, gy, [page({
    trigger: 1,
    list: [transfer(GYM, 6, 8, 2), endEvent()],
  })]));
  const [mx, my] = nearest(cells, [4, 24]);
  events.push(event(201, "Teckel: Muelle a Paraíso", mx, my, [page({
    list: [
      ifScript("pbHasItem?(:PARAISOTICKET)"),
      ...texts(["El barquero del Atlas revisa tu Ticket Paraíso y asiente.", "La lancha corta un mar que no aparece en ningún mapa."], 1),
      transfer(PARADISE, 10, 26, 2, 1),
      elseBranch(),
      ...texts(["El barquero: «Sin el Ticket Paraíso no cruzo. El Profesor Atlas", "lo entrega en Puerto Horizonte, a quien ya haya cerrado la Ruta de Dios.»"]),
      endBranch(),
      endEvent(),
    ],
  })]));
  // Conexión ciudad↔afueras: las celdas de arrivo y de warp se excluyen entre
  // sí y coinciden con las que calcula outskirtsEvents() en la reinstalación.
  const outCells = freeCells(OUTSKIRTS).filter((c) => !(c[0] === 8 && c[1] === 8));
  const [ox, oy] = nearest(outCells, [8, 10]);
  const cityArrival = nearest(cells, [55, 45]);
  const [wx, wy] = nearest(cells.filter((c) => !(c[0] === cityArrival[0] && c[1] === cityArrival[1])), [50, 40]);
  events.push(event(203, "Teckel: Camino a Afueras", wx, wy, [page({
    trigger: 1,
    list: [transfer(OUTSKIRTS, ox, oy, 2), endEvent()],
  })]));
  const [vx, vy] = nearest(cells, [24, 14]);
  events.push(event(202, "Teckel: Veterinaria canina", vx, vy, [page({
    list: [
      ...texts(["Veterinaria: «Aquí todo perro termina sano.»"]),
      script("$Trainer.party.each { |p| p.heal }"),
      script("pbMessage(\"Tu equipo descansa entre colchonetas y juguetes.\")"),
      endEvent(),
    ],
  })]));
  return events;
}

