function outskirtsEvents() {
  const cells = freeCells(OUTSKIRTS).filter((c) => !(c[0] === 8 && c[1] === 8));
  const cityCells = freeCells(CITY);
  const [cx, cy] = nearest(cityCells, [55, 45]);
  const [ax, ay] = nearest(cells, [8, 10]);
  const [wx, wy] = nearest(cells.filter((c) => !(c[0] === ax[0] && c[1] === ax[1])), [8, 40]);
  return [
    event(400, "Teckel: Cartel de afueras", 8, 8, [page({
      list: [...texts(["«Afueras Teckel: los perros marcan el camino; tú no.»"]), endEvent()],
    })]),
    event(401, "Teckel: Camino a la ciudad", wx, wy, [page({
      trigger: 1,
      list: [transfer(CITY, cx, cy, 2), endEvent()],
    })]),
  ];
}

