/* ─────────────────────────────────── datos ──────────────────────────────── */

function installEncounters() {
  const enc = readData("encounters.dat");
  const keyText = (k) => String(k?.name ?? k?.text ?? k);
  if (enc.pairs.some(([k]) => keyText(k).startsWith(`${OUTSKIRTS}_`))) return;
  const donors = enc.pairs.filter(([k]) => keyText(k).startsWith("28_"));
  if (!donors.length) throw new Error("sin tabla de encuentros donante (mapa 28)");
  let i = 0;
  const especies = speciesAvailable();
  const walk = (v) => {
    if (v instanceof RSymbol && !DOGS.includes(v.name) && especies.has(v.name)) {
      // símbolo de especie: lo sustituimos por un perro de la manada
      return new RSymbol(DOGS[i++ % DOGS.length]);
    }
    if (Array.isArray(v)) return v.map(walk);
    if (v && v.pairs) { v.pairs = v.pairs.map(([k, val]) => [walk(k), walk(val)]); return v; }
    if (v && v.ivars) { v.ivars = v.ivars.map(([k, val]) => [k, walk(val)]); return v; }
    return v;
  };
  for (const [k, donor] of donors) {
    const slot = keyText(k).split("_")[1] ?? "0";
    const copy = marshalLoad(Buffer.from(marshalDump(donor)));
    enc.pairs.push([Sym(`${OUTSKIRTS}_${slot}`), walk(copy)]);
  }
  writeData("encounters.dat", enc);
}

function installMaxineSpecies() {
  const data = readData("species.dat");
  if (data.pairs.some(([k]) => k instanceof RSymbol && k.name === "MAXINE")) return;
  const bySymbol = new Map();
  let maxId = 0;
  for (const [k, v] of data.pairs) {
    if (k instanceof RSymbol) bySymbol.set(k.name, v);
    if (typeof k === "number") maxId = Math.max(maxId, k);
    if (v?.getIvar) maxId = Math.max(maxId, Number(v.getIvar("@id_number") ?? 0));
  }
  const template = bySymbol.get("ZIGZAGOON");
  if (!template) throw new Error("falta plantilla ZIGZAGOON");
  const obj = new RObject(template.className, template.ivars.map(([k, v]) => [k, v]));
  const set = (n, v) => obj.setIvar(n, v);
  const stat = (vals) => new RHash(Object.entries(vals).map(([s, v]) => [Sym(s), v]));
  set("@id", Sym("MAXINE"));
  set("@id_number", maxId + 1);
  set("@species", Sym("MAXINE"));
  set("@form", 0);
  set("@real_name", S("MAXINE"));
  set("@real_form_name", null);
  set("@real_category", S("Florateck"));
  set("@real_pokedex_entry", S("Legendaria guardiana de la Isla Paraíso. Su armadura de flora mora florece una vez al siglo y su osito de peluche, dicen, es el sello que mantiene dormida a la verdadera bestia."));
  set("@type1", Sym("GRASS"));
  set("@type2", Sym("FAIRY"));
  set("@base_stats", stat({ HP: 95, ATTACK: 105, DEFENSE: 100, SPECIAL_ATTACK: 130, SPECIAL_DEFENSE: 110, SPEED: 95 }));
  set("@evs", stat({ HP: 0, ATTACK: 0, DEFENSE: 0, SPECIAL_ATTACK: 3, SPECIAL_DEFENSE: 0, SPEED: 0 }));
  set("@base_exp", 306);
  set("@growth_rate", Sym("Slow"));
  set("@gender_ratio", Sym("AllFemale"));
  set("@catch_rate", 3);
  set("@happiness", 100);
  set("@moves", [
    [1, Sym("PETALBLIZZARD")], [1, Sym("PLAYROUGH")], [40, Sym("EXTREMESPEED")],
    [60, Sym("GRASSKNOT")], [80, Sym("DAZZLINGGLEAM")], [100, Sym("CLOSECOMBAT")],
  ]);
  set("@tutor_moves", []);
  set("@egg_moves", []);
  set("@abilities", [Sym("FLOWERVEIL")]);
  set("@hidden_abilities", [Sym("FLOWERGIFT")]);
  set("@egg_groups", [Sym("Field")]);
  set("@hatch_steps", 30720);
  set("@evolutions", []);
  set("@height", 6.0);
  set("@weight", 28.5);
  set("@color", Sym("Brown"));
  set("@shape", Sym("Quadruped"));
  set("@habitat", Sym("Rare"));
  data.pairs.push([maxId + 1, obj], [Sym("MAXINE"), obj]);
  writeData("species.dat", data);
}

async function apply() {
  backup("teckel_maxine", ["Map997.rxdata", "Map998.rxdata", "Map999.rxdata", "Map2300.rxdata", "Map1001.rxdata", "Scripts.rxdata", "MapInfos.rxdata", "map_metadata.dat", "encounters.dat", "items.dat", "trainers.dat", "trainer_types.dat", "species.dat"]);
  cloneTerrain();

  const upserts = [
    [CITY, ["Teckel:"], cityEvents],
    [GYM, ["Teckel:"], gymEvents],
    [OUTSKIRTS, ["Teckel:"], outskirtsEvents],
    [PARADISE, ["Paraíso:"], paradiseEvents],
  ];
  for (const [mapId, owned, builder] of upserts) {
    const map = readMapRaw(mapId);
    const events = iv(map, "@events");
    events.pairs = events.pairs.filter(([, e]) => !owned.some((p) => txt(iv(e, "@name")).startsWith(p)));
    const built = builder();
    let nextId = Math.max(0, ...events.pairs.map(([k]) => Number(k))) + 1;
    for (const ev of built) {
      const id = Number(iv(ev, "@id"));
      ev.setIvar("@id", id);
      events.pairs.push([id, ev]);
      nextId = Math.max(nextId, id + 1);
    }
    writeMapRaw(mapId, map);
  }

  // Profesor Atlas en Puerto Horizonte (1001)
  {
    const map = readMapRaw(1001);
    const events = iv(map, "@events");
    events.pairs = events.pairs.filter(([, e]) => txt(iv(e, "@name")) !== "Teckel: Profesor Atlas");
    const ev = professorEvent();
    const cells = freeCells(1001);
    const [x, y] = cells[5] ?? [8, 6];
    ev.setIvar("@x", x); ev.setIvar("@y", y);
    events.pairs.push([Number(iv(ev, "@id")), ev]);
    writeMapRaw(1001, map);
  }

  installMapInfos([
    { mapId: CITY, title: "Ciudad Teckel", parentId: 1001, order: 901 },
    { mapId: GYM, title: "Gimnasio Teckel", parentId: CITY, order: 902 },
    { mapId: OUTSKIRTS, title: "Afueras Teckel", parentId: CITY, order: 903 },
    { mapId: PARADISE, title: "Isla Paraíso", parentId: CITY, order: 904 },
  ], "teckel_maxine");
  installMetadata([
    { mapId: CITY, exterior: true },
    { mapId: GYM },
    { mapId: OUTSKIRTS, exterior: true },
    { mapId: PARADISE, exterior: true, battleBackdrop: "forest" },
  ].map((s) => ({ mapId: s.mapId, parentId: s.exterior ? 1001 : CITY, battleBackdrop: s.battleBackdrop })), "teckel_maxine");

  installEncounters();
  installItems([
    { id: "PARAISOTICKET", base: "VERMILIONTICKET", nombre: "Ticket Paraíso", plural: "Tickets Paraíso" },
    { id: "TECKELBADGE", base: "ATLASERABADGE", nombre: "Medalla Pata", plural: "Medallas Pata" },
  ], "teckel_maxine");
  installTrainerTypes([{ id: "TECKEL_LEADER", base: "LEADER_Valerie", nombre: "Líder de Ciudad Teckel" }], "teckel_maxine");
  installTrainers([{
    tipo: "TECKEL_LEADER", nombre: "DUNA", nivel: 80,
    equipo: ["LILLIPUP", "ROCKRUFF", "POOCHYENA", "MIGHTYENA", "GROWLITHE", "ARCANINE"],
    derrota: "La manada confía en ti. Cuida su ritmo.",
  }], "teckel_maxine");
  installMaxineSpecies();

  // Grito + sprites de MAXINE
  const crySrc = path.join(GAME, "Audio", "SE", "NIDOGOD.ogg");
  const cryDst = path.join(GAME, "Audio", "SE", "MAXINE.ogg");
  if (!fs.existsSync(cryDst)) fs.copyFileSync(crySrc, cryDst);
  // Sprites fieles a las fotos generadas: sin reducción de paleta.
  const concept = path.join(ROOT, "reference", "pokegods", "concept", "MAXINE.png");
  if (fs.existsSync(concept)) {
    await buildPokemonSprites(concept, "MAXINE", { paletteSize: 0 });
  } else {
    const existingSprites = [
      "Graphics/Pokemon/Front/MAXINE.png", "Graphics/Pokemon/Back/MAXINE.png",
      "Graphics/Pokemon/Icons/MAXINE.png", "Graphics/Characters/MAXINE.png",
    ];
    if (existingSprites.some((file) => !fs.existsSync(path.join(GAME, file)))) {
      throw new Error("falta reference/pokegods/concept/MAXINE.png y no están todos los sprites ya construidos");
    }
    console.log("· MAXINE: se conservan los sprites ya construidos; falta la referencia de origen.");
  }
  const altar = path.join(ROOT, "reference", "maxine", "ALTAR_maxine_gb.png");
  if (fs.existsSync(altar)) await buildPokemonSprites(altar, "ALTAR_MAXINE", { paletteSize: 0 });

  saveManifest([
    mapPath(CITY), mapPath(GYM), mapPath(OUTSKIRTS), mapPath(PARADISE), mapPath(1001),
    "Data/MapInfos.rxdata", "Data/map_metadata.dat", "Data/encounters.dat",
    "Data/items.dat", "Data/trainers.dat", "Data/trainer_types.dat", "Data/species.dat",
    "Graphics/Pokemon/Front/MAXINE.png", "Graphics/Pokemon/Back/MAXINE.png",
    "Graphics/Pokemon/Icons/MAXINE.png", "Graphics/Characters/MAXINE.png",
    "Graphics/Characters/ALTAR_MAXINE.png",
    "Graphics/Pictures/Trainer Card/icon_badges.png",
    "Audio/SE/MAXINE.ogg",
  ]);
  console.log("OK: Ciudad Teckel, Gimnasio, Afueras, Isla Paraíso y MAXINE instalados");
}

function verify() {
  const check = makeChecker("ciudad teckel + maxine");
  const names = (id) => readMapRaw(id).getIvar("@events").pairs.map(([, e]) => txt(iv(e, "@name")));
  check.ok(names(CITY).some((n) => n.startsWith("Teckel: Muelle")), "falta el muelle a Paraíso");
  check.ok(names(CITY).filter((n) => /Manada errante/.test(n)).length === 3, "Ciudad Teckel debe concentrar los encuentros en tres manadas");
  const transfers = (id) => readMapRaw(id).getIvar("@events").pairs.flatMap(([, e]) =>
    (iv(e, "@pages") || []).flatMap((p) => (p.getIvar("@list") || []))
      .filter((c) => c.getIvar("@code") === 201).map((c) => Number(c.getIvar("@parameters")[1])));
  check.ok(names(CITY).includes("Teckel: Camino a Afueras") && transfers(CITY).includes(OUTSKIRTS), "la ciudad no conecta con las afueras");
  check.ok(names(OUTSKIRTS).includes("Teckel: Camino a la ciudad") && transfers(OUTSKIRTS).includes(CITY), "las afueras no conectan con la ciudad");
  const manadas = readMapRaw(CITY).getIvar("@events").pairs.map(([, e]) => e).filter((e) => /Manada errante/.test(txt(iv(e, "@name"))));
  const battleLines = [];
  for (const e of manadas) {
    const lines = iv(e, "@pages")[0].getIvar("@list").map((c) => txt(c.getIvar("parameters")?.[0] ?? "")).join("\n");
    check.ok(/pbWildBattle\(\[:\w+, :\w+\]\.sample, \d+, 1, true, true\)/.test(lines), `${txt(iv(e, "@name"))}: encuentro alterno debe conservar canLose`);
    battleLines.push(lines);
  }
  for (const species of DOGS) check.ok(battleLines.some((line) => line.includes(`:${species}`)), `falta la especie ${species} en una de las manadas`);
  const visibleCityActors = readMapRaw(CITY).getIvar("@events").pairs.map(([, e]) => {
    const pageObj = iv(e, "@pages")?.[0];
    return txt(iv(iv(pageObj, "@graphic"), "@character_name"));
  }).filter((name) => name && name !== "Object ball special");
  check.ok(visibleCityActors.length <= 5, `Ciudad Teckel supera cinco personajes visibles (${visibleCityActors.length})`);
  check.ok(names(GYM).some((n) => n.includes("Líder Duna")), "falta Duna");
  check.ok(names(PARADISE).some((n) => n.includes("MAXINE")), "falta MAXINE");
  check.ok(names(PARADISE).some((n) => n.includes("Altar de MAXINE")), "falta el altar");
  check.ok(fs.existsSync(path.join(GAME, "Graphics/Characters/ALTAR_MAXINE.png")), "falta el sprite del altar");
  check.ok(names(PARADISE).some((n) => n.includes("Guardiana Nira")), "falta la guardiana");
  check.ok(names(1001).includes("Teckel: Profesor Atlas"), "falta el Profesor Atlas");
  const items = readData("items.dat");
  check.ok(items.pairs.some(([k]) => txt(k) === "PARAISOTICKET"), "falta el ticket");
  check.ok(items.pairs.some(([k]) => txt(k) === "TECKELBADGE"), "falta la medalla");
  const sp = readData("species.dat");
  check.ok(sp.pairs.some(([k]) => k instanceof RSymbol && k.name === "MAXINE"), "falta la especie MAXINE");
  for (const f of ["Graphics/Pokemon/Front/MAXINE.png", "Graphics/Characters/MAXINE.png", "Audio/SE/MAXINE.ogg"]) {
    check.ok(fs.existsSync(path.join(GAME, f)), `falta ${f}`);
  }
  const maxinePage = readMapRaw(PARADISE).getIvar("@events").pairs
    .map(([, e]) => e).find((e) => txt(iv(e, "@name")) === "Paraíso: MAXINE");
  check.ok(maxinePage && iv(maxinePage, "@pages").length === 3, "MAXINE debe tener 3 páginas");
  check.done();
}

if (VERIFY) {
  verify();
} else {
  await apply();
  verify();
}#!/usr/bin/env node
/**
 * Compila planos estructurales de campañas de ROM como prototipos adaptados a
 * Fire Ash. No emula las ROM ni copia sus mapas, diálogos o recursos binarios.
 * Glazed, Light Platinum, Liquid Crystal y Pokémon Unbound ponen a Ash como
 * protagonista; TFOH conserva el tratamiento de visitante ya existente.
 */
import fs from "node:fs";
import path from "node:path";
import { marshalDump, RHash } from "../web/js/marshal.js";
import { tableGet } from "../web/js/rmxp.js";
import {
  DATA, ROOT, backup, condition, elseBranch, endBranch, endEvent, event, graphic,
  ifScript, installMapInfos, installMetadata, installTrainerTypes, installTrainers,
  page, pagesOf, readData, readMapRaw, script, selfSwitch, switchOn, texts, transfer,
  upsert, eventsOf, iv, makeChecker, wait, writeData, S, txt, grid, walkableAt,
} from "./lib/dlc_helpers.mjs";
import { TileCanvas, buildMapObject, loadSourceMap, tilesets } from "./lib/map_painter.mjs";

const VERIFY = process.argv.includes("--verify");
const ONLY = process.argv.find((arg) => arg.startsWith("--campaign="))?.split("=")[1] ?? null;
const PLAN_PATH = path.join(ROOT, "content", "rom_campaigns_complete.json");
const PLAN = JSON.parse(fs.readFileSync(PLAN_PATH, "utf8"));
const MARKER = "PokeMod Campaña ROM:";
const BACKUP = "complete_rom_campaigns";
const MAIN_CITY_MAP = 1001;
const LEAGUE_MAP = 643;
const GUIDE_NAME = `${MARKER} Cynthia — Guía de la fragmentación`;
const NORMAL_CAMPAIGNS = new Set(["glazed", "light_platinum", "liquid_crystal", "unbound"]);
const FIRST_MAP_SPAWN = {
  glazed: { x: 3, y: 3 },
  light_platinum: { x: 2, y: 2 },
  liquid_crystal: { x: 2, y: 3 },
  tfoh: { x: 2, y: 2 },
  unbound: { x: 10, y: 11 },
};
const BGM = {
  glazed: "Sinnoh Route.ogg",
  light_platinum: "Sinnoh Route.ogg",
  liquid_crystal: "Johto Route.ogg",
  tfoh: "Kanto Route.ogg",
  unbound: "Kanto Route.ogg",
};
const TEAMS = {
  glazed: ["GLACEON", "LUCARIO", "GARCHOMP", "ROTOM", "TOGEKISS", "KYUREM"],
  light_platinum: ["LUXRAY", "MILOTIC", "BRAVIARY", "VOLCARONA", "METAGROSS", "ZACIAN"],
  liquid_crystal: ["MEGANIUM", "TYPHLOSION", "FERALIGATR", "AMPHAROS", "UMBREON", "SUICUNE"],
  tfoh: ["VENUSAUR", "CHARIZARD", "BLASTOISE", "RAICHU", "DRAGONITE", "MEWTWO"],
  unbound: ["EMPOLEON", "LUCARIO", "GARCHOMP", "METAGROSS", "TOGEKISS", "ZOROARK"],
};
const campaigns = PLAN.campaigns.filter((campaign) => !ONLY || campaign.id === ONLY);
if (!campaigns.length) throw new Error(`Campaña desconocida: ${ONLY}`);

const pad = (n) => String(n).padStart(3, "0");
const mapPath = (id) => path.join(DATA, `Map${pad(id)}.rxdata`);
const flatten = (value) => value.flat(Infinity).filter(Boolean);
const returnMap = (campaign) => Number(campaign.returnMapId ?? campaign.lobbyMapId);
const isAshProtagonist = (campaign) => campaign.playerRole === "ash_protagonist";

function floorPalette(donorIds) {
  const passages = tilesets().get(1)?.passages?.data ?? [];
  const result = new Map();
  for (const id of donorIds) {
    const donor = loadSourceMap(id);
    const count = new Map();
    for (let y = 0; y < donor.height; y += 1) for (let x = 0; x < donor.width; x += 1) {
      const tile = tableGet(donor.table, x, y, 0);
      if (tile && (passages[tile] ?? 0) === 0) count.set(tile, (count.get(tile) ?? 0) + 1);
    }
    const floors = [...count.entries()].sort((a, b) => b[1] - a[1]).map(([tile]) => tile);
    if (!floors.length) throw new Error(`El donante Map${id} no tiene suelo transitable de tileset 1`);
    result.set(id, floors);
  }
  return { passages, result };
}

function paintMap(campaign, blueprint, palette) {
  const desiredEvents = blueprint.npcs.length + blueprint.warps.length + 6;
  const minSide = Math.ceil(Math.sqrt(desiredEvents)) + 4;
  const width = Math.max(blueprint.dimensions.width, minSide, 8);
  const height = Math.max(blueprint.dimensions.height, minSide, 8);
  const canvas = new TileCanvas(width, height, 1);
  for (let y = 0; y < height; y += 1) {
    const row = blueprint.visualRows[y % blueprint.visualRows.length];
    const donor = loadSourceMap(row.donorMapId);
    const floors = palette.result.get(row.donorMapId);
    for (let x = 0; x < width; x += 1) {
      const sx = (x + row.floorPhase) % donor.width;
      const sy = (y + blueprint.sequence + row.floorPhase) % donor.height;
      let floor = tableGet(donor.table, sx, sy, 0);
      if (!floor || (palette.passages[floor] ?? 0) !== 0) floor = floors[(x + y + row.floorPhase) % Math.min(floors.length, 12)];
      canvas.set(x, y, 0, floor);
      if ((x + row.floorPhase) % row.accentEvery === 0 && x > 1 && y > 1 && x < width - 2 && y < height - 2) {
        for (const z of [1, 2]) {
          const accent = tableGet(donor.table, sx, sy, z);
          if (accent && (palette.passages[accent] ?? 0) === 0) canvas.set(x, y, z, accent);
        }
      }
    }
  }
  return canvas;
}

function allocator(width, height) {
  const used = new Set();
  const reserve = (hx, hy) => {
    for (let radius = 0; radius < Math.max(width, height); radius += 1) {
      for (let dy = -radius; dy <= radius; dy += 1) for (let dx = -radius; dx <= radius; dx += 1) {
        const x = Math.max(1, Math.min(width - 2, hx + dx));
        const y = Math.max(1, Math.min(height - 2, hy + dy));
        const key = `${x},${y}`;
        if (!used.has(key)) { used.add(key); return [x, y]; }
      }
    }
    throw new Error(`Sin celdas para eventos en ${width}×${height}`);
  };
  return reserve;
}

function visitorEvent(campaign, name, npc, xy) {
  const gfx = graphic(`trchar${String((npc.sourceSprite % 66) + 1).padStart(3, "0")}`, 2, 1, {});
  if (!npc.trainer) return event(0, `${MARKER} NPC — ${name}`, xy[0], xy[1], [
    page({ gfx, list: [...texts(npc.dialoguePlan), endEvent()] }),
  ]);
  const winLines = isAshProtagonist(campaign)
    ? ["Ash: ¡Buena batalla! Me gusta que podamos seguir viajando después de medir fuerzas."]
    : ["Has comprendido este tramo sin apropiarte de él."];
  return event(0, `${MARKER} Entrenador — ${name}`, xy[0], xy[1], [
    page({ gfx, list: flatten([
      texts(npc.dialoguePlan),
      script(`pbTrainerIntro(:${npc.trainerType})`),
      ifScript(`pbTrainerBattle(:${npc.trainerType},"${npc.trainerName}",nil,false,0,true)`),
      texts(winLines, 1),
      selfSwitch("A", 0, 1),
      elseBranch(),
      texts(["Puedes reintentarlo o seguir explorando: aquí una derrota no encierra a nadie."], 1),
      endBranch(), script("pbTrainerEnd"), endEvent(),
    ]) }),
    page({ cond: condition({ self: "A" }), gfx, list: [...texts(["Nuestro combate ya forma parte del viaje. Sigue escuchando a esta dimensión."]), endEvent()] }),
  ]);
}

function navigationEvent(name, xy, target, lines, extra = [], targetX = 2, targetY = 2) {
  return event(0, `${MARKER} ${name}`, xy[0], xy[1], [
    page({ list: flatten([texts(lines), extra, transfer(target, targetX, targetY), endEvent()]) }),
  ]);
}

function finaleEvent(campaign, xy) {
  const trainerName = `${campaign.id.toUpperCase()}_FINAL`;
  const opening = isAshProtagonist(campaign)
    ? "Guardián: Ash, ya formas parte de esta historia sin dejar de ser tú. Tu manera de ayudar también cuenta."
    : `Guardián de ${campaign.title}: Ash, has recorrido este lugar sin exigir que te pertenezca.`;
  return event(0, `${MARKER} Final — ${campaign.title}`, xy[0], xy[1], [
    page({ gfx: graphic("trchar052", 2, 1, {}), list: flatten([
      texts([opening, "Este combate no decide quién posee la dimensión; decide qué aprendiste al escucharla."]),
      script(`pbTrainerIntro(:${campaign.trainerType})`),
      ifScript(`pbTrainerBattle(:${campaign.trainerType},"${trainerName}",nil,false,0,true)`),
      switchOn(campaign.completeSwitch, 1),
      texts(["La campaña queda completa. Sus rutas permanecen abiertas para volver cuando quieras."], 1),
      script("pbReceiveItem(:RARECANDY)", 1), selfSwitch("A", 0, 1),
      elseBranch(), texts(["El archivo espera. Puedes curarte, volver al puerto o intentarlo otra vez."], 1), endBranch(),
      script("pbTrainerEnd"), endEvent(),
    ]) }),
    page({ cond: condition({ self: "A" }), gfx: graphic("trchar052", 2, 1, {}), list: [
      ...texts([`La experiencia de ${campaign.title} está completa, pero sus ${campaign.mapCount} mapas siguen abiertos.`]), endEvent(),
    ] }),
  ]);
}

function compileMap(campaign, blueprint, palette) {
  const canvas = paintMap(campaign, blueprint, palette);
  const raw = buildMapObject(canvas, { bgm: BGM[campaign.id], encounterStep: 25 });
  const take = allocator(canvas.width, canvas.height);
  const pairs = [];
  let id = 1;
  const add = (object) => { object.setIvar("@id", id); pairs.push([id, object]); id += 1; };

  // El acceso desde los portales aterriza siempre en una celda vacía y transitable.
  take(2, 2);
  const returnedTo = returnMap(campaign);
  const portalX = campaign.cityPortal ? campaign.cityPortal.x : 34;
  const portalY = campaign.cityPortal ? campaign.cityPortal.y + 1 : 23;
  add(navigationEvent("Retorno libre", take(1, 1), returnedTo,
    [`Regresar a ${campaign.cityName ?? "Puerto Horizonte"}. El retorno nunca está condicionado.`], [],
    returnedTo === MAIN_CITY_MAP ? portalX : 2,
    returnedTo === MAIN_CITY_MAP ? portalY : 2));
  add(navigationEvent("Tramo anterior", take(1, canvas.height - 2), blueprint.linearLinks.previous,
    [blueprint.sequence === 1 ? "Volver a Puerto Horizonte." : `Volver al tramo ${blueprint.sequence - 1}.`], [],
    blueprint.linearLinks.previous === MAIN_CITY_MAP ? portalX : 2,
    blueprint.linearLinks.previous === MAIN_CITY_MAP ? portalY : 2));
  add(navigationEvent("Tramo siguiente", take(canvas.width - 2, canvas.height - 2), blueprint.linearLinks.next,
    [blueprint.finale ? "La ruta principal vuelve a Puerto Horizonte." : `Avanzar al tramo ${blueprint.sequence + 1} de ${campaign.mapCount}.`],
    [script(`$game_variables[${campaign.progressVariable}] = [$game_variables[${campaign.progressVariable}], ${Math.min(campaign.mapCount, blueprint.sequence + 1)}].max`)],
    blueprint.linearLinks.next === MAIN_CITY_MAP ? portalX : 2,
    blueprint.linearLinks.next === MAIN_CITY_MAP ? portalY : 2));

  for (let i = 0; i < blueprint.warps.length; i += 1) {
    const warp = blueprint.warps[i];
    const target = warp.targetMapId ?? warp.fallbackMapId;
    add(navigationEvent(`Warp ${i + 1}`, take(warp.x, warp.y), target,
      [`Enlace reconstruido del banco ${blueprint.source.bank}, mapa ${blueprint.source.map}.`, "La geometría se adaptó a Fire Ash; el destino conserva su relación estructural."]));
  }
  for (let i = 0; i < blueprint.npcs.length; i += 1) {
    const npc = blueprint.npcs[i];
    add(visitorEvent(campaign, `${campaign.id}_${blueprint.sequence}_${i + 1}`, npc, take(npc.x, npc.y)));
  }
  if (blueprint.finale) add(finaleEvent(campaign, take(Math.floor(canvas.width / 2), Math.floor(canvas.height / 2))));
  raw.setIvar("@events", new RHash(pairs));
  fs.writeFileSync(mapPath(blueprint.mapId), Buffer.from(marshalDump(raw)));
  return { width: canvas.width, height: canvas.height, events: pairs.length };
}

function trainerRecords(campaign) {
  const records = [];
  const team = TEAMS[campaign.id];
  for (const map of campaign.maps) for (let i = 0; i < map.npcs.length; i += 1) {
    const npc = map.npcs[i];
    if (!npc.trainer) continue;
    npc.trainerType = campaign.trainerType;
    npc.trainerName = `${campaign.id.toUpperCase()}_${map.sequence}_${i + 1}`;
    const count = 3 + ((map.sequence + i) % 4);
    const rotated = Array.from({ length: count }, (_, k) => team[(k + map.sequence + i) % team.length]);
    records.push({ tipo: campaign.trainerType, nombre: npc.trainerName, equipo: rotated, nivel: Math.min(150, 72 + Math.floor((map.sequence / campaign.mapCount) * 70)), derrota: "Ash respetó la historia de este lugar." });
  }
  records.push({ tipo: campaign.trainerType, nombre: `${campaign.id.toUpperCase()}_FINAL`, equipo: team, nivel: 145, derrota: `La memoria de ${campaign.title} queda abierta.` });
  return records;
}

function installLobbyPortal(campaign) {
  if (campaign.legacyLobbyEnabled === false || campaign.lobbyMapId === MAIN_CITY_MAP) return;
  upsert(campaign.lobbyMapId, [`${MARKER} Acceso completo — ${campaign.title}`], () => {
    const all = eventsOf(campaign.lobbyMapId);
    const occupied = new Set(all.map((entry) => `${iv(entry.obj, "@x")},${iv(entry.obj, "@y")}`));
    let x = 2, y = 2;
    while (occupied.has(`${x},${y}`)) { x += 1; if (x > 12) { x = 2; y += 1; } }
    const roleText = isAshProtagonist(campaign)
      ? "Ash cruza como protagonista de una historia propia; conserva su carácter y decide cómo ayudar."
      : "Ash entra como visitante. Hay retorno libre desde cada mapa y las derrotas permiten reintentar.";
    const spawn = FIRST_MAP_SPAWN[campaign.id] ?? { x: 2, y: 2 };
    return [event(0, `${MARKER} Acceso completo — ${campaign.title}`, x, y, [
      page({ gfx: graphic("ARCEUS_GATE", 2, 1, {}), list: [...texts(["El archivo completo permanece sellado hasta terminar La Ruta de Dios."]), endEvent()] }),
      page({ cond: condition({ sw: campaign.routeOfGodSwitch }), gfx: graphic("ARCEUS_GATE", 2, 1, {}), list: flatten([
        texts([`${campaign.title}: adaptación estructural de ${campaign.mapCount} mapas.`, roleText]),
        script(`$game_variables[${campaign.progressVariable}] = [$game_variables[${campaign.progressVariable}], 1].max`),
        transfer(campaign.firstMapId, spawn.x, spawn.y), endEvent(),
      ]) }),
    ])];
  }, BACKUP);
}

function cityPortalEvent(campaign) {
  const { x, y } = campaign.cityPortal;
  const spawn = FIRST_MAP_SPAWN[campaign.id] ?? { x: 2, y: 2 };
  const intro = {
    glazed: "Dos caminos de vida se rozan en Glazed; Ash conocerá a quienes sostienen cada uno.",
    light_platinum: "Light Platinum abre rutas nuevas y una liga viajera, con sus propios compañeros y rivales.",
    liquid_crystal: "Liquid Crystal guarda una historia de Johto, sus recuerdos, sus faros y sus vínculos.",
    unbound: "Pokémon Unbound cuenta una historia de frontera, decisiones difíciles y gente que protege su hogar.",
  }[campaign.id] ?? `${campaign.title} tiene una historia propia.`;
  return event(0, `${MARKER} Portal de Puerto Horizonte — ${campaign.title}`, x, y, [
    page({ gfx: graphic("ARCEUS_GATE", 2, 1, {}), list: [
      ...texts(["La grieta sigue dormida. Cynthia dijo que sólo respondería después de completar La Ruta de Dios."]), endEvent(),
    ] }),
    page({ cond: condition({ sw: campaign.routeOfGodSwitch }), gfx: graphic("ARCEUS_GATE", 2, 1, {}), list: flatten([
      texts([`${campaign.title}: ${intro}`, "Ash: No necesito convertirme en otra persona para vivir esta aventura. ¡Pikachu, vamos!", "¿Cruzar el portal y volver a Puerto Horizonte cuando quieras?" ]),
      script(`$game_variables[${campaign.progressVariable}] = [$game_variables[${campaign.progressVariable}], 1].max`),
      transfer(campaign.firstMapId, spawn.x, spawn.y), endEvent(),
    ]) }),
  ]);
}

function installCityPortals() {
  const cityCampaigns = campaigns.filter((campaign) => NORMAL_CAMPAIGNS.has(campaign.id) && campaign.cityPortal);
  const prefixes = cityCampaigns.map((campaign) => `${MARKER} Portal de Puerto Horizonte — ${campaign.title}`);
  upsert(MAIN_CITY_MAP, prefixes, () => cityCampaigns.map(cityPortalEvent), BACKUP);
}

function installCynthiaGuide() {
  upsert(LEAGUE_MAP, [GUIDE_NAME], () => [event(0, GUIDE_NAME, 18, 12, [
    page({ gfx: graphic("trchar198", 2, 1, {}), list: flatten([
      texts([
        "Cynthia: Ash, lo que sientes es la fragmentación: las rutas entre mundos se han separado, no desaparecido.",
        "Cada mundo conserva su gente, sus decisiones y una historia que ya estaba en marcha antes de nuestra llegada.",
      ]),
      wait(18),
      texts(["Ash: Entonces no vamos a tratar esos lugares como escenarios vacíos. Vamos a conocerlos y ayudar si hace falta."], 1),
      wait(14),
      texts([
        "Cynthia: En Puerto Horizonte, busca la plaza de portales justo al este y sudeste del portal Atlas. Los cuatro arcos tienen su nombre.",
        "Liquid Crystal: el arco más cercano al portal Atlas; su camino conduce a una historia propia de Johto.",
        "Light Platinum: el arco situado más al sur; allí te esperan rutas nuevas y una liga itinerante.",
        "Glazed: el arco del sudeste, algo más apartado; sus dos caminos guardan recuerdos distintos.",
        "Pokémon Unbound: el arco del extremo oriental; su región fronteriza tiene dilemas e historias propias.",
        "Las cuatro entradas se activan al completar La Ruta de Dios. Desde cualquier mundo puedes volver libremente a Puerto Horizonte.",
      ]),
      wait(12),
      selfSwitch("A", 0), endEvent(),
    ]) }),
    page({ cond: condition({ self: "A" }), gfx: graphic("trchar198", 2, 1, {}), list: flatten([
      texts([
        "Cynthia: Recuerda, Ash: no tienes que dejar de ser tú para formar parte de otra historia.",
        "Los cuatro portales de Puerto Horizonte, junto al este del portal Atlas, conservan el nombre de su mundo y un regreso abierto.",
      ]),
      endEvent(),
    ]) }),
  ])], BACKUP);
}

function installCampaignNames() {
  backup(BACKUP, ["System.rxdata"]);
  const system = readData("System.rxdata");
  const switches = iv(system, "switches") ?? [];
  const variables = iv(system, "variables") ?? [];
  for (const campaign of campaigns) {
    switches[campaign.completeSwitch] = S(`POKEMOD ${campaign.id.toUpperCase()} COMPLETADA`);
    variables[campaign.progressVariable] = S(`POKEMOD ${campaign.id.toUpperCase()} PROGRESO`);
  }
  system.setIvar("switches", switches);
  system.setIvar("variables", variables);
  writeData("System.rxdata", system);
}

function install() {
  const specs = [];
  const trainerTypes = [];
  const trainers = [];
  const built = [];
  for (const campaign of campaigns) {
    const palette = floorPalette(campaign.donors);
    const roleName = isAshProtagonist(campaign) ? "Ash · protagonista" : "Ash · visitante";
    trainerTypes.push({ id: campaign.trainerType, base: "GENTLEMAN", nombre: `${campaign.title} · ${roleName}` });
    trainers.push(...trainerRecords(campaign));
    for (const map of campaign.maps) {
      built.push({ campaign: campaign.id, mapId: map.mapId, ...compileMap(campaign, map, palette) });
      specs.push({ mapId: map.mapId, title: map.title, parentId: campaign.lobbyMapId, order: 950 + map.sequence });
    }
  }
  installMapInfos(specs, BACKUP);
  installMetadata(specs, BACKUP);
  installTrainerTypes(trainerTypes, BACKUP);
  const trainerResult = installTrainers(trainers, BACKUP);
  installCampaignNames();
  for (const campaign of campaigns) installLobbyPortal(campaign);
  if (campaigns.some((campaign) => NORMAL_CAMPAIGNS.has(campaign.id))) {
    installCityPortals();
    installCynthiaGuide();
  }
  console.log(`✔ Prototipos estructurales compilados: ${built.length} mapas, ${trainers.length} entrenadores adaptados.`);
  console.log(`  · altas nuevas de entrenador: ${trainerResult.filter((r) => r.added).length}`);
  return built;
}

function verify() {
  const check = makeChecker("Integración estructural de campañas invitadas");
  let maps = 0, npcs = 0, warps = 0, sourceTrainers = 0, finals = 0;
  for (const campaign of campaigns) {
    check.ok(campaign.routeOfGodSwitch === 876, `${campaign.title}: no exige completar La Ruta de Dios`);
    const legacyPortal = eventsOf(campaign.lobbyMapId).find((entry) => entry.name === `${MARKER} Acceso completo — ${campaign.title}`);
    if (campaign.legacyLobbyEnabled !== false && campaign.lobbyMapId !== MAIN_CITY_MAP) {
      check.ok(!!legacyPortal, `${campaign.title}: falta el acceso de compatibilidad en Map${campaign.lobbyMapId}`);
      if (legacyPortal) {
        const open = pagesOf(legacyPortal)[1];
        check.ok(Number(iv(open.condition, "@switch1_id")) === 876, `${campaign.title}: acceso sin switch 876`);
        check.ok(open.list.some((command) => command.code === 201 && Number(command.params[1]) === campaign.firstMapId), `${campaign.title}: el acceso no lleva al primer mapa`);
      }
    }
    for (const blueprint of campaign.maps) {
      maps += 1; npcs += blueprint.npcs.length; warps += blueprint.warps.length;
      sourceTrainers += blueprint.npcs.filter((npc) => npc.trainer).length;
      if (blueprint.finale) finals += 1;
      check.ok(blueprint.npcs.length <= 4, `Map${blueprint.mapId}: excede el máximo de 4 actores del plano A`);
      check.ok(fs.existsSync(mapPath(blueprint.mapId)), `${campaign.title}: falta Map${blueprint.mapId}`);
      if (!fs.existsSync(mapPath(blueprint.mapId))) continue;
      const raw = readMapRaw(blueprint.mapId);
      const width = Number(iv(raw, "@width")), height = Number(iv(raw, "@height"));
      const events = eventsOf(blueprint.mapId);
      check.ok(events.some((entry) => entry.name === `${MARKER} Retorno libre`), `Map${blueprint.mapId}: falta retorno libre`);
      check.ok(events.some((entry) => entry.name === `${MARKER} Tramo siguiente`), `Map${blueprint.mapId}: falta avance lineal`);
      check.ok(events.filter((entry) => entry.name.startsWith(`${MARKER} NPC —`) || entry.name.startsWith(`${MARKER} Entrenador —`)).length === blueprint.npcs.length,
        `Map${blueprint.mapId}: NPC incompletos`);
      check.ok(events.filter((entry) => entry.name.startsWith(`${MARKER} Warp `)).length === blueprint.warps.length,
        `Map${blueprint.mapId}: warps incompletos`);
      const actors = events.filter((entry) => entry.name.startsWith(`${MARKER} NPC —`) || entry.name.startsWith(`${MARKER} Entrenador —`) || entry.name.startsWith(`${MARKER} Final —`)).length;
      check.ok(actors <= 5, `Map${blueprint.mapId}: ${actors} actores; el límite postgame es 5`);
      for (const entry of events) {
        const x = Number(iv(entry.obj, "@x")), y = Number(iv(entry.obj, "@y"));
        check.ok(x >= 0 && y >= 0 && x < width && y < height, `Map${blueprint.mapId}: evento fuera de límites`);
      }
      if (blueprint.sequence === 1 || blueprint.finale) {
        const nav = events.find((entry) => entry.name === `${MARKER} ${blueprint.sequence === 1 ? "Tramo anterior" : "Tramo siguiente"}`);
        const target = nav && pagesOf(nav)[0].list.find((command) => command.code === 201)?.params[1];
        check.ok(Number(target) === returnMap(campaign), `Map${blueprint.mapId}: el extremo de campaña no retorna a Puerto Horizonte`);
      }
    }
    const finalEvents = eventsOf(campaign.lastMapId);
    check.ok(finalEvents.some((entry) => entry.name === `${MARKER} Final — ${campaign.title}`), `${campaign.title}: falta final de campaña`);
  }
  check.ok(maps === PLAN.totals.maps, `se esperaban ${PLAN.totals.maps} mapas y hay ${maps}`);
  check.ok(npcs === PLAN.totals.npcs, `se esperaban ${PLAN.totals.npcs} actores adaptados y hay ${npcs}`);
  check.ok(warps === PLAN.totals.warps, `se esperaban ${PLAN.totals.warps} warps y hay ${warps}`);
  check.ok(sourceTrainers + finals === PLAN.totals.trainers + campaigns.length, `recuento de entrenadores adaptados inconsistente`);

  const guide = eventsOf(LEAGUE_MAP).find((entry) => entry.name === GUIDE_NAME);
  if (campaigns.some((campaign) => NORMAL_CAMPAIGNS.has(campaign.id))) {
    check.ok(!!guide, "Liga de Sinnoh: falta la guía de Cynthia");
    if (guide) {
      check.ok(Number(iv(guide.obj, "@x")) === 18 && Number(iv(guide.obj, "@y")) === 12, "Cynthia no está en la celda lateral prevista");
      check.ok(pagesOf(guide).length === 2, "Cynthia debe tener diálogo inicial y recordatorio breve");
      check.ok(txt(iv(pagesOf(guide)[0].obj.getIvar("@graphic"), "@character_name")) === "trchar198", "La guía no usa el sprite original de Cynthia");
    }
    const city = eventsOf(MAIN_CITY_MAP);
    const cityGrid = grid(MAIN_CITY_MAP);
    for (const campaign of campaigns.filter((item) => NORMAL_CAMPAIGNS.has(item.id) && item.cityPortal)) {
      const name = `${MARKER} Portal de Puerto Horizonte — ${campaign.title}`;
      const portal = city.find((entry) => entry.name === name);
      check.ok(!!portal, `Puerto Horizonte: falta el portal a ${campaign.title}`);
      if (!portal) continue;
      const { x, y } = campaign.cityPortal;
      check.ok(Number(iv(portal.obj, "@x")) === x && Number(iv(portal.obj, "@y")) === y, `${campaign.title}: coordenadas de portal incorrectas`);
      check.ok(walkableAt(cityGrid, x, y), `${campaign.title}: portal en celda no transitable de Map1001`);
      check.ok(!city.some((entry) => entry.name !== name && Number(iv(entry.obj, "@x")) === x && Number(iv(entry.obj, "@y")) === y), `${campaign.title}: portal solapa otro evento de Map1001`);
      const pages = pagesOf(portal);
      check.ok(pages.length === 2 && Number(iv(pages[1].condition, "@switch1_id")) === 876, `${campaign.title}: portal sin bloqueo postgame`);
      check.ok(pages[1].list.some((command) => command.code === 201 && Number(command.params[1]) === campaign.firstMapId), `${campaign.title}: portal no llega al primer mapa`);
    }
  }
  check.done();
  console.log(`  · ${maps} mapas · ${npcs} actores adaptados · ${warps} warps · ${sourceTrainers + finals} combates · 4 portales urbanos · guía de Cynthia`);
}

if (VERIFY) verify();
else { install(); verify(); }#!/usr/bin/env node
/**
 * apply_dimensional_nightmare_battles.mjs — E4 fase B: jefes completos, trainers y objetos.
 *
 * Sobre lo ya instalado por `apply_dimensional_nightmare_events.mjs`:
 *   1. OBJETOS: registra en `items.dat` las recompensas del ciclo (`DN_PAGE_*`, `DN_ANCLA`, etc.)
 *      con su icono 48×48 en `Graphics/Items/` (sin icono el juego puede fallar al mostrarlos).
 *   2. TRAINERS: registra en `trainers.dat` los 9 entrenadores de fase A (`DN_EPxx_A`, `DN_Wx_A`)
 *      con los equipos que cada doc declara, sin sustituir entrenadores base.
 *   3. FASE B: instala los eventos de escenario que el doc pide para cada jefe con un contador
 *      independiente por mundo (v289–v297), gated por la victoria de fase A y el paso anterior.
 *      Cada paso se cierra con self-switch A; sólo el último sella el episodio, actualiza la
 *      resonancia, entrega la recompensa y activa la página de epílogo.
 *
 * No toca partidas. Backups en `pokemon_fire_ash/PokeModBackups/dimensional_nightmare_battles_originals/`.
 *
 * Uso:
 *   node tools/apply_dimensional_nightmare_battles.mjs --all
 *   node tools/apply_dimensional_nightmare_battles.mjs --episode EP01
 *   node tools/apply_dimensional_nightmare_battles.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas } from "@napi-rs/canvas";
import { marshalLoad, marshalDump, RHash, RObject, RString, RSymbol } from "../web/js/marshal.js";
import { parseMap } from "../web/js/rmxp.js";
import { passabilityOf } from "./lib/map_painter.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const ITEM_ICONS = path.join(GAME, "Graphics", "Items");
const BACKUP = path.join(GAME, "PokeModBackups", "dimensional_nightmare_battles_originals");
const BLUEPRINT = path.join(ROOT, "content", "dimensional_nightmare_events.json");
const BUILT = path.join(ROOT, "content", "dimensional_nightmare_events_built.json");
const CATALOG = path.join(ROOT, "content", "dimensional_nightmare_battles_built.json");

const argv = process.argv.slice(2);
const option = (name, fallback) => {
  const at = argv.indexOf(name);
  return at >= 0 && argv[at + 1] ? argv[at + 1] : fallback;
};
const EPISODE = option("--episode", null);
const ALL = argv.includes("--all");
const VERIFY = argv.includes("--verify");
const DRY = argv.includes("--dry-run");

// Fase A: switches 903–908 / 928–930. Fase B: contadores propios 289–297; v264 queda externo/read-only.
const PHASE_B_VARIABLE_BASE = 289; // un contador independiente para cada uno de los nueve mundos
const ITEM_ID_BASE = 1032;       // ids libres de items.dat
const PHASE_A_SWITCHES = Object.freeze({
  EP01: 903, EP02: 904, EP03: 905, EP04: 906, EP05: 907, EP06: 908,
  W7: 928, W8: 929, W9: 930,
});
const WITNESS_SEALS = [883, 884, 885, 886, 887, 888, 922, 923, 924];
const WITNESS_CHECK = `begin; $game_switches[931] = [${WITNESS_SEALS.map((id) => `$game_switches[${id}]`).join(", ")}].all?; rescue; end`;
const ROTOM_LEVEL_UPDATE =
  "$game_variables[275] = 0; $game_variables[275] = 1 if $game_variables[265] >= 20; " +
  "$game_variables[275] = 2 if $game_variables[265] >= 40; $game_variables[275] = 3 if $game_variables[265] >= 60; " +
  "$game_variables[275] = 4 if $game_variables[265] >= 80; $game_variables[275] = 5 if $game_variables[265] >= 100";
function phaseASwitch(ep) {
  const id = ep.bossSwitch ?? PHASE_A_SWITCHES[ep.key];
  if (!id) throw new Error(`${ep.key}: falta switch de fase A`);
  return id;
}
function phaseBVariable(ep) {
  const index = bossEpisodes.findIndex((candidate) => candidate.key === ep.key);
  if (index < 0) throw new Error(`${ep.key}: falta índice de variable de fase B`);
  return PHASE_B_VARIABLE_BASE + index;
}
function phaseBTotal(ep) {
  const spec = ep.boss.phaseB;
  return spec.maps?.length || spec.cells?.length || (spec.kind === "letras" ? 7 : 4);
}

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => { if (!DRY) fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value))); };
const S = (v) => RString.fromText(String(v));
const Sym = (v) => new RSymbol(String(v));
const txt = (v) => (v instanceof RString ? v.text : String(v ?? ""));
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;

const blueprint = JSON.parse(fs.readFileSync(BLUEPRINT, "utf8"));
const bossEpisodes = blueprint.episodes.filter((episode) => episode.boss);
const built = fs.existsSync(BUILT) ? JSON.parse(fs.readFileSync(BUILT, "utf8")).maps ?? {} : {};
const episodes = blueprint.episodes.filter((ep) => ep.boss && (ALL || !EPISODE || ep.key === EPISODE));
const warnings = [];
const result = { generatedBy: "tools/apply_dimensional_nightmare_battles.mjs", flags: { phaseASwitches: PHASE_A_SWITCHES, phaseBCounterBase: PHASE_B_VARIABLE_BASE, witnessSwitch: 931, itemIdBase: ITEM_ID_BASE }, episodes: {}, items: [] };

// --------------------------------------------------------------- RMXP bits
const cmd = (code, params = [], indent = 0) => new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", params]]);
const script = (text) => cmd(355, [S(text)]);
const texts = (lines) => [cmd(101, [S("")]), ...[].concat(lines).map((line) => cmd(401, [S(line)]))];
const condition = ({ sw = 0, sw2 = 0, self = "", variable = null } = {}) => new RObject("RPG::Event::Page::Condition", [
  ["@switch1_valid", !!sw], ["@switch1_id", sw || 1],
  ["@switch2_valid", !!sw2], ["@switch2_id", sw2 || 1],
  ["@variable_valid", !!variable], ["@variable_id", variable ? variable[0] : 1], ["@variable_value", variable ? variable[1] : 0],
  ["@self_switch_valid", !!self], ["@self_switch_ch", S(self || "A")],
]);
const graphic = (charName = "", dir = 2, pattern = 1, opts = {}) => new RObject("RPG::Event::Page::Graphic", [
  ["@tile_id", opts.tile ?? 0], ["@character_name", S(charName)], ["@character_hue", 0],
  ["@direction", dir], ["@pattern", pattern], ["@opacity", opts.opacity ?? 255], ["@blend_type", 0],
]);
const moveRoute = () => new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", false], ["@list", []]]);
const page = ({ cond = condition(), gfx = graphic(), trigger = 0, through = false, list = [cmd(0)] } = {}) => new RObject("RPG::Event::Page", [
  ["@condition", cond], ["@graphic", gfx],
  ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
  ["@move_route", moveRoute()], ["@walk_anime", true], ["@step_anime", false],
  ["@direction_fix", false], ["@through", through], ["@always_on_top", false],
  ["@trigger", trigger], ["@list", list],
]);
const event = (id, name, x, y, pages) => new RObject("RPG::Event", [["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]]);
const selfSwitch = (channel = "A", indent = 0) => cmd(123, [S(channel), 0], indent);

/** Máscara transitable de un mapa del ciclo (misma fuente que el instalador de E4). */
const masks = {};
function maskOf(mapId) {
  if (masks[mapId]) return masks[mapId];
  const parsed = parseMap(read(mapFile(mapId)));
  const pass = passabilityOf(parsed, parsed.tilesetId);
  masks[mapId] = { pass, width: parsed.width, height: parsed.height };
  return masks[mapId];
}
const walkAt = (mask, x, y) => x >= 0 && y >= 0 && x < mask.width && y < mask.height && mask.pass.passable(x, y, 8);

// ------------------------------------------------------------ items.dat
function installItems(list) {
  const items = read("items.dat");
  const ids = new Set(items.pairs.filter(([k]) => k instanceof RSymbol).map(([k]) => k.name));
  let next = Math.max(-1, ...items.pairs.filter(([k]) => typeof k === "number").map(([k]) => k)) + 1;
  next = Math.max(next, ITEM_ID_BASE);
  let added = 0;
  for (const item of list) {
    if (ids.has(item.id)) continue;
    const obj = new RObject("GameData::Item", [
      ["@id", Sym(item.id)], ["@id_number", next],
      ["@real_name", S(item.name)], ["@real_name_plural", S(item.namePlural ?? item.name)],
      ["@pocket", 8], ["@price", 0],
      ["@real_description", S(item.description)],
      ["@field_use", 0], ["@battle_use", 0], ["@type", 0], ["@move", null],
    ]);
    items.pairs.push([next, obj], [Sym(item.id), obj]);
    result.items.push({ id: item.id, idNumber: next });
    next++;
    added++;
  }
  write("items.dat", items);
  return added;
}

/** Icono 48×48: pergamino con el número de página (o el Ancla). */
function installItemIcons(list) {
  if (DRY) return 0;
  fs.mkdirSync(ITEM_ICONS, { recursive: true });
  let drawn = 0;
  for (const item of list) {
    const file = path.join(ITEM_ICONS, `${item.id}.png`);
    if (fs.existsSync(file)) continue;
    const canvas = createCanvas(48, 48);
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#2b2b2b";
    ctx.fillRect(0, 0, 48, 48);
    if (item.photo) {
      ctx.fillStyle = "#efe9dc";
      ctx.fillRect(6, 6, 36, 30);                 // copia
      ctx.fillStyle = item.photo === 4 ? "#f7f7f2" : "#5c6b7a";
      ctx.fillRect(9, 9, 30, 20);                 // imagen (la 4ª está en blanco)
      ctx.strokeStyle = "#2b2b2b";
      ctx.lineWidth = 2;
      ctx.strokeRect(6, 6, 36, 30);
      ctx.fillStyle = "#2b2b2b";
      ctx.fillRect(6, 36, 36, 6);                 // pie de foto
      ctx.fillStyle = "#c9a227";
      ctx.font = "bold 12px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(item.photo), 24, 39);
      fs.writeFileSync(file, canvas.toBuffer("image/png"));
      drawn++;
      continue;
    }
    ctx.fillStyle = item.page ? "#e8dcc0" : "#7fd8ff";
    ctx.fillRect(4, 3, 40, 42);
    ctx.strokeStyle = "#8a7856";
    ctx.strokeRect(4.5, 3.5, 39, 41);
    ctx.fillStyle = "#3a2f1c";
    ctx.font = "bold 26px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(item.page ? String(item.page) : "⚓", 24, 25);
    fs.writeFileSync(file, canvas.toBuffer("image/png"));
    drawn++;
  }
  return drawn;
}

// ------------------------------------------------------------ trainers.dat
function dataSymbols(file) {
  const ids = new Set();
  for (const [key] of read(file).pairs) if (key instanceof RSymbol) ids.add(key.name);
  return ids;
}
function pokemonData([species, level]) {
  return new RHash([[Sym("species"), Sym(species)], [Sym("level"), level]]);
}
function installTrainers(roster) {
  const species = dataSymbols("species.dat");
  const types = dataSymbols("trainer_types.dat");
  const items = dataSymbols("items.dat");
  for (const boss of roster) {
    if (!types.has(boss.type)) warnings.push(`${boss.trainer}: tipo de entrenador inexistente ${boss.type}`);
    if (boss.reward && !items.has(boss.reward)) warnings.push(`${boss.trainer}: recompensa inexistente ${boss.reward}`);
    for (const [sp] of boss.team) if (!species.has(sp)) warnings.push(`${boss.trainer}: especie inexistente ${sp}`);
  }
  const trainers = read("trainers.dat");
  let next = Math.max(-1, ...trainers.pairs.filter(([k]) => typeof k === "number").map(([k]) => k)) + 1;
  let added = 0;
  for (const boss of roster) {
    const key = [Sym(boss.type), S(boss.name), 0];
    const existing = trainers.pairs.find(([k]) => Array.isArray(k) && txt(k[1]) === boss.name && k[2] === 0);
    let trainerId = next;
    let obj;
    if (existing) {
      // Upsert the DN trainer: updating a curated EP06 roster must not leave the
      // stale all-Unown Lv120–125 party from an earlier build in trainers.dat.
      const existingKey = existing[0];
      obj = existing[1];
      trainerId = obj.getIvar("@id_number");
      existingKey[0] = key[0];
      existingKey[1] = key[1];
      existingKey[2] = 0;
      obj.setIvar("@id", existingKey);
      obj.setIvar("@trainer_type", key[0]);
      obj.setIvar("@real_name", S(boss.name));
      obj.setIvar("@version", 0);
      obj.setIvar("@items", [Sym("FULLRESTORE")]);
      obj.setIvar("@real_lose_text", S(boss.loss ?? "..."));
      obj.setIvar("@pokemon", boss.team.map(pokemonData));
    } else {
      obj = new RObject("GameData::Trainer", [
        ["@id", key], ["@id_number", trainerId], ["@trainer_type", key[0]],
        ["@real_name", S(boss.name)], ["@version", 0], ["@items", [Sym("FULLRESTORE")]],
        ["@real_lose_text", S(boss.loss ?? "...")], ["@numpkmn", 0], ["@guara", 0],
        ["@pokemon", boss.team.map(pokemonData)],
      ]);
      trainers.pairs.push([trainerId, obj], [key, obj]);
      next++;
      added++;
    }
    const prior = result.episodes[boss.episode] ?? {};
    const trainerRecord = { role: boss.role ?? "phaseA", trainer: boss.trainer, type: boss.type, name: boss.name, trainerId };
    const records = [...(prior.trainers ?? []), trainerRecord];
    result.episodes[boss.episode] = {
      ...prior,
      trainers: records,
      ...(trainerRecord.role === "final" ? { finalTrainer: trainerRecord.trainer, finalTrainerId: trainerId } : { trainer: boss.trainer, trainerId }),
    };
  }
  write("trainers.dat", trainers);
  return added;
}

// ------------------------------------------------------------ fase B (eventos)
const phaseBText = (spec, index) => spec.texts?.[index] ?? `${spec.noun} ${index + 1}`;
const KINGGUS_LETTERS = ["K", "I", "N", "G", "G", "U", "S"];
const KINGGUS_PREREQUISITES = [883, 884, 885, 886, 887];

/** Las siete letras son un puzzle previo a las batallas del Rey, no su fase posterior. */
function kinggusLetterStep(ep, index, total) {
  const letter = KINGGUS_LETTERS[index];
  const variable = phaseBVariable(ep);
  const seals = KINGGUS_PREREQUISITES.map((switchId) => `$game_switches[${switchId}]`).join(" && ");
  const prerequisites = `${seals} && $game_variables[264].to_i >= 7`;
  const inOrder = `$game_variables[${variable}].to_i == ${index}`;
  const list = [
    ...texts([`Pedestal ${index + 1}/7. La inscripción pide formar K-I-N-G-G-U-S de principio a fin.`]),
    cmd(111, [12, S(prerequisites)]),
    cmd(111, [12, S(inOrder)], 1),
    ...texts([`La letra ${letter} queda en su lugar. El suelo conserva el orden.`], 2),
    script(`$game_variables[${variable}] = ${index + 1}`, 2),
    ...(index === total - 1 ? texts(["La S completa KINGGUS. El Rey se levanta: primero deletreará; después dejará de tener letra."], 2) : []),
    selfSwitch("A", 2),
    cmd(411, [], 1),
    ...texts([`Esta letra llega después. La secuencia correcta es K-I-N-G-G-U-S; busca la siguiente letra pendiente.`], 2),
    cmd(412, [], 1),
    cmd(411),
    ...texts(["La puerta aún no reconoce el itinerario: sella EP01–EP05 y llega con las siete emisiones de Monte Silver (v264 = 7). No se modifica ese contador."], 1),
    cmd(412),
    cmd(0),
  ];
  const donePage = page({
    cond: condition({ self: "A" }), gfx: graphic(""), through: true,
    list: [...texts([`La letra ${letter} permanece escrita en el pedestal.`]), cmd(0)],
  });
  return [page({ cond: condition(), gfx: graphic(""), trigger: 0, through: true, list }), donePage];
}

/** Un paso ordenado, de un solo uso; el último cierra el episodio y sus flags dependientes. */
function phaseBStep(ep, spec, index, total) {
  if (ep.key === "EP06") return kinggusLetterStep(ep, index, total);
  const last = index === total - 1;
  const switchA = phaseASwitch(ep);
  const variable = phaseBVariable(ep);
  const list = [
    ...texts([phaseBText(spec, index)]),
    script(`$game_variables[${variable}] += 1`),
  ];
  if (last) {
    list.push(...texts([`El último gesto cierra el episodio: ${ep.bossName} se hunde.`]));
    list.push(cmd(121, [ep.seal, ep.seal, 0]));
    list.push(script(`$game_variables[265] = [$game_variables[265] + ${ep.resonance}, 100].min`));
    list.push(script(ROTOM_LEVEL_UPDATE));
    list.push(script(`begin; pbItemBall(:${ep.boss.reward}); rescue; pbMessage("(recompensa ${ep.boss.reward} pendiente)"); end`));
    if (ep.grieta) list.push(cmd(121, [ep.grieta, ep.grieta, 0]));
    list.push(script(WITNESS_CHECK));
  }
  // Cierra el evento después de todas las escrituras: cambiar de página no puede cortar el contador ni la recompensa.
  list.push(selfSwitch("A"));
  list.push(cmd(0));
  const usedPage = page({
    cond: condition({ sw: switchA, variable: [variable, index] }),
    gfx: graphic(""), trigger: 0, through: true, list,
  });
  const donePage = page({
    cond: condition({ self: "A" }), gfx: graphic(""), through: true,
    list: [...texts([`Este paso (${index + 1}/${total}) ya quedó registrado.`]), cmd(0)],
  });
  return [usedPage, donePage];
}

function installPhaseB(ep) {
  const spec = ep.boss.phaseB;
  const bossMap = ep.mapRange.to;
  // Los pasos pueden venir como celdas del mapa del jefe, como mapas sueltos (fogatas del EP03)
  // o sin ubicación (se reparten alrededor de la entrada del mapa del jefe).
  const targets = [];
  if (spec.maps?.length) {
    for (const mapId of spec.maps) targets.push([mapId, null]);
  } else if (spec.cells?.length) {
    for (const cell of spec.cells) targets.push([bossMap, cell]);
  }
  const total = targets.length || (spec.kind === "letras" ? 7 : 4);
  // sin celdas declaradas: se reparten en anillo alrededor de la entrada del mapa del jefe
  const fallbackCells = [];
  if (!targets.length) {
    const mask = maskOf(bossMap);
    const entry = built[bossMap]?.entry ?? [Math.floor(mask.width / 2), Math.floor(mask.height / 2)];
    for (let i = 0; i < total; i++) {
      const angle = (Math.PI * 2 * i) / total;
      const x = Math.min(mask.width - 2, Math.max(1, Math.round(entry[0] + Math.cos(angle) * 4)));
      const y = Math.min(mask.height - 2, Math.max(1, Math.round(entry[1] + Math.sin(angle) * 3)));
      fallbackCells.push([bossMap, [x, y]]);
    }
    warnings.push(`${ep.key}: la fase B (${spec.kind}) no declara celdas; se reparten alrededor de la entrada de ${bossMap}`);
  }

  const placed = [];
  const byMap = new Map();
  const used = new Map();   // celdas ya ocupadas por otros eventos (o por pasos previos)
  for (let i = 0; i < total; i++) {
    const [mapId, declared] = targets[i] ?? fallbackCells[i];
    const mask = maskOf(mapId);
    if (!used.has(mapId)) {
      const taken = new Set();
      for (const [, ev] of read(mapFile(mapId)).getIvar("@events").pairs) {
        // los pasos propios de este episodio no bloquean su propia celda declarada:
        // sin esto, cada pasada de dn:battles movía un poco los marcadores de fase B.
        if ((ev.getIvar("@name")?.text ?? "").startsWith(`BOSSB_${ep.key}_`)) continue;
        taken.add(`${ev.getIvar("@x")},${ev.getIvar("@y")}`);
      }
      used.set(mapId, taken);
    }
    const taken = used.get(mapId);
    // sin celda declarada: junto a la entrada de ese mapa
    const entryCell = built[mapId]?.entry ?? [Math.floor(mask.width / 2), Math.floor(mask.height / 2)];
    let [x, y] = declared ?? entryCell;
    if (!walkAt(mask, x, y) || taken.has(`${x},${y}`)) {
      // celda declarada fuera del suelo: se busca la transitable más cercana
      let best = null, bestD = Infinity;
      for (let j = 1; j < mask.height - 1; j++) {
        for (let k = 1; k < mask.width - 1; k++) {
          if (!walkAt(mask, k, j) || taken.has(`${k},${j}`)) continue;
          const d = Math.abs(k - x) + Math.abs(j - y);
          if (d < bestD) { bestD = d; best = [k, j]; }
        }
      }
      if (best) {
        if (declared) warnings.push(`${ep.key}: ${spec.noun} ${i + 1} movida de ${x},${y} a ${best[0]},${best[1]} (celda ocupada o bloqueada)`);
        [x, y] = best;
      } else {
        warnings.push(`${ep.key}: sin sitio libre para ${spec.noun} ${i + 1} en Map${mapId}`);
      }
    }
    taken.add(`${x},${y}`);
    if (!byMap.has(mapId)) byMap.set(mapId, []);
    byMap.get(mapId).push({ index: i, cell: [x, y] });
  }

  for (const [mapId, steps] of byMap) {
    const mapObject = read(mapFile(mapId));
    const hash = mapObject.getIvar("@events");
    let nextId = Math.max(0, ...hash.pairs.map(([k]) => Number(k))) + 1;
    for (const step of steps) {
      const name = `BOSSB_${ep.key}_${step.index + 1}`;
      const existing = hash.pairs.find(([, ev]) => ev.getIvar("@name")?.text === name);
      const built_event = event(nextId, name, step.cell[0], step.cell[1], phaseBStep(ep, spec, step.index, total));
      if (existing) existing[1] = built_event;
      else hash.pairs.push([nextId, built_event]);
      nextId++;
      placed.push({ map: mapId, cell: step.cell, step: step.index + 1 });
    }
    mapObject.setIvar("@events", hash);
    write(mapFile(mapId), mapObject);
  }
  return { kind: spec.kind, total, counterVariable: phaseBVariable(ep), phaseASwitch: phaseASwitch(ep), placed };
}

/** Epílogo del jefe: la última página del evento jefe pasa a depender del sello del episodio. */
function installBossEpilogue(ep) {
  const bossMap = ep.mapRange.to;
  const mapObject = read(mapFile(bossMap));
  const hash = mapObject.getIvar("@events");
  const boss = hash.pairs.find(([, ev]) => (ev.getIvar("@name")?.text ?? "").startsWith(`EV_${ep.key}_JEFE`));
  if (!boss) { warnings.push(`${ep.key}: no se encontró EV_${ep.key}_JEFE en ${bossMap}`); return false; }
  const pages = boss[1].getIvar("@pages");
  const epilogue = [page({
    cond: condition({ sw: ep.seal, sw2: phaseASwitch(ep), variable: [phaseBVariable(ep), phaseBTotal(ep)] }),
    gfx: graphic(""), list: [...texts([`${ep.bossName} ya no está. El sello aguanta (resonancia v265).`]), cmd(0)],
  })];
  const already = pages.some((p) => {
    const cond = p.getIvar("@condition");
    return cond?.getIvar("@switch1_id") === ep.seal && cond?.getIvar("@switch1_valid")
      && cond?.getIvar("@switch2_id") === phaseASwitch(ep) && cond?.getIvar("@switch2_valid")
      && cond?.getIvar("@variable_id") === phaseBVariable(ep)
      && cond?.getIvar("@variable_value") === phaseBTotal(ep)
      && cond?.getIvar("@variable_valid");
  });
  if (already) return true;
  pages.push(epilogue[0]);
  boss[1].setIvar("@pages", pages);
  mapObject.setIvar("@events", hash);
  write(mapFile(bossMap), mapObject);
  return true;
}

function bossEvent(mapObject, name) {
  const hash = mapObject.getIvar("@events");
  const pair = hash?.pairs.find(([, ev]) => txt(ev.getIvar("@name")) === name);
  return pair ? { hash, pair, event: pair[1] } : null;
}

function replaceTrainerBattleCondition(mapObject, name, replacement) {
  const found = bossEvent(mapObject, name);
  if (!found) return 0;
  let changed = 0;
  for (const eventPage of found.event.getIvar("@pages") ?? []) {
    for (const command of eventPage.getIvar("@list") ?? []) {
      if (command.getIvar("@code") !== 111) continue;
      const params = command.getIvar("@parameters") ?? [];
      if (params[0] !== 12 || !txt(params[1]).includes("pbTrainerBattle")) continue;
      params[1] = S(replacement);
      command.setIvar("@parameters", params);
      changed++;
    }
  }
  return changed;
}

function installEp05Mirror(mapId, name, mirrorName) {
  const mapObject = read(mapFile(mapId));
  const found = bossEvent(mapObject, name);
  if (!found) { warnings.push(`EP05: falta ${name} en Map${mapId}`); return false; }
  const battleCall = `begin; dn_mirror_battle(${JSON.stringify(mirrorName)}); rescue; pbMessage("El espejo se repliega sin alterar tu equipo."); false; end`;
  const changed = replaceTrainerBattleCondition(mapObject, name, battleCall);
  if (name === "EV_BLK_Espejo") {
    const choiceList = [
      ...texts(["El Espejo ofrece tu misma composición, nivel y movimientos; ningún Pokémon ni objeto se mueve de tu equipo.", "¿Quieres probar el reflejo ahora?"]),
      cmd(102, [[S("Enfrentar"), S("Luego")], 1]),
      cmd(402, [0, S("Enfrentar")]),
      cmd(111, [12, S(`dn_mirror_battle("${mirrorName}")`)], 1),
      ...texts(["El reflejo se disuelve. No ha podido recordar quién es su dueño."], 2),
      selfSwitch("A", 2),
      cmd(411, [], 1),
      ...texts(["La forma se deshace, pero el mausoleo conserva el combate. Puedes volver a intentarlo."], 2),
      cmd(412, [], 1),
      cmd(402, [1, S("Luego")]),
      ...texts(["El espejo espera en silencio. La salida sigue libre."], 1),
      cmd(404), cmd(0),
    ];
    const done = page({ cond: condition({ self: "A" }), gfx: graphic(""), list: [...texts(["El reflejo ya reconoció que este equipo es tuyo." ]), cmd(0)] });
    found.event.setIvar("@pages", [page({ cond: condition(), gfx: graphic(""), trigger: 0, list: choiceList }), done]);
  }
  found.hash.pairs[found.hash.pairs.indexOf(found.pair)][1] = found.event;
  mapObject.setIvar("@events", found.hash);
  write(mapFile(mapId), mapObject);
  return changed > 0 || name === "EV_BLK_Espejo";
}

function kinggusCompletionCommands(ep, indent = 1) {
  return [
    ...texts(["El Rey deja caer el Ancla del Testigo. Las siete letras quedan guardadas; el camino de salida vuelve a abrirse."], indent),
    cmd(121, [phaseASwitch(ep), phaseASwitch(ep), 0], indent),
    cmd(121, [ep.seal, ep.seal, 0], indent),
    script(`$game_variables[265] = [$game_variables[265] + ${ep.resonance}, 100].min`, indent),
    script(ROTOM_LEVEL_UPDATE, indent),
    script(`begin; pbItemBall(:${ep.boss.reward}); rescue; pbMessage("(recompensa ${ep.boss.reward} pendiente)"); end`, indent),
    ...(ep.grieta ? [cmd(121, [ep.grieta, ep.grieta, 0], indent)] : []),
    script(WITNESS_CHECK, indent),
  ];
}

function installEp06FinalBoss(ep) {
  const mapId = ep.mapRange.to;
  const mapObject = read(mapFile(mapId));
  const found = bossEvent(mapObject, `EV_${ep.key}_JEFE`);
  if (!found) { warnings.push(`EP06: falta EV_${ep.key}_JEFE en Map${mapId}`); return false; }
  const variable = phaseBVariable(ep);
  const sequence = "dn_kinggus_final_sequence";
  const battleBranch = (retry) => [
    ...texts([retry ? "Las siete letras siguen en orden. ¿Vuelves a afrontar las dos formas del Rey?" : "El suelo termina de deletrear KINGGUS." ]),
    cmd(111, [12, S(sequence)]),
    ...kinggusCompletionCommands(ep, 1),
    cmd(411),
    ...texts(["La Cámara del Trono restaura a tu equipo. Las letras no se pierden: prepara lo que necesites y vuelve a interactuar para reintentar."], 1),
    ...(retry ? [] : [selfSwitch("A", 1)]),
    cmd(412), cmd(0),
  ];
  const pages = [
    page({
      cond: condition({ variable: [variable, 7] }), gfx: graphic(""), trigger: 3, through: true,
      list: battleBranch(false),
    }),
    page({
      cond: condition({ self: "A" }), gfx: graphic(""), trigger: 0, through: true,
      list: battleBranch(true),
    }),
    page({
      cond: condition({ sw: phaseASwitch(ep), variable: [variable, 7] }), gfx: graphic(""), through: true,
      list: [...texts(["La Cámara reconoce las siete letras. El Rey ya no puede volver a levantarse." ]), cmd(0)],
    }),
    page({
      cond: condition({ sw: ep.seal, sw2: phaseASwitch(ep), variable: [variable, 7] }), gfx: graphic(""), through: true,
      list: [...texts(["EL REY SIN LETRA queda sellado. El Ancla y las siete letras permanecen en tu itinerario." ]), cmd(0)],
    }),
  ];
  found.event.setIvar("@pages", pages);
  found.hash.pairs[found.hash.pairs.indexOf(found.pair)][1] = found.event;
  mapObject.setIvar("@events", found.hash);
  write(mapFile(mapId), mapObject);
  return true;
}

function installBossSpecificEvents(ep) {
  if (ep.key === "EP05") {
    installEp05Mirror(2114, "EV_BLK_Espejo", "EL ESPEJO");
    const bossMap = read(mapFile(2119));
    const patched = replaceTrainerBattleCondition(bossMap, "EV_EP05_JEFE",
      'begin; dn_mirror_battle("EL JUGADOR 000"); rescue; pbMessage("El espejo se repliega sin alterar tu equipo."); false; end');
    const found = bossEvent(bossMap, "EV_EP05_JEFE");
    if (found) {
      found.hash.pairs[found.hash.pairs.indexOf(found.pair)][1] = found.event;
      bossMap.setIvar("@events", found.hash);
      write(mapFile(2119), bossMap);
    } else warnings.push("EP05: falta EV_EP05_JEFE en Map2119");
    return { mirrorMiniBoss: true, mirrorBossPagesPatched: patched };
  }
  if (ep.key === "EP06") return { finalBoss: installEp06FinalBoss(ep), lettersBeforeBattle: true };
  return {};
}

// ------------------------------------------------------------ main
const roster = episodes.flatMap((ep) => {
  const trainers = [{
    episode: ep.key, role: "phaseA", trainer: ep.boss.phaseA.trainer, type: ep.boss.phaseA.type,
    name: ep.boss.phaseA.label, team: ep.boss.team, reward: ep.boss.reward,
    loss: ep.boss.notes ?? "...",
  }];
  if (ep.boss.finalForm) trainers.push({
    episode: ep.key, role: "final", trainer: ep.boss.finalForm.trainer, type: ep.boss.finalForm.type,
    name: ep.boss.finalForm.label, team: ep.boss.finalForm.team,
    loss: ep.boss.finalForm.loss ?? "El Rey sin Letra permanece en el trono.",
  });
  return trainers;
});

const itemList = [];
for (const ep of episodes) {
  if (ep.boss.reward.startsWith("DN_PAGE_")) {
    const page = Number(ep.boss.reward.slice(-2));
    itemList.push({ id: ep.boss.reward, name: `Página Quemada ${String(page).padStart(2, "0")}`, namePlural: `Páginas Quemadas ${String(page).padStart(2, "0")}`, page, description: `Una página quemada por los bordes, rescatada del ${ep.bossName}. Forma parte del itinerario del Nightmare y queda archivada en la Gruta de los Testigos.` });
    for (let n = 1; n <= 4; n++) {
      itemList.push({
        id: `DN_PHOTO_0${n}`, name: `Foto ${n} del Sin Nombre`, namePlural: `Fotos del Sin Nombre`, photo: n,
        description: n === 4
          ? "La cuarta foto está en blanco: el nombre que aparece en ella es el de quien la sostiene."
          : `Foto ${n} rescatada de las ruinas de Lost Silver: el Sin Nombre la firmó con otra letra.`,
      });
    }
  } else if (ep.boss.reward === "DN_ANCLA") {
    itemList.push({ id: "DN_ANCLA", name: "Ancla del Testigo", namePlural: "Anclas del Testigo", page: 0, description: "El ancla que el Rey sin Letra dejó al caer: con ella el Rotom despierta y el itinerario se cierra." });
  }
}

if (VERIFY) {
  let failures = 0;
  const ok = (cond, label) => { if (!cond) { failures++; console.error(`  FALLA: ${label}`); } };
  const items = dataSymbols("items.dat");
  const trainers = read("trainers.dat");
  const trainerKeys = new Set();
  for (const [k] of trainers.pairs) if (Array.isArray(k)) trainerKeys.add(`${txt(k[1])}`);
  console.log("verificación de fase B (jefes, trainers y objetos)");
  const catalog = fs.existsSync(CATALOG) ? JSON.parse(fs.readFileSync(CATALOG, "utf8")).episodes : {};
  for (const ep of blueprint.episodes.filter((e) => e.boss)) {
    if (!ALL && EPISODE && ep.key !== EPISODE) continue;
    const info = catalog[ep.key];
    if (!info) { ok(false, `${ep.key}: sin registro de instalación`); continue; }
    ok(trainerKeys.has(ep.boss.phaseA.label), `${ep.key}: falta el trainer ${ep.boss.phaseA.label}`);
    if (ep.boss.finalForm) ok(trainerKeys.has(ep.boss.finalForm.label), `${ep.key}: falta el trainer de forma final ${ep.boss.finalForm.label}`);
    ok(items.has(ep.boss.reward), `${ep.key}: falta el objeto ${ep.boss.reward}`);
    ok(fs.existsSync(path.join(ITEM_ICONS, `${ep.boss.reward}.png`)), `${ep.key}: falta el icono ${ep.boss.reward}.png`);
    const total = info.phaseB?.total ?? 0;
    ok(total > 0, `${ep.key}: fase B sin pasos`);
    const phaseASw = phaseASwitch(ep);
    const counterVariable = phaseBVariable(ep);
    const expectedTotal = phaseBTotal(ep);
    ok(total === expectedTotal, `${ep.key}: fase B tiene ${total} pasos; el plano declara ${expectedTotal}`);
    const eventByName = (mapId, name) => {
      const mapObject = read(mapFile(mapId));
      return (mapObject.getIvar("@events")?.pairs ?? []).map(([, ev]) => ev)
        .find((ev) => txt(ev.getIvar("@name")) === name) ?? null;
    };
    const pageCondition = (pageObj) => pageObj?.getIvar("@condition");
    const pageList = (pageObj) => pageObj?.getIvar("@list") ?? [];
    const bossMap = ep.mapRange.to;
    const bossEvent = eventByName(bossMap, `EV_${ep.key}_JEFE`);
    ok(!!bossEvent, `${ep.key}: falta EV_${ep.key}_JEFE en Map${bossMap}`);
    if (bossEvent) {
      const bossPages = bossEvent.getIvar("@pages") ?? [];
      ok(bossPages.length === 4, `${ep.key}: jefe necesita 4 páginas (autorun, reintento, fase B, epílogo)`);
      const mainCommands = pageList(bossPages[0]);
      const retryCommands = pageList(bossPages[1]);
      const mainScripts = mainCommands.filter((c) => c.getIvar("@code") === 355).map((c) => txt(c.getIvar("@parameters")?.[0])).join("\n");
      const allBossScripts = bossPages.flatMap(pageList).filter((c) => c.getIvar("@code") === 355).map((c) => txt(c.getIvar("@parameters")?.[0])).join("\n");
      if (ep.key === "EP06") {
        const startCond = pageCondition(bossPages[0]);
        ok(startCond?.getIvar("@variable_valid") && startCond.getIvar("@variable_id") === counterVariable
          && startCond.getIvar("@variable_value") === total,
        "EP06: el Rey debe esperar a que las siete letras estén ordenadas");
        ok(mainCommands.some((c) => c.getIvar("@code") === 111 && txt(c.getIvar("@parameters")?.[1]).includes("dn_kinggus_final_sequence")),
          "EP06: falta la secuencia de combate intermedio + forma final");
        ok(!allBossScripts.includes(`$game_variables[${counterVariable}] = 0`), "EP06: un combate no debe borrar el puzzle de siete letras");
        const successSwitches = mainCommands.filter((c) => c.getIvar("@code") === 121).map((c) => c.getIvar("@parameters")?.[0]);
        ok(successSwitches.includes(phaseASw) && successSwitches.includes(ep.seal), "EP06: al completar ambas batallas deben activarse fase A y sello");
        ok(mainScripts.includes(`pbItemBall(:${ep.boss.reward})`) && mainScripts.includes("$game_variables[265]"),
          "EP06: la victoria final debe dar el Ancla y sumar resonancia");
        ok(mainCommands.some((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A"),
          "EP06: una derrota inicial debe dejar una página de reintento");
        const retryCond = pageCondition(bossPages[1]);
        ok(retryCond?.getIvar("@self_switch_valid") && txt(retryCond.getIvar("@self_switch_ch")) === "A",
          "EP06: falta página interactiva de reintento tras derrota");
        ok(retryCommands.some((c) => c.getIvar("@code") === 111 && txt(c.getIvar("@parameters")?.[1]).includes("dn_kinggus_final_sequence")),
          "EP06: el reintento debe ofrecer las dos formas del Rey");
        const pendingCond = pageCondition(bossPages[2]);
        ok(pendingCond?.getIvar("@switch1_valid") && pendingCond.getIvar("@switch1_id") === phaseASw,
          "EP06: falta página de jefe ya vencido");
        const endingCond = pageCondition(bossPages[3]);
        ok(endingCond?.getIvar("@switch1_id") === ep.seal && endingCond?.getIvar("@switch2_id") === phaseASw
          && endingCond?.getIvar("@variable_id") === counterVariable && endingCond?.getIvar("@variable_value") === total,
        "EP06: el epílogo no espera sello, ambas batallas y siete letras");
        ok(!/\$game_variables\[264\]\s*(?:=(?!=)|\+=|-=|\*=|\/=)/.test(allBossScripts), "EP06: altera v264, reservado a Monte Silver");
      } else {
        const battleNeedle = ep.key === "EP05" ? "dn_mirror_battle" : "pbTrainerBattle";
        const battleCommand = mainCommands.find((c) => c.getIvar("@code") === 111 && txt(c.getIvar("@parameters")?.[1]).includes(battleNeedle));
        ok(!!battleCommand, `${ep.key}: la página de fase A no evalúa su batalla`);
        const call = txt(battleCommand?.getIvar("@parameters")?.[1]);
        if (ep.key === "EP05") {
          ok(call.includes('dn_mirror_battle("EL JUGADOR 000")'), "EP05: el jefe no copia la party actual de forma temporal");
          const mirrorMap = read(mapFile(2114));
          const mirrorEvent = (mirrorMap.getIvar("@events")?.pairs ?? []).map(([, ev]) => ev)
            .find((ev) => txt(ev.getIvar("@name")) === "EV_BLK_Espejo");
          const mirrorPages = mirrorEvent?.getIvar("@pages") ?? [];
          const mirrorScripts = mirrorPages.flatMap(pageList).filter((c) => c.getIvar("@code") === 111)
            .map((c) => txt(c.getIvar("@parameters")?.[1])).join("\n");
          ok(mirrorScripts.includes('dn_mirror_battle("EL ESPEJO")'), "EP05: el miniboss del mausoleo no es un combate espejo");
          ok(mirrorPages.length === 2 && pageCondition(mirrorPages[1])?.getIvar("@self_switch_valid"),
            "EP05: el miniboss opcional no se cierra una sola vez tras la victoria");
        } else {
          ok(/false,\s*"",\s*true/.test(call), `${ep.key}: la batalla no permite perder sin bloquear la progresión`);
        }
        const successSwitch = mainCommands.find((c) => c.getIvar("@code") === 121);
        ok(successSwitch?.getIvar("@parameters")?.[0] === phaseASw
          && successSwitch?.getIvar("@parameters")?.[1] === phaseASw
          && successSwitch?.getIvar("@parameters")?.[2] === 0,
        `${ep.key}: el switch de fase A no se activa con parámetros RMXP válidos tras ganar`);
        const resetIndex = mainCommands.findIndex((c) => c.getIvar("@code") === 355
          && txt(c.getIvar("@parameters")?.[0]).includes(`$game_variables[${counterVariable}] = 0`));
        const successIndex = mainCommands.indexOf(successSwitch);
        ok(resetIndex >= 0 && successIndex > resetIndex,
          `${ep.key}: el contador de fase B debe reiniciarse antes de activar el switch de fase A`);
        const retryResetIndex = retryCommands.findIndex((c) => c.getIvar("@code") === 355
          && txt(c.getIvar("@parameters")?.[0]).includes(`$game_variables[${counterVariable}] = 0`));
        const retrySuccessIndex = retryCommands.findIndex((c) => c.getIvar("@code") === 121
          && c.getIvar("@parameters")?.[0] === phaseASw && c.getIvar("@parameters")?.[2] === 0);
        ok(retryResetIndex >= 0 && retrySuccessIndex > retryResetIndex,
          `${ep.key}: el reintento debe reiniciar fase B antes de activar su switch`);
        ok(mainCommands.some((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A"),
          `${ep.key}: tras perder el autorun no se cierra con self-switch A para permitir reintento manual`);
        const retryCond = pageCondition(bossPages[1]);
        ok(retryCond?.getIvar("@self_switch_valid") && txt(retryCond.getIvar("@self_switch_ch")) === "A",
          `${ep.key}: falta página interactiva de reintento tras derrota`);
        const pendingCond = pageCondition(bossPages[2]);
        ok(pendingCond?.getIvar("@switch1_valid") && pendingCond.getIvar("@switch1_id") === phaseASw,
          `${ep.key}: la fase B no depende del switch correcto de victoria en fase A`);
        const endingCond = pageCondition(bossPages[3]);
        ok(endingCond?.getIvar("@switch1_id") === ep.seal && endingCond?.getIvar("@switch2_id") === phaseASw
          && endingCond?.getIvar("@variable_id") === counterVariable && endingCond?.getIvar("@variable_value") === total,
        `${ep.key}: el epílogo no espera sello, victoria y contador completo de fase B`);
      }
    }
    const steps = new Map();
    for (const placed of info.phaseB?.placed ?? []) {
      const stepName = `BOSSB_${ep.key}_${placed.step}`;
      const stepEvent = eventByName(placed.map, stepName);
      ok(!!stepEvent, `${ep.key}: falta ${stepName} en Map${placed.map}`);
      if (!stepEvent) continue;
      steps.set(placed.step, stepEvent);
      const pages = stepEvent.getIvar("@pages") ?? [];
      const activeCond = pageCondition(pages[0]);
      const commands = pageList(pages[0]);
      const allPageCommands = pages.flatMap(pageList);
      const writesMonteSilver = allPageCommands.some((c) => c.getIvar("@code") === 355
        && /\$game_variables\[264\]\s*(?:=(?!=)|\+=|-=|\*=|\/=)/.test(txt(c.getIvar("@parameters")?.[0])));
      if (ep.key === "EP06") {
        ok(pages.length === 2 && !activeCond?.getIvar("@switch1_valid") && !activeCond?.getIvar("@variable_valid"),
          `${stepName}: pedestal de letra debe poder comprobar orden y prerrequisitos en su rama`);
        const branches = commands.filter((c) => c.getIvar("@code") === 111).map((c) => txt(c.getIvar("@parameters")?.[1])).join("\n");
        ok(KINGGUS_PREREQUISITES.every((switchId) => branches.includes(`$game_switches[${switchId}]`))
          && branches.includes("$game_variables[264].to_i >= 7")
          && branches.includes(`$game_variables[${counterVariable}].to_i == ${placed.step - 1}`),
        `${stepName}: debe verificar los cinco sellos, v264=7 y el orden exacto`);
        const letterWrite = commands.find((c) => c.getIvar("@code") === 355
          && txt(c.getIvar("@parameters")?.[0]).includes(`$game_variables[${counterVariable}] = ${placed.step}`));
        const lockIndex = commands.findIndex((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A");
        const letterIndex = commands.indexOf(letterWrite);
        ok(!!letterWrite && letterIndex >= 0 && lockIndex > letterIndex,
          `${stepName}: la letra ordenada debe persistir antes de cerrar el pedestal`);
        ok(pageCondition(pages[1])?.getIvar("@self_switch_valid")
          && txt(pageCondition(pages[1])?.getIvar("@self_switch_ch")) === "A",
        `${stepName}: falta recuerdo persistente de la letra resuelta`);
        ok(!writesMonteSilver, `${stepName}: altera v264, reservado al contador de Monte Silver`);
        if (placed.step === total) {
          ok(!commands.some((c) => c.getIvar("@code") === 121 && c.getIvar("@parameters")?.[0] === ep.seal),
            `${stepName}: no debe sellar EP06 antes de las batallas del Rey`);
          ok(!commands.some((c) => c.getIvar("@code") === 355
            && txt(c.getIvar("@parameters")?.[0]).includes(`pbItemBall(:${ep.boss.reward})`)),
          `${stepName}: no debe entregar el Ancla antes de la forma final`);
        }
      } else {
        ok(activeCond?.getIvar("@switch1_id") === phaseASw && activeCond?.getIvar("@switch1_valid")
          && activeCond?.getIvar("@variable_id") === counterVariable && activeCond?.getIvar("@variable_value") === placed.step - 1,
        `${stepName}: acceso no sincronizado con fase A y el paso anterior`);
        ok(pageCondition(pages[1])?.getIvar("@self_switch_valid")
          && txt(pageCondition(pages[1])?.getIvar("@self_switch_ch")) === "A",
        `${stepName}: falta cierre one-shot por self-switch A`);
        const lockIndex = commands.findIndex((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A");
        const counterIndex = commands.findIndex((c) => c.getIvar("@code") === 355
          && txt(c.getIvar("@parameters")?.[0]).includes(`$game_variables[${counterVariable}] += 1`));
        ok(lockIndex >= 0 && counterIndex >= 0 && counterIndex < lockIndex,
          `${stepName}: debe incrementar su contador antes de cerrarse con self-switch A`);
        ok(!writesMonteSilver, `${stepName}: altera v264, reservado al contador de Monte Silver`);
        for (const command of commands.filter((c) => c.getIvar("@code") === 121)) {
          const params = command.getIvar("@parameters") ?? [];
          ok(params.length >= 3 && params[0] === params[1] && (params[2] === 0 || params[2] === 1),
            `${stepName}: comando 121 con parámetros inválidos (${params.join(",")})`);
        }
        if (placed.step === total) {
          ok(commands.some((c) => c.getIvar("@code") === 121 && c.getIvar("@parameters")?.[0] === ep.seal
            && c.getIvar("@parameters")?.[1] === ep.seal && c.getIvar("@parameters")?.[2] === 0),
          `${stepName}: el último paso no enciende el sello del episodio`);
          const witnessIndex = commands.findIndex((c) => c.getIvar("@code") === 355
            && txt(c.getIvar("@parameters")?.[0]).includes("$game_switches[931]"));
          const rewardIndex = commands.findIndex((c) => c.getIvar("@code") === 355
            && txt(c.getIvar("@parameters")?.[0]).includes(`pbItemBall(:${ep.boss.reward})`));
          ok(witnessIndex >= 0, `${stepName}: no recalcula DN_TESTIGO_LISTO tras cerrar un sello`);
          ok(rewardIndex >= 0 && rewardIndex < lockIndex && witnessIndex < lockIndex,
            `${stepName}: recompensa y vitrina deben resolverse antes del cierre self-switch A`);
        }
      }
    }
    ok(steps.size === total, `${ep.key}: sólo hay ${steps.size}/${total} eventos de fase B`);
    console.log(`  ${ep.key}: ${ep.bossName} · ${info.phaseB?.kind} ×${total} (v${counterVariable}) · trainer ${ep.boss.phaseA.trainer} · objeto ${ep.boss.reward}`);
  }
  console.log(failures === 0 ? "verificación OK" : `verificación con ${failures} fallos`);
  process.exit(failures === 0 ? 0 : 1);
}

if (!DRY) {
  fs.mkdirSync(BACKUP, { recursive: true });
  for (const file of ["items.dat", "trainers.dat"]) {
    const target = path.join(BACKUP, file);
    if (!fs.existsSync(target)) fs.copyFileSync(path.join(DATA, file), target);
  }
}

const itemsAdded = installItems(itemList);
const iconsDrawn = installItemIcons(itemList);
const trainersAdded = installTrainers(roster);
for (const ep of episodes) {
  const phaseB = installPhaseB(ep);
  const epilogue = installBossEpilogue(ep);
  const mechanics = installBossSpecificEvents(ep);
  result.episodes[ep.key] = { ...(result.episodes[ep.key] ?? {}), bossName: ep.bossName, phaseB, epilogue, mechanics };
}

if (!DRY) fs.writeFileSync(CATALOG, `${JSON.stringify(result, null, 2)}\n`);
console.log(`jefes: ${episodes.length} · objetos nuevos: ${itemsAdded} (iconos ${iconsDrawn}) · trainers nuevos: ${trainersAdded}`);
for (const [key, info] of Object.entries(result.episodes)) {
  console.log(`  ${key}: fase B ${info.phaseB.kind} ×${info.phaseB.total} en ${[...new Set(info.phaseB.placed.map((p) => p.map))].map((m) => `Map${m}`).join(", ")}`);
}
if (warnings.length) {
  console.log(`avisos (${warnings.length}):`);
  for (const w of warnings.slice(0, 10)) console.log(`  - ${w}`);
}#!/usr/bin/env node
/**
 * apply_dimensional_nightmare_events.mjs — E4: hace jugables los mapas del Nightmare.
 *
 * Sobre los mapas ya construidos por `apply_dimensional_nightmare_maps.mjs`, escribe:
 *   1. CONEXIONES: transferencias encadenadas entre los mapas del episodio y con el hub
 *      (Gruta de los Testigos, Map2030 36,12), resolviendo las celdas con la malla de
 *      `content/dimensional_nightmare_passability.json`;
 *   2. NPCs: los de las tablas del GDD, con su sprite (con respaldo si falta), páginas por
 *      fase (v266) y diálogo derivado de las notas;
 *   3. EVENTOS del índice «Eventos programables»: anomalías (+1 a la variable del episodio y
 *      al total; +1 resonancia cada 3, tope 3), curaciones, objetos y disparadores;
 *   4. JEFE del episodio en su mapa final: fase A con derrota reintentable, luego fase B por pasos;
 *      sólo al cerrar todos los pasos se registran sello/resonancia/recompensa y se abre la salida.
 *
 * No crea trainers ni objetos (eso es del `create` correspondiente): las llamadas van
 * protegidas con `begin/rescue` y lo pendiente queda anotado en el catálogo construido.
 * No toca partidas.
 *
 * Uso:
 *   node tools/apply_dimensional_nightmare_events.mjs --episode EP01
 *   node tools/apply_dimensional_nightmare_events.mjs --all --render
 *   node tools/apply_dimensional_nightmare_events.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalLoad, marshalDump, RHash, RObject, RString } from "../web/js/marshal.js";
import { parseMap } from "../web/js/rmxp.js";
import { passabilityOf, reachableCells } from "./lib/map_painter.mjs";
import { tableGet } from "../web/js/rmxp.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "pokemon_fire_ash", "Data");
const CHARS = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Characters");
const BLUEPRINT = path.join(ROOT, "content", "dimensional_nightmare_events.json");
const MAPS = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const PASS = path.join(ROOT, "content", "dimensional_nightmare_passability.json");
const BUILT = path.join(ROOT, "content", "dimensional_nightmare_events_built.json");
const TILESETS = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Tilesets");
const RENDER_DIR = path.join(ROOT, "docs", "dn_referencia", "eventos");
const TILE = 32;
const COLUMNS = 8;
const BASE_ID = 384;            // primer id de tile normal (0-47 vacío, 48-383 autotiles)

const argv = process.argv.slice(2);
const option = (name, fallback) => {
  const at = argv.indexOf(name);
  return at >= 0 && argv[at + 1] ? argv[at + 1] : fallback;
};
const EPISODE = option("--episode", null);
const ALL = argv.includes("--all");
const ONLY = option("--only", null)?.split(",").map(Number).filter(Boolean) ?? null;
const VERIFY = argv.includes("--verify");
const DRY = argv.includes("--dry-run");
const RENDER = argv.includes("--render");

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => { if (!DRY) fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value))); };
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;
const S = (v) => RString.fromText(String(v));
const txt = (v) => (v instanceof RString ? v.text : String(v ?? ""));

const blueprint = JSON.parse(fs.readFileSync(BLUEPRINT, "utf8"));
const builtMaps = new Map(JSON.parse(fs.readFileSync(MAPS, "utf8")).maps.map((m) => [m.id, m]));
const passability = JSON.parse(fs.readFileSync(PASS, "utf8")).maps;
const previousBuilt = fs.existsSync(BUILT) ? JSON.parse(fs.readFileSync(BUILT, "utf8")).maps ?? {} : {};
const result = { generatedBy: "tools/apply_dimensional_nightmare_events.mjs", maps: { ...previousBuilt } };
const warnings = [];

// Flags distintas para los nueve combates de fase A; los switches 910–916 quedan reservados
// para compatibilidad con el catálogo antiguo y no se reutilizan como contador global.
const PHASE_A_SWITCHES = Object.freeze({
  EP01: 903, EP02: 904, EP03: 905, EP04: 906, EP05: 907, EP06: 908,
  W7: 928, W8: 929, W9: 930,
});
const PHASE_B_VARIABLE_BASE = 289;
const NEXO_RESOLVED_SWITCH = 935;
const bossEpisodes = blueprint.episodes.filter((episode) => episode.boss);
function phaseASwitch(episode) {
  const id = episode.bossSwitch ?? PHASE_A_SWITCHES[episode.key];
  if (!id) throw new Error(`${episode.key}: falta switch de fase A`);
  return id;
}
function phaseBVariable(episode) {
  const index = bossEpisodes.findIndex((candidate) => candidate.key === episode.key);
  if (index < 0) throw new Error(`${episode.key}: falta índice de variable de fase B`);
  return PHASE_B_VARIABLE_BASE + index;
}
function phaseBTotal(episode) {
  const spec = episode.boss?.phaseB;
  if (!spec) return 0;
  return spec.maps?.length || spec.cells?.length || (spec.kind === "letras" ? 7 : 4);
}

// --------------------------------------------------------------- RMXP bits
const cmd = (code, params = [], indent = 0) => new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", params]]);
const condition = ({ sw = 0, sw2 = 0, self = "", variable = null } = {}) => new RObject("RPG::Event::Page::Condition", [
  ["@switch1_valid", !!sw], ["@switch1_id", sw || 1],
  ["@switch2_valid", !!sw2], ["@switch2_id", sw2 || 1],
  ["@variable_valid", !!variable], ["@variable_id", variable ? variable[0] : 1], ["@variable_value", variable ? variable[1] : 0],
  ["@self_switch_valid", !!self], ["@self_switch_ch", S(self || "A")],
]);
const graphic = (charName = "", dir = 2, pattern = 1, opts = {}) => new RObject("RPG::Event::Page::Graphic", [
  ["@tile_id", opts.tile ?? 0], ["@character_name", S(charName)], ["@character_hue", 0],
  ["@direction", dir], ["@pattern", pattern], ["@opacity", opts.opacity ?? 255], ["@blend_type", 0],
]);
const moveRoute = () => new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", false], ["@list", []]]);
const page = ({ cond = condition(), gfx = graphic(), trigger = 0, through = false, list = [cmd(0)] } = {}) => new RObject("RPG::Event::Page", [
  ["@condition", cond], ["@graphic", gfx],
  ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
  ["@move_route", moveRoute()], ["@walk_anime", true], ["@step_anime", false],
  ["@direction_fix", false], ["@through", through], ["@always_on_top", false],
  ["@trigger", trigger], ["@list", list],
]);
const event = (id, name, x, y, pages) => new RObject("RPG::Event", [["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]]);
const texts = (lines, indent = 0) => [cmd(101, [S("")], indent), ...[].concat(lines).map((line) => cmd(401, [S(line)], indent))];
const script = (line, indent = 0) => cmd(355, [S(line)], indent);
const transfer = (mapId, x, y, dir = 2, indent = 0) => cmd(201, [0, mapId, x, y, dir, 1], indent);
const setSwitch = (id, indent = 0) => cmd(121, [id, id, 0], indent);
const setSelf = (ch, indent = 0) => cmd(123, [S(ch), 0], indent);
const wait = (frames, indent = 0) => cmd(106, [frames], indent);
const plannedItems = new Set([
  ...blueprint.episodes.flatMap((episode) => episode.boss?.reward ? [episode.boss.reward] : []),
  ...[1, 2, 3, 4].map((index) => `DN_PHOTO_0${index}`),
  "DN_ANCLA",
]);
const itemSymbols = new Set([
  ...read("items.dat").pairs.filter(([key]) => key && key.name !== undefined).map(([key]) => key.name),
  ...plannedItems,
]);

// ------------------------------------------------------------- pasabilidad
function maskOf(mapId) {
  const info = passability[String(mapId)];
  const size = builtMaps.get(mapId);
  if (!info || !size) return null;
  const { width, height } = size;
  const open = new Set(info.open ?? []);
  const blocked = new Set([...(info.computed ?? []), ...(info.blocked ?? [])]);
  const rects = (list) => {
    for (const [x0, y0, x1, y1] of list ?? []) {
      for (let y = Math.max(0, y0); y <= Math.min(height - 1, y1); y++) {
        for (let x = Math.max(0, x0); x <= Math.min(width - 1, x1); x++) open.add(`${x},${y}`), blocked.delete(`${x},${y}`);
      }
    }
  };
  rects(info.openRects);
  for (const [x0, y0, x1, y1] of info.blockRects ?? []) {
    for (let y = Math.max(0, y0); y <= Math.min(height - 1, y1); y++) {
      for (let x = Math.max(0, x0); x <= Math.min(width - 1, x1); x++) blocked.add(`${x},${y}`), open.delete(`${x},${y}`);
    }
  }
  const curated = new Set(open);   // suelo curado a mano (open + openRects − blockRects)
  const walkable = [];
  for (let y = 0; y < height; y++) {
    const row = [];
    for (let x = 0; x < width; x++) row.push(open.has(`${x},${y}`) || !blocked.has(`${x},${y}`));
    walkable.push(row);
  }
  return { walkable, width, height, curated };
}

function physicalMaskOf(mapId) {
  const curated = maskOf(mapId);
  if (curated) return curated;
  const file = path.join(DATA, mapFile(mapId));
  if (!fs.existsSync(file)) return null;
  const parsed = parseMap(read(mapFile(mapId)));
  const pass = passabilityOf(parsed, parsed.tilesetId);
  const walkable = Array.from({ length: parsed.height }, (_, y) =>
    Array.from({ length: parsed.width }, (_, x) => pass.passable(x, y, 8)));
  return { width: parsed.width, height: parsed.height, walkable };
}

/**
 * Celda de llegada al hub (Gruta de los Testigos): el plano fija (36,12), pero el mapa
 * 2030 se reconstruyó después; se busca la celda transitable más cercana a esa intención.
 */
function resolveHubCell() {
  const hub = blueprint.hub;
  try {
    const parsed = parseMap(read(mapFile(hub.map)));
    const pass = passabilityOf(parsed, parsed.tilesetId);
    let start = null, startD = Infinity;
    for (let y = 0; y < parsed.height; y++) {
      for (let x = 0; x < parsed.width; x++) {
        if (!pass.passable(x, y, 8)) continue;
        const d = Math.abs(x - hub.x) + Math.abs(y - hub.y);
        if (d < startD) { startD = d; start = [x, y]; }
      }
    }
    if (!start) throw new Error("no hay celdas transitables");
    const reachable = reachableCells(pass, start);
    let best = null, bestD = Infinity;
    for (const key of reachable) {
      const [x, y] = key.split(",").map(Number);
      const d = Math.abs(x - hub.x) + Math.abs(y - hub.y);
      if (d < bestD) { bestD = d; best = [x, y]; }
    }
    return { map: hub.map, cell: best ?? start, intended: [hub.x, hub.y], distance: bestD };
  } catch (error) {
    warnings.push(`no se pudo resolver la celda del hub: ${error.message}`);
    return { map: hub.map, cell: [hub.x, hub.y], intended: [hub.x, hub.y], distance: Infinity };
  }
}

const inBounds = (mask, x, y) => x >= 0 && y >= 0 && x < mask.width && y < mask.height;
const walkAt = (mask, x, y) => inBounds(mask, x, y) && mask.walkable[y][x];
function reachableMask(mask, start) {
  if (!mask || !start || !walkAt(mask, start[0], start[1])) return new Set();
  const seen = new Set([`${start[0]},${start[1]}`]);
  const queue = [[start[0], start[1]]];
  for (let at = 0; at < queue.length; at++) {
    const [x, y] = queue[at];
    for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
      const key = `${nx},${ny}`;
      if (!seen.has(key) && walkAt(mask, nx, ny)) { seen.add(key); queue.push([nx, ny]); }
    }
  }
  return seen;
}

/** Celda de entrada: borde superior más cercano al centro; si no hay, izquierda/derecha/abajo. */
/**
 * El anillo exterior de estos mapas es la banda de muro (a menudo transitable para el
 * motor pero no para el jugador); se penaliza para que las llegadas caigan en el suelo.
 */
const isBorder = (mask, x, y) => x === 0 || y === 0 || x === mask.width - 1 || y === mask.height - 1;
const cellScore = (mask, [x, y], mid, towards) => {
  const dir = towards === "down" ? (mask.height - y) : towards === "right" ? (mask.width - x) : y;
  return dir * 2 + Math.abs(x - mid) * 0.1
    + (mask.curated?.has(`${x},${y}`) ? 0 : 6)
    + (isBorder(mask, x, y) ? 20 : 0);
};
function entryCell(mask) {
  const mid = Math.floor(mask.width / 2);
  const candidates = [];
  for (let y = 0; y < mask.height; y++) for (let x = 0; x < mask.width; x++) if (walkAt(mask, x, y)) candidates.push([x, y]);
  if (!candidates.length) return null;
  candidates.sort((a, b) => cellScore(mask, a, mid, "up") - cellScore(mask, b, mid, "up"));
  return candidates[0];
}
/** Celda de salida hacia el mapa siguiente: preferimos el borde inferior/ derecho. */
function exitCell(mask, towards) {
  const cells = [];
  for (let y = 0; y < mask.height; y++) for (let x = 0; x < mask.width; x++) if (walkAt(mask, x, y)) cells.push([x, y]);
  if (!cells.length) return null;
  const mid = towards === "right" ? Math.floor(mask.height / 2) : Math.floor(mask.width / 2);
  cells.sort((a, b) => cellScore(mask, a, mid, towards) - cellScore(mask, b, mid, towards));
  return cells[0];
}

/** Coloca cerca del punto deseado: espiral sobre celdas transitables libres. */
function placeNear(mask, desired, occupied) {
  if (!mask) return null;
  const [dx, dy] = desired;
  for (let radius = 0; radius < Math.max(mask.width, mask.height); radius++) {
    for (let y = dy - radius; y <= dy + radius; y++) {
      for (let x = dx - radius; x <= dx + radius; x++) {
        if (Math.max(Math.abs(x - dx), Math.abs(y - dy)) !== radius) continue;
        if (!walkAt(mask, x, y)) continue;
        if (occupied.has(`${x},${y}`)) continue;
        return [x, y];
      }
    }
  }
  return null;
}

// ----------------------------------------------------------------- diálogo
const firstSentence = (text) => {
  const clean = text.replace(/\s+/g, " ").trim();
  const m = clean.match(/^(.{15,140}?[.:;])\s/);
  return (m ? m[1] : clean.slice(0, 140)).replace(/^\*\*|\*\*$/g, "");
};
const fixedPhrase = (notes) => {
  const m = notes.match(/Fija:\s*«([^»]+)»/i) ?? notes.match(/«([^»]{10,})»/);
  return m ? m[1] : firstSentence(notes);
};

function npcPages(npc) {
  const type = npc.type.toLowerCase();
  const name = (npc.displayName ?? npc.name).replace(/\s*\(.*?\)\s*/g, "");
  const first = firstSentence(npc.notes);
  const rest = npc.notes.replace(first, "").trim();
  if (type.includes("interdimensional")) {
    return [page({ gfx: graphic(npc.graphic), list: [...texts([`${name}: «${fixedPhrase(npc.notes)}»`]), cmd(0)] })];
  }
  if (type.includes("consciente")) {
    return [
      page({ gfx: graphic(npc.graphic), list: [...texts([`${name}: ${first}`]), cmd(0)] }),
      // en fase ≥5 el NPC consciente ya no está: página sin gráfico y sin comandos
      page({ cond: condition({ variable: [266, 5] }), gfx: graphic(""), list: [cmd(0)] }),
    ];
  }
  const pages = [page({ gfx: graphic(npc.graphic), list: [...texts([`${name}: ${first}`]), cmd(0)] })];
  if (rest.length > 20) {
    pages.push(page({ cond: condition({ variable: [266, 4] }), gfx: graphic(npc.graphic), list: [...texts([`${name}: ${firstSentence(rest)}`]), cmd(0)] }));
  }
  pages.push(page({
    cond: condition({ variable: [266, 6] }),
    gfx: graphic(npc.graphic, 2, 1, { opacity: 200 }),
    list: [...texts([`${name}: (no responde) Mira el hueco donde debería estar su sombra.`]), cmd(0)],
  }));
  return pages;
}

// ----------------------------------------------------------- comandos evento
// Tope del contador total: suma de anomalías declaradas de todos los mundos (77 del primer anillo
// + 35 del segundo). Antes era 77 fijo y el segundo anillo saturaba el contador.
const ANOMALY_TOTAL_CAP = blueprint.episodes.reduce((sum, ep) => sum + (ep.anomalies?.declared ?? 0), 0);

const ROTOM_LEVEL_UPDATE =
  "$game_variables[275] = 0; $game_variables[275] = 1 if $game_variables[265] >= 20; " +
  "$game_variables[275] = 2 if $game_variables[265] >= 40; $game_variables[275] = 3 if $game_variables[265] >= 60; " +
  "$game_variables[275] = 4 if $game_variables[265] >= 80; $game_variables[275] = 5 if $game_variables[265] >= 100";

const ANOMALY_SCRIPT = (episode) =>
  `$game_variables[${episode.anomalyVariable}] += 1; $game_variables[274] = [$game_variables[274] + 1, ${ANOMALY_TOTAL_CAP}].min; ` +
  `$game_variables[265] = [$game_variables[265] + (($game_variables[${episode.anomalyVariable}] % 3 == 0 && $game_variables[${episode.anomalyVariable}] <= 9) ? 1 : 0), 100].min; ` +
  `$game_switches[${episode.cuota}] = true if $game_variables[${episode.anomalyVariable}] >= ${"__TOTAL__"}; ${ROTOM_LEVEL_UPDATE}`;

/** Glitch visual breve y reversible (si el motor no trae el helper, no pasa nada). */
const VISUAL_GLITCH =
  "begin; pbToneChangeAll(Tone.new(-60, -30, -30, 40), 6); Kernel.pbWait(8); " +
  "pbToneChangeAll(Tone.new(0, 0, 0, 0), 12); rescue; end";

/**
 * Una anomalía del §5: aviso emergente, contador (variable del episodio + total + resonancia
 * cada 3, cuota al completar) y, si es visual, un glitch de tono breve. Las auditivas quedan
 * marcadas como pendientes de audio hasta que existan los archivos de «música alterada».
 */
function anomalyPages(item, episode) {
  const list = [
    ...texts([`[${item.code}] ${item.name}`, item.text.slice(0, 220)]),
    script(VISUAL_GLITCH),
    script(ANOMALY_SCRIPT(episode).replace("__TOTAL__", String(episode.anomalies.declared))),
    setSelf("A"),
    cmd(0),
  ];
  return [
    page({ gfx: graphic(""), trigger: item.trigger === "touch" ? 1 : 0, through: true, list }),
    page({
      cond: condition({ self: "A" }), gfx: graphic(""), through: true,
      list: [...texts([`[${item.code}] Ya figura en el Registro Dimensional.`]), cmd(0)],
    }),
  ];
}

/**
 * El índice del GDD es texto narrativo, no una lista de asignaciones ejecutables. Sólo se
 * conservan los efectos explícitos e inocuos (curación y una recompensa cuyo ID exista);
 * los sellos, grietas, fases y contadores se escriben en sus máquinas de estado dedicadas.
 */
function commandsForEvent(ev) {
  const effect = `${ev.detail} ${ev.effect}`;
  const list = [...texts([`[${ev.name}] ${ev.effect || ev.detail}`.slice(0, 240)])];
  if (/curaci/i.test(effect)) list.push(script("begin; pbHealAll; rescue; end"));

  const candidates = [...effect.matchAll(/\b[A-Z][A-Z0-9_]{2,}\b/g)].map((match) => match[0]);
  const item = candidates.find((candidate) => itemSymbols.has(candidate));
  if (item) {
    list.push(script(`begin; pbItemBall(:${item}); rescue; pbMessage("(objeto ${item} pendiente de registrar)"); end`));
    list.push(setSelf("A"));
  }
  list.push(cmd(0));
  return { list, once: !!item, item };
}

const HYPNO_SILENCE_UNTIL = "@dn_ep04_silence_until";
const HYPNO_SILENCERS_FOUND = "@dn_ep04_silencers_found";
const HYPNO_BGM_SILENCED = "@dn_ep04_bgm_silenced";
const HYPNO_BGM_MAP = "@dn_ep04_bgm_map";
const HYPNO_BGM_NAME = "DN_Hypnos_Lullaby";

function hypnoSilencerPages() {
  const activate = [
    ...texts(["El tronco hueco deja escapar la última nota.", "La nana calla durante un minuto; Rotom registra este silenciador."]),
    script(`begin; gs=$game_system; gs.instance_variable_set("${HYPNO_SILENCE_UNTIL}", Time.now.to_i + 60); n=gs.instance_variable_get("${HYPNO_SILENCERS_FOUND}") || 0; gs.instance_variable_set("${HYPNO_SILENCERS_FOUND}", [[n.to_i + 1, 0].max, 6].min); Audio.bgm_fade(1000); gs.instance_variable_set("${HYPNO_BGM_SILENCED}", true); rescue; end`),
    setSelf("A"),
    cmd(0),
  ];
  return [
    page({ list: activate }),
    page({
      cond: condition({ self: "A" }), gfx: graphic(""), through: true,
      list: [...texts(["Este tronco ya está silenciado; la marca sigue en el registro."]), cmd(0)],
    }),
  ];
}

function hypnoSleepPages() {
  const chance = `begin; gs=$game_system; until_at=gs.instance_variable_get("${HYPNO_SILENCE_UNTIL}") || 0; Time.now.to_i >= until_at.to_i && rand(100) < 15; rescue; false; end`;
  const list = [
    wait(2700), // 45 segundos a 60 fps: una tirada por intervalo, nunca cada frame.
    cmd(111, [12, S(chance)]),
    ...texts(["La nana te arrastra los párpados; Rotom corta el eco antes de que alcance al equipo."], 1),
    script(VISUAL_GLITCH, 1),
    cmd(411),
    cmd(412),
    cmd(0),
  ];
  return [page({ trigger: 2, through: true, list })];
}

function hypnoAudioGuardPages() {
  const source = `begin; gs=$game_system; map_id=$game_map.map_id; last_map=gs.instance_variable_get("${HYPNO_BGM_MAP}"); if last_map != map_id; gs.instance_variable_set("${HYPNO_BGM_MAP}", map_id); gs.instance_variable_set("${HYPNO_BGM_SILENCED}", false); end; until_at=gs.instance_variable_get("${HYPNO_SILENCE_UNTIL}") || 0; active=Time.now.to_i < until_at.to_i; silenced=gs.instance_variable_get("${HYPNO_BGM_SILENCED}"); if active && !silenced; Audio.bgm_fade(1000); gs.instance_variable_set("${HYPNO_BGM_SILENCED}", true); elsif !active && silenced; gs.bgm_play(RPG::AudioFile.new("${HYPNO_BGM_NAME}", 52, 100)); gs.instance_variable_set("${HYPNO_BGM_SILENCED}", false); end; rescue; end`;
  return [page({ trigger: 2, through: true, list: [script(source), wait(30), cmd(0)] })];
}

function indexedEventPages(ev) {
  if (ev.name === "EV_HYP_Silenciador") return hypnoSilencerPages();
  if (ev.name === "EV_HYP_Sueno") return hypnoSleepPages();
  const built = commandsForEvent(ev);
  const pages = [page({
    trigger: ev.trigger === "autorun" ? 3 : ev.trigger === "parallel" ? 2 : ev.trigger === "touch" ? 1 : 0,
    through: ev.trigger !== "action",
    list: built.list,
  })];
  if (built.once) pages.push(page({
    cond: condition({ self: "A" }), gfx: graphic(""), through: true,
    list: [...texts([`El objeto ${built.item} ya quedó registrado.`]), cmd(0)],
  }));
  return pages;
}

function nexoResolutionPages() {
  const sealChoice = [
    ...texts(["El Testigo puede cerrar el Nexo, o dejar que la rendija siga respirando.", "Esta decisión quedará registrada."]),
    cmd(102, [[S("Sellar el Nexo"), S("Dejarlo abierto")], 2]),
    cmd(402, [0, S("Sellar el Nexo")]),
    script(`begin; $game_variables[276] = 0; $game_variables[265] = [$game_variables[265] + 18, 100].min; ${ROTOM_LEVEL_UPDATE}; $game_switches[889] = true; $game_switches[${NEXO_RESOLVED_SWITCH}] = true; rescue; end`, 1),
    cmd(402, [1, S("Dejarlo abierto")]),
    script(`begin; $game_variables[276] = 1; $game_switches[889] = false; $game_switches[${NEXO_RESOLVED_SWITCH}] = true; rescue; end`, 1),
    cmd(404),
    setSelf("A"),
    cmd(0),
  ];
  return [
    page({ cond: condition({ sw: 888 }), gfx: graphic("Object ball special", 2, 1, { hue: 180 }), list: sealChoice }),
    page({
      cond: condition({ self: "A" }), gfx: graphic("Object ball special", 2, 1, { hue: 180 }),
      list: [script('pbMessage($game_variables[276] == 0 ? "El Nexo quedó sellado." : "La rendija sigue abierta.")'), cmd(0)],
    }),
  ];
}


// ------------------------------------------------------------------- render
/**
 * Hoja de revisión de E4: cada mapa del episodio con sus marcadores (NPCs, eventos,
 * conexiones y jefe). Es el artefacto que se versiona; permite ver de un vistazo si algo
 * quedó fuera de la zona transitable o amontonado.
 */
const MARKER = { npc: "#3d7bff", event: "#ffd23d", conn: "#2ecc71", boss: "#ff3b30" };

function markerKind(name) {
  if (name.startsWith("NPC_")) return "npc";
  if (name.startsWith("CONN_")) return "conn";
  if (/JEFE/.test(name) || /HUBSALIDA/.test(name)) return "boss";
  return "event";
}

async function renderMapOverlay(mapId) {
  const parsed = parseMap(read(mapFile(mapId)));
  const { width, height } = parsed;
  const canvas = createCanvas(width * TILE, height * TILE);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#101010";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const tilesetPath = path.join(TILESETS, `DN_${mapId}.png`);
  if (fs.existsSync(tilesetPath)) {
    const image = await loadImage(tilesetPath);
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const tile = tableGet(parsed.table, x, y, 0);
        if (!tile || tile < BASE_ID) continue;
        const k = tile - BASE_ID;
        ctx.drawImage(image, (k % COLUMNS) * TILE, Math.floor(k / COLUMNS) * TILE, TILE, TILE, x * TILE, y * TILE, TILE, TILE);
      }
    }
  } else {
    warnings.push(`${mapId}: sin DN_${mapId}.png; la hoja de E4 se dibuja sin arte (regenerar con dn:tiles)`);
  }

  // tinte suave de transitabilidad para juzgar la colocación
  const pass = passabilityOf(parsed, parsed.tilesetId);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      ctx.fillStyle = pass.passable(x, y, 8) ? "rgba(0,200,120,0.10)" : "rgba(200,30,30,0.16)";
      ctx.fillRect(x * TILE, y * TILE, TILE, TILE);
    }
  }

  const hash = read(mapFile(mapId)).getIvar("@events");
  const legend = [];
  for (const [, ev] of hash.pairs) {
    const name = ev.getIvar("@name")?.text ?? "?";
    const x = ev.getIvar("@x"), y = ev.getIvar("@y");
    const kind = markerKind(name);
    const cx = x * TILE + TILE / 2, cy = y * TILE + TILE / 2;
    ctx.lineWidth = 2;
    ctx.strokeStyle = "#000";
    ctx.fillStyle = MARKER[kind];
    if (kind === "conn") {
      ctx.beginPath(); ctx.moveTo(cx, cy - 9); ctx.lineTo(cx + 9, cy + 7); ctx.lineTo(cx - 9, cy + 7); ctx.closePath();
      ctx.fill(); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.arc(cx, cy, kind === "boss" ? 9 : 7, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
    legend.push({ name, x, y, kind, index: legend.length + 1 });
    ctx.fillStyle = "#000";
    ctx.font = "bold 11px sans-serif";
    ctx.fillText(String(legend.length), cx + 8, cy - 6);
  }
  return { mapId, canvas, legend, width, height };
}

async function renderEpisodes(episodes) {
  fs.mkdirSync(RENDER_DIR, { recursive: true });
  const LABEL = 24, LINE = 14, MARGIN = 16;
  for (const ep of episodes) {
    const ids = episodeMaps(ep).filter((id) => !onlySet || onlySet.has(id));
    if (!ids.length) continue;
    const panels = [];
    for (const id of ids) panels.push(await renderMapOverlay(id));
    const sheetW = Math.max(...panels.map((p) => p.canvas.width)) + MARGIN * 2;
    const sheetH = panels.reduce((sum, p) => sum + p.canvas.height + LABEL + p.legend.length * LINE + MARGIN, MARGIN);
    const sheet = createCanvas(sheetW, sheetH);
    const sctx = sheet.getContext("2d");
    sctx.imageSmoothingEnabled = false;
    sctx.fillStyle = "#141414";
    sctx.fillRect(0, 0, sheet.width, sheet.height);
    let y = MARGIN;
    for (const panel of panels) {
      sctx.fillStyle = "#fff";
      sctx.font = "bold 16px sans-serif";
      sctx.fillText(`Map${panel.mapId} — ${panel.width}×${panel.height}`, MARGIN, y + 12);
      y += LABEL - 4;
      sctx.drawImage(panel.canvas, MARGIN, y);
      y += panel.canvas.height + 4;
      sctx.font = "12px sans-serif";
      for (const item of panel.legend) {
        sctx.fillStyle = MARKER[item.kind];
        sctx.fillRect(MARGIN, y + 2, 8, 8);
        sctx.fillStyle = "#ddd";
        sctx.fillText(`${item.index}. ${item.name} (${item.x},${item.y})`, MARGIN + 14, y + 10);
        y += LINE;
      }
      y += MARGIN;
    }
    const out = path.join(RENDER_DIR, `${ep.key}.png`);
    fs.writeFileSync(out, sheet.toBuffer("image/png"));
    console.log(`render E4 → ${path.relative(ROOT, out)} (${panels.length} mapas, ${(fs.statSync(out).size / 1048576).toFixed(1)} MB)`);
  }
}

// ------------------------------------------------------------------- main
const hubCell = resolveHubCell();
const artPending = [];   // «mapId: NPC sin sprite (arte pendiente)»
let anomalyCount = 0;
const onlySet = ONLY ? new Set(ONLY) : null;
const scopeEpisodes = blueprint.episodes.filter((ep) => {
  if (onlySet) return onlySet.has(ep.mapRange.from) || [...onlySet].some((id) => id >= ep.mapRange.from && id <= ep.mapRange.to);
  if (EPISODE) return ep.key === EPISODE;
  return true;
});

function episodeMaps(ep) {
  const ids = [];
  for (let id = ep.mapRange.from; id <= ep.mapRange.to; id++) if (builtMaps.has(id)) ids.push(id);
  return ids;
}

let installed = 0, npcCount = 0, eventCount = 0, transferCount = 0;

if (!VERIFY)
for (const ep of scopeEpisodes) {
  const ids = episodeMaps(ep);
  if (!ids.length) continue;
  const hub = hubCell;
  for (let index = 0; index < ids.length; index++) {
    const mapId = ids[index];
    const mask = maskOf(mapId);
    if (!mask) { warnings.push(`${mapId}: sin pasabilidad; se omite`); continue; }
    const occupied = new Set();
    // lo que instala la pasada de jefes (`BOSSB_*`) ocupa su celda: se conserva y se respeta
    const previousEvents = read(mapFile(mapId)).getIvar("@events")?.pairs ?? [];
    for (const [, ev] of previousEvents) {
      if ((ev.getIvar("@name")?.text ?? "").startsWith("BOSSB_")) occupied.add(`${ev.getIvar("@x")},${ev.getIvar("@y")}`);
    }
    const events = [];
    let nextId = 1;
    const add = (name, x, y, pages) => {
      events.push(event(nextId++, name, x, y, pages));
      occupied.add(`${x},${y}`);
    };

    // --- conexiones ---
    const prev = index > 0 ? ids[index - 1] : null;
    const next = index < ids.length - 1 ? ids[index + 1] : null;
    const entry = entryCell(mask);
    if (prev) {
      add(`CONN_${prev}_entrada`, entry[0], entry[1], [page({
        trigger: 1, through: true,
        list: [transfer(prev, ...exitCell(maskOf(prev), "down") ?? entry, 8), cmd(0)],
      })]);
      transferCount++;
    } else {
      add("CONN_HUB_entrada", entry[0], entry[1], [page({
        trigger: 1, through: true,
        list: [transfer(hub.map, hub.cell[0], hub.cell[1], 8), cmd(0)],
      })]);
      transferCount++;
    }
    if (next) {
      const out = exitCell(mask, "down");
      const target = entryCell(maskOf(next));
      add(`CONN_${next}_salida`, out[0], out[1], [page({
        trigger: 1, through: true,
        list: [transfer(next, ...target, 2), cmd(0)],
      })]);
      transferCount++;
    }

    // --- NPCs ---
    const anchor = entry ?? [Math.floor(mask.width / 2), Math.floor(mask.height / 2)];
    for (const npc of ep.npcs.filter((n) => n.map === mapId)) {
      const spot = placeNear(mask, [Math.min(mask.width - 2, anchor[0] + 2), Math.min(mask.height - 2, anchor[1] + 2)], occupied);
      if (!spot) { warnings.push(`${mapId}: sin sitio para ${npc.name}`); continue; }
      let file = npc.sprite.replace(/[()*]/g, "").trim();
      // Celdas que describen el evento en vez de nombrar un archivo, y placeholders del GDD
      // («Sprite R3» sin arte todavía): el NPC queda sin gráfico, no con un muñeco cualquiera.
      if (!file || /^(texto|tiles|objeto|sprite|pendiente|n\/?a|—|-)$/i.test(file) || /texto|tiles|objeto|estatuas/i.test(npc.sprite)) {
        file = "";
        artPending.push(`${mapId}: ${npc.name} sin sprite (arte pendiente)`);
      }
      else if (!fs.existsSync(path.join(CHARS, `${file}.png`))) {
        const alt = file.replace(/^SWIMMER/, "trainer_SWIMMER").replace(/^([A-Z])/, (c) => c.toLowerCase());
        if (fs.existsSync(path.join(CHARS, `${alt}.png`))) file = alt;
        else { warnings.push(`${mapId}: sprite ${npc.sprite} no existe; se usa trchar000 (${npc.name})`); file = "trchar000"; }
      }
      const npcKey = npc.name.replace(/[^\w]/g, "_").slice(0, 24);
      const npcSuffix = (npc.groupCount ?? 1) > 1 ? `_${String(npc.instance).padStart(2, "0")}` : "";
      add(`NPC_${npcKey}${npcSuffix}`, spot[0], spot[1], npcPages({ ...npc, graphic: file }));
      npcCount++;
    }

    // --- anomalías (§5): una por ficha, con su contador ---
    for (const item of ep.anomalies.items) {
      if (item.map !== mapId) continue;
      const desired = item.cells[0] && inBounds(mask, item.cells[0][0], item.cells[0][1])
        ? item.cells[0]
        : [Math.max(1, anchor[0] - 1), Math.min(mask.height - 2, anchor[1] + 1)];
      const spot = walkAt(mask, desired[0], desired[1]) && !occupied.has(`${desired[0]},${desired[1]}`)
        ? desired
        : placeNear(mask, desired, occupied);
      if (!spot) { warnings.push(`${mapId}: sin sitio para la anomalía ${item.code}`); continue; }
      add(`ANOM_${item.code}`, spot[0], spot[1], anomalyPages(item, ep));
      anomalyCount++;
    }

    // --- eventos del índice ---
    // Los eventos sin mapa explícito en el GDD se instalan UNA vez, en el mapa del jefe
    // (antes se replicaban en todos los mapas del episodio y multiplicaban el recuento).
    const isBossMap = index === ids.length - 1;
    const phaseBPending = isBossMap ? ep.boss?.phaseB?.kind ?? null : null;
    const forThisMap = ep.events.filter((e) => (e.maps.length ? e.maps.includes(mapId) : isBossMap));
    for (const ev of forThisMap) {
      if (!ev.maps.length) warnings.push(`${ev.name}: sin mapa en el GDD; se instala en ${mapId} (mapa del jefe)`);
      const instances = ev.maps.length ? Math.max(1, Math.min(ev.instances, ev.cells.length || ev.instances)) : 1;
      for (let k = 0; k < instances; k++) {
        const desired = ev.cells[k] && inBounds(mask, ev.cells[k][0], ev.cells[k][1]) ? ev.cells[k] : [anchor[0], Math.max(0, anchor[1] - 2 - k)];
        const spot = placeNear(mask, desired, occupied);
        if (!spot) { warnings.push(`${mapId}: sin sitio para ${ev.name}`); break; }
        add(`${ev.name}${instances > 1 ? `_${k + 1}` : ""}`, spot[0], spot[1], indexedEventPages(ev));
        eventCount++;
      }
    }

    // El silenciador opera sólo durante 60 s y sin alterar BGM de otros episodios. Este
    // guardián paralelo vuelve a comprobar el temporizador al entrar/cambiar de mapa en EP04.
    if (ep.key === "EP04") {
      const audioSpot = placeNear(mask, [anchor[0], Math.min(mask.height - 2, anchor[1] + 3)], occupied);
      if (!audioSpot) warnings.push(`${mapId}: sin sitio para DN_AUDIO_EP04`);
      else add("DN_AUDIO_EP04", audioSpot[0], audioSpot[1], hypnoAudioGuardPages());
    }

    // --- jefe, sello y salida (mapa final) ---
    if (index === ids.length - 1) {
      const boss = ep.boss ?? null;
      if (boss) {
        const bossSpot = placeNear(mask, [Math.floor(mask.width / 2), Math.floor(mask.height / 2)], occupied) ?? anchor;
        const phaseA = boss.phaseA ?? { type: "HIKER", label: ep.bossName, trainer: `DN_${ep.key}_A` };
        const phaseB = boss.phaseB ?? null;
        const battleSwitch = phaseASwitch(ep);
        const stepVariable = phaseBVariable(ep);
        const stepTotal = phaseBTotal(ep);
        const call = `begin; pbTrainerBattle(PBTrainer.new("${phaseA.type}", "${phaseA.label}"), false, "", true); rescue; pbMessage("(jefe pendiente de registrar: ${phaseA.trainer})"); false; end`;
        const phaseASuccess = (indent = 1) => [
          script(`$game_variables[${stepVariable}] = 0`, indent),
          setSwitch(battleSwitch, indent),
        ];
        const bossList = [
          ...texts([`${ep.bossName} te espera.`, "El Rotom registra el pico de resonancia."]),
          cmd(111, [12, S(call)]),
          ...phaseASuccess(1),
          ...texts(["La batalla queda registrada. Ahora golpea lo que lo sostiene."], 1),
          cmd(411),
          ...texts(["La derrota no cierra el mundo. Cuando estés preparado, vuelve a tocar el evento para intentarlo de nuevo."], 1),
          setSelf("A", 1),
          cmd(412),
          cmd(0),
        ];
        const retryList = [
          ...texts([`${ep.bossName} sigue en pie. ¿Lo intentas otra vez?`]),
          cmd(111, [12, S(call)]),
          ...phaseASuccess(1),
          ...texts(["La batalla queda registrada. La fase B te espera."], 1),
          cmd(411),
          ...texts(["Todavía no. Puedes recuperarte y volver a intentarlo cuando quieras."], 1),
          cmd(412),
          cmd(0),
        ];
        const bossPendingList = [
          ...texts([
            phaseB ? `${ep.bossName} no cae a golpes: ${phaseB.verb} ${phaseBTotal(ep)} ${phaseB.noun}${phaseBTotal(ep) === 1 ? "" : "s"} del escenario.` : `${ep.bossName} sigue en pie.`,
            "El Rotom marca cada paso en el itinerario.",
          ]),
          cmd(0),
        ];
        const bossEpilogueList = [
          ...texts([`${ep.bossName} ya no está. El sello aguanta.`,
            "Lo que bajó contigo no puede volver a bajar. Pero puede recordar."]),
          cmd(0),
        ];
        // La derrota sólo habilita una página de reintento; el switch de fase A se enciende
        // únicamente en la rama verdadera del condicional (pbTrainerBattle devuelve victoria).
        const bossPages = [
          page({ trigger: 3, list: bossList }),
          page({ cond: condition({ self: "A" }), gfx: graphic(""), through: true, list: retryList }),
          page({ cond: condition({ sw: battleSwitch }), gfx: graphic(""), list: bossPendingList }),
          page({
            cond: condition({ sw: ep.seal, sw2: battleSwitch, variable: [stepVariable, stepTotal] }),
            gfx: graphic(""), list: bossEpilogueList,
          }),
        ];
        add(`EV_${ep.key}_JEFE`, bossSpot[0], bossSpot[1], bossPages);
      }
      if (ep.key === "NEXO") {
        const finalSpot = placeNear(mask, [anchor[0] + 1, anchor[1]], occupied) ?? anchor;
        add("EV_NEXO_FINAL", finalSpot[0], finalSpot[1], nexoResolutionPages());
      }
      // La salida sólo se abre cuando el estado completo del episodio se confirma, no por una
      // mención textual del sello en otro evento. En el Nexo, cualquiera de los dos finales
      // habilita el retorno; `sw889` sólo representa el final sellado.
      const exitSpot = placeNear(mask, [anchor[0], anchor[1]], occupied) ?? anchor;
      const exitCondition = ep.key === "NEXO"
        ? condition({ sw: NEXO_RESOLVED_SWITCH })
        : condition({ sw: ep.seal, sw2: phaseASwitch(ep), variable: [phaseBVariable(ep), phaseBTotal(ep)] });
      add(`EV_${ep.key}_HUBSALIDA`, exitSpot[0], exitSpot[1], [page({
        cond: exitCondition, trigger: 1, through: true,
        list: [transfer(hub.map, hub.cell[0], hub.cell[1], 8), cmd(0)],
      })]);
      transferCount++;
    }

    // --- volcado al mapa ---
    const mapPath = path.join(DATA, mapFile(mapId));
    const mapObject = read(mapFile(mapId));
    // Conserva lo que instala la pasada de jefes (`BOSSB_*`): este tool reescribe el mapa entero.
    const carried = (mapObject.getIvar("@events")?.pairs ?? []).filter(([, ev]) => (ev.getIvar("@name")?.text ?? "").startsWith("BOSSB_"));
    let carryId = Math.max(0, ...events.map((ev) => ev.getIvar("@id"))) + 1;
    const hash = new RHash([
      ...events.map((ev) => [ev.getIvar("@id"), ev]),
      ...carried.map(([, ev]) => [carryId++, ev]),
    ]);
    mapObject.setIvar("@events", hash);
    write(mapFile(mapId), mapObject);
    installed++;
    result.maps[String(mapId)] = {
      episode: ep.key,
      events: events.length,
      npcs: ep.npcs.filter((n) => n.map === mapId).length,
      entry, exit: index < ids.length - 1 ? exitCell(mask, "down") : null,
      boss: index === ids.length - 1 ? ep.bossName : null,
      pending: [
        ...(index === ids.length - 1 ? (phaseBPending ? [`fase B del jefe (${phaseBPending})`] : []) : []),
        ...artPending.filter((p) => p.startsWith(`${mapId}:`)),
      ],
    };
    if (!DRY) console.log(`${mapId} ${ep.key}: ${events.length} eventos (${result.maps[String(mapId)].npcs} NPCs) · entrada ${entry.join(",")}`);
  }
}

if (RENDER) await renderEpisodes(scopeEpisodes);

if (!DRY && !VERIFY) {
  result.hub = hubCell;
  fs.writeFileSync(BUILT, `${JSON.stringify(result, null, 2)}\n`);
  console.log(`\ninstalados: ${installed} mapas · ${npcCount} NPCs · ${anomalyCount} anomalías · ${eventCount} eventos de índice · ${transferCount} transferencias`);
  if (warnings.length) {
    console.log(`avisos (${warnings.length}):`);
    for (const w of warnings.slice(0, 12)) console.log(`  - ${w}`);
  }
}

// ---------------------------------------------------------------- verificación
if (VERIFY) {
  let failures = 0;
  const ok = (cond, label) => { if (!cond) { failures++; console.error(`  FALLA: ${label}`); } };
  const builtEventData = JSON.parse(fs.readFileSync(BUILT, "utf8"));
  const catalog = builtEventData.maps;
  const entries = Object.entries(catalog);
  const anomalyTally = new Map();
  console.log(`verificación de ${entries.length} mapas con eventos`);
  for (const [id, info] of entries) {
    const mapId = Number(id);
    const mapObject = read(mapFile(mapId));
    const events = mapObject.getIvar("@events");
    ok(events?.pairs?.length > 0, `${id}: sin eventos`);
    const seen = new Set();
    let transfers = 0;
    const mask = maskOf(mapId);
    const entry = info.entry ?? builtMaps.get(mapId)?.entry;
    const reachable = mask && entry ? reachableMask(mask, entry) : new Set();
    let anomalies = 0;
    for (const [, ev] of events.pairs ?? []) {
      const x = ev.getIvar("@x"), y = ev.getIvar("@y");
      const built = builtMaps.get(mapId);
      const evName = ev.getIvar("@name")?.text ?? "?";
      if (built) ok(x >= 0 && y >= 0 && x < built.width && y < built.height, `${id}: evento ${evName} fuera de límites (${x},${y})`);
      if (mask) ok(walkAt(mask, x, y), `${id}: ${evName} sobre una celda bloqueada (${x},${y})`);
      if (mask && /^(CONN_|NPC_|ANOM_|EV_|BOSSB_|MEDALLA_)/.test(evName)) {
        ok(reachable.has(`${x},${y}`), `${id}: ${evName} no es alcanzable desde la entrada ${entry}`);
      }
      if (evName.startsWith("ANOM_")) anomalies++;
      ok(!seen.has(`${x},${y}`), `${id}: dos eventos en ${x},${y}`);
      seen.add(`${x},${y}`);
      const pages = ev.getIvar("@pages") ?? [];
      if (evName.startsWith("ANOM_")) {
        ok(pages.length === 2, `${id}: ${evName} debe cerrarse tras el primer registro`);
        ok((pages[0]?.getIvar("@list") ?? []).some((c) => c.getIvar("@code") === 123
          && txt(c.getIvar("@parameters")?.[0]) === "A"), `${id}: ${evName} no activa self-switch A`);
        ok(pages[1]?.getIvar("@condition")?.getIvar("@self_switch_valid") === true
          && txt(pages[1]?.getIvar("@condition")?.getIvar("@self_switch_ch")) === "A",
        `${id}: ${evName} carece de página de cierre self-switch A`);
      }
      if (evName === "EV_NEXO_FINAL") {
        const firstPage = pages[0];
        const firstCommands = firstPage?.getIvar("@list") ?? [];
        const scriptSources = firstCommands.filter((c) => c.getIvar("@code") === 355)
          .map((c) => txt(c.getIvar("@parameters")?.[0]));
        const sealChoice = scriptSources.find((source) => source.includes("$game_variables[276] = 0")) ?? "";
        const openChoice = scriptSources.find((source) => source.includes("$game_variables[276] = 1")) ?? "";
        ok(pages.length === 2 && firstPage?.getIvar("@condition")?.getIvar("@switch1_valid") === true
          && firstPage?.getIvar("@condition")?.getIvar("@switch1_id") === 888,
        `${id}: EV_NEXO_FINAL debe abrirse tras sw888 y cerrarse después de la decisión`);
        ok(firstCommands.some((c) => c.getIvar("@code") === 102)
          && firstCommands.some((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A"),
        `${id}: EV_NEXO_FINAL carece de elección o de cierre one-shot`);
        ok(sealChoice.includes("$game_switches[889] = true") && sealChoice.includes(`$game_switches[${NEXO_RESOLVED_SWITCH}] = true`),
          `${id}: la opción sellar no activa sw889 y sw${NEXO_RESOLVED_SWITCH}`);
        ok(openChoice.includes("$game_switches[889] = false") && openChoice.includes(`$game_switches[${NEXO_RESOLVED_SWITCH}] = true`),
          `${id}: la opción dejar abierto no limpia sw889 o no activa sw${NEXO_RESOLVED_SWITCH}`);
        ok(pages[1]?.getIvar("@condition")?.getIvar("@self_switch_valid") === true
          && txt(pages[1]?.getIvar("@condition")?.getIvar("@self_switch_ch")) === "A",
        `${id}: la página de resultado no depende del self-switch A`);
      }
      const isGenericIndex = evName.startsWith("EV_")
        && !/^EV_(?:EP\d\d|W\d+)_JEFE$/.test(evName)
        && !evName.endsWith("_HUBSALIDA") && evName !== "EV_NEXO_FINAL";
      for (const pg of pages) {
        for (const command of pg.getIvar("@list") ?? []) {
          const code = command.getIvar("@code");
          const params = command.getIvar("@parameters") ?? [];
          if (code === 201) {
            transfers++;
            const [target, tx, ty] = [params[1], params[2], params[3]];
            const exists = fs.existsSync(path.join(DATA, mapFile(target)));
            ok(exists, `${id}: transfer a mapa inexistente ${target}`);
            const targetMask = physicalMaskOf(target);
            if (targetMask) {
              ok(walkAt(targetMask, tx, ty), `${id}: transfer a celda bloqueada ${target} (${tx},${ty})`);
              let targetStart = catalog[String(target)]?.entry ?? builtMaps.get(target)?.entry;
              if (target === hubCell.map) targetStart = hubCell.cell;
              if (target === 2040) targetStart = builtEventData.hubMap?.entry ?? targetStart;
              targetStart ??= [tx, ty];
              ok(reachableMask(targetMask, targetStart).has(`${tx},${ty}`),
                `${id}: transfer a destino aislado ${target} @ ${tx},${ty} (entrada ${targetStart})`);
            } else if (exists) {
              ok(target === hubCell.map || target === 2040, `${id}: transfer a ${target} sin malla ni destino de hub conocido`);
            }
          }
          if (code === 121) {
            ok(params[0] >= 882 && params.length >= 3 && params[0] === params[1] && (params[2] === 0 || params[2] === 1),
              `${id}: comando switch 121 inválido (${params.join(",")})`);
          }
          if (code === 355) {
            const source = txt(params[0]);
            ok(!/\$game_variables\[264\]\s*(?:=(?!=)|\+=|-=|\*=|\/=)/.test(source),
              `${id}: ${evName} altera v264, reservado al contador de Monte Silver`);
          }
          if (isGenericIndex) {
            ok(code !== 121, `${id}: ${evName} escribe una switch de progreso desde texto libre`);
            if (code === 355) {
              const source = txt(params[0]);
              ok(!/\$game_switches\[(?:883|884|885|886|887|888|889|890|891|892|893|894|895|922|923|924|925|926|927)\]/.test(source),
                `${id}: ${evName} escribe un sello/grieta fuera de su máquina de estado`);
              ok(!/\$game_variables\[266\]\s*=/.test(source), `${id}: ${evName} altera fase global desde texto libre`);
            }
          }
        }
      }
    }
    if (mapId >= 2088 && mapId <= 2103) {
      const named = new Map((events.pairs ?? []).map(([, ev]) => [ev.getIvar("@name")?.text ?? "", ev]));
      const audioGuard = named.get("DN_AUDIO_EP04");
      const guardPage = audioGuard?.getIvar("@pages")?.[0];
      const guardCommands = guardPage?.getIvar("@list") ?? [];
      const guardScript = guardCommands.filter((c) => c.getIvar("@code") === 355).map((c) => txt(c.getIvar("@parameters")?.[0])).join(" ");
      ok(!!audioGuard && guardPage?.getIvar("@trigger") === 2 && guardScript.includes(HYPNO_SILENCE_UNTIL),
        `${id}: falta DN_AUDIO_EP04 paralelo para respetar el silenciador al cambiar de mapa`);
      if ([2094, 2096, 2098].includes(mapId)) {
        const sleepEvent = named.get("EV_HYP_Sueno");
        const sleepPage = sleepEvent?.getIvar("@pages")?.[0];
        const sleepCommands = sleepPage?.getIvar("@list") ?? [];
        ok(sleepPage?.getIvar("@trigger") === 2
          && sleepCommands.some((c) => c.getIvar("@code") === 106 && c.getIvar("@parameters")?.[0] === 2700)
          && sleepCommands.some((c) => c.getIvar("@code") === 111),
        `${id}: EV_HYP_Sueno debe comprobar cada 45 s que no haya silenciador activo`);
      }
      if (mapId === 2103) {
        const silencers = [...named.entries()].filter(([name]) => /^EV_HYP_Silenciador_\d+$/.test(name));
        const expected = [[5, 2], [8, 4], [3, 5], [14, 5], [19, 4], [21, 6]];
        ok(silencers.length === 6, `2103: hay ${silencers.length}/6 troncos silenciadores`);
        ok(silencers.every(([, ev]) => ev.getIvar("@pages")?.length === 2
          && (ev.getIvar("@pages")?.[0]?.getIvar("@list") ?? []).some((c) => c.getIvar("@code") === 355
            && txt(c.getIvar("@parameters")?.[0]).includes(HYPNO_SILENCE_UNTIL))
          && (ev.getIvar("@pages")?.[0]?.getIvar("@list") ?? []).some((c) => c.getIvar("@code") === 123 && txt(c.getIvar("@parameters")?.[0]) === "A")),
        "2103: cada tronco debe contar una vez, iniciar los 60 s y cerrarse con self-switch A");
        const actual = silencers.map(([, ev]) => [ev.getIvar("@x"), ev.getIvar("@y")]);
        ok(expected.every(([x, y]) => actual.some(([ax, ay]) => ax === x && ay === y)),
          "2103: las seis celdas del silenciador deben coincidir con las coordenadas del GDD");
      }
    }
    ok(transfers >= 1, `${id}: sin ninguna transferencia`);
    anomalyTally.set(info.episode, (anomalyTally.get(info.episode) ?? 0) + anomalies);
  }
  // cada episodio debe tener instaladas tantas anomalías como declara su §5
  for (const [key, count] of anomalyTally) {
    const declared = blueprint.episodes.find((e) => e.key === key)?.anomalies.declared ?? 0;
    ok(count === declared, `${key}: ${count} anomalías instaladas; el GDD declara ${declared}`);
    console.log(`  ${key}: ${count}/${declared} anomalías`);
  }
  console.log(failures === 0 ? "verificación OK" : `verificación con ${failures} fallos`);
  process.exit(failures === 0 ? 0 : 1);
}#!/usr/bin/env node
/**
 * apply_dimensional_nightmare_maps.mjs — E3: convierte cada ficha de referencia
 * del Dimensional Nightmare en un mapa jugable de RPG Maker XP.
 *
 * Por cada mapa del plano (`content/dimensional_nightmare_maps.json`):
 *   1. toma su ficha (recorte del mosaico) del catálogo ×2 de E2;
 *   2. construye un **tileset por mapa** (`DN_<id>.png`) con solo los bloques de
 *      32×32 que ese mapa usa y registra la entrada correspondiente en
 *      `Tilesets.rxdata` (autotiles vacíos, pasajes/priorities/terrain desde el
 *      índice 384);
 *   3. escribe `Map<id>.rxdata` con la matriz de la ficha en la capa 1 — el mapa
 *      es la escena de referencia, sin invenciones;
 *   4. añade la entrada de `MapInfos.rxdata` y copia los metadatos de un mapa
 *      plantilla de `map_metadata.dat` (BGM de combate incluido).
 *
 * Pasajes: heurística conservadora + `content/dimensional_nightmare_passability.json`
 * (overrides manuales) + BFS de diagnóstico. Nada de esto toca partidas.
 *
 * Uso:
 *   node tools/apply_dimensional_nightmare_maps.mjs --only 2041,2088,2120   # piloto
 *   node tools/apply_dimensional_nightmare_maps.mjs --episode EP01
 *   node tools/apply_dimensional_nightmare_maps.mjs --all
 *   node tools/apply_dimensional_nightmare_maps.mjs --verify
 *   ... --dry-run (no escribe) · --render (comparativas antes/después)
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalLoad, marshalDump, RObject, RString } from "../web/js/marshal.js";

const S = (v) => RString.fromText(String(v));
import { parseMap, parseTileset, tableGet, tableToUserDef } from "../web/js/rmxp.js";
import { TileCanvas, buildMapObject, passabilityOf, reachableCells } from "./lib/map_painter.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "pokemon_fire_ash", "Data");
const GRAPHICS = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Tilesets");
const BACKUP = path.join(ROOT, "pokemon_fire_ash", "PokeModBackups", "dimensional_nightmare_maps_originals");
const RENDER_DIR = path.join(ROOT, "docs", "dn_referencia", "detalle");
const BLUEPRINT = path.join(ROOT, "content", "dimensional_nightmare_maps.json");
const CATALOG = path.join(ROOT, "content", "dimensional_nightmare_tiles_2x.json");
const BUILT_PATH = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const OVERRIDES_PATH = path.join(ROOT, "content", "dimensional_nightmare_passability.json");
const BASE_ID = 384;            // primer id de tile normal (0-47 vacío, 48-383 autotiles)
const TILE = 32;
const COLUMNS = 8;
const PASS_BLOCKED = 0x0f;
const METADATA_TEMPLATE = 2021; // mapa del que se heredan BGM de combate y campos comunes

const argv = process.argv.slice(2);
const flag = (name) => argv.includes(name);
const option = (name, fallback) => {
  const at = argv.indexOf(name);
  return at >= 0 && argv[at + 1] ? argv[at + 1] : fallback;
};
const ONLY = option("--only", null)?.split(",").map((s) => Number(s.trim())).filter(Boolean) ?? null;
const EPISODE = option("--episode", null);
const ALL = flag("--all");
const DRY = flag("--dry-run");
const VERIFY_ONLY = flag("--verify");
const RENDER = flag("--render");

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => {
  if (DRY) return;
  fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));
};
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;

// ---------------------------------------------------------------- selección
const blueprint = JSON.parse(fs.readFileSync(BLUEPRINT, "utf8"));
const catalog = JSON.parse(fs.readFileSync(CATALOG, "utf8"));

function selectedMaps() {
  let maps = blueprint.maps.filter((m) => m.primary);
  if (ONLY) maps = maps.filter((m) => ONLY.includes(m.id));
  else if (EPISODE) maps = maps.filter((m) => m.episode === EPISODE);
  else if (!ALL && !VERIFY_ONLY) {
    maps = maps.filter((m) => [2041, 2088, 2120].includes(m.id)); // piloto por defecto
  }
  return maps;
}

function sliceOf(map) {
  const basename = path.basename(map.primary.slice);
  for (const group of catalog.groups) {
    const found = group.maps.find((m) => path.basename(m.slice) === basename && path.basename(path.dirname(m.slice)) === map.primary.key);
    if (found) return { group, map: found };
  }
  throw new Error(`La ficha ${map.primary.slice} no está en ${path.relative(ROOT, CATALOG)} (¿ejecutaste dn:ingest y dn:tiles:2x?)`);
}

// ------------------------------------------------------------- pasabilidad
const overrides = fs.existsSync(OVERRIDES_PATH) ? JSON.parse(fs.readFileSync(OVERRIDES_PATH, "utf8")) : { maps: {} };

/**
 * Pasaje por bloque:
 *  - sin archivo de pasajes: todo transitable salvo lo transparente (arranque abierto);
 *  - con archivo: muro si la celda está en `computed`/`blocked` y no está en `open`
 *    (o sus rectángulos). Como RMXP guarda el pasaje POR TILE, un tile que aparezca
 *    en alguna celda transitable se instala transitable: los muros del arte se
 *    bloquean porque sus tiles solo se usan en zonas marcadas como muro.
 */
function passageForBlock(data, width, x0, y0) {
  let transparent = 0;
  for (let y = 0; y < TILE; y++) {
    for (let x = 0; x < TILE; x++) {
      const i = ((y0 + y) * width + x0 + x) * 4;
      if (data[i + 3] < 16) transparent++;
    }
  }
  return transparent / (TILE * TILE) > 0.5 ? PASS_BLOCKED : 0;
}

/** Celdas de un rectángulo [x0,y0,x1,y1] recortado al mapa. */
function rectCellsIn(rect, width, height) {
  const [x0, y0, x1, y1] = rect;
  const cells = new Set();
  for (let y = Math.max(0, y0); y <= Math.min(height - 1, y1); y++) {
    for (let x = Math.max(0, x0); x <= Math.min(width - 1, x1); x++) cells.add(`${x},${y}`);
  }
  return cells;
}

/** Transitabilidad por celda según `content/dimensional_nightmare_passability.json`. */
function walkableCells(mapId, width, height) {
  const entry = overrides.maps?.[String(mapId)];
  if (!entry) return null; // sin archivo: todo abierto salvo transparencia
  const open = new Set(entry.open ?? []);
  const blocked = new Set([...(entry.computed ?? []), ...(entry.blocked ?? [])]);
  for (const rect of entry.openRects ?? []) for (const cell of rectCellsIn(rect, width, height)) { open.add(cell); blocked.delete(cell); }
  for (const rect of entry.blockRects ?? []) for (const cell of rectCellsIn(rect, width, height)) { blocked.add(cell); open.delete(cell); }
  const walkable = [];
  for (let y = 0; y < height; y++) {
    const row = [];
    for (let x = 0; x < width; x++) {
      const key = `${x},${y}`;
      row.push(open.has(key) || !blocked.has(key));
    }
    walkable.push(row);
  }
  return walkable;
}

// ------------------------------------------------------------- construcción
function uniqueTiles(matrix) {
  const order = [];
  const map = new Map();
  for (const row of matrix) {
    for (const original of row) {
      if (map.has(original)) continue;
      map.set(original, BASE_ID + order.length);
      order.push(original);
    }
  }
  return { order, localIdOf: map };
}

async function buildAtlas(group, order, outPng, { walkable, matrix, localIdOf }) {
  const source = await loadImage(path.join(ROOT, group.tileset));
  const canvas = createCanvas(COLUMNS * TILE, Math.ceil(order.length / COLUMNS) * TILE);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  order.forEach((original, k) => {
    const sx = (original % COLUMNS) * TILE;
    const sy = Math.floor(original / COLUMNS) * TILE;
    ctx.drawImage(source, sx, sy, TILE, TILE, (k % COLUMNS) * TILE, Math.floor(k / COLUMNS) * TILE, TILE, TILE);
  });
  const px = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  const passages = new Uint16Array(BASE_ID + order.length);
  const priorities = new Uint16Array(BASE_ID + order.length);
  // 1) pasaje base por transparencia del bloque
  order.forEach((original, k) => {
    passages[BASE_ID + k] = passageForBlock(px, canvas.width, (k % COLUMNS) * TILE, Math.floor(k / COLUMNS) * TILE);
  });
  // 2) si el mapa tiene pasajes definidos, manda la celda: un tile se instala
  //    transitable cuando al menos una de sus celdas lo es.
  if (walkable) {
    const passableTile = new Set();
    for (let y = 0; y < matrix.length; y++) {
      for (let x = 0; x < matrix[0].length; x++) {
        if (!walkable[y][x]) continue;
        passableTile.add(localIdOf.get(matrix[y][x]));
      }
    }
    order.forEach((original, k) => {
      const tileId = BASE_ID + k;                                   // localIdOf guarda ids absolutos
      if (passableTile.has(tileId)) passages[tileId] &= ~0x0f;      // limpia los bits de dirección → transitable
      else if ((passages[tileId] & 0x0f) !== PASS_BLOCKED) passages[tileId] |= PASS_BLOCKED;
    });
  }
  if (!DRY) {
    fs.mkdirSync(path.dirname(outPng), { recursive: true });
    fs.writeFileSync(outPng, canvas.toBuffer("image/png"));
  }
  return { canvas, passages, priorities };
}

function installTileset(mapId, title, tileCount, passages, priorities) {
  const raw = read("Tilesets.rxdata");
  const fileBase = `DN_${mapId}`;
  const existing = raw.findIndex((entry) => entry && String(entry.getIvar?.("@tileset_name")?.text ?? "") === fileBase);
  const id = existing > 0 ? existing : raw.length;
  const total = BASE_ID + tileCount;
  const table = (data) => tableToUserDef({ dim: 1, x: total, y: 1, z: 1, data });
  const obj = new RObject("RPG::Tileset", [
    ["@id", id],
    ["@name", S(`DN ${mapId} — ${title}`)],
    ["@tileset_name", S(fileBase)],
    ["@autotile_names", Array.from({ length: 7 }, () => S(""))],
    ["@panorama_name", S("")], ["@panorama_hue", 0],
    ["@fog_name", S("")], ["@fog_hue", 0], ["@fog_opacity", 64],
    ["@fog_blend_type", 0], ["@fog_zoom", 200], ["@fog_sx", 0], ["@fog_sy", 0],
    ["@battleback_name", S("")],
    ["@passages", table(passages)],
    ["@priorities", table(priorities)],
    ["@terrain_tags", table(new Uint16Array(total))],
  ]);
  if (existing > 0) raw[existing] = obj; else raw.push(obj);
  write("Tilesets.rxdata", raw);
  return id;
}

function installMapInfo(mapId, title) {
  const infos = read("MapInfos.rxdata");
  infos.pairs = infos.pairs.filter(([key]) => Number(key) !== mapId);
  infos.pairs.push([mapId, new RObject("RPG::MapInfo", [
    ["@scroll_x", 320], ["@name", S(`DN ${mapId} · ${title}`)], ["@expanded", false],
    ["@order", 1200 + (mapId - 2040)], ["@scroll_y", 240], ["@parent_id", 2030],
  ])]);
  write("MapInfos.rxdata", infos);
}

function installMetadata(mapId) {
  const metadata = read("map_metadata.dat");
  const source = metadata.pairs.find(([id]) => Number(id) === METADATA_TEMPLATE)?.[1];
  if (!source) return;
  const meta = new RObject(source.className, source.ivars.map(([key, value]) => [key, value]));
  meta.setIvar("id", mapId);
  meta.setIvar("weather", null);
  meta.setIvar("map_BGM", null);
  metadata.pairs = metadata.pairs.filter(([id]) => Number(id) !== mapId);
  metadata.pairs.push([mapId, meta]);
  write("map_metadata.dat", metadata);
}

function buildMapData(matrix, localIdOf, tilesetId) {
  const width = matrix[0].length, height = matrix.length;
  const canvas = new TileCanvas(width, height, tilesetId);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) canvas.set(x, y, 0, localIdOf.get(matrix[y][x]) ?? 0);
  }
  return { canvas, object: buildMapObject(canvas) };
}

/** Transitabilidad con las tablas en memoria (dry-run incluido): prioridades 0. */
function passabilityFromTables(canvas, passages) {
  const passable = (x, y, dir) => {
    if (x < 0 || y < 0 || x >= canvas.width || y >= canvas.height) return false;
    const bit = 1 << (dir / 2 - 1);
    for (let z = 2; z >= 0; z--) {
      const tile = canvas.get(x, y, z);
      if (!tile) continue;
      const p = passages[tile] ?? 0;
      if ((p & bit) !== 0 || (p & 0x0f) === 0x0f) return false;
      return true;
    }
    return true;
  };
  const step = { 2: [0, 1], 4: [-1, 0], 6: [1, 0], 8: [0, -1] };
  const canMove = (x, y, dir) => {
    const [dx, dy] = step[dir];
    const nx = x + dx, ny = y + dy;
    if (nx < 0 || ny < 0 || nx >= canvas.width || ny >= canvas.height) return false;
    return passable(x, y, dir) && passable(nx, ny, 10 - dir);
  };
  return { canMove, passable, terrain: () => 0, width: canvas.width, height: canvas.height };
}

/** BFS de diagnóstico: entrada = celda transitable más cercana al centro del borde inferior. */
function bfsReport(canvas, passages) {
  const pass = passabilityFromTables(canvas, passages);
  let entry = null;
  for (let y = canvas.height - 1; y >= 0 && !entry; y--) {
    for (let x = Math.floor(canvas.width / 2); x < canvas.width; x++) {
      if (pass.passable(x, y, 8)) { entry = [x, y]; break; }
    }
    for (let x = Math.floor(canvas.width / 2) - 1; x >= 0 && !entry; x--) {
      if (pass.passable(x, y, 8)) { entry = [x, y]; break; }
    }
  }
  if (!entry) return { entry: null, reachable: 0, walkable: 0, isolated: 0, ratio: 0 };
  const reachable = reachableCells(pass, entry);
  let walkable = 0;
  for (let y = 0; y < canvas.height; y++) for (let x = 0; x < canvas.width; x++) if (pass.passable(x, y, 8)) walkable++;
  return {
    entry,
    reachable: reachable.size,
    walkable,
    isolated: Math.max(0, walkable - reachable.size),
    ratio: walkable ? reachable.size / walkable : 0,
  };
}

async function renderComparison(map, built) {
  const ref = await loadImage(path.join(ROOT, map.primary.slice));
  const tileset = await loadImage(path.join(GRAPHICS, `DN_${map.id}.png`));
  const data = built.canvas;
  const canvas = createCanvas(data.width * TILE, data.height * TILE);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  for (let y = 0; y < data.height; y++) {
    for (let x = 0; x < data.width; x++) {
      const tile = data.get(x, y, 0);
      if (!tile) continue;
      const k = tile - BASE_ID;
      ctx.drawImage(tileset, (k % COLUMNS) * TILE, Math.floor(k / COLUMNS) * TILE, TILE, TILE, x * TILE, y * TILE, TILE, TILE);
    }
  }
  const pass = passabilityFromTables(data, built.passages);
  const reach = bfsReport(data, built.passages);
  const reachable = reach.entry ? reachableCells(pass, reach.entry) : new Set();
  const overlay = createCanvas(canvas.width, canvas.height);
  const octx = overlay.getContext("2d");
  for (let y = 0; y < data.height; y++) {
    for (let x = 0; x < data.width; x++) {
      const walkable = pass.passable(x, y, 8);
      octx.fillStyle = walkable ? (reachable.has(`${x},${y}`) ? "rgba(0,220,120,0.35)" : "rgba(255,200,0,0.45)") : "rgba(220,40,40,0.45)";
      octx.fillRect(x * TILE, y * TILE, TILE, TILE);
    }
  }
  const gap = 12;
  const total = createCanvas(ref.width + canvas.width + overlay.width + gap * 4, Math.max(ref.height, canvas.height) + gap * 2);
  const tctx = total.getContext("2d");
  tctx.imageSmoothingEnabled = false;
  tctx.fillStyle = "#1a1a1a";
  tctx.fillRect(0, 0, total.width, total.height);
  tctx.drawImage(ref, gap, gap);
  tctx.drawImage(canvas, gap * 2 + ref.width, gap);
  tctx.globalAlpha = 0.85;
  tctx.drawImage(overlay, gap * 3 + ref.width + canvas.width, gap);
  tctx.globalAlpha = 1;
  fs.mkdirSync(RENDER_DIR, { recursive: true });
  const out = path.join(RENDER_DIR, `${map.id}_comparacion.png`);
  fs.writeFileSync(out, total.toBuffer("image/png"));
  return { out, reach };
}

/** Copia de seguridad de los archivos del juego que se van a modificar (una sola vez). */
function ensureBackups() {
  fs.mkdirSync(BACKUP, { recursive: true });
  const files = ["Tilesets.rxdata", "MapInfos.rxdata", "map_metadata.dat"];
  for (const file of files) {
    const origin = path.join(DATA, file);
    const copy = path.join(BACKUP, file);
    if (fs.existsSync(origin) && !fs.existsSync(copy)) fs.copyFileSync(origin, copy);
  }
  const readme = path.join(BACKUP, "LEEME.txt");
  if (!fs.existsSync(readme)) {
    fs.writeFileSync(readme, "Copias anteriores a la instalación de los mapas del Dimensional Nightmare " +
      "(tilesets DN_*, MapInfos y map_metadata). No contienen partidas.\n" +
      "Para revertir: copia estos archivos sobre pokemon_fire_ash/Data/ y borra los Map2xxx.rxdata del ciclo.\n");
  }
}

// ------------------------------------------------------------------- main
ensureBackups();

if (!VERIFY_ONLY) {
  const maps = selectedMaps();
  if (!maps.length) {
    console.error("No hay mapas seleccionados.");
    process.exit(1);
  }
  const built = [];
  for (const map of maps) {
    const { group, map: fichaMap } = sliceOf(map);
    const { order, localIdOf } = uniqueTiles(fichaMap.matrix);
    const walkable = walkableCells(map.id, fichaMap.matrix[0].length, fichaMap.matrix.length);
    const png = path.join(GRAPHICS, `DN_${map.id}.png`);
    const atlas = await buildAtlas(group, order, png, { walkable, matrix: fichaMap.matrix, localIdOf });
    const tilesetId = installTileset(map.id, map.title, order.length, atlas.passages, atlas.priorities);
    const { canvas, object } = buildMapData(fichaMap.matrix, localIdOf, tilesetId);
    write(mapFile(map.id), object);
    installMapInfo(map.id, map.title);
    installMetadata(map.id);
    const bfs = bfsReport(canvas, atlas.passages);
    built.push({ ...map, tilesetId, tiles: order.length, width: canvas.width, height: canvas.height, bfs });
    const badge = bfs.ratio > 0.98 ? "OK" : `BFS ${(bfs.ratio * 100).toFixed(0)}%`;
    console.log(`${DRY ? "[dry-run] " : ""}${map.id} ${map.title} · ficha ${map.primary.resource}-${map.primary.index} · ${canvas.width}×${canvas.height} bloques · ${order.length} tiles · ts #${tilesetId} · ${badge}`);
  }
  if (!DRY) {
    // fusión con lo ya construido: cada lote añade sus mapas sin borrar los anteriores
    const previous = fs.existsSync(BUILT_PATH) ? JSON.parse(fs.readFileSync(BUILT_PATH, "utf8")).maps ?? [] : [];
    const byId = new Map(previous.map((m) => [m.id, m]));
    for (const entry of built) byId.set(entry.id, entry);
    const merged = [...byId.values()].sort((a, b) => a.id - b.id);
    fs.writeFileSync(BUILT_PATH, `${JSON.stringify({ generatedBy: "tools/apply_dimensional_nightmare_maps.mjs", counts: merged.length, maps: merged }, null, 2)}\n`);
    if (RENDER) {
      for (const map of built) {
        const info = await renderComparison(map, { canvas: rebuildFromFile(map.id), tilesetId: map.tilesetId, passages: passagesOfTileset(map.tilesetId) });
        console.log(`  render → ${path.relative(ROOT, info.out)} (BFS ${(info.reach.ratio * 100).toFixed(0)} %)`);
      }
    }
  }
}

/** Tablas de pasajes del tileset ya instalado (para render/verificación desde disco). */
function passagesOfTileset(tilesetId) {
  const raw = read("Tilesets.rxdata");
  const parsed = parseTileset(raw[tilesetId]);
  return parsed.passages.data;
}

/** Relee Map<id>.rxdata y devuelve un TileCanvas para renderizar/validar. */
function rebuildFromFile(mapId) {
  const parsed = parseMap(read(mapFile(mapId)));
  const canvas = new TileCanvas(parsed.width, parsed.height, parsed.tilesetId);
  for (let y = 0; y < parsed.height; y++) {
    for (let x = 0; x < parsed.width; x++) {
      for (const z of [0, 1, 2]) canvas.set(x, y, z, tableGet(parsed.table, x, y, z));
    }
  }
  return canvas;
}

if (VERIFY_ONLY) {
  let failures = 0;
  const ok = (condition, label) => {
    if (!condition) { failures++; console.error(`  FALLA: ${label}`); }
  };
  const built = fs.existsSync(BUILT_PATH) ? JSON.parse(fs.readFileSync(BUILT_PATH, "utf8")) : { maps: [] };
  const tilesets = read("Tilesets.rxdata");
  const infos = read("MapInfos.rxdata").pairs;
  const metadata = read("map_metadata.dat").pairs;
  console.log(`verificación de ${built.maps.length} mapas construidos`);
  for (const info of built.maps) {
    const file = path.join(DATA, mapFile(info.id));
    ok(fs.existsSync(file), `${info.id}: falta ${mapFile(info.id)}`);
    if (!fs.existsSync(file)) continue;
    const canvas = rebuildFromFile(info.id);
    ok(canvas.width === info.width && canvas.height === info.height, `${info.id}: tamaño ${canvas.width}×${canvas.height} ≠ ${info.width}×${info.height}`);
    const tileset = tilesets[info.tilesetId];
    ok(!!tileset, `${info.id}: tileset #${info.tilesetId} ausente`);
    if (info.reusedTileset) {
      // El hub (2040) reutiliza un tileset del juego base: no tiene DN_<id>.png propio.
      ok(!!tileset, `${info.id}: tileset base #${info.tilesetId} ausente`);
    } else {
      const entry = tileset?.getIvar("@tileset_name")?.text;
      ok(entry === `DN_${info.id}`, `${info.id}: @tileset_name «${entry}»`);
    }
    const parsedTileset = tileset ? parseTileset(tileset) : null;
    ok(parsedTileset && parsedTileset.passages.x >= BASE_ID + info.tiles, `${info.id}: tabla de pasajes corta`);
    if (!info.reusedTileset) ok(fs.existsSync(path.join(GRAPHICS, `DN_${info.id}.png`)), `${info.id}: falta el PNG del tileset`);
    ok(infos.some(([key]) => Number(key) === info.id), `${info.id}: falta en MapInfos`);
    ok(metadata.some(([key]) => Number(key) === info.id), `${info.id}: falta en map_metadata.dat`);
    // la matriz del mapa debe reproducir la ficha: se compara el render contra la referencia
    const pass = passabilityOf(canvas, info.tilesetId);
    let walkable = 0;
    for (let y = 0; y < canvas.height; y++) for (let x = 0; x < canvas.width; x++) if (pass.passable(x, y, 8)) walkable++;
    const bfs = bfsReport(canvas, passagesOfTileset(info.tilesetId));
    const ratio = walkable ? bfs.reachable / walkable : 0;
    if (ratio < 0.9) console.warn(`  aviso: ${info.id} BFS alcanza el ${(ratio * 100).toFixed(0)} % de las celdas transitables (aisladas: ${bfs.isolated})`);
  }
  console.log(failures === 0 ? "verificación OK" : `verificación con ${failures} fallos`);
  process.exit(failures === 0 ? 0 : 1);
}#!/usr/bin/env node
/**
 * apply_dimensiones_barco.mjs
 *
 * «Atlas, Glazed y Light Platinum son lugares a explorar accesibles desde
 * barco.» Atlas ya tenía su capitán; faltaban las otras dos. Esta herramienta
 * crea cinco dimensiones invitadas navegables: Glazed, Light Platinum,
 * Liquid Crystal, TFOH y Factory Adventure. Cada ROM conserva su propio
 * Fragmento y Ash llega expresamente como visitante, nunca como sustituto de
 * su protagonista ni como dueño de sus criaturas.
 *
 * Cada dimensión se construye con ventanas reales de mapas del juego, se une
 * con avenidas en serpentina y se comprueba que **no quede una sola celda
 * vacía ni aislada**. Después se puebla con capitán en Puerto Horizonte,
 * barco de vuelta en la orilla, cronista del Fragmento, cuatro entrenadores,
 * dos pobladores y un gimnasio nuevo con su líder y su medalla.
 *
 * Los capitanes están cerrados hasta el duelo de Arceus (switch 873): son
 * Fragmentos de dimensión, y eso es canon. La vuelta nunca está cerrada.
 *
 * Nada de esto toca contenido original: los mapas son nuevos y los datos se
 * añaden con identificadores nuevos.
 *
 * Uso:
 *   node tools/apply_dimensiones_barco.mjs
 *   node tools/apply_dimensiones_barco.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import {
  DATA, ROOT, S, choice, choiceCase, choiceEnd, cmd, condition, elseBranch, endBranch,
  endEvent, event, eventsOf, graphic, ifScript, installItems, installMapInfos,
  installMetadata, installTrainerTypes, installTrainers, makeChecker, page, pagesOf,
  script, selfSwitch, spread, switchOn, texts, tint, transfer, upsert, wait, txt,
} from "./lib/dlc_helpers.mjs";
import {
  celdasLibres, componer, componerGimnasio, publicar, verificarMapa,
} from "./lib/dimension_builder.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "dimensiones_barco.json"), "utf8"));
const DUELO = PLAN.interruptores.DUELO_RESUELTO;
const PUERTO = PLAN.puerto.mapa;
const REGRESO = PLAN.puerto.pistas[0];
const BACKUP = "dimensiones_barco";
const MARKER = "PokeMod Barco:";
const REQUIRED_DIMENSIONS = ["glazed", "lightplatinum", "liquidcrystal", "tfoh", "factoryadventure"];
const trainerType = (dim) => dim.tipoEntrenador ?? (dim.id === "glazed" ? "GLAZED_TRAINER" : "PLATINUM_TRAINER");
const battleVariable = (dim) => Number(dim.variableCombate ?? (dim.id === "glazed" ? 314 : 315));

/** Aplana bloques anidados dentro de una lista de comandos. */
const plano = (lista) => lista.flat(Infinity).filter(Boolean);

/** Viaje con fundido: fundido a negro, transferencia y fundido de vuelta. */
const viaje = (mapId, x, y, indent = 1) => [
  tint(-255, -255, -255, 0, 6, indent),
  wait(8, indent),
  transfer(mapId, x, y, 2, indent),
  tint(0, 0, 0, 0, 6, indent),
];

/** Bloque «¿Sí o No?» con dos ramas. */
function elegir(si, no, ramaSi, ramaNo, indent = 0) {
  return [
    choice([si, no], indent),
    choiceCase(0, si, indent),
    ...plano(ramaSi(indent + 1)),
    choiceCase(1, no, indent),
    ...plano(ramaNo(indent + 1)),
    choiceEnd(indent),
  ];
}

/* ─────────────────────────────── los mapas ──────────────────────────────── */

function construirMapas() {
  const informe = [];
  for (const dim of PLAN.dimensiones) {
    const { canvas, centros, pasillos, ventanas } = componer({
      tilesetId: dim.tileset,
      distritos: dim.distritos,
      lado: dim.lado,
      columnas: dim.columnas,
    });
    publicar(dim.mapaId, dim.titulo, canvas, { parentId: dim.padre, bgm: dim.musica || "" });
    const gimnasio = componerGimnasio({
      ancho: PLAN.gimnasio.ancho,
      alto: PLAN.gimnasio.alto,
      donante: PLAN.donanteGimnasio,
      tilesetId: PLAN.gimnasio.tileset,
    });
    publicar(dim.gimnasioId, dim.tituloGimnasio, gimnasio.canvas, { parentId: dim.mapaId });
    informe.push({ dim, ancho: canvas.width, alto: canvas.height, pasillos, ventanas });
  }
  return informe;
}

function instalarMapInfosYMetadatos() {
  const specs = [];
  for (const dim of PLAN.dimensiones) {
    specs.push({ mapId: dim.mapaId, title: dim.titulo, parentId: dim.padre, order: 900 });
    specs.push({ mapId: dim.gimnasioId, title: dim.tituloGimnasio, parentId: dim.mapaId, order: 901 });
  }
  installMapInfos(specs, BACKUP);
  installMetadata(specs.map((s) => ({ mapId: s.mapId, parentId: s.parentId })), BACKUP);
}

/* ─────────────────────────── datos del juego ────────────────────────────── */

function instalarDatos() {
  const tipos = [];
  const entrenadores = [];
  const medallas = [];
  for (const dim of PLAN.dimensiones) {
    const tipoBase = trainerType(dim);
    tipos.push({ id: tipoBase, base: "GENTLEMAN", nombre: dim.slug });
    tipos.push({ id: dim.lider.tipo, base: "LEADER_Brock", nombre: dim.lider.mostrado });
    for (const t of dim.entrenadores) {
      entrenadores.push({ tipo: tipoBase, nombre: t.nombre, equipo: t.equipo, nivel: 100, derrota: t.frase });
    }
    entrenadores.push({
      tipo: dim.lider.tipo, nombre: dim.lider.nombre, equipo: dim.lider.equipo,
      nivel: dim.lider.nivel, derrota: dim.lider.derrota,
    });
    medallas.push({ id: dim.medalla, base: "BOULDERBADGE", nombre: dim.nombreMedalla, plural: `${dim.nombreMedalla}s`, pocket: 8 });
  }
  return {
    tipos: installTrainerTypes(tipos, BACKUP),
    entrenadores: installTrainers(entrenadores, BACKUP),
    medallas: installItems(medallas, BACKUP),
  };
}

/* ───────────────────────────────── eventos ──────────────────────────────── */

const LLEGADA = [2, 2];

function capitanEvent(dim, cell) {
  return event(0, `${MARKER} Capitán — ${dim.slug}`, cell[0], cell[1], [
    // Sin el duelo de Arceus el Fragmento no se sostiene: no hay viaje.
    page({
      gfx: graphic(dim.capitan.sprite, 2, 1, {}),
      list: plano([
        ...texts([
          `${dim.capitan.nombre}: Esa dimensión todavía no existe.`,
          "Cuando el Fragmento se sostenga por sí solo, mi barco sabrá el camino. Hasta entonces, no.",
        ]),
        endEvent(),
      ]),
    }),
    // Con el duelo resuelto: zarpar o quedarse.
    page({
      cond: condition({ sw: DUELO }),
      gfx: graphic(dim.capitan.sprite, 2, 1, {}),
      list: plano([
        ...texts(dim.capitan.saludo),
        elegir("Zarpar", "Quedarse",
          (i) => [...texts([dim.capitan.ir], i), ...viaje(dim.mapaId, LLEGADA[0], LLEGADA[1], i), switchOn(dim.abierta, i)],
          (i) => texts([dim.capitan.quedarse], i)),
        endEvent(),
      ]),
    }),
  ]);
}

function eventosDimension(dim) {
  // Una baliza por distrito evita que el gran mapa compuesto se sienta vacío:
  // identifica cada zona y recuerda el papel de Ash como visitante.
  const total = 3 + dim.distritos.length + dim.entrenadores.length + dim.pobladores.length;
  const celdas = spread(celdasLibres(dim.mapaId), total);
  let i = 0;
  const siguiente = () => celdas[i++];

  const barco = siguiente();
  const puerta = siguiente();
  const cronista = siguiente();
  const eventos = [];

  // Barco de vuelta: disponible siempre, sin condiciones.
  eventos.push(event(0, `${MARKER} Barco a Puerto Horizonte`, barco[0], barco[1], [
    page({
      gfx: graphic(dim.capitan.sprite, 2, 1, {}),
      list: plano([
        ...texts([dim.muelle.saludo, dim.muelle.volver]),
        elegir("Volver", "Quedarse",
          (k) => viaje(PUERTO, REGRESO[0], REGRESO[1], k),
          (k) => texts(["Te quedas. El barco espera, no se cansa."], k)),
        endEvent(),
      ]),
    }),
  ]));

  // Puerta del gimnasio.
  eventos.push(event(0, `${MARKER} Puerta del Gimnasio — ${dim.slug}`, puerta[0], puerta[1], [
    page({
      cond: condition({ sw: dim.abierta }),
      gfx: graphic("", 2, 1, {}),
      list: plano([
        ...texts([`${dim.tituloGimnasio}. El ${dim.lider.mostrado} entrena dentro.`]),
        elegir("Entrar", "Seguir explorando",
          (k) => viaje(dim.gimnasioId, 2, 2, k),
          (k) => texts(["Vuelve cuando quieras."], k)),
        endEvent(),
      ]),
    }),
    page({
      gfx: graphic("", 2, 1, {}),
      list: plano([...texts(["La puerta del gimnasio está cerrada por dentro. Alguien entrena al otro lado."]), endEvent()]),
    }),
  ]));

  // Cronista del Fragmento.
  eventos.push(event(0, `${MARKER} Cronista — ${dim.slug}`, cronista[0], cronista[1], [
    page({
      gfx: graphic(dim.cronista.sprite, 2, 1, {}),
      list: plano([...texts(dim.cronista.lineas), endEvent()]),
    }),
  ]));

  // Balizas diegéticas: cada distrito tiene identidad y una pauta de visita.
  dim.distritos.forEach((distrito, index) => {
    const celda = siguiente();
    eventos.push(event(0, `${MARKER} Baliza ${index + 1} — ${distrito.label}`, celda[0], celda[1], [
      page({
        gfx: graphic("", 2, 1, {}),
        list: plano([
          ...texts([
            `${dim.slug} · Distrito ${index + 1}/${dim.distritos.length}: ${distrito.label}.`,
            `Ash visita este Fragmento como huésped. Explora, escucha y deja siempre abierto el camino de vuelta.`,
          ]),
          endEvent(),
        ]),
      }),
    ]));
  });

  // Entrenadores: se puede perder, nunca bloquean el paso.
  const tipoBase = trainerType(dim);
  const variable = battleVariable(dim);
  for (const t of dim.entrenadores) {
    const celda = siguiente();
    eventos.push(event(0, `${MARKER} Entrenador — ${t.nombre}`, celda[0], celda[1], [
      page({
        gfx: graphic(t.sprite, 2, 1, {}),
        list: plano([
          ...texts([t.frase]),
          script(`pbTrainerIntro(:${tipoBase})`),
          script(`$game_variables[${variable}] = pbTrainerBattle(:${tipoBase},"${t.nombre}",nil,false,0,true) ? 1 : 0`),
          script("pbTrainerEnd"),
          endEvent(),
        ]),
      }),
    ]));
  }

  // Pobladores.
  for (const p of dim.pobladores) {
    const celda = siguiente();
    eventos.push(event(0, `${MARKER} Poblador — ${dim.slug}`, celda[0], celda[1], [
      page({
        gfx: graphic(p.sprite, 2, 1, {}),
        list: plano([...texts(p.lineas), endEvent()]),
      }),
    ]));
  }

  return eventos;
}

function eventosGimnasio(dim) {
  const celdas = spread(celdasLibres(dim.gimnasioId), 2);
  const salida = celdas[0];
  const lider = celdas[1];
  return [
    event(0, `${MARKER} Salida del Gimnasio`, salida[0], salida[1], [
      page({
        gfx: graphic("", 2, 1, {}),
        list: plano([...texts(["Sales al aire libre."]), viaje(dim.mapaId, LLEGADA[0], LLEGADA[1], 0), endEvent()]),
      }),
    ]),
    event(0, `${MARKER} Líder — ${dim.lider.mostrado}`, lider[0], lider[1], [
      page({
        gfx: graphic(dim.lider.sprite, 2, 1, {}),
        list: plano([
          ...texts(dim.lider.intro),
          script(`pbTrainerIntro(:${dim.lider.tipo})`),
          ifScript(`pbTrainerBattle(:${dim.lider.tipo},"${dim.lider.nombre}",nil,false,0,true)`),
          ...texts([dim.lider.victoria], 1),
          script(`pbReceiveItem(:${dim.medalla})`, 1),
          selfSwitch("A", 0, 1),
          elseBranch(),
          ...texts([dim.lider.derrota], 1),
          endBranch(),
          script("pbTrainerEnd"),
          endEvent(),
        ]),
      }),
      page({
        cond: condition({ self: "A" }),
        gfx: graphic(dim.lider.sprite, 2, 1, {}),
        list: plano([...texts(["Entrena y vuelve: el gimnasio no se cierra."]), endEvent()]),
      }),
    ]),
  ];
}

function instalarCapitanes() {
  const libres = spread(celdasLibres(PUERTO), PLAN.dimensiones.length);
  const construidos = PLAN.dimensiones.map((dim, index) => capitanEvent(dim, libres[index]));
  upsert(PUERTO, [`${MARKER} Capitán`], () => construidos, BACKUP);
  return libres;
}

function instalar() {
  const mapas = construirMapas();
  instalarMapInfosYMetadatos();
  const datos = instalarDatos();
  const capitanes = instalarCapitanes();
  for (const dim of PLAN.dimensiones) {
    upsert(dim.mapaId, [MARKER], () => eventosDimension(dim), BACKUP);
    upsert(dim.gimnasioId, [MARKER], () => eventosGimnasio(dim), BACKUP);
  }
  return { mapas, datos, capitanes };
}

/* ──────────────────────────── verificación ──────────────────────────────── */

function verify() {
  const check = makeChecker("Dimensiones de barco");
  const ids = new Set(PLAN.dimensiones.map((dim) => dim.id));
  const mapIds = PLAN.dimensiones.flatMap((dim) => [dim.mapaId, dim.gimnasioId]);
  for (const required of REQUIRED_DIMENSIONS) check.ok(ids.has(required), `falta la dimensión ROM ${required}`);
  check.ok(ids.size === PLAN.dimensiones.length, "hay ids de dimensión repetidos");
  check.ok(new Set(mapIds).size === mapIds.length, "hay ids de mapa repetidos entre dimensiones");

  for (const dim of PLAN.dimensiones) {
    check.ok(!!dim.rom?.archivo, `${dim.slug}: falta la procedencia forense del ROM`);
    check.ok(Number.isInteger(dim.rom?.mapasDetectados), `${dim.slug}: falta el conteo forense de mapas`);
    check.ok(dim.cronista.lineas.some((linea) => /Ash/i.test(linea)), `${dim.slug}: Ash no está presentado como visitante`);
    const arranques = [LLEGADA];

    // — el mapa de la dimensión es jugable
    verificarMapa(check, dim.mapaId, dim.titulo, arranques, 0.25);
    verificarMapa(check, dim.gimnasioId, dim.tituloGimnasio, [[2, 2]], 0.25);

    // — capitán en el puerto, cerrado hasta el duelo
    const capitan = eventsOf(PUERTO).find((e) => e.name === `${MARKER} Capitán — ${dim.slug}`);
    check.ok(!!capitan, `falta el capitán de ${dim.slug} en el puerto ${PUERTO}`);
    if (capitan) {
      const paginas = pagesOf(capitan);
      check.ok(paginas.length === 2, `el capitán de ${dim.slug} debe tener dos páginas`);
      const abierta = paginas[1];
      check.ok(!!abierta.condition?.getIvar("@switch1_valid")
        && Number(abierta.condition.getIvar("@switch1_id")) === DUELO,
        `el capitán de ${dim.slug} no exige el duelo de Arceus (${DUELO})`);
      check.ok(abierta.list.some((c) => c.code === 201 && Number(c.params[1]) === dim.mapaId),
        `el capitán de ${dim.slug} no transfiere a su dimensión`);
      check.ok(abierta.list.some((c) => c.code === 121 && Number(c.params[0]) === dim.abierta),
        `el capitán de ${dim.slug} no abre su dimensión`);
    }

    // — barco de vuelta siempre disponible y sin condiciones
    const barco = eventsOf(dim.mapaId).find((e) => e.name === `${MARKER} Barco a Puerto Horizonte`);
    check.ok(!!barco, `${dim.slug}: falta el barco de vuelta`);
    if (barco) {
      const pagina = pagesOf(barco)[0];
      check.ok(!pagina.condition || !pagina.condition.getIvar("@switch1_valid"),
        `${dim.slug}: el barco de vuelta no puede estar condicionado`);
      check.ok(pagina.list.some((c) => c.code === 201 && Number(c.params[1]) === PUERTO),
        `${dim.slug}: el barco de vuelta no lleva a Puerto Horizonte`);
    }

    // — gimnasio con líder y medalla
    const lider = eventsOf(dim.gimnasioId).find((e) => e.name === `${MARKER} Líder — ${dim.lider.mostrado}`);
    check.ok(!!lider, `${dim.slug}: falta el líder del gimnasio`);
    if (lider) {
      const primera = pagesOf(lider)[0];
      const llama = primera.list.some((c) => (c.code === 355 || c.code === 111)
        && [c.params[0], c.params[1]].some((p) => String(p ?? "").includes(`pbTrainerBattle(:${dim.lider.tipo}`)));
      check.ok(llama, `${dim.slug}: el líder no invoca su combate`);
      check.ok(primera.list.some((c) => (c.code === 355 || c.code === 655 || c.code === 111)
        && [c.params[0], c.params[1]].some((p) => String(p ?? "").includes(`pbReceiveItem(:${dim.medalla}`))),
        `${dim.slug}: el líder no entrega la medalla ${dim.medalla}`);
    }

    // — distritos señalizados y entrenadores
    const balizas = eventsOf(dim.mapaId).filter((e) => e.name.startsWith(`${MARKER} Baliza `));
    check.ok(balizas.length === dim.distritos.length,
      `${dim.slug}: se esperaban ${dim.distritos.length} balizas y hay ${balizas.length}`);
    for (const baliza of balizas) {
      const lineas = pagesOf(baliza)[0].list.map((c) => String(c.params?.[0] ?? "")).join(" ");
      check.ok(/Ash/.test(lineas) && /huésped/.test(lineas), `${dim.slug}: una baliza no explica el rol visitante de Ash`);
    }

    const tipoBase = trainerType(dim);
    const peleas = eventsOf(dim.mapaId).filter((e) => e.name.startsWith(`${MARKER} Entrenador —`));
    check.ok(peleas.length === dim.entrenadores.length,
      `${dim.slug}: se esperaban ${dim.entrenadores.length} entrenadores y hay ${peleas.length}`);
    for (const p of peleas) {
      const lista = pagesOf(p)[0].list;
      check.ok(lista.some((c) => (c.code === 355 || c.code === 655 || c.code === 111)
        && [c.params[0], c.params[1]].some((p) => String(p ?? "").includes(`pbTrainerBattle(:${tipoBase}`))),
        `${dim.slug}: ${p.name} no pelea con el tipo ${tipoBase}`);
    }

    // — cronista
    check.ok(eventsOf(dim.mapaId).some((e) => e.name === `${MARKER} Cronista — ${dim.slug}`),
      `${dim.slug}: falta el cronista`);
  }

  check.done();
}

/* ──────────────────────────────── main ──────────────────────────────────── */

if (VERIFY_ONLY) {
  verify();
} else {
  const resultado = instalar();
  console.log(`✔ Dimensiones de barco instaladas: ${PLAN.dimensiones.length}`);
  for (const { dim, ancho, alto, pasillos, ventanas } of resultado.mapas) {
    console.log(`  · ${dim.slug}: Map${dim.mapaId} ${ancho}×${alto} · ${ventanas.length} distritos · ${pasillos} pasillos de unión`);
    for (const v of ventanas) {
      console.log(`      - ${v.label} ← mapa ${v.sourceId} (ventana ${v.ox},${v.oy} · ${v.tiles} tiles · ${(v.ratio * 100).toFixed(0)}% andable)`);
    }
    console.log(`      gimnasio Map${dim.gimnasioId} · líder ${dim.lider.mostrado} · ${dim.medalla}`);
  }
  const nuevos = (lista) => lista.filter((x) => x.added).length;
  console.log(`  · tipos nuevos: ${nuevos(resultado.datos.tipos)} de ${resultado.datos.tipos.length}`);
  console.log(`  · entrenadores nuevos: ${nuevos(resultado.datos.entrenadores)} de ${resultado.datos.entrenadores.length}`);
  console.log(`  · medallas nuevas: ${nuevos(resultado.datos.medallas)} de ${resultado.datos.medallas.length}`);
  console.log(`  · capitanes en Puerto Horizonte: ${resultado.capitanes.length}`);
  verify();
}#!/usr/bin/env node
/**
 * apply_diplomas_planta.mjs — criterio 6:
 *  · nuevo mapa "Casa de Ash — Salón de Diplomas" (ID nuevo 2288) construido
 *    con los tiles de la casa (Map003, tileset 3);
 *  · puerta nueva en la planta alta de Map003 hacia el salón;
 *  · siete marcos-diploma con estado vacío/conseguido según el hito:
 *      La Ruta de Dios (switch 876), Liga Oscura (switch 948),
 *      Atlas (variable 319 >= 8), Glazed (990), Light Platinum (991),
 *      Liquid Crystal (992), TFOH (993);
 *  · gráficos diploma_*.png propios (generados por canvas, IDs nuevos).
 *
 * Uso: node tools/apply_diplomas_planta.mjs [--verify]
 */
import fs from "node:fs";
import path from "node:path";
import { createCanvas } from "@napi-rs/canvas";
import {
  S, cmd, condition, endEvent, event, freeCells, graphic, grid, iv, page,
  readData, readMapRaw, texts, txt, upsert, writeData, writeMapRaw, walkableAt,
} from "./lib/dlc_helpers.mjs";
import { RObject, DATA, GAME, ROOT, mapFile } from "./lib/dlc_helpers.mjs";
import { TileCanvas, buildMapObject, passabilityOf, reachableCells } from "./lib/map_painter.mjs";
import { tableGet } from "../web/js/rmxp.js";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(new URL("../content/diplomas_planta.json", import.meta.url), "utf8"));
const DIR = "diplomas_planta";
const M = PLAN.mapaId;
const DIRIG = path.join(GAME, "Graphics", "Characters");

/* ─────────────────────────── gráficos de diploma ────────────────────────── */

function envolver(ctx, texto, x, y, ancho, alto, fuente, color) {
  ctx.font = fuente;
  ctx.fillStyle = color;
  ctx.textAlign = "center";
  const palabras = texto.split(" ");
  const lineas = [];
  let linea = "";
  for (const p of palabras) {
    const prueba = linea ? `${linea} ${p}` : p;
    if (ctx.measureText(prueba).width > ancho && linea) { lineas.push(linea); linea = p; }
    else linea = prueba;
  }
  if (linea) lineas.push(linea);
  let cy = y;
  for (const l of lineas.slice(0, 3)) {
    ctx.fillText(l, x, cy);
    cy += alto;
  }
}

function dibujarCelda(ctx, tipo, nombre) {
  if (tipo === "puerta") {
    ctx.fillStyle = "#2b1b12"; ctx.fillRect(0, 0, 64, 96);
    ctx.fillStyle = "#7a4b28"; ctx.fillRect(6, 4, 52, 90);
    ctx.fillStyle = "#5d371c"; ctx.fillRect(12, 10, 40, 84);
    ctx.fillStyle = "#e8c874"; ctx.beginPath(); ctx.arc(46, 52, 4, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "#8a5a2e"; ctx.fillRect(12, 10, 40, 8);
    return;
  }
  if (tipo === "vacio") {
    ctx.fillStyle = "#241d18"; ctx.fillRect(0, 0, 64, 96);
    ctx.fillStyle = "#6b5637"; ctx.fillRect(4, 4, 56, 88);
    ctx.fillStyle = "#2e251c"; ctx.fillRect(10, 10, 44, 76);
    envolver(ctx, "¿?", 32, 50, 40, 16, "bold 22px sans-serif", "#8d7a5c");
    return;
  }
  // diploma con nombre
  ctx.fillStyle = "#f7ecd5"; ctx.fillRect(0, 0, 64, 96);
  ctx.strokeStyle = "#b98a2f"; ctx.lineWidth = 3; ctx.strokeRect(3, 3, 58, 90);
  ctx.strokeStyle = "#e8c874"; ctx.lineWidth = 1; ctx.strokeRect(8, 8, 48, 80);
  ctx.fillStyle = "#b98a2f"; ctx.fillRect(14, 16, 36, 2);
  envolver(ctx, "DIPLOMA", 32, 32, 48, 10, "bold 10px sans-serif", "#7a5a1e");
  envolver(ctx, nombre, 32, 48, 48, 11, "bold 11px sans-serif", "#3b2c17");
  // sello
  ctx.fillStyle = "#a3232d"; ctx.beginPath(); ctx.arc(32, 76, 7, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#e8c874"; ctx.beginPath(); ctx.arc(32, 76, 3, 0, Math.PI * 2); ctx.fill();
}

function hoja(tipo, nombre) {
  const cel = createCanvas(64, 96);
  dibujarCelda(cel.getContext("2d"), tipo, nombre);
  const sheet = createCanvas(256, 384);
  const sc = sheet.getContext("2d");
  for (let row = 0; row < 4; row++) for (let col = 0; col < 4; col++) {
    sc.drawImage(cel, col * 64, row * 96);
  }
  return sheet;
}

function instalarGraficos() {
  fs.mkdirSync(DIRIG, { recursive: true });
  const hechos = [];
  const write = (nombre, tipo, texto) => {
    const dest = path.join(DIRIG, `${nombre}.png`);
    fs.writeFileSync(dest, hoja(tipo, texto).toBuffer("image/png"));
    hechos.push(nombre);
  };
  write("event_puerta_salon", "puerta", null);
  write("diploma_vacio", "vacio", null);
  for (const d of PLAN.diplomas) write(`diploma_${d.clave}`, "diploma", d.nombre);
  return hechos;
}

/* ─────────────────────────── mapa salón ─────────────────────────────────── */

function instalarMapa() {
  const gOrigen = grid(PLAN.mapaOrigen);
  const tabla = gOrigen.parsed.table;
  let suelo = null, muro = null;
  for (let y = 0; y < gOrigen.height && (!suelo || !muro); y++) {
    for (let x = 0; x < gOrigen.width; x++) {
      const st = [0, 1, 2].map((z) => tableGet(tabla, x, y, z));
      if (!st.some((v) => v)) continue;
      if (!suelo && walkableAt(gOrigen, x, y)) suelo = st;
      else if (!muro && !walkableAt(gOrigen, x, y)) muro = st;
      if (suelo && muro) break;
    }
  }
  if (!suelo || !muro) throw new Error("no se encontraron muestras de suelo/muro en Map003");

  const [W, H] = PLAN.tamano;
  const canvas = new TileCanvas(W, H, PLAN.tilesetOrigen);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const borde = x === 0 || x === W - 1 || y === 0 || y === 1 || y === H - 1;
      const st = borde ? muro : suelo;
      st.forEach((v, z) => { if (v) canvas.set(x, y, z, v); });
    }
  }

  // verificación de tránsito antes de escribir
  const pass = passabilityOf(canvas, PLAN.tilesetOrigen);
  const [ex, ey] = PLAN.entrada;
  if (!pass.canMove(ex, ey, 8)) {
    // canMove(dir) comprueba si SE PUEDE ENTRAR a la celda; usamos passable-like:
  }
  const alcanzables = reachableCells(pass, [ex, ey]);
  const interactuables = PLAN.columnasDiplomas.map((x) => `${x},${PLAN.filaDiplomas + 1}`);
  const inalcanzables = interactuables.filter((c) => !alcanzables.has(c));
  if (inalcanzables.length) {
    throw new Error(`celdas de diploma inalcanzables desde la entrada: ${inalcanzables.join(" ")}`);
  }

  const mapa = buildMapObject(canvas, { bgm: "" });
  writeMapRaw(M, mapa);

  // MapInfos: entrada nueva bajo la casa de Ash
  const infos = readData("MapInfos.rxdata");
  const maxOrder = Math.max(0, ...infos.pairs.map(([, m]) => {
    const o = iv(m, "@order");
    return Number(o?.value ?? o ?? 0);
  }));
  const info = new RObject("RPG::MapInfo", [
    ["@name", S(PLAN.titulo)], ["@parent_id", PLAN.mapaOrigen],
    ["@order", maxOrder + 1], ["@expanded", false], ["@scroll_x", 0], ["@scroll_y", 0],
  ]);
  infos.pairs = [
    ...infos.pairs.filter(([id]) => Number(id?.value ?? id) !== M),
    [M, info],
  ];
  writeData("MapInfos.rxdata", infos);

  // metadata: clon de la casa
  const meta = readData("map_metadata.dat");
  const origen = meta.pairs.find(([id]) => Number(id?.value ?? id) === PLAN.mapaOrigen)?.[1];
  if (origen) {
    const clon = new RObject(origen.className, origen.ivars.map(([n, v]) => [n, v]));
    clon.setIvar("@id", M);
    meta.pairs = [
      ...meta.pairs.filter(([id]) => Number(id?.value ?? id) !== M),
      [M, clon],
    ];
    writeData("map_metadata.dat", meta);
  }
  return { suelo, muro };
}

/* ─────────────────────────── eventos ────────────────────────────────────── */

function condDe(d) {
  if (d.condicion.switch) return condition({ sw: d.condicion.switch });
  const [id, valor] = d.condicion.variable;
  return condition({ variable: [id, valor] });
}

function eventoDiploma(d, x, y) {
  return event(0, `${PLAN.prefijo} ${d.nombre}`, x, y, [
    page({
      gfx: graphic("diploma_vacio", 2, 1, {}),
      dirFix: true,
      list: [...texts(d.vacio), endEvent()],
    }),
    page({
      cond: condDe(d),
      gfx: graphic(`diploma_${d.clave}`, 2, 1, {}),
      dirFix: true,
      list: [...texts(d.ganado), endEvent()],
    }),
  ]);
}

function eventoSalida(casa) {
  const [x, y] = PLAN.salida;
  return event(0, `${PLAN.prefijo} salida`, x, y, [
    page({
      gfx: graphic("event_puerta_salon", 2, 1, {}),
      dirFix: true,
      list: [
        ...texts(["\\sp[Puerta del Salón]La puerta devuelve a la planta de Ash."]),
        cmd(201, [0, PLAN.mapaOrigen, casa[0], casa[1], 8, 1]),
        endEvent(),
      ],
    }),
  ]);
}

function eventoPuerta(celda) {
  return event(0, `${PLAN.prefijo} puerta del salón`, celda[0], celda[1], [
    page({
      gfx: graphic("event_puerta_salon", 2, 1, {}),
      dirFix: true,
      list: [
        ...texts([
          "\\sp[Puerta del Salón]Una puerta nueva en la planta alta de la casa de Ash.",
          "\\sp[Puerta del Salón]Detrás: el Salón de Diplomas.",
        ]),
        cmd(201, [0, M, PLAN.entrada[0], PLAN.entrada[1], 2, 1]),
        endEvent(),
      ],
    }),
  ]);
}

function instalarEventos(puertaCelda) {
  // puerta en la planta alta de la casa
  const libres = freeCells(PLAN.puertaSegundaPlanta.mapa);
  const [px, py] = PLAN.puertaSegundaPlanta.preferida;
  const orden = [...libres].sort((a, b) =>
    (Math.abs(a[0] - px) + Math.abs(a[1] - py)) - (Math.abs(b[0] - px) + Math.abs(b[1] - py)));
  const celda = puertaCelda ?? orden[0];
  upsert(PLAN.puertaSegundaPlanta.mapa, [PLAN.prefijo], () => [eventoPuerta(celda)], DIR);

  // salón: diplomas + salida
  const eventos = [];
  PLAN.diplomas.forEach((d, i) => {
    eventos.push(eventoDiploma(d, PLAN.columnasDiplomas[i], PLAN.filaDiplomas));
  });
  eventos.push(eventoSalida(celda));
  const added = upsert(M, [PLAN.prefijo], (nextId) => {
    eventos.forEach((e, i) => e.setIvar("@id", nextId + i));
    return eventos;
  }, DIR);
  return { celda, added };
}

/* ─────────────────────────── System: switch 948 ─────────────────────────── */

function instalarNombreSwitch() {
  const system = readData("System.rxdata");
  const switches = iv(system, "switches") || [];
  switches[948] = S("POKEMOD LIGA OSCURA COMPLETA");
  system.setIvar("switches", switches);
  writeData("System.rxdata", system);
}

/* ─────────────────────────── verificación ───────────────────────────────── */

function verificar() {
  const fallos = [];
  // mapa
  const rutaMapa = path.join(DATA, mapFile(M));
  if (!fs.existsSync(rutaMapa)) fallos.push(`falta ${mapFile(M)}`);
  else {
    const mapa = readMapRaw(M);
    const nombres = (iv(mapa, "@events")?.pairs ?? []).map(([, e]) => txt(iv(e, "@name")));
    for (const d of PLAN.diplomas) {
      if (!nombres.some((n) => n === `${PLAN.prefijo} ${d.nombre}`)) fallos.push(`falta diploma ${d.nombre} en el salón`);
    }
    if (!nombres.some((n) => n === `${PLAN.prefijo} salida`)) fallos.push("falta la salida del salón");
  }
  // puerta en Map003
  const casa = readMapRaw(PLAN.puertaSegundaPlanta.mapa);
  const nombresCasa = (iv(casa, "@events")?.pairs ?? []).map(([, e]) => txt(iv(e, "@name")));
  if (!nombresCasa.some((n) => n.startsWith(PLAN.prefijo))) fallos.push("falta la puerta del salón en la planta alta");
  // gráficos
  for (const nombre of ["event_puerta_salon", "diploma_vacio", ...PLAN.diplomas.map((d) => `diploma_${d.clave}`)]) {
    if (!fs.existsSync(path.join(DIRIG, `${nombre}.png`))) fallos.push(`falta ${nombre}.png`);
  }
  // switch 948: nombre + marca en la arena de la Liga Oscura
  const system = readData("System.rxdata");
  const switches = iv(system, "switches") || [];
  if (!txt(switches[948]).includes("LIGA OSCURA")) fallos.push("switch 948 sin nombre");
  const expansion = JSON.parse(fs.readFileSync(new URL("../content/expansion_multiversal.json", import.meta.url), "utf8"));
  const ultimo = expansion.darkLeague.battles[expansion.darkLeague.battles.length - 1];
  const arena = readMapRaw(expansion.darkLeague.maps[1].mapId ?? 2193);
  const eventos = (iv(arena, "@events")?.pairs ?? []).map(([, e]) => ({
    nombre: txt(iv(e, "@name")),
    paginas: (iv(e, "@pages") ?? []).map((p) => (iv(p, "@list") ?? []).map((c) => ({
      code: Number(iv(c, "@code")?.value ?? iv(c, "@code") ?? -1),
      params: (iv(c, "@parameters") ?? []).map((v) => Number(v?.value ?? v)),
    }))),
  }));
  const final = eventos.find((e) => e.nombre.endsWith(ultimo.name));
  if (!final) fallos.push(`falta el jefe final «${ultimo.name}» en la arena de la Liga Oscura`);
  else {
    const marca = final.paginas.some((lista) => lista.some((c) => c.code === 121 && c.params[0] === 948));
    if (!marca) fallos.push("el jefe final de la Liga Oscura no marca el switch 948 al ganar");
  }
  return fallos;
}

/* ─────────────────────────── main ───────────────────────────────────────── */

if (!VERIFY_ONLY) {
  const hechos = instalarGraficos();
  console.log(`· Gráficos: ${hechos.map((n) => `${n}.png`).join(", ")}`);
  instalarNombreSwitch();
  console.log("· System.rxdata: switch 948 «POKEMOD LIGA OSCURA COMPLETA».");
  const { suelo, muro } = instalarMapa();
  console.log(`· ${mapFile(M)} «${PLAN.titulo}» ${PLAN.tamano.join("x")} — suelo/muro muestreados de Map${String(PLAN.mapaOrigen).padStart(3, "0")}.`);
  const { celda, added } = instalarEventos();
  console.log(`· Puerta en Map${String(PLAN.puertaSegundaPlanta.mapa).padStart(3, "0")} (${celda.join(",")}) y ${added.length} eventos en el salón.`);
}

const fallos = verificar();
if (fallos.length) {
  console.error("FALLOS:\n" + fallos.map((f) => "  · " + f).join("\n"));
  process.exit(1);
}
console.log("OK: Salón de Diplomas instalado; siete marcos con hitos verificados.");#!/usr/bin/env node
/**
 * apply_dlc_ambience.mjs
 *
 * Los diecisiete mapas nuevos salieron del compositor sin banda sonora: eran
 * mundos mudos. Esta herramienta les pone música real del juego (sólo archivos
 * que ya existen en Audio/BGM, nunca uno inventado) y añade tablas de
 * encuentros temáticas a los mapas que tienen terreno compatible.
 *
 * La música no es decorativa: cada dimensión suena a lo que es. Glazed lleva
 * nieve, Light Platinum lleva costa, la base del Sindicato lleva su propio tema
 * y los ocho gimnasios de Atlas suenan cada uno distinto.
 *
 * Los encuentros se escriben en `content/wild_zones.json`, que es el catálogo
 * que consume `tools/apply_wild_zones.mjs`; aquí sólo se sincronizan.
 *
 * Uso:
 *   node tools/apply_dlc_ambience.mjs
 *   node tools/apply_dlc_ambience.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { DATA, GAME, ROOT, RString, iv, makeChecker, mapFile, readMapRaw, writeMapRaw } from "./lib/dlc_helpers.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "dlc_ambience.json"), "utf8"));
const WILD_PATH = path.join(ROOT, "content", "wild_zones.json");
const BGM_DIR = path.join(GAME, "Audio", "BGM");
const BACKUP = "dlc_ambience";

function backupFile(file) {
  const dir = path.join(GAME, "PokeModBackups", BACKUP);
  fs.mkdirSync(dir, { recursive: true });
  const source = path.join(DATA, file);
  if (fs.existsSync(source)) fs.copyFileSync(source, path.join(dir, file));
}

/* ─────────────────────────────── la música ──────────────────────────────── */

function instalarMusica() {
  const aplicadas = [];
  const fallidas = [];
  for (const fila of PLAN.musica) {
    const archivo = mapFile(fila.mapId);
    if (!fs.existsSync(path.join(DATA, archivo))) { fallidas.push(`${fila.mapId}: no existe el mapa`); continue; }
    if (!fs.existsSync(path.join(BGM_DIR, fila.bgm))) { fallidas.push(`${fila.mapId}: no existe ${fila.bgm}`); continue; }
    backupFile(archivo);
    const map = readMapRaw(fila.mapId);
    const bgm = iv(map, "@bgm");
    if (!bgm) { fallidas.push(`${fila.mapId}: el mapa no tiene @bgm`); continue; }
    bgm.setIvar("@name", RString.fromText(fila.bgm));
    bgm.setIvar("@volume", 100);
    bgm.setIvar("@pitch", 100);
    map.setIvar("@autoplay_bgm", true);
    writeMapRaw(fila.mapId, map);
    aplicadas.push(fila);
  }
  return { aplicadas, fallidas };
}

/* ──────────────────────────── los encuentros ───────────────────────────── */

function sincronizarZonas() {
  const catalogo = JSON.parse(fs.readFileSync(WILD_PATH, "utf8"));
  const porMapa = new Map(catalogo.zones.map((z) => [z.mapId, z]));
  let anadidas = 0;
  for (const zona of PLAN.zonas) {
    if (porMapa.has(zona.mapId)) Object.assign(porMapa.get(zona.mapId), zona);
    else { catalogo.zones.push(zona); anadidas += 1; }
  }
  fs.writeFileSync(WILD_PATH, `${JSON.stringify(catalogo, null, 2)}\n`);
  return { anadidas, total: catalogo.zones.length };
}

function instalar() {
  const musica = instalarMusica();
  const zonas = sincronizarZonas();
  return { musica, zonas };
}

/* ──────────────────────────── verificación ──────────────────────────────── */

function verify() {
  const check = makeChecker("Ambientación del DLC");

  for (const fila of PLAN.musica) {
    const archivo = path.join(DATA, mapFile(fila.mapId));
    check.ok(fs.existsSync(archivo), `no existe Map${fila.mapId}`);
    if (!fs.existsSync(archivo)) continue;
    check.ok(fs.existsSync(path.join(BGM_DIR, fila.bgm)),
      `la música ${fila.bgm} del Map${fila.mapId} no existe en Audio/BGM`);
    const map = readMapRaw(fila.mapId);
    const nombre = iv(iv(map, "@bgm"), "@name");
    const texto = typeof nombre === "string" ? nombre : nombre?.text ?? "";
    check.ok(texto === fila.bgm, `Map${fila.mapId} no suena ${fila.bgm} (tiene «${texto}»)`);
    check.ok(iv(map, "@autoplay_bgm") === true, `Map${fila.mapId} no reproduce la música al entrar`);
  }

  const catalogo = JSON.parse(fs.readFileSync(WILD_PATH, "utf8"));
  for (const zona of PLAN.zonas) {
    const guardada = catalogo.zones.find((z) => z.mapId === zona.mapId);
    check.ok(!!guardada, `falta la zona salvaje del Map${zona.mapId} en wild_zones.json`);
    if (!guardada) continue;
    for (const tipo of Object.keys(zona.types)) {
      check.ok((guardada.types[tipo] ?? []).length === zona.types[tipo].length,
        `Map${zona.mapId}: la tabla ${tipo} no coincide`);
    }
  }

  check.done();
}

/* ──────────────────────────────── main ──────────────────────────────────── */

if (VERIFY_ONLY) {
  verify();
} else {
  const resultado = instalar();
  console.log(`✔ Ambientación del DLC instalada`);
  console.log(`  · música asignada: ${resultado.musica.aplicadas.length} de ${PLAN.musica.length} mapas`);
  if (resultado.musica.fallidas.length) {
    for (const f of resultado.musica.fallidas) console.error(`   ✘ ${f}`);
  }
  console.log(`  · zonas salvajes: ${resultado.zonas.anadidas} nuevas (${resultado.zonas.total} en el catálogo)`);
  console.log("  · ahora hay que aplicar el catálogo: node tools/apply_wild_zones.mjs");
  verify();
}#!/usr/bin/env node
/**
 * apply_dlc_regiones.mjs
 *
 * Convierte Glazed y Light Platinum en regiones y la base del Team Rocket en
 * un edificio por el que se infiltra uno. Antes de esto, las dos invitadas
 * eran dos habitaciones con un gimnasio —un puerto, no una región— y la base
 * del Sindicato era un descampado con uniformes.
 *
 * Ahora son diecinueve mapas conectados: rutas, ciudades, una cueva glaciar,
 * centros, tiendas, un laboratorio, una zona safari y siete salas
 * industriales. Cada uno se dibuja con `region_builder`, que aprende los
 * bordes de los materiales de mapas reales del juego, y cada uno pasa el
 * filtro de los tres departamentos antes de darse por bueno:
 *
 *   · mapeo      → planta trazada y reparada (pasillos de dos, sin islas)
 *   · QA técnico → inundación desde la llegada; softlock con coordenadas
 *   · dirección de arte → monotonía, costuras y prioridad de capas
 *
 * La profundidad se resuelve con dos planos que se mueven a distinta
 * velocidad: la niebla (plano cercano, generada por código, se desplaza con
 * `@fog_sx`/`@fog_sy`) y el clima (partículas, desde `map_metadata`). RPG
 * Maker XP sólo tiene un plano de niebla por mapa, y en Essentials lo lee el
 * tileset, así que cada ambiente se estrena con un tileset clonado: nunca se
 * tocan los 792 mapas que comparten el tileset 1.
 *
 * Nada de esto edita contenido existente: los mapas, los tilesets y las
 * imágenes son nuevos, y de los mapas existentes sólo se tocan los eventos
 * cuyo nombre empieza por el marcador de este instalador.
 *
 * Uso:
 *   node --max-old-space-size=6144 tools/apply_dlc_regiones.mjs
 *   node --max-old-space-size=6144 tools/apply_dlc_regiones.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import {
  DATA, GAME, ROOT, S, cmd, condition, endEvent, event, eventsOf, graphic,
  installMapInfos, iv, makeChecker, mapFile, marshalDump, marshalLoad,
  page, pagesOf, spread, texts, tint, transfer, upsert, wait,
} from "./lib/dlc_helpers.mjs";
import { celdasLibres } from "./lib/dimension_builder.mjs";
import {
  auditar, clonarTileset, construir, publicar, reparar, trazar,
} from "./lib/region_builder.mjs";
import { CAPAS, escribirPNG } from "./lib/png.mjs";
import { RSymbol } from "../web/js/marshal.js";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "dlc_regiones.json"), "utf8"));
const BACKUP = "dlc_regiones";
const MARK = PLAN.marcador;
const FOG_DIR = path.join(GAME, "Graphics", "Fogs");

/** Viaje con fundido: fundido a negro, transferencia y fundido de vuelta. */
const viaje = (mapId, x, y, indent = 0) => [
  tint(-255, -255, -255, 0, 6, indent),
  wait(8, indent),
  transfer(mapId, x, y, 2, indent),
  tint(0, 0, 0, 0, 6, indent),
  endEvent(indent),
];

/* ─────────────────────────────── la niebla ──────────────────────────────── */

function instalarNieblas() {
  const escritas = [];
  for (const [nombre, spec] of Object.entries(PLAN.nieblas)) {
    const generar = CAPAS[spec.capa];
    if (!generar) throw new Error(`capa de niebla desconocida: ${spec.capa}`);
    const imagen = generar(640, 480, { semilla: spec.semilla ?? 1, ...spec.opciones });
    const ruta = path.join(FOG_DIR, `${nombre}.png`);
    escribirPNG(ruta, imagen.w, imagen.h, imagen.rgba);
    escritas.push({ nombre, ruta: path.relative(ROOT, ruta) });
  }
  return escritas;
}

/* ──────────────────────────── mapas y fichas ───────────────────────────── */

function instalarTilesets() {
  const nieblaDe = (clave) => {
    const spec = PLAN.nieblas[clave];
    return { nombre: clave, opacidad: spec.opacidad, zoom: spec.zoom, sx: spec.sx, sy: spec.sy, mezcla: 0, hue: 0 };
  };
  return PLAN.tilesets.map((t) => ({
    ...t,
    resultado: clonarTileset(t.origen, t.id, {
      niebla: t.niebla ? nieblaDe(t.niebla) : null,
      dirName: BACKUP,
    }),
  }));
}

function construirMapas() {
  const construidos = new Map();
  for (const espec of PLAN.mapas) {
    const { canvas, traza, materiales } = construir(espec);
    publicar(espec.mapId, espec.titulo, canvas, { bgm: espec.bgm ?? "", encounterStep: 25 });
    construidos.set(espec.mapId, { espec, traza, materiales, canvas });
  }
  return construidos;
}

/**
 * Metadatos por mapa, clonando los del donante para que el fondo de combate y
 * las músicas de batalla sean las que ya corresponden a ese tipo de escenario.
 */
function instalarMetadatos(construidos) {
  const archivo = path.join(DATA, "map_metadata.dat");
  const meta = marshalLoad(fs.readFileSync(archivo));
  const dir = path.join(GAME, "PokeModBackups", BACKUP);
  fs.mkdirSync(dir, { recursive: true });
  const respaldo = path.join(dir, "map_metadata.dat");
  if (!fs.existsSync(respaldo)) fs.copyFileSync(archivo, respaldo);

  for (const { espec } of construidos.values()) {
    const donante = meta.pairs.find(([k]) => Number(k) === Number(espec.donante));
    let objeto;
    if (donante) {
      objeto = new (donante[1].constructor)(donante[1].className, donante[1].ivars.map(([k, v]) => [k, v]));
    } else {
      objeto = new (Object.getPrototypeOf(meta.pairs[0][1]).constructor)("GameData::MapMetadata", []);
    }
    objeto.setIvar("@id", Number(espec.mapId));
    objeto.setIvar("@outdoor_map", !!espec.exterior);
    objeto.setIvar("@announce_location", !!espec.anunciar);
    objeto.setIvar("@can_bicycle", !!espec.exterior);
    objeto.setIvar("@dark_map", !!espec.oscuro);
    objeto.setIvar("@safari_map", !!espec.safari);
    objeto.setIvar("@snap_edges", true);
    if (espec.clima && espec.clima !== "None") objeto.setIvar("@weather", new RSymbol(espec.clima));
    else objeto.setIvar("@weather", null);

    const entrada = meta.pairs.find(([k]) => Number(k) === Number(espec.mapId));
    if (entrada) entrada[1] = objeto;
    else meta.pairs.push([Number(espec.mapId), objeto]);
  }
  fs.writeFileSync(archivo, Buffer.from(marshalDump(meta)));
}

function instalarFichas() {
  installMapInfos(
    PLAN.mapas.map((m) => ({ mapId: m.mapId, title: m.titulo, parentId: m.padre ?? 0, order: 910 })),
    BACKUP,
  );
}

/* ──────────────────────────────── eventos ──────────────────────────────── */

/**
 * Celda de llegada de un mapa. Si se acaba de construir, se reutiliza; si
 * sólo se está verificando, se recalcula trazando la planta otra vez, que es
 * determinista y no necesita pintar nada.
 */
function llegadaDe(mapId, construidos) {
  const propio = construidos.get(mapId);
  if (propio) return propio.traza.llegada;
  const espec = PLAN.mapas.find((m) => m.mapId === mapId);
  if (espec) {
    const semilla = espec.semilla ?? 1;
    const traza = reparar(
      trazar(espec.arquetipo, espec.ancho ?? (espec.interior ? 20 : 37), espec.alto ?? (espec.interior ? 15 : 25), { ...espec, semilla }),
      semilla,
    );
    return traza.llegada;
  }
  return [2, 2];
}

function instalarRutas(construidos) {
  const porMapa = new Map();
  const anadir = (mapId, fabrica) => {
    if (!porMapa.has(mapId)) porMapa.set(mapId, []);
    porMapa.get(mapId).push(fabrica);
  };

  for (const ruta of PLAN.rutas) {
    const tituloDestino = tituloDe(ruta.a);
    const destino = tituloDe(ruta.de);
    anadir(ruta.de, (celda, id) => event(id, `${MARK} Puerta — ${ruta.nombre}`, celda[0], celda[1], [
      page({
        trigger: 1,
        list: [...texts(ruta.texto ?? [`${ruta.nombre}.`]), ...viaje(ruta.a, ...llegadaDe(ruta.a, construidos))],
      }),
    ]));
    anadir(ruta.a, (celda, id) => event(id, `${MARK} Salida — ${destino}`, celda[0], celda[1], [
      page({ trigger: 1, list: [...viaje(ruta.de, ...llegadaDe(ruta.de, construidos))] }),
    ]));
    void tituloDestino;
  }

  // Los pobladores se cuelgan del mapa que les toca.
  for (const p of PLAN.pobladores ?? []) {
    anadir(p.mapa, (celda, id) => event(id, `${MARK} ${p.nombre}`, celda[0], celda[1], [
      page({
        gfx: graphic(p.sprite, 2, 1, {}),
        list: [...texts(p.lineas), endEvent()],
      }),
    ]));
  }

  const colocados = [];
  for (const [mapId, fabricas] of porMapa) {
    upsert(mapId, [MARK], () => [], BACKUP);
    const celdas = spread(celdasLibres(mapId), fabricas.length);
    upsert(mapId, [MARK], (nextId) => {
      let id = nextId;
      return fabricas.map((fabrica, i) => fabrica(celdas[i] ?? celdas[0], id++));
    }, BACKUP);
    colocados.push({ mapId, eventos: fabricas.length });
  }
  return colocados;
}

const tituloDe = (mapId) => PLAN.mapas.find((m) => m.mapId === mapId)?.titulo ?? `Map${mapId}`;

/**
 * Sala de Comunicaciones: la alarma roja late. Un PNG no puede latir, así que
 * el pulso lo da un evento en paralelo moviendo la opacidad de la niebla
 * (comando 206). Son diez latidos y se detiene: RMXP no tiene bucle de
 * eventos y un proceso paralelo que no acaba es una receta para el desastre.
 */
function instalarAlarma() {
  const salas = PLAN.mapas.filter((m) => m.alarma);
  for (const sala of salas) {
    const lista = [];
    for (let i = 0; i < 10; i++) {
      lista.push(cmd(206, [88, 8], 0));   // subir la opacidad
      lista.push(wait(14, 0));
      lista.push(cmd(206, [46, 8], 0));   // bajarla
      lista.push(wait(14, 0));
    }
    lista.push(endEvent(0));
    upsert(sala.mapId, [`${MARK} Alarma`], (nextId) => [
      event(nextId, `${MARK} Alarma`, 1, 1, [
        page({ cond: condition(), trigger: 4, list: lista }),
      ]),
    ], BACKUP);
  }
  return salas.map((s) => s.mapId);
}

/* ───────────────────────────── verificación ────────────────────────────── */

function verify(construidos = new Map()) {
  const check = makeChecker("Regiones del DLC");

  // — las capas de niebla existen y son PNG válidos
  for (const nombre of Object.keys(PLAN.nieblas)) {
    const ruta = path.join(FOG_DIR, `${nombre}.png`);
    check.ok(fs.existsSync(ruta), `falta la capa de niebla ${nombre}.png`);
    if (fs.existsSync(ruta)) {
      const bytes = fs.readFileSync(ruta);
      check.ok(bytes.length > 100 && bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])),
        `${nombre}.png no es un PNG válido`);
    }
  }

  // — los tilesets clonados conservan la pasabilidad del original
  const ts = marshalLoad(fs.readFileSync(path.join(DATA, "Tilesets.rxdata")));
  for (const t of PLAN.tilesets) {
    const clon = ts[t.id];
    check.ok(!!clon, `falta el tileset ${t.id}`);
    if (!clon) continue;
    const original = ts[t.origen];
    check.ok(Buffer.compare(
      Buffer.from(clon.getIvar("@terrain_tags").bytes),
      Buffer.from(original.getIvar("@terrain_tags").bytes),
    ) === 0, `el tileset ${t.id} no conserva la pasabilidad del ${t.origen}`);
    if (t.niebla) {
      const esperado = String(t.niebla);
      const nombre = clon.getIvar("@fog_name");
      check.ok(String(nombre?.text ?? nombre ?? "") === esperado,
        `el tileset ${t.id} no lleva la niebla ${esperado}`);
      check.ok(Number(clon.getIvar("@fog_opacity")) === PLAN.nieblas[t.niebla].opacidad,
        `el tileset ${t.id} no tiene la opacidad de niebla esperada`);
    }
  }

  // — los mapas existen, suenan y pasan el filtro de los tres departamentos
  for (const espec of PLAN.mapas) {
    check.ok(fs.existsSync(path.join(DATA, mapFile(espec.mapId))), `falta Map${espec.mapId}`);
    const bruto = marshalLoad(fs.readFileSync(path.join(DATA, mapFile(espec.mapId))));
    const nombre = iv(iv(bruto, "@bgm"), "@name");
    const texto = typeof nombre === "string" ? nombre : nombre?.text ?? "";
    check.ok(texto === (espec.bgm ?? ""), `Map${espec.mapId} no suena ${espec.bgm} (tiene «${texto}»)`);
    check.ok(fs.existsSync(path.join(GAME, "Audio", "BGM", espec.bgm)),
      `la música ${espec.bgm} del Map${espec.mapId} no existe en Audio/BGM`);
    check.ok(Number(iv(bruto, "@tileset_id")) === espec.tileset,
      `Map${espec.mapId} no usa el tileset ${espec.tileset}`);

    auditar(check, espec.mapId, {
      titulo: espec.titulo,
      llegada: llegadaDe(espec.mapId, construidos),
      eventosInstalados: true,
      minimoTransitable: espec.arquetipo === "cueva" ? 0.28 : 0.25,
    });
  }

  // — los dos sentidos de cada ruta, y que ambos transfieran de verdad
  for (const ruta of PLAN.rutas) {
    const ida = eventsOf(ruta.de).find((e) => e.name === `${MARK} Puerta — ${ruta.nombre}`);
    check.ok(!!ida, `falta la puerta «${ruta.nombre}» en el Map${ruta.de}`);
    if (ida) {
      check.ok(pagesOf(ida)[0].list.some((c) => c.code === 201 && Number(c.params[1]) === ruta.a),
        `la puerta «${ruta.nombre}» no lleva al Map${ruta.a}`);
    }
    const vuelta = eventsOf(ruta.a).find((e) => e.name === `${MARK} Salida — ${tituloDe(ruta.de)}`);
    check.ok(!!vuelta, `falta la salida de vuelta al Map${ruta.de} desde el Map${ruta.a}`);
    if (vuelta) {
      check.ok(pagesOf(vuelta)[0].list.some((c) => c.code === 201 && Number(c.params[1]) === ruta.de),
        `la salida del Map${ruta.a} no vuelve al Map${ruta.de}`);
    }
  }

  // — los pobladores
  for (const p of PLAN.pobladores ?? []) {
    check.ok(eventsOf(p.mapa).some((e) => e.name === `${MARK} ${p.nombre}`),
      `falta el poblador «${p.nombre}» en el Map${p.mapa}`);
  }

  // — la alarma
  for (const sala of PLAN.mapas.filter((m) => m.alarma)) {
    const alarma = eventsOf(sala.mapId).find((e) => e.name === `${MARK} Alarma`);
    check.ok(!!alarma, `Map${sala.mapId}: falta la alarma`);
    if (alarma) {
      const lista = pagesOf(alarma)[0].list;
      check.ok(lista.filter((c) => c.code === 206).length >= 10,
        `Map${sala.mapId}: la alarma no late (hacen falta diez cambios de opacidad)`);
    }
  }

  check.done();
}

/* ──────────────────────────────── main ──────────────────────────────────── */

if (VERIFY_ONLY) {
  verify();
} else {
  const nieblas = instalarNieblas();
  const tilesets = instalarTilesets();
  const construidos = construirMapas();
  instalarFichas();
  instalarMetadatos(construidos);
  const rutas = instalarRutas(construidos);
  const alarmas = instalarAlarma();

  console.log(`✔ Regiones del DLC instaladas`);
  console.log(`  · capas de profundidad: ${nieblas.length} (${nieblas.map((n) => n.nombre).join(", ")})`);
  console.log(`  · tilesets nuevos: ${tilesets.map((t) => `${t.id}←${t.origen}${t.resultado.creado ? " (nuevo)" : " (actualizado)"}`).join(", ")}`);
  console.log(`  · mapas: ${construidos.size}`);
  for (const { espec, traza, materiales } of construidos.values()) {
    console.log(`      Map${espec.mapId} ${traza.width}×${traza.height} ${espec.arquetipo.padEnd(9)} ts${espec.tileset} ← donante ${espec.donante} · familia [${materiales.fuentes.join(",")}]`);
  }
  console.log(`  · rutas de ida y vuelta: ${PLAN.rutas.length}`);
  console.log(`  · pobladores: ${(PLAN.pobladores ?? []).length} en ${rutas.length} mapas`);
  console.log(`  · salas con alarma: ${alarmas.length}`);
  verify(construidos);
}#!/usr/bin/env node
/**
 * Depura las tarjetas de título incrustadas en cinco mapas del Dimensional
 * Nightmare. No desplaza eventos ni celdas: sustituye el arte superior por
 * variantes gráficas tomadas de las filas inmediatamente inferiores y clona,
 * por celda, pasabilidad/prioridad/terreno de los tiles originales.
 *
 * El inventario completo (todos los mapas compilados, no sólo EP03) y las cinco
 * intervenciones visuales revisadas están en content/dimensional_nightmare_map_polish.json.
 *
 * Uso:
 *   node tools/apply_dn_banner_cleanup.mjs --dry-run
 *   node tools/apply_dn_banner_cleanup.mjs --apply --render
 *   node tools/apply_dn_banner_cleanup.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalDump, marshalLoad } from "../web/js/marshal.js";
import {
  parseMap, parseTileset, tableGet, tableSet, tableToUserDef,
} from "../web/js/rmxp.js";
import { renderMapId } from "./render_map_png.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const GAME_DATA = path.join(GAME, "Data");
const GAME_GRAPHICS = path.join(GAME, "Graphics", "Tilesets");
const QA = path.join(ROOT, "Scripts_corregido", "Dimensional_Nightmare_QA");
const QA_DATA = path.join(QA, "Data");
const QA_GRAPHICS = path.join(QA, "Graphics", "Tilesets");
const BUILT = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const PLAN = path.join(ROOT, "content", "dimensional_nightmare_map_polish.json");
const BACKUP = path.join(GAME, "PokeModBackups", "dn_map_banner_cleanup_originals");
const RENDER_DIR = path.join(ROOT, "docs", "dn_referencia", "detalle");

const TILE = 32;
const COLUMNS = 8;
const FIRST_NORMAL_TILE = 384;
const VERSION = 1;
const APPLY = process.argv.includes("--apply");
const VERIFY = process.argv.includes("--verify");
const RENDER = process.argv.includes("--render");
const REFRESH = process.argv.includes("--refresh-plan");
const DRY = !APPLY && !VERIFY;

const readRx = (directory, file) => marshalLoad(fs.readFileSync(path.join(directory, file)));
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;
const writeAtomic = (file, bytes) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const tmp = `${file}.dn-polish-tmp`;
  fs.writeFileSync(tmp, bytes);
  fs.renameSync(tmp, file);
};
const backupOnce = (source, destination) => {
  if (!fs.existsSync(source)) throw new Error(`Falta archivo de origen: ${source}`);
  if (!fs.existsSync(destination)) {
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.copyFileSync(source, destination);
  }
};
const sha256 = (value) => createHash("sha256").update(value).digest("hex");
const hashJson = (value) => sha256(Buffer.from(JSON.stringify(value), "utf8"));

const plan = JSON.parse(fs.readFileSync(PLAN, "utf8"));
const built = JSON.parse(fs.readFileSync(BUILT, "utf8"));
const byId = new Map((built.maps ?? []).map((entry) => [Number(entry.id), entry]));

function validateInventory() {
  const ids = [...byId.keys()].sort((a, b) => a - b);
  const planned = [...(plan.auditedMaps ?? [])].map((entry) => Number(entry.id)).sort((a, b) => a - b);
  if (ids.length !== plan.auditedMapCount || ids.length !== planned.length ||
      ids.some((id, index) => id !== planned[index])) {
    throw new Error(`El inventario cambió: compilados=${ids.length}, plan=${planned.length}. Revisa ${path.relative(ROOT, PLAN)}.`);
  }
  for (const id of ids) {
    if (!fs.existsSync(path.join(GAME_DATA, mapFile(id)))) {
      throw new Error(`El inventario completo debe seguir disponible: falta ${mapFile(id)}.`);
    }
  }
}

function ensureBackups() {
  for (const [label, dataDir, graphicsDir] of [
    ["juego", GAME_DATA, GAME_GRAPHICS],
    ["qa", QA_DATA, QA_GRAPHICS],
  ]) {
    backupOnce(path.join(dataDir, "Tilesets.rxdata"), path.join(BACKUP, label, "Data", "Tilesets.rxdata"));
    for (const entry of plan.cleanupTargets) {
      backupOnce(path.join(dataDir, mapFile(entry.id)), path.join(BACKUP, label, "Data", mapFile(entry.id)));
      const png = `DN_${entry.id}.png`;
      backupOnce(path.join(graphicsDir, png), path.join(BACKUP, label, "Graphics", "Tilesets", png));
    }
  }
  const readme = path.join(BACKUP, "LEEME.txt");
  if (!fs.existsSync(readme)) {
    fs.mkdirSync(BACKUP, { recursive: true });
    fs.writeFileSync(readme,
      "Originales de los cinco mapas/tile sets anteriores a la depuración de rótulos.\n" +
      "El parche mantiene dimensiones, eventos y flags de pasabilidad/prioridad por celda.\n" +
      "No son partidas guardadas.\n", "utf8");
  }
}

function expandTileTable(source, newX, copiedFlags) {
  if (source.y !== 1 || source.z !== 1) {
    throw new Error(`Tabla de tile no unidimensional (${source.x}×${source.y}×${source.z}).`);
  }
  const data = new Uint16Array(newX);
  data.set(source.data.subarray(0, Math.min(source.data.length, data.length)));
  for (const { newId, originalId } of copiedFlags) {
    data[newId] = tableGet(source, originalId, 0, 0);
  }
  return { dim: source.dim, x: newX, y: 1, z: 1, data };
}

async function prepareInstall(dataDir, graphicsDir, label) {
  const tilesetsRaw = readRx(dataDir, "Tilesets.rxdata");
  const mapWrites = [];
  const pngWrites = [];
  const changedTilesets = new Set();
  let skipped = 0;

  for (const entry of plan.cleanupTargets) {
    const filename = mapFile(entry.id);
    const mapObject = readRx(dataDir, filename);
    if (Number(mapObject.getIvar("dn_banner_cleanup_version") ?? 0) === VERSION) {
      console.log(`  ${label}: Map${entry.id} ya tiene depuración v${VERSION}; sin cambios.`);
      skipped++;
      continue;
    }
    const parsed = parseMap(mapObject);
    if (entry.rows * 2 > parsed.height) {
      throw new Error(`Map${entry.id}: faltan filas de origen para la banda de ${entry.rows} filas.`);
    }
    const tilesetObject = tilesetsRaw[parsed.tilesetId];
    if (!tilesetObject) throw new Error(`Map${entry.id}: no existe tileset #${parsed.tilesetId}.`);
    const tileset = parseTileset(tilesetObject);
    const graphicName = `DN_${entry.id}.png`;
    const graphicFile = path.join(graphicsDir, graphicName);
    const image = await loadImage(graphicFile);
    if (image.width % TILE !== 0 || image.height % TILE !== 0) {
      throw new Error(`${graphicName}: dimensiones no alineadas a tiles de ${TILE}px.`);
    }
    const atlasColumns = image.width / TILE;
    const atlasCapacity = atlasColumns * (image.height / TILE);
    if (atlasColumns !== COLUMNS) throw new Error(`${graphicName}: se esperaban ${COLUMNS} columnas, hay ${atlasColumns}.`);

    const variants = [];
    for (let y = 0; y < entry.rows; y++) {
      for (let x = 0; x < parsed.width; x++) {
        const originalId = tableGet(parsed.table, x, y, 0);
        const sourceId = tableGet(parsed.table, x, y + entry.rows, 0);
        const originalIndex = originalId - FIRST_NORMAL_TILE;
        const sourceIndex = sourceId - FIRST_NORMAL_TILE;
        if (originalIndex < 0 || originalIndex >= atlasCapacity || sourceIndex < 0 || sourceIndex >= atlasCapacity) {
          throw new Error(`Map${entry.id} (${x},${y}): no es un tile normal del atlas (#${originalId} → #${sourceId}).`);
        }
        const newId = FIRST_NORMAL_TILE + atlasCapacity + variants.length;
        variants.push({ x, y, originalId, sourceId, newId, sourceIndex });
      }
    }

    const appendRows = Math.ceil(variants.length / COLUMNS);
    const canvas = createCanvas(image.width, image.height + appendRows * TILE);
    const ctx = canvas.getContext("2d");
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(image, 0, 0);
    for (const [i, variant] of variants.entries()) {
      const sx = (variant.sourceIndex % COLUMNS) * TILE;
      const sy = Math.floor(variant.sourceIndex / COLUMNS) * TILE;
      const dstIndex = atlasCapacity + i;
      const dx = (dstIndex % COLUMNS) * TILE;
      const dy = Math.floor(dstIndex / COLUMNS) * TILE;
      ctx.drawImage(image, sx, sy, TILE, TILE, dx, dy, TILE, TILE);
      tableSet(parsed.table, variant.x, variant.y, 0, variant.newId);
    }

    const oldFlags = [];
    for (const variant of variants) oldFlags.push({ newId: variant.newId, originalId: variant.originalId });
    const newTableLength = FIRST_NORMAL_TILE + atlasCapacity + variants.length;
    tilesetObject.setIvar("passages", tableToUserDef(expandTileTable(tileset.passages, newTableLength, oldFlags)));
    tilesetObject.setIvar("priorities", tableToUserDef(expandTileTable(tileset.priorities, newTableLength, oldFlags)));
    if (tileset.terrain) {
      tilesetObject.setIvar("terrain_tags", tableToUserDef(expandTileTable(tileset.terrain, newTableLength, oldFlags)));
    }
    changedTilesets.add(parsed.tilesetId);

    mapObject.setIvar("data", tableToUserDef(parsed.table));
    mapObject.setIvar("dn_banner_cleanup_version", VERSION);
    mapObject.setIvar("dn_banner_cleanup_rows", entry.rows);
    mapWrites.push({ file: path.join(dataDir, filename), bytes: Buffer.from(marshalDump(mapObject)) });
    pngWrites.push({ file: graphicFile, bytes: canvas.toBuffer("image/png") });
    console.log(`  ${label}: Map${entry.id} · ${parsed.width}×${parsed.height} · banda ${entry.rows} filas · ${variants.length} tiles con flags clonados.`);
  }

  if (changedTilesets.size) {
    const bytes = Buffer.from(marshalDump(tilesetsRaw));
    if (APPLY) writeAtomic(path.join(dataDir, "Tilesets.rxdata"), bytes);
  }
  if (APPLY) {
    for (const write of pngWrites) writeAtomic(write.file, write.bytes);
    for (const write of mapWrites) writeAtomic(write.file, write.bytes);
  }
  return { skipped, changed: mapWrites.length };
}

function getCellFlag(parsedTileset, tileId, field) {
  const table = parsedTileset[field];
  return table ? tableGet(table, tileId, 0, 0) : 0;
}

function mapTilesOutsideBand(parsed, rows) {
  const values = [];
  for (let z = 0; z < parsed.table.z; z++) {
    for (let y = 0; y < parsed.height; y++) {
      for (let x = 0; x < parsed.width; x++) {
        if (z === 0 && y < rows) continue;
        values.push(tableGet(parsed.table, x, y, z));
      }
    }
  }
  return values;
}

function collisionSignature(parsedMap, parsedTileset) {
  const values = [];
  for (let z = 0; z < parsedMap.table.z; z++) {
    for (let y = 0; y < parsedMap.height; y++) {
      for (let x = 0; x < parsedMap.width; x++) {
        const tileId = tableGet(parsedMap.table, x, y, z);
        values.push([
          getCellFlag(parsedTileset, tileId, "passages"),
          getCellFlag(parsedTileset, tileId, "priorities"),
          getCellFlag(parsedTileset, tileId, "terrain"),
        ]);
      }
    }
  }
  return values;
}

function imageRegionHash(image, width, height) {
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(image, 0, 0, width, height, 0, 0, width, height);
  return sha256(Buffer.from(ctx.getImageData(0, 0, width, height).data));
}

async function verifyInstall(dataDir, graphicsDir, label) {
  for (const entry of plan.cleanupTargets) {
    const baseline = entry.baseline;
    if (!baseline) throw new Error(`Map${entry.id}: el plan no tiene huellas originales para verificación reproducible.`);
    const currentMapObject = readRx(dataDir, mapFile(entry.id));
    const currentMap = parseMap(currentMapObject);
    const currentTilesets = readRx(dataDir, "Tilesets.rxdata");
    const currentTileset = parseTileset(currentTilesets[currentMap.tilesetId]);
    const marker = Number(currentMapObject.getIvar("dn_banner_cleanup_version") ?? 0);
    const rowsMarker = Number(currentMapObject.getIvar("dn_banner_cleanup_rows") ?? 0);
    if (marker !== VERSION || rowsMarker !== entry.rows) {
      throw new Error(`Map${entry.id}: falta el marcador de depuración v${VERSION}.`);
    }
    if (currentMap.width !== baseline.width || currentMap.height !== baseline.height ||
        currentMap.tilesetId !== baseline.tilesetId) {
      throw new Error(`Map${entry.id}: cambiaron dimensiones o tileset.`);
    }
    const eventsHash = sha256(Buffer.from(marshalDump(currentMapObject.getIvar("events"))));
    if (eventsHash !== baseline.eventsSha256) throw new Error(`Map${entry.id}: los eventos cambiaron.`);
    if (hashJson(mapTilesOutsideBand(currentMap, entry.rows)) !== baseline.outsideBandTileSha256) {
      throw new Error(`Map${entry.id}: se modificaron tiles fuera de la banda superior.`);
    }
    if (hashJson(collisionSignature(currentMap, currentTileset)) !== baseline.collisionSha256) {
      throw new Error(`Map${entry.id}: cambiaron pasabilidad, prioridad o terreno en una o más celdas.`);
    }

    const graphicName = `DN_${entry.id}.png`;
    const currentImage = await loadImage(path.join(graphicsDir, graphicName));
    const appendRows = Math.ceil(entry.rows * currentMap.width / COLUMNS);
    if (currentImage.width !== baseline.atlasWidth ||
        currentImage.height !== baseline.atlasHeight + appendRows * TILE) {
      throw new Error(`Map${entry.id}: tamaño de atlas inesperado ${currentImage.width}×${currentImage.height}.`);
    }
    if (imageRegionHash(currentImage, baseline.atlasWidth, baseline.atlasHeight) !== baseline.atlasPixelSha256) {
      throw new Error(`Map${entry.id}: cambió el arte base fuera de las variantes añadidas.`);
    }
    const imageCanvas = createCanvas(currentImage.width, currentImage.height);
    const imageCtx = imageCanvas.getContext("2d");
    imageCtx.drawImage(currentImage, 0, 0);
    const pixels = imageCtx.getImageData(0, 0, currentImage.width, currentImage.height).data;
    let variantIndex = 0;
    for (let y = 0; y < entry.rows; y++) {
      for (let x = 0; x < currentMap.width; x++) {
        const currentId = tableGet(currentMap.table, x, y, 0);
        const expectedId = FIRST_NORMAL_TILE + baseline.atlasCapacity + variantIndex;
        if (currentId !== expectedId) throw new Error(`Map${entry.id} (${x},${y}): tile ${currentId}, se esperaba variante ${expectedId}.`);
        const sourceId = tableGet(currentMap.table, x, y + entry.rows, 0);
        const sourceIndex = sourceId - FIRST_NORMAL_TILE;
        if (sourceIndex < 0 || sourceIndex >= baseline.atlasCapacity) {
          throw new Error(`Map${entry.id} (${x},${y}): tile de origen fuera del atlas (${sourceId}).`);
        }
        const destinationIndex = baseline.atlasCapacity + variantIndex;
        const columns = baseline.atlasWidth / TILE;
        for (let py = 0; py < TILE; py++) {
          for (let px = 0; px < TILE; px++) {
            const sx = ((sourceIndex % columns) * TILE + px + currentImage.width * (Math.floor(sourceIndex / columns) * TILE + py)) * 4;
            const dx = ((destinationIndex % columns) * TILE + px + currentImage.width * (Math.floor(destinationIndex / columns) * TILE + py)) * 4;
            if (pixels[sx] !== pixels[dx] || pixels[sx + 1] !== pixels[dx + 1] ||
                pixels[sx + 2] !== pixels[dx + 2] || pixels[sx + 3] !== pixels[dx + 3]) {
              throw new Error(`Map${entry.id} (${x},${y}): la variante no reproduce la textura de la escena.`);
            }
          }
        }
        variantIndex++;
      }
    }
    console.log(`  ${label}: Map${entry.id} OK · eventos/dimensiones intactos · flags por celda idénticos · arte verificado.`);
  }
}

async function renderSamples() {
  fs.mkdirSync(RENDER_DIR, { recursive: true });
  for (const entry of plan.cleanupTargets) {
    const { canvas } = await renderMapId(entry.id);
    const file = path.join(RENDER_DIR, `Map${entry.id}_polished.png`);
    fs.writeFileSync(file, canvas.toBuffer("image/png"));
    console.log(`  render → ${path.relative(ROOT, file)}`);
  }
}

/**
 * Recalcula las huellas del plan a partir del estado instalado.
 *
 * Tras reconstruir los mapas del Dimensional Nightmare (nuevas propuestas de
 * pasabilidad), los eventos se recolocan unas pocas celdas y el atlas se
 * regenera: las huellas originales dejan de servir. Este modo las vuelve a
 * medir con exactamente las mismas funciones que usa la verificación, de modo
 * que "sin alterar eventos, dimensiones ni colisiones" siga siendo cierto
 * hacia delante.
 */
async function refreshPlan() {
  const tilesetsRaw = readRx(GAME_DATA, "Tilesets.rxdata");
  for (const entry of plan.cleanupTargets) {
    const mapObject = readRx(GAME_DATA, mapFile(entry.id));
    const parsed = parseMap(mapObject);
    const tileset = parseTileset(tilesetsRaw[parsed.tilesetId]);
    const image = await loadImage(path.join(GAME_GRAPHICS, `DN_${entry.id}.png`));
    // La pasada añade ceil(variantes / COLUMNS) filas al atlas: se descuentan
    // para recuperar las medidas previas a la limpieza.
    const appendRows = Math.ceil((parsed.width * entry.rows) / COLUMNS);
    const atlasWidth = image.width;
    const atlasHeight = image.height - appendRows * TILE;
    const atlasCapacity = (atlasWidth / TILE) * (atlasHeight / TILE);
    if (atlasHeight <= 0 || image.height % TILE !== 0) {
      throw new Error(`Map${entry.id}: atlas ${image.width}x${image.height} no cuadra con ${appendRows} filas añadidas.`);
    }
    entry.baseline = {
      width: parsed.width,
      height: parsed.height,
      tilesetId: parsed.tilesetId,
      atlasWidth,
      atlasHeight,
      atlasCapacity,
      atlasPixelSha256: imageRegionHash(image, atlasWidth, atlasHeight),
      eventsSha256: sha256(Buffer.from(marshalDump(mapObject.getIvar("events")))),
      outsideBandTileSha256: hashJson(mapTilesOutsideBand(parsed, entry.rows)),
      collisionSha256: hashJson(collisionSignature(parsed, tileset)),
    };
    console.log(`  Map${entry.id}: huellas recalculadas · ${parsed.width}x${parsed.height} · atlas ${atlasWidth}x${atlasHeight} (${appendRows} filas añadidas).`);
  }
  plan.refreshedAt = new Date().toISOString();
  fs.writeFileSync(PLAN, `${JSON.stringify(plan, null, 2)}\n`);
  console.log(`Plan de depuración actualizado: ${path.relative(ROOT, PLAN)} (${plan.cleanupTargets.length} objetivos).`);
}

async function main() {
  validateInventory();
  if (REFRESH) {
    await refreshPlan();
    return;
  }
  if (VERIFY) {
    await verifyInstall(GAME_DATA, GAME_GRAPHICS, "juego");
    await verifyInstall(QA_DATA, QA_GRAPHICS, "qa");
    console.log(`Verificados ${plan.auditedMapCount} mapas en inventario y ${plan.cleanupTargets.length} limpiezas visuales sin alterar eventos, dimensiones ni colisiones.`);
    return;
  }

  if (APPLY) ensureBackups();
  const gameResult = await prepareInstall(GAME_DATA, GAME_GRAPHICS, "juego");
  const qaResult = await prepareInstall(QA_DATA, QA_GRAPHICS, "qa");
  if (APPLY) {
    console.log(`Aplicado: juego ${gameResult.changed} mapas · QA ${qaResult.changed} mapas · ${gameResult.skipped + qaResult.skipped} ya estaban listos.`);
    if (RENDER) await renderSamples();
  } else {
    console.log(`Simulación: se depurarían ${plan.cleanupTargets.length} mapas en juego y QA; no se escribió ningún archivo.`);
  }
}

main().catch((error) => {
  console.error(`Error en depuración de mapas: ${error.stack ?? error.message}`);
  process.exitCode = 1;
});#!/usr/bin/env node
/**
 * Parche: Abra de emergencia y Torre de Créditos 0 (Grandeur Club).
 *
 * Resuelve:
 * 1. Softlock al volver de Isla Espejo / Pueblo Paleta:
 *    - El ferry de vuelta en Mapa 997 ahora desembarca en (39, 23) (césped libre).
 *    - En Mapa 033 (Pueblo Paleta), la celda (39, 25) deja de tener el tile de valla
 *      bloqueante (bits de colisión = 0), permitiendo moverse en cualquier dirección
 *      incluso si se carga una partida ya guardada encima de la valla.
 *    - El Ayudante de Oak en (39, 24) tiene @through = true para no obstaculizar el paso,
 *      ofrece teletransporte directo a la casa de Ash en Kanto y entrega el "Abra de emergencia".
 *    - En Mapa 048 (Sótano laboratorio Oak), el Ayudante también tiene @through = true.
 *
 * 2. Objeto e interacción "Abra de emergencia":
 *    - Registrado como Objeto Clave (:ABRADEEMERGENCIA, id 1031, bolsillo 8, uso infinito)
 *      en items.dat con icono propio 48x48 en Graphics/Items/ABRADEEMERGENCIA.png.
 *    - Usable desde la Mochila en el mapa para teletransportar inmediatamente al jugador
 *      a la casa del protagonista en Kanto (Mapa 42, coordenadas 3, 8).
 *    - Eventos NPC Abra de emergencia ubicados en:
 *        * Mapa 997 (Atrio de Isla Espejo) en (12, 10).
 *        * Mapa 999 (Archivo Cero, junto al NPC de Game Over) en (19, 11).
 *      Ambos entregan el objeto al hablar con ellos y permiten teletransporte inmediato.
 *
 * 3. Torre de postgame (Grandeur Club) a 0 créditos:
 *    - Máquina expendedora (Mapa 151, Evento 72): todos los objetos, códigos, pases
 *      y BGM pack cuestan 0 créditos (condición de crédito >= 0, resta de créditos = 0).
 *    - Common Events 26..32 (Gemas y categorías de objetos de combate): comprobación
 *      de crédito >= 0 y llamada con precio 0.
 *    - Scripts.rxdata:
 *        * Sección 392 (Grandeur Club): grandeurItemExchange fuerza precio 0, permite
 *          hasta 99 unidades, no divide por 0 ni descuenta créditos, y recarga créditos.
 *        * Sección 393 (Sygna Buffs): SygnaBuff inicializa coste en 0, showShopBuffs
 *          muestra "0 GC Credits", y buyBuff permite adquirir todos los buffs sin coste
 *          ni comprobación de saldo.
 *        * Sección 248 (Item_Effects): manejadores UseInField y UseFromBag de :ABRADEEMERGENCIA.
 *
 * Uso:
 *   node tools/apply_emergency_abra_and_free_tower.mjs            # instala y verifica
 *   node tools/apply_emergency_abra_and_free_tower.mjs --verify   # solo verifica
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { marshalDump, marshalLoad, RObject, RString, RSymbol, RUserDef } from "../web/js/marshal.js";
import { cmdOf, parseEvent, parseMap, parseTileset, tableGet, tableSet, tableToUserDef, tableFromUserDef } from "../web/js/rmxp.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const BACKUP = path.join(GAME, "PokeModBackups", "emergency_abra_and_tower_originals");
const S = (value) => RString.fromText(String(value));
const iv = (object, name) => object?.getIvar?.(name);
const txt = (value) => value instanceof RString ? value.text : String(value ?? "");
const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));

function cmd(code, parameters = [], indent = 0) {
  return new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", parameters]]);
}
function condition(sw = 0) {
  return new RObject("RPG::Event::Page::Condition", [
    ["@switch1_valid", Boolean(sw)], ["@switch1_id", sw || 1],
    ["@switch2_valid", false], ["@switch2_id", 1],
    ["@variable_valid", false], ["@variable_id", 1], ["@variable_value", 0],
    ["@self_switch_valid", false], ["@self_switch_ch", S("A")]
  ]);
}
function graphic({ tile = 0, name = "", dir = 2 } = {}) {
  return new RObject("RPG::Event::Page::Graphic", [
    ["@tile_id", tile], ["@character_name", S(name)], ["@character_hue", 0],
    ["@direction", dir], ["@pattern", 0], ["@opacity", 255], ["@blend_type", 0]
  ]);
}
function route() {
  return new RObject("RPG::MoveRoute", [
    ["@repeat", true], ["@skippable", false],
    ["@list", [new RObject("RPG::MoveCommand", [["@code", 0], ["@parameters", []]])]]
  ]);
}
function page({ cond = condition(), gfx = graphic(), list = [cmd(0)], through = false, trigger = 0 } = {}) {
  return new RObject("RPG::Event::Page", [
    ["@condition", cond], ["@graphic", gfx], ["@move_type", 0], ["@move_speed", 3],
    ["@move_frequency", 3], ["@move_route", route()], ["@walk_anime", true],
    ["@step_anime", false], ["@direction_fix", false], ["@through", through],
    ["@always_on_top", false], ["@trigger", trigger], ["@list", list]
  ]);
}
function event(id, name, [x, y], pages) {
  return new RObject("RPG::Event", [
    ["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]
  ]);
}
function tone(red, green, blue, gray = 0) {
  const buffer = Buffer.alloc(32);
  [red, green, blue, gray].forEach((value, index) => buffer.writeDoubleLE(value, index * 8));
  return new RUserDef("Tone", Uint8Array.from(buffer));
}

// ---------------------------------------------------------------------------
// 1. Icono de Abra de emergencia (48x48 PNG)
// ---------------------------------------------------------------------------
async function installItemIcon() {
  const outPath = path.join(GAME, "Graphics", "Items", "ABRADEEMERGENCIA.png");
  if (fs.existsSync(outPath) && fs.statSync(outPath).size > 100) return;
  const abraIconPath = path.join(GAME, "Graphics", "Pokemon", "Icons", "ABRA.png");
  try {
    const { createCanvas, loadImage } = await import("@napi-rs/canvas");
    const img = await loadImage(abraIconPath);
    const canvas = createCanvas(48, 48);
    const ctx = canvas.getContext("2d");
    ctx.drawImage(img, 0, 0, 64, 64, 0, 0, 48, 48);
    fs.writeFileSync(outPath, canvas.toBuffer("image/png"));
  } catch (err) {
    if (fs.existsSync(abraIconPath)) {
      fs.copyFileSync(abraIconPath, outPath);
    }
  }
}

