    cmd(412),
    cmd(101, [S("¿Deseas usar Teletransporte ahora hacia la casa de Ash en Kanto?\\ch[1,2,Teletransportar,Quedarme aquí]")]),
    cmd(111, [1, 1, 0, 0, 0]),
