/**
 * apply_graficos_safety.mjs
 *
 * «Muchas crash movimiento z.»
 *
 * La Z del mapa es `Input::SPECIAL` → `pbUseKeyItem` (UI_ReadyMenu). Ese método
 * lee los objetos registrados de la PARTIDA y los busca con `GameData::Item.get`,
 * que lanza un error si el id ya no existe en los datos (los parches del DLC
 * renombran/retiran ítems). Resultado: menú con Z = error en mitad del mapa.
 *
 * Este aplicador inyecta la sección Ruby `PokeMod_Graficos`
 * (tools/lib/pokemod_graficos.rb) que limpia la lista de ids inválidos, deja
 * `registeredIndex` siempre válido y convierte cualquier fallo del menú en un
 * mensaje en pantalla en vez de la pantalla de error de RGSS.
 *
 * Uso:
 *   node tools/apply_graficos_safety.mjs            # aplica
 *   node tools/apply_graficos_safety.mjs --verify   # solo comprueba
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const VERIFY_ONLY = process.argv.includes("--verify");
const TITULO = "PokeMod_Graficos";
const RUBY = fs.readFileSync(new URL("./lib/pokemod_graficos.rb", import.meta.url), "utf8");

const SCRIPTS = [
  path.join(ROOT, "pokemon_fire_ash", "Data", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Paquete_directo", "Data", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Dimensional_Nightmare_QA", "Data", "Scripts.rxdata"),
].filter((f) => fs.existsSync(f));

const ESPERADOS = [
  "module PokeModGraficos",
  "def buscarPorCaja",
  "def arreglarTilesetDelMapa",
  "pokemod_orig_setup",
  "pokemod_orig_load_bitmap",
  "pokemod_orig_pbGetTileset",
];

function inyectar(archivo) {
  const scripts = marshalLoad(fs.readFileSync(archivo));
  const comprimido = zlib.deflateSync(Buffer.from(RUBY, "utf-8"));
  const idx = scripts.findIndex(([, t]) => t && t.text === TITULO);
  if (idx >= 0) scripts[idx][2] = new RString(comprimido);
  // Antes de la última sección (Main), como el resto de secciones PokeMod.
  else scripts.splice(scripts.length - 1, 0, [999903, RString.fromText(TITULO), new RString(comprimido)]);
  fs.writeFileSync(archivo, Buffer.from(marshalDump(scripts)));
  return idx >= 0;
}

function verificar(archivo) {
  const fallos = [];
  const scripts = marshalLoad(fs.readFileSync(archivo));
  const seccion = scripts.find(([, t]) => t && t.text === TITULO);
  if (!seccion) return [`${archivo}: falta la sección ${TITULO}`];
  let code = "";
  try { code = zlib.inflateSync(Buffer.from(seccion[2].bytes)).toString("utf8"); }
  catch { return [`${archivo}: la sección ${TITULO} no se puede descomprimir`]; }
  for (const e of ESPERADOS) if (!code.includes(e)) fallos.push(`${archivo}: falta «${e}»`);
  // La sección tiene que ir ANTES de Main (si no, se cargaría después del bucle)
  const iSec = scripts.findIndex(([, t]) => t && t.text === TITULO);
  const iMain = scripts.findIndex(([, t]) => t && t.text === "Main");
  if (iMain >= 0 && iSec > iMain) fallos.push(`${archivo}: ${TITULO} está después de Main`);
  return fallos;
}

let fallos = [];
let cambios = 0;
for (const archivo of SCRIPTS) {
  const rel = path.relative(ROOT, archivo);
  if (VERIFY_ONLY) {
    const f = verificar(archivo);
    fallos = fallos.concat(f);
    console.log(`${f.length ? "✘" : "✔"} ${rel}${f.length ? ` → ${f.join(" · ")}` : ""}`);
    continue;
  }
  const ya = inyectar(archivo);
  cambios += ya ? 0 : 1;
  const f = verificar(archivo);
  fallos = fallos.concat(f);
  console.log(`${f.length ? "✘" : "✔"} ${rel}: ${ya ? "sección actualizada" : "sección añadida"}`);
}

if (VERIFY_ONLY) {
  console.log(fallos.length ? `\n✘ ${fallos.length} problema(s)` : "\n✔ parche de gráficos presente y correcto");
  process.exit(fallos.length ? 1 : 0);
}
console.log(`\n✔ ${SCRIPTS.length} Scripts.rxdata con PokeMod_Graficos (${cambios} nuevos)`);
process.exit(fallos.length ? 1 : 0);#!/usr/bin/env node
/**
 * Mochila libre en la torre del laboratorio de Oak (Grandeur Club).
 *
 * Contexto verificado en los datos compilados de Fire Ash 3.7.1:
 *   - El segundo transportador cuántico del sótano del laboratorio de Oak
 *     (mapa 48, evento 16, condicionado por el switch 429 = Postgame) lleva al
 *     Pico Secreto (141), al Salón Grandeur (151) y al Escenario (214).
 *   - Ocho eventos de contacto de esa torre encienden el switch
 *     674 = NO ITEM INBATT (siete de ellos también 675 = NO ITEM OUTBATT).
 *   - El parche previo solo eliminó el switch 674 de `pbItemMenu`
 *     (Battle_Phase_Command). La Mochila se abría, pero
 *     `pbCanUseItemOnPokemon?` (Battle_Action_UseItem) seguía rechazando el
 *     objeto con "You can't use items here!".
 *
 * Este instalador termina el trabajo: el switch 674 deja de tener efecto sobre
 * el jugador dentro de cualquier combate interno. No se tocan los eventos de la
 * torre, la regla `!@internalBattle` de los sistemas externos ni el switch 675.
 *
 * Uso:
 *   node tools/apply_grandeur_bag_freedom.mjs            # instala y verifica
 *   node tools/apply_grandeur_bag_freedom.mjs --verify   # solo verifica
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { marshalDump, marshalLoad, RString } from "../web/js/marshal.js";
import { parseEvent, parseMap, cmdOf } from "../web/js/rmxp.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const BACKUP = path.join(GAME, "PokeModBackups", "grandeur_bag_originals");
const TOWER_MAPS = [141, 151, 214];
const OAK_LAB = 48;
const text = (value) => value instanceof RString ? value.text : String(value ?? "");
const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));

// --- Parche 1: Battle_Action_UseItem#pbCanUseItemOnPokemon? -----------------
const OLD_USE_GUARD = [
  "    # Player isn't allowed to use items",
  "    if $game_switches[674] && !(battler && !battler.pbOwnedByPlayer?)",
  "      scene.pbDisplay(_INTL(\"You can't use items here!\")) if showMessages",
  "      return false",
  "    end",
].join("\r\n");
const NEW_USE_GUARD = [
  "    # PokeMod: switch 674 (NO ITEM INBATT) no longer blocks the player's items.",
  "    # The Grandeur Club tower under Oak's lab sets it on entry; the Bag must",
  "    # stay usable there so the challenge can be played freely.",
].join("\r\n");
const USE_MARKER = "switch 674 (NO ITEM INBATT) no longer blocks";

// --- Parche 2: Battle_Phase_Command#pbItemMenu (instalado por Isla Espejo) ---
const OLD_MENU_GUARD = "    if !@internalBattle || $game_switches[674]";
const NEW_MENU_GUARD = [
  "    # PokeMod: switch 674 no longer disables the Bag in internal battles.",
  "    # Keep the original rule for external/special battle systems.",
  "    if !@internalBattle",
].join("\r\n");
const MENU_MARKER = "switch 674 no longer disables";

function sectionCode(scripts, name) {
  const row = scripts.find((entry) => text(entry[1]) === name);
  if (!row) throw new Error(`No se encontró la sección ${name} en Scripts.rxdata`);
  return { row, code: zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8") };
}
function storeCode(row, code) {
  row[2].bytes = Uint8Array.from(zlib.deflateSync(Buffer.from(code, "utf8")));
}
function backup() {
  fs.mkdirSync(BACKUP, { recursive: true });
  const target = path.join(BACKUP, "Scripts.rxdata");
  if (!fs.existsSync(target)) fs.copyFileSync(path.join(DATA, "Scripts.rxdata"), target);
  fs.writeFileSync(path.join(BACKUP, "LEEME.txt"), "Scripts.rxdata anterior a la Mochila libre del Grandeur Club. Restaura este archivo sobre Data/ para revertir el parche.\n");
}
function install() {
  const scripts = read("Scripts.rxdata");
  let changed = false;
  const use = sectionCode(scripts, "Battle_Action_UseItem");
  if (!use.code.includes(USE_MARKER)) {
    if (!use.code.includes(OLD_USE_GUARD)) throw new Error("Battle_Action_UseItem no contiene la comprobación original del switch 674");
    storeCode(use.row, use.code.replace(OLD_USE_GUARD, NEW_USE_GUARD));
    changed = true;
  }
  const menu = sectionCode(scripts, "Battle_Phase_Command");
  if (!menu.code.includes(MENU_MARKER)) {
    if (!menu.code.includes(OLD_MENU_GUARD)) throw new Error("Battle_Phase_Command no contiene la comprobación original del switch 674");
    storeCode(menu.row, menu.code.replace(OLD_MENU_GUARD, NEW_MENU_GUARD));
    changed = true;
  }
  if (changed) write("Scripts.rxdata", scripts);
  return changed;
}

function methodBody(code, signature) {
  const start = code.indexOf(signature);
  if (start < 0) return "";
  const rest = code.slice(start);
  const end = rest.search(/\r?\n  def /);
  return end < 0 ? rest : rest.slice(0, end);
}
function towerBagLocks() {
  const locks = [];
  for (const mapId of TOWER_MAPS) {
    const parsed = parseMap(read(`Map${String(mapId).padStart(3, "0")}.rxdata`));
    for (const { obj } of parsed.events) {
      const event = parseEvent(obj);
      for (const page of event.pages) for (const command of page.list) {
        const cmd = cmdOf(command);
        if (cmd.code !== 121) continue;
        const [from, to, operation] = cmd.params.map(Number);
        if (operation === 0 && from <= 674 && 674 <= to) locks.push({ mapId, eventId: event.id, name: event.name, page: page.index });
      }
    }
  }
  return locks;
}
function oakLabTowerDoor() {
  const parsed = parseMap(read(`Map${String(OAK_LAB).padStart(3, "0")}.rxdata`));
  for (const { obj } of parsed.events) {
    const event = parseEvent(obj);
    for (const page of event.pages) {
      const gated = page.condition?.switch1 === 429 || page.condition?.switch2 === 429;
      const transfers = page.list.map(cmdOf).filter((cmd) => cmd.code === 201 && Number(cmd.params[1]) === 141);
      if (gated && transfers.length) return { eventId: event.id, page: page.index };
    }
  }
  return null;
}
function verify() {
  const errors = [];
  const ok = (value, message) => { if (!value) errors.push(message); };
  const scripts = read("Scripts.rxdata");
  const use = sectionCode(scripts, "Battle_Action_UseItem");
  const useBody = methodBody(use.code, "def pbCanUseItemOnPokemon?");
  ok(useBody.length > 0, "no se encontró pbCanUseItemOnPokemon?");
  ok(use.code.includes(USE_MARKER), "falta el parche de Battle_Action_UseItem");
  ok(!/\$game_switches\s*\[\s*674\s*\]/.test(useBody), "pbCanUseItemOnPokemon? todavía consulta el switch 674");
  ok(useBody.includes("itemsRemaining == 0"), "pbCanUseItemOnPokemon? perdió el límite de objetos por combate");
  ok(useBody.includes("PBEffects::Embargo"), "pbCanUseItemOnPokemon? perdió la regla de Embargo");
  const menu = sectionCode(scripts, "Battle_Phase_Command");
  const menuBody = methodBody(menu.code, "def pbItemMenu");
  ok(menu.code.includes(MENU_MARKER), "falta el parche de Battle_Phase_Command");
  ok(!/\$game_switches\s*\[\s*674\s*\]/.test(menuBody), "pbItemMenu todavía consulta el switch 674");
  ok(menuBody.includes("if !@internalBattle"), "pbItemMenu perdió la regla de combates externos");
  for (const entry of scripts) {
    if (!(entry[2] instanceof RString)) continue;
    let code = "";
    try { code = zlib.inflateSync(Buffer.from(entry[2].bytes)).toString("utf8"); } catch { errors.push(`sección ${text(entry[1])} ilegible`); continue; }
    if (/\$game_switches\s*\[\s*674\s*\]/.test(code)) errors.push(`la sección ${text(entry[1])} aún consulta el switch 674`);
  }
  const door = oakLabTowerDoor();
  ok(door, "el laboratorio de Oak no conserva el transportador a la torre (mapa 141) condicionado por el switch 429");
  const locks = towerBagLocks();
  ok(locks.length === 8, `la torre debería conservar sus 8 activaciones originales del switch 674 (7 dobles 674-675 y 1 simple) y tiene ${locks.length}`);
  if (errors.length) throw new Error(`Mochila libre inválida (${errors.length}):\n- ${errors.join("\n- ")}`);
  console.log(`Verificación OK: la Mochila funciona dentro de la torre del laboratorio de Oak (transportador evento ${door.eventId}, mapas ${TOWER_MAPS.join("/")}); ${locks.length} activaciones del switch 674 conservadas pero inofensivas; 0 secciones de script consultan el switch 674.`);
}

if (!VERIFY_ONLY) {
  backup();
  const changed = install();
  console.log(changed ? `Parche aplicado a Scripts.rxdata. Backup: ${path.relative(ROOT, BACKUP)}` : "Scripts.rxdata ya contenía la Mochila libre; sin cambios.");
}
verify();#!/usr/bin/env node
/**
 * Instala/verifica "Horizontes": misión de Hypno en Ciudad Verde, un bosque
 * nuevo y 500 aventuras interactivas repartidas entre 20 lugares postgame.
 *
 * Es aditivo: usa mapas 1000-1020, switches 701-705 y variable 101. Conserva
 * los mapas y entrenadores base. Los originales tocados se copian una sola vez
 * a PokeModBackups/horizontes_originals/.
 *
 * Uso:
 *   node tools/apply_horizontes_500_expansion.mjs
 *   node tools/apply_horizontes_500_expansion.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  marshalLoad, marshalDump, RHash, RObject, RString, RSymbol,
} from "../web/js/marshal.js";
import { parseMap, parseTileset, tableGet } from "../web/js/rmxp.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const CATALOG_FILE = path.join(ROOT, "content", "horizontes_500.json");
const BACKUP = path.join(GAME, "PokeModBackups", "horizontes_originals");
const VERIFY = process.argv.includes("--verify");
const catalog = JSON.parse(fs.readFileSync(CATALOG_FILE, "utf8"));
const realms = catalog.realms;
const adventures = catalog.adventures;

const VIRIDIAN = 43;
const FOREST = 1000;
const HUB = 1001;
const POSTGAME = 429;
const QUEST_STARTED = 701;
const HYPNO_SUBDUED = 702;
const QUEST_COMPLETE = 703;
const HORIZONS_OPEN = 704;
const ALL_COMPLETE = 705;
const ADVENTURE_COUNT = 101;
const NPC_MARKER = "PokeMod: Guardabosques Horizontes";
const NEW_MAP_IDS = [FOREST, ...realms.map((r) => r.mapId)];
const affected = ["System.rxdata", "Map043.rxdata", "MapInfos.rxdata", "map_metadata.dat", "trainers.dat"];

const S = (v) => RString.fromText(String(v));
const Sym = (v) => new RSymbol(String(v));
const iv = (o, n) => o?.getIvar?.(n);
const txt = (v) => v instanceof RString ? v.text : String(v ?? "");
const sym = (v) => v instanceof RSymbol ? v.name : String(v ?? "");
const pad3 = (n) => String(n).padStart(3, "0");
const readRx = (f) => marshalLoad(fs.readFileSync(path.join(DATA, f)));
const writeRx = (f, v) => fs.writeFileSync(path.join(DATA, f), Buffer.from(marshalDump(v)));
const cloneMarshal = (v) => marshalLoad(Buffer.from(marshalDump(v)));

function backupAffected() {
  fs.mkdirSync(BACKUP, { recursive:true });
  for (const file of affected) {
    const src = path.join(DATA, file), dst = path.join(BACKUP, file);
    if (fs.existsSync(src) && !fs.existsSync(dst)) fs.copyFileSync(src, dst);
  }
  fs.writeFileSync(path.join(BACKUP, "LEEME.txt"),
    "Originales inmediatamente anteriores a Horizontes. No incluye partidas.\n" +
    "Para revertir, copia estos archivos a Data y elimina Map1000-Map1020.rxdata.\n");
}

// ---------------------------------------------------------------------------
// Constructores RMXP expandidos
// ---------------------------------------------------------------------------
function cmd(code, params = [], indent = 0) {
  return new RObject("RPG::EventCommand", [["@code",code],["@indent",indent],["@parameters",params]]);
}
function condition({ sw1=0, sw2=0, variable=0, variableValue=0, self="" } = {}) {
  return new RObject("RPG::Event::Page::Condition", [
    ["@switch1_valid",!!sw1],["@switch1_id",sw1||1],
    ["@switch2_valid",!!sw2],["@switch2_id",sw2||1],
    ["@variable_valid",!!variable],["@variable_id",variable||1],["@variable_value",variableValue||0],
    ["@self_switch_valid",!!self],["@self_switch_ch",S(self||"A")],
  ]);
}
function graphic(name="", dir=2, pattern=1) {
  return new RObject("RPG::Event::Page::Graphic", [
    ["@tile_id",0],["@character_name",S(name)],["@character_hue",0],
    ["@direction",dir],["@pattern",pattern],["@opacity",255],["@blend_type",0],
  ]);
}
function route() { return new RObject("RPG::MoveRoute", [["@repeat",true],["@skippable",false],["@list",[]]]); }
function page({ cond=condition(), gfx=graphic(), trigger=0, through=false, alwaysTop=false, list=[cmd(0)] } = {}) {
  return new RObject("RPG::Event::Page", [
    ["@condition",cond],["@graphic",gfx],["@move_type",0],["@move_speed",3],["@move_frequency",3],
    ["@move_route",route()],["@walk_anime",true],["@step_anime",false],["@direction_fix",false],
    ["@through",through],["@always_on_top",alwaysTop],["@trigger",trigger],["@list",list],
  ]);
}
function event(id,name,x,y,pages) {
  return new RObject("RPG::Event", [["@id",id],["@name",S(name)],["@x",x],["@y",y],["@pages",pages]]);
}
function wrapLine(input, max=43) {
  const out=[];
  for (const paragraph of String(input).split("\n")) {
    const words=paragraph.split(/\s+/).filter(Boolean); let line="";
    for (const word of words) {
      if (!line) line=word;
      else if (`${line} ${word}`.length<=max) line+=` ${word}`;
      else { out.push(line); line=word; }
    }
    if (line) out.push(line);
  }
  return out.length ? out : ["..."];
}
function textCommands(lines, indent=0) {
  const all=(Array.isArray(lines)?lines:[lines]).flatMap((line)=>wrapLine(line));
  return [cmd(101,[S("")],indent),...all.map((line)=>cmd(401,[S(line)],indent))];
}
function scriptCommands(lines, indent=0) {
  const all=Array.isArray(lines)?lines:[lines];
  return [cmd(355,[S(all[0]||"")],indent),...all.slice(1).map((line)=>cmd(655,[S(line)],indent))];
}
function transfer(map,x,y,dir=2,indent=0) { return cmd(201,[0,map,x,y,dir,1],indent); }
function setSwitch(id,on=true,indent=0) { return cmd(121,[id,id,on?0:1],indent); }
function selfOn(letter="A",indent=0) { return cmd(123,[S(letter),0],indent); }
function addEvent(mapObj,ev) { iv(mapObj,"events").pairs.push([Number(iv(ev,"id")),ev]); }
function commandsOf(ev) {
  const out=[]; for (const pg of iv(ev,"pages")||[]) for (const c of iv(pg,"list")||[]) out.push(c); return out;
}

// ---------------------------------------------------------------------------
// Flags del sistema
// ---------------------------------------------------------------------------
function installSystemFlags() {
  const system=readRx("System.rxdata");
  const switches=iv(system,"switches")||[];
  const variables=iv(system,"variables")||[];
  const names={
    [QUEST_STARTED]:"POKEMOD HYPNO RESCUE STARTED",
    [HYPNO_SUBDUED]:"POKEMOD HYPNO SUBDUED",
    [QUEST_COMPLETE]:"POKEMOD CHILDREN RESCUED",
    [HORIZONS_OPEN]:"POKEMOD HORIZONS OPEN",
    [ALL_COMPLETE]:"POKEMOD HORIZONS 500 COMPLETE",
  };
  for (const [id,name] of Object.entries(names)) switches[Number(id)]=S(name);
  variables[ADVENTURE_COUNT]=S("POKEMOD HORIZONS COMPLETED");
  system.setIvar("switches",switches); system.setIvar("variables",variables);
  writeRx("System.rxdata",system);
}

// ---------------------------------------------------------------------------
// Misión principal de Hypno
// ---------------------------------------------------------------------------
function viridianNpc(id) {
  const first=[
