function readRx(filePath) {
  return marshalLoad(new Uint8Array(fs.readFileSync(filePath)));
}

function writeRx(filePath, data) {
  fs.writeFileSync(filePath, Buffer.from(marshalDump(data)));
}

function updateMapInfos(targetPath) {
  if (!fs.existsSync(targetPath)) return;
  const infos = readRx(targetPath);
  let updated = 0;
  if (Array.isArray(infos.pairs)) {
    for (const [key, info] of infos.pairs) {
      const mid = typeof key === "number" ? key : Number(key.name ?? key.text ?? String(key));
      if (mid >= 3200 && mid <= 3631) {
        info.setIvar("@name", S(getLcTitle(mid)));
        updated++;
      }
    }
  }
  writeRx(targetPath, infos);
  console.log(`✔ ${targetPath}: ${updated} nombres de mapa de Liquid Crystal actualizados.`);
}

function updateCampaignCatalog() {
  const catalog = JSON.parse(fs.readFileSync(CAMPAIGNS_JSON, "utf8"));
  const lc = catalog.campaigns.find((c) => c.id === "liquid_crystal");
  if (!lc) return;
  let count = 0;
  for (const m of lc.maps) {
    if (m.mapId >= 3200 && m.mapId <= 3631) {
      m.title = getLcTitle(m.mapId);
      count++;
    }
  }
  fs.writeFileSync(CAMPAIGNS_JSON, `${JSON.stringify(catalog, null, 2)}\n`, "utf8");
  console.log(`✔ content/rom_campaigns_complete.json: ${count} títulos de Liquid Crystal actualizados.`);
}

function updateMap3200(mapPath) {
  if (!fs.existsSync(mapPath)) return;
  const map = readRx(mapPath);
  const evPairs = map.getIvar("@events");
  if (!evPairs || !Array.isArray(evPairs.pairs)) return;

  const kept = evPairs.pairs.filter(([, ev]) => {
    const name = ev.getIvar("@name")?.text ?? "";
    if (name.includes("liquid_crystal_1_") || name.startsWith("PokeMod Líder liquid_crystal 1")) return false;
    if (name.includes("Prof. Elm") || name.includes("Silver") || name.includes("Lyra") || name.includes("Eusine")) return false;
    return true;
  });

  let maxId = Math.max(0, ...kept.map(([k]) => (typeof k === "number" ? k : 0)));

  function makeNpc(name, sprite, x, y, lines) {
    maxId++;
    const pageGfx = new RObject("RPG::Event::Page::Graphic", [
      ["@character_name", S(sprite)],
      ["@character_hue", 0],
      ["@direction", 2],
      ["@pattern", 0],
      ["@opacity", 255],
      ["@blend_type", 0],
    ]);
    const list = [
      new RObject("RPG::EventCommand", [["@code", 101], ["@indent", 0], ["@parameters", [S("")]]]),
      ...lines.map((l) => new RObject("RPG::EventCommand", [["@code", 401], ["@indent", 0], ["@parameters", [S(l)]]])),
      new RObject("RPG::EventCommand", [["@code", 0], ["@indent", 0], ["@parameters", []]]),
    ];
    const page = new RObject("RPG::Event::Page", [
      ["@condition", new RObject("RPG::Event::Page::Condition", [
        ["@switch1_valid", false], ["@switch2_valid", false], ["@variable_valid", false],
        ["@self_switch_valid", false], ["@switch1_id", 1], ["@switch2_id", 1],
        ["@variable_id", 1], ["@variable_value", 0], ["@self_switch_ch", S("A")],
      ])],
      ["@graphic", pageGfx],
      ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
      ["@move_route", new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", false], ["@list", []]])],
      ["@walk_anime", true], ["@step_anime", false], ["@direction_fix", false],
      ["@through", false], ["@always_on_top", false], ["@trigger", 0],
      ["@list", list],
    ]);
    return [maxId, new RObject("RPG::Event", [
      ["@id", maxId], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", [page]],
    ])];
  }

  const profElm = makeNpc(
    "PokeMod Campaña ROM: NPC — Prof. Elm",
    "trchar046",
    4, 4,
    [
      "\\sp[Prof. Elm]¡Hola Ash! Es un honor tenerte en Pueblo Primavera. He estado investigando las pautas de eclosión de los huevos Pokémon.",
      "\\sp[Prof. Elm]Johto tiene leyendas milenarias: las tres bestias sagradas y las aves guardianas. ¡Disfruta cada paso de tu viaje!",
    ]
  );

  const silver = makeNpc(
    "PokeMod Campaña ROM: NPC — Rival Silver",
    "trchar003",
    8, 4,
    [
      "\\sp[Silver]¿Tú eres el famoso Ash? No me importan los discursos sobre la amistad. Solo los entrenadores con verdadera fuerza importan.",
      "\\sp[Silver]¡Si te cruzas en mi camino hacia la cima, te aplastaré!",
    ]
  );

  const lyra = makeNpc(
    "PokeMod Campaña ROM: NPC — Lyra",
    "trchar005",
    6, 5,
    [
      "\\sp[Lyra]¡Bienvenido a Johto, Ash! No olvides llevar siempre contigo el PokéGear y cuidar mucho a tu Pikachu.",
    ]
  );

  const eusine = makeNpc(
    "PokeMod Campaña ROM: NPC — Eusine",
    "trchar048",
    10, 5,
    [
      "\\sp[Eusine]He seguido el rastro del viento del norte… Suicune corre libre por las praderas de Johto. Algún día seré digno de su mirada.",
    ]
  );

  evPairs.pairs = [...kept, profElm, silver, lyra, eusine];
  writeRx(mapPath, map);
  console.log(`✔ ${mapPath}: eventos de New Bark Town personalizados con Elm, Silver, Lyra y Eusine.`);
}

function updateMap3631(mapPath) {
  if (!fs.existsSync(mapPath)) return;
  const map = readRx(mapPath);
  const evPairs = map.getIvar("@events");
  if (!evPairs || !Array.isArray(evPairs.pairs)) return;

  const finaleEv = evPairs.pairs.find(([, ev]) =>
    (ev.getIvar("@name")?.text ?? "").includes("Final — Liquid Crystal")
  );

  if (finaleEv) {
    const pages = finaleEv[1].getIvar("@pages");
    if (pages && pages[0]) {
      pages[0].setIvar("@list", [
        new RObject("RPG::EventCommand", [["@code", 101], ["@indent", 0], ["@parameters", [S("")]]]),
        new RObject("RPG::EventCommand", [["@code", 401], ["@indent", 0], ["@parameters", [S("\\sp[Red]… … …")]]]),
        new RObject("RPG::EventCommand", [["@code", 401], ["@indent", 0], ["@parameters", [S("\\sp[Red]… … …!")]]]),
        new RObject("RPG::EventCommand", [["@code", 401], ["@indent", 0], ["@parameters", [S("\\sp[Ash]¡Red! ¡Dos leyendas frente a frente en la cima del Monte Plateado!")]]]),
        new RObject("RPG::EventCommand", [["@code", 355], ["@indent", 0], ["@parameters", [S("$game_switches[992] = true")]]]),
        new RObject("RPG::EventCommand", [["@code", 101], ["@indent", 0], ["@parameters", [S("")]]]),
        new RObject("RPG::EventCommand", [["@code", 401], ["@indent", 0], ["@parameters", [S("¡Campaña de Pokémon Liquid Crystal completada! El paso entre dimensiones permanece abierto.")]]]),
        new RObject("RPG::EventCommand", [["@code", 0], ["@indent", 0], ["@parameters", []]]),
      ]);
    }
  }

  writeRx(mapPath, map);
  console.log(`✔ ${mapPath}: clímax en la cumbre del Monte Plateado actualizado con el Campeón Red.`);
}

function installEncounters() {
  if (!fs.existsSync(LC_ENCOUNTERS_JSON)) return;
  const catalog = JSON.parse(fs.readFileSync(LC_ENCOUNTERS_JSON, "utf8"));
  const encPath = path.join(DATA, "encounters.dat");
  const encounters = readRx(encPath);

  let count = 0;
  for (const zone of catalog.zones) {
    const keyStr = `${zone.mapId}_0`;
    const stepChances = new RHash(
      Object.entries(zone.step_chances).map(([t, steps]) => [new RSymbol(t), steps])
    );
    const types = new RHash(
      Object.entries(zone.types).map(([t, slots]) => [
        new RSymbol(t),
        slots.map(([w, sp, min, max]) => [w, new RSymbol(sp), min, max]),
      ])
    );
    const encObj = new RObject("GameData::Encounter", [
      ["@id", new RSymbol(keyStr)],
      ["@map", zone.mapId],
      ["@version", 0],
      ["@step_chances", stepChances],
      ["@types", types],
    ]);

    const idx = encounters.pairs.findIndex(
      ([k]) => (k && (k.name ?? k.text ?? String(k))) === keyStr
    );
    if (idx >= 0) {
      encounters.pairs[idx][1] = encObj;
    } else {
      encounters.pairs.push([new RSymbol(keyStr), encObj]);
    }
    count++;
  }

  writeRx(encPath, encounters);
  if (fs.existsSync(PKG_DATA)) {
    writeRx(path.join(PKG_DATA, "encounters.dat"), encounters);
  }
  console.log(`✔ encounters.dat: ${count} zonas de Liquid Crystal instaladas y sincronizadas.`);
}

export function verify() {
  const catalog = JSON.parse(fs.readFileSync(CAMPAIGNS_JSON, "utf8"));
  const lc = catalog.campaigns.find((c) => c.id === "liquid_crystal");
  if (!lc) throw new Error("Falta la campaña liquid_crystal en content/rom_campaigns_complete.json");

  for (const m of lc.maps) {
    const expected = getLcTitle(m.mapId);
    if (m.title !== expected) {
      throw new Error(`Map${m.mapId} título desincronizado: ${m.title} != ${expected}`);
    }
  }

  const encPath = path.join(DATA, "encounters.dat");
  const encounters = readRx(encPath);
  const lcEnc = JSON.parse(fs.readFileSync(LC_ENCOUNTERS_JSON, "utf8"));
  for (const zone of lcEnc.zones) {
    const keyStr = `${zone.mapId}_0`;
    const found = encounters.pairs.some(
      ([k]) => (k && (k.name ?? k.text ?? String(k))) === keyStr
    );
    if (!found) throw new Error(`Falta tabla de encuentros para ${zone.name}`);
  }

  console.log(`✔ Verificación OK: 432 mapas y ${lcEnc.zones.length} tablas de encuentros de Liquid Crystal validados.`);
}

export function main() {
  if (VERIFY_ONLY) {
    verify();
    return;
  }
  console.log("Aplicando títulos canónicos, lore y encuentros de Pokémon Liquid Crystal...");
  updateCampaignCatalog();
  updateMapInfos(path.join(DATA, "MapInfos.rxdata"));
  updateMapInfos(path.join(PKG_DATA, "MapInfos.rxdata"));

  updateMap3200(path.join(DATA, "Map3200.rxdata"));
  updateMap3200(path.join(PKG_DATA, "Map3200.rxdata"));

  updateMap3631(path.join(DATA, "Map3631.rxdata"));
  updateMap3631(path.join(PKG_DATA, "Map3631.rxdata"));

  installEncounters();
  console.log("OK: Integración de lore y narrativa de Pokémon Liquid Crystal completada.");
  verify();
}

main();#!/usr/bin/env node
/**
 * Instala/verifica la reconstrucción artesanal del Monte Silver:
 *
 *   - 2021  «Monte Silver — Falda»: mapa dibujado tile a tile con los
 *           materiales del propio Fire Ash (bosque nevado y montaña de la
 *           Ruta 216 / Monte Lanakila), con entrada real a la cueva
 *           (pbCaveEntrance), refugio de curación, placa y casa.
 *   - 2030  «Monte Silver — Gruta de los Testigos»: cueva de hielo NUEVA con
 *           las siete puertas custodiadas por Unown que deletrean TESTIGO.
 *           El contador del catálogo (v264) solo sube al SELLAR una emisión
 *           (victoria del jefe), nunca al entrar en el mapa.
 *   - 2022  «Monte Silver — Cumbre»: reconstruida sobre nieve real (la
 *           anterior era un tejado lleno de objetos Poké Ball), con escalera
 *           de hielo, placa inspeccionable, menú de puertas y música de Red.
 *
 * Se modifican: mapas 2021/2022, mapa nuevo 2030, MapInfos, map_metadata,
 * transferencias externas (mapa 48 y las 7 emisiones) y encounters.dat
 * (se añade 2030_0; 2021_0/2022_0 se conservan). Backups en
 * pokemon_fire_ash/PokeModBackups/monte_silver_rebuild_originals/.
 *
 * Uso:
 *   node tools/apply_monte_silver_rebuild.mjs
 *   node tools/apply_monte_silver_rebuild.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { marshalLoad, marshalDump, RHash, RObject, RString, RSymbol } from "../web/js/marshal.js";
import { parseEvent, parseMap } from "../web/js/rmxp.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";
import {
  TileCanvas, learnMaterial, paintMaterial, rectSet, stamp,
  reachableCells, passabilityOf, buildMapObject,
} from "./lib/map_painter.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const BACKUP = path.join(GAME, "PokeModBackups", "monte_silver_rebuild_originals");
const CATALOG_PATH = path.join(ROOT, "content", "monte_silver_rebuild.json");
const CATALOG = JSON.parse(fs.readFileSync(CATALOG_PATH, "utf8"));
const MULTI = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "multiverse_creepypasta.json"), "utf8"));
const MARKER = CATALOG.marker;

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));
const S = (v) => RString.fromText(String(v));
const Sym = (v) => new RSymbol(String(v));
const iv = (o, n) => o?.getIvar?.(n);
const txt = (v) => (v instanceof RString ? v.text : String(v ?? ""));
const pad3 = (n) => String(n).padStart(3, "0");
const mapFile = (id) => `Map${pad3(id)}.rxdata`;
const clone = (v) => marshalLoad(Buffer.from(marshalDump(v)));
const T = CATALOG.texts;
const cmdCode = (c) => Number(c.getIvar("code"));
const cmdParams = (c) => c.getIvar("parameters");

// ---------------------------------------------------------------- RMXP bits
function cmd(code, params = [], indent = 0) {
  return new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", params]]);
}
function condition({ sw = 0, self = "" } = {}) {
  return new RObject("RPG::Event::Page::Condition", [
    ["@switch1_valid", !!sw], ["@switch1_id", sw || 1],
    ["@switch2_valid", false], ["@switch2_id", 1],
    ["@variable_valid", false], ["@variable_id", 1], ["@variable_value", 0],
    ["@self_switch_valid", !!self], ["@self_switch_ch", S(self || "A")],
  ]);
}
function graphic(charName = "", dir = 2, pattern = 1, tile = 0, opts = {}) {
  return new RObject("RPG::Event::Page::Graphic", [
    ["@tile_id", tile], ["@character_name", S(charName)], ["@character_hue", 0],
    ["@direction", dir], ["@pattern", pattern], ["@opacity", opts.opacity ?? 255], ["@blend_type", 0],
  ]);
}
function moveRoute() { return new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", false], ["@list", []]]); }
function page({ cond = condition(), gfx = graphic(), trigger = 0, through = false, list = [cmd(0)] } = {}) {
  return new RObject("RPG::Event::Page", [
    ["@condition", cond], ["@graphic", gfx],
    ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
    ["@move_route", moveRoute()], ["@walk_anime", true], ["@step_anime", false],
    ["@direction_fix", false], ["@through", through], ["@always_on_top", false],
    ["@trigger", trigger], ["@list", list],
  ]);
}
function event(id, name, x, y, pages) {
  return new RObject("RPG::Event", [["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]]);
}
function texts(lines, indent = 0) {
  const arr = Array.isArray(lines) ? lines : [lines];
  return [cmd(101, [S("")], indent), ...arr.map((line) => cmd(401, [S(line)], indent))];
}
function script(line, indent = 0) { return cmd(355, [S(line)], indent); }
function transfer(map, x, y, dir = 2, indent = 0) { return cmd(201, [0, map, x, y, dir, 1], indent); }
function choices(labels, branches, indent = 0) {
  const list = [cmd(102, [labels.map(S), 2], indent)];
  branches.forEach((branch, i) => {
    list.push(cmd(402, [i, S(labels[i])], indent));
    list.push(...branch);
  });
  list.push(cmd(404, [], indent));
  return list;
}
function inspectEvent(id, name, x, y, lines, { tile = 0 } = {}) {
  return event(id, name, x, y, [page({ gfx: graphic("", 2, 1, tile), trigger: 2, list: [...texts(lines), cmd(0)] })]);
}
function itemBall(id, x, y, item) {
  return event(id, `${MARKER} Objeto`, x, y, [
    page({ gfx: graphic("Object ball"), list: [cmd(111, [12, S(`pbItemBall(:${item})`)]), cmd(123, [S("A"), 0], 1), cmd(411), cmd(412), cmd(0)] }),
    page({ cond: condition({ self: "A" }), gfx: graphic("", 2, 1, 0, { opacity: 0 }), through: true, list: [cmd(0)] }),
  ]);
}
function healerEvent(id, x, y) {
  const list = [
    ...texts(T.refugio),
    ...choices(["Sí", "No"], [
      [cmd(314, [0], 1), ...texts([T.refugioHealed], 1)],
      texts([T.refugioNo], 1),
    ]),
    cmd(0),
  ];
  return event(id, `${MARKER} Guardiana`, x, y, [page({ gfx: graphic("NPC 16"), list })]);
}
function exitEvent(id, name, x, y, targetMap, arrival, message) {
  return event(id, `${MARKER} ${name}`, x, y, [page({
    trigger: 1,
    list: [...texts([message]), transfer(targetMap, arrival[0], arrival[1]), cmd(0)],
  })]);
}
function caveEntranceEvent(id, x, y, targetMap, arrival, message) {
  return event(id, `${MARKER} Entrada de cueva`, x, y, [page({
    trigger: 1,
    list: [...texts([message]), script("pbCaveEntrance"), transfer(targetMap, arrival[0], arrival[1], 8), cmd(0)],
  })]);
}
function caveExitEvent(id, name, x, y, targetMap, arrival, message) {
  return event(id, `${MARKER} ${name}`, x, y, [page({
    trigger: 1,
    list: [...texts([message]), script("pbCaveExit"), transfer(targetMap, arrival[0], arrival[1], 2), cmd(0)],
  })]);
}
function unownDoorEvent(id, zone, index, x, y, targetMap, arrival) {
  const openList = [
    ...texts(T.doorIntro),
    ...texts([CATALOG.unownLetters[index]]),
    ...choices(T.doorChoice, [[transfer(targetMap, arrival[0], arrival[1], 2, 1)], []]),
    cmd(0),
  ];
  const sealed = [...texts(T.doorSealed), cmd(0)];
  return event(id, `${MARKER} Puerta ${index + 1} — ${CATALOG.unownLetters[index]}`, x, y, [
    page({ gfx: graphic(CATALOG.unownSprites[index], 2), list: openList }),
    page({ cond: condition({ sw: 768 + zone }), gfx: graphic(CATALOG.unownSprites[index], 2), list: sealed }),
  ]);
}

// ------------------------------------------------------- materiales aprendidos
function range(a, b) { const s = new Set(); for (let i = a; i <= b; i++) s.add(i); return s; }
const MATERIALS = {
  forest: learnMaterial({
    name: "bosque nevado",
    tiles: new Set([4480, 4481, 4484, 4485, 4488, 4489, 4492, 4493, 4496, 4497, 4500, 4501]),
    sources: [620, 622, 924, 625, 621, 623, 624],
  }),
  mountain: learnMaterial({
