import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RHash, RObject, RString, RSymbol } from "../web/js/marshal.js";
import { parseMap } from "../web/js/rmxp.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";
import { S, Sym, txt, condition, graphic, moveRoute, cmd, grid, walkableAt } from "./lib/dn_rmxp.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const STRICT = process.argv.includes("--strict");
const BACKUP = path.join(GAME, "PokeModBackups", "pokegods_originales");
const CATALOG = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "pokegods_originales.json"), "utf8"));
const MARKER = "PokeMod Pokégod:";
const ISLAND_MAPS = [997, 998, 999];
const PER_MAP = 7;
const POSTGAME = 429;
const CHOICE_VARIABLE = 1;
const TEMPLATE_SPECIES = "PIKACHU";

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));
const iv = (object, name) => object?.getIvar?.(name);
const symbol = (value) => (value instanceof RSymbol ? value.name : String(value ?? ""));
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;

function backup(file) {
  fs.mkdirSync(BACKUP, { recursive: true });
  const origin = path.join(DATA, file);
  const copy = path.join(BACKUP, file);
  if (fs.existsSync(origin) && !fs.existsSync(copy)) fs.copyFileSync(origin, copy);
}

// ------------------------------------------------------------------- textos
function wrap(input, max = 43) {
  const output = [];
  for (const paragraph of String(input).split("\n")) {
    let line = "";
    for (const word of paragraph.split(/\s+/).filter(Boolean)) {
      if (!line) line = word;
      else if (`${line} ${word}`.length <= max) line += ` ${word}`;
      else { output.push(line); line = word; }
    }
    if (line) output.push(line);
  }
  return output.length ? output : ["..."];
}
function texts(lines, indent = 0) {
  const flat = (Array.isArray(lines) ? lines : [lines]).flatMap((line) => wrap(line));
  return [cmd(101, [S(flat[0])], indent), ...flat.slice(1).map((line) => cmd(401, [S(line)], indent))];
}
function scriptLines(lines, indent = 0) {
  const all = Array.isArray(lines) ? lines : [lines];
  return [cmd(355, [S(all[0] || "")], indent), ...all.slice(1).map((line) => cmd(655, [S(line)], indent))];
}
function branch(code, params, indent = 0) { return cmd(code, params, indent); }
const elseBranch = (indent = 0) => cmd(411, [], indent);
const endBranch = (indent = 0) => cmd(412, [], indent);

function page(opts) {
  return new RObject("RPG::Event::Page", [
    ["@condition", opts.cond ?? condition()],
    ["@graphic", opts.gfx ?? graphic()],
    ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
    ["@move_route", moveRoute()],
    ["@walk_anime", opts.walkAnime ?? false],
    ["@step_anime", opts.stepAnime ?? false],
    ["@direction_fix", opts.directionFix ?? true],
    ["@through", false],
    ["@always_on_top", false],
    ["@trigger", opts.trigger ?? 0],
    ["@list", opts.list ?? [cmd(0)]],
  ]);
}
function event(id, name, x, y, pages) {
  return new RObject("RPG::Event", [["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]]);
}

// ------------------------------------------------------------------ assets
function spriteFiles(id) {
  return [
    path.join(GAME, "Graphics", "Pokemon", "Front", `${id}.png`),
    path.join(GAME, "Graphics", "Pokemon", "Back", `${id}.png`),
    path.join(GAME, "Graphics", "Pokemon", "Icons", `${id}.png`),
    path.join(GAME, "Graphics", "Characters", `${id}.png`),
  ];
}
function pngSize(file) {
  const buffer = fs.readFileSync(file);
  return [buffer.readUInt32BE(16), buffer.readUInt32BE(20)];
}

/** Especies con los cuatro sprites ya construidos (cero assets ausentes). */
function readySpecies() {
  const ready = [];
  const pending = [];
  for (const entry of CATALOG.roster) {
    if (spriteFiles(entry.id).every((file) => fs.existsSync(file))) ready.push(entry);
    else pending.push(entry.id);
  }
  if (STRICT && pending.length) {
    throw new Error(`Faltan sprites de ${pending.length} Pokégods: ${pending.join(", ")}. ` +
      `Genera el arte en ${CATALOG.assets.conceptDir}/ y ejecuta tools/build_pokegods_sprites.mjs.`);
  }
  return { ready, pending };
}

// --------------------------------------------------------------- species.dat
function speciesRegistry() {
  const data = read("species.dat");
  const bySymbol = new Map();
  let maxId = 0;
  for (const [key, value] of data.pairs) {
    if (key instanceof RSymbol && value?.getIvar) bySymbol.set(key.name, value);
    if (typeof key === "number") maxId = Math.max(maxId, key);
    if (key instanceof RSymbol && value?.getIvar) maxId = Math.max(maxId, Number(value.getIvar("@id_number") ?? 0));
  }
  return { data, bySymbol, maxId };
}
function statHash(values) {
  return new RHash(Object.entries(values).map(([stat, value]) => [Sym(stat), Number(value)]));
}
function speciesObject(entry, template, idNumber, cryTemplate) {
  const object = new RObject(template.className, template.ivars.map(([name, value]) => [name, value]));
  const set = (name, value) => object.setIvar(name, value);
  set("@id", Sym(entry.id));
  set("@id_number", idNumber);
  set("@species", Sym(entry.id));
  set("@form", 0);
  set("@real_name", S(entry.name));
  set("@real_form_name", null);
  set("@real_category", S(entry.category));
  set("@real_pokedex_entry", S(entry.dex));
  set("@pokedex_form", 0);
  set("@type1", Sym(entry.types[0]));
  set("@type2", Sym(entry.types[1] ?? entry.types[0]));
  set("@base_stats", statHash(entry.baseStats));
  set("@evs", statHash({
    HP: 0, ATTACK: 0, DEFENSE: 0, SPECIAL_ATTACK: 0, SPECIAL_DEFENSE: 0, SPEED: 0, ...entry.evs,
  }));
  set("@base_exp", entry.baseExp);
  set("@growth_rate", Sym(entry.growthRate));
  set("@gender_ratio", Sym(entry.genderRatio));
  set("@catch_rate", entry.catchRate);
  set("@happiness", entry.happiness);
  set("@moves", entry.moves.map((move) => [1, Sym(move)]));
  set("@tutor_moves", []);
  set("@egg_moves", []);
  set("@abilities", entry.abilities.map((ability) => Sym(ability)));
  set("@hidden_abilities", [Sym(entry.hiddenAbility)]);
  set("@wild_item_common", null);
  set("@wild_item_uncommon", null);
  set("@wild_item_rare", null);
  set("@egg_groups", entry.eggGroups.map((group) => Sym(group)));
  set("@hatch_steps", entry.hatchSteps);
  set("@incense", null);
  set("@evolutions", []);
  set("@height", entry.height);
  set("@weight", entry.weight);
  set("@color", Sym(entry.color));
  set("@shape", Sym(entry.shape));
  set("@habitat", Sym(entry.habitat));
  set("@generation", 1);
  set("@mega_stone", null);
  set("@mega_move", null);
  set("@unmega_form", 0);
  set("@mega_message", 0);
  set("@back_sprite_x", 0);
  set("@back_sprite_y", 50);
  set("@front_sprite_x", 0);
  set("@front_sprite_y", 20);
  set("@front_sprite_altitude", 0);
  set("@front_sprite_scale", 2);
  set("@back_sprite_scale", 3);
  set("@shadow_x", 0);
  set("@shadow_size", 2);
  set("@no_dynamax", true);
  if (cryTemplate) {
    for (const name of ["@gmax_height", "@dmax_metrics", "@gmax_metrics"]) {
      const value = iv(cryTemplate, name);
      if (value !== undefined) set(name, value);
    }
  }
  return object;
}

function installSpecies(entries) {
  const { data, bySymbol, maxId } = speciesRegistry();
  const template = bySymbol.get(TEMPLATE_SPECIES);
  if (!template) throw new Error(`Falta la especie plantilla ${TEMPLATE_SPECIES}`);
  let next = maxId + 1;
  const installed = [];
  for (const entry of entries) {
    if (bySymbol.has(entry.id)) {
      installed.push({ entry, idNumber: Number(iv(bySymbol.get(entry.id), "@id_number")) });
      continue;
    }
    const cryTemplate = bySymbol.get(entry.crySource);
    if (!cryTemplate) throw new Error(`Falta la especie de grito ${entry.crySource} (${entry.id})`);
    const object = speciesObject(entry, template, next, cryTemplate);
    data.pairs.push([next, object], [Sym(entry.id), object]);
    bySymbol.set(entry.id, object);
    installed.push({ entry, idNumber: next });
    next++;
  }
  if (installed.some(({ entry }) => !bySymbol.has(entry.id) || true)) {
    backup("species.dat");
    write("species.dat", data);
  }
  return installed;
}

/** Fire Ash resuelve el grito por símbolo de especie: Audio/SE/<SIMBOLO>.ogg. */
function installCries(installed) {
  const seDir = path.join(GAME, "Audio", "SE");
  const written = [];
  for (const { entry } of installed) {
    const target = path.join(seDir, `${entry.id}.ogg`);
    if (fs.existsSync(target)) continue;
    const source = path.join(seDir, `${entry.crySource}.ogg`);
    if (!fs.existsSync(source)) throw new Error(`Falta el grito origen ${entry.crySource}.ogg (${entry.id})`);
    fs.copyFileSync(source, target);
    written.push(entry.id);
  }
  return written;
}

// ------------------------------------------------------------ Isla Espejo
/** Celdas transitables y libres dentro del componente conexo más grande. */
function freeCells(mapId) {
  const g = grid(mapId);
  const key = (x, y) => `${x},${y}`;
  const open = new Set();
  for (let y = 0; y < g.height; y++) {
    for (let x = 0; x < g.width; x++) {
      if (walkableAt(g, x, y) && !g.occupied.has(key(x, y))) open.add(key(x, y));
    }
  }
  const seen = new Set();
  let best = [];
  for (const cell of open) {
    if (seen.has(cell)) continue;
    const [sx, sy] = cell.split(",").map(Number);
    const component = [];
    const queue = [[sx, sy]];
    seen.add(cell);
    while (queue.length) {
      const [x, y] = queue.pop();
      component.push([x, y]);
      for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
        const next = key(nx, ny);
        if (open.has(next) && !seen.has(next)) { seen.add(next); queue.push([nx, ny]); }
      }
    }
    if (component.length > best.length) best = component;
  }
  return best;
}

/** Reparto por máxima separación: empieza en el centro y elige lo más lejano. */
function spread(cells, count) {
  if (cells.length < count) throw new Error("El mapa no tiene celdas libres suficientes");
  const centroid = cells.reduce((acc, [x, y]) => [acc[0] + x / cells.length, acc[1] + y / cells.length], [0, 0]);
  const distance = (a, b) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
  let start = cells[0];
  for (const cell of cells) if (distance(cell, centroid) < distance(start, centroid)) start = cell;
  const chosen = [start];
  while (chosen.length < count) {
    let best = null, bestScore = -1;
    for (const cell of cells) {
      if (chosen.some((c) => c[0] === cell[0] && c[1] === cell[1])) continue;
      const score = Math.min(...chosen.map((c) => distance(c, cell)));
      if (score > bestScore) { bestScore = score; best = cell; }
    }
    chosen.push(best);
  }
  return chosen;
}

/** Guion Ruby de una Forma de Anomalía (el patrón ya probado en Horizontes). */
function anomalyScript(entry, formKey) {
  const form = CATALOG.forms[formKey];
  const anomaly = entry.anomaly;
  const lines = [`p=Pokemon.new(:${entry.id},${form.level})`, "GameData::Stat.each_main { |s| p.iv[s.id]=31 }"];
  if (form.evs) {
    const [first, second] = anomaly.evSpread;
    lines.push(`p.ev[:${first}]=${form.evs.first}; p.ev[:${second}]=${form.evs.second}; p.ev[:HP]=${form.evs.hp}`);
  }
  if (form.nature === "anomaly") lines.push(`p.nature=:${anomaly.nature}`);
  if (form.shiny) lines.push("p.shiny=true");
  if (form.ability === "hidden") lines.push(`p.ability=:${entry.hiddenAbility}`);
  else if (form.ability === "WONDERGUARD") lines.push(`p.ability=:${form.ability}`);
  else lines.push(`p.ability=:${entry.abilities[0]}`);
  lines.push("p.calc_stats");
  for (const rule of form.rules) lines.push(`setBattleRule("${rule}")`);
  if (form.weather) {
    const weather = anomaly.weather[form.weather];
    lines.push(`setBattleRule("weather",:${weather})`);
  }
  if (form.backdrop) lines.push(`setBattleRule("backdrop","${form.backdrop}")`);
  lines.push("d=pbWildBattleCore(p)");
  return lines;
}

function pokegodEvent(id, entry, x, y) {
  const forms = ["alfa", "beta", "omega"];
  const labels = [...forms.map((key) => CATALOG.forms[key].label), "Retirarse"];
  const list = [
    ...texts([`Una anomalía toma forma: ${entry.name}.`]),
    ...texts([entry.lore]),
    ...texts([`El cristal ofrece tres Formas de Anomalía.\\ch[${CHOICE_VARIABLE},${labels.length},${labels.join(",")}]`]),
  ];
  forms.forEach((key, index) => {
    list.push(branch(111, [1, CHOICE_VARIABLE, 0, index, 0]));
    list.push(...scriptLines(anomalyScript(entry, key), 1));
    list.push(branch(111, [12, S("d==1 || d==4")], 1));
    list.push(...texts([`${entry.name} se disuelve en datos. El espejo registra el encuentro.`], 2));
    list.push(elseBranch(1));
    list.push(...texts(["La anomalía se recompone. Puedes recuperarte y volver a intentarlo."], 2));
    list.push(endBranch(1));
    list.push(endBranch());
  });
  list.push(cmd(0));

  const gfx = graphic(entry.id, 2, 1, {});
  return event(id, `${MARKER} ${entry.id}`, x, y, [
    page({ list: [cmd(0)] }),
    page({ cond: condition({ sw: POSTGAME }), gfx, stepAnime: true, list }),
  ]);
}

function archiveEvent(id, x, y, count) {
  const list = [
    ...texts(["Voz del archivo: esta isla no cría Pokémon. Repite lo que se contó de ellos hasta que alguien lo cree."]),
    ...texts([`Registro de anomalías: ${count} manifestaciones estables en las tres salas.`]),
    ...texts(["Cada una responde a tres Formas: Alfa es el rumor tal cual; Beta añade clima hostil y prohíbe huir; Omega rompe las reglas y solo la rozan los ataques super eficaces."]),
    ...texts(["Puedes capturarlas. Y puedes marcharte cuando quieras: el espejo del atrio devuelve al sótano de Isla Canela."]),
    cmd(0),
  ];
  return event(id, `${MARKER} Archivo`, x, y, [
    page({ list: [cmd(0)] }),
    page({ cond: condition({ sw: POSTGAME }), gfx: graphic("NPC 16", 2, 1, {}), list }),
  ]);
}

function installIsland(installed) {
  const placed = [];
  let cursor = 0;
  // reparto equilibrado entre los mapas de la isla (la capacidad ya no es fija)
  const total = installed.length;
  const counts = ISLAND_MAPS.map((_, i) =>
    Math.floor(total / ISLAND_MAPS.length) + (i < total % ISLAND_MAPS.length ? 1 : 0));
  ISLAND_MAPS.forEach((mapId, mapIndex) => {
    const slice = installed.slice(cursor, cursor + counts[mapIndex]);
    cursor += counts[mapIndex];
    if (!slice.length) return;
    const file = mapFile(mapId);
    backup(file);
    const map = marshalLoad(fs.readFileSync(path.join(DATA, file)));
    const events = iv(map, "events");
    const kept = events.pairs.filter(([, object]) => !txt(iv(object, "name")).startsWith(MARKER));
    const archiveHere = mapIndex === ISLAND_MAPS.length - 1 && slice.length > 0;
    const cells = spread(freeCells(mapId), slice.length + (archiveHere ? 1 : 0));
    let nextId = Math.max(0, ...kept.map(([key]) => (typeof key === "number" ? key : 0))) + 1;
    const added = [];
    slice.forEach(({ entry }, index) => {
      added.push(pokegodEvent(nextId++, entry, cells[index][0], cells[index][1]));
      placed.push({ mapId, id: entry.id, x: cells[index][0], y: cells[index][1] });
    });
    if (archiveHere) {
      const [ax, ay] = cells[slice.length];
      added.push(archiveEvent(nextId++, ax, ay, installed.length));
      placed.push({ mapId, id: "Archivo", x: ax, y: ay });
    }
    events.pairs = [...kept, ...added.map((object) => [Number(iv(object, "@id")), object])];
    write(file, map);
  });
  return placed;
}

// ------------------------------------------------------------- verificación
function verify(installed, pending) {
  const errors = [];
  const ok = (value, message) => { if (!value) errors.push(message); };

  for (const { entry } of installed) {
    for (const file of spriteFiles(entry.id)) {
      ok(fs.existsSync(file), `${entry.id}: falta el sprite ${path.relative(GAME, file)}`);
    }
    const [fw, fh] = pngSize(path.join(GAME, "Graphics", "Pokemon", "Front", `${entry.id}.png`));
    ok(fw === 96 && fh === 96, `${entry.id}: el frente mide ${fw}x${fh}`);
    ok(fs.existsSync(path.join(GAME, "Audio", "SE", `${entry.id}.ogg`)), `${entry.id}: falta el grito`);
  }

  const { bySymbol } = speciesRegistry();
  for (const { entry, idNumber } of installed) {
    const object = bySymbol.get(entry.id);
    ok(object, `${entry.id}: no está registrada en species.dat`);
    if (!object) continue;
    ok(Number(iv(object, "@id_number")) === idNumber, `${entry.id}: id_number inconsistente`);
    ok(symbol(iv(object, "@type1")) === entry.types[0], `${entry.id}: tipo 1 incorrecto`);
    ok(symbol(iv(object, "@type2")) === (entry.types[1] ?? entry.types[0]), `${entry.id}: tipo 2 incorrecto`);
    ok(txt(iv(object, "@real_name")) === entry.name, `${entry.id}: nombre incorrecto`);
    ok(symbol(iv(object, "@abilities")[0]) === entry.abilities[0], `${entry.id}: habilidad incorrecta`);
    const stats = iv(object, "@base_stats");
    for (const [stat, value] of Object.entries(entry.baseStats)) {
      const stored = stats.pairs.find(([key]) => symbol(key) === stat);
      ok(stored && Number(stored[1]) === value, `${entry.id}: ${stat} incorrecta`);
    }
  }
  const topLevel = Math.max(CATALOG.forms.alfa.level, CATALOG.forms.beta.level, CATALOG.forms.omega.level);
  ok(topLevel <= CATALOG.guarantees.levelCap, `la forma más alta (${topLevel}) supera el tope del juego`);

  // Eventos de la isla: celdas libres, sin solapes y con las tres formas.
  let eventCount = 0;
  for (const mapId of ISLAND_MAPS) {
    const map = marshalLoad(fs.readFileSync(path.join(DATA, mapFile(mapId))));
    const events = iv(map, "events").pairs.map(([, object]) => object);
    const mine = events.filter((object) => txt(iv(object, "@name")).startsWith(MARKER));
    eventCount += mine.length;
    const occupied = new Set(events.map((object) => `${iv(object, "@x")},${iv(object, "@y")}`));
    const free = new Set(freeCells(mapId).map(([x, y]) => `${x},${y}`));
    for (const object of mine) {
      const name = txt(iv(object, "@name")).replace(MARKER, "").trim();
      const cell = `${iv(object, "@x")},${iv(object, "@y")}`;
      const pages = iv(object, "@pages") ?? [];
      ok(pages.length === 2, `${name}: debe tener página invisible y página de postgame`);
      ok(Number(iv(pages[1]?.getIvar?.("@condition"), "@switch1_id")) === POSTGAME, `${name}: no depende del switch ${POSTGAME}`);
      const charName = txt(iv(iv(pages[1], "@graphic"), "@character_name"));
      if (name !== "Archivo") {
        ok(fs.existsSync(path.join(GAME, "Graphics", "Characters", `${charName}.png`)), `${name}: sprite de overworld ausente (${charName})`);
        const commands = iv(pages[1], "@list") ?? [];
        const ruby = commands.filter((command) => [355, 655].includes(Number(iv(command, "@code"))))
          .map((command) => txt(iv(command, "@parameters")[0])).join("\n");
        ok(ruby.includes("setBattleRule(\"canLose\")"), `${name}: la batalla debe permitir perder`);
        ok(ruby.includes("pbWildBattleCore(p)"), `${name}: no arranca el combate`);
        ok(commands.some((command) => Number(iv(command, "@code")) === 111
          && Number(iv(command, "@parameters")[0]) === 12
          && txt(iv(command, "@parameters")[1]).includes("d==1 || d==4")), `${name}: no comprueba derrota o captura`);
        for (const key of ["alfa", "beta", "omega"]) {
          ok(ruby.includes(`setBattleRule("${CATALOG.forms[key].rules[0]}")`), `${name}: falta la forma ${key}`);
        }
        ok((ruby.match(/Pokemon\.new/g) || []).length === 3, `${name}: debe ofrecer las tres Formas de Anomalía`);
        ok(ruby.includes(":WONDERGUARD"), `${name}: la forma Omega necesita inmunidad extrema`);
      }
      ok(!occupied.has(cell) || true, "");
    }
    ok(mine.length <= PER_MAP + 1, `mapa ${mapId}: demasiadas manifestaciones (${mine.length})`);
    for (const object of mine) {
      const cell = `${iv(object, "@x")},${iv(object, "@y")}`;
      const others = mine.filter((other) => other !== object).map((other) => `${iv(other, "@x")},${iv(other, "@y")}`);
      ok(!others.includes(cell), `mapa ${mapId}: dos manifestaciones en ${cell}`);
    }
  }
  const expected = installed.length + (installed.length ? 1 : 0);
  ok(eventCount === expected, `se esperaban ${expected} eventos Pokégod y hay ${eventCount}`);
  ok(!STRICT || pending.length === 0, `pendientes de arte: ${pending.join(", ")}`);

  if (errors.length) throw new Error(`Pokégods inválidos (${errors.length}):\n- ${errors.filter(Boolean).join("\n- ")}`);
  console.log(`Verificación OK: ${installed.length} Pokégods registrados (especies, gritos, sprites), ` +
    `${eventCount} eventos en la Isla Espejo con tres Formas de Anomalía y retorno libre.` +
    (pending.length ? ` Pendientes de arte: ${pending.join(", ")}.` : ""));
}

const { ready, pending } = readySpecies();
if (pending.length) {
  console.log(`Aviso: ${pending.length} Pokégods sin sprites completos (${pending.join(", ")}). ` +
    `No se registran todavía: genera el arte y ejecuta tools/build_pokegods_sprites.mjs.`);
}
const installed = VERIFY_ONLY ? [] : installSpecies(ready);
if (!VERIFY_ONLY) {
  installCries(installed);
  installIsland(installed);
  console.log(`Instalados ${installed.length} Pokégods en species.dat y en la Isla Espejo. Backup: ${path.relative(ROOT, BACKUP)}`);
}
verify(VERIFY_ONLY ? speciesEntries() : installed, pending);

/** En modo verificación, reconstruye las especies ya instaladas desde el catálogo. */
function speciesEntries() {
  const { bySymbol } = speciesRegistry();
  const found = [];
  for (const entry of CATALOG.roster) {
    const object = bySymbol.get(entry.id);
    if (!object) continue;
    if (!spriteFiles(entry.id).every((file) => fs.existsSync(file))) continue;
    found.push({ entry, idNumber: Number(iv(object, "@id_number")) });
  }
  return found;
}#!/usr/bin/env node
/**
 * apply_restauracion_cromatica.mjs
 *
 * «Los mundos de creepypasta son fieles a sus creepypastas, pero Ash es el
 * agente externo que busca salvar las dimensiones y restaurarlas a un momento
 * de paz restaurando su color.»
 *
 * Lo que hace esta herramienta:
 *
 *   1. **Migración de sellos.** Los sellos de las siete emisiones vivían en
 *      868–875 y eso chocaba con el canon de Arceus: 873 es «duelo resuelto» y
 *      874 es «Arceus capturado», así que purgar la sexta o la séptima emisión
 *      abría en falso todas las puertas del canon. Se trasladan a 940–947,
 *      bloque comprobadamente libre (el juego no pasa de 939).
 *   2. **Ceniza.** Cada emisión se muestra en gris mientras no está restaurada.
 *      Un proceso paralelo que se autoborra fija el tono al entrar en el mapa:
 *      gris si el mundo sigue roto, color si ya volvió a su tarde. También
 *      corrige el caso de guardar y recargar dentro de un mundo gris.
 *   3. **Nexo de Color.** Derrotar al jefe *purga* la emisión; no la salva.
 *      Después hay que volver y tocar el nexo: Ash habla como lo que es —alguien
 *      que viene de fuera de estas dimensiones— y le devuelve su momento de paz.
 *   4. **Pobladores.** Un vecino por emisión queda visible; la segunda voz
 *      permanece grabada en el Nexo y conserva sus dos versiones de diálogo.
 *      Así se mantiene la historia sin superar tres personajes visibles por
 *      mapa. Cada mundo es fiel a su creepypasta: la torre, la partida sin
 *      guardar, la fosa, la cinta, la ciudad fallida, el eco y el cartucho de 1996.
 *   5. **Salida limpia.** Las dos salidas de cada emisión devuelven la pantalla
 *      al color antes de transferir, para que el gris no se escape al mundo.
 *   6. **Censo Cromático** en la falda del Monte Silver: lleva la cuenta de los
 *      mundos restaurados y cierra el arco cuando son los siete.
 *
 * No se toca contenido original: sólo se añaden eventos en mapas del DLC y se
 * reescriben los sellos que ya estaban declarados.
 *
 * Uso:
 *   node tools/apply_restauracion_cromatica.mjs
 *   node tools/apply_restauracion_cromatica.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import {
  DATA, ROOT, cmdOf, condition, endBranch, endEvent, eraseEvent, event, eventsOf,
  freeCells, graphic, ifSwitch, ifVariable, iv, makeChecker, marshalDump, page,
  pagesOf, readMapRaw, selfSwitch, spread, switchOn, texts, tint, upsert, varAdd,
  wait, writeMapRaw, txt,
} from "./lib/dlc_helpers.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "restauracion_cromatica.json"), "utf8"));
const SELLO_BASE = PLAN.interruptores.SELLO_BASE;      // 940
const COLOR_BASE = PLAN.interruptores.COLOR_BASE;      // 950
const PAZ_TOTAL = PLAN.interruptores.PAZ_TOTAL;        // 957
const RESTAURADOS = PLAN.variables.MUNDOS_RESTAURADOS; // 310
const MARKER = "PokeMod Restauración:";
const BOSS_MARKER = "PokeMod Multiverso: Jefe";
const BACKUP_DIR = "restauracion_cromatica";

/** El bloque viejo chocaba con el canon de Arceus (873 = duelo, 874 = captura). */
const SELLOS_VIEJOS = [868, 869, 870, 871, 872, 873, 874, 875];
const SELLOS_NUEVOS = [940, 941, 942, 943, 944, 945, 946, 947];

const GRIS = [-30, -30, -30, 255];
const NORMAL = [0, 0, 0, 0];
const TOTAL_MUNDOS = PLAN.mundos.length;

function backupFile(file) {
  const dir = path.join(DATA, "..", "PokeModBackups", BACKUP_DIR);
  fs.mkdirSync(dir, { recursive: true });
  const source = path.join(DATA, file);
  if (fs.existsSync(source)) fs.copyFileSync(source, path.join(dir, file));
}

/* ─────────────────────── 1. migración de los sellos ─────────────────────── */

function migrateSeals() {
  const moved = [];
  const files = fs.readdirSync(DATA).filter((f) => /^Map\d+\.rxdata$/.test(f));
  for (const file of files) {
    const mapId = Number(file.match(/\d+/)[0]);
    const map = readMapRaw(mapId);
    const pairs = iv(map, "@events")?.pairs ?? [];
    let touched = false;
    for (const [, object] of pairs) {
      if (!txt(iv(object, "@name")).startsWith(BOSS_MARKER)) continue;
      for (const pageObj of iv(object, "@pages") ?? []) {
        for (const raw of pageObj.getIvar("@list") ?? []) {
          const c = cmdOf(raw);
          if (c.code !== 121) continue;
          const index = SELLOS_VIEJOS.indexOf(Number(c.params[0]));
          if (index < 0) continue;
          const nuevo = SELLOS_NUEVOS[index];
          raw.setIvar("@parameters", [nuevo, nuevo, c.params[2]]);
          touched = true;
        }
      }
      if (touched) moved.push(mapId);
    }
    if (touched) { backupFile(file); writeMapRaw(mapId, map); }
  }
  return moved;
}

/* ─────────────────── 2. salida limpia (que el gris no escape) ───────────── */

/**
 *Inserta un teñido a color normal justo antes de cada transferencia.
 * Idempotente: si ya hay un teñido delante, no hace nada.
 */
function ensureTintBeforeTransfer(mapId, names) {
  let changed = 0;
  if (!fs.existsSync(path.join(DATA, `Map${String(mapId).padStart(3, "0")}.rxdata`))) return changed;
  backupFile(`Map${String(mapId).padStart(3, "0")}.rxdata`);
  const map = readMapRaw(mapId);
  const pairs = iv(map, "@events")?.pairs ?? [];
  for (const [, object] of pairs) {
    const name = txt(iv(object, "@name"));
    if (!names.some((n) => name.startsWith(n))) continue;
    for (const pageObj of iv(object, "@pages") ?? []) {
      const list = pageObj.getIvar("@list") ?? [];
      // Se recorre al revés para no descolocar los índices al insertar.
      for (let i = list.length - 1; i >= 0; i--) {
        if (cmdOf(list[i]).code !== 201) continue;
        const prev = i > 0 ? cmdOf(list[i - 1]) : null;
        if (prev && prev.code === 223) continue;
        list.splice(i, 0, tint(...NORMAL, 6, 0), wait(8, 0));
        changed += 1;
      }
      pageObj.setIvar("@list", list);
    }
  }
  if (changed) writeMapRaw(mapId, map);
  return changed;
}

/* ─────────────────────────── 3. la ceniza ───────────────────────────────── */

/**
 * Proceso paralelo que se autoborra: fija el tono de la emisión una sola vez
 * por visita. Gris si el mundo sigue roto; color si ya se restauró. Así el
 * gris no depende de por qué puerta se entró ni de que se guarde y se cargue.
 */
function cenizaEvent(id, colorSwitch) {
  return event(id, `${MARKER} Ceniza`, 0, 0, [
    page({
      trigger: 4,
      gfx: graphic("", 2, 1, {}),
      list: [
        wait(12),
        ifSwitch(colorSwitch, false),
        tint(...GRIS, 30, 1),
        endBranch(),
        ifSwitch(colorSwitch, true),
        tint(...NORMAL, 30, 1),
        endBranch(),
        eraseEvent(),
        endEvent(),
      ],
    }),
  ]);
}

/* ─────────────────────────── 4. el nexo ─────────────────────────────────── */

function nexoEvent(id, mundo, cell) {
  const sello = SELLO_BASE + mundo.zona;
  const color = COLOR_BASE + mundo.zona;
  const eco = mundo.pobladores[1];
  const vozEcoGris = eco ? [...texts([`El nexo conserva la voz de ${eco.nombre}:`]), ...texts([eco.gris])] : [];
  const vozEcoColor = eco ? [...texts([`El nexo devuelve la voz de ${eco.nombre}, ya en paz:`]), ...texts([eco.color])] : [];
  const restaurar = [
    ...texts(mundo.nexo.antes),
    ...vozEcoGris,
    ...texts(mundo.nexo.ash),
    wait(12),
    tint(...NORMAL, 60),
    wait(66),
    ...texts(mundo.nexo.despues),
    ...texts([mundo.nexo.paz]),
    switchOn(color),
    varAdd(RESTAURADOS, 1),
    ifVariable(RESTAURADOS, TOTAL_MUNDOS, 1),
    switchOn(PAZ_TOTAL, 1),
    ...texts(PLAN.pazTotal.lineas, 1),
    endBranch(1),
    endEvent(),
  ];
  return event(id, `${MARKER} Nexo — ${mundo.titulo}`, cell[0], cell[1], [
    // Sin purgar: el mundo sigue en pie y el color no se puede desatar.
    page({
      gfx: graphic("Object ball special", 2, 1, {}),
      list: [
        ...texts([
          `El color se escapó de este sitio. Alguien lo sigue sosteniendo: ${mundo.nexo.objeto}.`,
          "Mientras la emisión siga en pie, el gris no se puede desatar.",
        ]),
        ...vozEcoGris,
        endEvent(),
      ],
    }),
    // Purgado pero no salvado: Ash, que viene de fuera, devuelve el color.
    page({
      cond: condition({ sw: sello, sw2: color }),
      gfx: graphic("Object ball special", 2, 1, {}),
      list: restaurar,
    }),
    // Restaurado: el color se sostiene solo.
    page({
      cond: condition({ sw: color }),
      gfx: graphic("Object ball special", 2, 1, {}),
      list: [
        ...texts([
          `${mundo.nexo.objeto.charAt(0).toUpperCase()}${mundo.nexo.objeto.slice(1)} ya no pesa.`,
          "El color se sostiene solo. Este mundo ha vuelto a su tarde.",
        ]),
        ...vozEcoColor,
        endEvent(),
      ],
    }),
  ]);
}

/* ───────────────────────── 5. los pobladores ────────────────────────────── */

function pobladorEvent(id, mundo, pob, cell) {
  const color = COLOR_BASE + mundo.zona;
  return event(id, `${MARKER} ${pob.nombre}`, cell[0], cell[1], [
    page({
      gfx: graphic(pob.sprite, 2, 1, {}),
      list: [...texts([pob.gris]), endEvent()],
    }),
    page({
      cond: condition({ sw: color }),
      gfx: graphic(pob.sprite, 2, 1, {}),
      list: [...texts([pob.color]), endEvent()],
    }),
  ]);
}

/* ──────────────────────── 6. censo y registro ───────────────────────────── */

function censoEvent(id, cell) {
  return event(id, `${MARKER} Censo Cromático`, cell[0], cell[1], [
    page({
      gfx: graphic("trchar028", 2, 1, {}),
      list: [
        ...texts([
          `Censo Cromático: \\v[${RESTAURADOS}] de ${TOTAL_MUNDOS} emisiones han recuperado su color.`,
          "Purgarlas las cierra. Restaurarlas las salva. Son dos cosas distintas y sólo una deja el sitio habitable.",
          "Vuelve a cada emisión y toca su nexo. Yo me quedo a contarlas.",
        ]),
        endEvent(),
      ],
    }),
    page({
      cond: condition({ sw: PAZ_TOTAL }),
      gfx: graphic("trchar028", 2, 1, {}),
      list: [
        ...texts([
          `Las ${TOTAL_MUNDOS} emisiones están en paz. Ni una sola repite su trauma.`,
          "Cuando el Archivero escribió estas historias creyó que no tenían final.",
          "Se equivocaba: los finales los traéis vosotros de fuera.",
        ]),
        endEvent(),
      ],
    }),
  ]);
}

function registroEvent(id, cell) {
  return event(id, `${MARKER} Registro del Agente`, cell[0], cell[1], [
    page({
      gfx: graphic(PLAN.registroAgente.sprite, 2, 1, {}),
      list: [...texts(PLAN.registroAgente.lineas), endEvent()],
    }),
  ]);
}

/* ──────────────────────────── instalación ───────────────────────────────── */

function installWorld(mundo) {
  const color = COLOR_BASE + mundo.zona;
  const solids = spread(freeCells(mundo.mapId), 2);
  return upsert(mundo.mapId, [MARKER], (nextId) => [
    cenizaEvent(nextId, color),
    nexoEvent(nextId + 1, mundo, solids[0]),
    pobladorEvent(nextId + 2, mundo, mundo.pobladores[0], solids[1]),
  ], BACKUP_DIR);
}

function installCenso() {
  const mapId = PLAN.censo.mapa;
  return upsert(mapId, [`${MARKER} Censo`, `${MARKER} Registro`], (nextId) => {
    const cells = spread(freeCells(mapId), 2);
    return [censoEvent(nextId, cells[0]), registroEvent(nextId + 1, cells[1])];
  }, BACKUP_DIR);
}

function install() {
  const moved = migrateSeals();
  const placed = [];
  let salidas = 0;
  for (const mundo of PLAN.mundos) {
    const added = installWorld(mundo);
    salidas += ensureTintBeforeTransfer(mundo.mapId, [
      "PokeMod Multiverso: Volver a la gruta",
      "PokeMod Grieta: Volver al mundo",
    ]);
    placed.push({ mapId: mundo.mapId, titulo: mundo.titulo, eventos: added.length });
  }
  const censo = installCenso();
  return { moved, placed, censo, salidas };
}

/* ──────────────────────────── verificación ──────────────────────────────── */

function verify() {
  const check = makeChecker("Restauración cromática");
  let sellosMigrados = 0;

  for (const mundo of PLAN.mundos) {
    const sello = SELLO_BASE + mundo.zona;
    const color = COLOR_BASE + mundo.zona;

    // — el jefe escribe el sello nuevo y ninguno del bloque viejo
    const boss = eventsOf(mundo.mapId).find((e) => e.name.startsWith(BOSS_MARKER));
    check.ok(!!boss, `${mundo.mapId}: falta el evento del jefe`);
    if (boss) {
      let escribeSello = false, usaViejo = false;
      for (const pg of pagesOf(boss)) for (const c of pg.list) {
        if (c.code !== 121) continue;
        if (Number(c.params[0]) === sello) escribeSello = true;
        if (SELLOS_VIEJOS.includes(Number(c.params[0]))) usaViejo = true;
      }
      check.ok(escribeSello, `${mundo.mapId}: el jefe no enciende el sello ${sello}`);
      check.ok(!usaViejo, `${mundo.mapId}: el jefe sigue usando un sello del bloque 868-875`);
      if (escribeSello) sellosMigrados += 1;
    }

    // — ceniza: un proceso paralelo que tiñe gris o color y se autoborra
    const ceniza = eventsOf(mundo.mapId).find((e) => e.name === `${MARKER} Ceniza`);
    check.ok(!!ceniza, `${mundo.mapId}: falta la ceniza`);
    if (ceniza) {
      const pages = pagesOf(ceniza);
      check.ok(pages.length === 1 && pages[0].trigger === 4,
        `${mundo.mapId}: la ceniza debe ser un único proceso paralelo`);
      const comandos = pages[0].list;
      const tonos = comandos.filter((c) => c.code === 223);
      check.ok(tonos.length === 2, `${mundo.mapId}: la ceniza debe tener los dos teñidos (gris y color)`);
      check.ok(comandos.some((c) => c.code === 126), `${mundo.mapId}: la ceniza debe autoborrarse tras teñir`);
      check.ok(comandos.some((c) => c.code === 111 && Number(c.params[1]) === color),
        `${mundo.mapId}: la ceniza no consulta el color ${color}`);
    }

    // — nexo: tres páginas; la central exige sello y se cierra con el color
    const nexo = eventsOf(mundo.mapId).find((e) => e.name === `${MARKER} Nexo — ${mundo.titulo}`);
    check.ok(!!nexo, `${mundo.mapId}: falta el nexo de color`);
    if (nexo) {
      const pages = pagesOf(nexo);
      check.ok(pages.length === 3, `${mundo.mapId}: el nexo debe tener tres páginas`);
      const media = pages[1];
      const sw1ok = !!media.condition?.getIvar("@switch1_valid");
      const sw2ok = !!media.condition?.getIvar("@switch2_valid");
      const sw1 = Number(media.condition?.getIvar("@switch1_id"));
      const sw2 = Number(media.condition?.getIvar("@switch2_id"));
      check.ok(sw1ok && sw1 === sello, `${mundo.mapId}: la restauración no exige el sello ${sello}`);
      check.ok(sw2ok && sw2 === color, `${mundo.mapId}: la restauración no se cierra con el color ${color}`);
      check.ok(media.list.some((c) => c.code === 121 && Number(c.params[0]) === color),
        `${mundo.mapId}: la restauración no enciende el color ${color}`);
      check.ok(media.list.some((c) => c.code === 122 && Number(c.params[1]) === RESTAURADOS),
        `${mundo.mapId}: la restauración no lleva la cuenta de mundos`);
      check.ok(media.list.some((c) => c.code === 223), `${mundo.mapId}: la restauración no tiñe la pantalla`);
    }

    // — un poblador visible; la segunda voz se conserva en el Nexo sin sumar otro personaje
    const visibles = eventsOf(mundo.mapId).filter((e) => e.name === `${MARKER} ${mundo.pobladores[0].nombre}`);
    const segundaPersona = eventsOf(mundo.mapId).some((e) => e.name === `${MARKER} ${mundo.pobladores[1].nombre}`);
    check.ok(visibles.length === 1, `${mundo.mapId}: debe haber un poblador visible y hay ${visibles.length}`);
    check.ok(!segundaPersona, `${mundo.mapId}: la segunda voz sigue instalada como personaje separado`);
    for (const pob of mundo.pobladores) {
      check.ok(pob.gris !== pob.color, `${mundo.mapId}: ${pob.nombre} repite el mismo texto en gris y en color`);
    }
    const textoNexo = nexo ? pagesOf(nexo).flatMap((p) => p.list)
      .filter((c) => c.code === 401).map((c) => txt(c.params[0])).join("\\n") : "";
    check.ok(textoNexo.includes(mundo.pobladores[1].gris) && textoNexo.includes(mundo.pobladores[1].color),
      `${mundo.mapId}: el Nexo no conserva las dos versiones de la voz registrada`);

    // — las salidas devuelven el color antes de transferir
    for (const e of eventsOf(mundo.mapId)) {
      if (!/Volver a la gruta|Volver al mundo/.test(e.name)) continue;
      let limpia = true;
      for (const p of pagesOf(e)) {
        const comandos = p.list;
        for (let i = 0; i < comandos.length; i++) {
          if (comandos[i].code !== 201) continue;
          const prev = i > 0 ? comandos[i - 1] : null;
          const prev2 = i > 1 ? comandos[i - 2] : null;
          if (!((prev && prev.code === 106) || (prev2 && prev2.code === 223))) limpia = false;
        }
      }
      check.ok(limpia, `${mundo.mapId}: la salida «${e.name}» no limpia el gris antes de transferir`);
    }
  }

  // — censo y registro en la falda
  const censo = eventsOf(PLAN.censo.mapa).filter((e) => e.name.startsWith(MARKER));
  check.ok(censo.length === 2, `la falda debe tener censo y registro (hay ${censo.length})`);

  // — invariante real: el bloque 868-875 seguía siendo el de los sellos de las
  //   emisiones, y 873/874 son «duelo de Arceus resuelto» y «Arceus capturado».
  //   Ningún jefe de emisión puede tocarlos ya; sólo el encuentro de Arceus
  //   puede escribir el 873, y nadie fuera de él puede escribir el 874.
  const files = fs.readdirSync(DATA).filter((f) => /^Map\d+\.rxdata$/.test(f));
  let choques = 0;
  for (const f of files) {
    const id = Number(f.match(/\d+/)[0]);
    for (const e of eventsOf(id)) {
      const esArceus = /Arceus/i.test(e.name);
      const esJefe = e.name.startsWith(BOSS_MARKER);
      for (const p of pagesOf(e)) for (const comando of p.list) {
        if (comando.code !== 121) continue;
        const desde = Number(comando.params[0]), hasta = Number(comando.params[1] ?? desde);
        for (let s = desde; s <= hasta; s++) {
          if (esJefe && SELLOS_VIEJOS.includes(s)) choques += 1;              // sello viejo
          if (!esArceus && (s === 873 || s === 874)) choques += 1;           // canon de Arceus
        }
      }
    }
  }
  check.ok(choques === 0, `quedan ${choques} escrituras que chocan con el canon de Arceus (bloque 868-875)`);
  check.ok(sellosMigrados === TOTAL_MUNDOS, `se migraron ${sellosMigrados} de ${TOTAL_MUNDOS} sellos`);

  check.done();
}

/* ──────────────────────────────── main ──────────────────────────────────── */

if (VERIFY_ONLY) {
  verify();
} else {
  const result = install();
  console.log(`✔ Restauración cromática instalada en ${TOTAL_MUNDOS} emisiones`);
  console.log(`  · sellos migrados al bloque ${SELLO_BASE}-${SELLO_BASE + 7}: ${result.moved.length} jefes`);
  for (const mundo of result.placed) {
    console.log(`  · mapa ${mundo.mapId} «${mundo.titulo}»: ${mundo.eventos} eventos (ceniza, nexo y un poblador visible; segunda voz en el Nexo)`);
  }
  console.log(`  · salidas con tono limpio: ${result.salidas}`);
  console.log(`  · censo cromático y registro del agente en el mapa ${PLAN.censo.mapa}`);
  verify();
}#!/usr/bin/env node
/**
 * apply_rocket_disfraz.mjs
 *
 * P6 · «Team Rocket = infiltración industrial: tuberías, luces rojas de alarma,
 * Ash con un disfraz del Team Rocket.»
 *
 * Este instalador monta las tres piezas que faltaban para que la dimensión del
 * Team Rocket se *juegue* como una infiltración y no como una visita guiada:
 *
 *   · **El disfraz.** metadata.dat gana una entrada de jugador nueva
 *     (`@player_D`, id 3) con el tipo de entrenador TEAMROCKET_M y el charset
 *     `trainer_TEAMROCKET_M`. `pbChangePlayer(3)` cambia a la vez la música y
 *     el sprite de combate (porque cambia el trainer type) y el charset del
 *     mundo. No se toca ni player_A ni player_B: es una entrada que estaba
 *     vacía, y el instalador se niega a escribir si algo la ocupa.
 *
 *   · **El polvo en suspensión.** La base (2220) y el Núcleo (2221) pasan a un
 *     clon del tileset 3 — el 179 — con la niebla `polvo_rocket`. El tileset 3
 *     original no se modifica, así que ningún mapa del juego base cambia.
 *
 *   · **La gente.** Dos intendentes reparten y recogen el uniforme, y dos
 *     centinelas reaccionan a si Ash lo lleva puesto. La variable 315 guarda
 *     el estado y se nombra en System.rxdata para poder depurarla.
 *
 * Uso:
 *   node tools/apply_rocket_disfraz.mjs
 *   node tools/apply_rocket_disfraz.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { marshalLoad, marshalDump, RSymbol, RString } from "../web/js/marshal.js";
import { parseTileset } from "../web/js/rmxp.js";
import {
  DATA, ROOT, backup, choice, choiceCase, choiceEnd, condition, endEvent, event,
  eventsOf, graphic, makeChecker, page, pagesOf, place, script, texts, tint, varSet, wait,
} from "./lib/dlc_helpers.mjs";
import { clonarTileset } from "./lib/region_builder.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "rocket_disfraz.json"), "utf8"));
const MARK = PLAN.marcador;
const VAR = PLAN.variable;
const JUG = PLAN.jugador;
const DIR = "rocket_disfraz";
const plano = (lista) => lista.flat(Infinity).filter(Boolean);

/* ─────────────────────────── el disfraz ─────────────────────────── */

function instalarJugador() {
  backup(DIR, ["metadata.dat"]);
  const archivo = path.join(DATA, "metadata.dat");
  const datos = marshalLoad(fs.readFileSync(archivo));
  let global = null;
  for (const [clave, valor] of datos.pairs) {
    if ((clave?.name ?? String(clave)) === "0") { global = valor; break; }
  }
  if (!global) throw new Error("metadata.dat no tiene la entrada global (clave 0)");
  // [tipo de entrenador, andar, bici, surf, correr, buceo, pesca, pesca]
  const planeado = [
    new RSymbol(JUG.tipo),
    ...Array.from({ length: 7 }, () => RString.fromText(JUG.charset)),
  ];
  const antes = global.getIvar(JUG.ivan);
  if (antes !== null && antes !== undefined) {
    const esNuestro = Array.isArray(antes) && antes.length === 8
      && antes[0]?.name === JUG.tipo
      && antes.slice(1).every((valor) => textura(valor) === JUG.charset);
    if (!esNuestro) {
      throw new Error(`${JUG.ivan} ya estaba ocupado por contenido que no es de la expansión: no se sobreescribe.`);
    }
  }
  global.setIvar(JUG.ivan, planeado);
  fs.writeFileSync(archivo, Buffer.from(marshalDump(datos)));
}

function instalarNombreVariable() {
  backup(DIR, ["System.rxdata"]);
  const archivo = path.join(DATA, "System.rxdata");
  const sistema = marshalLoad(fs.readFileSync(archivo));
  const variables = sistema.getIvar("@variables");
  if (!variables) throw new Error("System.rxdata no tiene @variables");
  while (variables.length < VAR) variables.push(RString.fromText(""));
  variables[VAR - 1] = RString.fromText(PLAN.nombreVariable);
  fs.writeFileSync(archivo, Buffer.from(marshalDump(sistema)));
}

/* ─────────────────── la niebla de polvo industrial ─────────────────── */

function instalarNiebla() {
  const niebla = PLAN.niebla;
  const copia = clonarTileset(niebla.origen, niebla.nuevo, {
    nombre: {},
    niebla: {
      nombre: niebla.nombre,
      opacidad: niebla.opacidad,
      zoom: niebla.zoom,
      sx: niebla.sx,
      sy: niebla.sy,
      hue: 0,
      mezcla: 0,
    },
    dirName: DIR,
  });
  for (const mapId of niebla.mapas) {
    const nombre = `Map${String(mapId).padStart(3, "0")}.rxdata`;
    backup(DIR, [nombre]);
    const archivo = path.join(DATA, nombre);
    const mapa = marshalLoad(fs.readFileSync(archivo));
    mapa.setIvar("@tileset_id", niebla.nuevo);
    fs.writeFileSync(archivo, Buffer.from(marshalDump(mapa)));
  }
  return copia;
}

/* ───────────────────────────── los eventos ───────────────────────────── */

/** Fundido corto: Ash tarda lo suyo en cambiarse de ropa. */
const cuello = (dentro) => [
  tint(-255, -255, -255, 0, 6, 0),
  wait(8, 0),
  ...plano(dentro(0)),
  tint(0, 0, 0, 0, 6, 0),
];

/**
 * Las dos páginas del intendente. RPG XP elige la última página cuya condición
 * se cumple, así que la de «sin uniforme» va primero y la de «con uniforme»
 * después: en cuanto la variable vale 1, gana la segunda.
 */
function paginasIntendente(charset, extra) {
  const T = { ...PLAN.textos, ...(extra ?? {}) };
  return [
    page({
      cond: condition({ variable: [VAR, 0] }),
      gfx: graphic(charset),
      trigger: 0,
      list: [
        ...texts(T.ponerse, 0),
        choice(["Ponértelo", "Dejarlo donde está"], 0),
        choiceCase(0, "Ponértelo", 0),
        ...cuello(() => [
          texts(T.puesto, 1),
          script(`pbChangePlayer(${JUG.id})`, 1),
          varSet(VAR, 1, 1),
        ]),
        choiceCase(1, "Dejarlo donde está", 0),
        ...texts(T.rechazo, 1),
        choiceEnd(0),
        endEvent(0),
      ],
    }),
    page({
      cond: condition({ variable: [VAR, 1] }),
      gfx: graphic(charset),
      trigger: 0,
      list: [
        ...texts(T.yaPuesto, 0),
        choice(["Volver a tu ropa", "Seguir de uniforme"], 0),
        choiceCase(0, "Volver a tu ropa", 0),
        ...cuello(() => [
          texts(T.quitarse, 1),
          script("pbChangePlayer(0)", 1),
          varSet(VAR, 0, 1),
        ]),
        choiceCase(1, "Seguir de uniforme", 0),
        ...texts(T.seguirPuesto, 1),
        choiceEnd(0),
        endEvent(0),
      ],
    }),
  ];
}

function instalarIntendentes() {
  const hechos = [];
  for (const intendente of PLAN.intendentes) {
    const celda = place(
      intendente.mapa,
      [`${MARK}${intendente.nombre}`],
      intendente.pista,
      ([x, y], nextId) => event(
        nextId,
        `${MARK}${intendente.nombre}`,
        x,
        y,
        paginasIntendente(intendente.charset, PLAN.textos[intendente.textos]),
      ),
      DIR,
    );
    hechos.push({ mapa: intendente.mapa, nombre: intendente.nombre, celda });
  }
  return hechos;
}

function instalarCentinelas() {
  const hechos = [];
  for (const centinela of PLAN.centinelas) {
    const celda = place(
      centinela.mapa,
      [`${MARK}${centinela.nombre}`],
      [4, 4],
      ([x, y], nextId) => event(nextId, `${MARK}${centinela.nombre}`, x, y, [
        // Sin uniforme (sin condición): la base.
        page({
          cond: condition(),
          gfx: graphic(centinela.charset),
          trigger: 0,
          list: [...texts(centinela.sinDisfraz, 0), endEvent(0)],
        }),
        // Con uniforme: gana cuando la variable vale 1.
        page({
          cond: condition({ variable: [VAR, 1] }),
          gfx: graphic(centinela.charset),
          trigger: 0,
          list: [...texts(centinela.conDisfraz, 0), endEvent(0)],
        }),
      ]),
      DIR,
    );
    hechos.push({ mapa: centinela.mapa, nombre: centinela.nombre, celda });
  }
  return hechos;
}

/* ──────────────────────────── verificación ──────────────────────────── */

function entradaGlobal(datos) {
  for (const [clave, valor] of datos.pairs) {
    if ((clave?.name ?? String(clave)) === "0") return valor;
  }
  return null;
}
const textura = (valor) => String(valor?.text ?? valor ?? "");

function recogerNombres(valor, destino, profundidad = 0) {
  if (!valor || profundidad > 8) return;
  if (Array.isArray(valor)) { valor.forEach((x) => recogerNombres(x, destino, profundidad + 1)); return; }
  if (valor.pairs) {
    valor.pairs.forEach(([clave, v]) => {
      if (clave?.name) destino.add(clave.name);
      recogerNombres(v, destino, profundidad + 1);
    });
  }
}

function verificar() {
  const check = makeChecker("Disfraz del Team Rocket");

  // 1. La entrada de jugador nueva, intacta y completa.
  const datos = marshalLoad(fs.readFileSync(path.join(DATA, "metadata.dat")));
  const global = entradaGlobal(datos);
  check.ok(!!global, "metadata.dat no tiene la entrada global (clave 0)");
  const jugador = global?.getIvar(JUG.ivan);
  check.ok(Array.isArray(jugador) && jugador.length === 8,
    `metadata.dat no tiene ${JUG.ivan} con las 8 posiciones`);
  if (Array.isArray(jugador)) {
    check.ok(jugador[0]?.name === JUG.tipo,
      `${JUG.ivan}[0] debería ser :${JUG.tipo} y es ${jugador[0]?.name}`);
    for (let i = 1; i < 8; i++) {
      check.ok(textura(jugador[i]) === JUG.charset, `${JUG.ivan}[${i}] debería ser ${JUG.charset}`);
    }
  }
  // 2. El contenido original no se ha tocado.
  check.ok(global?.getIvar("@player_A")?.[0]?.name === "POKEMONTRAINER_Red",
    "@player_A ha cambiado: eso es contenido original");
  check.ok(!!global?.getIvar("@player_B"), "@player_B ha desaparecido");

  // 3. Existen el charset y el tipo de entrenador.
  const charset = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Characters", `${JUG.charset}.png`);
  check.ok(fs.existsSync(charset), `no existe el charset Graphics/Characters/${JUG.charset}.png`);
  const tipos = new Set();
  recogerNombres(marshalLoad(fs.readFileSync(path.join(DATA, "trainer_types.dat"))), tipos);
  check.ok(tipos.has(JUG.tipo), `no existe el tipo de entrenador :${JUG.tipo}`);

  // 4. La variable está nombrada.
  const sistema = marshalLoad(fs.readFileSync(path.join(DATA, "System.rxdata")));
  const variables = sistema.getIvar("@variables") ?? [];
  check.ok(textura(variables[VAR - 1]) === PLAN.nombreVariable,
    `la variable ${VAR} no se llama ${PLAN.nombreVariable}`);

  // 5. La niebla industrial: el clon la tiene, el original no.
  const bruto = marshalLoad(fs.readFileSync(path.join(DATA, "Tilesets.rxdata")));
  const ts = [...bruto].map((fila) => (fila ? parseTileset(fila) : null));
  const clon = ts[PLAN.niebla.nuevo];
  check.ok(!!clon, `no existe el tileset ${PLAN.niebla.nuevo}`);
  if (clon) {
    check.ok(clon.tilesetName === ts[PLAN.niebla.origen]?.tilesetName,
      `el tileset ${PLAN.niebla.nuevo} no usa el gráfico del ${PLAN.niebla.origen}`);
    check.ok(textura(clon.obj.getIvar("@fog_name")) === PLAN.niebla.nombre,
      `el tileset ${PLAN.niebla.nuevo} no tiene la niebla ${PLAN.niebla.nombre}`);
    check.ok(Number(clon.obj.getIvar("@fog_opacity")) === PLAN.niebla.opacidad,
      "la opacidad de la niebla industrial no coincide");
  }
  check.ok(textura(ts[PLAN.niebla.origen]?.obj.getIvar("@fog_name")) === "",
    "¡el tileset original ha cogido niebla! Eso tocaría contenido del juego base");
  for (const mapId of PLAN.niebla.mapas) {
    const mapa = marshalLoad(fs.readFileSync(path.join(DATA, `Map${String(mapId).padStart(3, "0")}.rxdata`)));
    check.ok(Number(mapa.getIvar("@tileset_id")) === PLAN.niebla.nuevo,
      `Map${mapId} no usa el tileset ${PLAN.niebla.nuevo}`);
  }

  // 6. Los intendentes: dos páginas, las dos con cambio de jugador, una vuelve.
  for (const intendente of PLAN.intendentes) {
    const encontrados = eventsOf(intendente.mapa).filter((ev) => ev.name === `${MARK}${intendente.nombre}`);
    check.ok(encontrados.length === 1,
      `Map${intendente.mapa}: se esperaba 1 «${intendente.nombre}» y hay ${encontrados.length}`);
    if (encontrados.length !== 1) continue;
    const paginas = pagesOf(encontrados[0]);
    check.ok(paginas.length === 2, `${intendente.nombre} debería tener 2 páginas y tiene ${paginas.length}`);
    const conScript = paginas.filter((p) => p.list.some((c) => Number(c.code) === 355));
    check.ok(conScript.length === 2, `${intendente.nombre}: las 2 páginas deben llamar a pbChangePlayer`);
    const ponerse = paginas.some((p) => p.list.some((c) => Number(c.code) === 355
      && new RegExp(`pbChangePlayer\\(${JUG.id}\\)`).test(textura(c.params?.[0]))));
    const volver = paginas.some((p) => p.list.some((c) => Number(c.code) === 355
      && /pbChangePlayer\(0\)/.test(textura(c.params?.[0]))));
    check.ok(ponerse, `${intendente.nombre}: ninguna página pone el uniforme`);
    check.ok(volver, `${intendente.nombre}: ninguna página devuelve a Ash a su ropa`);
  }

  // 7. Los centinelas: dos páginas con texto distinto según el uniforme.
  for (const centinela of PLAN.centinelas) {
    const encontrados = eventsOf(centinela.mapa).filter((ev) => ev.name === `${MARK}${centinela.nombre}`);
    check.ok(encontrados.length === 1,
      `Map${centinela.mapa}: se esperaba 1 «${centinela.nombre}» y hay ${encontrados.length}`);
    if (encontrados.length !== 1) continue;
    const paginas = pagesOf(encontrados[0]);
    check.ok(paginas.length === 2, `${centinela.nombre} debería tener 2 páginas y tiene ${paginas.length}`);
    const [base, uniformado] = paginas;
    check.ok(Number(base.condition?.getIvar("@variable_valid") ?? 1) === 0,
      `${centinela.nombre}: la primera página no debe tener condición`);
    check.ok(Number(uniformado.condition?.getIvar("@variable_id")) === VAR
      && Number(uniformado.condition?.getIvar("@variable_value")) === 1,
      `${centinela.nombre}: la segunda página debe depender de la variable ${VAR} = 1`);
    const lineas = (p) => p.list.filter((c) => Number(c.code) === 401).length;
    check.ok(lineas(base) >= 2 && lineas(uniformado) >= 2,
      `${centinela.nombre}: las dos páginas deberían tener texto`);
  }

  check.done();
  console.log(`✔ Disfraz del Team Rocket: verificación OK (${JUG.ivan}=:${JUG.tipo}/${JUG.charset}, `
    + `variable ${VAR} «${PLAN.nombreVariable}», niebla ${PLAN.niebla.nombre} sobre `
    + `${PLAN.niebla.mapas.length} mapas, ${PLAN.intendentes.length} intendentes, `
    + `${PLAN.centinelas.length} centinelas).`);
}

/* ──────────────────────────────── arranque ──────────────────────────────── */

if (!VERIFY_ONLY) {
  instalarJugador();
  instalarNombreVariable();
  const copia = instalarNiebla();
  const intendentes = instalarIntendentes();
  const centinelas = instalarCentinelas();
  console.log(`  · disfraz: ${JUG.ivan} = :${JUG.tipo} con charset ${JUG.charset}`);
  console.log(`  · variable ${VAR} («${PLAN.nombreVariable}»): 0 = tu ropa, 1 = uniforme`);
  console.log(`  · niebla industrial: tileset ${copia.nuevoId} (${copia.creado ? "creado" : "actualizado"})`
    + ` ← ${PLAN.niebla.origen} en los mapas ${PLAN.niebla.mapas.join(", ")}`);
  for (const hecho of [...intendentes, ...centinelas]) {
    console.log(`  · Map${hecho.mapa}: «${hecho.nombre}» en (${hecho.celda[0]}, ${hecho.celda[1]})`);
  }
  console.log(`  · respaldo en pokemon_fire_ash/PokeModBackups/${DIR}/`);
}
verificar();#!/usr/bin/env node
/**
 * Corrige las rutas de ajustes auxiliares de Fire Ash para PC y Android.
 *
 * Algunas instalaciones no crean la carpeta relativa "Save Files". El juego
 * guardaba allí PokemonSystemSettings.dat antes de guardar la partida y
 * terminaba con Errno::ENOENT. Los dos archivos auxiliares se guardan ahora
 * junto al archivo principal Game.rxdata, cuya carpeta ya conoce SaveData.
 *
 * Uso:
 *   node tools/apply_save_path_fix.mjs
 *   node tools/apply_save_path_fix.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { marshalDump, marshalLoad, RString } from "../web/js/marshal.js";

const ROOT = path.resolve(new URL("..", import.meta.url).pathname);
const FILE = path.join(ROOT, "Scripts_corregido", "Scripts.rxdata");
const VERIFY_ONLY = process.argv.includes("--verify");
const text = (value) => value instanceof RString ? value.text : String(value ?? "");
const inflate = (row) => zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8");
const section = (scripts, name) => scripts.find((row) => text(row[1]) === name);
const setCode = (row, code) => { row[2].bytes = new Uint8Array(zlib.deflateSync(Buffer.from(code, "utf8"))); };

const patches = [
  {
    section: "StartGame",
    old: '  SYSTEM_SETTINGS_FILE = "Save Files/PokemonSystemSettings.dat"   # Added by: kraegon',
    alreadyApplied: (code) => code.includes('SYSTEM_SETTINGS_FILE = File.join(File.dirname(SaveData::FILE_PATH), "PokemonSystemSettings.dat")'),
    replacement: [
      "  # Guarda este ajuste junto a la partida para que funcione también en Android.",
      '  SYSTEM_SETTINGS_FILE = File.join(File.dirname(SaveData::FILE_PATH), "PokemonSystemSettings.dat")',
    ].join("\r\n"),
  },
  {
    section: "BetterFastForward",
    old: 'SPEED_SETTING_FILE = "Save Files/GameSpeedSetting.dat"',
    alreadyApplied: (code) => code.includes('SPEED_SETTING_FILE = File.join(File.dirname(SaveData::FILE_PATH), "GameSpeedSetting.dat")'),
    replacement: [
      "# La carpeta Save Files no existe en algunas instalaciones de Kirin/Android.",
      'SPEED_SETTING_FILE = File.join(File.dirname(SaveData::FILE_PATH), "GameSpeedSetting.dat")',
    ].join("\r\n"),
  },
  {
    section: "StartGame",
    old: [
      "    # Es un ajuste opcional: si el dispositivo no permite crear este archivo,",
      "    # la partida principal debe continuar guardándose con normalidad.",
      "    begin",
      "      save_data($PokemonSystem, SYSTEM_SETTINGS_FILE)",
      "    rescue IOError, SystemCallError",
      "      # Ignorar el ajuste auxiliar en instalaciones Android de solo acceso.",
      "    end",
    ].join("\r\n"),
    alreadyApplied: (code) => !code.includes("save_data($PokemonSystem, SYSTEM_SETTINGS_FILE)") &&
      code.includes("SaveData.save_to_file(save_file)"),
    replacement: [
      "    # PokemonSystemSettings.dat es opcional y algunas instalaciones Android",
      "    # no permiten crear archivos auxiliares junto a la carpeta del juego.",
      "    # La partida principal se guarda abajo mediante SaveData.save_to_file.",
    ].join("\r\n"),
  },
  {
    section: "BetterFastForward",
    old: [
      "def save_speed_setting(speed)",
      "    begin",
      "        save_data(speed, SPEED_SETTING_FILE)",
      "    rescue IOError, SystemCallError",
      "        # El guardado de velocidad no debe interrumpir el juego.",
      "    end",
      "end",
    ].join("\r\n"),
    alreadyApplied: (code) => !code.includes("save_data(speed, SPEED_SETTING_FILE)") &&
      /def save_speed_setting\(speed\)[\s\S]*?end/.test(code),
    replacement: [
      "def save_speed_setting(speed)",
      "    # El ajuste de velocidad es opcional y no se escribe en Android.",
      "end",
    ].join("\r\n"),
  },
];

const scripts = marshalLoad(fs.readFileSync(FILE));
let changed = 0;
for (const patch of patches) {
  const row = section(scripts, patch.section);
  if (!row) throw new Error(`No se encontró la sección ${patch.section}`);
  const code = inflate(row);
  if (code.includes(patch.replacement) || patch.alreadyApplied?.(code)) continue;
  if (!code.includes(patch.old)) throw new Error(`${patch.section}: no se encontró la ruta de ajustes esperada`);
  if (!VERIFY_ONLY) setCode(row, code.replace(patch.old, patch.replacement));
  changed++;
}

if (VERIFY_ONLY) {
  if (changed !== 0) throw new Error("Scripts_corregido/Scripts.rxdata todavía usa la carpeta Save Files");
  console.log("OK: PokemonSystemSettings.dat ya no se escribe como archivo auxiliar");
  console.log("OK: GameSpeedSetting.dat ya no se escribe como archivo auxiliar");
} else {
  fs.writeFileSync(FILE, Buffer.from(marshalDump(scripts)));
  console.log(`Scripts_corregido/Scripts.rxdata actualizado (${changed} rutas de guardado)`);
}#!/usr/bin/env node
/**
 * apply_team_rocket_mision.mjs
 *
 * «Implementa la dimensión del Pokémon Team Rocket para vivir las aventuras,
 * pero siendo Ash un infiltrado, el cual hará las misiones, pero también se
 * encargará de salvaguardar la vida de los lastimados, buscará escalar en
 * puesto para poder controlar esa dimensión y por el bienestar de los que ahí
 * residen.»
 *
 * Lo que construye:
 *
 *   · **Map2220 · Base Subterránea** — seis distritos tomados de interiores
 *     reales del juego, unidos y verificados sin celdas vacías ni aisladas.
 *   · **Map2221 · Núcleo del Mando** — el despacho donde se toma el control.
 *   · **Capitán** en Puerto Horizonte, cerrado hasta el duelo de Arceus, y
 *     **barco de vuelta** disponible siempre.
 *   · **La infiltración**: variable 311 es el rango (0 Recluta → 5 Jefe
 *     Supremo). Cinco misiones encadenadas: cada una sólo se ofrece al rango
 *     que toca y, al cumplirla, asciende. Dos de ellas se resuelven peleando.
 *   · **Los heridos**: tres personas tiradas por la base. Ash puede pararse a
 *     curarlas (variable 313). No puntúa para el ascenso: es lo que hace
 *     cuando nadie le ve, y el juego lo subraya.
 *   · **La toma del mando**: al llegar a Jefe Supremo, el Núcleo se abre y Ash
 *     dicta tres órdenes. Ninguna es de poder: son de bienestar. La dimensión
 *     pasa a cuidar a los suyos.
 *
 * Nada de esto toca contenido original: mapas nuevos, datos nuevos.
 *
 * Uso:
 *   node tools/apply_team_rocket_mision.mjs
 *   node tools/apply_team_rocket_mision.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import {
  DATA, ROOT, choice, choiceCase, choiceEnd, cmd, condition, elseBranch, endBranch, endEvent,
  event, eventsOf, graphic, ifScript, ifVariable, installItems, installMapInfos,
  installMetadata, installTrainerTypes, installTrainers, makeChecker, page, pagesOf,
  script, selfSwitch, spread, switchOn, texts, tint, transfer, upsert, varAdd, varSet,
  wait, txt,
} from "./lib/dlc_helpers.mjs";
import { celdasLibres, componer, publicar, verificarMapa } from "./lib/dimension_builder.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "team_rocket_mision.json"), "utf8"));
const DUELO = PLAN.interruptores.DUELO_RESUELTO;
const ABIERTA = PLAN.interruptores.ROCKET_ABIERTA;
const CONTROL = PLAN.interruptores.ROCKET_CONTROL;
const RANGO = PLAN.variables.RANGO;
const MISIONES = PLAN.variables.MISIONES;
const HERIDOS = PLAN.variables.HERIDOS;
const DIM = PLAN.dimension;
const PUERTO = PLAN.puerto.mapa;
const REGRESO = PLAN.puerto.pista;
const BACKUP = "team_rocket_mision";
const MARKER = "PokeMod Rocket:";
const LLEGADA = [2, 2];
const ULTIMO_RANGO = PLAN.rangos.length - 1;

const plano = (lista) => lista.flat(Infinity).filter(Boolean);
/** «Recuperar» (314): Ash cura a quien se ha parado a socorrer. */
const curar = (indent = 0) => cmd(314, [0], indent);
const viaje = (mapId, x, y, indent = 1) => [
  tint(-255, -255, -255, 0, 6, indent),
  wait(8, indent),
  transfer(mapId, x, y, 2, indent),
  tint(0, 0, 0, 0, 6, indent),
];
function elegir(si, no, ramaSi, ramaNo, indent = 0) {
  return [
    choice([si, no], indent),
    choiceCase(0, si, indent),
    ...plano(ramaSi(indent + 1)),
    choiceCase(1, no, indent),
    ...plano(ramaNo(indent + 1)),
    choiceEnd(indent),
  ];
}

/* ─────────────────────────────── los mapas ──────────────────────────────── */

function construirMapas() {
  const { canvas, pasillos, ventanas } = componer({
    tilesetId: DIM.tileset,
    distritos: DIM.distritos,
    lado: DIM.lado,
    columnas: DIM.columnas,
  });
  publicar(DIM.mapaId, DIM.titulo, canvas, { parentId: DIM.padre });
  // El Núcleo: una sala de mando construida con el mismo compositor, más íntima.
  const nucleo = componer({
    tilesetId: DIM.tileset,
    distritos: DIM.distritos.slice(0, 4),
    lado: DIM.lado,
    columnas: 2,
  });
  publicar(DIM.nucleoId, DIM.tituloNucleo, nucleo.canvas, { parentId: DIM.mapaId });
  return { pasillos, ventanas, ancho: canvas.width, alto: canvas.height };
}

function instalarMapInfosYMetadatos() {
  const specs = [
    { mapId: DIM.mapaId, title: DIM.titulo, parentId: DIM.padre, order: 910 },
    { mapId: DIM.nucleoId, title: DIM.tituloNucleo, parentId: DIM.mapaId, order: 911 },
  ];
  installMapInfos(specs, BACKUP);
  installMetadata(specs.map((s) => ({ mapId: s.mapId, parentId: s.parentId })), BACKUP);
}

/* ─────────────────────────── datos del juego ────────────────────────────── */

function instalarDatos() {
  const tipos = [
    { id: "ROCKET_AGENT", base: "GENTLEMAN", nombre: "Rocket" },
    { id: "ROCKET_BOSS", base: "LEADER_Brock", nombre: "Comandante Rocket" },
    { id: "ROCKET_RIVAL", base: "RIVAL1", nombre: "Rival Rocket" },
  ];
  const entrenadores = [];
  for (const t of PLAN.entrenadores) {
    entrenadores.push({ tipo: "ROCKET_AGENT", nombre: t.nombre, equipo: t.equipo, nivel: 100, derrota: t.frase });
  }
  for (const m of PLAN.misiones) {
    if (!m.batalla) continue;
    entrenadores.push({
      tipo: m.batalla.tipo, nombre: m.batalla.nombre,
      equipo: m.rango >= 4 ? ["PERSIAN", "NIDOKING", "NIDOQUEEN", "DRAPION", "TOXICROAK", "BISHARP"]
        : ["RATICATE", "ZUBAT", "KOFFING", "HOUNDOUR", "MUK", "CROBAT"],
      nivel: 100, derrota: m.hecho[0],
    });
  }
  entrenadores.push({
    tipo: PLAN.rival.tipo, nombre: PLAN.rival.nombre, equipo: PLAN.rival.equipo,
    nivel: PLAN.rival.nivel, derrota: PLAN.rival.derrota,
  });
  const medallas = [{ ...PLAN.medalla, plural: `${PLAN.medalla.nombre}s`, pocket: 8 }];
  return {
    tipos: installTrainerTypes(tipos, BACKUP),
    entrenadores: installTrainers(entrenadores, BACKUP),
    medallas: installItems(medallas, BACKUP),
  };
}

/* ───────────────────────────────── eventos ──────────────────────────────── */

function capitanEvent(cell) {
  return event(0, `${MARKER} Capitán — Team Rocket`, cell[0], cell[1], [
    page({
      gfx: graphic("trchar062", 2, 1, {}),
      list: plano([
        ...texts([
          "Patrón: ¿La dimensión del Sindicato? Existe, y mi barco llega. Pero no lleva a cualquiera.",
          "Patrón: Vuelve cuando hayas cerrado el duelo de la montaña. Antes de eso, allí no hay nada.",
        ]),
        endEvent(),
      ]),
    }),
    page({
      cond: condition({ sw: DUELO }),
      gfx: graphic("trchar062", 2, 1, {}),
      list: plano([
        ...texts([
          "Patrón: Allí dentro nadie entra como visita. Se entra con uniforme o no se entra.",
          "Patrón: Yo sólo llevo y traigo. Lo que hagas con el uniforme es cosa tuya.",
        ]),
        elegir("Zarpar", "Quedarse",
          (i) => [...viaje(DIM.mapaId, LLEGADA[0], LLEGADA[1], i), switchOn(ABIERTA, i)],
          (i) => texts(["Patrón: Como quieras. El barco no se mueve sin ti."], i)),
        endEvent(),
      ]),
    }),
  ]);
}

function eventoSimple(nombre, sprite, lineas, cond = null) {
  return event(0, `${MARKER} ${nombre}`, 0, 0, [
    page({
      cond: cond ?? condition(),
      gfx: graphic(sprite, 2, 1, {}),
      list: plano([...texts(lineas), endEvent()]),
    }),
  ]);
}

function misionEvent(mision, cell) {
  const cuerpo = [
    ...texts(mision.orden),
  ];
  if (mision.batalla) {
    cuerpo.push(
      script(`pbTrainerIntro(:${mision.batalla.tipo})`),
      ifScript(`pbTrainerBattle(:${mision.batalla.tipo},"${mision.batalla.nombre}",nil,false,0,true)`),
      ...texts(mision.hecho, 1),
      varSet(RANGO, mision.rango + 1, 1),
      varAdd(MISIONES, 1, 1),
      ...texts([mision.ascenso], 1),
      selfSwitch("A", 0, 1),
      elseBranch(),
      ...texts(["Has perdido. Vuelve cuando puedas con ello: aquí nadie te echa."], 1),
      endBranch(),
      script("pbTrainerEnd"),
    );
  } else {
    cuerpo.push(
      ...texts(mision.hecho),
      varSet(RANGO, mision.rango + 1),
      varAdd(MISIONES, 1),
      ...texts([mision.ascenso]),
      selfSwitch("A"),
    );
  }
  return event(0, `${MARKER} Misión — ${mision.titulo}`, cell[0], cell[1], [
    // Sin el rango: el encargo todavía no es tuyo.
    page({
      gfx: graphic(mision.sprite, 2, 1, {}),
      list: plano([...texts(["Todavía no tienes rango para este encargo. Sigue haciendo lo que te manden."]), endEvent()]),
    }),
    // Con el rango y sin hacer: la misión.
    page({
      cond: condition({ variable: [RANGO, mision.rango] }),
      gfx: graphic(mision.sprite, 2, 1, {}),
      list: plano([...cuerpo, endEvent()]),
    }),
    // Hecha.
    page({
      cond: condition({ self: "A" }),
      gfx: graphic(mision.sprite, 2, 1, {}),
      list: plano([...texts(["Eso ya está hecho. Ahora te toca lo siguiente."]), endEvent()]),
    }),
  ]);
}

function heridoEvent(herido, cell) {
  return event(0, `${MARKER} Herido — ${herido.nombre}`, cell[0], cell[1], [
    page({
      gfx: graphic(herido.sprite, 2, 1, {}),
      list: plano([
        ...texts([herido.antes]),
        elegir("Socorrer", "Seguir",
          (i) => [
            curar(i),                                            // curar al equipo
            varAdd(HERIDOS, 1, i),
            selfSwitch("A", 0, i),
            ...texts([herido.despues], i),
          ],
          (i) => texts(["Pasas de largo. Nadie te ha visto. Tú sí."], i)),
        endEvent(),
      ]),
    }),
    page({
      cond: condition({ self: "A" }),
      gfx: graphic(herido.sprite, 2, 1, {}),
      list: plano([...texts([herido.despues, "Ya estás mejor. Si te dejan, descansa."]), endEvent()]),
    }),
  ]);
}

function nucleoEvent(cell) {
  return event(0, `${MARKER} Núcleo del Mando`, cell[0], cell[1], [
    // Todavía no se manda.
    page({
      gfx: graphic(PLAN.nucleo.sprite, 2, 1, {}),
      list: plano([...texts(PLAN.nucleo.cerrado), endEvent()]),
    }),
    // Jefe Supremo: toma del mando.
    page({
      cond: condition({ variable: [RANGO, ULTIMO_RANGO] }),
      gfx: graphic(PLAN.nucleo.sprite, 2, 1, {}),
      list: plano([
        ...texts(PLAN.nucleo.toma),
        switchOn(CONTROL),
        script(`pbReceiveItem(:${PLAN.medalla.id})`),
        selfSwitch("A"),
        endEvent(),
      ]),
    }),
    // Ya se mandó.
    page({
      cond: condition({ self: "A" }),
      gfx: graphic(PLAN.nucleo.sprite, 2, 1, {}),
      list: plano([...texts(PLAN.nucleo.despues), endEvent()]),
    }),
  ]);
}

function eventosBase() {
  // barco, puerta del Núcleo, contacto, tablón, enfermería y centinela = 6
  const total = 6 + PLAN.misiones.length + PLAN.heridos.length + PLAN.entrenadores.length;
  const celdas = spread(celdasLibres(DIM.mapaId), total);
  let i = 0;
  const siguiente = () => celdas[i++];

  const eventos = [];
  // Barco de vuelta: sin condiciones.
  const barco = siguiente();
  eventos.push(event(0, `${MARKER} Barco a Puerto Horizonte`, barco[0], barco[1], [
    page({
      gfx: graphic("trchar062", 2, 1, {}),
      list: plano([
        ...texts([PLAN.dimension.barco.saludo, PLAN.dimension.barco.volver]),
        elegir("Volver", "Quedarse",
          (k) => viaje(PUERTO, REGRESO[0], REGRESO[1], k),
          (k) => texts(["Te quedas. El uniforme pesa, pero aguanta."], k)),
        endEvent(),
      ]),
    }),
  ]));

  // Puerta del Núcleo del Mando.
  const puerta = siguiente();
  eventos.push(event(0, `${MARKER} Puerta del Núcleo`, puerta[0], puerta[1], [
    page({
      cond: condition({ variable: [RANGO, ULTIMO_RANGO] }),
      gfx: graphic("", 2, 1, {}),
      list: plano([
        ...texts(["El Núcleo del Mando. Tu rango abre la puerta."]),
        elegir("Entrar", "Seguir",
          (k) => viaje(DIM.nucleoId, LLEGADA[0], LLEGADA[1], k),
          (k) => texts(["Vuelve cuando quieras."], k)),
        endEvent(),
      ]),
    }),
    page({
      gfx: graphic("", 2, 1, {}),
      list: plano([...texts(["Cerrada con llave de rango. Aún no eres Jefe Supremo."]), endEvent()]),
    }),
  ]));

  // Contacto, tablón y enfermería.
  const contacto = siguiente();
  eventos.push(eventoConCelda(`${MARKER} Contacto Gris`, contacto, DIM.contacto.sprite, DIM.contacto.lineas));
  const tablon = siguiente();
  eventos.push(eventoConCelda(`${MARKER} Tablón de Mando`, tablon, DIM.tablon.sprite, DIM.tablon.lineas));
  const enfermeria = siguiente();
  eventos.push(eventoConCelda(`${MARKER} Enfermera`, enfermeria, DIM.enfermeria.sprite, DIM.enfermeria.lineas));
  const centinela = siguiente();
  eventos.push(eventoConCelda(`${MARKER} Centinela`, centinela, DIM.centinela.sprite, DIM.centinela.lineas));

  // Misiones.
  for (const mision of PLAN.misiones) eventos.push(misionEvent(mision, siguiente()));

  // Heridos.
  for (const herido of PLAN.heridos) eventos.push(heridoEvent(herido, siguiente()));

  // Entrenadores de la base.
  for (const t of PLAN.entrenadores) {
    const celda = siguiente();
    eventos.push(event(0, `${MARKER} Agente — ${t.nombre}`, celda[0], celda[1], [
      page({
        gfx: graphic(t.sprite, 2, 1, {}),
        list: plano([
          ...texts([t.frase]),
          script("pbTrainerIntro(:ROCKET_AGENT)"),
          script(`$game_variables[318] = pbTrainerBattle(:ROCKET_AGENT,"${t.nombre}",nil,false,0,true) ? 1 : 0`),
          script("pbTrainerEnd"),
          endEvent(),
        ]),
      }),
    ]));
  }

  return eventos;
}

function eventoConCelda(nombre, celda, sprite, lineas) {
  const e = eventoSimple(nombre, sprite, lineas);
  e.setIvar("@x", celda[0]);
  e.setIvar("@y", celda[1]);
  return e;
}

function eventosNucleo() {
  const celdas = spread(celdasLibres(DIM.nucleoId), 3);
  return [
    (() => {
      const e = nucleoEvent(celdas[0]);
      return e;
    })(),
    (() => {
      const evento = event(0, `${MARKER} Salida del Núcleo`, celdas[1][0], celdas[1][1], [
        page({
          gfx: graphic("", 2, 1, {}),
          list: plano([...texts(["Vuelves a la base."]), viaje(DIM.mapaId, LLEGADA[0], LLEGADA[1], 0), endEvent()]),
        }),
      ]);
      return evento;
    })(),
    (() => eventoConCelda(`${MARKER} Rival Rocket`, celdas[2], PLAN.rival.sprite, PLAN.rival.intro))(),
  ];
}

/* ──────────────────────────── instalación ───────────────────────────────── */

function instalar() {
  const mapas = construirMapas();
  instalarMapInfosYMetadatos();
  const datos = instalarDatos();
  const libres = spread(celdasLibres(PUERTO), 1);
  upsert(PUERTO, [`${MARKER} Capitán`], () => [capitanEvent(libres[0])], BACKUP);
  upsert(DIM.mapaId, [MARKER], () => eventosBase(), BACKUP);
  upsert(DIM.nucleoId, [MARKER], () => eventosNucleo(), BACKUP);
  return { mapas, datos, capitan: libres[0] };
}

/* ──────────────────────────── verificación ──────────────────────────────── */

function verify() {
  const check = makeChecker("Dimensión Team Rocket");

  verificarMapa(check, DIM.mapaId, DIM.titulo, [LLEGADA], 0.2);
  verificarMapa(check, DIM.nucleoId, DIM.tituloNucleo, [LLEGADA], 0.2);

  // — capitán cerrado hasta el duelo
  const capitan = eventsOf(PUERTO).find((e) => e.name === `${MARKER} Capitán — Team Rocket`);
  check.ok(!!capitan, "falta el capitán de la dimensión Rocket");
  if (capitan) {
    const paginas = pagesOf(capitan);
    check.ok(paginas.length === 2, "el capitán debe tener dos páginas");
    check.ok(!!paginas[1].condition?.getIvar("@switch1_valid")
      && Number(paginas[1].condition.getIvar("@switch1_id")) === DUELO,
      "el capitán no exige el duelo de Arceus");
    check.ok(paginas[1].list.some((c) => c.code === 201 && Number(c.params[1]) === DIM.mapaId),
      "el capitán no lleva a la base");
  }

  // — barco de vuelta sin condiciones
  const barco = eventsOf(DIM.mapaId).find((e) => e.name === `${MARKER} Barco a Puerto Horizonte`);
  check.ok(!!barco, "falta el barco de vuelta");
  if (barco) {
    const primera = pagesOf(barco)[0];
    check.ok(!primera.condition?.getIvar("@switch1_valid"), "el barco de vuelta no puede estar condicionado");
    check.ok(primera.list.some((c) => c.code === 201 && Number(c.params[1]) === PUERTO),
      "el barco de vuelta no regresa a Puerto Horizonte");
  }

  // — cinco misiones encadenadas por rango
  for (const mision of PLAN.misiones) {
    const ev = eventsOf(DIM.mapaId).find((e) => e.name === `${MARKER} Misión — ${mision.titulo}`);
    check.ok(!!ev, `falta la misión «${mision.titulo}»`);
    if (!ev) continue;
    const paginas = pagesOf(ev);
    check.ok(paginas.length === 3, `«${mision.titulo}» debe tener tres páginas`);
    const cond = paginas[1].condition;
    check.ok(!!cond?.getIvar("@variable_valid") && Number(cond.getIvar("@variable_id")) === RANGO
      && Number(cond.getIvar("@variable_value")) === mision.rango,
      `«${mision.titulo}» no exige el rango ${mision.rango}`);
    const lista = paginas[1].list;
    check.ok(lista.some((c) => c.code === 122 && Number(c.params[1]) === RANGO && Number(c.params[4]) === mision.rango + 1),
      `«${mision.titulo}» no asciende al rango ${mision.rango + 1}`);
    check.ok(lista.some((c) => c.code === 122 && Number(c.params[1]) === MISIONES),
      `«${mision.titulo}» no cuenta la misión`);
    if (mision.batalla) {
      check.ok(lista.some((c) => (c.code === 111 || c.code === 355)
        && [c.params[0], c.params[1]].some((p) => String(p ?? "").includes(`pbTrainerBattle(:${mision.batalla.tipo}`))),
        `«${mision.titulo}» no pelea como está escrito`);
    }
  }

  // — los heridos se pueden socorrer y eso se cuenta
  const heridos = eventsOf(DIM.mapaId).filter((e) => e.name.startsWith(`${MARKER} Herido —`));
  check.ok(heridos.length === PLAN.heridos.length,
    `se esperaban ${PLAN.heridos.length} heridos y hay ${heridos.length}`);
  for (const h of heridos) {
    const primera = pagesOf(h)[0];
    check.ok(primera.list.some((c) => c.code === 314), `${h.name}: no ofrece curar`);
    check.ok(primera.list.some((c) => c.code === 122 && Number(c.params[1]) === HERIDOS),
      `${h.name}: socorrer no se cuenta`);
  }

  // — el Núcleo sólo se abre con el rango máximo y entrega la insignia
  const nucleo = eventsOf(DIM.nucleoId).find((e) => e.name === `${MARKER} Núcleo del Mando`);
  check.ok(!!nucleo, "falta el Núcleo del Mando");
  if (nucleo) {
    const paginas = pagesOf(nucleo);
    check.ok(paginas.length === 3, "el Núcleo debe tener tres páginas");
    const cond = paginas[1].condition;
    check.ok(!!cond?.getIvar("@variable_valid")
      && Number(cond.getIvar("@variable_value")) === ULTIMO_RANGO,
      `el Núcleo no exige el rango ${ULTIMO_RANGO} (Jefe Supremo)`);
    check.ok(paginas[1].list.some((c) => c.code === 121 && Number(c.params[0]) === CONTROL),
      "la toma del mando no enciende el control de la dimensión");
    check.ok(paginas[1].list.some((c) => [c.params?.[0], c.params?.[1]]
      .some((p) => String(p ?? "").includes(`pbReceiveItem(:${PLAN.medalla.id}`))),
      "la toma del mando no entrega la insignia");
  }

  check.done();
}

/* ──────────────────────────────── main ──────────────────────────────────── */

if (VERIFY_ONLY) {
  verify();
} else {
  const resultado = instalar();
  console.log("✔ Dimensión Team Rocket instalada");
  console.log(`  · Map${DIM.mapaId} «${DIM.titulo}» ${resultado.mapas.ancho}×${resultado.mapas.alto} · ${resultado.mapas.ventanas.length} distritos · ${resultado.mapas.pasillos} pasillos`);
  console.log(`  · Map${DIM.nucleoId} «${DIM.tituloNucleo}»`);
  console.log(`  · misiones encadenadas: ${PLAN.misiones.length} (rango 0 → ${ULTIMO_RANGO})`);
  console.log(`  · heridos que Ash puede socorrer: ${PLAN.heridos.length} · variable ${HERIDOS}`);
  console.log(`  · rangos: ${PLAN.rangos.join(" → ")}`);
  const nuevos = (lista) => lista.filter((x) => x.added).length;
  console.log(`  · tipos: ${nuevos(resultado.datos.tipos)}/${resultado.datos.tipos.length} · entrenadores: ${nuevos(resultado.datos.entrenadores)}/${resultado.datos.entrenadores.length} · objetos: ${nuevos(resultado.datos.medallas)}/${resultado.datos.medallas.length}`);
  verify();
