function spread(map,count,excluded){const ban=new Set(excluded.map((p)=>p.join(","))),cells=largest(map).filter((p)=>!ban.has(p.join(",")));if(cells.length<count)throw new Error(`No hay ${count} posiciones libres`);const chosen=[cells[Math.floor(cells.length/2)]],used=new Set([chosen[0].join(",")]);while(chosen.length<count){let best,score=-1;for(const c of cells){if(used.has(c.join(",")))continue;const d=Math.min(...chosen.map((p)=>(p[0]-c[0])**2+(p[1]-c[1])**2));if(d>score){score=d;best=c;}}chosen.push(best);used.add(best.join(","));}return chosen;}
function npcEvent(id,npc,pos,flag){const gfx=()=>graphic(npc.sprite);return event(id,`${MARKER} NPC ${npc.name}`,pos[0],pos[1],[page({gfx:gfx(),list:[...texts(npc.dialogue.before),...texts(npc.dialogue.optional),cmd(0)]}),page({cond:condition({sw:flag}),gfx:gfx(),list:[...texts(npc.dialogue.after),cmd(0)]})]);}
