  const introduction = [blueprint.title, blueprint.promise, ...firstNpc.dialogue.before, `Objetivo: ${blueprint.objective}`, `${blueprint.mechanic.name}: ${blueprint.mechanic.rules.join(" / ")}`, blueprint.mechanic.failureSafe];
