import fs from "node:fs";
import path from "node:path";
import { marshalLoad, marshalDump, RHash, RObject, RSymbol } from "../web/js/marshal.js";
import { parseMap, parseTileset, tableGet } from "../web/js/rmxp.js";
import { DATA, GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY_ONLY = process.argv.includes("--verify");
// Techo de nivel de la expansión: 175. Arceus (200) y Mad Pikachu (???) viven fuera
// de las tablas salvajes y se controlan desde sus propios eventos.
const MAX_LEVEL = 175;
const BACKUP = path.join(GAME, "PokeModBackups", "wild_zones_originals");
const CATALOG = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "wild_zones.json"), "utf8"));
const TERRAIN_OK = {
  // tipo de encuentro -> etiquetas de terreno que lo disparan (Cave: cualquier paso)
  Cave: null,
  Land: new Set([2, 10, 11, 14]),
  Water: new Set([5, 6, 7]),
};

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));
const pad3 = (n) => String(n).padStart(3, "0");

function dataSymbols(file) {
  const ids = new Set();
  for (const [key] of read(file).pairs) if (key instanceof RSymbol) ids.add(key.name);
  return ids;
}
function tilesetsById() {
  const rows = read("Tilesets.rxdata");
  const out = new Map();
  for (let i = 1; i < rows.length; i++) if (rows[i]) { const t = parseTileset(rows[i]); out.set(t.id, t); }
  return out;
}
function mapTerrainTags(mapId, tilesets) {
  const map = parseMap(read(`Map${pad3(mapId)}.rxdata`));
  const ts = tilesets.get(map.tilesetId);
  const tags = new Set();
  for (let y = 0; y < map.height; y++) for (let x = 0; x < map.width; x++) for (let z = 0; z < map.table.z; z++) {
    const tile = tableGet(map.table, x, y, z);
    if (tile > 0 && tile < ts.terrain.data.length) {
      const tag = ts.terrain.data[tile];
      if (tag > 0) tags.add(tag);
    }
  }
  return tags;
}
function encounterObject(zone) {
  const id = new RSymbol(`${zone.mapId}_0`);
  const stepChances = new RHash(Object.entries(zone.step_chances).map(([type, steps]) => [new RSymbol(type), steps]));
  const types = new RHash(Object.entries(zone.types).map(([type, slots]) => [
    new RSymbol(type),
    slots.map(([weight, species, min, max]) => [weight, new RSymbol(species), min, max]),
  ]));
  return new RObject("GameData::Encounter", [
    ["@id", id], ["@map", zone.mapId], ["@version", 0],
    ["@step_chances", stepChances], ["@types", types],
  ]);
}
function validate() {
  const species = dataSymbols("species.dat");
  const tilesets = tilesetsById();
  const errors = [];
  for (const zone of CATALOG.zones) {
    for (const [type, slots] of Object.entries(zone.types)) {
      if (!(type in TERRAIN_OK)) { errors.push(`${zone.mapId}: tipo de encuentro desconocido ${type}`); continue; }
      const needed = TERRAIN_OK[type];
      if (needed) {
        const tags = mapTerrainTags(zone.mapId, tilesets);
        if (![...needed].some((tag) => tags.has(tag))) errors.push(`${zone.mapId} (${zone.label}): sin tiles para el tipo ${type}`);
      }
      for (const [weight, sp, min, max] of slots) {
        if (!species.has(sp)) errors.push(`${zone.mapId}: especie inexistente ${sp}`);
        if (!(weight > 0)) errors.push(`${zone.mapId}: peso inválido en ${sp}`);
        if (!(min >= 1 && max >= min && max <= MAX_LEVEL)) errors.push(`${zone.mapId}: niveles inválidos en ${sp} (${min}-${max})`);
      }
    }
  }
  return errors;
}
function install() {
  fs.mkdirSync(BACKUP, { recursive: true });
  const src = path.join(DATA, "encounters.dat");
  const dst = path.join(BACKUP, "encounters.dat");
  if (!fs.existsSync(dst)) fs.copyFileSync(src, dst);
  fs.writeFileSync(path.join(BACKUP, "LEEME.txt"), "encounters.dat anterior a las zonas salvajes de la expansión. No contiene partidas.\n");
  const encounters = read("encounters.dat");
  const ours = new Set(CATALOG.zones.map((zone) => `${zone.mapId}_0`));
  encounters.pairs = encounters.pairs.filter(([key]) => !ours.has(key.name ?? String(key)));
  for (const zone of CATALOG.zones) {
    const obj = encounterObject(zone);
    encounters.pairs.push([new RSymbol(`${zone.mapId}_0`), obj]);
  }
  write("encounters.dat", encounters);
}
function verify() {
  const errors = validate();
  const encounters = read("encounters.dat");
  for (const zone of CATALOG.zones) {
    const entry = encounters.pairs.find(([key]) => (key.name ?? String(key)) === `${zone.mapId}_0`)?.[1];
    if (!entry) { errors.push(`${zone.mapId}: falta la entrada en encounters.dat`); continue; }
    const types = entry.getIvar("@types");
    const stepChances = entry.getIvar("@step_chances");
    for (const [type, slots] of Object.entries(zone.types)) {
      const stored = types.pairs.find(([key]) => key.name === type)?.[1];
      if (!stored || stored.length !== slots.length) errors.push(`${zone.mapId}: tabla ${type} incorrecta`);
      const steps = stepChances.pairs.find(([key]) => key.name === type)?.[1];
      if (steps !== zone.step_chances[type]) errors.push(`${zone.mapId}: step_chance ${type} incorrecto`);
    }
  }
  if (errors.length) throw new Error(`Zonas salvajes inválidas (${errors.length}):\n- ${errors.join("\n- ")}`);
  const slots = CATALOG.zones.reduce((sum, zone) => sum + Object.values(zone.types).reduce((s, t) => s + t.length, 0), 0);
  console.log(`Verificación OK: ${CATALOG.zones.length} zonas salvajes con ${slots} slots en encounters.dat (especies existentes, niveles ≤ ${MAX_LEVEL}, terrenos compatibles).`);
}

if (!VERIFY_ONLY) { install(); console.log("Zonas salvajes instaladas en encounters.dat. Backup en " + path.relative(ROOT, BACKUP)); }
verify();#!/usr/bin/env node
/**
 * apply_z_menu_safety.mjs
 *
 * «Muchas crash movimiento z.»
 *
 * La Z del mapa es `Input::SPECIAL` → `pbUseKeyItem` (UI_ReadyMenu). Ese método
 * lee los objetos registrados de la PARTIDA y los busca con `GameData::Item.get`,
 * que lanza un error si el id ya no existe en los datos (los parches del DLC
 * renombran/retiran ítems). Resultado: menú con Z = error en mitad del mapa.
 *
 * Este aplicador inyecta la sección Ruby `PokeMod_ZMenu`
 * (tools/lib/pokemod_zmenu.rb) que limpia la lista de ids inválidos, deja
 * `registeredIndex` siempre válido y convierte cualquier fallo del menú en un
 * mensaje en pantalla en vez de la pantalla de error de RGSS.
 *
 * Uso:
 *   node tools/apply_z_menu_safety.mjs            # aplica
 *   node tools/apply_z_menu_safety.mjs --verify   # solo comprueba
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const VERIFY_ONLY = process.argv.includes("--verify");
const TITULO = "PokeMod_ZMenu";
const RUBY = fs.readFileSync(new URL("./lib/pokemod_zmenu.rb", import.meta.url), "utf8");

const SCRIPTS = [
  path.join(ROOT, "pokemon_fire_ash", "Data", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Paquete_directo", "Data", "Scripts.rxdata"),
  path.join(ROOT, "Scripts_corregido", "Dimensional_Nightmare_QA", "Data", "Scripts.rxdata"),
].filter((f) => fs.existsSync(f));

const ESPERADOS = [
  "module PokeModZMenu",
  "def self.objetoValido?",
  "def self.limpiarRegistro",
  "pokemod_orig_registeredIndex",
  "pokemod_orig_pbUseKeyItem",
  "GameData::Item.try_get",
];

function inyectar(archivo) {
  const scripts = marshalLoad(fs.readFileSync(archivo));
  const comprimido = zlib.deflateSync(Buffer.from(RUBY, "utf-8"));
  const idx = scripts.findIndex(([, t]) => t && t.text === TITULO);
  if (idx >= 0) scripts[idx][2] = new RString(comprimido);
  // Antes de la última sección (Main), como el resto de secciones PokeMod.
  else scripts.splice(scripts.length - 1, 0, [999903, RString.fromText(TITULO), new RString(comprimido)]);
  fs.writeFileSync(archivo, Buffer.from(marshalDump(scripts)));
  return idx >= 0;
}

function verificar(archivo) {
  const fallos = [];
  const scripts = marshalLoad(fs.readFileSync(archivo));
  const seccion = scripts.find(([, t]) => t && t.text === TITULO);
  if (!seccion) return [`${archivo}: falta la sección ${TITULO}`];
  let code = "";
  try { code = zlib.inflateSync(Buffer.from(seccion[2].bytes)).toString("utf8"); }
  catch { return [`${archivo}: la sección ${TITULO} no se puede descomprimir`]; }
  for (const e of ESPERADOS) if (!code.includes(e)) fallos.push(`${archivo}: falta «${e}»`);
  // La sección tiene que ir ANTES de Main (si no, se cargaría después del bucle)
  const iSec = scripts.findIndex(([, t]) => t && t.text === TITULO);
  const iMain = scripts.findIndex(([, t]) => t && t.text === "Main");
  if (iMain >= 0 && iSec > iMain) fallos.push(`${archivo}: ${TITULO} está después de Main`);
  return fallos;
}

let fallos = [];
let cambios = 0;
for (const archivo of SCRIPTS) {
  const rel = path.relative(ROOT, archivo);
  if (VERIFY_ONLY) {
    const f = verificar(archivo);
    fallos = fallos.concat(f);
    console.log(`${f.length ? "✘" : "✔"} ${rel}${f.length ? ` → ${f.join(" · ")}` : ""}`);
    continue;
  }
  const ya = inyectar(archivo);
  cambios += ya ? 0 : 1;
  const f = verificar(archivo);
  fallos = fallos.concat(f);
  console.log(`${f.length ? "✘" : "✔"} ${rel}: ${ya ? "sección actualizada" : "sección añadida"}`);
}

if (VERIFY_ONLY) {
  console.log(fallos.length ? `\n✘ ${fallos.length} problema(s)` : "\n✔ parche del botón Z presente y correcto");
  process.exit(fallos.length ? 1 : 0);
}
console.log(`\n✔ ${SCRIPTS.length} Scripts.rxdata con PokeMod_ZMenu (${cambios} nuevos)`);
process.exit(fallos.length ? 1 : 0);#!/usr/bin/env python3
"""Ensambla los kits de atuendos de Ash (assets_raw/) en gráficos del juego.

Kit completo por atuendo (que no falte ningún sprite ni animación):
- trchar000_N.png          caminar  (128x192, 4x4 de 32x48)   <- 3 poses IA
- boy_run_N.png            correr   (128x192)                 <- derivado (avance)
- boy_bike_N.png           bici     (192x192, 6x4 de 32x48)   <- paleta del atuendo
- boy_surf_N.png           surf     (128x192)                 <- paleta del atuendo
- boy_fish_offset_N.png    pesca    (384x320)                 <- paleta del atuendo
- POKEMONTRAINER_Red_N.png batalla frente (158x158)           <- IA
- POKEMONTRAINER_Red_N_back.png batalla espalda (812x196)     <- IA

Los crudos IA son pixel-art estilo GBA de Ash con cada atuendo; aquí se les
quita el fondo (flood-fill desde los bordes -> alfa 0), se recorta el personaje
y se ajusta al tamaño exacto de los sprites del motor (marco 32x48 de
primera/tercera generación en RMXP, batalla 158x158 / tira 812x196), siempre
RGBA con transparencia para que no desentonen con el juego.
"""
import os
import sys
from collections import deque

from PIL import Image

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RAW = os.path.join(ROOT, "assets_raw")
GFX = os.path.join(ROOT, "pokemon_fire_ash", "Graphics")
CHARS = os.path.join(GFX, "Characters")
TRAINERS = os.path.join(GFX, "Trainers")

# slot de outfit del motor -> prefijo de crudos en assets_raw/
KITS = {
    8: "ash_maestro",  # Campeón del Mundo (regalo de Oak, La Ruta de Dios)
    11: "creep",       # Viajero dimensional 1ª Gen (mundos crepypasta)
    12: "glazed",      # Pokémon Glazed (Tunod)
    13: "lp",          # Pokémon Light Platinum (Zhery y Lauren)
    14: "lc",          # Pokémon Liquid Crystal (Johto)
}


def load(name):
    p = os.path.join(RAW, name)
    return Image.open(p).convert("RGBA") if os.path.exists(p) else None


def remove_bg(img, tol=40):
    """Flood-fill desde los bordes sobre el color de fondo -> alfa 0."""
    im = img.convert("RGBA")
    w, h = im.size
    px = im.load()
    samples = []
    for x in range(0, w, max(1, w // 64)):
        samples.append(px[x, 0][:3])
        samples.append(px[x, h - 1][:3])
    for y in range(0, h, max(1, h // 64)):
        samples.append(px[0, y][:3])
        samples.append(px[w - 1, y][:3])
    samples.sort(key=lambda c: c[0] + c[1] + c[2])
    bg = samples[len(samples) // 2]

    def near(c):
        return (abs(c[0] - bg[0]) <= tol and abs(c[1] - bg[1]) <= tol
                and abs(c[2] - bg[2]) <= tol)

    seen = bytearray(w * h)
    dq = deque()
    for x in range(w):
        for y in (0, h - 1):
            i = y * w + x
            if not seen[i] and near(px[x, y][:3]):
                seen[i] = 1
                dq.append((x, y))
    for y in range(h):
        for x in (0, w - 1):
            i = y * w + x
            if not seen[i] and near(px[x, y][:3]):
                seen[i] = 1
                dq.append((x, y))
    while dq:
        x, y = dq.popleft()
        px[x, y] = (px[x, y][0], px[x, y][1], px[x, y][2], 0)
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < w and 0 <= ny < h:
                i = ny * w + nx
                if not seen[i] and near(px[nx, ny][:3]):
                    seen[i] = 1
                    dq.append((nx, ny))
    return im


def isolate(img):
    """Recorta el personaje; si hay varias figuras en fila toma la izquierda."""
    bbox = img.getbbox()
    if not bbox:
        return img
    x0, y0, x1, y1 = bbox
    w, h = x1 - x0, y1 - y0
    if w > h * 1.1:  # hoja con varias figuras -> quédate con la de la izquierda
        mid = (x0 + x1) // 2
        left = img.crop((x0, y0, mid, y1))
        b2 = left.getbbox()
        return left.crop(b2) if b2 else left
    return img.crop(bbox)


def fit_aspect(img, w, h):
    """Ajusta conservando proporción, centrado horizontal y pies abajo."""
    iw, ih = img.size
    if iw <= 0 or ih <= 0:
        return Image.new("RGBA", (w, h), (0, 0, 0, 0))
    s = min(w / iw, h / ih)
    nw, nh = max(1, int(round(iw * s))), max(1, int(round(ih * s)))
    r = img.resize((nw, nh), Image.LANCZOS)
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    out.paste(r, ((w - nw) // 2, h - nh), r)
    return out


def save(img, dest):
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    img.convert("RGBA").save(dest)
    print("  ->", os.path.relpath(dest, ROOT), img.size)


def step_frame(base, shift):
    w, h = base.size
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    cut = int(h * 0.62)
    body = base.crop((0, 0, w, cut))
    legs = base.crop((0, cut, w, h))
    out.paste(body, (0, -1), body)
    out.paste(legs, (shift, cut), legs)
    return out


def run_frame(base, shift):
    """Marco de carrera: inclinación hacia delante + zancada mayor."""
    w, h = base.size
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    cut = int(h * 0.60)
    body = base.crop((0, 0, w, cut))
    legs = base.crop((0, cut, w, h))
    out.paste(body, (2, -2), body)
    out.paste(legs, (2 + shift, cut + 1), legs)
    return out


def walk_sheet(front, back, left, step=step_frame):
    f = fit_aspect(front, 32, 48)
    b = fit_aspect(back, 32, 48)
    l = fit_aspect(left, 32, 48)
    r = l.transpose(Image.FLIP_LEFT_RIGHT)
    sheet = Image.new("RGBA", (128, 192), (0, 0, 0, 0))
    rows = [(f, f.transpose(Image.FLIP_LEFT_RIGHT)), (l, r), (r, l),
            (b, b.transpose(Image.FLIP_LEFT_RIGHT))]
    for row, (base, mirrored) in enumerate(rows):
        frames = [base, step(base, -1), base, step(mirrored, 1)]
        for col, fr in enumerate(frames):
            sheet.paste(fr, (col * 32, row * 48), fr)
    return sheet


def _opaque_cols(img, max_w=8192):
    im = img.convert("RGBA")
    data = im.tobytes()
    cols = [(data[i], data[i + 1], data[i + 2])
            for i in range(0, len(data), 4) if data[i + 3] > 0]
    if not cols:
        return None
    if len(cols) > max_w:
        step = len(cols) / max_w
        cols = [cols[int(j * step)] for j in range(max_w)]
    strip = Image.new("RGB", (len(cols), 1))
    strip.putdata(cols)
    return strip


def _used_palette(q):
    pal = q.getpalette() or []
    used = sorted({i for _, i in (q.getcolors() or [])})
    return [tuple(pal[i * 3:i * 3 + 3]) for i in used] or [(0, 0, 0)]


def palette_transfer(orig, donor, n=16):
    """Recolorea `orig` con la paleta de `donor`, conservando su alfa.

    Las paletas se calculan solo con píxeles opacos (el alfa de los PNG no
    contamina los colores) y se emparejan por rango de luminancia.
    """
    o = orig.convert("RGBA")
    w, h = o.size
    ostrip = _opaque_cols(o)
    dstrip = _opaque_cols(donor)
    if ostrip is None or dstrip is None:
        return o
    o_pal = _used_palette(ostrip.quantize(colors=n, method=Image.MEDIANCUT))
    d_pal = _used_palette(dstrip.quantize(colors=n, method=Image.MEDIANCUT))

    def lum(c):
        return 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]

    o_sorted = sorted(o_pal, key=lum)
    d_sorted = sorted(d_pal, key=lum)
    lut = []
    for rank in range(len(o_sorted)):
        pos = int(round(rank * (len(d_sorted) - 1) / max(1, len(o_sorted) - 1)))
        lut.append(d_sorted[min(max(pos, 0), len(d_sorted) - 1)])

    cache = {}

    def nearest(c):
        i = cache.get(c)
        if i is None:
            i = min(range(len(o_sorted)),
                    key=lambda k: (o_sorted[k][0] - c[0]) ** 2
                    + (o_sorted[k][1] - c[1]) ** 2
                    + (o_sorted[k][2] - c[2]) ** 2)
            cache[c] = i
        return i

    data = o.tobytes()
    outb = bytearray(w * h * 4)
    j = 0
    for i in range(0, len(data), 4):
        a = data[i + 3]
        if a:
            c = lut[nearest((data[i], data[i + 1], data[i + 2]))]
            outb[j] = c[0]
            outb[j + 1] = c[1]
            outb[j + 2] = c[2]
        outb[j + 3] = a
        j += 4
    out = Image.new("RGBA", (w, h))
    out.frombytes(bytes(outb))
    return out


def battle_back_strip(stand, throw):
    if stand is None and throw is None:
        return None
    if stand is None:
        stand = throw
    if throw is None:
        throw = stand
    s = fit_aspect(stand, 203, 196)
    t = fit_aspect(throw, 203, 196)
    strip = Image.new("RGBA", (812, 196), (0, 0, 0, 0))
    for i, fr in enumerate([s, s, t, t]):
        strip.paste(fr, (i * 203, 0), fr)
    return strip


def build_kit(slot, raw):
    front = load(f"{raw}_front.png")
    back = load(f"{raw}_back.png")
    left = load(f"{raw}_left.png")
    if front is None or back is None or left is None:
        print(f"  (kit {raw}: faltan poses de caminar, se omite)")
        return False
    print(f"== kit {raw} (outfit {slot}) ==")
    front = isolate(remove_bg(front))
    back = isolate(remove_bg(back))
    left = isolate(remove_bg(left))
    # caminar
    save(walk_sheet(front, back, left),
         os.path.join(CHARS, f"trchar000_{slot}.png"))
    # correr (derivado)
    save(walk_sheet(front, back, left, step=run_frame),
         os.path.join(CHARS, f"boy_run_{slot}.png"))
    # bici / surf / pesca: paleta del atuendo sobre los originales del juego
    for orig_name, out_name in [
        ("boy_bike.png", f"boy_bike_{slot}.png"),
        ("boy_surf.png", f"boy_surf_{slot}.png"),
        ("boy_fish_offset.png", f"boy_fish_offset_{slot}.png"),
    ]:
        p = os.path.join(CHARS, orig_name)
        orig = Image.open(p).convert("RGBA") if os.path.exists(p) else None
        if orig is None:
            print(f"  (falta {orig_name}, se omite)")
            continue
        save(palette_transfer(orig, front), os.path.join(CHARS, out_name))
    # batalla
    bf = load(f"{raw}_battle_front.png")
    if bf is not None:
        save(fit_aspect(isolate(remove_bg(bf)), 158, 158),
             os.path.join(TRAINERS, f"POKEMONTRAINER_Red_{slot}.png"))
    bs = load(f"{raw}_battle_back_stand.png")
    bt = load(f"{raw}_battle_back_throw.png")
    if bs is not None:
        bs = isolate(remove_bg(bs))
    if bt is not None:
        bt = isolate(remove_bg(bt))
    if bs is None and back is not None:
        bs = back  # deriva la pose quieta desde la espalda de caminar
    strip = battle_back_strip(bs, bt)
    if strip is not None:
        save(strip, os.path.join(TRAINERS, f"POKEMONTRAINER_Red_{slot}_back.png"))
    return True


def main():
    hechos = 0
    for slot, raw in KITS.items():
        if build_kit(slot, raw):
            hechos += 1
    print(f"OK: {hechos} kits de atuendo ensamblados.")
    return 0 if hechos else 1


if __name__ == "__main__":
    sys.exit(main())#!/usr/bin/env python3
"""Ensambla el arte R17 (assets_raw/) en los gráficos del juego.

Entrada:  assets_raw/*.png  (generados con IA, un asset por archivo)
Salida:   pokemon_fire_ash/Graphics/...

- Arceus fases 1-5  -> Pokemon/Front/ARCEUS_F1..F5.png (96x96)
  (la fase 6 usa la forma primigenia: Pokemon/Front/ARCEUS.png, ya existente)
- Fondos de batalla -> Battlebacks/genesis{1,2,3}_bg.png (512x288, reemplaza
  el arte de nuestro DLC) y olas_bg / volus_bg (nuevos) con sus bases.
- Ash Maestro       -> Characters/ash_outfit_maestro.png (128x192, 4x4 de 32x48),
  Trainers/POKEMONTRAINER_Red_8.png (158x158) y POKEMONTRAINER_Red_8_back.png
  (812x196 = 4 poses de 203x196).

Los originales reemplazados se respaldan en PokeModBackups/la_ruta_de_dios/graphics/.
Los crudos generados NO son entregables: viven en assets_raw/ (fuera del juego).
"""
import os
import shutil
import sys

from PIL import Image

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RAW = os.path.join(ROOT, "assets_raw")
GAME = os.path.join(ROOT, "pokemon_fire_ash")
GFX = os.path.join(GAME, "Graphics")
BACKUP = os.path.join(GAME, "PokeModBackups", "la_ruta_de_dios", "graphics")


def load(name):
    p = os.path.join(RAW, name)
    return Image.open(p).convert("RGBA") if os.path.exists(p) else None


def save(img, relpath, quantize_colors=64):
    dest = os.path.join(GFX, relpath)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    if os.path.exists(dest):
        os.makedirs(BACKUP, exist_ok=True)
        bak = os.path.join(BACKUP, os.path.basename(dest))
        if not os.path.exists(bak):
            shutil.copy2(dest, bak)
    out = img.convert("RGB")
    if quantize_colors:
        out = out.quantize(colors=quantize_colors, method=Image.MEDIANCUT).convert("RGB")
    out.save(dest)
    print("  ->", os.path.relpath(dest, ROOT), out.size)


def fit(img, w, h):
    return img.resize((w, h), Image.LANCZOS)


def step_frame(base, shift):
    """Marco de paso: piernas (40% inferior) desplazadas, cuerpo 1px arriba."""
    w, h = base.size
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    body = base.crop((0, 0, w, int(h * 0.62)))
    legs = base.crop((0, int(h * 0.62), w, h))
    out.paste(body, (0, -1))
    out.paste(legs, (shift, 0))
    return out


def arceus_fases():
    names = {
        1: "arceus_fase1_cielo.png",
        2: "arceus_fase2_talento.png",
        3: "arceus_fase3_velocidad.png",
        4: "arceus_fase4_tipo.png",
        5: "arceus_fase5_regla.png",
    }
    for n, fn in names.items():
        img = load(fn)
        if img is None:
            print(f"  (falta {fn}, se omite)")
            continue
        save(fit(img, 96, 96), os.path.join("Pokemon", "Front", f"ARCEUS_F{n}.png"))


def fondos():
    mapping = {
        "bg_genesis1_calma.png": "genesis1_bg.png",
        "bg_genesis2_tormenta.png": "genesis2_bg.png",
        "bg_genesis3_apocalipsis.png": "genesis3_bg.png",
        "bg_olas_ritual.png": "olas_bg.png",
        "bg_volus_puerta.png": "volus_bg.png",
    }
    for raw, out in mapping.items():
        img = load(raw)
        if img is None:
            print(f"  (falta {raw}, se omite)")
            continue
        save(fit(img, 512, 288), os.path.join("Battlebacks", out), quantize_colors=96)
    # Bases: copiar las de genesis1 para los fondos nuevos (plataformas del DLC).
    for base_out in ("olas_base0.png", "olas_base1.png", "volus_base0.png", "volus_base1.png"):
        src = os.path.join(GFX, "Battlebacks", base_out.replace("olas", "genesis1").replace("volus", "genesis1"))
        dest = os.path.join(GFX, "Battlebacks", base_out)
        if os.path.exists(src) and not os.path.exists(dest):
            shutil.copy2(src, dest)
            print("  ->", os.path.relpath(dest, ROOT), "(copia de genesis1)")


def ash_maestro():
    front = load("ash_maestro_front.png")
    back = load("ash_maestro_back.png")
    left = load("ash_maestro_left.png")
    if front is not None:
        f = fit(front, 32, 48)
        right = f.transpose(Image.FLIP_LEFT_RIGHT)
        l = fit(left, 32, 48) if left is not None else f
        b = fit(back, 32, 48) if back is not None else f
        r = l.transpose(Image.FLIP_LEFT_RIGHT)
        sheet = Image.new("RGBA", (128, 192), (0, 0, 0, 0))
        # filas RMXP: 0 abajo, 1 izquierda, 2 derecha, 3 arriba
        rows = [(f, right), (l, r), (r, l), (b, b.transpose(Image.FLIP_LEFT_RIGHT))]
        for row, (base, mirrored) in enumerate(rows):
            frames = [base, step_frame(base, -1), base, step_frame(mirrored, 1)]
            for col, fr in enumerate(frames):
                sheet.paste(fr, (col * 32, row * 48))
        save(sheet, os.path.join("Characters", "ash_outfit_maestro.png"), quantize_colors=64)
    else:
        print("  (faltan sprites de Ash, se omite)")
        return
    bat = load("ash_maestro_battle_front.png")
    if bat is not None:
        save(fit(bat, 158, 158), os.path.join("Trainers", "POKEMONTRAINER_Red_8.png"))
    stand = load("ash_maestro_battle_back_stand.png")
    throw = load("ash_maestro_battle_back_throw.png")
    if stand is not None:
        s = fit(stand, 203, 196)
        t = fit(throw, 203, 196) if throw is not None else s
        strip = Image.new("RGBA", (812, 196), (0, 0, 0, 0))
        for i, fr in enumerate([s, s, t, t]):
            strip.paste(fr, (i * 203, 0))
        save(strip, os.path.join("Trainers", "POKEMONTRAINER_Red_8_back.png"), quantize_colors=64)


def main():
    if not os.path.isdir(RAW):
        print("No existe assets_raw/: nada que ensamblar.")
        return 1
    print("== Arceus fases 1-5 ==")
    arceus_fases()
    print("== Fondos de batalla ==")
    fondos()
    print("== Ash Maestro ==")
    ash_maestro()
    print("OK: arte R17 ensamblado.")
    return 0


if __name__ == "__main__":
    sys.exit(main())#!/usr/bin/env node
/**
 * atlas_ingest_reference.mjs
 *
 * Ingesta de los mosaicos de referencia de **Atlas Mil** (`Mapas/Atlas/`).
 *
 * El Dimensional Nightmare ya tiene su propio pipeline (`dn:ingest`), que
 * ignora expresamente `Mapas/Atlas/`. Estos diecisiete mosaicos se quedaron
 * por eso sin herramienta: nadie los cortaba, nadie los medía y nadie podía
 * comparar el Atlas instalado con su referencia.
 *
 * Qué hace:
 *   · localiza la rejilla de cada mosaico buscando los separadores oscuros
 *     (no asume un tamaño fijo: lo mide);
 *   · recorta cada ficha a su caja de contenido real;
 *   · la mide: tamaño en píxeles, factor de escala aparente, alto y ancho en
 *     tiles de 16 px, luminancia media, paleta dominante y una huella de 8×8
 *     para detectar fichas repetidas entre mosaicos;
 *   · escribe `reference/atlas/slices/<mosaico>/NN.png` y
 *     `reference/atlas/index.json`.
 *
 * No adivina a qué mapa corresponde cada ficha: eso depende de un criterio de
 * orden que los nombres de archivo no traen. Lo que sí deja es la medida, que
 * es lo que cualquier asignación necesita para poder comprobarse.
 *
 * Uso:
 *   node tools/atlas_ingest_reference.mjs            # corta y mide
 *   node tools/atlas_ingest_reference.mjs --check    # sólo informa
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIR = path.join(ROOT, "Mapas", "Atlas");
const OUT = path.join(ROOT, "reference", "atlas");
const SLICES = path.join(OUT, "slices");
const INDEX = path.join(OUT, "index.json");
const CHECK_ONLY = process.argv.includes("--check");

const DARK = 26;        // luminancia por debajo de la cual un píxel es «separador»
const FILL = 0.93;      // fracción de la línea que debe ser oscura
const MIN_SPAN = 6;     // grosor mínimo de un separador
const MIN_CELL = 96;    // una ficha más pequeña que esto es un recorte espurio

const round = (n, d = 2) => Number(n.toFixed(d));

async function pixelsOf(file) {
  const image = await loadImage(file);
  const canvas = createCanvas(image.width, image.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(image, 0, 0);
  return { width: image.width, height: image.height, data: ctx.getImageData(0, 0, image.width, image.height).data };
}
const lumAt = (px, x, y) => {
  const i = (y * px.width + x) * 4;
  return px.data[i] * 0.299 + px.data[i + 1] * 0.587 + px.data[i + 2] * 0.114;
};

/** Tramos de filas o columnas que son casi enteramente oscuros. */
function darkRuns(px, horizontal) {
  const length = horizontal ? px.height : px.width;
  const cross = horizontal ? px.width : px.height;
  const step = Math.max(1, Math.floor(cross / 400));
  const runs = [];
  let start = null;
  for (let p = 0; p < length; p++) {
    let dark = 0, total = 0;
    for (let q = 0; q < cross; q += step) {
      const value = horizontal ? lumAt(px, q, p) : lumAt(px, p, q);
      if (value < DARK) dark++;
      total++;
    }
    const fraction = dark / total;
    if (fraction >= FILL) { if (start === null) start = p; }
    else if (start !== null) { if (p - start >= MIN_SPAN) runs.push([start, p - 1]); start = null; }
  }
  if (start !== null && length - start >= MIN_SPAN) runs.push([start, length - 1]);
  return runs;
}

/** Celdas entre separadores, descartando las que no llegan al mínimo. */
function cellsBetween(runs, length) {
  const centres = runs.map(([a, b]) => Math.round((a + b) / 2));
  const edges = [0, ...centres, length - 1];
  const cells = [];
  for (let i = 1; i < edges.length; i++) {
    const from = edges[i - 1] + 2, to = edges[i] - 2;
    if (to - from >= MIN_CELL) cells.push([from, to]);
  }
  return cells;
}

/** Caja de contenido real de una celda (recorta el marco negro). */
function contentBox(px, [x0, x1, y0, y1]) {
  let left = x1, top = y1, right = x0, bottom = y0;
  const step = Math.max(1, Math.floor((x1 - x0) / 240));
  for (let y = y0; y <= y1; y += step) {
    for (let x = x0; x <= x1; x += step) {
      if (lumAt(px, x, y) >= DARK + 6) {
        if (x < left) left = x;
        if (x > right) right = x;
        if (y < top) top = y;
        if (y > bottom) bottom = y;
      }
    }
  }
  if (right <= left || bottom <= top) return null;
  return [left, top, right, bottom];
}

function paletteOf(px, [x0, y0, x1, y1], size = 8) {
  const buckets = new Map();
  const stepX = Math.max(1, Math.floor((x1 - x0) / 60));
  const stepY = Math.max(1, Math.floor((y1 - y0) / 60));
  for (let y = y0; y <= y1; y += stepY) {
    for (let x = x0; x <= x1; x += stepX) {
      const i = (y * px.width + x) * 4;
      const r = px.data[i], g = px.data[i + 1], b = px.data[i + 2];
      const key = `${r >> 5},${g >> 5},${b >> 5}`;
      buckets.set(key, (buckets.get(key) ?? 0) + 1);
    }
  }
  return [...buckets.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, size)
    .map(([key, count]) => {
      const [r, g, b] = key.split(",").map((n) => Number(n) * 32 + 16);
      return { rgb: [r, g, b], weight: count };
    });
}

/** Huella de 8×8 en escala de grises, para detectar fichas repetidas. */
function fingerprintOf(px, [x0, y0, x1, y1]) {
  const grid = [];
  for (let gy = 0; gy < 8; gy++) {
    for (let gx = 0; gx < 8; gx++) {
      const x = Math.round(x0 + ((x1 - x0) * (gx + 0.5)) / 8);
      const y = Math.round(y0 + ((y1 - y0) * (gy + 0.5)) / 8);
      grid.push(Math.round(lumAt(px, x, y)));
    }
  }
  const mean = grid.reduce((a, b) => a + b, 0) / grid.length;
  return grid.map((v) => (v > mean ? 1 : 0)).join("");
}

/** Factor de escala aparente: el mayor divisor «redondo» del tamaño en tiles. */
function scaleGuessOf(width, height) {
  for (const factor of [4, 3, 2, 1]) {
    const w = width / factor / 16, h = height / factor / 16;
    if (w >= 12 && h >= 8 && Number.isInteger(Math.round(w)) && Number.isInteger(Math.round(h))) return factor;
  }
  return 1;
}

async function measure(file) {
  const px = await pixelsOf(file);
  const rows = cellsBetween(darkRuns(px, true), px.height);
  const cols = cellsBetween(darkRuns(px, false), px.width);
  const slices = [];
  let index = 0;
  rows.forEach(([y0, y1], fila) => {
    cols.forEach(([x0, x1], columna) => {
      index += 1;
      const box = contentBox(px, [x0, x1, y0, y1]);
      if (!box) return;
      const [bx0, by0, bx1, by1] = box;
      const width = bx1 - bx0 + 1, height = by1 - by0 + 1;
      const factor = scaleGuessOf(width, height);
      slices.push({
        index,
        row: fila + 1,
        col: columna + 1,
        box,
        width,
        height,
        scaleGuess: factor,
        tilesWide: Math.round(width / factor / 16),
        tilesHigh: Math.round(height / factor / 16),
        luminance: round(meanLuminance(px, box), 1),
        palette: paletteOf(px, box),
        fingerprint: fingerprintOf(px, box),
      });
    });
  });
  return { image: { width: px.width, height: px.height }, grid: { rows: rows.length, cols: cols.length }, slices };
}

function meanLuminance(px, [x0, y0, x1, y1]) {
  let sum = 0, n = 0;
  const stepX = Math.max(1, Math.floor((x1 - x0) / 120));
  const stepY = Math.max(1, Math.floor((y1 - y0) / 120));
  for (let y = y0; y <= y1; y += stepY) {
    for (let x = x0; x <= x1; x += stepX) { sum += lumAt(px, x, y); n++; }
  }
  return n ? sum / n : 0;
}

async function writeSlice(source, slice, folder) {
  const image = await loadImage(source);
  const [x0, y0, x1, y1] = slice.box;
  const canvas = createCanvas(x1 - x0 + 1, y1 - y0 + 1);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(image, x0, y0, x1 - x0 + 1, y1 - y0 + 1, 0, 0, x1 - x0 + 1, y1 - y0 + 1);
  const file = path.join(folder, `${String(slice.index).padStart(2, "0")}.png`);
  fs.writeFileSync(file, canvas.toBuffer("image/png"));
  return path.relative(ROOT, file);
}

// ---------------------------------------------------------------------- main
const files = fs.readdirSync(DIR).filter((name) => /\.png$/i.test(name)).sort();
if (!files.length) {
  console.error(`No hay mosaicos PNG en ${path.relative(ROOT, DIR)}.`);
  process.exit(1);
}
console.log(`mosaicos: ${files.length} en ${path.relative(ROOT, DIR)}`);

const index = {
  title: "Atlas Mil — catálogo de referencia visual",
  generatedBy: "tools/atlas_ingest_reference.mjs",
  note: "Cada ficha es un recorte medido de un mosaico. La correspondencia ficha → mapa no está en los nombres de archivo y no se adivina: este índice sólo entrega la medida.",
  mosaics: [],
};
let total = 0;
for (const name of files) {
  const source = path.join(DIR, name);
  const info = await measure(source);
  const folder = path.join(SLICES, name.replace(/\.png$/i, ""));
  if (!CHECK_ONLY) fs.mkdirSync(folder, { recursive: true });
  for (const slice of info.slices) {
    if (!CHECK_ONLY) slice.file = await writeSlice(source, slice, folder);
  }
  total += info.slices.length;
  const sizes = new Set(info.slices.map((s) => `${s.tilesWide}×${s.tilesHigh}`));
  console.log(`  ${name}: rejilla ${info.grid.cols}×${info.grid.rows} → ${info.slices.length} fichas · tamaños ${[...sizes].slice(0, 4).join(", ")}`);
  index.mosaics.push({ name: path.relative(ROOT, source), ...info });
}

if (CHECK_ONLY) {
  console.log(`\n[check] ${total} fichas medibles en ${files.length} mosaicos (no se ha escrito nada).`);
  process.exit(0);
}
fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(INDEX, `${JSON.stringify(index, null, 2)}\n`);
console.log(`\nTotal: ${total} fichas → ${path.relative(ROOT, INDEX)}`);#!/usr/bin/env node
/**
 * Pipeline narrativo de Atlas Mil.
 * - Clasifica 1.000 mapas en Tier 1/2/3.
 * - Genera seeds y paquetes de contexto para los 40 mapas Tier 1.
 * - Audita blueprints JSON y emite prompts de revisión por fallo.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad,RSymbol } from "../web/js/marshal.js";

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");
const DATA=path.join(ROOT,"pokemon_fire_ash","Data");
const catalog=JSON.parse(fs.readFileSync(path.join(ROOT,"content","atlas_mil_500.json"),"utf8"));
const regionDesign=JSON.parse(fs.readFileSync(path.join(ROOT,"content","atlas_region_design.json"),"utf8"));
const studioReference=JSON.parse(fs.readFileSync(path.join(ROOT,"content","atlas_studio_reference.json"),"utf8"));
const styleBaseline=JSON.parse(fs.readFileSync(path.join(ROOT,"content","atlas_style_baseline.json"),"utf8"));
if(regionDesign.landmarks?.length!==40||regionDesign.compatibility?.readyForNarrativePipeline!==true)throw new Error("El diseño importado de Region Builder no superó la compuerta de compatibilidad.");
if(studioReference.integrity?.ok!==true)throw new Error("El manifiesto de autoría inspirado en Pokémon Studio tiene referencias inválidas.");
if(styleBaseline.integrity?.ok!==true||styleBaseline.summary?.technicalPassed!==40)throw new Error("La comparación de estilo con Fire Ash no superó la compuerta técnica.");
const regionLandmarks=new Map(regionDesign.landmarks.map((landmark)=>[Number(landmark.sectorId),landmark]));
const studioRecords=new Map(studioReference.records.map((record)=>[Number(record.mapId),record]));
const styleAnchors=new Map(styleBaseline.anchors.map((anchor)=>[Number(anchor.mapId),anchor]));
const masterPrompt=fs.readFileSync(path.join(ROOT,"docs","PROMPT_MAESTRO_TIER1.md"),"utf8");
const read=(f)=>marshalLoad(fs.readFileSync(path.join(DATA,f)));
const sym=(v)=>v instanceof RSymbol?v.name:String(v??"");

const crossovers=[
  ["Pokémon Adventures","TCG","radio de Pueblo Lavanda"],["The Electric Tale of Pikachu","anime clásico","torneos escolares"],
  ["Pokémon Origins","archivos de Oak","Liga prototipo"],["Mystery Dungeon","gremios","expediciones"],
  ["Pokémon Ranger","rescate","ecología"],["Colosseum/XD","Orre","rehabilitación oscura"],
