console.log(`Compuertas externas: Region Builder=${regionDesign.landmarks.length}/40, Studio=${studioReference.records.length} registros íntegros, estilo Fire Ash=${styleBaseline.summary.technicalPassed}/40.`);#!/usr/bin/env node
/**
 * Compara las 40 anclas de Atlas con mapas reales de Fire Ash.
 * Valida geometría, tilesets, pasabilidad, recursos visuales y eventos sin
 * intentar sustituir la prueba final dentro de Game.exe.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { ROOT, GAME, DATA, readMarshalData, stringValue } from "./lib/fire_ash_registry.mjs";
import { parseEvent, parseMap, parseTileset, tableGet } from "../web/js/rmxp.js";

const json = (file) => JSON.parse(fs.readFileSync(file, "utf8"));
const writeJson = (file, value) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
};
const pad = (value) => String(value).padStart(3, "0");
const hashTable = (table) => crypto.createHash("sha256").update(Buffer.from(table.data.buffer, table.data.byteOffset, table.data.byteLength)).digest("hex");

const imageInventory = new Map();
function imageExists(folder, name) {
  if (!name) return true;
  if (!imageInventory.has(folder)) {
    const files = fs.existsSync(folder) ? fs.readdirSync(folder) : [];
    imageInventory.set(folder, new Set(files.filter((file) => /\.(png|jpg|jpeg|bmp)$/i.test(file)).map((file) => file.toLowerCase())));
  }
  return [".png", ".jpg", ".jpeg", ".bmp"].some((extension) => imageInventory.get(folder).has(`${name}${extension}`.toLowerCase()));
}

function passabilityRatio(map, tileset) {
  let passable = 0;
  const total = map.width * map.height;
  for (let y = 0; y < map.height; y++) {
    for (let x = 0; x < map.width; x++) {
      let directions = 0;
      for (let z = 0; z < map.table.z; z++) {
        const tile = tableGet(map.table, x, y, z);
        if (tile > 0 && tile < tileset.passages.data.length) directions |= tileset.passages.data[tile] & 15;
      }
      if (directions !== 15) passable++;
    }
  }
  return total ? Number((passable / total).toFixed(4)) : 0;
}

function tileSimilarity(left, right) {
  if (left.table.x !== right.table.x || left.table.y !== right.table.y || left.table.z !== right.table.z) return 0;
  let same = 0;
  for (let index = 0; index < left.table.data.length; index++) if (left.table.data[index] === right.table.data[index]) same++;
  return Number((same / Math.max(1, left.table.data.length)).toFixed(4));
}

function mapMetrics(parsed, tileset) {
  const layers = [];
  const uniqueTiles = new Set();
  for (let z = 0; z < parsed.table.z; z++) {
    let occupied = 0;
    for (let y = 0; y < parsed.height; y++) for (let x = 0; x < parsed.width; x++) {
      const tile = tableGet(parsed.table, x, y, z);
      if (tile) { occupied++; uniqueTiles.add(tile); }
    }
    layers.push({ layer: z, occupied, ratio: Number((occupied / Math.max(1, parsed.width * parsed.height)).toFixed(4)) });
  }
  return {
    width: parsed.width,
    height: parsed.height,
    tilesetId: parsed.tilesetId,
    tileHash: hashTable(parsed.table),
    uniqueTiles: uniqueTiles.size,
    layerOccupancy: layers,
    passabilityRatio: passabilityRatio(parsed, tileset),
    eventCount: parsed.events.length,
  };
}

export function buildAtlasStyleReport() {
  const hierarchy = json(path.join(ROOT, "content", "atlas_content_hierarchy.json"));
  const approved = json(path.join(ROOT, "content", "atlas_tier1_blueprints_approved.json")).blueprints ?? [];
  const approvedIds = new Set(approved.map((entry) => Number(entry.mapId)));
  const characters = new Set(fs.readdirSync(path.join(GAME, "Graphics", "Characters"))
    .filter((file) => /\.(png|jpg|jpeg|bmp)$/i.test(file)).map((file) => file.replace(/\.(png|jpg|jpeg|bmp)$/i, "")));
  const rawTilesets = readMarshalData("Tilesets.rxdata");
  const tilesets = new Map();
  for (let index = 1; index < rawTilesets.length; index++) if (rawTilesets[index]) {
    const parsed = parseTileset(rawTilesets[index]);
    tilesets.set(parsed.id, parsed);
  }

  const errors = [];
  const warnings = [];
  const anchors = hierarchy.maps.filter((entry) => entry.tier === 1).map((entry) => {
    const mapFile = path.join(DATA, `Map${pad(entry.mapId)}.rxdata`);
    const sourceFile = path.join(DATA, `Map${pad(entry.sourceId)}.rxdata`);
    if (!fs.existsSync(mapFile) || !fs.existsSync(sourceFile)) {
      errors.push(`${entry.mapId}: falta mapa Atlas o fuente ${entry.sourceId}.`);
      return { mapId: entry.mapId, sourceMapId: entry.sourceId, technicalStatus: "failed" };
    }
    const current = parseMap(readMarshalData(`Map${pad(entry.mapId)}.rxdata`));
    const source = parseMap(readMarshalData(`Map${pad(entry.sourceId)}.rxdata`));
    const currentTileset = tilesets.get(current.tilesetId);
    const sourceTileset = tilesets.get(source.tilesetId);
    if (!currentTileset || !sourceTileset) {
      errors.push(`${entry.mapId}: tileset no registrado.`);
      return { mapId: entry.mapId, sourceMapId: entry.sourceId, technicalStatus: "failed" };
    }
    const currentMetrics = mapMetrics(current, currentTileset);
    const sourceMetrics = mapMetrics(source, sourceTileset);
    const similarity = tileSimilarity(current, source);
    const events = current.events.map(({ obj }) => parseEvent(obj));
    const missingSprites = [...new Set(events.flatMap((event) => event.pages.map((page) => page.graphic?.charName).filter(Boolean)).filter((name) => !characters.has(name)))];
    const outOfBoundsEvents = events.filter((event) => event.x < 0 || event.y < 0 || event.x >= current.width || event.y >= current.height).map((event) => event.id);
    const pokeModEvents = events.filter((event) => event.name.startsWith("PokeMod Tier1:"));
    const hasReturn = events.some((event) => event.name === "Return to Puerto Horizonte");
    const tilesetAssets = {
      tileset: currentTileset.tilesetName,
      tilesetExists: imageExists(path.join(GAME, "Graphics", "Tilesets"), currentTileset.tilesetName),
      missingAutotiles: currentTileset.autotiles.filter((name) => name && !imageExists(path.join(GAME, "Graphics", "Autotiles"), name)),
    };
    const technicalProblems = [];
    if (current.tilesetId !== source.tilesetId) technicalProblems.push("tileset distinto del mapa base");
    if (current.width !== source.width || current.height !== source.height) technicalProblems.push("dimensiones distintas del mapa base");
    if (!tilesetAssets.tilesetExists) technicalProblems.push("gráfico de tileset ausente");
    if (tilesetAssets.missingAutotiles.length) technicalProblems.push("autotiles ausentes");
    if (missingSprites.length) technicalProblems.push("sprites de evento ausentes");
    if (outOfBoundsEvents.length) technicalProblems.push("eventos fuera de límites");
    if (!hasReturn) technicalProblems.push("retorno a Puerto Horizonte ausente");
    if (approvedIds.has(entry.mapId) && pokeModEvents.length !== 5) technicalProblems.push(`episodio aprobado con ${pokeModEvents.length}/5 eventos Tier 1`);
    if (technicalProblems.length) errors.push(`${entry.mapId}: ${technicalProblems.join(", ")}.`);

    const artDirectionStatus = similarity === 1 ? "review-required-inherited-geometry" : "customized-needs-game-preview";
    if (approvedIds.has(entry.mapId) && similarity === 1) warnings.push(`${entry.mapId}: conserva exactamente la geometría fuente; es compatible, pero no debe certificarse como mapa visual final sin una pasada artesanal.`);
    if (approvedIds.has(entry.mapId) && similarity !== 1) warnings.push(`${entry.mapId}: incorpora composición visual propia, pero todavía requiere revisión estática y prueba dentro de Game.exe.`);
    return {
      mapId: entry.mapId,
      sourceMapId: entry.sourceId,
      sector: entry.sector,
      sectorName: entry.sectorName,
      approvedEpisode: approvedIds.has(entry.mapId),
      current: currentMetrics,
      source: sourceMetrics,
      comparison: {
        tileSimilarity: similarity,
        exactInheritedGeometry: similarity === 1,
        passabilityDelta: Number((currentMetrics.passabilityRatio - sourceMetrics.passabilityRatio).toFixed(4)),
        eventDelta: currentMetrics.eventCount - sourceMetrics.eventCount,
      },
      assets: { ...tilesetAssets, missingSprites },
      events: { pokeModEvents: pokeModEvents.length, hasFreeReturn: hasReturn, outOfBounds: outOfBoundsEvents },
      technicalStatus: technicalProblems.length ? "failed" : "passed",
      artDirectionStatus,
    };
  });

  return {
    version: 1,
    purpose: "Comparación de fidelidad visual/técnica contra mapas reales de Fire Ash.",
    scope: {
      anchors: anchors.length,
      approvedEpisodes: anchors.filter((entry) => entry.approvedEpisode).length,
      engine: "RPG Maker XP / Pokémon Essentials",
      finalGamePreviewStillRequired: true,
    },
    summary: {
      technicalPassed: anchors.filter((entry) => entry.technicalStatus === "passed").length,
      technicalFailed: anchors.filter((entry) => entry.technicalStatus === "failed").length,
      exactInheritedGeometry: anchors.filter((entry) => entry.comparison?.exactInheritedGeometry).length,
      customGeometry: anchors.filter((entry) => entry.comparison && !entry.comparison.exactInheritedGeometry).length,
      staticCompositionPending: anchors.filter((entry) => entry.comparison?.exactInheritedGeometry).length,
      artReviewRequired: anchors.filter((entry) => entry.approvedEpisode && entry.artDirectionStatus !== "certified").length,
      gamePreviewRequired: anchors.filter((entry) => entry.approvedEpisode).length,
    },
    integrity: { ok: errors.length === 0, errors, warnings },
    anchors,
  };
}

function argument(name, fallback = null) {
  const at = process.argv.indexOf(name);
  return at >= 0 ? process.argv[at + 1] : fallback;
}

export function runCli() {
  const report = buildAtlasStyleReport();
  const checkOnly = process.argv.includes("--check");
  const output = path.resolve(argument("--output", path.join(ROOT, "content", "atlas_style_baseline.json")));
  if (!checkOnly) writeJson(output, report);
  console.log(JSON.stringify({ summary: report.summary, integrity: { ok: report.integrity.ok, errors: report.integrity.errors.length, warnings: report.integrity.warnings.length } }, null, 2));
  if (!report.integrity.ok) process.exitCode = 1;
}

if (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {
  try { runCli(); } catch (error) { console.error(error.stack ?? error.message); process.exitCode = 1; }
}#!/usr/bin/env node
/**
 * atlas_tile_audit.mjs
 *
 * Auditoría real de la Expedición Atlas Mil, mapa por mapa, para responder dos
 * preguntas concretas:
 *
 *   1. ¿Cada mapa ofrece una experiencia distinta?
 *      Se compara la geometría y el vocabulario de tiles de los 1000 mapas
 *      entre sí y contra su mapa de origen en Fire Ash. Un mapa solo se
 *      considera "clon" si coincide en tamaño, tileset y tabla de tiles.
 *
 *   2. ¿Hay tiles mal hechos?
 *      Se buscan los defectos clásicos de un mapa construido por código:
 *        · ids de tile fuera del rango del tileset (basura en la tabla);
 *        · celdas vacías en las tres capas (huecos negros bajo el suelo);
 *        · regiones transitables aisladas (el jugador no puede llegar);
 *        · eventos sobre celdas bloqueadas o fuera del mapa;
 *        · sin salida: un mapa del que no se puede volver;
 *        · mapas planos (un solo tile repetido: sin diseño).
 *
 * El informe queda en docs/atlas_tile_audit.md y el detalle en
 * content/atlas_tile_audit.json.
 *
 * Uso:
 *   node tools/atlas_tile_audit.mjs
 *   node tools/atlas_tile_audit.mjs --check   # falla si hay defectos
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { marshalLoad, marshalDump, RHash, RObject, RString } from "../web/js/marshal.js";
import { parseMap, tableGet } from "../web/js/rmxp.js";
import { ROOT, DATA } from "./lib/fire_ash_registry.mjs";
import { txt, mapFile } from "./lib/dn_rmxp.mjs";
import { passabilityOf, reachableCells, tilesets } from "./lib/map_painter.mjs";

const CHECK = process.argv.includes("--check");
const HIERARCHY = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "atlas_content_hierarchy.json"), "utf8"));
const SALIDA = path.join(ROOT, "content", "atlas_tile_audit.json");
const INFORME = path.join(ROOT, "docs", "atlas_tile_audit.md");

const readMap = (id) => marshalLoad(fs.readFileSync(path.join(DATA, mapFile(id))));
const tileSets = tilesets();

/* ─────────────────────────────── por mapa ──────────────────────────────── */

function auditarMapa(entrada) {
  const id = entrada.mapId;
  if (!fs.existsSync(path.join(DATA, mapFile(id)))) {
    return { id, sector: entrada.sector, sectorName: entrada.sectorName, ausente: true, defectos: ["el mapa no existe"] };
  }
  const raw = readMap(id);
  const parsed = parseMap(raw);
  const { width, height, tilesetId, table } = parsed;
  const ts = tileSets.get(tilesetId);
  const pases = ts?.passages?.data?.length ?? 0;
  const defectos = [];

  // --- vocabulario de tiles y capas
  const tilesUnicos = new Set();
  const ocupacion = [0, 0, 0];
  let fueraDeRango = 0;
  let vacias = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let cubierta = false;
      for (let z = 0; z < table.z; z++) {
        const t = tableGet(table, x, y, z);
        if (!t) continue;
        cubierta = true;
        ocupacion[z]++;
        tilesUnicos.add(t);
        if (t < 0 || (pases && t >= pases)) fueraDeRango++;
      }
      if (!cubierta) vacias++;
    }
  }
  if (fueraDeRango) defectos.push(`${fueraDeRango} celdas con ids de tile fuera del tileset`);
  const totalCeldas = width * height;
  if (vacias > 0) defectos.push(`${vacias} celdas sin ningún tile (huecos)`);

  // --- transitabilidad y regiones aisladas
  const pass = passabilityOf(parsed, tilesetId);
  const eventos = (raw.getIvar("@events")?.pairs ?? []).map(([key, obj]) => ({
    key, nombre: txt(obj.getIvar("@name")), x: obj.getIvar("@x"), y: obj.getIvar("@y"), obj,
  }));

  const entradaEvento = eventos.find((e) => /entrada|entry|llegada|beacon|baliza/i.test(e.nombre))
    ?? eventos.find((e) => /Return to Puerto Horizonte/i.test(e.nombre))
    ?? eventos[0];
  const walkable = [];
  let celdasLibres = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (pass.passable(x, y, 8)) { walkable.push([x, y]); celdasLibres++; }
    }
  }
  // Una celda solo esta perdida si no se puede llegar a ella ni siquiera
  // apareciendo en cada evento del mapa (puertas, balizas, NPCs). Se construye
  // el union de lo alcanzable desde todos los eventos y el resto son huérfanas.
  const alcanzable = new Set();
  const arranques = eventos.filter((e) => e.x >= 0 && e.y >= 0 && e.x < width && e.y < height && pass.passable(e.x, e.y, 8));
  for (const e of arranques) for (const c of reachableCells(pass, [e.x, e.y])) alcanzable.add(c);
  if (!arranques.length && walkable.length) {
    for (const c of reachableCells(pass, walkable[0])) alcanzable.add(c);
  }
  let aisladas = 0;
  for (const [x, y] of walkable) if (!alcanzable.has(`${x},${y}`)) aisladas++;
  const regiones = 1;
  const mayor = alcanzable.size;
  // --- eventos mal colocados
  const eventosMal = eventos.filter((e) => e.x < 0 || e.y < 0 || e.x >= width || e.y >= height
    || !pass.passable(e.x, e.y, 8));
  if (eventosMal.length) defectos.push(`${eventosMal.length} eventos sobre celdas bloqueadas o fuera del mapa`);

  // --- salida siempre disponible
  const tieneSalida = eventos.some((e) => /Return to Puerto Horizonte|Volver|Salida|Salir|Beacon|Baliza|Anterior|Siguiente|Prev|Next/i.test(e.nombre));
  if (!tieneSalida) defectos.push("sin evento de salida evidente");

  // --- plano (un solo tile repetido: sin diseño)
  if (tilesUnicos.size < 8) defectos.push(`vocabulario de ${tilesUnicos.size} tiles: mapa plano, sin diseño`);

  // --- qué defectos ya estaban en el mapa de Fire Ash del que se copió
  const heredado = new Set();
  const fuente = fuentes.get(entrada.sourceId);
  if (fuente) {
    if (fuente.vacias >= vacias && fuente.vacias > 0) heredado.add("celdas sin ningún tile (huecos)");
    if (fuente.tilesUnicos < 8 && tilesUnicos < 8) heredado.add("vocabulario de menos de 8 tiles: mapa plano, sin diseño");
    if (fuente.mismoTrazo && fuente.eventosMal >= eventosMal.length && eventosMal.length > 0) heredado.add("eventos sobre celdas bloqueadas");
  }

  // --- huella para comparar mapas entre sí
  const huella = crypto.createHash("sha256")
    .update(`${width}x${height}|${tilesetId}|`)
    .update(table.data instanceof Uint8Array ? table.data : Buffer.from(table.data ?? []))
    .digest("hex");

  return {
    id,
    sector: entrada.sector,
    sectorName: entrada.sectorName,
    sourceId: entrada.sourceId,
    sourceName: entrada.sourceName,
    tamaño: `${width}x${height}`,
    width, height, tilesetId,
    tilesUnicos: tilesUnicos.size,
    conjuntoTiles: [...tilesUnicos].sort((a, b) => a - b),
    pila: (() => {
      const out = new Uint16Array(totalCeldas * 3);
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) for (let z = 0; z < table.z; z++) out[(x + y * width) * 3 + z] = tableGet(table, x, y, z);
      return out;
    })(),
    ocupacion: ocupacion.map((n) => +(n / totalCeldas).toFixed(4)),
    transitabilidad: +(celdasLibres / totalCeldas).toFixed(4),
    regiones,
    regionMayor: mayor,
    aisladas,
    eventos: eventos.length,
    nombresEventos: [...new Set(eventos.map((e) => e.nombre))],
    huella,
    vacias,
    fueraDeRango,
    eventosMal: eventosMal.map((e) => e.nombre),
    heredados: [...heredado],
    defectos: defectos.filter((d) => ![...heredado].some((h) => d.endsWith(h) || d.includes(h))),
  };
}

/* ───────────────────────────── comparación ─────────────────────────────── */

const jaccard = (a, b) => {
  const A = new Set(a);
  let inter = 0;
  for (const v of b) if (A.has(v)) inter++;
  const union = A.size + b.length - inter;
  return union ? inter / union : 1;
};

function comparar(resultados) {
  const porHuella = new Map();
  for (const r of resultados) {
    if (r.ausente) continue;
    porHuella.set(r.huella, [...(porHuella.get(r.huella) ?? []), r.id]);
  }
  const nombreDe = new Map(resultados.map((r) => [r.id, `${r.sourceName ?? ""}`]));
  // Interiores estándar: en los juegos originales todos los Centros Pokémon
  // (y las salas de concurso, los ascensores de centros comerciales, las
  // sedes de la Liga...) son exactamente la misma habitación. Que el eco sea
  // idéntico es fidelidad, no un defecto.
  const INTERIOR = /pok[eé](mon)?\s*(center|centre)|centro\s*pok[eé]?mon|\bmart\b|tienda|\bshop\b|gym|gimnasio|lab(oratorio|oratory)?\b|contest|concurso|elevator|ascensor|dept\.?\b|league\b|liga|fan club|club de fans|\bgate\b|\bcaf[eé]\b|hotel|inn\b|posada|\btower\b|torre\b|\bcave\b|\bcueva\b|\bhouse\b|\bcasa\b/i;
  const esServicio = (ids) => {
    const aciertos = ids.filter((id) => INTERIOR.test(nombreDe.get(id) ?? "")).length;
    return aciertos / ids.length >= 0.8;
  };
  const clones = [...porHuella.entries()].filter(([, ids]) => ids.length > 1)
    .map(([h, ids]) => ({ huella: h.slice(0, 12), ids, servicio: esServicio(ids) }))
    .sort((a, b) => (a.servicio === b.servicio ? b.ids.length - a.ids.length : a.servicio ? 1 : -1));

  // Vecinos más parecidos: solo se comparan mapas del mismo tamaño y tileset.
  const porFirma = new Map();
  for (const r of resultados) {
    if (r.ausente) continue;
    const k = `${r.width}x${r.height}|${r.tilesetId}`;
    (porFirma.get(k) ?? porFirma.set(k, []).get(k)).push(r);
  }
  const pares = [];
  for (const grupo of porFirma.values()) {
    for (let i = 0; i < grupo.length; i++) {
      for (let j = i + 1; j < grupo.length; j++) {
        const vocabulario = jaccard(grupo[i].conjuntoTiles, grupo[j].conjuntoTiles);
        if (vocabulario < 0.9) continue;
        // Disposición real: cuántas celdas tienen exactamente la misma pila de
        // tiles. Dos rutas pueden compartir materiales y no parecerse en nada.
        const A = grupo[i].pila, B = grupo[j].pila;
        let iguales = 0;
        for (let k = 0; k < A.length; k++) if (A[k] === B[k]) iguales++;
        const disposicion = iguales / A.length;
        pares.push({ a: grupo[i].id, b: grupo[j].id, vocabulario: +vocabulario.toFixed(3), disposicion: +disposicion.toFixed(4) });
      }
    }
  }
  pares.sort((x, y) => y.disposicion - x.disposicion);
  return { clones, paresSimilares: pares };
}

/* ──────────────────────────────── informe ──────────────────────────────── */

function escribirInforme(resultados, comparacion) {
  const validos = resultados.filter((r) => !r.ausente);
  const conDefectos = validos.filter((r) => r.defectos.length);
  const tipos = new Map();
  for (const r of conDefectos) for (const d of r.defectos) {
    const clave = d.replace(/^\d+ /, "").replace(/\d+(\.\d+)?%?/g, "N");
    tipos.set(clave, (tipos.get(clave) ?? 0) + 1);
  }

  const media = (fn) => (validos.reduce((s, r) => s + fn(r), 0) / validos.length).toFixed(3);
  const lineas = [];
  lineas.push("# Auditoría de tiles — Expedición Atlas Mil");
  lineas.push("");
  lineas.push(`Informe generado por \`tools/atlas_tile_audit.mjs\` sobre **${validos.length} mapas** de Atlas Mil.`);
  lineas.push("");
  lineas.push("## 1. ¿Ofrece cada mapa una experiencia distinta?");
  lineas.push("");
  lineas.push(`- Huellas de geometría únicas: **${new Set(validos.map((r) => r.huella)).size} de ${validos.length}**.`);
  lineas.push(`- Mapas idénticos entre sí (clones exactos): **${comparacion.clones.length}**.`);
  lineas.push(`- Pares con más del 90 % de vocabulario de tiles compartido: **${comparacion.paresSimilares.length}**.`);
  const identicos = comparacion.paresSimilares.filter((p) => p.disposicion >= 0.97);
  const enInteriores = new Set();
  for (const c of comparacion.clones) if (c.servicio) for (const id of c.ids) enInteriores.add(id);
  const dentroDeInteriores = identicos.filter((p) => enInteriores.has(p.a) && enInteriores.has(p.b)).length;
  lineas.push(`- De esos pares, con la **misma disposición** de tiles en más del 97 % de las celdas: **${identicos.length}** (${dentroDeInteriores} dentro de los grupos de interiores estándar).`);
  const servicio = comparacion.clones.filter((c) => c.servicio);
  lineas.push(`- Grupos de mapas idénticos que son edificios de servicio (Centros Pokémon, Tiendas…): **${servicio.length}** de ${comparacion.clones.length}.`);
  lineas.push(`- Tamaño medio: **${media((r) => r.width)} × ${media((r) => r.height)}** celdas.`);
  lineas.push(`- Tiles distintos por mapa: media **${media((r) => r.tilesUnicos)}** (mín. ${Math.min(...validos.map((r) => r.tilesUnicos))}, máx. ${Math.max(...validos.map((r) => r.tilesUnicos))}).`);
  lineas.push(`- Transitabilidad media: **${media((r) => r.transitabilidad)}**.`);
  lineas.push("");
  if (comparacion.clones.length) {
    lineas.push("### Clones exactos");
    lineas.push("");
    for (const c of comparacion.clones.slice(0, 25)) {
      lineas.push(`- \`${c.huella}\` (${c.ids.length} mapas)${c.servicio ? " — **edificio de servicio**: idéntico por diseño, igual que en el juego original" : ""}: ${c.ids.slice(0, 12).join(", ")}${c.ids.length > 12 ? `, … (+${c.ids.length - 12})` : ""}`);
    }
    lineas.push("");
  }
  if (comparacion.paresSimilares.length) {
    lineas.push("### Pares más parecidos (≥ 90 % de materiales compartidos)");
    lineas.push("");
    lineas.push("| Mapa A | Mapa B | Materiales | Misma disposición |");
    lineas.push("|---|---|---|---|");
    for (const p of comparacion.paresSimilares.slice(0, 30)) lineas.push(`| ${p.a} | ${p.b} | ${p.vocabulario} | ${(p.disposicion * 100).toFixed(1)} % |`);
    lineas.push("");
  }

  // Diversidad de contenido: la geometría es solo la mitad de la experiencia.
  const firmas = new Map();
  for (const r of resultados) {
    if (r.ausente) continue;
    const clave = [...(r.nombresEventos ?? [])].sort().join("|");
    firmas.set(clave, [...(firmas.get(clave) ?? []), r.id]);
  }
  const distintivas = [...firmas.values()].filter((ids) => ids.length === 1).length;
  lineas.push(`- Mapas cuya **combinación de NPCs y eventos** no se repite en ningún otro mapa: **${distintivas}**.`);
  lineas.push(`- Firmas de contenido distintas: **${firmas.size}** para ${validos.length} mapas.`);
  lineas.push("");
  lineas.push("## 2. ¿Hay tiles mal hechos?");
  lineas.push("");
  lineas.push(`- Mapas sin ningún defecto detectado: **${validos.length - conDefectos.length} de ${validos.length}**.`);
  lineas.push("");
  if (tipos.size) {
    lineas.push("| Defecto | Mapas afectados |");
    lineas.push("|---|---|");
    for (const [tipo, n] of [...tipos.entries()].sort((a, b) => b[1] - a[1])) lineas.push(`| ${tipo} | ${n} |`);
    lineas.push("");
    lineas.push("### Detalle por mapa");
    lineas.push("");
    for (const r of conDefectos.slice(0, 60)) {
      lineas.push(`- **Mapa ${r.id}** (${r.sectorName}, ${r.tamaño}): ${r.defectos.join("; ")}.`);
    }
    if (conDefectos.length > 60) lineas.push(`- ...y ${conDefectos.length - 60} mapas más (detalle completo en \`content/atlas_tile_audit.json\`).`);
    lineas.push("");
  } else {
    lineas.push("Ninguno de los defectos comprobados aparece en ningún mapa.");
    lineas.push("");
  }
  lineas.push("## 3. Qué comprueba exactamente esta auditoría");
  lineas.push("");
  for (const d of [
    "ids de tile fuera del rango del tileset (basura en la tabla de tiles);",
    "celdas sin ningún tile en las tres capas (huecos negros bajo el suelo);",
    "regiones transitables aisladas de la entrada (zonas a las que no se puede llegar);",
    "mapas sin ninguna celda transitable;",
    "eventos sobre celdas bloqueadas o fuera de los límites;",
    "mapas sin evento de salida (el jugador podría quedarse atrapado);",
    "mapas planos: menos de 8 tiles distintos, es decir, sin diseño.",
  ]) lineas.push(`- ${d}`);
  lineas.push("");
  return { lineas: lineas.join("\n"), conDefectos, tipos };
}

/* ──────────────────────────────── programa ─────────────────────────────── */

/** Datos mínimos del mapa de origen, para distinguir defecto propio de herencia. */
function medirFuente(id) {
  if (!id || !fs.existsSync(path.join(DATA, mapFile(id)))) return null;
  const raw = readMap(id);
  const parsed = parseMap(raw);
  const { width, height, tilesetId, table } = parsed;
  const tilesUnicos = new Set();
  let vacias = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let cubierta = false;
      for (let z = 0; z < table.z; z++) {
        const t = tableGet(table, x, y, z);
        if (!t) continue;
        cubierta = true;
        tilesUnicos.add(t);
      }
      if (!cubierta) vacias++;
    }
  }
  let eventosMal = 0;
  if (fs.existsSync(path.join(DATA, mapFile(id)))) {
    const pass = passabilityOf(parsed, tilesetId);
    for (const [, obj] of raw.getIvar("@events")?.pairs ?? []) {
      const x = obj.getIvar("@x"), y = obj.getIvar("@y");
      if (x < 0 || y < 0 || x >= width || y >= height || !pass.passable(x, y, 8)) eventosMal++;
    }
  }
  return { width, height, tilesetId, vacias, tilesUnicos: tilesUnicos.size, eventosMal, mismoTrazo: true };
}

const fuentes = new Map();
for (const entrada of HIERARCHY.maps) {
  if (!fuentes.has(entrada.sourceId)) fuentes.set(entrada.sourceId, medirFuente(entrada.sourceId));
}

const resultados = [];
for (const entrada of HIERARCHY.maps) resultados.push(auditarMapa(entrada));
const comparacion = comparar(resultados);
for (const r of resultados) { delete r.conjuntoTiles; delete r.pila; delete r.nombresEventos; }
fs.writeFileSync(SALIDA, JSON.stringify({ version: 1, mapas: resultados, comparacion }, null, 2));

const { lineas, conDefectos } = escribirInforme(resultados, comparacion);
fs.writeFileSync(INFORME, lineas);

console.log(lineas.split("\n").filter((l) => l.startsWith("-") || l.startsWith("#")).join("\n"));
console.log(`\nInforme: ${path.relative(ROOT, INFORME)}`);
console.log(`Detalle: ${path.relative(ROOT, SALIDA)}`);

if (CHECK && conDefectos.length) {
  console.log(`\n✘ ${conDefectos.length} mapas con defectos.`);
  process.exit(1);
}#!/usr/bin/env node
/**
 * atlas_tile_repair.mjs
 *
 * Repara los defectos que detecta `atlas_tile_audit.mjs` en los 1000 mapas de
 * la Expedición Atlas Mil:
 *
 *   1. **Mapas planos o vacíos.** Un puñado deAtlas mapas son ecos de mapas de
 *      Fire Ash que no tienen tabla de tiles (mapas de región del Pokédex,
 *      maquetas de viaje…). El eco sale en negro. Se les da geometría copiando
 *      una ventana real de un mapa del juego con el mismo tileset: suelo,
 *      muros y decoración salen del propio juego, nunca inventados.
 *
 *   2. **Regiones sin acceso.** Al recortar y redimensionar los ecos quedan
 *      zonas transitables desconectadas: trozos de mapa a los que el jugador
 *      no puede llegar nunca. Se abren corredores en L desde la región
 *      principal con el tile de suelo más común del propio mapa, de modo que
 *      el pasillo se ve igual que el resto del suelo.
 *
 *   3. **Huecos.** Las celdas sin ningún tile se rellenan con el suelo del
 *      mapa: nunca queda un agujero negro bajo los pies.
 *
 * No se tocan los eventos: se conservan sus nombres, sus comandos y sus
 * destinos. Únicamente se recoloca sobre una celda transitable el evento que
 * quedó atrapado dentro de un muro al cambiar la geometría.
 *
 * Uso:
 *   node tools/atlas_tile_repair.mjs
 *   node tools/atlas_tile_repair.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { marshalLoad, marshalDump, RHash, RObject, RString } from "../web/js/marshal.js";
import { parseMap, tableGet, tableToUserDef } from "../web/js/rmxp.js";
import { ROOT, DATA } from "./lib/fire_ash_registry.mjs";
import { txt, mapFile, readMap, writeMap } from "./lib/dn_rmxp.mjs";
import { TileCanvas, passabilityOf, reachableCells, tilesets } from "./lib/map_painter.mjs";

const VERIFY = process.argv.includes("--verify");
const HIERARCHY = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "atlas_content_hierarchy.json"), "utf8"));
const AUDIT = path.join(ROOT, "content", "atlas_tile_audit.json");
const BACKUP = path.join(ROOT, "pokemon_fire_ash", "PokeModBackups", "atlas_tile_repair_originals");
const TS = tilesets();

const pad3 = (n) => String(n).padStart(3, "0");
const hashDe = (n) => crypto.createHash("sha256").update(`atlas-tile-repair:${n}`).digest();

/* ─────────────────────────────── lectura ───────────────────────────────── */

function lienzoDe(raw) {
  const parsed = parseMap(raw);
  const canvas = new TileCanvas(parsed.width, parsed.height, parsed.tilesetId);
  for (let z = 0; z < 3; z++) {
    for (let y = 0; y < parsed.height; y++) {
      for (let x = 0; x < parsed.width; x++) canvas.set(x, y, z, tableGet(parsed.table, x, y, z));
    }
  }
  return { canvas, parsed };
}

function vocabulario(canvas) {
  const tiles = new Map();
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      for (let z = 0; z < 3; z++) {
        const t = canvas.get(x, y, z);
        if (t) tiles.set(t, (tiles.get(t) ?? 0) + 1);
      }
    }
  }
  return tiles;
}

/** Tile de suelo: el más usado en la capa 0 que sea totalmente transitable. */
function sueloDe(canvas) {
  const ts = TS.get(canvas.tilesetId);
  const usados = new Map();
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      const t = canvas.get(x, y, 0);
      if (t) usados.set(t, (usados.get(t) ?? 0) + 1);
    }
  }
  const orden = [...usados.entries()].sort((a, b) => b[1] - a[1]);
  for (const [tile] of orden) {
    if (tile >= 384 && (ts?.passages?.data?.[tile] ?? 0) === 0) return tile;
  }
  // Ningún tile del mapa sirve: se busca uno cualquiera del tileset.
  const pases = ts?.passages?.data;
  if (pases) {
    for (let t = 384; t < pases.length; t++) if (pases[t] === 0) return t;
  }
  return 0;
}

/* ───────────────────────── mapas donantes reales ───────────────────────── */

let donantesPorTileset = null;
function donantes() {
  if (donantesPorTileset) return donantesPorTileset;
  donantesPorTileset = new Map();
  for (const archivo of fs.readdirSync(DATA)) {
    const m = /^Map(\d+)\.rxdata$/.exec(archivo);
    if (!m) continue;
    const id = Number(m[1]);
    if (id >= 1000) continue;            // solo mapas originales de Fire Ash
    let parsed;
    try { parsed = parseMap(marshalLoad(fs.readFileSync(path.join(DATA, archivo)))); } catch { continue; }
    if (!parsed.width || parsed.width < 12 || parsed.height < 12) continue;
    const tiles = new Set();
    for (let y = 0; y < parsed.height; y++) {
      for (let x = 0; x < parsed.width; x++) {
        for (let z = 0; z < 3; z++) { const t = tableGet(parsed.table, x, y, z); if (t) tiles.add(t); }
      }
    }
    if (tiles.size < 40) continue;
    const lista = donantesPorTileset.get(parsed.tilesetId) ?? [];
    lista.push({ id, width: parsed.width, height: parsed.height, tiles: tiles.size });
    donantesPorTileset.set(parsed.tilesetId, lista);
  }
  for (const lista of donantesPorTileset.values()) lista.sort((a, b) => b.tiles - a.tiles);
  return donantesPorTileset;
}

function pintar(fuente, canvas, ox, oy) {
  for (let z = 0; z < 3; z++) {
    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        canvas.set(x, y, z, tableGet(fuente.table, ox + (x % fuente.width), oy + (y % fuente.height), z));
      }
    }
  }
}

function calidad(canvas) {
  const pass = passabilityOf(canvas, canvas.tilesetId);
  let libres = 0;
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) if (pass.passable(x, y, 8)) libres++;
  }
  return { ratio: libres / (canvas.width * canvas.height), tiles: vocabulario(canvas).size };
}

/**
 * Copia una ventana real de un mapa del juego al lienzo. Se prueban varios
 * candidatos y se queda con el primero que da un trozo de mapa jugable: suelo
 * suficiente y vocabulario de tiles amplio. Si el mapa de origen es mas grande
 * se recorta una ventana; si es mas pequeno, se repite (nunca se deja vacio).
 */
function sembrar(canvas, semilla) {
  const lista = donantes().get(canvas.tilesetId) ?? [];
  if (!lista.length) return null;
  const h = hashDe(semilla);
  let elegido = null;
  let aceptado = false;
  for (let intento = 0; intento < 10 && !aceptado; intento++) {
    const candidato = lista[(h[intento] + intento * 7) % lista.length];
    const fuente = parseMap(marshalLoad(fs.readFileSync(path.join(DATA, mapFile(candidato.id)))));
    const ox = h[intento + 10] % Math.max(1, fuente.width - Math.min(canvas.width, fuente.width) + 1);
    const oy = h[intento + 11] % Math.max(1, fuente.height - Math.min(canvas.height, fuente.height) + 1);
    pintar(fuente, canvas, ox, oy);
    const q = calidad(canvas);
    aceptado = q.ratio >= 0.15 && q.tiles >= 24;
    if (aceptado) elegido = candidato;
  }
  if (!aceptado) {
    // Último recurso: el candidato con mas tiles del tileset, repetido.
    const candidato = lista[0];
    const fuente = parseMap(marshalLoad(fs.readFileSync(path.join(DATA, mapFile(candidato.id)))));
    pintar(fuente, canvas, 0, 0);
    elegido = candidato;
  }
  return elegido;
}

/* ───────────────────────────── reconexión ──────────────────────────────── */

/** Celdas a las que no se llega ni apareciendo en cada evento del mapa. */
function huerfanas(canvas, eventos) {
  const pass = passabilityOf(canvas, canvas.tilesetId);
  const walkable = [];
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) if (pass.passable(x, y, 8)) walkable.push([x, y]);
  }
  const alcanzable = new Set();
  const arranques = eventos.filter((e) => e.x >= 0 && e.y >= 0 && e.x < canvas.width && e.y < canvas.height && pass.passable(e.x, e.y, 8));
  for (const e of arranques) for (const c of reachableCells(pass, [e.x, e.y])) alcanzable.add(c);
  if (!arranques.length && walkable.length) for (const c of reachableCells(pass, walkable[0])) alcanzable.add(c);
  const perdidas = walkable.filter(([x, y]) => !alcanzable.has(`${x},${y}`));
  return { pass, perdidas, alcanzable };
}

/** Abre un pasillo en L entre dos celdas usando el suelo del propio mapa. */
function abrirPasillo(canvas, desde, hasta, suelo) {
  if (!suelo) return;
  let [x, y] = desde;
  const [tx, ty] = hasta;
  while (x !== tx) {
    for (let z = 0; z < 3; z++) canvas.set(x, y, z, z === 0 ? suelo : 0);
    x += x < tx ? 1 : -1;
  }
  while (y !== ty) {
    for (let z = 0; z < 3; z++) canvas.set(x, y, z, z === 0 ? suelo : 0);
    y += y < ty ? 1 : -1;
  }
  for (let z = 0; z < 3; z++) canvas.set(tx, ty, z, z === 0 ? suelo : 0);
}

/**
 * Conecta las celdas huérfanas con la parte viva del mapa: se abre un pasillo
 * desde la celda alcanzable mas cercana hasta la huérfana mas cercana y se
 * repite hasta que no queda nada aislado (o se agota el presupuesto).
 */
function reconectar(canvas, eventos, maxPasillos = 40) {
  let abiertos = 0;
  for (let ronda = 0; ronda < maxPasillos; ronda++) {
    const { perdidas, alcanzable } = huerfanas(canvas, eventos);
    if (!perdidas.length) break;
    const suelo = sueloDe(canvas);
    if (!suelo) break;
    // La huérfana mas cerca de alguna celda alcanzable.
    let mejor = null;
    let mejorD = Infinity;
    for (const [ox, oy] of perdidas) {
      for (const otra of alcanzable) {
        const [px, py] = otra.split(",").map(Number);
        const d = Math.abs(ox - px) + Math.abs(oy - py);
        if (d < mejorD) { mejorD = d; mejor = [[px, py], [ox, oy]]; }
      }
      if (mejorD <= 1) break;
    }
    if (!mejor) break;
    abrirPasillo(canvas, mejor[0], mejor[1], suelo);
    abiertos++;
  }
  return abiertos;
}

/* ─────────────────────────── reparación de un mapa ─────────────────────── */

function reparar(entrada) {
  const id = entrada.mapId;
  if (!fs.existsSync(path.join(DATA, mapFile(id)))) return null;
  const raw = readMap(id);
  const { canvas } = lienzoDe(raw);
  const antes = vocabulario(canvas);
  const acciones = [];

  // 1. mapa plano o vacío: se le planta una ventana de un mapa real del juego.
  if (antes.size < 8) {
    const donante = sembrar(canvas, id);
    if (donante) acciones.push(`geometría sembrada desde el mapa ${donante.id} (${donante.tiles} tiles)`);
  }

  // 2. huecos: ninguna celda sin suelo.
  let huecos = 0;
  for (let y = 0; y < canvas.height; y++) {
    for (let x = 0; x < canvas.width; x++) {
      let cubierta = false;
      for (let z = 0; z < 3; z++) if (canvas.get(x, y, z)) { cubierta = true; break; }
      if (!cubierta) huecos++;
    }
  }
  if (huecos > 0) {
    const suelo = sueloDe(canvas);
    let rellenados = 0;
    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        let cubierta = false;
        for (let z = 0; z < 3; z++) if (canvas.get(x, y, z)) { cubierta = true; break; }
        if (!cubierta && suelo) { canvas.set(x, y, 0, suelo); rellenados++; }
      }
    }
    if (rellenados) acciones.push(`${rellenados} huecos rellenados con el suelo del mapa`);
  }

  // 3. regiones a las que no se puede llegar.
  const pares = raw.getIvar("@events")?.pairs ?? [];
  const posiciones = () => pares.map(([, ev]) => ({ x: ev.getIvar("@x"), y: ev.getIvar("@y") }));
  const abiertos = reconectar(canvas, posiciones());
  if (abiertos) acciones.push(`${abiertos} pasillos abiertos hacia zonas inaccesibles`);

  // 4. Ningún evento se mueve ni se reescribe: se le abre el suelo debajo.
  // Mover un evento rompería los manifiestos de servicio de Atlas Mil, así que
  // la regla es estricta: el evento se queda donde está y el mapa se abre.
  const pass = passabilityOf(canvas, canvas.tilesetId);
  const suelo = sueloDe(canvas);
  let caminos = 0;
  let sinSalida = 0;
  for (const [, ev] of pares) {
    const x = ev.getIvar("@x");
    const y = ev.getIvar("@y");
    if (x >= 0 && y >= 0 && x < canvas.width && y < canvas.height && pass.passable(x, y, 8)) continue;
    let destino = null;
    let mejorD = Infinity;
    for (let y2 = 0; y2 < canvas.height; y2++) {
      for (let x2 = 0; x2 < canvas.width; x2++) {
        if (!pass.passable(x2, y2, 8)) continue;
        if (x2 === x && y2 === y) continue;
        const d = Math.abs(x2 - x) + Math.abs(y2 - y);
        if (d < mejorD) { mejorD = d; destino = [x2, y2]; }
      }
    }
    if (destino && suelo && x >= 0 && y >= 0 && x < canvas.width && y < canvas.height) {
      abrirPasillo(canvas, destino, [x, y], suelo);
      if (passabilityOf(canvas, canvas.tilesetId).passable(x, y, 8)) { caminos++; continue; }
    }
    sinSalida++;
  }
  if (caminos) acciones.push(`${caminos} suelos abiertos bajo eventos que quedaron dentro de un muro`);
  if (sinSalida) acciones.push(`${sinSalida} eventos sin arreglo posible (se dejan intactos)`);

  if (!acciones.length) return null;

  // Se escribe la nueva geometría conservando todo lo demás del mapa.
  raw.setIvar("@data", tableToUserDef(canvas.toTable()));
  writeMap(id, raw);
  return { id, acciones, tilesAntes: antes.size, tilesDespues: vocabulario(canvas).size };
}

