/**
 * Audita la persistencia de derrotas en el contenido de la expansión y la torre.
 * Regla exigida: "si lo derrotaste una vez, queda derrotado".
 *
 * Patrones aceptados de cierre tras ganar (ambos con canLose para poder reintentar
 * tras perder):
 *   A) IF pbTrainerBattle(...)/pbWildBattle(...) → self-switch o sello → página cerrada.
 *   B) d=pbWildBattleCore(p) + IF d==1 || d==4 → self-switch o contador → página cerrada.
 * Las revanchas solo se aceptan tras elección explícita (menú Rematch/Later).
 * El contenido base del Grandeur Club (etapas de entrenamiento) es repetible por
 * diseño del juego original y se reporta aparte.
 *
 * Uso: node tools/audit_defeat_persistence.mjs
 */
import { readMarshalData } from "./lib/fire_ash_registry.mjs";
import { parseMap, parseEvent } from "../web/js/rmxp.js";

const dec = (value) => (value?.bytes ? Buffer.from(value.bytes).toString("utf8") : String(value ?? ""));
const battlePattern = /pbTrainerBattle|pbWildBattle|pbWildBattleCore|pbBattleStart|pbGhostBattle|pbBeginBattle/;

function argsOf(call, name) {
  const start = call.indexOf("(");
  const inner = call.slice(start + 1, call.lastIndexOf(")"));
  const parts = [];
  let depth = 0;
  let current = "";
  for (const char of inner) {
    if (char === "(") depth++;
    if (char === ")") depth--;
    if (char === "," && depth === 0) { parts.push(current.trim()); current = ""; } else current += char;
  }
  parts.push(current.trim());
  return parts;
}

function canLoseOf(scriptBlock) {
  if (/setBattleRule\("canLose"\)/.test(scriptBlock)) return true;
  for (const line of scriptBlock.split("\n")) {
    if (/pbTrainerBattle\(/.test(line)) {
      const args = argsOf(line.slice(line.indexOf("pbTrainerBattle")));
      if (args.length >= 6 && args[5] === "true") return true;
    }
    if (/pbWildBattle\(/.test(line)) {
      const args = argsOf(line.slice(line.indexOf("pbWildBattle")));
      if (args.length >= 5 && args[4] === "true") return true;
    }
  }
  return false;
}

function analyze(event) {
  const pages = event.pages;
  const battleScripts = pages.flatMap((page) => page.list).map((command) => {
    const code = command.getIvar("code");
    const params = command.getIvar("parameters");
    return code === 111 && params?.[0] === 12 ? dec(params[1]) : (code === 355 || code === 655 ? dec(params[0]) : "");
  }).filter((text) => battlePattern.test(text));
  if (!battleScripts.length) return null;

  const fullBlock = pages.flatMap((page) => page.list).map((command) => {
    const code = command.getIvar("code");
    const params = command.getIvar("parameters");
    return code === 111 && params?.[0] === 12 ? `IF ${dec(params[1])}` : (code === 355 || code === 655 ? dec(params[0]) : "");
  }).filter(Boolean).join("\n");

  let winGated = false;
  let locked = false;
  const sealedSwitches = new Set();
  pages.forEach((page) => {
    const texts = page.list.map((command) => {
      const code = command.getIvar("code");
      const params = command.getIvar("parameters");
      return { code, params, text: code === 111 && params?.[0] === 12 ? dec(params[1]) : (code === 355 || code === 655 ? dec(params[0]) : "") };
    });
    texts.forEach((entry, index) => {
      const isIfBattle = entry.code === 111 && entry.params?.[0] === 12 && battlePattern.test(entry.text);
      const isBattleDo = (entry.code === 355 || entry.code === 655) && battlePattern.test(entry.text);
      const winIfAfterCore = isBattleDo && texts.slice(index + 1, index + 6).some((next) => next.code === 111 && next.params?.[0] === 12 && /d==1 *\|\| *d==4|\$game_switches\[/.test(dec(next.params[1])));
      if (isIfBattle || winIfAfterCore) winGated = true;
    });
    texts.forEach((entry) => {
      if (entry.code === 123 && entry.params?.[1] === 0) locked = true;
      if (entry.code === 121 && entry.params?.[2] === 0) sealedSwitches.add(Number(entry.params?.[0]));
      if (entry.code === 355 || entry.code === 655) {
        const switchSet = entry.text.match(/\$game_switches\[(\d+)\] *= *(?:true|1)/);
        if (switchSet) sealedSwitches.add(Number(switchSet[1]));
      }
    });
  });
  if (sealedSwitches.size) locked = true;

  const postPage = pages.slice(1).some((page) =>
    page.condition.selfSwitch === "A" ||
    (page.condition.switch1 > 0 && (sealedSwitches.has(Number(page.condition.switch1)) || page.condition.switch1 >= 700)));
  const persistent = winGated && locked && postPage;

  const defeatedPages = pages.filter((page) => page.condition.selfSwitch === "A" || (page.condition.switch1 > 0 && page.condition.switch1 >= 700));
  const optionalRematch = defeatedPages.some((page) => page.list.some((command) => command.getIvar("code") === 102 || /revancha|Rematch|repetirse|repetir/i.test(dec(command.getIvar("parameters")?.[0]))));

  return {
    id: event.id,
    name: event.name,
    battles: battleScripts.length,
    persistent,
    winGated,
    optionalRematch,
    canLose: canLoseOf(fullBlock),
  };
}

const zones = [
  { name: "Torre Grandeur Club (141/151/214) — etapas de entrenamiento del juego base", maps: [141, 151, 214], vanilla: true },
  { name: "Isla Espejo / Ciudad Teckel (997-999)", maps: [997, 998, 999], wild: true },
  { name: "Bosque/Hypno + Horizontes (1000-1020)", maps: Array.from({ length: 21 }, (_, i) => 1000 + i) },
  { name: "Atlas Mil (1021-2020)", maps: Array.from({ length: 1000 }, (_, i) => 1021 + i), atlasPokegods: true },
  { name: "Monte Silver — Emisiones (2021-2029)", maps: Array.from({ length: 9 }, (_, i) => 2021 + i) },
  { name: "Expansión Multiversal (2191-2194)", maps: [2191, 2192, 2193, 2194] },
];

let totalBattles = 0;
let totalEvents = 0;
let totalPersistent = 0;
let totalRematch = 0;
const anomalies = [];

console.log("Persistencia de derrotas — «si lo derrotaste una vez, queda derrotado\"\n");
for (const zone of zones) {
  const events = [];
  for (const mapId of zone.maps) {
    let map;
    try { map = parseMap(readMarshalData(`Map${mapId}.rxdata`)); } catch { continue; }
    for (const { obj } of map.events) {
      const result = analyze(parseEvent(obj));
      if (result) events.push({ mapId, ...result });
    }
  }
  const persistent = events.filter((entry) => entry.persistent);
  const rematches = events.filter((entry) => entry.optionalRematch);
  const noLose = events.filter((entry) => !entry.canLose);
  const repeats = events.filter((entry) => !entry.persistent);
  totalBattles += events.reduce((sum, entry) => sum + entry.battles, 0);
  totalEvents += events.length;
  totalPersistent += persistent.length;
  totalRematch += rematches.length;
  console.log(`${zone.name}`);
  console.log(`  ${events.length} eventos con batalla | derrota permanente: ${persistent.length} | revancha opcional (menú): ${rematches.length} | canLose: ${events.length - noLose.length}/${events.length}`);
  for (const entry of repeats) {
    // Los Pokégods son encuentros salvajes con tres Formas de Anomalía: se
    // repiten a propósito, igual que el resto de la fauna de la isla. En el
    // Atlas Mil los Pokégods repartidos por la dimensión conservan ese mismo
    // diseño (fauna anómala repetible), y la fauna errante de Ciudad Teckel
    // también. Un líder con revancha pedida por menú (opcional) no es anomalía.
    const wild = zone.wild ?? false;
    const pokégod = (wild || zone.atlasPokegods) && /PokeMod Pokégod:/.test(entry.name);
    const faunaTeckel = wild && /errante/.test(entry.name);
    const revanchaOpcional = entry.optionalRematch;
    const label = zone.vanilla ? "repetible por diseño del club base"
      : pokégod ? "salvaje repetible (Pokégod)"
      : faunaTeckel ? "fauna errante repetible (Teckel)"
      : revanchaOpcional ? "revancha opcional por menú"
      : "¡ANOMALÍA!";
    console.log(`  [${label}] Map${entry.mapId} ev${entry.id} ${JSON.stringify(entry.name)}`);
    if (!zone.vanilla && !pokégod && !faunaTeckel && !revanchaOpcional) anomalies.push({ mapId: entry.mapId, ...entry });
  }
  for (const entry of noLose) {
    console.log(`  [sin canLose] Map${entry.mapId} ev${entry.id} ${JSON.stringify(entry.name)}`);
    if (!zone.vanilla) anomalies.push({ mapId: entry.mapId, ...entry, issue: "sin canLose" });
  }
}
console.log(`\nTOTAL: ${totalBattles} batallas en ${totalEvents} eventos; derrota permanente ${totalPersistent}/${totalEvents}; revanchas opcionales por menú: ${totalRematch}.`);
if (anomalies.length) {
  console.log(`ANOMALÍAS en contenido de la expansión: ${anomalies.length}`);
  process.exitCode = 1;
} else {
  console.log("Sin anomalías: todo el contenido de la expansión queda derrotado tras ganar (con reintentos tras perder) y las revanchas son opcionales.");
}#!/usr/bin/env python3
"""Respalda partidas + Data + PBS + Game.ini a un ZIP con fecha. Nunca borra nada.

Uso:
    python tools/backup.py "C:/Juegos/FireAsh"
    python tools/backup.py game --out mis_backups
"""
import argparse, os, zipfile
from datetime import datetime

INCLUDE_DIRS = ("Data", "PBS")
INCLUDE_FILES = ("Game.ini",)


def is_save(base: str) -> bool:
    b = base.lower()
    return (b.startswith("save") and b.endswith(".rxdata")) or b == "game.rxdata" or b.endswith(".sav")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("game_dir", help="carpeta del juego")
    ap.add_argument("--out", default=None, help="carpeta destino (defecto: <juego>/PokeModBackups)")
    args = ap.parse_args()
    game = os.path.abspath(args.game_dir)
    outdir = args.out or os.path.join(game, "PokeModBackups")
    os.makedirs(outdir, exist_ok=True)
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    dest = os.path.join(outdir, f"backup_{ts}.zip")
    n = 0
    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED) as z:
        for root, _dirs, files in os.walk(game):
            # no respaldar backups dentro de backups
            if os.path.abspath(root).startswith(os.path.abspath(outdir) + os.sep) and root != game:
                continue
            for f in files:
                full = os.path.join(root, f)
                rel = os.path.relpath(full, game)
                top = rel.split(os.sep)[0]
                if top in INCLUDE_DIRS or (os.sep not in rel and (f in INCLUDE_FILES or is_save(f))):
                    z.write(full, rel)
                    n += 1
    print(f"Backup: {n} archivos → {dest}")


if __name__ == "__main__":
    main()#!/usr/bin/env node
/**
 * Empaqueta `Scripts_corregido/Paquete_directo/` en el ZIP descargable.
 *
 * El ZIP se descomprime directamente sobre la raíz del juego (la que tiene
 * `Game.exe`): las carpetas `Data`, `Graphics` y `Audio` van en la raíz, sin
 * una carpeta intermedia. Además incluye `LEEME.txt` generado a partir de
 * `LEEME.md` para que las instrucciones viajen dentro del archivo.
 *
 * Uso:
 *   node tools/build_direct_package.mjs           # reconstruye el ZIP
 *   node tools/build_direct_package.mjs --verify  # solo comprueba el ZIP actual
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { listFiles, readZipEntry, readZipIndex, writeZip } from "./lib/zip_writer.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const PACKAGE = path.join(ROOT, "Scripts_corregido");
const DIRECT = path.join(PACKAGE, "Paquete_directo");
const ZIP = path.join(PACKAGE, "Fire_Ash_Paquete_Directo.zip");
const README_MD = path.join(PACKAGE, "LEEME.md");
const README_TXT = "LEEME.txt";
const VERIFY_ONLY = process.argv.includes("--verify");

/** Convierte el LEEME en Markdown a texto plano legible dentro del ZIP. */
export function leemeToText(markdown) {
  return `${markdown
    .replace(/^```[a-z]*$/gm, "")
    .replace(/^(#{1,6})\s+/gm, "")
    .replace(/\*\*(.+?)\*\*/g, "$1")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/\n{3,}/g, "\n\n")
    .trim()}\n`;
}

function readmeText() {
  if (!fs.existsSync(README_MD)) throw new Error(`Falta ${README_MD}`);
  return leemeToText(fs.readFileSync(README_MD, "utf8"));
}

export function build() {
  if (!fs.existsSync(DIRECT)) throw new Error(`Falta ${DIRECT}`);
  writeZip({ root: DIRECT, destination: ZIP, extraFiles: { [README_TXT]: readmeText() } });
}

export function verify() {
  if (!fs.existsSync(ZIP)) throw new Error("Falta Fire_Ash_Paquete_Directo.zip: ejecútalo sin --verify");
  const expected = new Set([...listFiles(DIRECT), README_TXT]);
  const zip = readZipIndex(ZIP);
  const actual = new Set(zip.entries.keys());

  for (const name of expected) {
    if (!actual.has(name)) throw new Error(`El ZIP no incluye ${name}`);
  }
  for (const name of actual) {
    if (!expected.has(name)) throw new Error(`El ZIP trae un archivo inesperado: ${name}`);
    if (name.includes("..") || name.startsWith("/")) throw new Error(`Ruta insegura en el ZIP: ${name}`);
  }
  for (const name of expected) {
    const onDisk = name === README_TXT ? Buffer.from(readmeText(), "utf8") : fs.readFileSync(path.join(DIRECT, name));
    const inZip = readZipEntry(zip, name);
    if (!onDisk.equals(inZip)) throw new Error(`El contenido de ${name} no coincide con Paquete_directo/`);
  }
  return { files: expected.size, bytes: fs.statSync(ZIP).size };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (!VERIFY_ONLY) build();
  const result = verify();
  console.log(
    `OK: Fire_Ash_Paquete_Directo.zip con ${result.files} archivos (${(result.bytes / 1024).toFixed(0)} KB)`,
  );
}#!/usr/bin/env node
/**
 * Construye un parche QA independiente para «Pokémon Fire Ash: Ashen Guardian».
 * No altera `Fire_Ash_Paquete_Directo.zip` ni la carpeta de La Ruta de Dios.
 * El ZIP se extrae sobre la raíz de una copia de Fire Ash 3.7.1 (Data/ y Graphics/).
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
import { marshalDump, marshalLoad, RString } from "../web/js/marshal.js";
import { listFiles, readZipEntry, readZipIndex, writeZip } from "./lib/zip_writer.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const GRAPHICS = path.join(GAME, "Graphics");
const AUDIO_BGM = path.join(GAME, "Audio", "BGM");
const AUDIO_MANIFEST = path.join(ROOT, "content", "dimensional_nightmare_audio.json");
const OUTPUT = path.join(ROOT, "Scripts_corregido", "Dimensional_Nightmare_QA");
const ZIP = path.join(ROOT, "Scripts_corregido", "Dimensional_Nightmare_QA.zip");
const FIXED_SCRIPTS = path.join(ROOT, "Scripts_corregido", "Scripts.rxdata");
const DN_RUNTIME = path.join(ROOT, "content", "dimensional_nightmare_runtime.rb");
const README_NAME = "LEEME_QA.txt";
const MANIFEST_NAME = "QA_MANIFEST.json";
const VERIFY_ONLY = process.argv.includes("--verify");

const MAP_IDS = [2030, ...Array.from({ length: 151 }, (_, index) => 2040 + index)];
const POSTGAME_MAP_FILES = [
  "Map033.rxdata",
  "Map513.rxdata",
  "Map625.rxdata",
  ...Array.from({ length: 38 }, (_, index) => `Map${2001 + index}.rxdata`),
];
const DATA_FILES = [
  "MapInfos.rxdata", "System.rxdata", "Tilesets.rxdata", "map_metadata.dat", "encounters.dat",
  "items.dat", "trainers.dat", "trainertypes.dat", "trainer_types.dat",
  "trainerlists.dat", "trainer_lists.dat",
];
const POSTGAME_ASSETS = [
  "Graphics/Characters/ash_outfit_creep.png",
  "Graphics/Characters/ARCEUS.png",
  "Graphics/Characters/ARCEUS_GATE.png",
  "Graphics/Characters/ARC_Cynthia.png",
  "Graphics/Characters/ARC_Ethan.png",
  "Graphics/Characters/ARC_Steven.png",
  "Graphics/Characters/DIALGA.png",
  "Graphics/Characters/Object ball special.png",
  "Graphics/Characters/PALKIA.png",
  "Graphics/Characters/SECRET_Red.png",
  "Graphics/Characters/SECRET_Volo.png",
  "Graphics/Characters/SQUIRTLE.png",
  "Graphics/Characters/ash_outfit_creep.png",
  "Audio/BGM/Legend Sinnoh.ogg",
  "Graphics/Pictures/Trainer Card/icon_badges.png",
  "Audio/BGM/secretvolo.ogg",
];
const COPY_GRAPHIC_DIRS = [
  "Autotiles", "Characters", "Items", "Pictures", "Pokemon/Front", "Trainers",
];
const TITLE_GRAPHIC = "Titles/title.png";

const README = `PAQUETE QA — POKÉMON FIRE ASH: ASHEN GUARDIAN
==================================================

Este parche independiente prepara el contenido Dimensional Nightmare / Protector de la Ceniza
para una prueba manual. Es una entrega interna de QA, no una distribución pública de recursos.
Los mosaicos derivados se incluyen únicamente para que el juego pueda cargarlos durante esta prueba.

COMPATIBILIDAD
--------------
- Diseñado para una copia limpia de Pokémon Fire Ash 3.7.1 con RPG Maker XP / Essentials v19.
- Instálalo en una copia separada del juego. El ZIP no incluye Game.exe, partidas ni Game.rxdata.
- Incluye los datos, gráficos originales y pistas MIDI propias del contenido DN, nombres de flags
  y una copia del Scripts.rxdata corregido con un módulo Runtime DN aislado (batalla espejo y
  secuencia final de EP06). El archivo compartido del paquete de La Ruta de Dios no se modifica.

INSTALACIÓN
-----------
1. Cierra Fire Ash y el emulador/launcher.
2. Duplica la carpeta del juego y conserva intacta la original.
3. Haz una copia adicional de tus partidas. No se deben reemplazar ni borrar Game.rxdata o Save*.
4. Extrae Dimensional_Nightmare_QA.zip directamente en la raíz de la copia, junto a Game.exe y
   Game.ini. Acepta reemplazar Data/Scripts.rxdata, Data/MapInfos.rxdata, Data/System.rxdata,
   Data/Tilesets.rxdata, los mapas listados, los gráficos y Audio/BGM/DN_*.mid.
5. No dejes Data/ ni Graphics/ dentro de una carpeta intermedia llamada
   Dimensional_Nightmare_QA/; deben quedar directamente bajo la raíz del juego.
6. Inicia una partida postgame en la copia. La entrada está en la Gruta de los Testigos (Map2030),
   junto a la llegada de la Antesala. El primer anillo requiere v264 ≥ 3; el contenido tardío conserva
   las condiciones narrativas indicadas por el juego (incluidos los 7 sellos de Monte Silver).

RECORRIDO DE QA SUGERIDO
------------------------
- Prueba el acceso a la Antesala y confirma que las puertas cerradas explican qué falta.
- Visita EP01–EP06, el Nexo, la Liga Oscura y W7–W9; usa las salidas y retornos de cada zona.
- Habla varias veces con NPC normales, conscientes e interdimensionales. Sus páginas recuerdan
  visitas, se mueven según su papel y reaccionan al cambio de fase.
- Inspecciona el hito de Rotom de cada mapa. Registra anomalías, objetos, pedestales y estatuas.
- Prueba las diez decisiones opcionales y consulta la Vitrina del Testigo en la Antesala.
- Pierde y reintenta los combates; comprueba fase B, curación, recompensas únicas y regreso seguro.
- Comprueba el subtítulo Ashen Guardian, las BGM MIDI originales, el silencio de EP05 (2104–2109) y el fade/restauración del silenciador de EP04.
- Comprueba que los tonos/fases vuelvan a neutro al salir y que v264 no cambie al recorrer el Nightmare; DN sólo lo consulta como contador externo.

LIMITACIONES CONOCIDAS
----------------------
- Esta entrega pasó verificación estática y de empaquetado; no se ha ejecutado en Game.exe/Kirin.
- La QA manual sigue pendiente. Si detectas un error, anota mapa, coordenadas, flags y pasos para
  reproducirlo antes de restaurar la copia limpia.
- No redistribuyas el paquete ni los gráficos de referencia fuera de esta prueba.

La carpeta descomprimida equivalente está en Scripts_corregido/Dimensional_Nightmare_QA/.
`;

function sha256(bytes) {
  return crypto.createHash("sha256").update(bytes).digest("hex");
}
function ensureSource(source, description) {
  if (!fs.existsSync(source)) throw new Error(`Falta ${description}: ${path.relative(ROOT, source)}`);
}
function copyFile(source, relative) {
  ensureSource(source, relative);
  const destination = path.join(OUTPUT, relative);
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.copyFileSync(source, destination);
}
function runtimePatchedScripts() {
  ensureSource(FIXED_SCRIPTS, "Scripts.rxdata corregido base");
  ensureSource(DN_RUNTIME, "Runtime Ruby de Dimensional Nightmare");
  const scripts = marshalLoad(fs.readFileSync(FIXED_SCRIPTS));
  if (!Array.isArray(scripts)) throw new Error("Scripts.rxdata no contiene una lista de secciones");
  const runtimeCode = fs.readFileSync(DN_RUNTIME, "utf8");
  const compressed = new RString(zlib.deflateSync(Buffer.from(runtimeCode, "utf8")));
  const existingIndex = scripts.findIndex((entry) => entry?.[1]?.text === "DN_RuntimeSupport");
  if (existingIndex >= 0) {
    scripts[existingIndex][2] = compressed;
  } else {
    const numericIds = scripts.map((entry) => Number(entry?.[0])).filter(Number.isFinite);
    const newId = Math.max(0, ...numericIds) + 1;
    const mainIndex = scripts.findIndex((entry) => entry?.[1]?.text === "Main");
    const newSection = [newId, RString.fromText("DN_RuntimeSupport"), compressed];
    scripts.splice(mainIndex >= 0 ? mainIndex : scripts.length, 0, newSection);
  }
  return Buffer.from(marshalDump(scripts));
}

function runtimeCodeInScripts(bytes) {
  const scripts = marshalLoad(bytes);
  const section = scripts.find((entry) => entry?.[1]?.text === "DN_RuntimeSupport");
  if (!section?.[2]?.bytes) throw new Error("Data/Scripts.rxdata no contiene DN_RuntimeSupport");
  return zlib.inflateSync(Buffer.from(section[2].bytes)).toString("utf8");
}

function tileNamesUsedByNewMaps() {
  const tilesets = marshalLoad(fs.readFileSync(path.join(DATA, "Tilesets.rxdata")));
  const names = new Set();
  for (const mapId of MAP_IDS) {
    const file = path.join(DATA, `Map${mapId}.rxdata`);
    ensureSource(file, `Map${mapId}.rxdata`);
    const map = marshalLoad(fs.readFileSync(file));
    const tilesetId = Number(map.getIvar("@tileset_id"));
    const tileset = tilesets[tilesetId];
    if (!tileset) throw new Error(`Map${mapId}: tileset ${tilesetId} no existe en Tilesets.rxdata`);
    const name = tileset.getIvar("@tileset_name")?.text;
    if (name?.startsWith("DN_")) names.add(name);
  }
  return [...names].sort((a, b) => a.localeCompare(b, "en"));
}
function customGraphics() {
  const files = [];
  for (const directory of COPY_GRAPHIC_DIRS) {
    const full = path.join(GRAPHICS, directory);
    if (!fs.existsSync(full)) continue;
    for (const name of fs.readdirSync(full)) {
      if (!/^DN_.*\.png$/i.test(name)) continue;
      files.push(path.join(directory, name).replaceAll(path.sep, "/"));
    }
  }
  return files.sort();
}
function customAudio() {
  if (!fs.existsSync(AUDIO_BGM)) return [];
  return fs.readdirSync(AUDIO_BGM).filter((name) => /^DN_.*\.mid$/i.test(name)).sort()
    .map((name) => `Audio/BGM/${name}`);
}
function cleanOutput() {
  if (fs.existsSync(OUTPUT)) fs.rmSync(OUTPUT, { recursive: true, force: true });
  fs.mkdirSync(OUTPUT, { recursive: true });
}
function createManifest() {
  const entries = listFiles(OUTPUT).filter((name) => name !== MANIFEST_NAME).sort().map((name) => {
    const bytes = fs.readFileSync(path.join(OUTPUT, name));
    return { path: name, bytes: bytes.length, sha256: sha256(bytes) };
  });
  const manifest = {
    package: "Pokémon Fire Ash: Ashen Guardian — Dimensional Nightmare QA",
    version: "2026-10-02",
    baseGame: "Pokémon Fire Ash 3.7.1",
    installRoot: "Game.exe / Game.ini",
    intendedForManualQA: true,
    includesSaveFiles: false,
    maps: MAP_IDS,
    customTilesets: tileNamesUsedByNewMaps(),
    files: entries,
  };
  fs.writeFileSync(path.join(OUTPUT, MANIFEST_NAME), `${JSON.stringify(manifest, null, 2)}\n`);
  return manifest;
}

export function build() {
  cleanOutput();
  fs.mkdirSync(path.join(OUTPUT, "Data"), { recursive: true });
  for (const name of MAP_IDS) copyFile(path.join(DATA, `Map${name}.rxdata`), `Data/Map${name}.rxdata`);
  for (const name of POSTGAME_MAP_FILES) copyFile(path.join(DATA, name), `Data/${name}`);
  for (const name of DATA_FILES) copyFile(path.join(DATA, name), `Data/${name}`);
  const scriptsDestination = path.join(OUTPUT, "Data/Scripts.rxdata");
  fs.writeFileSync(scriptsDestination, runtimePatchedScripts());

  const tilesetNames = tileNamesUsedByNewMaps();
  for (const name of tilesetNames) copyFile(path.join(GRAPHICS, "Tilesets", `${name}.png`), `Graphics/Tilesets/${name}.png`);
  for (const name of customGraphics()) copyFile(path.join(GRAPHICS, name), `Graphics/${name}`);
  for (const name of customAudio()) copyFile(path.join(AUDIO_BGM, path.basename(name)), name);
  for (const rel of POSTGAME_ASSETS) copyFile(path.join(GAME, rel), rel);
  copyFile(path.join(GRAPHICS, TITLE_GRAPHIC), `Graphics/${TITLE_GRAPHIC}`);
  fs.writeFileSync(path.join(OUTPUT, README_NAME), README, "utf8");
  const manifest = createManifest();
  writeZip({ root: OUTPUT, destination: ZIP });
  return { maps: MAP_IDS.length + POSTGAME_MAP_FILES.length - 1, tilesets: manifest.customTilesets.length, files: manifest.files.length + 1, bytes: fs.statSync(ZIP).size };
}

export function verify() {
  ensureSource(ZIP, "Dimensional_Nightmare_QA.zip; ejecútalo sin --verify");
  ensureSource(OUTPUT, "carpeta QA descomprimida");
  const expected = new Set(listFiles(OUTPUT));
  const archive = readZipIndex(ZIP);
  const actual = new Set(archive.entries.keys());
  for (const name of expected) if (!actual.has(name)) throw new Error(`ZIP sin el archivo ${name}`);
  for (const name of actual) {
    if (!expected.has(name)) throw new Error(`Archivo inesperado en el ZIP: ${name}`);
    if (name.startsWith("/") || name.split("/").includes("..")) throw new Error(`Ruta insegura en el ZIP: ${name}`);
  }
  for (const name of expected) {
    const disk = fs.readFileSync(path.join(OUTPUT, name));
    const inZip = readZipEntry(archive, name);
    if (!disk.equals(inZip)) throw new Error(`Diferencia carpeta/ZIP: ${name}`);
  }

  const manifest = JSON.parse(fs.readFileSync(path.join(OUTPUT, MANIFEST_NAME), "utf8"));
  const expectedEntries = new Set(manifest.files.map((entry) => entry.path));
  const actualEntries = new Set([...expected].filter((name) => name !== MANIFEST_NAME));
  if (expectedEntries.size !== actualEntries.size || [...actualEntries].some((name) => !expectedEntries.has(name))) {
    throw new Error("QA_MANIFEST.json no coincide con la carpeta de entrega");
  }
  for (const entry of manifest.files) {
    const bytes = fs.readFileSync(path.join(OUTPUT, entry.path));
    if (bytes.length !== entry.bytes || sha256(bytes) !== entry.sha256) throw new Error(`Hash incorrecto: ${entry.path}`);
  }
  if (expected.has("Data/Game.rxdata") || [...expected].some((name) => /(?:^|\/)(?:Game|Save\d*)\.rxdata$/i.test(name))) {
    throw new Error("El paquete contiene una partida o Game.rxdata; no debe empaquetarse");
  }
  for (const name of MAP_IDS) if (!expected.has(`Data/Map${name}.rxdata`)) throw new Error(`Falta Map${name}.rxdata`);
  for (const name of POSTGAME_MAP_FILES) if (!expected.has(`Data/${name}`)) throw new Error(`Falta ${name}`);
  for (const rel of POSTGAME_ASSETS) if (!expected.has(rel)) throw new Error(`Falta asset de postgame: ${rel}`);
  for (const required of [
    "Data/Scripts.rxdata", "Data/MapInfos.rxdata", "Data/System.rxdata", "Data/Tilesets.rxdata",
    "Data/map_metadata.dat", "Data/encounters.dat", "Data/items.dat", "Data/trainers.dat", `Graphics/${TITLE_GRAPHIC}`, README_NAME,
  ]) if (!expected.has(required)) throw new Error(`Falta archivo imprescindible: ${required}`);
  ensureSource(AUDIO_MANIFEST, "manifiesto de música DN");
  const audioManifest = JSON.parse(fs.readFileSync(AUDIO_MANIFEST, "utf8"));
  if (!audioManifest.originalComposition || !audioManifest.tracks?.length) throw new Error("El manifiesto DN debe declarar temas originales");
  for (const track of audioManifest.tracks) {
    if (!expected.has(track.file)) throw new Error(`Falta pista original en el ZIP: ${track.file}`);
    const bytes = fs.readFileSync(path.join(OUTPUT, track.file));
    if (bytes.length !== track.bytes || sha256(bytes) !== track.sha256) throw new Error(`Pista del ZIP distinta del manifiesto: ${track.file}`);
  }
  const packagedScripts = fs.readFileSync(path.join(OUTPUT, "Data/Scripts.rxdata"));
  const packagedRuntime = runtimeCodeInScripts(packagedScripts);
  if (packagedRuntime !== fs.readFileSync(DN_RUNTIME, "utf8")) throw new Error("DN_RuntimeSupport del ZIP está desactualizado");
  const result = { files: expected.size, bytes: fs.statSync(ZIP).size, maps: MAP_IDS.length, tilesets: manifest.customTilesets.length };
  console.log(`QA del paquete OK: ${result.maps} mapas · ${result.tilesets} tilesets DN · ${result.files} archivos · ${(result.bytes / 1048576).toFixed(1)} MB`);
  return result;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (!VERIFY_ONLY) {
    const built = build();
    console.log(`generado: Scripts_corregido/Dimensional_Nightmare_QA.zip (${built.files} archivos, ${(built.bytes / 1048576).toFixed(1)} MB)`);
  }
  verify();
}#!/usr/bin/env node
/**
 * Empaqueta la Expansión Multiversal para instalarla sobre una copia de
 * Pokémon Fire Ash 3.7.1.
 *
 * La lista de archivos no está escrita a mano: se deriva del plano
 * (content/expansion_multiversal.json) y del plantel Pokégod
 * (content/pokegods_originales.json), de modo que si el arco crece, el paquete
 * crece con él sin que nadie se acuerde de actualizar una lista.
 *
 * Salida:
 *   Scripts_corregido/Expansion_Multiversal/                 carpeta lista
 *   Scripts_corregido/Fire_Ash_Expansion_Multiversal.zip     ZIP para extraer
 *
 * Uso:
 *   node tools/build_expansion_package.mjs            # construye y verifica
 *   node tools/build_expansion_package.mjs --verify    # solo verifica (CI)
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad } from "../web/js/marshal.js";
import { GAME, ROOT } from "./lib/fire_ash_registry.mjs";
import { assertSameFile } from "./lib/package_integrity.mjs";
import { readZipIndex, writeZip } from "./lib/zip_writer.mjs";

const VERIFY = process.argv.includes("--verify");
const DATA = path.join(GAME, "Data");
const OUTPUT = path.join(ROOT, "Scripts_corregido", "Expansion_Multiversal");
const ZIP = path.join(ROOT, "Scripts_corregido", "Fire_Ash_Expansion_Multiversal.zip");
const PLAN = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "expansion_multiversal.json"), "utf8"));
const POKEGODS = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "pokegods_originales.json"), "utf8"));
const ZIP_STAMP = new Date(Date.UTC(2024, 0, 1));

// ------------------------------------------------------------------ archivos
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;
const maps = new Set([
  PLAN.oakLab.mapId,                                   // laboratorio de Oak
  ...PLAN.rifts.map((rift) => rift.world.mapId),       // las siete grietas
  ...PLAN.rifts.map((rift) => rift.emissionMap),       // emisiones (salida nueva)
  PLAN.collapse.mapId, PLAN.collapse.targetMap,        // Torre Pokémon 1F y falda
  PLAN.falda.mapId, PLAN.darkLeague.gate.mapId,        // falda y cumbre
  ...PLAN.darkLeague.maps.map((map) => map.mapId),     // Liga Oscura
  PLAN.atlas.captainMap, PLAN.atlas.dock.mapId,        // Ciudad Carmín y muelle
  PLAN.mirror.mansionMap, PLAN.mirror.basement.mapId, PLAN.mirror.islandMap,
  998, 999,                                            // resto de la Isla Espejo
  2195, 2196,                                          // Vía de las Nueve Eras y su gimnasio
  2200, 2201, 2210, 2211,                              // Glazed y Light Platinum
  2220, 2221,                                          // dimensión Team Rocket
  2230,                                                // Avenida de los Ocho Gimnasios
  2240, 2241, 2242, 2243, 2244, 2245,                  // Liquid Crystal, TFOH y Factory Adventure
  ...Array.from({ length: 8 }, (_, i) => 2250 + i),     // los ocho gimnasios de Atlas
]);

/** Copias de charsets que usan los eventos verdes de los mapas incluidos. */
function eventCharacterAssets() {
  const names = new Set(["ash_outfit_creep"]);
  for (const mapId of maps) {
    const file = path.join(DATA, mapFile(mapId));
    if (!fs.existsSync(file)) continue;
    const map = marshalLoad(fs.readFileSync(file));
    const events = map.getIvar("@events")?.pairs ?? [];
    for (const [, event] of events) for (const page of event.getIvar("@pages") ?? []) {
      const graphic = page.getIvar("@graphic");
      const name = graphic?.getIvar("@character_name")?.text ?? "";
      if (name.startsWith("DN_")) names.add(name);
    }
  }
  return [...names].sort();
}

function greenTilesetAssets() {
  const tilesets = marshalLoad(fs.readFileSync(path.join(DATA, "Tilesets.rxdata")));
  const files = new Set();
  for (const mapId of maps) {
    const file = path.join(DATA, mapFile(mapId));
    if (!fs.existsSync(file)) continue;
    const map = marshalLoad(fs.readFileSync(file));
    const tileset = tilesets[Number(map.getIvar("@tileset_id"))];
    if (!tileset) throw new Error(`Map${mapId}: tileset ausente al construir el paquete`);
    const name = tileset.getIvar("@tileset_name")?.text ?? "";
    if (name.startsWith("DN_")) files.add(`Graphics/Tilesets/${name}.png`);
    for (const auto of tileset.getIvar("@autotile_names") ?? []) {
      const autoName = auto?.text ?? "";
      if (autoName.startsWith("DN_")) files.add(`Graphics/Autotiles/${autoName}.png`);
    }
  }
  return [...files].sort();
}

/** Archivos del arco, siempre relativos a la raíz del juego. */
function fileList() {
  const files = [
    "Data/MapInfos.rxdata",     // nombres de los mapas nuevos
    "Data/Tilesets.rxdata",     // copias verdes con pasabilidad original
    "Data/map_metadata.dat",    // metadatos de los mapas nuevos
    "Data/trainers.dat",        // los cinco combates de la Liga Oscura y los diez del Gimnasio de las Eras
    "Data/trainer_types.dat",   // tipos de las Eras, las dimensiones y el circuito
    "Data/items.dat",           // medallas de las Eras, Glazed, Platino, Rocket y Atlas
    "Data/species.dat",         // los doce Pokégods
  ];
  for (const id of [...maps].sort((a, b) => a - b)) files.push(`Data/${mapFile(id)}`);
  for (const entry of POKEGODS.roster) {
    files.push(`Graphics/Pokemon/Front/${entry.id}.png`);
    files.push(`Graphics/Pokemon/Back/${entry.id}.png`);
    files.push(`Graphics/Pokemon/Icons/${entry.id}.png`);
    files.push(`Graphics/Characters/${entry.id}.png`);
    files.push(`Audio/SE/${entry.id}.ogg`);
  }
  files.push("Graphics/Characters/ARCEUS_GATE.png");  // sprite de las grietas
  for (const name of eventCharacterAssets()) files.push(`Graphics/Characters/${name}.png`);
  files.push(...greenTilesetAssets());
  return [...new Set(files)];
}

const README = `PAQUETE — EXPANSIÓN MULTIVERSAL (POKÉMON FIRE ASH 3.7.1)
=========================================================

Arco posterior a «La Ruta de Dios». No añade ningún menú de viaje: todo se
descubre andando por Kanto y Johto. El laboratorio de Oak vuelve a tener solo
sus dos transportadores originales y Oak actúa como consejero.

QUÉ INSTALA
-----------
- Siete grietas purgables en Torre Pokémon, Islas Espuma, Monte Moon, Torre
  Quemada, Planta de Energía, Ruinas Alfa y Mansión Pokémon.
- Las siete emisiones y la Liga Oscura llevan arte de cuatro tonos Game Boy;
  los tiles RMXP siguen siendo de 32 px y cada mapa respeta el límite de tres
  personajes visibles.
- Punto de colapso en la Torre Pokémon 1F y Liga Oscura (dos mapas, cinco
  combates que se pueden perder: dos en el umbral y tres en la arena).
- Expedición a Atlas Mil: capitán en el puerto de Ciudad Carmín y muelle propio.
- Cinco ROMs reinterpretadas como dimensiones separadas: Glazed, Light
  Platinum, Liquid Crystal, TFOH y Factory Adventure; Ash entra como visitante
  y cada orilla conserva un barco de retorno libre.
- Sótano sellado de la Mansión Pokémon con el espejo que abre la Isla Espejo.
- Los doce Pokégods con sus tres Formas de Anomalía.

REQUISITOS
----------
1. Una copia de Pokémon Fire Ash 3.7.1 con el postgame activo (switch 429:
   termina el evento de Mew y vuelve a casa).
2. Tener instalado el contenido previo del proyecto (La Ruta de Dios y, si
   quieres recorrerlo, el paquete Dimensional Nightmare): este arco usa el
   Monte Silver y el contador de purgas, y no los incluye por duplicado.

INSTALACIÓN
-----------
1. Cierra Fire Ash y Kirin.
2. Trabaja sobre una copia del juego y guarda tus partidas aparte.
   No reemplaces ni borres Game.rxdata ni los archivos Save*.
3. Extrae Fire_Ash_Expansion_Multiversal.zip en la raíz de la copia, la que
   contiene Game.exe y Game.ini. Acepta reemplazar los archivos existentes.
4. Las carpetas Data/, Graphics/ y Audio/ deben quedar directamente bajo la
   raíz del juego, sin una carpeta intermedia Expansion_Multiversal/.
5. Inicia el juego y carga tu partida postgame.

CÓMO SE JUEGA
-------------
- Grietas: aparecen en los siete lugares; cada una avisa y pregunta
  «Entrar / Retirarse». Al tumbar al jefe de la emisión, la línea temporal se
  purga (\\v[264] sube) y la grieta se convierte en una cicatriz tranquila.
  Cada emisión tiene un «Volver al mundo» que te deja donde entraste.
- Con 7 purgas: punto de colapso en la Torre Pokémon 1F → Monte Silver.
- Con 8 purgas (incluido el Campeón Silencioso): umbral de la Liga Oscura en la
  cumbre, con salida al mundo siempre disponible.
- Atlas Mil: habla con el capitán en el puerto de Ciudad Carmín.
- Isla Espejo: escotilla nueva en el B1F de la Mansión Pokémon → espejo.
- Oak: te dice cuántas líneas llevas purgadas y hacia dónde mirar.

GARANTÍAS
---------
- Ningún combate encierra: todos permiten perder y hay curación y retorno.
- Ningún evento nuevo ofrece un menú de destinos.
- No se crea ni un switch ni una variable nueva: el progreso vive en \\v[264]
  y en los sellos 868-875, así que ninguna partida guardada se queda sin slots.

LIMITACIONES CONOCIDAS
----------------------
- Verificación estática y de empaquetado; no ejecutado en Game.exe/Kirin.
- El sprite de Pikablu está adaptado del Pikachu del juego (matiz a azul cielo)
  mientras no exista arte conceptual propio.
- La checklist manual está en docs/QA_MANUAL_PLAYTEST.md (sección G) y el
  diseño completo en docs/EXPANSION_MULTIVERSAL.md.

La carpeta descomprimida equivalente está en Scripts_corregido/Expansion_Multiversal/.
`;

// ------------------------------------------------------------------ construir
function build() {
  const files = fileList();
  for (const relative of files) {
    const origin = path.join(GAME, relative);
    if (!fs.existsSync(origin)) throw new Error(`Falta el archivo del juego: ${relative}`);
    const destination = path.join(OUTPUT, relative);
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    if (!fs.existsSync(destination) || !fs.readFileSync(destination).equals(fs.readFileSync(origin))) {
      fs.copyFileSync(origin, destination);
    }
  }
  fs.writeFileSync(path.join(OUTPUT, "LEEME_EXPANSION.txt"), README);
  writeZip({ root: OUTPUT, destination: ZIP, timestamp: ZIP_STAMP });
  const count = readZipIndex(ZIP).entries.size;
  console.log(`Expansión Multiversal empaquetada: ${files.length} archivos del juego + LEEME (${count} entradas en el ZIP).`);
}

function verify() {
  if (!fs.existsSync(ZIP)) {
    // El ZIP es un artefacto generado (está en .gitignore): si no existe, se
    // construye a partir de la carpeta versionada en vez de fallar.
    console.log("El ZIP de la Expansión Multiversal no existía; lo construyo a partir de Expansion_Multiversal/.");
    build();
  }
  const files = fileList();
  for (const relative of files) assertSameFile(path.join(GAME, relative), path.join(OUTPUT, relative));
  const index = readZipIndex(ZIP).entries;
  for (const relative of files) {
    if (!index.has(relative)) throw new Error(`El ZIP no contiene ${relative}`);
  }
  if (!index.has("LEEME_EXPANSION.txt")) throw new Error("El ZIP no contiene el LEEME");
  if (!fs.readFileSync(path.join(OUTPUT, "LEEME_EXPANSION.txt"), "utf8").includes("EXPANSIÓN MULTIVERSAL")) {
    throw new Error("El LEEME del paquete está desactualizado");
  }
  console.log(`Paquete de la Expansión Multiversal OK: ${files.length} archivos idénticos al juego, carpeta y ZIP sincronizados.`);
}

if (VERIFY) verify();
else { build(); verify(); }#!/usr/bin/env node
/**
 * build_outfit_sheets.mjs — convierte los assets de atavios en hojas de
 * personaje RMXP 128x192 (4x4 de 32x48).
 *
 * Entrada:  assets_outfit/<clave>.png (rejilla 4x4 generada, fondo blanco).
 * Salida:   pokemon_fire_ash/Graphics/Characters/<charset>.png (fondo transparente).
 *
 * Proceso por celda: recorta la celda de la rejilla, detecta el bounding box
 * del personaje (lo no-blanco), lo reescala a 32x48 conservando proporción y
 * lo ancla al centro-inferior de la celda (como hace RMXP con los charsets).
 *
 * Uso: node tools/build_outfit_sheets.mjs [--verify]
 */
import fs from "node:fs";
import path from "node:path";
import { createCanvas, loadImage } from "@napi-rs/canvas";

const ROOT = path.resolve(new URL(".", import.meta.url).pathname, "..");
const SRC = path.join(ROOT, "assets_outfit");
const DST = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Characters");
const BACKUP = path.join(ROOT, "PokeModBackups", "atavios");
const CELL_W = 32, CELL_H = 48, GRID = 4;
const SHEET_W = CELL_W * GRID, SHEET_H = CELL_H * GRID;
const BLANCO = 235; // canal por encima = fondo

const BOM = [
  ["atlas",   "ash_outfit_atlas"],
  ["creep",   "ash_outfit_creep"],
  ["glazed",  "ash_outfit_glazed"],
  ["lp",      "ash_outfit_lp"],
  ["lc",      "ash_outfit_lc"],
  ["tfoh",    "ash_outfit_tfoh"],
];

function bgPixel(d, i) {
  // blanco casi puro o transparente = fondo
  return (d[i + 3] < 20) || (d[i] >= BLANCO && d[i + 1] >= BLANCO && d[i + 2] >= BLANCO);
}

function bboxOf(imgData, x0, y0, w, h) {
  const d = imgData.data;
  let minX = w, minY = h, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = ((y0 + y) * imgData.width + (x0 + x)) * 4;
      if (!bgPixel(d, i)) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  return maxX < 0 ? null : { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
}

async function convertir(clave, charset) {
  const src = path.join(SRC, `${clave}.png`);
  const img = await loadImage(src);
  const big = createCanvas(img.width, img.height);
  const bc = big.getContext("2d");
  bc.drawImage(img, 0, 0);
  const data = bc.getImageData(0, 0, img.width, img.height);

  const sheet = createCanvas(SHEET_W, SHEET_H);
  const sc = sheet.getContext("2d");
  sc.imageSmoothingEnabled = true;

  const cw = Math.floor(img.width / GRID), ch = Math.floor(img.height / GRID);
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < GRID; col++) {
      const cx = col * cw, cy = row * ch;
      const bb = bboxOf(data, cx, cy, cw, ch);
      // destino dentro de la celda 32x48
      const dx0 = col * CELL_W, dy0 = row * CELL_H;
      if (!bb) continue; // celda vacía: celda transparente
      const esc = Math.min(CELL_W / bb.w, CELL_H / bb.h);
      const dw = Math.round(bb.w * esc), dh = Math.round(bb.h * esc);
      const dx = dx0 + Math.round((CELL_W - dw) / 2);
      const dy = dy0 + CELL_H - dh; // anclado al suelo
      sc.drawImage(img, cx + bb.x, cy + bb.y, bb.w, bb.h, dx, dy, dw, dh);
    }
  }

  // key de residuos blancos: píxeles con canales altos → transparentes (los
  // bordes suaves del reescalado se degradan a alfa proporcional)
  const out = sc.getImageData(0, 0, SHEET_W, SHEET_H);
  const od = out.data;
  for (let i = 0; i < od.length; i += 4) {
    if (od[i + 3] === 0) continue;
    const m = Math.max(od[i], od[i + 1], od[i + 2]);
    if (od[i] >= BLANCO && od[i + 1] >= BLANCO && od[i + 2] >= BLANCO) {
      od[i + 3] = 0;
    } else if (m >= 200) {
      od[i + 3] = Math.round(od[i + 3] * Math.max(0, (255 - m) / (255 - BLANCO)));
    }
  }
  sc.putImageData(out, 0, 0);

  const dest = path.join(DST, `${charset}.png`);
  if (fs.existsSync(dest) && !fs.existsSync(path.join(BACKUP, `${charset}.png`))) {
    fs.mkdirSync(BACKUP, { recursive: true });
    fs.copyFileSync(dest, path.join(BACKUP, `${charset}.png`));
  }
  fs.mkdirSync(DST, { recursive: true });
  fs.writeFileSync(dest, sheet.toBuffer("image/png"));
  console.log(`[atavios] ${charset}.png 128x192 <- assets_outfit/${clave}.png`);
  return dest;
}

async function main() {
  const soloVerificar = process.argv.includes("--verify");
  for (const [clave, charset] of BOM) {
    const dest = path.join(DST, `${charset}.png`);
    if (soloVerificar) {
      const ok = fs.existsSync(dest) &&
        (await loadImage(dest).then(i => i.width === SHEET_W && i.height === SHEET_H).catch(() => false));
      if (!ok) throw new Error(`falta o mal dimensionada: ${charset}.png`);
      console.log(`[atavios] verificada ${charset}.png 128x192`);
    } else {
      await convertir(clave, charset);
    }
  }
  console.log(soloVerificar ? "build_outfit_sheets --verify OK" : "build_outfit_sheets OK");
}

main().catch(err => { console.error("[atavios] ERROR:", err.message); process.exit(1); });#!/usr/bin/env node
/**
 * Pikablu es el rumor más viejo de todos: un Pikachu azul que nadie pudo
 * enseñar dos veces. Mientras no exista arte conceptual propio, este script lo
 * adapta del Pikachu del juego en lugar de dejar un hueco:
 *
 *   Graphics/Pokemon/Front/PIKACHU.png   -> Front/PIKABLU.png      96x96
 *   Graphics/Pokemon/Back/PIKACHU.png    -> Back/PIKABLU.png       96x96
 *   Graphics/Pokemon/Icons/PIKACHU.png   -> Icons/PIKABLU.png     128x64
 *   (hoja de overworld)                  -> Characters/PIKABLU.png 256x256
 *
 * La transformación trabaja en HSL: solo reescribe los tonos amarillos y
 * marrones (cuerpo y rayas) y empuja su matiz al azul cielo. Los cheek sacs
 * rojos, el negro del contorno y los blancos se respetan tal cual, así que la
 * silueta sigue siendo legible a 96x96.
 *
 * Si algún día se dibuja arte conceptual en reference/pokegods/concept/, este
 * script se aparta: avisa y deja el trabajo a build_pokegods_sprites.mjs, que
 * reconstruye los cuatro formatos desde el concepto con paleta reducida.
 *
 * Uso:
 *   node tools/build_pikablu_sprite.mjs            # adapta y verifica
 *   node tools/build_pikablu_sprite.mjs --verify   # solo comprueba tamaños
 */
import fs from "node:fs";
import path from "node:path";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY = process.argv.includes("--verify");
const CATALOG = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "pokegods_originales.json"), "utf8"));
const ENTRY = CATALOG.roster.find((entry) => entry.id === "PIKABLU");
if (!ENTRY) throw new Error("El catálogo no define a PIKABLU");
const SOURCE = "PIKACHU";
const FRONT_DIR = path.join(GAME, "Graphics", "Pokemon", "Front");
const BACK_DIR = path.join(GAME, "Graphics", "Pokemon", "Back");
const ICON_DIR = path.join(GAME, "Graphics", "Pokemon", "Icons");
const CHAR_DIR = path.join(GAME, "Graphics", "Characters");
const CONCEPT = path.join(ROOT, CATALOG.assets.conceptDir, "PIKABLU.png");
const [FW, FH] = CATALOG.assets.sizes.front;
const [IW, IH] = CATALOG.assets.sizes.icon;
const [CW, CH] = CATALOG.assets.sizes.character;
const SKY = 197 / 360;      // azul cielo del rumor
const DEEP = 212 / 360;     // azul profundo para las rayas del lomo

// ------------------------------------------------------------------- color
function rgbToHsl(r, g, b) {
  const rn = r / 255, gn = g / 255, bn = b / 255;
  const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
  const l = (max + min) / 2;
  const d = max - min;
  if (!d) return [0, 0, l];
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h;
  if (max === rn) h = ((gn - bn) / d + (gn < bn ? 6 : 0)) / 6;
  else if (max === gn) h = ((bn - rn) / d + 2) / 6;
  else h = ((rn - gn) / d + 4) / 6;
  return [h, s, l];
}
function hueToRgb(p, q, t) {
  let x = t;
  if (x < 0) x += 1;
  if (x > 1) x -= 1;
  if (x < 1 / 6) return p + (q - p) * 6 * x;
  if (x < 1 / 2) return q;
  if (x < 2 / 3) return p + (q - p) * (2 / 3 - x) * 6;
  return p;
}
function hslToRgb(h, s, l) {
  if (!s) { const v = Math.round(l * 255); return [v, v, v]; }
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  return [
    Math.round(hueToRgb(p, q, h + 1 / 3) * 255),
    Math.round(hueToRgb(p, q, h) * 255),
    Math.round(hueToRgb(p, q, h - 1 / 3) * 255),
  ];
}
/** Amarillos y marrones del cuerpo -> azul; todo lo demás se queda como está. */
function pikabluTint(data) {
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] === 0) continue;
    const [h, s, l] = rgbToHsl(data[i], data[i + 1], data[i + 2]);
    if (s < 0.18 || l < 0.12) continue;              // contorno, sombra, blanco
    // Los rojos (cheeks) y los magentas se respetan: el rumor decía "azul", no "gris".
    if (h < 0.055 || h > 0.92) continue;
    if (h >= 0.09 && h <= 0.20) {                    // amarillo del cuerpo
      const rgb = hslToRgb(SKY, Math.min(1, s * 1.05), Math.min(0.92, l + 0.02));
      [data[i], data[i + 1], data[i + 2]] = rgb;
    } else if (h > 0.055 && h < 0.09) {              // marrón de las rayas del lomo
      const rgb = hslToRgb(DEEP, Math.min(1, s * 0.9), Math.max(0.18, l - 0.02));
      [data[i], data[i + 1], data[i + 2]] = rgb;
    }
  }
  return data;
}

// ------------------------------------------------------------------ lienzo
function pixelsOf(image) {
  const canvas = createCanvas(image.width, image.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(image, 0, 0);
  return { canvas, width: image.width, height: image.height };
}
async function tinted(file) {
  const image = await loadImage(file);
  const { canvas, width, height } = pixelsOf(image);
  const ctx = canvas.getContext("2d");
  const frame = ctx.getImageData(0, 0, width, height);
  pikabluTint(frame.data);
  ctx.putImageData(frame, 0, 0);
  return canvas;
}
/** Hoja de overworld: 4 direcciones x 4 pasos, todas de frente, como el resto de Pokégods. */
function overworldSheet(front) {
  const sheet = createCanvas(CW, CH);
  const ctx = sheet.getContext("2d");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  for (let row = 0; row < 4; row++) {
    for (let step = 0; step < 4; step++) {
      const bob = step % 2 === 0 ? 0 : -2;
      ctx.drawImage(front, step * 64, row * 64 + bob, 64, 64);
    }
  }
  return sheet;
}

// -------------------------------------------------------------- verificación
function sizeOf(file) {
  const buffer = fs.readFileSync(file);
  return [buffer.readUInt32BE(16), buffer.readUInt32BE(20)];
}
function verify() {
  const errors = [];
  const targets = [
    [path.join(FRONT_DIR, "PIKABLU.png"), FW, FH],
    [path.join(BACK_DIR, "PIKABLU.png"), FW, FH],
    [path.join(ICON_DIR, "PIKABLU.png"), IW, IH],
    [path.join(CHAR_DIR, "PIKABLU.png"), CW, CH],
  ];
  for (const [file, width, height] of targets) {
    if (!fs.existsSync(file)) { errors.push(`falta ${path.relative(GAME, file)}`); continue; }
    const [w, h] = sizeOf(file);
    if (w !== width || h !== height) errors.push(`${path.basename(file)} mide ${w}x${h} y debe medir ${width}x${height}`);
  }
  if (errors.length) throw new Error(`Pikablu inválido (${errors.length}):\n- ${errors.join("\n- ")}`);
  console.log(`Pikablu OK: frente ${FW}x${FH}, reverso, icono ${IW}x${IH} y overworld ${CW}x${CH}.`);
}

if (VERIFY) {
  verify();
} else if (fs.existsSync(CONCEPT)) {
  // Si hay arte conceptual propio, manda el convertidor oficial.
  console.log(`Existe ${path.relative(ROOT, CONCEPT)}: reconstruye los sprites con tools/build_pokegods_sprites.mjs`);
  verify();
} else {
  const frontSource = path.join(FRONT_DIR, `${SOURCE}.png`);
  const backSource = path.join(BACK_DIR, `${SOURCE}.png`);
  const iconSource = path.join(ICON_DIR, `${SOURCE}.png`);
  for (const file of [frontSource, backSource, iconSource]) {
    if (!fs.existsSync(file)) throw new Error(`Falta el sprite base ${path.relative(GAME, file)}`);
  }
  const front = await tinted(frontSource);
  const back = await tinted(backSource);
  const icon = await tinted(iconSource);
  if (front.width !== FW || front.height !== FH) throw new Error(`El frente base no mide ${FW}x${FH}`);
  if (back.width !== FW || back.height !== FH) throw new Error(`El reverso base no mide ${FW}x${FH}`);
  if (icon.width !== IW || icon.height !== IH) throw new Error(`El icono base no mide ${IW}x${IH}`);

  fs.mkdirSync(CHAR_DIR, { recursive: true });
  fs.writeFileSync(path.join(FRONT_DIR, "PIKABLU.png"), front.toBuffer("image/png"));
  fs.writeFileSync(path.join(BACK_DIR, "PIKABLU.png"), back.toBuffer("image/png"));
  fs.writeFileSync(path.join(ICON_DIR, "PIKABLU.png"), icon.toBuffer("image/png"));
  fs.writeFileSync(path.join(CHAR_DIR, "PIKABLU.png"), overworldSheet(front).toBuffer("image/png"));
  console.log(`Pikablu adaptado desde ${SOURCE} (matiz amarillo/marrón -> azul cielo). ` +
    "Si dibujas arte conceptual, el convertidor oficial tendrá prioridad.");
  verify();
}#!/usr/bin/env node
/**
 * Convierte el arte conceptual de los Pokégods en los sprites reales que usa
 * Fire Ash 3.7.1.
 *
 * Entrada  : reference/pokegods/concept/<ID>.png  (cualquier tamaño; se recorta
 *            el fondo liso, se recorta la criatura y se centra).
 * Salida   : Graphics/Pokemon/Front/<ID>.png        96x96   (combate, frente)
 *            Graphics/Pokemon/Back/<ID>.png         96x96   (combate, reverso)
 *            Graphics/Pokemon/Icons/<ID>.png       128x64   (dos fotogramas de 64)
 *            Graphics/Characters/<ID>.png         256x256   (4 direcciones x 4 pasos)
 *
 * El proceso reduce la paleta por corte mediano (median cut) a 32 colores para
 * que el resultado conviva con los sprites clásicos del juego en lugar de
 * parecer una ilustración pegada. El reverso y los fotogramas se derivan del
 * frente: la isla está habitada por anomalías, así que todas las direcciones
 * muestran la misma criatura "mirando" a la vez; es una decisión estética, no
 * un error de assets.
 *
 * Uso:
 *   node tools/build_pokegods_sprites.mjs            # convierte lo que exista
 *   node tools/build_pokegods_sprites.mjs --verify   # valida tamaños y alfa
 *   node tools/build_pokegods_sprites.mjs --strict   # exige los 12 planteles
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { GAME, ROOT } from "./lib/fire_ash_registry.mjs";

const VERIFY = process.argv.includes("--verify");
const STRICT = process.argv.includes("--strict");
const CATALOG = JSON.parse(fs.readFileSync(path.join(ROOT, "content", "pokegods_originales.json"), "utf8"));
const CONCEPT_DIR = path.join(ROOT, CATALOG.assets.conceptDir);
const FRONT_DIR = path.join(GAME, "Graphics", "Pokemon", "Front");
const BACK_DIR = path.join(GAME, "Graphics", "Pokemon", "Back");
const ICON_DIR = path.join(GAME, "Graphics", "Pokemon", "Icons");
const CHAR_DIR = path.join(GAME, "Graphics", "Characters");
const CRY_DIR = path.join(GAME, "Audio", "SE");
const PALETTE_SIZE = 32;
const [FW, FH] = CATALOG.assets.sizes.front;
const [IW, IH] = CATALOG.assets.sizes.icon;
const [CW, CH] = CATALOG.assets.sizes.character;

// ------------------------------------------------------------------ imagen
function pixelsOf(image) {
  const canvas = createCanvas(image.width, image.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(image, 0, 0);
  const data = ctx.getImageData(0, 0, image.width, image.height);
  return { data: data.data, width: image.width, height: image.height };
}

/** Funde el fondo: recorre desde los bordes con tolerancia de color. */
function keyBackground({ data, width, height }) {
  const alpha = new Uint8Array(width * height).fill(255);
  const at = (x, y) => (y * width + x) * 4;
  const corner = (x, y) => {
    const i = at(x, y);
    return [data[i], data[i + 1], data[i + 2]];
  };
  const samples = [corner(0, 0), corner(width - 1, 0), corner(0, height - 1), corner(width - 1, height - 1)];
  const bg = [0, 1, 2].map((c) => samples.reduce((sum, s) => sum + s[c], 0) / samples.length);
  const near = (i, tolerance = 46) =>
    Math.abs(data[i] - bg[0]) + Math.abs(data[i + 1] - bg[1]) + Math.abs(data[i + 2] - bg[2]) <= tolerance;
  const seen = new Uint8Array(width * height);
  const queue = [];
  for (let x = 0; x < width; x++) { queue.push([x, 0], [x, height - 1]); }
  for (let y = 0; y < height; y++) { queue.push([0, y], [width - 1, y]); }
  while (queue.length) {
    const [x, y] = queue.pop();
    if (x < 0 || y < 0 || x >= width || y >= height) continue;
    const index = y * width + x;
    if (seen[index]) continue;
    seen[index] = 1;
    const i = index * 4;
    if (!near(i)) continue;
    alpha[index] = 0;
    queue.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
  }
  return alpha;
}

function boundingBox(alpha, width, height) {
  let minX = width, minY = height, maxX = -1, maxY = -1;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!alpha[y * width + x]) continue;
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  return maxX < 0 ? null : { minX, minY, maxX, maxY };
}

/** Paleta por corte mediano sobre los píxeles opacos. */
function medianCut(rgbList, size) {
  if (!rgbList.length) return [];
  let boxes = [rgbList];
  while (boxes.length < size) {
    boxes.sort((a, b) => b.length - a.length);
    const box = boxes.shift();
    if (!box || box.length < 2) { if (box) boxes.push(box); break; }
    let range = -1, channel = 0;
    for (let c = 0; c < 3; c++) {
      let lo = 255, hi = 0;
      for (const px of box) { lo = Math.min(lo, px[c]); hi = Math.max(hi, px[c]); }
      if (hi - lo > range) { range = hi - lo; channel = c; }
    }
    box.sort((a, b) => a[channel] - b[channel]);
    const mid = Math.floor(box.length / 2);
    boxes.push(box.slice(0, mid), box.slice(mid));
  }
  return boxes.filter((box) => box.length).map((box) => [0, 1, 2].map((c) =>
    Math.round(box.reduce((sum, px) => sum + px[c], 0) / box.length)));
}

function quantize(data, width, height, alpha) {
  const opaque = [];
  for (let i = 0; i < width * height; i++) {
    if (!alpha[i]) continue;
    const p = i * 4;
    opaque.push([data[p], data[p + 1], data[p + 2]]);
  }
  const palette = medianCut(opaque, PALETTE_SIZE);
  const out = new Uint8ClampedArray(data.length);
  out.set(data);
  if (!palette.length) return out;
  for (let i = 0; i < width * height; i++) {
    if (!alpha[i]) { out[i * 4 + 3] = 0; continue; }
    const p = i * 4;
    let best = 0, bestDistance = Infinity;
    for (let k = 0; k < palette.length; k++) {
      const [r, g, b] = palette[k];
      const distance = (r - data[p]) ** 2 + (g - data[p + 1]) ** 2 + (b - data[p + 2]) ** 2;
      if (distance < bestDistance) { bestDistance = distance; best = k; }
    }
    out[p] = palette[best][0];
    out[p + 1] = palette[best][1];
    out[p + 2] = palette[best][2];
    out[p + 3] = 255;
  }
  return out;
}

function canvasFrom(source, width, height) {
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(source, 0, 0, width, height);
  return canvas;
}

/**
 * Reescala y cuantiza en el tamaño final. La paleta se calcula DESPUÉS de
 * reescalar: si se hiciera antes, el suavizado volvería a mezclar colores y el
 * sprite perdería el aspecto de pixel art del juego base.
 */
function finalize(source, width, height) {
  const canvas = canvasFrom(source, width, height);
  const ctx = canvas.getContext("2d");
  const pixels = ctx.getImageData(0, 0, width, height);
  const mask = new Uint8Array(width * height);
  for (let i = 0; i < mask.length; i++) mask[i] = pixels.data[i * 4 + 3] > 8 ? 1 : 0;
  const quantized = quantize(pixels.data, width, height, mask);
  const image = ctx.createImageData(width, height);
  image.data.set(quantized);
  ctx.putImageData(image, 0, 0);
  return canvas;
}

async function buildOne(entry) {
  const file = path.join(CONCEPT_DIR, `${entry.id}.png`);
  if (!fs.existsSync(file)) return { id: entry.id, missing: true };
  const image = await loadImage(file);
  const raw = pixelsOf(image);
  const alpha = keyBackground(raw);
  const box = boundingBox(alpha, raw.width, raw.height);
  if (!box) throw new Error(`${entry.id}: el concepto no tiene criatura recognoscible (fondo no separable)`);
  const cutW = box.maxX - box.minX + 1;
  const cutH = box.maxY - box.minY + 1;

  // Recorte centrado sobre un lienzo cuadrado de trabajo.
  const base = 256;
  const scale = Math.min(base / cutW, base / cutH);
  const drawW = Math.max(1, Math.round(cutW * scale));
  const drawH = Math.max(1, Math.round(cutH * scale));
  const canvas = createCanvas(base, base);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  const cutData = new Uint8ClampedArray(cutW * cutH * 4);
  for (let y = 0; y < cutH; y++) {
    for (let x = 0; x < cutW; x++) {
      const from = ((box.minY + y) * raw.width + (box.minX + x)) * 4;
      const to = (y * cutW + x) * 4;
      cutData[to] = raw.data[from];
      cutData[to + 1] = raw.data[from + 1];
      cutData[to + 2] = raw.data[from + 2];
      cutData[to + 3] = alpha[(box.minY + y) * raw.width + (box.minX + x)] ? 255 : 0;
    }
  }
  const cutCanvas = createCanvas(cutW, cutH);
  const cutCtx = cutCanvas.getContext("2d");
  const cutImage = cutCtx.createImageData(cutW, cutH);
  cutImage.data.set(cutData);
  cutCtx.putImageData(cutImage, 0, 0);
  ctx.drawImage(cutCanvas, Math.floor((base - drawW) / 2), Math.floor((base - drawH) / 2), drawW, drawH);

  fs.mkdirSync(FRONT_DIR, { recursive: true });
  fs.mkdirSync(BACK_DIR, { recursive: true });
  fs.mkdirSync(ICON_DIR, { recursive: true });
  fs.mkdirSync(CHAR_DIR, { recursive: true });

  // Frente: 96x96 con paleta reducida.
  const front = finalize(canvas, FW, FH);
  fs.writeFileSync(path.join(FRONT_DIR, `${entry.id}.png`), front.toBuffer("image/png"));

  // Reverso: la misma silueta en sombra (la isla no muestra dos caras).
  const backRaw = createCanvas(FW, FH);
  const backRawCtx = backRaw.getContext("2d");
  backRawCtx.drawImage(front, 0, 0);
  backRawCtx.globalCompositeOperation = "source-atop";
  backRawCtx.fillStyle = "rgba(18,14,32,0.34)";
  backRawCtx.fillRect(0, 0, FW, FH);
  const back = finalize(backRaw, FW, FH);
  fs.writeFileSync(path.join(BACK_DIR, `${entry.id}.png`), back.toBuffer("image/png"));

  // Icono: dos fotogramas de 64; el segundo late un píxel, como un dato corrupto.
  const iconRaw = createCanvas(IW, IH);
  const iconRawCtx = iconRaw.getContext("2d");
  iconRawCtx.imageSmoothingEnabled = true;
  iconRawCtx.imageSmoothingQuality = "high";
  iconRawCtx.drawImage(canvas, 0, 0, 64, 64);
  iconRawCtx.drawImage(canvas, 64 + 1, 0, 63, 64);
  const icon = finalize(iconRaw, IW, IH);
  fs.writeFileSync(path.join(ICON_DIR, `${entry.id}.png`), icon.toBuffer("image/png"));

  // Overworld: 4 direcciones x 4 pasos de 64. Todas miran de frente: son
  // anomalías, no criaturas con espalda.
  const sheetRaw = createCanvas(CW, CH);
  const sheetRawCtx = sheetRaw.getContext("2d");
  sheetRawCtx.imageSmoothingEnabled = true;
  sheetRawCtx.imageSmoothingQuality = "high";
  for (let row = 0; row < 4; row++) {
    for (let step = 0; step < 4; step++) {
      const bob = step % 2 === 0 ? 0 : -2;
      sheetRawCtx.drawImage(canvas, step * 64, row * 64 + bob, 64, 64);
    }
  }
  const sheet = finalize(sheetRaw, CW, CH);
  fs.writeFileSync(path.join(CHAR_DIR, `${entry.id}.png`), sheet.toBuffer("image/png"));
  return { id: entry.id, missing: false };
}

// -------------------------------------------------------------- verificación
function pngSize(file) {
  const buffer = fs.readFileSync(file);
  return [buffer.readUInt32BE(16), buffer.readUInt32BE(20)];
}
function coverage(file) {
  const [width, height] = pngSize(file);
  return { width, height, ok: width > 0 && height > 0 };
}

async function verify() {
  const errors = [];
  const pending = [];
  for (const entry of CATALOG.roster) {
    const targets = [
      [path.join(FRONT_DIR, `${entry.id}.png`), FW, FH],
      [path.join(BACK_DIR, `${entry.id}.png`), FW, FH],
      [path.join(ICON_DIR, `${entry.id}.png`), IW, IH],
      [path.join(CHAR_DIR, `${entry.id}.png`), CW, CH],
    ];
    let complete = true;
    for (const [file, width, height] of targets) {
      if (!fs.existsSync(file)) { complete = false; continue; }
      const size = coverage(file);
      if (size.width !== width || size.height !== height) {
        errors.push(`${entry.id}: ${path.basename(path.dirname(file))}/${path.basename(file)} mide ${size.width}x${size.height} y debe medir ${width}x${height}`);
      }
    }
    if (!complete) pending.push(entry.id);
  }
  if (STRICT && pending.length) {
    errors.push(`faltan sprites de ${pending.length} Pokégods: ${pending.join(", ")}`);
  }
  if (errors.length) throw new Error(`Sprites Pokégod inválidos (${errors.length}):\n- ${errors.join("\n- ")}`);
  const ready = CATALOG.roster.length - pending.length;
  console.log(`Verificación OK: ${ready}/${CATALOG.roster.length} Pokégods con frente ${FW}x${FH}, reverso, icono ${IW}x${IH} y overworld ${CW}x${CH}.` +
    (pending.length ? ` Pendientes de arte: ${pending.join(", ")}.` : ""));
}

if (VERIFY) {
  await verify();
} else {
  const built = [];
  const missing = [];
  for (const entry of CATALOG.roster) {
    const result = await buildOne(entry);
    (result.missing ? missing : built).push(result.id);
  }
  if (built.length) console.log(`Sprites construidos (${built.length}): ${built.join(", ")}`);
  if (missing.length) console.log(`Sin arte conceptual todavía (${missing.length}): ${missing.join(", ")}`);
  await verify();
}// ============================================================================
// build_teckel_package.mjs
// ----------------------------------------------------------------------------
// Empaqueta el contenido de Ciudad Teckel / Isla Paraíso / MAXINE y la
// relocalización de Pokégods y versiones alternativas al Atlas, usando el
// manifest que dejan tools/apply_atlas_relocalizacion.mjs y
// tools/apply_ciudad_teckel_maxine.mjs (content/teckel_manifest.json).
//
//   node tools/build_teckel_package.mjs            # reconstruye ZIP + carpeta
//   node tools/build_teckel_package.mjs --verify   # comprueba ZIP vs carpeta
// ============================================================================

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { ROOT, GAME } from "./lib/fire_ash_registry.mjs";
import { writeZip, readZipIndex, readZipEntry } from "./lib/zip_writer.mjs";

const VERIFY = process.argv.includes("--verify");
const MANIFEST = path.join(ROOT, "content", "teckel_manifest.json");
const STAGE = path.join(ROOT, "Scripts_corregido", "Ciudad_Teckel_Paraiso");
const ZIP = path.join(ROOT, "Scripts_corregido", "Fire_Ash_Ciudad_Teckel_Paraiso.zip");

const LEEME = `CIUDAD TECKEL E ISLA PARAÍSO (rediseño de la Isla Espejo)
=========================================================

La Isla Espejo cambia de propósito y la Dimensión Atlas absorbe su contenido
anterior:

 · Los 20 Pokégods y las 15/16 versiones alternativas de personajes (Mirror
   Boss, ahora con sprites recoloreados ALT_*) viven repartidos por los mapas
   Tier 1 de la Dimensión Atlas.
 · Map 997 = Ciudad Teckel: perros Pokémon (Zigzagoon, Poochyena, Growlithe,
   Eevee…) deambulando libres, veterinaria que cura, gimnasio y muelle.
 · Map 998 = Gimnasio Teckel: la líder Duna entrega la Medalla Pata.
 · Map 999 = Afueras Teckel: prado con encuentros de perros.
 · Map 2300 = Isla Paraíso: el altar de MAXINE, la Legendaria Florateck
   (nivel 125).

Cómo se juega
-------------
1. Tras cerrar la Ruta de Dios (Arceus), habla con el PROFESOR ATLAS en Puerto
   Horizonte (Atlas Mil): te da el TICKET PARAÍSO.
2. En Ciudad Teckel, vence a DUNA en el gimnasio para la MEDALLA PATA.
3. Cruza en el muelle con el ticket hasta Isla Paraíso.
4. La GUARDIANA NIRA pregunta: «¿qué le gusta más a MAXINE, el pollo o la
   pata?» La respuesta correcta es LA PATA. Con ella, MAXINE despierta en su
   altar y puede combatirse (y capturarse) al nivel 125.

Instalación
-----------
Extrae este ZIP en la raíz del juego (junto a Game.exe) aceptando reemplazos.
Requiere haber instalado antes Fire_Ash_Paquete_Directo.zip y
Dimensional_Nightmare_QA.zip (los mapas Atlas existen desde esa capa).
No toca partidas guardadas.
`;

function manifestFiles() {
  const m = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
  return m.files;
}

function build() {
  fs.rmSync(STAGE, { recursive: true, force: true });
  fs.mkdirSync(STAGE, { recursive: true });
  const files = manifestFiles();
  for (const rel of files) {
    const src = path.join(GAME, rel);
    if (!fs.existsSync(src)) throw new Error(`el manifest cita ${rel} y no existe en el juego`);
    const dst = path.join(STAGE, rel);
    fs.mkdirSync(path.dirname(dst), { recursive: true });
    fs.copyFileSync(src, dst);
  }
  fs.writeFileSync(path.join(STAGE, "LEEME_TECKEL.txt"), LEEME);
  writeZip({ root: STAGE, destination: ZIP });
  console.log(`OK: Fire_Ash_Ciudad_Teckel_Paraiso.zip (${files.length + 1} entradas)`);
}

function verify() {
  const files = manifestFiles();
  const zip = readZipIndex(ZIP);
  const missing = files.filter((f) => !zip.entries.has(f));
  if (missing.length) throw new Error(`ZIP sin: ${missing.slice(0, 5).join(", ")}`);
  for (const f of files) {
    const disk = fs.readFileSync(path.join(STAGE, f));
    const inZip = Buffer.from(readZipEntry(zip, f));
    if (!disk.equals(inZip)) throw new Error(`diferencia carpeta/ZIP en ${f}`);
  }
  if (!zip.entries.has("LEEME_TECKEL.txt")) throw new Error("ZIP sin LEEME_TECKEL.txt");
  console.log(`OK: paquete Teckel/Paraíso verificado (${files.length + 1} entradas)`);
}

if (VERIFY) verify();
else { build(); verify(); }#!/usr/bin/env node
/**
 * Extrae la hoja de caminar de Ash de la referencia local de Unbound y la adapta
 * al charset RMXP del juego: 4 direcciones × 4 patrones, celdas 32×48, fondo
 * transparente, tamaño final 128×192. No extrae ni empaqueta datos de la ROM.
 *
 * node tools/build_unbound_ash_outfit.mjs [--verify]
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = path.join(ROOT, "ashsprites", "ash_pokemon_unbound.jpg");
const DEST_DIR = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Characters");
const DEST = path.join(DEST_DIR, "ash_outfit_unbound.png");
const BACKUP = path.join(ROOT, "pokemon_fire_ash", "PokeModBackups", "atavios", "ash_outfit_unbound.png");
const CELL_W = 32, CELL_H = 48, COLS = 4, ROWS = 4;
const OUTPUT_W = CELL_W * COLS, OUTPUT_H = CELL_H * ROWS;
const FRAME_W = 42, FRAME_H = 64;
const FRAME_X = [53, 107, 161];
const FRAME_Y = [81, 151, 221];
const CYCLE = [0, 1, 2, 1];

function isReferenceGreen(r, g, b) {
  // El fondo y la filigrana de la lámina son verde/sombra-verde; el sprite de
  // Ash usa rojo, crema, piel, azul y marrón. El key no toca esos tonos.
  return g >= 42 && g > r * 1.13 && g > b * 1.04 && r < 125 && b < 145;
}

function extractFrame(source, sx, sy, mirror) {
  const raw = createCanvas(FRAME_W, FRAME_H);
  const rc = raw.getContext("2d");
  rc.drawImage(source, sx, sy, FRAME_W, FRAME_H, 0, 0, FRAME_W, FRAME_H);
  const image = rc.getImageData(0, 0, FRAME_W, FRAME_H);
  const pixels = image.data;
  let left = FRAME_W, top = FRAME_H, right = -1, bottom = -1;
  for (let y = 0; y < FRAME_H; y += 1) for (let x = 0; x < FRAME_W; x += 1) {
    const i = (y * FRAME_W + x) * 4;
    const r = pixels[i], g = pixels[i + 1], b = pixels[i + 2];
    if (isReferenceGreen(r, g, b)) {
      pixels[i + 3] = 0;
      continue;
    }
    // La fuente es JPEG; cuantizar a 5 bits/canal elimina el ruido de compresión
    // sin desdibujar el pixel art ni cambiar su paleta de forma agresiva.
    pixels[i] = Math.round(r / 8) * 8;
    pixels[i + 1] = Math.round(g / 8) * 8;
    pixels[i + 2] = Math.round(b / 8) * 8;
    if (x < left) left = x;
    if (x > right) right = x;
    if (y < top) top = y;
    if (y > bottom) bottom = y;
  }
  if (right < left || bottom < top) throw new Error(`No se detectó el personaje en el recorte ${sx},${sy}`);
  rc.putImageData(image, 0, 0);
  const bounds = { x: left, y: top, w: right - left + 1, h: bottom - top + 1 };
  const frame = createCanvas(CELL_W, CELL_H);
  const fc = frame.getContext("2d");
  fc.imageSmoothingEnabled = false;
  const scale = Math.min(CELL_W / bounds.w, CELL_H / bounds.h);
  const w = Math.max(1, Math.min(CELL_W, Math.round(bounds.w * scale)));
  const h = Math.max(1, Math.min(CELL_H, Math.round(bounds.h * scale)));
  const x = Math.floor((CELL_W - w) / 2);
  const y = CELL_H - h;
  fc.drawImage(raw, bounds.x, bounds.y, bounds.w, bounds.h, x, y, w, h);
  return { canvas: frame, mirror };
}

async function build() {
  if (!fs.existsSync(SOURCE)) throw new Error(`Falta la referencia visual ${SOURCE}`);
  const source = await loadImage(SOURCE);
  if (source.width < 220 || source.height < 285) {
    throw new Error(`La lámina tiene tamaño inesperado: ${source.width}×${source.height}`);
  }
  const sheet = createCanvas(OUTPUT_W, OUTPUT_H);
  const ctx = sheet.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  // Orden RMXP: abajo, izquierda, derecha, arriba. La fuente ofrece tres
  // patrones por pose; se coloca el paso central en el patrón de reposo.
  const directions = [
    { sourceRow: 0, mirror: false }, // frente / abajo
    { sourceRow: 2, mirror: true },  // perfil reflejado / izquierda
    { sourceRow: 2, mirror: false }, // perfil / derecha
    { sourceRow: 1, mirror: false }, // espalda / arriba
  ];
  for (let row = 0; row < ROWS; row += 1) {
    const direction = directions[row];
    for (let col = 0; col < COLS; col += 1) {
      const frameIndex = CYCLE[col];
      const frame = extractFrame(source, FRAME_X[frameIndex], FRAME_Y[direction.sourceRow], direction.mirror);
      const dx = col * CELL_W, dy = row * CELL_H;
