        ctx.save();
        ctx.translate(dx + CELL_W, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(frame.canvas, 0, 0);
        ctx.restore();
      } else {
        ctx.drawImage(frame.canvas, dx, dy);
      }
    }
