const NPC_ROW = /^\|\s*(\d{4})\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*`?([^`|\s]+)`?[^|]*\|\s*([^|]+?)\s*\|?\s*$/;
const CELL = () => /\((\d+)\s*,\s*(\d+)\)/g;
const MAP_ID = () => /\b(20[3-9]\d|21[0-8]\d|2190)\b/g;   // 2039–2140 · 2143–2190 (W7–W9)

function sections(text) {
  const out = new Map();
  let current = null;
  for (const line of text.split("\n")) {
    const heading = line.match(/^##+\s+(.*)$/);
    if (heading) {
      current = heading[1];
      out.set(current, []);
      continue;
    }
    if (current) out.get(current).push(line);
  }
  return out;
}

function parseNpcs(lines) {
  const npcs = [];
  for (const line of lines) {
    const m = line.match(NPC_ROW);
    if (!m) continue;
    const [, mapId, rawName, rawType, rawSprite, rawNotes] = m;
    if (!/^\d{4}$/.test(mapId) || /^:?-+$/.test(rawName)) continue;
    const name = rawName.trim().replace(/\*\*/g, "");
    const typeText = rawType.trim();
    const group = typeText.match(/[×x]\s*(\d+)\s*$/i);
    const groupCount = group ? Math.max(1, Math.min(12, Number(group[1]))) : 1;
    const type = typeText.replace(/[×x]\s*\d+\s*$/i, "").trim();
    let sprite = rawSprite.trim();
    // El GDD escribe cosas como «(sin sprite)», «(imagen fija)» o «(evento sin sprite)»:
    // no son nombres de archivo de Graphics/Characters, son eventos sin gráfico propio.
    if (sprite.startsWith("(")) sprite = "";
    for (let instance = 1; instance <= groupCount; instance++) {
      npcs.push({
        map: Number(mapId),
        name,
        displayName: groupCount > 1 ? `${name} ${instance}` : name,
        instance,
        groupCount,
        type,
        sprite,
        notes: rawNotes.trim().replace(/\*\*/g, ""),
      });
    }
  }
  return npcs;
}

/** Índice de eventos: un bloque de código con líneas «EV_XXX — …» (y continuaciones con «→»). */
function parseEvents(lines, episode) {
  const events = [];
  let inBlock = false;
  let current = null;
  for (const line of lines) {
    if (line.trim().startsWith("```")) { inBlock = !inBlock; current = null; continue; }
    if (!inBlock) continue;
    const head = line.match(/^(EV_[A-Z0-9]+_[A-Za-z0-9]+)\s*[—-]\s*(.*)$/);
    if (head) {
      current = { name: head[1], episode: episode.key, detail: head[2].trim(), effect: "" };
      events.push(current);
      continue;
    }
    if (current && line.trim().startsWith("→")) current.effect += (current.effect ? " " : "") + line.trim().replace(/^→\s*/, "");
  }
  for (const ev of events) {
    const maps = [...ev.detail.matchAll(MAP_ID())].map((m) => Number(m[1]));
    const cells = [...ev.detail.matchAll(CELL())].map((m) => [Number(m[1]), Number(m[2])]);
    const triggerText = ev.detail.toLowerCase();
    const trigger = /paralelo/.test(triggerText) ? "parallel"
      : /autorun/.test(triggerText) ? "autorun"
        : /pisar|al pisar/.test(triggerText) ? "touch" : "action";
    ev.maps = maps.length ? maps : [];
    ev.cells = cells;
    ev.trigger = trigger;
    // "EV_CAT_Urnas — 2042, 4 puntos — ..." significa 4 eventos en 2042
    const count = ev.detail.match(/(\d+)\s*puntos?/i);
    ev.instances = count ? Number(count[1]) : Math.max(1, ev.cells.length);
  }
  return events;
}

/**
 * §5 «Anomalías (N)» de cada doc: bloque de texto, no tabla.
 *
 *   [A01] LA ANTORCHA QUE VUELVE — visual
 *     Map2042 — (7,6) [R7-4]. Fase ≥2. La antorcha apagada está encendida al reentrar.
 */
function parseAnomalies(sectionsMap) {
  for (const [title, lines] of sectionsMap) {
    const m = title.match(/^5\.\s*Anomal[íi]as\s*\((\d+)\)/i);
    if (!m) continue;
    const items = [];
    let current = null;
    for (const line of lines) {
      const head = line.match(/^\s*\[(A\d+)\]\s*(.+?)\s*[—-]\s*([a-záéíóú/\s]+?)\s*$/i);
      if (head) {
        const kinds = head[3].toLowerCase().split(/[/\sy]+/).filter((k) => /^(visual|auditiva|temporal|espacial)$/.test(k));
        current = { code: head[1], name: head[2].trim(), type: kinds[0] ?? "visual", types: kinds, map: null, cells: [], text: "" };
        items.push(current);
        continue;
      }
      if (!current) continue;
      const where = line.match(/Map(\d{4})[\s\S]*?/);
      if (where && current.map === null) current.map = Number(where[1]);
      for (const cell of line.matchAll(CELL())) current.cells.push([Number(cell[1]), Number(cell[2])]);
      const body = line.trim();
      if (body) current.text += (current.text ? " " : "") + body;
    }
    for (const item of items) {
      item.trigger = /pisar|al pisar/i.test(item.text) ? "touch" : "action";
      item.fase = Number(item.text.match(/Fase\s*[≥>=]+\s*(\d)/i)?.[1] ?? 1);
    }
    return { declared: Number(m[1]), items };
  }
  return { declared: 0, items: [] };
}

/**
 * Valores curados en el catálogo anterior que la regeneración debe respetar: hoy sólo el
 * `type` de la fase A del jefe (el tipo de entrenador «DN_KINGGUS» es un tipo propio del
 * mod y no aparece en la tabla del plan). Si el catálogo previo trae el mismo jefe, se
 * conserva su `phaseA` para no pisar ajustes hechos a mano.
 */
function curatedBossTypes() {
  if (!fs.existsSync(OUT)) return new Map();
  try {
    const previous = JSON.parse(fs.readFileSync(OUT, "utf8"));
    const out = new Map();
    for (const ep of previous.episodes ?? []) {
      if (ep.boss?.phaseA?.type && ep.bossName === ep.boss.name) out.set(ep.key, ep.boss.phaseA);
    }
    return out;
  } catch {
    return new Map();
  }
}
const CURATED = curatedBossTypes();

const blueprint = {
  title: "Dimensional Nightmare — plano de conexiones, NPCs y eventos",
  generatedBy: "tools/create_dimensional_nightmare_events.mjs",
  docs: "docs/DIMENSIONAL_NIGHTMARE/01..07",
  hub: { map: 2030, x: 36, y: 12, note: "Gruta de los Testigos: punto de entrada/salida de cada episodio" },
  flags: {
    switchRange: [882, 935],
    variableRange: [265, 307],
    externalVariablesReadOnly: { 264: "Emisiones selladas de Monte Silver; DN sólo lee este contador (0–7)." },
    commonEvents: [900, 906],
  },
  episodes: [],
};

for (const episode of EPISODES) {
  const text = fs.readFileSync(path.join(DOCS, episode.doc), "utf8");
  const sectionsMap = sections(text);
  const npcSection = [...sectionsMap].find(([t]) => /NPCs por mapa/i.test(t))?.[1] ?? [];
  const eventSection = [...sectionsMap].find(([t]) => /Eventos programables/i.test(t))?.[1] ?? [];
  const anomalies = parseAnomalies(sectionsMap);
  blueprint.episodes.push({
    key: episode.key,
    doc: episode.doc,
    mapRange: { from: episode.from, to: episode.to },
    seal: episode.seal,
    grieta: episode.grieta,
    resonance: episode.res,
    anomalyVariable: episode.var,
    cuota: episode.cuota,
    bossName: episode.boss,
    boss: BOSSES[episode.key]
      ? { ...BOSSES[episode.key], phaseA: CURATED.get(episode.key) ?? BOSSES[episode.key].phaseA }
      : null,
    anomalies,
    npcs: parseNpcs(npcSection),
    events: parseEvents(eventSection, episode),
  });
}

// Nexo: eventos propios (doc 07) sin tabla de NPCs
const nexoText = fs.readFileSync(path.join(DOCS, "07_MAPA_DE_FLUJO.md"), "utf8");
const nexoEvents = [...nexoText.matchAll(/EV_NEXO_[A-Za-z0-9]+/g)].map((m) => m[0]);
blueprint.episodes.push({
  key: "NEXO",
  doc: "07_MAPA_DE_FLUJO.md",
  mapRange: { from: 2136, to: 2140 },
  seal: 889,
  grieta: 895,
  resonance: 18,
  anomalyVariable: null,
  bossName: null,
  boss: null,
  anomalies: { declared: 0, items: [] },
  npcs: [],
  events: [...new Set(nexoEvents)].map((name) => ({
    name, episode: "NEXO", detail: "ver doc 07", effect: "", maps: [], cells: [], trigger: "action", instances: 1,
  })),
});

const stats = blueprint.episodes.map((e) => ({
  key: e.key,
  npcs: e.npcs.length,
  events: e.events.length,
  instances: e.events.reduce((sum, ev) => sum + ev.instances, 0),
  anomalies: e.anomalies.declared,
}));

if (CHECK) {
  console.log("episodio  NPCs  eventos  instancias  anomalías");
  for (const s of stats) console.log(`${s.key.padEnd(8)} ${String(s.npcs).padStart(4)} ${String(s.events).padStart(7)} ${String(s.instances).padStart(10)} ${String(s.anomalies).padStart(10)}`);
  const missing = blueprint.episodes.filter((e) => !e.npcs.length && e.key !== "NEXO" && e.key !== "EP01");
  if (missing.length) {
    console.log(`aviso: sin NPCs parseados en ${missing.map((e) => e.key).join(", ")} (revisar el formato de la tabla)`);
    process.exitCode = 1;
  }
  process.exit(process.exitCode ?? 0);
}

fs.writeFileSync(OUT, `${JSON.stringify(blueprint, null, 2)}\n`);
console.log(`plano de eventos: ${blueprint.episodes.length} episodios → ${path.relative(ROOT, OUT)}`);
for (const s of stats) console.log(`  ${s.key}: ${s.npcs} NPCs · ${s.events} eventos (${s.instances} instancias) · ${s.anomalies} anomalías`);#!/usr/bin/env node
/**
 * create_dimensional_nightmare_maps.mjs — Plano de recreación (blueprint).
 *
 * Lee las tablas del GDD (`docs/DIMENSIONAL_NIGHTMARE/01..07`) y escribe
 * `content/dimensional_nightmare_maps.json`: por cada mapa, su título, la FICHA
 * de referencia (R#-N) que le asignó el GDD, el recorte concreto en
 * `reference/dimensional_nightmare/slices/` y el tamaño de diseño.
 *
 * Este archivo es la entrada de `tools/apply_dimensional_nightmare_maps.mjs`
 * (E3). No toca el juego: solo lee documentación y escribe el plano.
 *
 * Uso:
 *   node tools/create_dimensional_nightmare_maps.mjs
 *   node tools/create_dimensional_nightmare_maps.mjs --check
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DOCS = path.join(ROOT, "docs", "DIMENSIONAL_NIGHTMARE");
const OUT = path.join(ROOT, "content", "dimensional_nightmare_maps.json");
const CHECK = process.argv.includes("--check");

const RESOURCES = {
  R1: { key: "r1_glitch_city", label: "Glitch City Compilation", cols: 4 },
  R2: { key: "r2_dark_forest", label: "Creepy Dark Forest", cols: 4 },
  R3: { key: "r3_king_unown", label: "King Unown (sprite)", cols: 1 },
  R4: { key: "r4_trono_unown", label: "El Trono del Rey Unown", cols: 4 },
  R5: { key: "r5_pueblos_tumbas", label: "Pueblos y Tumbas", cols: 4 },
  R6: { key: "r6_snowy_mountain", label: "Creepy Snowy Mountain", cols: 5 },
  R7: { key: "r7_catacumbas", label: "Catacumbas de Lavanda", cols: 4 },
  // Segundo anillo (W7–W9): hojas origen compuestas a partir del arte del autor
  // por `tools/dn_create_world_sheets.mjs` (misma rejilla 4×4 que los mosaicos).
  R8: { key: "r8_strangled_red", label: "Strangled Red (W7)", cols: 4 },
  R9: { key: "r9_buried_alive", label: "Buried Alive (W8)", cols: 4 },
  R10: { key: "r10_lavender_syndrome", label: "Lavender Town Syndrome (W9)", cols: 4 },
};

// `R7-1` · `R6-12` · `R5-3bis` · `R1-6 (void con código)` · `R5-1 vacío + R1`
const FICHA_RE = /\bR(\d{1,2})-(\d+)(bis)?\b/g;

/** Índice secuencial (1..N) a partir de "R7-13" o de la forma "R7-3,2" (fila,col). */
function fichaIndexOf(resource, number, bis) {
  return { index: Number(number), bis: Boolean(bis), resource };
}

const MAP_ROW = /^\|\s*(\d{4})\s*\|(.+)\|(.+)\|(.+)\|\s*(\d+)[×x](\d+)\s*\|(.*?)\|?\s*$/;
const MAP_ROW_5COL = /^\|\s*(\d{4})\s*\|(.+)\|(.+)\|\s*(\d+)[×x](\d+)\s*\|(.*?)\|?\s*$/;

function loadEpisodeMaps(file, episode) {
  const maps = [];
  for (const line of fs.readFileSync(path.join(DOCS, file), "utf8").split("\n")) {
    const six = line.match(MAP_ROW);   // | id | título | ficha | tileset | WxH | rol |
    const five = line.match(MAP_ROW_5COL); // | id | título | ficha | WxH | rol |
    let id, title, fichaCell, tileset, width, height, role;
    if (six) {
      [, id, title, fichaCell, tileset, width, height, role] = six;
    } else if (five) {
      [, id, title, fichaCell, width, height, role] = five;
      tileset = "";
    } else continue;
    if (!/\bR\d{1,2}-\d/.test(fichaCell)) continue; // filas de NPCs, objetos…: no son mapas
    maps.push({
      id: Number(id),
      episode,
      title: title.trim().replace(/\*\*/g, ""),
      fichaCell: fichaCell.trim(),
      tileset: (tileset ?? "").trim(),
      designSize: { width: Number(width), height: Number(height) },
      role: (role ?? "").trim().replace(/\*\*/g, ""),
    });
  }
  return maps;
}

function resolveFichas(cell) {
  const found = [];
  for (const m of cell.matchAll(FICHA_RE)) {
    const [, r, n, bis] = m;
    const resource = `R${r}`;
    if (!RESOURCES[resource]) continue;
    const info = fichaIndexOf(resource, n, bis);
    // evita duplicar la misma ficha repetida en la celda
    if (!found.some((f) => f.resource === resource && f.index === info.index)) found.push(info);
  }
  return found;
}

const maps = [];
for (const [file, episode] of [
  ["01_EP01_WHITE_HAND.md", "EP01"],
  ["02_EP02_LOST_SILVER.md", "EP02"],
  ["03_EP03_SNOW_ON_MT_SILVER.md", "EP03"],
  ["04_EP04_HYPNOS_LULLABY.md", "EP04"],
  ["05_EP05_POKEMON_BLACK.md", "EP05"],
  ["06_EP06_KING_UNOWN.md", "EP06"],
  ["07_MAPA_DE_FLUJO.md", "NEXO"],
  ["16_W7_STRANGLED_RED.md", "W7"],
  ["17_W8_BURIED_ALIVE.md", "W8"],
  ["18_W9_LAVENDER_SYNDROME.md", "W9"],
]) {
  maps.push(...loadEpisodeMaps(file, episode));
}

// Antesala (2040): es el hub, no tiene ficha de referencia.
maps.push({
  id: 2040,
  episode: "HUB",
  title: "Antesala de las Grietas",
  fichaCell: "—",
  tileset: "",
  designSize: { width: 30, height: 24 },
  role: "Entrada del Nightmare (hub); se construye a mano sobre tiles de la Gruta (2030)",
});

maps.sort((a, b) => a.id - b.id);

const blueprint = {
  title: "Dimensional Nightmare — plano de recreación de mapas",
  generatedBy: "tools/create_dimensional_nightmare_maps.mjs",
  docs: "docs/DIMENSIONAL_NIGHTMARE/01..07 (tablas «Mapa | Título | Recurso (ficha) | …»)",
  note: "La ficha R#-N se resuelve al recorte NN.png de reference/dimensional_nightmare/slices/<recurso>/. El tamaño es el de DISEÑO del GDD; el mapa se construye al tamaño real de la ficha × escala.",
  resources: RESOURCES,
  count: maps.length,
  maps: maps.map((m) => {
    const fichas = resolveFichas(m.fichaCell);
    return {
      id: m.id,
      episode: m.episode,
      title: m.title,
      tilesetHint: m.tileset,
      designSize: m.designSize,
      fichaCell: m.fichaCell,
      role: m.role,
      primary: fichas[0]
        ? {
            ...fichas[0],
            key: RESOURCES[fichas[0].resource].key,
            slice: `reference/dimensional_nightmare/slices/${RESOURCES[fichas[0].resource].key}/${String(fichas[0].index).padStart(2, "0")}.png`,
          }
        : null,
      extras: fichas.slice(1).map((f) => ({
        ...f,
        key: RESOURCES[f.resource].key,
        slice: `reference/dimensional_nightmare/slices/${RESOURCES[f.resource].key}/${String(f.index).padStart(2, "0")}.png`,
      })),
    };
  }),
};

if (CHECK) {
  const withoutFicha = blueprint.maps.filter((m) => !m.primary);
  const missingSlice = blueprint.maps.filter((m) => m.primary && !fs.existsSync(path.join(ROOT, m.primary.slice)));
  // Un recorte puede faltar por dos motivos muy distintos: que el mosaico de
  // ese mundo nunca se depositó (referencia pendiente) o que, estando el
  // mosaico, la ingesta no lo haya producido (fallo real). Sólo el segundo
  // detiene la cadena; el primero se anuncia y los mapas conservan su arte.
  const indexPath = path.join(ROOT, "reference", "dimensional_nightmare", "index.json");
  const pending = new Set();
  if (fs.existsSync(indexPath)) {
    for (const entry of JSON.parse(fs.readFileSync(indexPath, "utf8")).pending ?? []) pending.add(entry.key);
  }
  const esperando = missingSlice.filter((m) => pending.has(m.primary.key));
  const rotos = missingSlice.filter((m) => !pending.has(m.primary.key));
  console.log(`mapas en el plano: ${blueprint.count}`);
  console.log(`  con ficha: ${blueprint.count - withoutFicha.length} (sin ficha: ${withoutFicha.map((m) => m.id).join(", ") || "ninguno"})`);
  console.log(`  recortes presentes: ${blueprint.maps.filter((m) => m.primary).length - missingSlice.length}`);
  if (esperando.length) {
    const mundos = [...new Set(esperando.map((m) => m.primary.key))];
    console.log(`  pendientes de referencia: ${esperando.length} recorte(s) · mundos ${mundos.join(", ")}`);
    console.log("  → deposita el mosaico en Mapas/Crepypastas/ y ejecuta `npm run dn:ingest`");
    console.log("  (mientras tanto esos mapas conservan el arte ya instalado)");
  }
  if (rotos.length) {
    console.log(`  recortes ausentes: ${rotos.map((m) => `${m.id} (${m.primary.slice})`).join(", ")}`);
    console.log("  → ejecutar `npm run dn:ingest`");
    process.exitCode = 1;
  }
  process.exit(process.exitCode ?? 0);
}

fs.writeFileSync(OUT, `${JSON.stringify(blueprint, null, 2)}\n`);
const byEpisode = {};
for (const m of blueprint.maps) byEpisode[m.episode] = (byEpisode[m.episode] ?? 0) + 1;
console.log(`plano: ${blueprint.count} mapas → ${path.relative(ROOT, OUT)}`);
console.log(`  ${Object.entries(byEpisode).map(([k, v]) => `${k}: ${v}`).join(" · ")}`);
console.log(`  con ficha de referencia: ${blueprint.maps.filter((m) => m.primary).length} · sin ficha: ${blueprint.maps.filter((m) => !m.primary).map((m) => m.id).join(", ") || "ninguno"}`);#!/usr/bin/env node
/**
 * Crea/verifica `content/expansion_multiversal.json`: el plano de la Expansión
 * Multiversal posterior a la Ruta de Dios.
 *
 * Cuatro reglas de diseño gobiernan el plano y se comprueban aquí:
 *
 *   1. Nada se alcanza por un menú. Los siete relatos creepypasta se acceden
 *      por grietas repartidas por Kanto y Johto; el Atlas Mil por el capitán
 *      del puerto de Ciudad Carmín; la Isla Espejo por un espejo en el sótano
 *      sellado de la Mansión Pokémon de Isla Canela.
 *   2. Nadie queda atrapado. Cada destino tiene retorno al mundo y cada combate
 *      se puede perder.
 *   3. Purgar una grieta cierra una línea temporal: la cuenta vive en el
 *      contador 264 y en los sellos 940-947 que ya instala el Monte Silver.
 *      Con las siete purgadas aparece el punto de colapso; con las ocho, la
 *      Liga Oscura.
 *   4. El laboratorio de Oak recupera sus funciones originales: se retira la
 *      cápsula central nueva y Oak se queda como consejero, no como transporte.
 *
 * El plano no usa ni un switch ni una variable nueva: reutiliza el contador y
 * los sellos existentes, así que ninguna partida guardada queda en un estado
 * imposible por falta de slots.
 *
 * Uso:
 *   node tools/create_expansion_multiversal.mjs          # escribe el JSON
 *   node tools/create_expansion_multiversal.mjs --check  # solo verifica
 */
