  {name:"Pía Nido",sprite:"NPC 05",role:"ayudante de guardería",reason:"Lleva semanas cuidando el huevo sin figurar en el torneo.",conflict:"El huevo la eligió, pero teme que reclamarlo parezca ambición.",want:"Que la decisión se base en rutina, cuidado y consentimiento.",fear:"Que abran la incubadora para resolver una discusión de adultos.",tic:"Compara decisiones con temperatura y tiempo.",before:["Un huevo no necesita un ganador; necesita la misma voz mañana.","Cuando Yara se acerca, descansa. Cuando yo me alejo, baja la temperatura.","No quiero quedármelo por vencer a nadie. Quiero seguir llegando temprano."],during:["La luz está estable. Eso es un sí más claro que el marcador.","No abran la tapa; algunas respuestas necesitan calor, no testigos."],after:["La incubadora registró dos cuidadoras. Me gusta más que una campeona y una perdedora.","Yara vendrá los martes. Yo seguiré llegando antes del amanecer.","Cuando nazca, la primera decisión será suya: acercarse o esconderse."],optional:["Los huevos oyen discusiones como tormentas lejanas.","La paciencia también deja huellas; solo son más pequeñas."]}
 ],
 trainer:{name:"Prefecta Centella",type:"COOLTRAINER_F",sprite:"trchar008",story:"El equipo avanza desde crías presionadas a una evolución que elige su propio momento.",hint:"Los seis miembros mezclan apoyo, prioridad y cobertura; objetos, cambios y estados siguen disponibles.",team:[
  ["PICHU",88,"la promesa todavía pequeña",["THUNDERBOLT","CHARM","GRASSKNOT","PROTECT"],"FOCUSSASH"],["ELEKID",89,"la energía sin dirección",["THUNDERPUNCH","FIREPUNCH","ICEPUNCH","QUICKATTACK"],"LIFEORB"],["MAGBY",90,"la rabia ante el público",["FLAMETHROWER","PSYCHIC","FOCUSBLAST","CONFUSERAY"],"CHOICESPECS"],["RIOLU",91,"la confianza aprendida",["AURASPHERE","METEORMASH","EXTREMESPEED","SWORDSDANCE"],"FOCUSSASH"],["TOGETIC",92,"el cuidado compartido",["AIRSLASH","DAZZLINGGLEAM","ANCIENTPOWER","ROOST"],"LEFTOVERS"],["RAICHU",94,"la elección adulta",["VOLTTACKLE","IRONTAIL","BRICKBREAK","NASTYPLOT"],"LIFEORB"]]},
 cut:{trigger:"Hablar con Yara junto a la copa.",steps:["Yara rechaza la ceremonia delante del marcador.","Milo intenta bromear y el marcador convierte el ruido en puntos.","Pía acerca la incubadora sin abrirla.","El jugador decide apoyar una renuncia pública o pedir una evaluación privada.","Milo apaga su programa y confiesa la alteración.","La Prefecta propone una batalla de evaluación no eliminatoria.","La victoria activa el sello y registra a Yara y Pía como cuidadoras.","La incubadora enciende una luz y la salida queda libre."],question:"¿Cómo debe resolverse la ceremonia?",options:["Renuncia pública y clara","Evaluación privada de cuidado"],immediate:["El público aprende a escuchar un no.","La escuela suspende el premio mientras observa la rutina."],later:["Yara funda una regla de renuncia voluntaria.","Pía redacta el protocolo de elección del huevo."],failure:"La enfermería cura al equipo y la evaluación puede repetirse sin reiniciar la decisión.",reentry:"Milo omite la presentación y pregunta directamente si están listos."},
 reward:["LUCKYEGG","Sello de la Elección","La guardería reconoce cuidadores en lugar de propietarios.","El Archivo Final consulta si el jugador priorizó declaración pública o proceso privado.","El Huevo Suerte representa crecimiento elegido, no rendimiento impuesto."],flag:709
},
{
 mapId:1071,title:"El Campeón de Fecha Imposible",promise:"Un expediente anterior a la Liga obliga a decidir si una institución nació de un héroe borrado o de una falsificación creada para unir Kanto.",
 biome:"Centro Pokémon convertido en archivo provisional de una Liga que aún no debería existir",visual:["Seis retratos tienen fechas anteriores al edificio.","Una vitrina conserva una medalla sin región.","El sello oficial cambia de tinta bajo la luz del Centro."],ambient:["Las máquinas de curación marcan una fecha equivocada durante la investigación.","Tras la resolución, un reloj queda detenido en la fecha aceptada."],
 narrative:{premise:"Vera encuentra un expediente de Campeón firmado antes de la fundación de la Liga.",centralQuestion:"¿Una mentira que permitió cooperar sigue siendo fraude cuando todos conocen su origen?",setup:"El archivo describe un equipo y una final que nadie recuerda.",escalation:"La base de datos empieza a reconocer al jugador como retador de aquella temporada.",reversal:"Tomás admite que varios líderes inventaron al Campeón Cero para evitar una guerra entre gimnasios.",resolution:"El jugador conserva el expediente como mito fundador o lo reclasifica como acuerdo político.",globalConnection:"El tercer sello revela que Atlas trata las historias compartidas como infraestructura real."},
 voice:{tone:"documental, contenido y escéptico",lexicon:["expediente","folio","temporada","sello","acta","fundación"],sentenceRule:"Vera cita pruebas; Tomás responde con preguntas; K-0 habla en encabezados.",forbiddenPhrases:["Soy un entrenador","Qué gran combate","Este Pokémon es muy fuerte","Según la Pokédex","Debes derrotarme"]},
 npcs:[
  {name:"Vera Quill",sprite:"trchar028",role:"archivera de Liga",reason:"Audita documentos recuperados por Atlas.",conflict:"Su carrera depende de exponer falsificaciones, pero esta evitó violencia real.",want:"Publicar el expediente con todas sus contradicciones visibles.",fear:"Que la Liga borre el documento o lo convierta en propaganda.",tic:"Nombra folio y evidencia antes de emitir opinión.",before:["Folio uno: firma válida. Folio dos: edificio inexistente. ¿Cuál de los dos miente?","La tinta tiene cien años; la historia, según la Liga, tiene setenta.","No busco un héroe. Busco quién necesitaba que pareciera real."],during:["Ese orden de salida coincide con el acta, ¿pero quién lo recordó primero?","La base de datos acaba de añadir tu nombre sin pedirme permiso."],after:["Publicaré la falsificación junto a las vidas que protegió.","Un mito etiquetado sigue siendo evidencia; solo deja de fingir inocencia.","La Liga aceptó una nota al pie. Es una grieta pequeña y suficiente."],optional:["Los archivos no hablan. Crujen cuando alguien se sienta encima.","Una fecha imposible es una pregunta, no una orden de borrado."]},
  {name:"Tomás Rojo",sprite:"trchar069",role:"árbitro retirado",reason:"Es el último testigo del pacto entre gimnasios.",conflict:"Firmó el nombre del Campeón Cero y juró negarlo.",want:"Que el pacto sea juzgado por lo que evitó y por lo que ocultó.",fear:"Que los jóvenes repitan el engaño porque funcionó una vez.",tic:"Contesta cada afirmación con una pregunta precisa.",before:["¿Qué habrías ofrecido a ocho líderes que solo confiaban en una derrota?","¿Importa que el campeón no existiera si todos aceptaron perder contra él?","Firmé un nombre vacío. ¿Eso me vuelve árbitro o autor?"],during:["¿Reconoces al equipo porque es histórico o porque lo has visto mil veces?","Si ganas, ¿habrá existido por fin aquella final?"],after:["No necesito absolución. Necesito que nadie vuelva a llamar tradición a nuestro miedo.","El pacto evitó una guerra y fabricó décadas de silencio.","¿Puedes conservar ambas verdades sin convertir una en excusa?"],optional:["Una medalla sin región pesa como todas las demás.","Los jueces también dejan huellas en el campo." ]},
  {name:"K-0",sprite:"NPC 02",role:"auxiliar de archivo",reason:"Clasifica documentos según reglas escritas después del expediente.",conflict:"No puede archivar una temporada anterior a su propio sistema.",want:"Crear una categoría que admita origen incierto.",fear:"Que una excepción vuelva inútil todo el catálogo.",tic:"Habla mediante títulos de formulario.",before:["ESTADO: fecha válida, contexto ausente.","SOLICITUD: definir si un acuerdo puede competir en una Liga.","ERROR: el documento te reconoce como participante futuro."],during:["ACTUALIZACIÓN: el equipo histórico está respondiendo.","ADVERTENCIA: vencer no equivale a verificar."],after:["CLASIFICACIÓN NUEVA: mito fundador documentado.","NOTA: verdad política y verdad material pueden compartir carpeta.","RESPALDO: completado sin borrar la contradicción."],optional:["CAMPO VACÍO: nombre real del Campeón Cero.","SUGERENCIA: no rellenar por comodidad." ]}
 ],
 trainer:{name:"Campeón Cero",type:"COOLTRAINER_M",sprite:"trchar007",story:"Seis arquetipos de la primera Liga forman un campeón colectivo en lugar de una persona.",hint:"El equipo alterna clima, control y atacantes mixtos; no comparte una sola debilidad y recompensa leer el orden.",team:[
  ["ARCANINE",91,"valor atribuido al héroe",["FLAREBLITZ","CRUNCH","WILLOWISP","MORNINGSUN"],"LEFTOVERS"],["LAPRAS",92,"la ruta entre regiones",["SURF","ICEBEAM","SING","PERISHSONG"],"LEFTOVERS"],["EXEGGUTOR",93,"las voces de varios líderes",["PSYCHIC","GIGADRAIN","SLEEPPOWDER","LEECHSEED"],"CHOICESPECS"],["MACHAMP",94,"la fuerza pública del mito",["CLOSECOMBAT","STONEEDGE","BULLETPUNCH","KNOCKOFF"],"LIFEORB"],["ALAKAZAM",95,"el plan secreto",["PSYCHIC","SHADOWBALL","FOCUSBLAST","RECOVER"],"FOCUSSASH"],["DRAGONITE",97,"el símbolo final adoptado",["DRAGONPULSE","HURRICANE","EARTHQUAKE","DRAGONDANCE"],"LIFEORB"]]},
 cut:{trigger:"Examinar la medalla sin región.",steps:["Vera bloquea temporalmente la vitrina.","K-0 muestra la fecha imposible en las máquinas.","Tomás reconoce su firma y su juramento.","El jugador elige mito fundador o acuerdo político.","La base de datos genera al Campeón Cero.","Se libra una recreación con derrota no bloqueante.","Vera añade la clasificación elegida y activa el sello.","Los relojes vuelven a la fecha actual salvo uno."],question:"¿Cómo debe publicarse el expediente?",options:["Mito fundador documentado","Acuerdo político dramatizado"],immediate:["La medalla se exhibe con autoría colectiva.","La medalla se conserva como instrumento diplomático."],later:["Los campeones discuten quién hereda un mito.","Los líderes estudian el pacto como precedente peligroso."],failure:"K-0 restaura al equipo y conserva la elección sin validar el expediente.",reentry:"La simulación se reinicia desde la formación del equipo, no desde la confesión."},
