  ["PELIPPER",89,"mensajero meteorológico",["SURF","HURRICANE","RAINDANCE","TAILWIND"],"FOCUSSASH"],["AUDINO",90,"médica de campo",["WISH","PROTECT","HEALBELL","HYPERVOICE"],"LEFTOVERS"],["EXCADRILL",91,"excavador que debe detenerse",["EARTHQUAKE","IRONHEAD","RAPIDSPIN","STEALTHROCK"],"LIFEORB"],["CHANDELURE",92,"baliza del túnel",["SHADOWBALL","FLAMETHROWER","ENERGYBALL","TRICKROOM"],"CHOICESPECS"],["LUCARIO",93,"disciplina del gremio",["AURASPHERE","FLASHCANNON","DARKPULSE","EXTREMESPEED"],"LIFEORB"],["FLYGON",95,"guía de regreso",["EARTHQUAKE","DRAGONPULSE","ROCKSLIDE","UTURN"],"FOCUSSASH"]]},
 cut:{trigger:"Retirar del tablón la nota con la firma de Tilo.",steps:["La camilla se desplaza sola hasta el mapa del túnel.","Senda compara barro y esporas con la nota futura.","Tilo intenta aceptar el encargo sin autorización.","El jugador elige sellar el túnel o mantener una ruta vigilada.","Bruna convoca la proyección Equipo Retorno.","La batalla prueba si el gremio puede retirarse con disciplina.","La ruta elegida cambia en el tablón y se activa el sello.","Las notas futuras dejan de aparecer y la salida permanece abierta."],question:"¿Qué hacer con el túnel?",options:["Sellarlo hasta entenderlo","Mantener una ruta vigilada"],immediate:["El gremio redirige todos los encargos.","Senda establece turnos y puntos médicos."],later:["El Archivo registra una ausencia evitada.","El Archivo registra una ruta que exige responsabilidad continua."],failure:"Senda cura al equipo y la proyección vuelve al tablón sin cerrar rutas.",reentry:"Bruna conserva la decisión provisional y permite repetir solo la prueba."},
 reward:["ESCAPEROPE","Sello del Regreso","Las rutas futuras pueden reconocer retiradas como éxito.","El Archivo Final ofrece una salida adicional si el jugador valoró regresar.","La Cuerda Huida deja de simbolizar fracaso y se convierte en herramienta oficial del gremio."],flag:711
},
{
 mapId:1121,title:"Operación Rescate Demasiado Perfecto",promise:"Una patrulla que evacuó cada Pokémon de un incendio descubre que salvar individuos puede destruir un hábitat si nadie pregunta quién debe regresar.",
 biome:"Centro de coordinación Ranger rodeado por un corredor ecológico inexplicablemente vacío",visual:["Los comederos están llenos y no tienen huellas.","Las jaulas de transporte están abiertas hacia el bosque.","Un mapa de calor muestra vida alrededor de la ruta, nunca dentro."],ambient:["Los sonidos de aves desaparecen al acercarse al centro.","Tras la decisión regresan llamadas distintas según el plan de repoblación."],
 narrative:{premise:"Cora celebra un rescate sin bajas, pero la fauna se niega a regresar al corredor restaurado.",centralQuestion:"¿Cuándo termina un rescate y comienza la obligación de devolver autonomía al ecosistema?",setup:"La patrulla atribuye el vacío a trauma posterior al incendio.",escalation:"Eli descubre repelentes Ranger todavía activos bajo el suelo.",reversal:"Jo confiesa que mantuvo las balizas para proteger estadísticas perfectas, no a los Pokémon.",resolution:"El jugador retira todas las balizas o mantiene una red mínima controlada por comportamiento animal.",globalConnection:"El quinto sello enseña que Atlas puede preservar tanto una solución que impide que el mundo vuelva a vivir."},
 voice:{tone:"operativo, compasivo y autocrítico",lexicon:["pulso","corredor","baliza","reingreso","hábitat","protocolo"],sentenceRule:"Cora da órdenes cortas; Eli describe rastros; Jo habla en porcentajes hasta confesar.",forbiddenPhrases:["Soy un entrenador","Qué gran combate","Este Pokémon es muy fuerte","Según la Pokédex","Debes derrotarme"]},
 npcs:[
  {name:"Cora Pulso",sprite:"trchar016",role:"capitana Ranger",reason:"Dirigió la evacuación y debe autorizar el reingreso.",conflict:"Su operación perfecta está manteniendo vacío aquello que salvó.",want:"Corregir el protocolo sin deshonrar al equipo que arriesgó su vida.",fear:"Que admitir el error vuelva sospechoso cada rescate anterior.",tic:"Da una orden y luego pregunta a quién afecta.",before:["Patrulla, alto. ¿Alto para nosotros o para todo lo que intenta volver?","Cero bajas, cero nidos, cero huellas. Esa suma no es una victoria.","Retiraremos una baliza por vez y observaremos antes de felicitarnos."],during:["No persigan al primer Pokémon que aparezca; déjenlo elegir distancia.","La red está defendiendo el corredor de sus habitantes."],after:["Informe corregido: el rescate terminó hoy, no el día del incendio.","El equipo aceptó la enmienda. Las estadísticas tendrán que aprender humildad.","Escucha: no regresaron todos, pero regresaron por su cuenta."],optional:["Una orden corta puede tener una sombra muy larga.","El uniforme no vuelve neutral una buena intención." ]},
  {name:"Eli Rastro",sprite:"trchar009",role:"ecólogo de campo",reason:"Mide el reingreso de especies después del incendio.",conflict:"Sospechó de las balizas, pero calló para no enfrentar a la patrulla.",want:"Que la fauna marque el ritmo de recuperación.",fear:"Que su silencio sea tratado como prudencia científica.",tic:"Describe lo que falta antes de lo que ve.",before:["No hay plumas en el barro ni mordidas en la fruta. El vacío también deja muestras.","Las raíces crecieron alrededor de algo que sigue emitiendo.","Escribí 'trauma' porque era más cómodo que escribir 'nosotros'."],during:["Tropius mira el corredor y no entra. Esa es una medición, no un capricho.","Las balizas imitan depredadores sin saber cuándo detenerse."],after:["La primera huella cruzó el límite y volvió a salir. Perfecto: pudo elegir.","Publicaré mi demora junto al hallazgo.","Un hábitat sano no obedece el calendario del informe."],optional:["La ausencia tiene dirección si aprendes a mirar tallos doblados.","No todo silencio pertenece a un misterio." ]},
  {name:"Jo Cifra",sprite:"NPC 01",role:"operador de balizas",reason:"Mantuvo activa la red de seguridad después de la evacuación.",conflict:"Protegió un índice de éxito porque temía perder su puesto.",want:"Reparar el corredor sin ser reducido a un villano conveniente.",fear:"Que nadie distinga presión institucional de decisión personal.",tic:"Usa porcentajes cuando evita decir yo.",before:["La red conserva un noventa y nueve coma ocho por ciento de eficacia.","El reingreso no figuraba en mis objetivos trimestrales.","Puedo apagarla. Lo que no sé es cómo explicar por qué no lo hice ayer."],during:["La señal está subiendo; no, yo la dejé subir.","Ese Zoroark aprendió mi patrón mejor que yo."],after:["Registro personal: elegí la cifra y el corredor pagó la diferencia.","Aceptaré la sanción y también el turno de desmontaje.","El porcentaje de retorno ya no será una meta; será una observación."],optional:["Cien por ciento es una cifra sospechosa en un bosque.","Las balizas no mienten. Yo elegí qué pregunta hacerles." ]}
