 battle:{trainerName:"Maestra de Juegos",trainerType:"COOLTRAINER_F",sprite:"trchar008",storyToldByTeam:"Cada compañero encarna una atracción que aprendió a entretener sin encerrar a sus visitantes en un bucle.",counterplayHint:"El equipo alterna clima, prioridad y soporte; eliminar el control de velocidad abre múltiples respuestas y los objetos están permitidos.",canLose:true,bagAllowed:true,doubleBattle:false,team:[T("LUDICOLO",89,"baile de bienvenida",["SURF","GIGADRAIN","ICEBEAM","RAINDANCE"],"LEFTOVERS"),T("DELIBIRD",90,"regalo sin destinatario",["ICEBEAM","BRAVEBIRD","QUICKATTACK","PROTECT"],"FOCUSSASH"),T("AMBIPOM",91,"juego de puntería",["DOUBLEHIT","UTURN","BRICKBREAK","THUNDERPUNCH"],"LIFEORB"),T("MRMIME",92,"escenario invisible",["PSYCHIC","DAZZLINGGLEAM","THUNDERBOLT","PROTECT"],"LEFTOVERS"),T("TOGEKISS",93,"fanfarria serena",["AIRSLASH","AURASPHERE","ROOST","THUNDERWAVE"],"LEFTOVERS"),T("SNORLAX",95,"el asiento que por fin descansa",["BODYSLAM","CRUNCH","EARTHQUAKE","REST"],"LEFTOVERS")]},
