function build(d,index){return{mapId:d.id,tier:1,title:d.title,oneSentencePromise:d.promise,biome:{identity:d.identity,visualStorytelling:d.visual,ambientChanges:d.ambient,assetManifest:[...new Map(d.npcs.map(n=>[n.sprite,{type:"character",id:n.sprite,exists:true}])).values()]},narrative:d.narrative,voiceProfile:d.voice,npcs:d.npcs,battle:d.battle,cutscene:{trigger:d.steps[0],steps:d.steps.map((action,i)=>({order:i+1,eventCommand:i===3?"Show Choices":i===5?"Trainer Battle canLose":"RMXP event command",actor:i===3?"Jugador":i===5?d.battle.trainerName:"Escena",action,stateChange:i===6?`switch${d.flag}=true`:i===7?"map_state=resolved":null})),decision:d.decision,failurePath:"La derrota devuelve al jugador al punto de curación; no cambia la decisión ni bloquea la salida.",reentryPath:"La escena omite su introducción y permite repetir únicamente la prueba pendiente."},reward:d.reward,flags:{globalSwitches:[{id:d.flag,name:`POKEMOD ATLAS SEAL ${String(d.flag-707).padStart(2,"0")}`,setWhen:"Tras resolver la decisión y vencer.",readWhen:"Archivo Final y continuidad sectorial."}],variables:[{id:103,name:"POKEMOD ATLAS NARRATIVE SEALS",operation:"Incrementar una vez, protegido por self-switch A."}],selfSwitches:[{event:"Conductor de escena",letter:"A",purpose:"Bloquear recompensa repetida."},{event:d.npcs[0].name,letter:"B",purpose:"Diálogo posterior."}]},exits:[{destination:1001,condition:"always",purpose:"Retorno incondicional a Puerto Horizonte."}],qaClaims:q};}
