P("CASTFORM",91,"clima del presente",["WEATHERBALL","THUNDERBOLT","ICEBEAM","SUNNYDAY"],"FOCUSSASH","Recuerda que las condiciones actuales importan más que la etiqueta."),
P("BRONZONG",92,"vitrina sellada",["PSYCHIC","FLASHCANNON","EARTHQUAKE","PROTECT"],"LEFTOVERS","Custodia el lote sin declarar destino."),
P("PORYGONZ",93,"diario incompleto",["TRIATTACK","THUNDERBOLT","ICEBEAM","DARKPULSE"],"LIFEORB","Intenta completar datos futuros como si fueran instrucciones."),
P("XATU",94,"posibilidad observada",["PSYCHIC","AIRSLASH","UTURN","ROOST"],"LEFTOVERS","Mira varios desenlaces sin elegir por el equipo."),
P("DIALGA",96,"fecha sin mandato",["DRAGONPULSE","FLASHCANNON","AURASPHERE","THUNDERBOLT"],"LIFEORB","Cierra separando control temporal de autoridad moral.") ]},
decision:{question:"¿Qué ocurrirá con los objetos prematuros?",options:["Devolverlos con contexto","Sellar el lote para estudio"],immediateDifferences:["Cada dueño recibe su objeto y un registro de futuros incompatibles.","Vesna clausura vitrinas y publica mediciones sin nombres personales."],laterDifferences:["Los objetos podrán usarse sin representar su pérdida prevista.","La investigación comparará posibilidades sin alterar las expediciones."]},
reward:{item:"TIMERBALL",narrativeToken:"Sello del Vestigio",globalEffect:"Atlas deja de convertir objetos futuros en órdenes para el presente.",futurePayoff:"El final devolverá hallazgos contextualizados o abrirá un archivo sellado.",whyMeaningful:"La Acopio Ball mide tiempo transcurrido sin afirmar que todo desenlace está fijado."},
steps:["Una ráfaga deposita el diario futuro de Daro.","Ena encuentra una placa de rescate fechada mañana.","Vesna revela dos futuros incompatibles en la misma vitrina.","El jugador elige devolución contextual o custodia sellada.","La presión inversa convoca al Custodio de Isobaras.","La batalla permite curación, objetos y retirada.","La expedición corrige sus protocolos y recibe el sello.","La manga de viento vuelve a señalar el clima presente."]
