P("CORSOLA",90,"hábitat presente",["POWERGEM","SCALD","RECOVER","STEALTHROCK"],"FOCUSSASH","Representa refugios actuales que no deben sacrificarse en silencio."),
P("CURSOLA",91,"arrecife perdido",["SHADOWBALL","POWERGEM","ENERGYBALL","WILLOWISP"],"LIFEORB","Hace visible el costo de esperar demasiado."),
P("OMASTAR",92,"memoria fósil",["SURF","ICEBEAM","POWERGEM","SHELLSMASH"],"FOCUSSASH","Recuerda restauraciones basadas en vidas antiguas."),
P("CRADILY",93,"parcela estable",["GIGADRAIN","POWERGEM","EARTHPOWER","RECOVER"],"LEFTOVERS","Ancla larvas futuras en límites revisables."),
P("LAPRAS",94,"corredor migratorio",["SURF","ICEBEAM","THUNDERBOLT","PSYCHIC"],"ASSAULTVEST","Transporta especies sin imponer residencia."),
P("SUICUNE",96,"agua entre tiempos",["SURF","ICEBEAM","EXTRASENSORY","CALMMIND"],"LEFTOVERS","Cierra purificando sin borrar la historia química del arrecife.") ]},
decision:{question:"¿Cómo continuará la restauración paradójica?",options:["Parcelas contenidas y revisables","Corredores vigilados y reversibles"],immediateDifferences:["Neris limita larvas a viveros con evaluación comunitaria.","Maia abre dos rutas y conserva compuertas de emergencia."],laterDifferences:["Cada expansión necesitará demostrar beneficio y bajo desplazamiento.","Las migraciones se seguirán entre sectores y podrán detenerse."]},
reward:{item:"SHOALSHELL",narrativeToken:"Sello del Arrecife Tardío",globalEffect:"Atlas conecta restauración futura con consentimiento ecológico presente.",futurePayoff:"La convergencia mostrará parcelas recuperadas o corredores intersectoriales.",whyMeaningful:"La Concha Nácar guarda capas de mareas distintas sin convertir una en reemplazo de la otra."},
steps:["Aleta Tardía hace florecer coral sobre una poza vacía.","Maia muestra refugios actuales desplazados por las larvas.","Olan revela la acidificación procedente de otro sector.","El jugador elige parcelas o corredores reversibles.","Las piscinas forman a la Custodia del Arrecife.","La prueba permite objetos, curación y retirada.","El consejo adopta límites y recibe el sello.","Una larva cruza únicamente por la ruta acordada."]
},
{
id:1496,flag:727,title:"Los Dos Nombres del Cometa",promise:"Una fusión estable pide conservar los dos nombres de quienes la formaron, mientras el centro de crianza insiste en registrarla como una criatura nueva o como un accidente que debe revertirse.",
identity:"Centro de crianza transformado en clínica de convergencia, con dos habitaciones unidas por una franja de luz",visual:["Dos placas con nombres proyectan una sola sombra de borde doble.","Los historiales usan pronombres corregidos a mano.","Una incubadora vacía conserva dos ritmos cardíacos."],ambient:["Dos tonos responden desde una misma posición.","Tras la decisión, la megafonía pronuncia ambos nombres juntos o alternados."],
narrative:{premise:"Nilo y Vera quedaron fusionados durante el paso de un cometa y rechazan el nombre clínico Orbe.",centralQuestion:"¿Una identidad combinada debe elegir entre ser una persona nueva y conservar a quienes continúan dentro de ella?",setup:"La doctora Elia necesita un registro para tratarlos y propone un único nombre operativo.",escalation:"El procedimiento de separación empieza a borrar recuerdos que Nilo y Vera construyeron juntos después de fusionarse.",reversal:"Paz demuestra que la fusión cambia de voz sin dividir conciencia: ambos nombres son relaciones activas, no restos médicos.",resolution:"El jugador decide crear un registro conjunto con dos nombres o mantener expedientes enlazados para una posible separación voluntaria.",globalConnection:"El sello veinte revela que Atlas reduce identidades complejas a una etiqueta porque sus puertas solo leen un campo."},
voice:{tone:"ético, reflexivo y luminoso",lexicon:["nombre","registro","vínculo","pulso","consentimiento","separación","continuidad"],sentenceRule:"Nilo/Vera alterna imágenes; Elia define procedimientos; Paz pregunta quién gana y quién pierde con cada término."},
npcs:[
N("Nilo y Vera","NPC 04","persona fusionada","Vive en la clínica mientras el sistema rechaza su doble registro.","Desea ambos nombres y también teme que esa decisión obligue a permanecer fusionada para siempre.","Acceder a tratamiento sin renunciar a continuidad ni opción futura.","Que cada cambio de voz sea usado como prueba de inestabilidad.","Alterna una imagen cálida y otra fría antes de responder juntos.",D(["Nilo recuerda sol en las manos; Vera, nieve en la nuca. Los dos decimos presente.","Orbe cabe en la puerta, pero ninguno reconoce ese llamado.","Queremos dos nombres, no dos jaulas ni una fusión obligatoria."],["La luz tira hacia ambos lados; nosotros elegimos quedarnos quietos.","No borren el recuerdo del cometa solo porque pertenece a los dos."],["La puerta pronuncia Nilo y Vera sin decidir quién va primero.","Conservamos una cita de separación como opción, no amenaza.","Nuestro primer documento conjunto tiene espacio para cambios."],["Compartir pulso no reparte la voz en mitades.","A veces respondemos juntos; a veces uno escucha."])),
N("Elia Bifase","trchar008","médica de convergencia","Desarrolló el tratamiento que mantiene estable la fusión.","Su protocolo salva cuerpos, pero exige categorías que invalidan lo que no puede medir.","Dar cuidado continuo con registros flexibles.","Ser responsable si una identidad cambia después de aceptar el tratamiento.","Define un término y luego pregunta si todavía sirve.",D(["Paciente único: término útil para dosis. Término insuficiente para historia.","Escribí Orbe porque el formulario no aceptó una conjunción.","La estabilidad clínica no demuestra una identidad simple."],["Separación: procedimiento disponible. No resultado obligatorio.","Detengo el borrado; el consentimiento cambió."],["El historial admite dos nombres, una dosis y decisiones futuras.","Revisé otros expedientes que llamamos errores.","La clínica aprendió a tratar sin resolver a la persona."],["Una categoría puede sostener una jeringa y aun así fallar como nombre.","El protocolo debe adaptarse antes que el paciente."])),
N("Paz Conjunción","trchar028","defensora de pacientes","Impugna el registro único y entrevista a ambas voces.","Habla con firmeza por Nilo y Vera y corre el riesgo de sustituir su propia respuesta.","Crear un precedente sin convertir a esta persona en símbolo permanente.","Que aceptar expedientes enlazados debilite derechos presentes.","Pregunta quién obtiene facilidad con cada etiqueta.",D(["Si usamos Orbe, ¿quién gana comodidad y quién pierde respuesta?", "Dos nombres complican el archivo, no el pulso.", "Preparé un discurso brillante y olvidé preguntar si querían pronunciarlo."],["La clínica ofrece dos caminos; Nilo y Vera deben marcar el ritmo.","¿Quién pierde memoria si aceleramos esta luz?"],["El precedente incluye derecho a cambiar de formato.","Nilo y Vera hablaron ante el consejo; yo tomé notas.","Defender también significa apartarse del micrófono."],["Cuando un formulario dice imposible, suele describir al formulario.","Una conjunción no fusiona derechos; los conecta."]))
],
battle:{trainerName:"Mediadora del Cometa",trainerType:"PSYCHIC_F",sprite:"trchar069",storyToldByTeam:"Tres pares narran unión y diferencia hasta dos formas digitales que comparten origen sin perder sus nombres.",counterplayHint:"El equipo cubre varios tipos, pero Siniestro, Tierra, Lucha y estados permiten responder; ninguna fase exige una condición oculta.",canLose:true,bagAllowed:true,doubleBattle:false,team:[
P("PLUSLE",91,"voz afirmativa",["THUNDERBOLT","GRASSKNOT","DAZZLINGGLEAM","NASTYPLOT"],"FOCUSSASH","Representa a Nilo sin separarlo del vínculo."),
P("MINUN",91,"voz complementaria",["THUNDERBOLT","GRASSKNOT","DAZZLINGGLEAM","NASTYPLOT"],"FOCUSSASH","Representa a Vera sin reducirla a una mitad."),
P("ESPEON",93,"recuerdo luminoso",["PSYCHIC","DAZZLINGGLEAM","SHADOWBALL","CALMMIND"],"LIFEORB","Conserva memorias anteriores a la convergencia."),
P("UMBREON",93,"recuerdo reservado",["DARKPULSE","TOXIC","MOONLIGHT","PROTECT"],"LEFTOVERS","Protege experiencias que no deben compartirse automáticamente."),
P("PORYGON2",95,"registro enlazado",["TRIATTACK","ICEBEAM","THUNDERBOLT","RECOVER"],"LEFTOVERS","Mantiene expedientes compatibles sin cerrar evolución."),
P("PORYGONZ",97,"nombre no normalizado",["TRIATTACK","DARKPULSE","ICEBEAM","THUNDERBOLT"],"LIFEORB","Cierra demostrando que desviarse del formato no invalida existencia.") ]},
decision:{question:"¿Cómo registrará la clínica a Nilo y Vera?",options:["Un registro conjunto con dos nombres","Dos expedientes enlazados y reversibles"],immediateDifferences:["Elia modifica el sistema para aceptar la conjunción.","Paz enlaza historiales sin programar una separación obligatoria."],laterDifferences:["Otras fusiones podrán mantener múltiples nombres en una identidad actual.","Cada continuidad conservará derechos y una decisión futura sobre separación."]},
reward:{item:"DESTINYKNOT",narrativeToken:"Sello de la Conjunción",globalEffect:"Las puertas de Atlas aceptan identidades con más de un nombre autorizado.",futurePayoff:"El Archivo Final llamará conjuntamente o consultará expedientes enlazados.",whyMeaningful:"El Lazo Destino simboliza vínculo sin declarar que la unión sea irreversible."},
steps:["La puerta clínica rechaza la conjunción de nombres.","Elia muestra recuerdos compartidos que el procedimiento está borrando.","Paz devuelve el micrófono a Nilo y Vera.","El jugador elige registro conjunto o expedientes enlazados.","La luz del cometa convoca a la Mediadora.","La batalla conserva Mochila, curación y salida.","La clínica actualiza el sistema y registra el sello.","La megafonía pronuncia ambos nombres y espera respuesta."]
}
];
