  R(1365,"La Final que Pronosticaba Campeones","Un torneo en las nubes ajusta el marcador según el clima previsto y otorga ventaja a equipos que aún no han entrado al campo.","Separar pronóstico, condiciones reales y puntuación antes de la siguiente ronda.",
