        ["Los triunfos subían y los entrenadores bajaban la mirada", "me apresuré: conté victorias que nadie había ganado", "pondré asteriscos y abriré una columna de renuncias"],
        ["el marcador distingue victoria propia y victoria asistida", "Blissey guarda las renuncias junto a las curaciones", "ningún partido nuevo empieza con un asterisco abierto"]),
      N("Basto Ofrenda", "NPC 04", "cuidador de la ofrenda", "SPIRITOMB", "Spiritomb", "que la ofrenda descanse sin comprar victorias", "dejó la ofrenda encendida toda la noche por costumbre",
        ["La ofrenda arde desde hace noches sin que nadie la apague", "tardé en reconocer que la costumbre costaba victorias ajenas", "la ofrenda tendrá horario y su apagado será solemne"],
        ["la ofrenda se enciende con permiso y se apaga con gratitud", "Spiritomb se aquieta cuando el marcador se corrige", "las renuncias se leen en voz alta, sin nombres si se pide"])],
    ["¿Qué hará la guardería con las victorias ayudadas?", ["Renunciar públicamente a ellas", "Contarlas como récord de la casa"]],
    ["la guardería vacía la columna de récords y abre un libro de renuncias", "la ofrenda se mantiene solo en fechas acordadas"],
    ["ROWAPBERRY", "Devuelve sin ruido un regalo que nadie quiso aceptar."]),
  R(1833, "El Cartucho que Ofrecía Victoria Fácil",
    "Un cartucho negro regala victorias fáciles a cambio de nada y el pueblo debate si sellarlo o convertirlo en atracción.",
    "Que todo reto del cartucho permita perder y registre sus victorias como asistidas.",
    ["Prueba con derrota posible", ["Todo reto admite derrota y retirada.", "Las victorias del cartucho se registran como asistidas.", "El sellado requiere votación pública."], "El centro Pokémon y la salida del pueblo quedan fuera del reto."], [
      N("Tuno Cartucho", "trchar008", "coleccionista de juegos", "SCRAFTY", "Scrafty", "conservar el cartucho como historia, no como máquina de trofeos", "organizó un torneo con victorias garantizadas",
        ["El torneo repartió coronas y nadie perdió ni un partido", "me precipité: prometí victorias para llenar la sala", "cada reto del cartucho tendrá retirada libre y marcador con asterisco"],
        ["el cartucho juega sin prometer triunfos y la sala sigue llena", "Scrafty guarda el cartucho cuando el público se agota", "el registro de asistidas se lee antes de cada partida"]),
      N("Eli Victoria", "NPC 04", "alcaldesa del barrio", "KROOKODILE", "Krookodile", "decidir el futuro del cartucho sin prohibir la memoria", "ordenó ocultar el cartucho para no asustar a las familias",
        ["El cartucho desapareció del estante y el rumor creció", "tardé en reconocer que esconderlo parecía miedo", "convocaré votación y explicaré los riesgos reales"],
        ["la votación quedó citada y el cartucho vuelve al estante", "Krookodile vigila la urna sin intervenir", "sea cual sea el resultado, el pueblo conocerá su historia"])],
    ["¿Qué hará el pueblo con el cartucho?", ["Sellarlo tras votación pública", "Conservarlo como atracción regulada"]],
    ["el pueblo fija la votación y sus condiciones por escrito", "el centro Pokémon ofrece marcadores honestos para el torneo"],
    ["EJECTPACK", "Abandona con dignidad una partida que nunca quiso jugarse de verdad."]),
  R(1840, "La Curación que Cobraba una Victoria",
    "Un programa de curación de la costa cobra victorias futuras como deuda y los entrenadores combaten enfermos para saldarla.",
    "Que ninguna curación dependa de una victoria y que la deuda deje de ser pelea.",
    ["Deuda sin pelea", ["La curación nunca exige combates.", "Las donaciones son voluntarias y públicas.", "El libro de cuentas se muestra a quien lo pide."], "La enfermería de emergencia cura antes de preguntar nada."], [
      N("Lina Deuda", "trchar009", "coordinadora del programa", "WIGGLYTUFF", "Wigglytuff", "curar sin atar la recuperación a un resultado", "firmó contratos de victorias futuras para financiar la enfermería",
        ["Los contratos de curación acumulan victorias sin dueño feliz", "me apresuré: financié la enfermería con triunfos ajenos", "separaré donación, curación y cualquier gratitud"],
        ["la enfermería cura y el libro de donaciones queda abierto", "Wigglytuff cobra sonriendo cero victorias", "los contratos viejos se archivarán como lección"]),
      N("Roque Historial", "NPC 04", "entrenador endeudado", "LUVDISC", "Luvdisc", "combatir sano sin pelear por una deuda", "ocultó una lesión para cumplir su cuota de victorias",
        ["Mi equipo jugaba enfermo para no deber más partidas", "tardé en reconocer que la deuda me quitó el criterio", "renunciaré a la cuota y pediré curación sin promesas"],
        ["la renuncia quedó firmada y mi equipo volvió al agua", "Luvdisc nada sin reloj ni cuota detrás", "contaré mi caso a quien firme el próximo contrato"])],
    ["¿Cómo se financiará la enfermería?", ["Donaciones voluntarias públicas", "Contratos de victorias futuras"]],
    ["la enfermería abre su libro de donaciones y quita los contratos", "el pueblo acuerda que ninguna curación se cobra en victorias"],
    ["SITRUSBERRY", "Restaura poco a poco, sin pedir a nadie una victoria a cambio."]),
  R(1851, "La Excavación que Ensamblaba un Monstruo",
    "Una excavación mezcló huesos de especies distintas para montar un monstruo de museo y los visitantes creen que la criatura existió.",
    "Etiquetar procedencia de cada fragmento y exhibir los montajes como réplicas, nunca como hallazgos.",
    ["Cartela de procedencia", ["Etiquetar origen antes de montar.", "Exhibir mezclas como réplicas declaradas.", "Ningún entierro escenificado se presenta como real."], "La sala de familias y la salida no participan de la exhibición."], [
      N("Yelmo Osario", "trchar008", "director de excavación", "MAROWAK", "Marowak", "reconstruir ambientes sin fabricar criaturas", "unió cuernos de tres sitios y presentó la pieza como especie nueva",
        ["El cartel del museo presenta una especie que nunca existió", "me precipité: ensamblé tres sitios en un solo esqueleto", "desmontaré la pieza y etiquetaré cada fragmento"],
        ["las vitrinas distinguen fósil, réplica y conjetura", "Marowak toca cada etiqueta antes de que se cierre la vitrina", "el montaje volverá a exhibirse solo como advertencia"]),
      N("Pía Estrato", "NPC 04", "geóloga de campo", "YAMASK", "Yamask", "explicar la tierra sin escenificar entierros", "autorizó una recreación de entierro para atraer público",
        ["La recreación del entierro llenó el calendario de visitas", "tardé en reconocer que había puesto duelo ajeno en escena", "la recreación se retirará y la tierra explicará sola"],
        ["la sala vuelve a la estratigrafía y el público aprende igual", "Yamask acompaña las visitas sin escenificar nada", "las familias podrán preguntar sin guiñarle el ojo al cartel"])],
    ["¿Cómo se mostrará la excavación?", ["Piezas con cartela de procedencia", "Montajes espectaculares de época"]],
    ["el museo aprueba el reglamento de cartelas y retira el entierro escenificado", "la excavación publica su diario con los errores incluidos"],
    ["DUBIOUSDISC", "Guarda la duda sobre un hallazgo fabricado hasta que su procedencia quede clara."]),
  R(1858, "El Retrato del Esqueleto Inexistente",
    "Un museo exhibe retratos de un esqueleto que nunca se encontró y las guías infantiles convierten la conjetura en monstruo de cuento.",
    "Separar ilustración e hallazgo real y devolver los cuentos al horario de historias, no a la sala de fósiles.",
    ["Retrato con fuente", ["Ilustrar solo hallazgos reales en la sala de fósiles.", "Marcar la ficción con el sello de hora de cuentos.", "Publicar guías infantiles separadas del material científico."], "El patio infantil y la salida quedan fuera del recorrido de terror."], [
      N("Lupa Cartela", "trchar009", "ilustradora científica", "PUMPKABOO", "Pumpkaboo", "dibujar lo encontrado sin convertir la duda en bestia", "rellenó vacíos del esqueleto con rasgos de criaturas inventadas",
        ["La sala muestra mandíbulas que ningún hallazgo respalda", "me apresuré: dibujé conjeturas con luz de monstruo", "devolveré la mandíbula al cuaderno y marcaré la duda"],
        ["la ilustración enseña huesos reales y preguntas abiertas", "Pumpkaboo ilumina los huecos sin rellenarlos", "la conjetura vivirá en papel aparte, con su sello"]),
      N("Ren Pincel", "NPC 04", "guía de familias", "HOUNDOOM", "Houndoom", "contar historias sin asustar a quien viene a aprender", "leyó la leyenda del esqueleto con efectos de sonido",
        ["Los cuentos con truenos terminaban en llanto y en visitas cortas", "tardé en reconocer que el susto no explicaba nada", "separaré hora de cuentos y hora de fósiles"],
        ["las familias eligen el recorrido y nadie sale asustado por error", "Houndoom se queda en silencio durante la hora de cuentos", "las guías infantiles tendrán su propio mapa"])],
    ["¿Dónde vivirán los retratos del esqueleto?", ["Sala de fósiles solo con fuentes", "Exhibición mixta de hallazgo y leyenda"]],
    ["el museo separa las salas y sella la ficción con su sello", "las guías infantiles se reimprimen con el mapa nuevo"],
    ["MICLEBERRY", "Aporta exactitud a una descripción que se había atrevido a imaginar demasiado."]),
  R(1865, "La Piedra que Simulaba un Entierro",
    "Una instalación de cristal recrea un rito funerario para turistas y las familias del pueblo piden que deje de ser espectáculo.",
    "Que los ritos vuelvan a ser privados y el cristal se venda como decoración, no como reliquia.",
    ["Ritual sin público", ["Los ritos se realizan sin cámara ni entrada.", "El cristal se vende como decoración declarada.", "Toda ceremonia requiere permiso de la familia."], "La plaza y el regreso permanecen abiertos durante cualquier ceremonia."], [
      N("Crista Ritual", "trchar008", "artista de instalaciones", "WHIMSICOTT", "Whimsicott", "crear belleza sin alquilar el duelo de nadie", "vendió entradas para una ceremonia que no era suya",
        ["La ceremonia de cristal tenía butacas numeradas", "me precipité: convertí un rito en función de tarde", "la instalación volverá al arte y el rito a su familia"],
        ["la obra brilla sin público sentado y las ceremonias son privadas", "Whimsicott apaga los cristales cuando llega la familia", "las entradas se sustituyen por visitas de día"]),
      N("Maura Lápida", "NPC 04", "portavoz de las familias", "PURUGLY", "Purugly", "proteger la intimidad sin prohibir el arte", "organizó un boicot que ahuyentó a todo el pueblo",
        ["Mi boicot vació la plaza y endureció a los artistas", "tardé en reconocer que cerrar la puerta no abrió diálogo", "pediré permiso, horario y una condición por escrito"],
        ["familias y artista firmaron el acuerdo de ceremonias", "Purugly se sienta en la puerta sin impedir el paso", "el arte del cristal tendrá su temporada sin rito"])],
    ["¿Qué se venderá en la tienda de la instalación?", ["Cristal decorativo declarado", "Réplicas de reliquia del rito"]],
    ["la tienda retira las reliquias y expone el cristal como decoración", "las familias guardan un ejemplar del acuerdo firmado"],
    ["ENIGMABERRY", "Absorbe la curiosidad que lastima cuando se exhibe como producto."]),
  R(1876, "El Reporte que Cruzaba la Nieve",
    "Un equipo aislado sigue enviando reportes desde la nieve y los rescatistas discuten quién debe partir primero.",
    "Ordenar el rescate por necesidad real y no por fama, repitiendo posición y suministros en cada reporte.",
    ["Cadena de reporte", ["Cada reporte repite posición y suministros.", "El relevo confirma recepción con acuse.", "El orden de rescate se fija por necesidad, no por nombre."], "La cueva mantiene un refugio cálido sin depender de la cola de rescate."], [
      N("Neve Reporte", "trchar009", "radiooperadora de montaña", "ABOMASNOW", "Abomasnow", "mantener la cadena de reportes viva sin gritar", "transmitió sin pedir acuse y dio la señal por recibida",
        ["Los reportes salen y nadie confirma si llegan", "me apresuré: di por enviado cada parte sin esperar acuse", "pediré confirmación y repetiré posición y suministros"],
        ["cada transmisión cierra con acuse y número de parte", "Abomasnow marca la ruta del relevo sobre la nieve", "el cuaderno de suministros viajará con el primer rescate"]),
      N("Tor Rescate", "NPC 04", "jefe de relevo", "AVALUGG", "Avalugg", "rescatar por orden de necesidad aunque la prensa pida nombres", "adelantó a un equipo famoso dejando atrás un caso urgente",
        ["El equipo famoso llegó primero y el urgente esperó dos días", "tardé en reconocer que la fama pesó más que el parte médico", "el orden saldrá de los partes, no de las cámaras"],
        ["la cola de rescate obedece a la necesidad declarada", "Avalugg abre la pista sin preguntar quién es quién", "la prensa recibirá los partes con retraso deliberado"])],
    ["¿Cómo se ordenará la cola de rescate?", ["Por necesidad médica declarada", "Por antigüedad del reporte"]],
    ["el relevo publica su criterio de orden en la entrada", "la cueva abre su refugio cálido a todo orden de la cola"],
    ["NEVERMELTICE", "Conserva un reporte helado hasta que alguien por fin lo encuentre."]),
  R(1883, "El Equipo que No Pedía Rescate",
    "El equipo aislado rechaza el rescate por orgullo y los guías insisten con cámaras encendidas.",
    "Ofrecer ayuda sin presión: suministros primero, puertas de salida documentadas, cámaras apagadas.",
    ["Permiso de ayuda", ["Ofrecer sin presionar.", "Enviar suministros antes que entrevistas.", "Documentar rutas de salida sin exigir declaración."], "La ruta de retirada del equipo permanece marcada y expedita."], [
      N("Nida Ayuda", "trchar008", "guía de relevo", "PILOSWINE", "Piloswine", "ayudar sin arrancar una declaración", "llegó con el micrófono puesto y la ayuda en la mochila cerrada",
        ["Mi primera oferta sonó a noticia y la puerta se cerró", "me precipité: enseñé la cámara antes que los suministros", "dejaré el equipo a la puerta y preguntaré desde lejos"],
        ["los suministros entraron y las cámaras siguen guardadas", "Piloswine carga sin exigir nombre para el parte", "el equipo decidirá cuándo se habla y cuándo no"]),
      N("Risco Orgullo", "NPC 04", "capitán del equipo aislado", "URSARING", "Ursaring", "mantener a su equipo unido sin convertirlo en fortaleza", "rechazó ayuda tres veces para no parecer débil",
        ["Mi equipo comía raciones cortas mientras yo firmaba orgullo", "tardé en reconocer que confundí coherencia con testarudez", "aceptaré suministros y reservaré la retirada para cuando toque"],
        ["el equipo acepta suministros y conserva su ruta de salida", "Ursaring camina junto al relevo sin escolta obligatoria", "cuando hablemos, será con las manos vacías y sin micrófonos"])],
    ["¿Cómo ofrecerá el relevo su ayuda?", ["Suministros primero y sin cámaras", "Operación con cobertura mediática"]],
    ["el relevo adopta el protocolo de suministros primero", "el equipo aislado recibe un mapa de retirada actualizado"],
    ["SALACBERRY", "Da impulso a una ayuda que se ofreció sin esperar a la bandera correcta."]),
  R(1890, "La Pintura que Esperaba a los Ausentes",
    "Un mural inacabado espera el regreso de un equipo y la galería quiere terminarlo con sustitutos para la inauguración.",
    "Que el mural conserve su parte sin terminar y toda homenaje sustituto se muestre como obra aparte.",
    ["Obra abierta", ["Lo inacabado se inaugura sin completar.", "Los homenajes sustitutos se exponen como obras propias.", "Los artistas ausentes conservan el pincel de su sección."], "La salida de la galería y la cafetería quedan fuera del recorrido del mural."], [
      N("Sora Pincel", "trchar009", "coordinadora de la galería", "SPRITZEE", "Spritzee", "inaugurar sin cerrar una historia ajena", "encargó a otros pintores terminar la sección del equipo ausente",
        ["Los sustitutos pintaron una sección que no les pertenecía", "me precipité: quise una inauguración completa y toqué lo ajeno", "colgaré los homenajes al lado, con nombre propio"],
        ["el mural luce su hueco y los homenajes cuelgan firmados", "Spritzee vuela por el borde sin rozar la pintura", "la sección del equipo guarda sus pinceles hasta su regreso"]),
      N("Tilo Ausente", "NPC 04", "familiar del equipo", "DEDENNE", "Dedenne", "que el mural espere sin convertirse en rehén", "presionó para cerrar el mural antes de tiempo por hastío",
        ["Yo mismo quise pintar encima y acabar de una vez", "tardé en reconocer que el cansancio me hacía traicionar la espera", "el mural espera y nosotros esperamos con él"],
        ["la inauguración aceptó el hueco y el público entendió", "Dedenne se posa en el marco cada tarde de visita", "cuando vuelvan, elegirán ellos el pincel"])],
    ["¿Qué verá el público en la inauguración?", ["Mural inacabado con sus huecos", "Versión completada por sustitutos"]],
    ["la galería inaugura el mural tal cual y abre el libro de visitas", "los homenajes se exponen en la sala contigua con sus firmas"],
    ["SILVERPOWDER", "Añade brillo a lo terminado sin rellenar lo que todavía espera."]),
  R(1901, "El Dato que Intentaba Clasificar al Jugador",
    "Datos corruptos de la cueva intentan clasificar al jugador en categorías fijas y las etiquetas se pegan a los entrenadores.",
    "Convertir toda etiqueta en consejo reversible y poner en cuarentena las filas corruptas sin borrarlas.",
    ["Etiqueta reversible", ["Las categorías son consejos, nunca sentencias.", "El jugador puede cambiar su etiqueta cuando quiera.", "Las filas corruptas se aíslan sin eliminarse."], "El faro de la trinchera mantiene su señal y el retorno intactos ante cualquier error de datos."], [
      N("Bit Etiqueta", "trchar008", "tecnófarera de datos", "PORYGONZ", "Porygon-Z", "clasificar sin encasillar a nadie", "convirtió una etiqueta provisional en registro permanente",
        ["La cueva clasifica y el registro no se borra nunca", "me apresuré: guardé etiquetas provisionales como si fueran diagnóstico", "pondré fecha de caducidad y botón de cambio"],
        ["las etiquetas caducan y el jugador corrige su fila", "Porygon-Z copia la fila nueva sin arrastrar la corrupta", "la cuarentena conserva los datos originales bajo llave"]),
      N("Zeta Cuarentena", "NPC 04", "conservadora de archivos", "ELECTRODE", "Electrode", "preservar los datos rotos hasta entenderlos", "ordenó purgar la carpeta corrupta con un clic",
        ["La carpeta corrupta se borró dos veces esta temporada", "tardé en reconocer que purgar no es reparar", "aíslo, copio y espero a que alguien entienda"],
        ["la cuarentena guarda copias fechadas de cada fila rota", "Electrode rueda lento para no tirar los cajones", "las purgas exigirán acta y dos lectores"])],
    ["¿Qué hará la cueva con las filas corruptas?", ["Cuarentena con copias fechadas", "Purga inmediata del archivo"]],
    ["la cueva abre la sala de cuarentena y publica su reglamento", "los entrenadores reciben sus etiquetas con botón de cambio"],
    ["METALCOAT", "Recubre un dato frágil sin ocultar del todo sus bordes dañados."]),
  R(1908, "La Luz que Purgaba Archivos Rotos",
    "Un haz de luz de la isla elimina por completo los archivos corruptos y los conservadores reclaman copias antes de reparar.",
    "Que la luz aísle en vez de borrar y que toda reparación empiece por una copia de respaldo.",
    ["Cámara de cuarentena", ["La luz aísla; nunca borra sin revisión.", "Toda reparación parte de una copia.", "Las reparaciones se anuncian con su fecha."], "La senda del bosque y el retorno siguen iluminados aunque el archivo esté en cuarentena."], [
      N("Fax Purga", "trchar009", "farera de archivos", "JOLTEON", "Jolteon", "dirigir la luz sin destruir la historia", "ordenó encender el haz a máxima potencia sobre la carpeta completa",
        ["La carpeta entera se apagó con la luz al máximo", "me precipité: quise limpiar rápido y borré contexto", "bajaré el haz y separaré brillo de destrucción"],
        ["la luz solo aísla y la carpeta vuelve con su contexto", "Jolteon marca el umbral con una descarga corta", "cada reparación se anuncia antes y después"]),
      N("Mora Archivo", "NPC 04", "archivera de respaldos", "GALVANTULA", "Galvantula", "tejer respaldos que nadie tenga que recordar pedir", "confió en la luz y dejó de hacer copias semanales",
        ["Mis respaldos se adelgazaron mientras la luz brillaba", "tardé en reconocer que la confianza no es un plan", "tejeré copias nuevas aunque la luz prometa limpieza"],
        ["la red de respaldos sostiene cada carpeta con dos copias", "Galvantula revisa los hilos cuando cambia el viento", "el calendario de copias cuelga junto al del haz"])],
    ["¿Cómo actuará el haz de luz?", ["Aislar y notificar antes de reparar", "Borrar todo archivo marcado como roto"]],
    ["el bosque fija el protocolo de aislamiento y sus avisos", "los respaldos semanales vuelven a ser obligatorios"],
    ["PRISMSCALE", "Devuelve color a un archivo que la luz había vuelto plano del todo."]),
  R(1915, "La Torre de Datos con Dos Versiones",
    "Una torre guarda dos versiones de la misma ruta y los fallos intercambian sus etiquetas hasta confundir a los viajeros.",
    "Conservar ambas versiones con fecha y registrar cada intercambio de etiqueta.",
    ["Doble versión con fecha", ["Ambas versiones se conservan.", "Las etiquetas se sellan con resumen fijo.", "Todo intercambio queda registrado con hora."], "La torre mantiene su señal de retorno visible desde cualquiera de las dos versiones."], [
      N("Nix Versión", "trchar008", "administradora de la torre", "MORPEKO", "Morpeko", "sostener dos historias sin convertirlas en trampa", "dejó las etiquetas colgadas de un gancho común",
        ["Las etiquetas cuelgan juntas y el viajero elige a ciegas", "me apresuré: ahorré anclajes y mezclé los destinos", "fijaré cada etiqueta a su versión y sellaré el resumen"],
        ["las etiquetas quedan ancladas y el registro anota los cruces", "Morpeko no cambia de gancho sin firmar el registro", "las dos versiones tendrán su propia entrada"]),
      N("Raya Cambio", "NPC 04", "técnico de intercambios", "BOLTUND", "Boltund", "reparar etiquetas sin esconder los errores", "recolocó etiquetas de noche y no anotó nada",
        ["Mi recolocación nocturna explicó el caos de la mañana", "tardé en reconocer que el silencio multiplicaba el daño", "cada cambio llevará hora, firma y motivo"],
        ["el registro delata mis manos y por fin ayuda", "Boltund trae el sello antes de que se mueva nada", "los viajeros leerán el registro junto al mapa"])],
    ["¿Qué hará la torre con sus dos versiones?", ["Dos entradas fechadas y firmadas", "Una versión principal y la otra oculta"]],
    ["la torre abre doble entrada y publica el registro de cambios", "los viajeros reciben el mapa con sus dos lecturas"],
    ["ELECTIRIZER", "Da impulso a la revisión cada vez que las etiquetas vuelven a intercambiarse."]),
  R(1926, "El Acertijo que Fingía Profundidad",
