/**
 * Dimensión creepypasta — contrato visual B:
 *   · arte propio DN en paleta Game Boy verde de cuatro tonos;
 *   · reducción a una microcuadrícula visible de 16×16 px (2×2 dentro del tile RMXP 32×32);
 *   · copias DN de los gráficos de eventos, sin recolorear los recursos compartidos;
 *   · no más de 3 personajes visibles ni 1 Poké Ball por mapa.
 *
 * El juego usa tiles RMXP de 32 px; no se cambia el tamaño global, que rompería mapas
 * normales. Las referencias y originales se conservan en PokeModBackups/dn_gameboy_palette.
 *
 * Uso: node tools/dn_apply_gameboy_palette.mjs [--verify]
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { DATA, GAME, RObject, S, txt, iv, readData, writeData, readMapRaw, writeMapRaw } from "./lib/dlc_helpers.mjs";

const ROOT_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONTRACT_PATH = path.join(ROOT_DIR, "content", "dimensional_nightmare_visual_contract.json");
const ART_MANIFEST = path.join(ROOT_DIR, "content", "dimensional_nightmare_art.json");
const sha1 = (buf) => crypto.createHash("sha1").update(buf).digest("hex").slice(0, 12);
const CONTRACT = JSON.parse(fs.readFileSync(CONTRACT_PATH, "utf8"));
const GRAPHICS = path.join(GAME, "Graphics");
const CHARS = path.join(GRAPHICS, "Characters");
const BACKUP = path.join(GAME, "PokeModBackups", "dn_gameboy_palette");
const VERIFY_ONLY = process.argv.includes("--verify");
const GREEN = ["#0f380f", "#306230", "#8bac0f", "#9bbc0f"].map((hex) => [
  Number.parseInt(hex.slice(1, 3), 16), Number.parseInt(hex.slice(3, 5), 16), Number.parseInt(hex.slice(5, 7), 16),
]);
const MAP_RANGES = CONTRACT.mapRanges;
const GREEN_SHARED_PREFIX = "DN_SHARED_";
const GREEN_TILESET_PREFIX = "DN_GB_";

const fileExists = (p) => fs.existsSync(p);
const safeDecodeHex = (hex) => {
  if (!/^(?:[0-9a-f]{2})+$/i.test(hex)) return null;
  const value = Buffer.from(hex, "hex").toString("utf8");
  return value && !/[\\/]/.test(value) ? value : null;
};
const sharedName = (sourceName) => `${GREEN_SHARED_PREFIX}${Buffer.from(sourceName, "utf8").toString("hex")}`;
const decodeSharedName = (name) => name.startsWith(GREEN_SHARED_PREFIX) ? safeDecodeHex(name.slice(GREEN_SHARED_PREFIX.length)) : null;
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;

function walkPngs(dir) {
  if (!fileExists(dir)) return [];
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...walkPngs(full));
    else if (entry.isFile() && entry.name.toLowerCase().endsWith(".png")) files.push(full);
  }
  return files;
}

function resolveGraphicPath(dir, name) {
  const expected = path.join(dir, `${name}.png`);
  if (fileExists(expected)) return expected;
  const match = fs.readdirSync(dir).find((entry) => entry.toLowerCase() === `${name}.png`.toLowerCase());
  if (match) return path.join(dir, match);
  throw new Error(`falta el recurso gráfico ${path.join(dir, `${name}.png`)}`);
}

function eventEntriesForMap(mapId) {
  const raw = readMapRaw(mapId);
  const hash = iv(raw, "@events");
  return { raw, events: hash?.pairs ?? [] };
}

function baseCharacterName(name) {
  return decodeSharedName(name) ?? name;
}

function isActualItemBall(eventName) {
  return /(?:^|\b)(?:ITEM|POKEBALL|POK[EÉ]?BALL|MEDALLA|RELIQUIA|RECOMPENSA)(?:\b|_)/i.test(eventName);
}

function chooseSharedSource(baseName, eventName, keptBall) {
  if (baseName !== "Object ball" && baseName !== "Object ball special") return { source: baseName, keptBall };
  if (isActualItemBall(eventName) && !keptBall) return { source: baseName, keptBall: true };
  if (/DN_TOWN_MART/i.test(eventName)) return { source: "Object pokedex", keptBall };
  if (/^(?:DN_MAP_MEMORY|DN_STATUE_LORE|VITRINA_)/i.test(eventName)) return { source: "Object rock", keptBall };
  if (/^(?:HUB_|LIGA_|DN_TOWN_)/i.test(eventName)) return { source: "Object pokedex", keptBall };
  return { source: "Object rock", keptBall };
}

function imageSourceFor(relativePath) {
  const basename = path.basename(relativePath, ".png");
  const originalSharedName = decodeSharedName(basename);
  if (originalSharedName) return path.join(CHARS, `${originalSharedName}.png`);
  if (basename === "ash_outfit_creep") return path.join(BACKUP, "Characters", "ash_outfit_creep.png");
  return path.join(BACKUP, relativePath);
}

function makeBackup(original, relativePath) {
  const backupPath = path.join(BACKUP, relativePath);
  if (!fileExists(backupPath)) {
    fs.mkdirSync(path.dirname(backupPath), { recursive: true });
    fs.copyFileSync(original, backupPath);
  }
  return backupPath;
}

function makeDataBackup(relativePath, sourcePath) {
  const backupPath = path.join(BACKUP, "Data", relativePath);
  if (!fileExists(backupPath)) {
    fs.mkdirSync(path.dirname(backupPath), { recursive: true });
    fs.copyFileSync(sourcePath, backupPath);
  }
}

function makeSourceBackup(relativePath, sourcePath) {
  const backupPath = path.join(BACKUP, "tile_sources", relativePath);
  if (!fileExists(backupPath)) {
    fs.mkdirSync(path.dirname(backupPath), { recursive: true });
    fs.copyFileSync(sourcePath, backupPath);
  }
}

function shadeFor(luminance, thresholds) {
  if (luminance <= thresholds[0]) return 0;
  if (luminance <= thresholds[1]) return 1;
  if (luminance <= thresholds[2]) return 2;
  return 3;
}

function quantile(sorted, q) {
  if (!sorted.length) return 0;
  return sorted[Math.min(sorted.length - 1, Math.floor((sorted.length - 1) * q))];
}

/** 2×2 block reduction, then the four-tone classic Game Boy green palette. */
function transformPixels(imageData) {
  const { width, height } = imageData;
  const input = imageData.data;
  const blocks = [];
  const luminances = [];
  const channelLuma = (r, g, b) => 0.299 * r + 0.587 * g + 0.114 * b;
  for (let y = 0; y < height; y += 2) for (let x = 0; x < width; x += 2) {
    let r = 0, g = 0, b = 0, count = 0;
    for (let by = y; by < Math.min(y + 2, height); by += 1) for (let bx = x; bx < Math.min(x + 2, width); bx += 1) {
      const i = (by * width + bx) * 4;
      const a = input[i + 3] / 255;
      if (!a) continue;
      r += input[i] * a; g += input[i + 1] * a; b += input[i + 2] * a; count += a;
    }
    if (!count) { blocks.push({ x, y, opaque: false, luma: 0 }); continue; }
    const luma = channelLuma(r / count, g / count, b / count);
    blocks.push({ x, y, opaque: true, luma });
    luminances.push(luma);
  }
  luminances.sort((a, b) => a - b);
  const thresholds = [quantile(luminances, 0.25), quantile(luminances, 0.5), quantile(luminances, 0.75)];
  const output = new Uint8ClampedArray(input);
  for (const block of blocks) {
    if (!block.opaque) continue;
    const [r, g, b] = GREEN[shadeFor(block.luma, thresholds)];
    for (let y = block.y; y < Math.min(block.y + 2, height); y += 1) for (let x = block.x; x < Math.min(block.x + 2, width); x += 1) {
      const i = (y * width + x) * 4;
      if (input[i + 3] === 0) continue;
      output[i] = r; output[i + 1] = g; output[i + 2] = b;
      // Se conserva cada píxel de alfa, por lo que bordes transparentes siguen limpios.
    }
  }
  return output;
}

async function colorizeFile(sourcePath, outputPath) {
  if (!fileExists(sourcePath)) throw new Error(`falta origen gráfico ${sourcePath}`);
  const image = await loadImage(sourcePath);
  const canvas = createCanvas(image.width, image.height);
  const context = canvas.getContext("2d");
  context.drawImage(image, 0, 0);
  const imageData = context.getImageData(0, 0, image.width, image.height);
  const result = transformPixels(imageData);
  imageData.data.set(result);
  context.putImageData(imageData, 0, 0);
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, canvas.toBuffer("image/png"));
  return { width: image.width, height: image.height };
}

/** Deja constancia en el manifiesto de arte de la huella ya recoloreada. */
function recordArtPaletteHashes() {
  if (!fileExists(ART_MANIFEST)) return 0;
  const manifest = JSON.parse(fs.readFileSync(ART_MANIFEST, "utf8"));
  let recorded = 0;
  for (const item of manifest.assets ?? []) {
    const abs = path.join(GAME, item.out);
    if (!fileExists(abs)) continue;
    const hash = sha1(fs.readFileSync(abs));
    if (item.gbSha1 !== hash) {
      item.gbSha1 = hash;
      recorded += 1;
    }
    item.palette = "gameboy-green";
  }
  manifest.paletteAppliedAt = new Date().toISOString();
  fs.writeFileSync(ART_MANIFEST, `${JSON.stringify(manifest, null, 2)}\n`);
  return recorded;
}

function mapIds() {
  const ids = new Set();
  for (const [lo, hi] of MAP_RANGES) for (let id = lo; id <= hi; id += 1) {
    if (fileExists(path.join(DATA, mapFile(id)))) ids.add(id);
  }
  return [...ids].sort((a, b) => a - b);
}

async function applyGreenTilesets(ids) {
  const tilesetPath = path.join(DATA, "Tilesets.rxdata");
  const tilesets = readData("Tilesets.rxdata");
  const needed = new Map();
  const originalMapTilesets = new Map();
  for (const mapId of ids) {
    const map = readMapRaw(mapId);
    const tilesetId = Number(iv(map, "@tileset_id"));
    const tileset = tilesets[tilesetId];
    if (!tileset) throw new Error(`Map${mapId}: falta el tileset ${tilesetId}`);
    const name = txt(iv(tileset, "@tileset_name"));
    if (name.startsWith("DN_")) continue;
    needed.set(tilesetId, tileset);
    originalMapTilesets.set(mapId, tilesetId);
  }

  let nextId = tilesets.length;
  while (tilesets[nextId]) nextId += 1;
  const replacementIds = new Map();
  let cloned = 0, autotiles = 0;
  for (const [sourceId, source] of needed) {
    const sourceTilesetName = txt(iv(source, "@tileset_name"));
    const outputName = `${GREEN_TILESET_PREFIX}TS${sourceId}`;
    const outputPath = path.join(GRAPHICS, "Tilesets", `${outputName}.png`);
    const sourcePath = resolveGraphicPath(path.join(GRAPHICS, "Tilesets"), sourceTilesetName);
    makeSourceBackup(path.join("Tilesets", `${sourceTilesetName}.png`), sourcePath);
    await colorizeFile(sourcePath, outputPath);

    const sourceAutotiles = iv(source, "@autotile_names") ?? [];
    const outputAutotiles = [];
    for (let index = 0; index < sourceAutotiles.length; index += 1) {
      const sourceAutotileName = txt(sourceAutotiles[index]);
      if (!sourceAutotileName) { outputAutotiles.push(S("")); continue; }
      const outputAutotileName = `${GREEN_TILESET_PREFIX}TS${sourceId}_A${index}`;
      const autoSource = resolveGraphicPath(path.join(GRAPHICS, "Autotiles"), sourceAutotileName);
      const autoOutput = path.join(GRAPHICS, "Autotiles", `${outputAutotileName}.png`);
      makeSourceBackup(path.join("Autotiles", `${sourceAutotileName}.png`), autoSource);
      await colorizeFile(autoSource, autoOutput);
      outputAutotiles.push(S(outputAutotileName));
      autotiles += 1;
    }

    const clone = new RObject(source.className, source.ivars.map(([key, value]) => [key, value]));
    clone.setIvar("@id", nextId);
    clone.setIvar("@name", S(`DN Game Boy ${sourceId}`));
    clone.setIvar("@tileset_name", S(outputName));
    clone.setIvar("@autotile_names", outputAutotiles);
    tilesets[nextId] = clone;
    replacementIds.set(sourceId, nextId);
    nextId += 1;
    cloned += 1;
  }

  if (cloned) {
    makeDataBackup("Tilesets.rxdata", tilesetPath);
    writeData("Tilesets.rxdata", tilesets);
  }
  let reassigned = 0;
  for (const [mapId, oldId] of originalMapTilesets) {
    const map = readMapRaw(mapId);
    const file = path.join(DATA, mapFile(mapId));
    map.setIvar("@tileset_id", replacementIds.get(oldId));
    mapBackup(mapId, file);
    writeMapRaw(mapId, map);
    reassigned += 1;
  }
  return { cloned, autotiles, reassigned };
}

function plannedMapGraphics(ids) {
  const needed = new Map();
  for (const mapId of ids) {
    const { events } = eventEntriesForMap(mapId);
    for (const [, eventObj] of events) {
      const eventName = txt(iv(eventObj, "@name"));
      for (const page of iv(eventObj, "@pages") ?? []) {
        const graphic = iv(page, "@graphic");
        const name = txt(iv(graphic, "@character_name"));
        if (!name) continue;
        const base = baseCharacterName(name);
        if (base.startsWith("DN_")) continue;
        const chosen = chooseSharedSource(base, eventName, false).source;
        needed.set(chosen, path.join(CHARS, `${chosen}.png`));
      }
    }
  }
  return needed;
}

function mapBackup(mapId, mapPathname) {
  const destination = path.join(BACKUP, "maps", mapFile(mapId));
  if (!fileExists(destination)) {
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.copyFileSync(mapPathname, destination);
  }
}

function isVisibleActor(eventName, characterName) {
  const base = baseCharacterName(characterName);
  if (!base || base.startsWith("Object ")) return false;
  // Estas UNOWN son puertas/rutas, no personajes. Los UNOWN llamados NPC_* sí cuentan.
  if (/^HUB_GRIETA_/.test(eventName)) return false;
  if (/^(?:DN_MAP_MEMORY|DN_STATUE_LORE|DN_PHASE_GUARD|DN_OPENING_SCENE|DN_DECISION_|DN_TOWN_CENTER|DN_TOWN_MART|HUB_SALIDA|HUB_PROGRESO|HUB_LIGA_OSCURA|VITRINA_|CONN_|ANOM_|LIGA_(?:ACCESO|SALIDA|CHISPA_))/i.test(eventName)) return false;
  if (base === "NPC 16" && /(?:Nurse|Curaci[oó]n|Healing)/i.test(eventName)) return true;
  return true;
}

function namesAndBallCount(mapId) {
  const { events } = eventEntriesForMap(mapId);
  let actors = 0, balls = 0;
  const violations = [];
  for (const [, eventObj] of events) {
    const eventName = txt(iv(eventObj, "@name"));
    let eventActor = false, eventBall = false;
    for (const page of iv(eventObj, "@pages") ?? []) {
      const name = txt(iv(iv(page, "@graphic"), "@character_name"));
      if (!name) continue;
      const base = baseCharacterName(name);
      if (base === "Object ball" || base === "Object ball special") eventBall = true;
      if (isVisibleActor(eventName, name)) eventActor = true;
      if (!name.startsWith("DN_")) violations.push(`${eventName}: sprite sin copia DN (${name})`);
      else if (!fileExists(path.join(CHARS, `${name}.png`))) violations.push(`${eventName}: falta Graphics/Characters/${name}.png`);
    }
    if (eventActor) actors += 1;
    if (eventBall) balls += 1;
  }
  return { actors, balls, violations };
}

async function verifyArtwork() {
  const files = walkPngs(GRAPHICS).filter((file) => path.basename(file).startsWith("DN_")
    || file === path.join(CHARS, "ash_outfit_creep.png"));
  const errors = [];
  for (const file of files) {
    const image = await loadImage(file);
    const canvas = createCanvas(image.width, image.height);
    const context = canvas.getContext("2d");
    context.drawImage(image, 0, 0);
    const data = context.getImageData(0, 0, image.width, image.height).data;
    let visible = 0;
    for (let i = 0; i < data.length; i += 4) {
      // Canvas aplica redondeo de sRGB en semitransparencias al decodificar PNG.
      // Los píxeles opacos deben coincidir con uno de los cuatro tonos (±2 por canal).
      if (data[i + 3] < 250) continue;
      visible += 1;
      const matched = GREEN.some(([r, g, b]) => Math.abs(data[i] - r) <= 2 && Math.abs(data[i + 1] - g) <= 2 && Math.abs(data[i + 2] - b) <= 2);
      if (!matched) {
        errors.push(`${path.relative(GRAPHICS, file)}: color fuera de la paleta verde`);
        break;
      }
    }
    if (!visible) errors.push(`${path.relative(GRAPHICS, file)}: imagen vacía`);
  }
  return { files: files.length, errors };
}

function verifyTilesetCoverage(ids) {
  const tilesets = readData("Tilesets.rxdata");
  const errors = [];
  for (const mapId of ids) {
    const map = readMapRaw(mapId);
    const tilesetId = Number(iv(map, "@tileset_id"));
    const tileset = tilesets[tilesetId];
    if (!tileset) { errors.push(`Map${mapId}: falta el tileset ${tilesetId}`); continue; }
    const name = txt(iv(tileset, "@tileset_name"));
    if (!name.startsWith("DN_")) errors.push(`Map${mapId}: tileset fuera de la paleta Game Boy (${name})`);
    if (!fileExists(path.join(GRAPHICS, "Tilesets", `${name}.png`))) errors.push(`Map${mapId}: falta Graphics/Tilesets/${name}.png`);
    for (const autoName of (iv(tileset, "@autotile_names") ?? []).map(txt).filter(Boolean)) {
      if (!autoName.startsWith("DN_")) errors.push(`Map${mapId}: autotile fuera de la paleta Game Boy (${autoName})`);
      if (!fileExists(path.join(GRAPHICS, "Autotiles", `${autoName}.png`))) errors.push(`Map${mapId}: falta Graphics/Autotiles/${autoName}.png`);
    }
  }
  return errors;
}

async function verify() {
  const errors = [];
  const artwork = await verifyArtwork();
  errors.push(...artwork.errors);
  const ids = mapIds();
  errors.push(...verifyTilesetCoverage(ids));
  for (const id of ids) {
    const { actors, balls, violations } = namesAndBallCount(id);
    errors.push(...violations.map((message) => `Map${id}: ${message}`));
    if (actors > CONTRACT.maxVisibleCharactersPerMap) errors.push(`Map${id}: ${actors} personajes visibles (máximo ${CONTRACT.maxVisibleCharactersPerMap})`);
    if (balls > CONTRACT.maxVisiblePokeballsPerMap) errors.push(`Map${id}: ${balls} Poké Balls visibles (máximo ${CONTRACT.maxVisiblePokeballsPerMap})`);
  }
  if (errors.length) {
    console.error(`✘ Contrato Game Boy: ${errors.length} problema(s)`);
    for (const error of errors.slice(0, 24)) console.error(`  · ${error}`);
    process.exit(1);
  }
  console.log(`✔ Contrato Game Boy: ${artwork.files} imágenes en paleta verde, ${ids.length} mapas, ≤${CONTRACT.maxVisibleCharactersPerMap} personajes y ≤${CONTRACT.maxVisiblePokeballsPerMap} Poké Ball por mapa.`);
}

async function apply() {
  const ids = mapIds();
  const tilesetStats = await applyGreenTilesets(ids);
  const requested = plannedMapGraphics(ids);
  const sharedFiles = new Map();
  for (const [sourceName, sourcePath] of requested) {
    if (!fileExists(sourcePath)) throw new Error(`no existe el charset base ${sourceName}.png`);
    const outputName = sharedName(sourceName);
    const outputPath = path.join(CHARS, `${outputName}.png`);
    sharedFiles.set(sourceName, { outputName, outputPath, sourcePath });
  }

  let recolored = 0;
  for (const { outputName, outputPath, sourcePath } of sharedFiles.values()) {
    await colorizeFile(sourcePath, outputPath);
    recolored += 1;
  }

  // Cada mapa conserva el mismo tileset, autotiles, pasabilidad y celdas RMXP;
  // las copias DN cambian sólo la paleta, sin tocar la geometría del terreno.
  let patchedMaps = 0, patchedPages = 0;
  for (const mapId of ids) {
    const file = path.join(DATA, mapFile(mapId));
    const { raw, events } = eventEntriesForMap(mapId);
    const keptBallByMap = { value: false };
    let changed = false;
    for (const [, eventObj] of events) {
      const eventName = txt(iv(eventObj, "@name"));
      const pages = iv(eventObj, "@pages") ?? [];
      const eventKeepsBall = !keptBallByMap.value && isActualItemBall(eventName) && pages.some((page) => {
        const name = txt(iv(iv(page, "@graphic"), "@character_name"));
        const base = baseCharacterName(name);
        return base === "Object ball" || base === "Object ball special";
      });
      if (eventKeepsBall) keptBallByMap.value = true;
      for (const page of pages) {
        const graphic = iv(page, "@graphic");
        const currentName = txt(iv(graphic, "@character_name"));
        if (!currentName) continue;
        const decoded = baseCharacterName(currentName);
        const isBall = decoded === "Object ball" || decoded === "Object ball special";
        const source = eventKeepsBall && isBall ? decoded : chooseSharedSource(decoded, eventName, keptBallByMap.value).source;
        const nextName = source.startsWith("DN_") ? source : sharedName(source);
        if (currentName !== nextName) {
          graphic.setIvar("@character_name", S(nextName));
          changed = true;
          patchedPages += 1;
        }
      }
    }
    if (changed) {
      mapBackup(mapId, file);
      writeMapRaw(mapId, raw);
      patchedMaps += 1;
    }
  }

  // Conserva originales de DN y del traje creep; la salida siempre se regenera
  // desde la copia sin cuantizar para que la operación sea idempotente.
  const artwork = walkPngs(GRAPHICS).filter((file) => {
    const name = path.basename(file);
    return (name.startsWith("DN_") && !name.startsWith(GREEN_TILESET_PREFIX))
      || file === path.join(CHARS, "ash_outfit_creep.png");
  });
  for (const outputPath of artwork) {
    const relativePath = path.relative(GRAPHICS, outputPath);
    const sourcePath = imageSourceFor(relativePath);
    let stableSource = sourcePath;
    if (!path.basename(relativePath).startsWith(GREEN_SHARED_PREFIX)) {
      stableSource = makeBackup(outputPath, relativePath);
    }
    await colorizeFile(stableSource, outputPath);
  }
  const allGameboyImages = walkPngs(GRAPHICS).filter((file) => path.basename(file).startsWith("DN_")
    || file === path.join(CHARS, "ash_outfit_creep.png"));
  recordArtPaletteHashes();
  console.log(`✔ Paleta Game Boy aplicada: ${allGameboyImages.length} imágenes; ${recolored} charsets, ${tilesetStats.cloned} tilesets y ${tilesetStats.autotiles} autotiles copiados; ${tilesetStats.reassigned} mapas usan tilesets verdes, ${patchedMaps} mapas/${patchedPages} páginas de eventos ajustados.`);
  await verify();
}

if (VERIFY_ONLY) await verify();
else {
  try { await apply(); }
  catch (error) { console.error(`[dn-gameboy] ERROR: ${error.message}`); process.exit(1); }
}#!/usr/bin/env node
/**
 * dn_apply_medals.mjs — medallas y cartucheras de los mundos creepypasta (M2).
 *
 * Cada mundo entrega una **Medalla** y su **cartuchera**, y la cartuchera se llama exactamente
 * `Badges of <mundo>` (requisito de diseño). La medalla se recoge en el **Pedestal del Sello** de la
 * cámara del jefe: el pedestal se enciende cuando el sello del mundo queda cerrado, entrega medalla
 * + cartuchera una sola vez (self-switch A) y deja el registro a la vista.
 *
 *   EP01 White Hand          DN_MEDAL_WHT + DN_CASE_WHT · Badges of White Hand          (2056)
 *   EP02 Lost Silver         DN_MEDAL_LSV + DN_CASE_LSV · Badges of Lost Silver         (2072)
 *   EP03 Snow on Mt. Silver  DN_MEDAL_SNO + DN_CASE_SNO · Badges of Snow on Mt. Silver  (2087)
 *   EP04 Hypno's Lullaby     DN_MEDAL_HYP + DN_CASE_HYP · Badges of Hypno's Lullaby     (2103)
 *   EP05 Pokémon Black       DN_MEDAL_BLK + DN_CASE_BLK · Badges of Pokémon Black       (2119)
 *   EP06 King Unown          DN_MEDAL_UNO + DN_CASE_UNO · Badges of King Unown          (2135)
 *
 *   W7  Strangled Red         DN_MEDAL_AMO + DN_CASE_AMO · Badges of Strangled Red     (2158)
 *   W8  Buried Alive          DN_MEDAL_FOS + DN_CASE_FOS · Badges of Buried Alive      (2174)
 *   W9  Lavender Town Syndr.  DN_MEDAL_SIL + DN_CASE_SIL · Badges of Lavender Town     (2190)
 *
 * Los dos últimos (Medalla del Vínculo · Badges of Mad Pikachu) los entrega la Liga Oscura
 * (`tools/dn_build_liga.mjs`), que reutiliza estas mismas definiciones. Al cerrar los **nueve**
 * mundos, la Antesala entrega además la cartuchera del testigo `DN_CASE_WIT`
 * («Badges of the Witness») desde el evento `VITRINA_TESTIGO` (mapa 2040).
 *
 * Uso:
 *   node tools/dn_apply_medals.mjs            # objetos, iconos y pedestales
 *   node tools/dn_apply_medals.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { createCanvas } from "@napi-rs/canvas";
import {
  GRAPHICS, txt, grid, nearestFreeCell, reachableFrom, upsertEvents, writeItems, cmd,
  readData, readJson, CATALOG, EVENTS, condition, graphic, page, event, texts, script,
  selfSwitch,
} from "./lib/dn_rmxp.mjs";

const argv = process.argv.slice(2);
const VERIFY = argv.includes("--verify");
const DRY = argv.includes("--dry-run");
const ITEM_BASE = 1040;
const ITEM_ICONS = path.join(GRAPHICS, "Items");

/** Mundos, medallas, cartucheras y colores de su icono. */
export const WORLDS = [
  { key: "EP01", world: "White Hand", medal: "DN_MEDAL_WHT", case: "DN_CASE_WHT", medalName: "Medalla de la Mano Blanca", caseName: "Badges of White Hand", body: "#e8e0d0", ring: "#8a6a3c", glyph: "✋" },
  { key: "EP02", world: "Lost Silver", medal: "DN_MEDAL_LSV", case: "DN_CASE_LSV", medalName: "Medalla del Sin Nombre", caseName: "Badges of Lost Silver", body: "#c8ccd4", ring: "#3d5a8a", glyph: "☠" },
  { key: "EP03", world: "Snow on Mt. Silver", medal: "DN_MEDAL_SNO", case: "DN_CASE_SNO", medalName: "Medalla del Caminante", caseName: "Badges of Snow on Mt. Silver", body: "#eaf4ff", ring: "#4a86c8", glyph: "❄" },
  { key: "EP04", world: "Hypno's Lullaby", medal: "DN_MEDAL_HYP", case: "DN_CASE_HYP", medalName: "Medalla de la Nana", caseName: "Badges of Hypno's Lullaby", body: "#b06ad8", ring: "#5a2a7a", glyph: "♪" },
  { key: "EP05", world: "Pokémon Black", medal: "DN_MEDAL_BLK", case: "DN_CASE_BLK", medalName: "Medalla del Jugador 000", caseName: "Badges of Pokémon Black", body: "#1c1c22", ring: "#8e1b1b", glyph: "0" },
  { key: "EP06", world: "King Unown", medal: "DN_MEDAL_UNO", case: "DN_CASE_UNO", medalName: "Medalla del Rey Unown", caseName: "Badges of King Unown", body: "#39ff88", ring: "#101418", glyph: "ᛝ" },
  { key: "W7", world: "Strangled Red", medal: "DN_MEDAL_AMO", case: "DN_CASE_AMO", medalName: "Medalla del Amo", caseName: "Badges of Strangled Red", body: "#b03a3a", ring: "#3a0d0d", glyph: "⛓" },
  { key: "W8", world: "Buried Alive", medal: "DN_MEDAL_FOS", case: "DN_CASE_FOS", medalName: "Medalla de la Fosa", caseName: "Badges of Buried Alive", body: "#6b5236", ring: "#241708", glyph: "▽" },
  { key: "W9", world: "Lavender Town Syndrome", medal: "DN_MEDAL_SIL", case: "DN_CASE_SIL", medalName: "Medalla del Silencio", caseName: "Badges of Lavender Town Syndrome", body: "#b98ad8", ring: "#33134f", glyph: "◌" },
];

/**
 * Cartuchera del testigo: se entrega en la Antesala cuando los **nueve** sellos están cerrados.
 * No tiene medalla propia: es el registro de haber visto cerrarse los nueve mundos.
 */
export const WITNESS = {
  id: "DN_CASE_WIT", name: "Badges of the Witness",
  description: "Cartuchera del Testigo: se entrega cuando los nueve sellos del Dimensional Nightmare están cerrados.",
  hubMap: 2040,
};

/** Todos los sellos del Dimensional Nightmare (seis del primer anillo + tres del segundo). */
export const SEALS = [883, 884, 885, 886, 887, 888, 922, 923, 924];

const PHASE_A_SWITCHES = Object.freeze({
  EP01: 903, EP02: 904, EP03: 905, EP04: 906, EP05: 907, EP06: 908,
  W7: 928, W8: 929, W9: 930,
});
const PHASE_B_VARIABLE_BASE = 289;
function bossProgress(catalog, key) {
  const bosses = catalog.episodes.filter((episode) => episode.boss);
  const index = bosses.findIndex((episode) => episode.key === key);
  const episode = bosses[index];
  if (!episode || !PHASE_A_SWITCHES[key]) throw new Error(`${key}: faltan datos de progresión del jefe`);
  const spec = episode.boss.phaseB;
  const total = spec.maps?.length || spec.cells?.length || (spec.kind === "letras" ? 7 : 4);
  return { phaseA: PHASE_A_SWITCHES[key], variable: PHASE_B_VARIABLE_BASE + index, total };
}

/** Condición de la Vitrina del Testigo: los nueve sellos cerrados. */
export const WITNESS_CHECK = `begin; $game_switches[931] = [${SEALS.map((id) => `$game_switches[${id}]`).join(", ")}].all?; rescue; end`;

/** Con las seis cartucheras se abre la Liga Oscura (switch 917); lo comprueba también el Archivero. */
export const READY_CHECK = `begin; $game_switches[917] = [${WORLDS.map((w) => `:${w.case}`).join(", ")}].all? { |i| $PokemonBag.pbHasItem?(i) }; rescue; end`;

/** Séptima cartuchera: la entrega la Liga Oscura. */
export const FINAL_WORLD = {
  key: "LIGA", world: "Mad Pikachu", medal: "DN_MEDAL_MPK", case: "DN_CASE_MPK",
  medalName: "Medalla del Vínculo", caseName: "Badges of Mad Pikachu",
  body: "#ffe14d", ring: "#b8860b", glyph: "⚡",
};

export const ALL_ITEMS = [
  ...WORLDS.flatMap((w) => [
    { id: w.medal, name: w.medalName, description: `${w.medalName}: cierra el sello de ${w.world} y se guarda en su cartuchera.`, kind: "medal", color: w },
    { id: w.case, name: w.caseName, description: `Cartuchera de ${w.world}. Guarda la ${w.medalName} y su registro.`, kind: "case", color: w },
  ]),
  { id: FINAL_WORLD.medal, name: FINAL_WORLD.medalName, description: `${FINAL_WORLD.medalName}: el vínculo que devolvió a Mad Pikachu.`, kind: "medal", color: FINAL_WORLD },
  { id: FINAL_WORLD.case, name: FINAL_WORLD.caseName, description: `Cartuchera de la Liga Oscura. Guarda la ${FINAL_WORLD.medalName}.`, kind: "case", color: FINAL_WORLD },
  { id: WITNESS.id, name: WITNESS.name, description: WITNESS.description, kind: "case", color: { body: "#e8e2c8", ring: "#5a4a24", glyph: "◈" } },
];

// --------------------------------------------------------------- iconos
function drawMedal(color) {
  const canvas = createCanvas(48, 48);
  const ctx = canvas.getContext("2d");
  // cintas
  ctx.fillStyle = color.ring;
  ctx.beginPath(); ctx.moveTo(18, 2); ctx.lineTo(30, 2); ctx.lineTo(27, 20); ctx.lineTo(21, 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(12, 4); ctx.lineTo(20, 4); ctx.lineTo(24, 19); ctx.lineTo(17, 17); ctx.fill();
  ctx.beginPath(); ctx.moveTo(36, 4); ctx.lineTo(28, 4); ctx.lineTo(24, 19); ctx.lineTo(31, 17); ctx.fill();
  // disco
  ctx.fillStyle = color.ring;
  ctx.beginPath(); ctx.arc(24, 30, 15, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = color.body;
  ctx.beginPath(); ctx.arc(24, 30, 11.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#101418";
  ctx.font = "bold 15px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(color.glyph, 24, 31);
  return canvas;
}

function drawCase(color) {
  const canvas = createCanvas(48, 48);
  const ctx = canvas.getContext("2d");
  // caja
  ctx.fillStyle = "#2a2f36";
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(4, 12, 40, 28, 5); else ctx.rect(4, 12, 40, 28);
  ctx.fill();
  ctx.strokeStyle = color.ring;
  ctx.lineWidth = 2;
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(5, 13, 38, 26, 4); else ctx.rect(5, 13, 38, 26);
  ctx.stroke();
  // ranura con la medalla
  ctx.fillStyle = "#101418";
  ctx.beginPath(); ctx.arc(18, 26, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = color.body;
  ctx.beginPath(); ctx.arc(18, 26, 5.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#101418";
  ctx.font = "bold 8px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(color.glyph, 18, 27);
  // dos ranuras vacías
  ctx.strokeStyle = "#4a525c";
  ctx.lineWidth = 1.5;
  for (const cx of [32, 40]) { ctx.beginPath(); ctx.arc(cx, 26, 4, 0, Math.PI * 2); ctx.stroke(); }
  // broche
  ctx.fillStyle = color.ring;
  ctx.fillRect(20, 8, 8, 6);
  return canvas;
}

function installIcons() {
  fs.mkdirSync(ITEM_ICONS, { recursive: true });
  let drawn = 0;
  for (const item of ALL_ITEMS) {
    const file = path.join(ITEM_ICONS, `${item.id}.png`);
    if (DRY) { drawn++; continue; }
    fs.writeFileSync(file, (item.kind === "medal" ? drawMedal(item.color) : drawCase(item.color)).toBuffer("image/png"));
    drawn++;
  }
  return drawn;
}

// --------------------------------------------------------------- pedestales
/** Mapa del jefe de cada episodio, según el catálogo de eventos construido. */
function bossMaps() {
  const built = readJson(EVENTS).maps ?? {};
  const out = new Map();
  for (const [id, info] of Object.entries(built)) if (info.boss) out.set(info.episode, Number(id));
  return out;
}

function applyPedestals() {
  const catalog = readJson(CATALOG);
  const bosses = bossMaps();
  const summary = [];
  for (const world of WORLDS) {
    const episode = catalog.episodes.find((e) => e.key === world.key);
    const mapId = bosses.get(world.key);
    if (!episode || !mapId) { summary.push({ key: world.key, mapId: null, cell: null, error: "sin mapa de jefe" }); continue; }
    const seal = episode.seal;
    const progress = bossProgress(catalog, world.key);
    const g = grid(mapId);
    const sealEvent = g.events.find((e) => /Sello/.test(e.name)) ?? g.events.find((e) => /JEFE/.test(e.name));
    const from = sealEvent ? [sealEvent.x, sealEvent.y] : [Math.floor(g.width / 2), Math.floor(g.height / 2)];
    const entry = readJson(EVENTS).maps?.[String(mapId)]?.entry ?? [Math.floor(g.width / 2), g.height - 2];
    const reach = reachableFrom(g, entry);
    const cell = nearestFreeCell(g, from, { maxDistance: 8, allowed: reach });
    if (!cell) { summary.push({ key: world.key, mapId, cell: null, error: "sin celda libre" }); continue; }
    const name = `MEDALLA_${world.key}`;
    const built = upsertEvents(mapId, [name], (baseId) => [
      event(baseId, name, cell[0], cell[1], [
        // Página base primero; en RMXP siempre gana la página activa de número más alto.
        page({
          gfx: graphic("Object ball special", 2, 1, { hue: 0 }),
          list: [...texts([`Pedestal de ${world.world}.`, `Se encenderá cuando el sello cierre. La medalla se guarda en «${world.caseName}».`]), cmd(0)],
        }),
        page({
          cond: condition({ sw: seal, sw2: progress.phaseA, variable: [progress.variable, progress.total] }),
          gfx: graphic("Object ball special", 2, 1, { hue: 32 }),
          list: [
            ...texts([
              `El sello de ${world.world} está cerrado.`,
              `El pedestal entrega la ${world.medalName} y su cartuchera.`,
            ]),
            script(`begin; pbReceiveItem(:${world.medal}); pbReceiveItem(:${world.case}); rescue; pbMessage("(medalla ${world.medal} pendiente de registrar)"); end`),
            script(READY_CHECK),
            selfSwitch("A"),
            cmd(0),
          ],
        }),
        page({
          cond: condition({ self: "A" }),
          gfx: graphic("Object ball special", 2, 1, { hue: 0 }),
          list: [...texts([`El pedestal guarda la ${world.medalName}.`, `Cartuchera registrada: «${world.caseName}».`]), cmd(0)],
        }),
      ]),
    ], { dry: DRY });
    summary.push({ key: world.key, mapId, cell, seal, event: name, added: built.added.length });
  }
  applyWitness(summary);
  return summary;
}

/** Vitrina del Testigo: un evento en la Antesala (2040) que entrega `DN_CASE_WIT` una sola vez. */
function applyWitness(summary) {
  const mapId = WITNESS.hubMap;
  const g = grid(mapId);
  const entry = readJson(EVENTS).maps?.[String(mapId)]?.entry ?? [Math.floor(g.width / 2), g.height - 2];
  const reach = reachableFrom(g, entry);
  const cell = nearestFreeCell(g, entry, { maxDistance: 12, allowed: reach }) ?? [Math.floor(g.width / 2), Math.floor(g.height / 2)];
  const name = "VITRINA_TESTIGO";
  const built = upsertEvents(mapId, [name], (baseId) => [
    event(baseId, name, cell[0], cell[1], [
      page({
        gfx: graphic("Object ball special", 2, 1, { hue: 0 }),
        list: [...texts(["Vitrina del Testigo: nueve sellos por cerrar.", "Vuelve cuando los nueve mundos estén en silencio."]), cmd(0)],
      }),
      page({
        cond: condition({ sw: 931 }),
        gfx: graphic("Object ball special", 2, 1, { hue: 0 }),
        list: [
          ...texts([
            "La Vitrina del Testigo tiene nueve huecos.",
            "Nueve sellos cerrados: la vitrina se abre sola y entrega una cartuchera vacía.",
            "«Badges of the Witness»: el registro de quien vio cerrarse los nueve mundos.",
          ]),
          script(`begin; pbReceiveItem(:${WITNESS.id}); rescue; pbMessage("(cartuchera del testigo pendiente de registrar)"); end`),
          selfSwitch("A"),
          cmd(0),
        ],
      }),
      page({
        cond: condition({ self: "A" }),
        gfx: graphic("Object ball special", 2, 1, { hue: 32 }),
        list: [...texts(["La Vitrina del Testigo guarda tu cartuchera.", "Nueve mundos, nueve medallas, un solo testigo."]), cmd(0)],
      }),
    ]),
  ], { dry: DRY });
  summary.push({ key: "WIT", mapId, cell, seal: 931, event: name, added: built.added.length });
}

// --------------------------------------------------------------- verificación
function verify() {
  const failures = [];
  const ok = (cond, msg) => { if (!cond) failures.push(msg); };
  const items = readData("items.dat");
  const bySymbol = new Map(items.pairs.filter(([k]) => k && k.name !== undefined).map(([k, v]) => [k.name, v]));
  for (const item of ALL_ITEMS) {
    const entry = bySymbol.get(item.id);
    ok(!!entry, `falta el objeto ${item.id}`);
    if (!entry) continue;
    ok(txt(entry.getIvar("@real_name")) === item.name, `${item.id}: nombre «${txt(entry.getIvar("@real_name"))}» ≠ «${item.name}»`);
    ok(entry.getIvar("@pocket") === 8, `${item.id}: no es objeto clave`);
    ok(fs.existsSync(path.join(ITEM_ICONS, `${item.id}.png`)), `${item.id}: falta el icono 48×48`);
  }
  for (const world of WORLDS) {
    ok(readData("items.dat").pairs.some(([k, v]) => k && k.name !== undefined && k.name === world.case &&
      txt(v.getIvar("@real_name")) === `Badges of ${world.world}`), `${world.case}: la cartuchera no se llama «Badges of ${world.world}»`);
  }
  // pedestales
  const catalog = readJson(CATALOG);
  const bosses = bossMaps();
  for (const world of WORLDS) {
    const mapId = bosses.get(world.key);
    ok(!!mapId, `${world.key}: sin mapa de jefe en el catálogo`);
    if (!mapId) continue;
    const g = grid(mapId);
    const ev = g.events.find((e) => e.name === `MEDALLA_${world.key}`);
    ok(!!ev, `Map${mapId}: falta el pedestal MEDALLA_${world.key}`);
    if (!ev) continue;
    ok(ev.pages.length === 3, `${world.key}: el pedestal necesita 3 páginas (bloqueada / entrega / registrada)`);
    const claim = ev.pages[1];
    const progress = bossProgress(catalog, world.key);
    const claimCondition = claim?.getIvar("@condition");
    const sealOk = claimCondition?.getIvar("@switch1_id") === catalog.episodes.find((e) => e.key === world.key).seal &&
      claimCondition?.getIvar("@switch1_valid") === true
      && claimCondition?.getIvar("@switch2_id") === progress.phaseA && claimCondition?.getIvar("@switch2_valid") === true
      && claimCondition?.getIvar("@variable_id") === progress.variable && claimCondition?.getIvar("@variable_value") === progress.total
      && claimCondition?.getIvar("@variable_valid") === true;
    ok(sealOk, `${world.key}: la página que entrega la medalla no exige sello, victoria y fase B completa`);
    const claimText = (claim?.getIvar("@list") ?? []).map((c) => (c.getIvar("@parameters") ?? []).map((p) => txt(p)).join(" ")).join(" ");
    ok(claimText.includes(`:${world.medal}`) && claimText.includes(`:${world.case}`), `${world.key}: el pedestal no entrega medalla y cartuchera`);
    ok(!(ev.pages[0]?.getIvar("@condition")?.getIvar("@switch1_valid") ?? false)
      && !(ev.pages[0]?.getIvar("@condition")?.getIvar("@self_switch_valid") ?? false), `${world.key}: la página bloqueada no es la página base`);
    ok((ev.pages[2]?.getIvar("@condition")?.getIvar("@self_switch_valid") ?? false) === true, `${world.key}: falta la página «ya registrada» (self-switch A)`);
  }
  // Vitrina del Testigo (2040)
  {
    const g = grid(WITNESS.hubMap);
    const ev = g.events.find((e) => e.name === "VITRINA_TESTIGO");
    ok(!!ev, `Map${WITNESS.hubMap}: falta la VITRINA_TESTIGO`);
    if (ev) {
      const locked = ev.pages[0]?.getIvar("@condition");
      const claim = ev.pages[1];
      const cond = claim?.getIvar("@condition");
      ok(!(locked?.getIvar("@switch1_valid") ?? false) && !(locked?.getIvar("@self_switch_valid") ?? false),
        "VITRINA_TESTIGO: la página bloqueada debe ser la página base");
      ok(cond?.getIvar("@switch1_id") === 931 && cond?.getIvar("@switch1_valid") === true,
        "VITRINA_TESTIGO: la página de entrega debe exigir el switch 931 (nueve sellos)");
      const claimText = (claim?.getIvar("@list") ?? []).map((c) => (c.getIvar("@parameters") ?? []).map((p) => txt(p)).join(" ")).join(" ");
      ok(claimText.includes(`:${WITNESS.id}`), "VITRINA_TESTIGO: no entrega DN_CASE_WIT");
      ok(ev.pages[2]?.getIvar("@condition")?.getIvar("@self_switch_valid") === true,
        "VITRINA_TESTIGO: la página registrada debe cerrar con self-switch A");
    }
    const entry = readData("items.dat");
    const wit = entry.pairs.find(([k, v]) => k && k.name !== undefined && k.name === WITNESS.id);
    ok(!!wit, `falta el objeto ${WITNESS.id}`);
    if (wit) ok(txt(wit[1].getIvar("@real_name")) === WITNESS.name, `${WITNESS.id}: nombre ≠ «${WITNESS.name}»`);
  }
  console.log(`verificación de medallas y cartucheras (${ALL_ITEMS.length} objetos, ${WORLDS.length} pedestales, 1 vitrina)`);
  if (failures.length) { for (const f of failures) console.error(`  FALLA: ${f}`); process.exit(1); }
  console.log("verificación de medallas OK");
}

// --------------------------------------------------------------- main
if (VERIFY) {
  verify();
} else {
  const written = writeItems(ALL_ITEMS, { base: ITEM_BASE, dry: DRY });
  const icons = installIcons();
  const pedestals = applyPedestals();
  console.log(`objetos: ${written.filter((w) => !w.existed).length} nuevos · iconos: ${icons}`);
  for (const p of pedestals) {
    console.log(p.error ? `  ${p.key}: ${p.error}` : `  ${p.key}: pedestal en Map${p.mapId} @ ${p.cell.join(",")} (sello ${p.seal})`);
  }
}#!/usr/bin/env node
/**
 * dn_apply_sensations.mjs — la «sensación» de cada mundo creepypasta (M2).
 *
 * Cada mundo debe sentirse distinto al entrar. Esta herramienta recorre **todas** las
 * transferencias de los mapas del ciclo y les inserta, justo antes, un cambio de tono de pantalla
 * con la paleta del mundo de destino:
 *
 *   EP01 White Hand          sepia sucio        (-30,-20,-20, 40)   papel y tinta
 *   EP02 Lost Silver         azul de cartucho   (-60,-20,+20, 30)   frío estático
 *   EP03 Snow on Mt. Silver  blanco cegador     (+30,+30,+40,  0)   silencio de nieve
 *   EP04 Hypno's Lullaby     violeta            (+40,-20,+60, 20)   sueño hipnótico
 *   EP05 Pokémon Black       negro total       (-100,-100,-100, 0)  ausencia
 *   EP06 King Unown          verde glitch       (+20,-40,+20, 80)   ruptura
 *   NEXO / HUB / LIGA        azules de código   (0,-20,+40,20) etc. archivo y tormenta
 *   resto (juego base)       neutro             (0,0,0,0)           al salir se limpia el tono
 *
 * Las líneas llevan la marca `dn:sensacion`, así que se refrescan sin duplicarse: primero se
 * borran las marcas anteriores de esa transferencia y después se escribe la correcta.
 *
 * Uso:
 *   node tools/dn_apply_sensations.mjs            # aplica/refresca
 *   node tools/dn_apply_sensations.mjs --verify
 *   node tools/dn_apply_sensations.mjs --dry-run
 */
import {
  BUILT, mapFile, readMap, writeMap, backup, script, txt, toneLine, isToneLine, readJson,
} from "./lib/dn_rmxp.mjs";

const argv = process.argv.slice(2);
const VERIFY = argv.includes("--verify");
const DRY = argv.includes("--dry-run");

const DURATION = 24;
const MARKER = "dn:sensacion";
const PHASE_MARKER = "dn:fase";
const TONES = {
  EP01: [-30, -20, -20, 40],
  EP02: [-60, -20, 20, 30],
  EP03: [30, 30, 40, 0],
  EP04: [40, -20, 60, 20],
  EP05: [-100, -100, -100, 0],
  EP06: [20, -40, 20, 80],
  W7: [-40, -20, -20, 20],   // rojo apagado: duelo y culpa
  W8: [-60, -50, -40, 10],   // tierra y penumbra: claustrofobia
  W9: [20, -20, 60, 30],     // violeta y ondas: el sonido duele
  NEXO: [0, -20, 40, 20],
  HUB: [0, -10, 30, 10],
  LIGA: [-40, -40, -40, 0],
  DEFAULT: [0, 0, 0, 0],
};

function episodeIndex() {
  const index = new Map(readJson(BUILT).maps.map((m) => [m.id, m.episode]));
  index.set(2030, "DEFAULT");           // Gruta de los Testigos (juego base): al salir, tono neutro
  return index;
}

function mapIds() {
  return [...new Set([2030, ...readJson(BUILT).maps.map((map) => map.id)])].sort((a, b) => a - b);
}

const PHASE_OFFSETS = {
  1: [0, 0, 0, 0],
  2: [-8, -8, -8, 0],
  3: [-24, -24, -24, 0],
  4: [-48, -32, -32, 0],
  5: [-64, -48, -48, 0],
  6: [-96, -64, -64, 40],
  7: [-128, -96, -96, 80],
};
const PHASE_RANGES = [
  [2041, 2056], [2057, 2072], [2073, 2087], [2088, 2103], [2104, 2119], [2120, 2135],
  [2136, 2140], [2143, 2158], [2159, 2174], [2175, 2190],
];

function phaseOf(mapId, index) {
  const key = index.get(Number(mapId));
  if (!key || key === "HUB" || key === "DEFAULT") return 0;
  if (key === "LIGA") return Number(mapId) === 2141 ? 5 : 7;
  const range = PHASE_RANGES.find(([from, to]) => Number(mapId) >= from && Number(mapId) <= to);
  if (!range) return 0;
  const [from, to] = range;
  const span = Math.max(1, to - from);
  return Math.max(1, Math.min(7, Math.round(((Number(mapId) - from) / span) * 6) + 1));
}

function toneOf(mapId, index) {
  const base = TONES[index.get(Number(mapId))] ?? TONES.DEFAULT;
  const phase = phaseOf(mapId, index);
  const offset = PHASE_OFFSETS[phase] ?? [0, 0, 0, 0];
  return base.map((value, channel) => Math.max(channel === 3 ? 0 : -255, Math.min(255, value + offset[channel])));
}
const toneText = (tone) => `Tone.new(${tone.join(", ")})`;
const phaseLine = (phase) => `begin; $game_variables[266] = ${phase}; rescue; end # ${PHASE_MARKER}`;

/** Transferencias (comando 201) de un mapa, agrupadas por lista para poder editar en orden inverso. */
function transfersOf(map) {
  const byList = new Map();
  for (const [, ev] of map.getIvar("@events")?.pairs ?? []) {
    for (const page of ev.getIvar("@pages") ?? []) {
      const list = page.getIvar("@list") ?? [];
      list.forEach((command, index) => {
        if (command.getIvar("@code") !== 201) return;
        if (!byList.has(list)) byList.set(list, []);
        byList.get(list).push(index);
      });
    }
  }
  return byList;
}

const scriptText = (command) => (command?.getIvar("@parameters") ?? []).map((p) => txt(p)).join("");
const isToneCommand = (command) => command?.getIvar("@code") === 355 && isToneLine(scriptText(command), MARKER);
const isPhaseCommand = (command) => command?.getIvar("@code") === 355 && scriptText(command).includes(`# ${PHASE_MARKER}`);
const isManagedCommand = (command) => isToneCommand(command) || isPhaseCommand(command);

function applyToMap(mapId, index) {
  const map = readMap(mapId);
  const byList = transfersOf(map);
  let inserted = 0, removed = 0;
  for (const [list, indices] of byList) {
    for (const at of [...indices].sort((a, b) => b - a)) {
      const destination = (list[at].getIvar("@parameters") ?? [])[1];
      const indent = list[at].getIvar("@indent") ?? 0;
      let head = at;
      while (head > 0 && isManagedCommand(list[head - 1])) { list.splice(head - 1, 1); head--; removed++; }
      list.splice(head, 0,
        script(phaseLine(phaseOf(destination, index)), indent),
        script(toneLine(toneOf(destination, index), DURATION, MARKER), indent));
      inserted++;
    }
  }
  if (inserted && !DRY) {
    backup(mapFile(mapId));
    writeMap(mapId, map);
  }
  return { inserted, removed };
}

function verify(index) {
  const failures = [];
  const maps = mapIds();
  let checked = 0, orphans = 0;
  for (const mapId of maps) {
    const map = readMap(mapId);
    for (const [, ev] of map.getIvar("@events")?.pairs ?? []) {
      for (const page of ev.getIvar("@pages") ?? []) {
        const list = page.getIvar("@list") ?? [];
        list.forEach((command, at) => {
          if (isToneCommand(command) && (list[at + 1]?.getIvar("@code") ?? 0) !== 201) {
            orphans++;
            failures.push(`Map${mapId}: línea de sensación sin transferencia detrás (comando ${at})`);
          }
          if (isPhaseCommand(command) && !isToneCommand(list[at + 1])) {
            orphans++;
            failures.push(`Map${mapId}: línea de fase sin tono de transferencia detrás (comando ${at})`);
          }
          if (command.getIvar("@code") !== 201) return;
          const destination = (list[at].getIvar("@parameters") ?? [])[1];
          const previous = list[at - 1];
          const phasePrevious = list[at - 2];
          if (!isToneCommand(previous)) {
            failures.push(`Map${mapId}: transferencia a ${destination} sin línea de sensación`);
            return;
          }
          if (!isPhaseCommand(phasePrevious) || !scriptText(phasePrevious).includes(`$game_variables[266] = ${phaseOf(destination, index)}`)) {
            failures.push(`Map${mapId}: transferencia a ${destination} sin su fase de corrupción`);
          }
          if (!scriptText(previous).includes(toneText(toneOf(destination, index)))) {
            failures.push(`Map${mapId}: transferencia a ${destination} con tono equivocado`);
          }
          checked++;
        });
      }
    }
  }
  console.log(`verificación de sensaciones (${checked} transferencias en ${maps.length} mapas${orphans ? `, ${orphans} huérfanas` : ""})`);
  for (const [episode, tone] of Object.entries(TONES)) console.log(`  ${episode.padEnd(8)} ${toneText(tone)}`);
  if (failures.length) { for (const f of failures.slice(0, 12)) console.error(`  FALLA: ${f}`); process.exit(1); }
  console.log("verificación de sensaciones OK");
}

const index = episodeIndex();
if (VERIFY) {
  verify(index);
} else {
  const maps = mapIds();
  let inserted = 0, removed = 0;
  for (const mapId of maps) {
    const result = applyToMap(mapId, index);
    inserted += result.inserted;
    removed += result.removed;
  }
  console.log(`${DRY ? "[dry-run] " : ""}sensaciones: ${inserted} transferencias marcadas (${removed} marcas viejas) en ${maps.length} mapas`);
}#!/usr/bin/env node
/**
 * dn_apply_story_content.mjs — pasada final de guion, memoria, estatuas, ciudades y exploración (E9).
 *
 * Aplica el libreto de `content/dimensional_nightmare_story.json` y las fichas del Director de Nivel
 * (`content/dimensional_nightmare_visual_plan.json` + `TOWN_SERVICE_SPECS`) sobre los datos compilados:
 *   - NPCs con memoria de visita, rutinas animadas en su sitio y reacciones a fase/entorno;
 *   - reubicación segura de eventos sólidos (`character_name != ""`) fuera de cuellos de botella de 1 celda;
 *   - una escena de llegada y tres interludios emotivos por mundo;
 *   - dos puntos de exploración por mapa en los 151 mapas (`DN_MAP_MEMORY` y `DN_STATUE_LORE`);
 *   - Centro Pokémon (`DN_TOWN_CENTER`) y Tienda (`DN_TOWN_MART`) contextuales en los 13 asentamientos;
 *   - una decisión reversible por cada episodio/mundo y una vitrina con consecuencias;
 *   - una guardia de fase por mapa para partidas guardadas dentro del contenido.
 *
 * Uso:
 *   node tools/dn_apply_story_content.mjs            # aplicar
 *   node tools/dn_apply_story_content.mjs --verify   # comprobar datos instalados y transitabilidad con sólidos
 *   node tools/dn_apply_story_content.mjs --dry-run  # plan sin escribir
 */
import fs from "node:fs";
import path from "node:path";
import { RHash, RObject } from "../web/js/marshal.js";
import {
  ROOT, DATA, S, txt, mapFile, readMap, writeMap, backup,
  cmd, condition, graphic, event, texts, script, selfSwitch, wait, readData,
  parseMap, passabilityOf, reachableCells,
} from "./lib/dn_rmxp.mjs";
import { TOWN_SERVICE_SPECS } from "./dn_build_visual_plan.mjs";

const STORY_FILE = path.join(ROOT, "content", "dimensional_nightmare_story.json");
const BLUEPRINT_FILE = path.join(ROOT, "content", "dimensional_nightmare_events.json");
const BUILT_FILE = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const PASS_FILE = path.join(ROOT, "content", "dimensional_nightmare_passability.json");
const EVENTS_BUILT_FILE = path.join(ROOT, "content", "dimensional_nightmare_events_built.json");
const EXPERIENCE_FILE = path.join(ROOT, "content", "dimensional_nightmare_visual_plan.json");
const VERIFY = process.argv.includes("--verify");
const DRY = process.argv.includes("--dry-run");
const story = JSON.parse(fs.readFileSync(STORY_FILE, "utf8"));
const blueprint = JSON.parse(fs.readFileSync(BLUEPRINT_FILE, "utf8"));
const builtPlan = JSON.parse(fs.readFileSync(BUILT_FILE, "utf8"));
const passabilityJson = JSON.parse(fs.readFileSync(PASS_FILE, "utf8")).maps ?? {};
const eventsBuiltJson = JSON.parse(fs.readFileSync(EVENTS_BUILT_FILE, "utf8")).maps ?? {};
const experience = JSON.parse(fs.readFileSync(EXPERIENCE_FILE, "utf8"));
const mapMeta = new Map(builtPlan.maps.map((item) => [item.id, item]));
const visualByMap = new Map(experience.maps.map((item) => [item.map, item]));
const episodeByKey = new Map(blueprint.episodes.map((episode) => [episode.key, episode]));
const episodesWithBoss = blueprint.episodes.filter((episode) => episode.boss);
const PHASE_A_SWITCHES = Object.freeze({ EP01: 903, EP02: 904, EP03: 905, EP04: 906, EP05: 907, EP06: 908, W7: 928, W8: 929, W9: 930 });
const PHASE_B_VARIABLE_BASE = 289;
const PHASE_NAMES = Object.freeze({
  1: "Normal", 2: "Duda", 3: "Grieta", 4: "Ruido", 5: "Pérdida", 6: "Ruptura parcial", 7: "Ruptura",
});
const OWNED_NAMES = new Set([
  "DN_PHASE_GUARD",
  "DN_MAP_MEMORY",
  "DN_STATUE_LORE",
  "DN_TOWN_CENTER",
  "DN_TOWN_MART",
  "DN_OPENING_SCENE",
  "DN_DECISION_ARCHIVE",
  ...Array.from({ length: 5 }, (_, i) => `DN_PHASE_SCENE_${i + 3}`),
]);
const OWNED_PREFIXES = ["DN_DECISION_", "DN_PHASE_SCENE_"];
const OPENING_MAPS = Object.freeze({
  HUB: 2040, EP01: 2041, EP02: 2057, EP03: 2073, EP04: 2088, EP05: 2104, EP06: 2120,
  NEXO: 2136, LIGA: 2141, W7: 2143, W8: 2159, W9: 2175,
});
const HUE = Object.freeze({ EP01: 0, EP02: 36, EP03: 72, EP04: 144, EP05: 216, EP06: 288, NEXO: 180, LIGA: 180, W7: 12, W8: 30, W9: 300, HUB: 180 });
const HUB_OPENING = [
  "Rotom: Nueve rutas aparecen en el registro; sólo las que has desbloqueado responden.",
  "Ash: No voy a cambiar sus historias. Voy a escuchar lo que dejaron en el camino.",
  "Rotom: Las marcas de regreso están guardadas. Puedes abandonar la Antesala cuando quieras."
];
const WORLD_RANGES = Object.freeze({
  EP01: [2041, 2056], EP02: [2057, 2072], EP03: [2073, 2087], EP04: [2088, 2103],
  EP05: [2104, 2119], EP06: [2120, 2135], NEXO: [2136, 2140], W7: [2143, 2158],
  W8: [2159, 2174], W9: [2175, 2190],
});
const DECISION_WORLDS = Object.keys(WORLD_RANGES).filter((key) => story.worlds[key]?.decision);
const allDecisionProfiles = [
  ...DECISION_WORLDS.map((key) => [key, story.worlds[key].decision]),
  ["LIGA", story.worlds.LIGA.decision],
];

const hasMarker = (name) => OWNED_NAMES.has(name) || OWNED_PREFIXES.some((prefix) => name.startsWith(prefix));
const makePage = ({
  cond = condition(), gfx = graphic(), trigger = 0, through = false, moveType = 0,
  moveSpeed = 2, moveFrequency = 2, stepAnime = false, directionFix = false, list = [cmd(0)],
} = {}) => new RObject("RPG::Event::Page", [
  ["@condition", cond], ["@graphic", gfx],
  ["@move_type", moveType], ["@move_speed", moveSpeed], ["@move_frequency", moveFrequency],
  ["@move_route", new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", true], ["@list", []]])],
  ["@walk_anime", true], ["@step_anime", stepAnime], ["@direction_fix", directionFix],
  ["@through", through], ["@always_on_top", false], ["@trigger", trigger], ["@list", list],
]);
const listText = (lines, indent = 0) => texts(lines, indent);
const scriptCommand = (source, indent = 0) => script(source, indent);
const varAtLeast = (id, value) => condition({ variable: [id, value] });
const selfIs = (letter) => condition({ self: letter });
const cleanName = (name) => String(name ?? "").replace(/\s*\(.*?\)\s*/g, "").trim();
const worldForEpisode = (key) => story.worlds[key] ?? story.worlds.NEXO;

function mapPhase(mapId) {
  if (mapId === 2040) return 0;
  if (mapId === 2141) return 5;
  if (mapId === 2142) return 7;
  const key = mapMeta.get(mapId)?.episode;
  const range = WORLD_RANGES[key];
  if (!range) return 0;
  const [from, to] = range;
  const span = Math.max(1, to - from);
  return Math.max(1, Math.min(7, Math.round(((mapId - from) / span) * 6) + 1));
}

function npcEventName(npc) {
  const key = npc.name.replace(/[^\w]/g, "_").slice(0, 24);
  const suffix = (npc.groupCount ?? 1) > 1 ? `_${String(npc.instance).padStart(2, "0")}` : "";
  return `NPC_${key}${suffix}`;
}

function extractQuote(notes) {
  const fixed = notes.match(/Fija:\s*«([^»]+)»/i);
  if (fixed) return fixed[1].trim();
  const quoted = notes.match(/«([^»]{8,})»/);
  return quoted?.[1]?.trim() ?? null;
}

function npcRole(npc) {
  const type = String(npc.type).toLowerCase();
  if (type.includes("interdimensional") || type.includes("entidad") || type.includes("jefe final")) return "interdimensional";
  if (type.includes("consciente")) return "conscious";
  return "normal";
}

function eventGraphic(eventObject) {
  const first = eventObject.getIvar("@pages")?.[0]?.getIvar("@graphic");
  const charName = txt(first?.getIvar("@character_name"));
  const hue = first?.getIvar("@character_hue") ?? 0;
  const tile = first?.getIvar("@tile_id") ?? 0;
  const opacity = first?.getIvar("@opacity") ?? 255;
  return graphic(charName, first?.getIvar("@direction") ?? 2, first?.getIvar("@pattern") ?? 1, { hue, tile, opacity });
}

function eventHasSolidSprite(eventObject) {
  return (eventObject.getIvar("@pages") ?? []).some(
    (page) => txt(page.getIvar("@graphic")?.getIvar("@character_name")) !== "",
  );
}

function npcPages(npc, world, existingGraphic) {
  const name = cleanName(npc.displayName ?? npc.name);
  const quoted = extractQuote(npc.notes);
  const role = npcRole(npc);
  const lively = role === "normal" && !/no caminan|no se mueve|no habla|solo texto|sin sprite|no se puede hablar/i.test(npc.notes);
  if (role === "interdimensional") {
    const fixed = quoted ?? world.interdimensional.phase4;
    return [
      makePage({ gfx: existingGraphic, list: [...listText([`${name}: «${fixed}»`]), cmd(0)] }),
      makePage({ cond: varAtLeast(266, 4), gfx: existingGraphic, trigger: 0, stepAnime: true,
        list: [...listText([`${name}: «${world.interdimensional.phase4}»`]), cmd(0)] }),
      makePage({ cond: varAtLeast(266, 7), gfx: existingGraphic, trigger: 0,
        list: [...listText([`${name}: «${world.interdimensional.phase7}»`]), cmd(0)] }),
    ];
  }

  const lines = role === "conscious" ? world.conscious : world.normal;
  if (role === "normal") {
    const firstLine = quoted ?? lines[0];
    // moveType: 0 con stepAnime evita que el NPC camine hacia un pasillo de 1 celda y bloquee al jugador en Game.exe
    return [
      makePage({ gfx: existingGraphic, moveType: 0, stepAnime: lively,
        list: [...listText([`${name}: ${firstLine}`]), selfSwitch("A"), cmd(0)] }),
      makePage({ cond: selfIs("A"), gfx: existingGraphic, moveType: 0, stepAnime: lively,
        list: [...listText([`${name}: ${lines[1]}`]), selfSwitch("B"), cmd(0)] }),
      makePage({ cond: selfIs("B"), gfx: existingGraphic, moveType: 0, stepAnime: lively,
        list: [...listText([`${name}: ${lines[2]}`]), selfSwitch("C"), cmd(0)] }),
      makePage({ cond: selfIs("C"), gfx: existingGraphic, moveType: 0, stepAnime: lively,
        list: [...listText([`${name}: ${lines[3]}`]), selfSwitch("D"), cmd(0)] }),
      makePage({ cond: selfIs("D"), gfx: existingGraphic, moveType: 0,
        list: [...listText([`${name}: ${lines[4]}`]), selfSwitch("E"), cmd(0)] }),
      makePage({ cond: selfIs("E"), gfx: existingGraphic, trigger: 0, list: [cmd(0)] }),
      makePage({ cond: varAtLeast(266, 6), gfx: existingGraphic, trigger: 0, list: [cmd(0)] }),
    ];
  }

  const firstLine = quoted ?? lines[0];
  const disappearsAtRupture = (Number(npc.map) + Number(npc.instance ?? 1)) % 3 === 0;
  return [
    makePage({ gfx: existingGraphic, list: [...listText([`${name}: ${firstLine}`]), selfSwitch("A"), cmd(0)] }),
    makePage({ cond: selfIs("A"), gfx: existingGraphic, moveType: 0, stepAnime: true,
      list: [...listText([`${name}: ${lines[1]}`]), selfSwitch("B"), cmd(0)] }),
    makePage({ cond: selfIs("B"), gfx: existingGraphic, moveType: 0, stepAnime: true,
      list: [...listText([`${name}: ${lines[2]}`]), selfSwitch("C"), cmd(0)] }),
    makePage({ cond: selfIs("C"), gfx: existingGraphic, list: [...listText([`${name}: ${lines[3]}`]), selfSwitch("D"), cmd(0)] }),
    makePage({ cond: selfIs("D"), gfx: existingGraphic, trigger: 0, list: [cmd(0)] }),
    makePage({ cond: varAtLeast(266, 6), gfx: disappearsAtRupture ? graphic("") : existingGraphic,
      trigger: 0, through: true, list: [cmd(0)] }),
  ];
}

function guardEvent(mapId, id, x, y) {
