    originalComposition: true,
    format: "Standard MIDI File type 0 · 480 PPQ · General MIDI · no borrowed samples",
    silence: { from: 2104, to: 2109, reason: "EP05 phases 1–3 require true silence" },
    tracks: TRACKS.map((track) => {
      const file = `${track.name}.mid`;
      const bytes = fs.readFileSync(path.join(BGM_DIR, file));
      return {
        file: `Audio/BGM/${file}`, title: track.title, bpm: track.bpm,
        bars: track.bars, beatsPerBar: track.beats,
        durationSeconds: Math.round(track.bars * track.beats * 60 / track.bpm),
        mood: track.mood, bytes: bytes.length, sha256: sha256(bytes),
      };
    }),
    mapAssignments: MAP_RANGES.map((range) => ({
      from: range.from, to: range.to, track: range.track || null,
      volume: range.volume, pitch: 100,
    })),
  };
}
function build() {
  fs.mkdirSync(BGM_DIR, { recursive: true });
  for (const track of TRACKS) fs.writeFileSync(path.join(BGM_DIR, `${track.name}.mid`), midiFor(track));
  for (const range of MAP_RANGES) {
    for (let mapId = range.from; mapId <= range.to; mapId++) applyMap(mapId, {
      track: range.track, volume: range.volume, pitch: 100,
    });
  }
  fs.writeFileSync(MANIFEST, `${JSON.stringify(manifestFor(), null, 2)}\n`);
  console.log(`audio DN: ${TRACKS.length} composiciones MIDI originales · silencio explícito Map2104–2109 · BGM asignadas en ${MAP_RANGES.reduce((n, range) => n + range.to - range.from + 1, 0)} mapas`);
}
function verify() {
  const failures = [];
  const check = (condition, message) => { if (!condition) failures.push(message); };
  for (const track of TRACKS) {
    const file = path.join(BGM_DIR, `${track.name}.mid`);
    if (!fs.existsSync(file)) { failures.push(`falta Audio/BGM/${track.name}.mid`); continue; }
    const bytes = fs.readFileSync(file);
    check(bytes.subarray(0, 4).toString("ascii") === "MThd", `${track.name}: cabecera MIDI inválida`);
    check(bytes.readUInt16BE(8) === 0 && bytes.readUInt16BE(10) === 1 && bytes.readUInt16BE(12) === PPQ,
      `${track.name}: debe ser MIDI tipo 0 de una pista a 480 PPQ`);
    check(bytes.includes(Buffer.from(track.name, "utf8")), `${track.name}: falta metadato de título`);
    check(bytes.subarray(bytes.length - 3).equals(Buffer.from([0xff, 0x2f, 0x00])), `${track.name}: falta fin de pista MIDI`);
  }
  for (const range of MAP_RANGES) for (let mapId = range.from; mapId <= range.to; mapId++) {
    const file = path.join(DATA, mapFile(mapId));
    if (!fs.existsSync(file)) { failures.push(`falta ${mapFile(mapId)}`); continue; }
    const actual = mapAudio(mapId);
    check(actual.autoplay === true && actual.name === range.track && actual.volume === range.volume && actual.pitch === 100,
      `Map${mapId}: BGM/autoplay no coincide con ${range.track || "silencio"}`);
  }
  if (!fs.existsSync(MANIFEST)) failures.push("falta content/dimensional_nightmare_audio.json");
  else {
    const manifest = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
    check(manifest.tracks?.length === TRACKS.length, "manifiesto de audio incompleto");
    for (const item of manifest.tracks ?? []) {
      const bytes = fs.readFileSync(path.join(BGM_DIR, path.basename(item.file)));
      check(bytes.length === item.bytes && sha256(bytes) === item.sha256, `${item.file}: hash distinto del manifiesto`);
    }
  }
  if (failures.length) {
    for (const failure of failures) console.error(`FALLA: ${failure}`);
    process.exit(1);
  }
  console.log(`audio DN verificado: ${TRACKS.length} MIDI originales y ${MAP_RANGES.reduce((n, range) => n + range.to - range.from + 1, 0)} mapas con BGM explícita`);
}
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (VERIFY) verify();
  else { build(); verify(); }
}

export { TRACKS, MAP_RANGES, midiFor, manifestFor };#!/usr/bin/env node
/**
 * dn_build_hub_events.mjs — eventos del hub del Dimensional Nightmare.
 *
 * El mapa 2040 (Antesala de las Grietas) se construyó en E3 pero quedó sin eventos: hoy el
 * jugador termina un episodio, cae en la Gruta de los Testigos (Map2030, celda de llegada que
 * fija el GDD) y no tiene forma de volver a entrar al ciclo. Esta herramienta cierra ese lazo:
 *
 *   Map2030  HUB_GRIETA_CAVE   grieta de entrada (se abre con v264 ≥ 3) → Antesala
 *   Map2040  HUB_GRIETA_EPxx   seis grietas, una por episodio (EP01-03 con v264 ≥ 3,
 *                              EP04-06 con v264 ≥ 7) → primer mapa del episodio
 *   Map2040  HUB_GRIETA_W7-W9  segundo anillo: W7 abre con la Liga Oscura cerrada (sw920);
 *                              W8 y W9 se encadenan por los cierres W7/W8 (sw925/sw926).
 *                              v264 sigue siendo sólo el contador de emisiones de Monte Silver.
 *   Map2040  HUB_ARCHIVERO     guía del hub (textos por progreso de sellos)
 *   Map2040  HUB_PROGRESO      monumento: sellos, resonancia y anomalías registradas
 *   Map2040  HUB_SALIDA        borde inferior de la Antesala → de vuelta a la Gruta
 *
 * Las celdas se eligen sobre la malla **real** del mapa (pasabilidad + alcanzabilidad desde la
 * entrada), nunca a ojo: los seis altares se reparten por el perímetro con muestreo de punto más
 * lejano, y la salida se ancla al borde inferior. Todo se guarda en
 * `content/dimensional_nightmare_events_built.json` → `hubMap`, para que la verificación pueda
 * comprobar celdas, tipos de evento y destinos sin abrir el juego.
 *
 * Uso:
 *   node tools/dn_build_hub_events.mjs            # construye/actualiza (idempotente)
 *   node tools/dn_build_hub_events.mjs --dry-run  # muestra el plan sin escribir
 *   node tools/dn_build_hub_events.mjs --verify   # sólo comprueba
 *   node tools/dn_build_hub_events.mjs --render   # además, hoja visual del hub
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RHash, RObject, RString } from "../web/js/marshal.js";
import { parseMap, tableGet } from "../web/js/rmxp.js";
import { passabilityOf, reachableCells } from "./lib/map_painter.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "pokemon_fire_ash", "Data");
const CHAR_DIR = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Characters");
const BUILT = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const EVENTS = path.join(ROOT, "content", "dimensional_nightmare_events_built.json");
const BACKUP = path.join(ROOT, "pokemon_fire_ash", "PokeModBackups", "dimensional_nightmare_maps_originals");

const OWNED = ["HUB_GRIETA_CAVE", "HUB_ARCHIVERO", "HUB_PROGRESO", "HUB_SALIDA"];   // eventos propios
const OWNS = (name) => OWNED.includes(name) || /^HUB_GRIETA_(EP\d\d|W\d+|NEXO)$/.test(name);

const CAVE_ID = 2030;          // Gruta de los Testigos (mapa base del juego)
const HUB_ID = 2040;           // Antesala de las Grietas (construida en E3)
const RIFT_STEP = 4;           // separación mínima entre altares
const EPISODES = [
  { key: "EP01", unlock: 3, hue: 0, flavor: "La grieta huele a papel viejo y a tinta." },
  { key: "EP02", requireSwitch: 890, hue: 36, flavor: "Un cartucho gira en el aire, sin consola." },
  { key: "EP03", requireSwitch: 891, hue: 72, flavor: "De la grieta cae nieve que no derrite." },
  { key: "EP04", requireSwitch: 892, requireSwitch2: 703, hue: 144, flavor: "Alguien tararea una nana al otro lado." },
  { key: "EP05", requireSwitch: 893, requireVariable: [275, 2], hue: 216, flavor: "La grieta devuelve tu propio reflejo, un paso tarde." },
  { key: "EP06", unlock: 7, requireSwitch: 894, hue: 288, flavor: "Una letra te observa desde el borde." },
  { key: "NEXO", requireSwitch: 895, hue: 180, flavor: "El Nexo sólo responde cuando King Unown deja su sello." },
  // Segundo anillo: la Liga Oscura ya cerrada abre W7; los sellos encadenan W8 → W9.
  // No se reutiliza v264: pertenece al contador de emisiones selladas de Monte Silver (máximo 7).
  { key: "W7", requireSwitch: 920, hue: 12, flavor: "Del segundo anillo llega olor a correa vieja." },
  { key: "W8", requireSwitch: 925, hue: 30, flavor: "La grieta escupe tierra húmeda y no se cierra." },
  { key: "W9", requireSwitch: 926, hue: 300, flavor: "Alguien tararea desafinado detrás del muro." },
];

const argv = process.argv.slice(2);
const VERIFY = argv.includes("--verify");
const RENDER = argv.includes("--render");
const DRY = argv.includes("--dry-run");

const S = (v) => RString.fromText(String(v));
const txt = (v) => (v && v.text !== undefined ? v.text : String(v ?? ""));
const mapFile = (id) => `Map${String(id).padStart(3, "0")}.rxdata`;
const readMap = (id) => marshalLoad(fs.readFileSync(path.join(DATA, mapFile(id))));
const warnings = [];

// --------------------------------------------------------------- RMXP bits
const cmd = (code, params = [], indent = 0) => new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", params]]);
const condition = ({ sw = 0, sw2 = 0, self = "", variable = null } = {}) => new RObject("RPG::Event::Page::Condition", [
  ["@switch1_valid", !!sw], ["@switch1_id", sw || 1],
  ["@switch2_valid", !!sw2], ["@switch2_id", sw2 || 1],
  ["@variable_valid", !!variable], ["@variable_id", variable ? variable[0] : 1], ["@variable_value", variable ? variable[1] : 0],
  ["@self_switch_valid", !!self], ["@self_switch_ch", S(self || "A")],
]);
const graphic = (charName = "", dir = 2, pattern = 1, opts = {}) => new RObject("RPG::Event::Page::Graphic", [
  ["@tile_id", opts.tile ?? 0], ["@character_name", S(charName)], ["@character_hue", opts.hue ?? 0],
  ["@direction", dir], ["@pattern", pattern], ["@opacity", opts.opacity ?? 255], ["@blend_type", 0],
]);
const moveRoute = () => new RObject("RPG::MoveRoute", [["@repeat", true], ["@skippable", false], ["@list", []]]);
const page = ({ cond = condition(), gfx = graphic(), trigger = 0, through = false, list = [cmd(0)] } = {}) => new RObject("RPG::Event::Page", [
  ["@condition", cond], ["@graphic", gfx],
  ["@move_type", 0], ["@move_speed", 3], ["@move_frequency", 3],
  ["@move_route", moveRoute()], ["@walk_anime", true], ["@step_anime", false],
  ["@direction_fix", false], ["@through", through], ["@always_on_top", false],
  ["@trigger", trigger], ["@list", list],
]);
const event = (id, name, x, y, pages) => new RObject("RPG::Event", [["@id", id], ["@name", S(name)], ["@x", x], ["@y", y], ["@pages", pages]]);
const texts = (lines) => [cmd(101, [S("")]), ...[].concat(lines).map((line) => cmd(401, [S(line)]))];
const script = (line) => cmd(355, [S(line)]);
const transfer = (mapId, x, y, dir = 2) => cmd(201, [0, mapId, x, y, dir, 1]);
const graphicOk = (name) => fs.existsSync(path.join(CHAR_DIR, name));

// --------------------------------------------------------------- malla del hub
function grid(id) {
  const raw = readMap(id);
  const parsed = parseMap(raw);
  const pass = passabilityOf(parsed, parsed.tilesetId);
  const pairs = raw.getIvar("@events")?.pairs ?? [];
  const events = pairs.map(([, obj]) => ({
    name: txt(obj.getIvar("@name")),
    x: obj.getIvar("@x"),
    y: obj.getIvar("@y"),
    obj,
  }));
  const occupied = new Set(events.filter((e) => !OWNS(e.name)).map((e) => `${e.x},${e.y}`));
  return { raw, parsed, pass, events, occupied, width: parsed.width, height: parsed.height };
}

function buildPlan() {
  const builtMaps = JSON.parse(fs.readFileSync(BUILT, "utf8")).maps;
  const eventData = JSON.parse(fs.readFileSync(EVENTS, "utf8"));
  const hubMeta = builtMaps.find((m) => m.id === HUB_ID);
  if (!hubMeta) throw new Error(`no hay ficha de construcción del mapa ${HUB_ID}; corre \`npm run dn:hub\``);
  const entry = hubMeta.bfs?.entry ?? [Math.floor(hubMeta.width / 2), hubMeta.height - 2];
  const hub = grid(HUB_ID);
  const reach = reachableCells(hub.pass, entry);
  const dist = (a, b) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
  const center = [Math.floor(hub.width / 2), Math.floor(hub.height / 2)];
  const occupied = new Set(hub.occupied);
  const candidates = [...reach]
    .map((k) => k.split(",").map(Number))
    .filter(([x, y]) => !occupied.has(`${x},${y}`) && dist([x, y], entry) >= 2);

  // salida: la celda alcanzable más al sur (borde inferior de la Antesala)
  const exit = [...candidates].sort((a, b) => b[1] - a[1] || Math.abs(a[0] - center[0]) - Math.abs(b[0] - center[0]))[0];
  if (!exit) throw new Error("no hay celdas libres alcanzables en la Antesala");

  // altares: banda de perímetro + muestreo del punto más lejano (reparto parejo)
  const ring = candidates.filter((c) => dist(c, center) >= Math.max(4, Math.floor(Math.min(hub.width, hub.height) / 2)));
  const pool = ring.length >= EPISODES.length ? ring : candidates;
  const chosen = [...pool].sort((a, b) => dist(b, entry) - dist(a, entry))[0] ? [
    [...pool].sort((a, b) => dist(b, entry) - dist(a, entry))[0],
  ] : [];
  const taken = [entry, exit, ...chosen];
  while (chosen.length < EPISODES.length) {
    let best = null, bestScore = -1;
    for (const c of pool) {
      if (taken.includes(c)) continue;
      const score = Math.min(...taken.map((t) => dist(c, t)));
      if (score > bestScore) { bestScore = score; best = c; }
    }
    if (!best || bestScore < RIFT_STEP) break;
    chosen.push(best); taken.push(best);
  }
  if (chosen.length < EPISODES.length) warnings.push(`sólo se pudieron repartir ${chosen.length}/${EPISODES.length} altares con separación ≥${RIFT_STEP}`);

  // archivero junto a la salida; monumento junto a la entrada
  const near = (from, min = 1) => [...candidates].filter((c) => !taken.includes(c) && dist(c, from) >= min)
    .sort((a, b) => dist(a, from) - dist(b, from))[0] ?? null;
  const archivero = near(exit, 1);
  if (archivero) taken.push(archivero);
  // monumento en el centro de la sala (calculado después de reservar el archivero)
  const progreso = [...candidates].filter((c) => !taken.includes(c)).sort((a, b) => dist(a, center) - dist(b, center))[0] ?? null;
  if (progreso) taken.push(progreso);

  // grieta de entrada en la Gruta: celda libre junto a la llegada del GDD
  const cave = grid(CAVE_ID);
  const caveOccupied = new Set(cave.occupied);
  const arrival = (eventData.hub?.cell ?? [36, 12]).slice(0, 2);
  if (caveOccupied.has(arrival.join(","))) warnings.push(`la llegada al hub ${arrival} coincide con un evento de la Gruta`);
  let caveStart = arrival;
  if (!cave.pass.passable(caveStart[0], caveStart[1], 8)) {
    let best = null, bestDistance = Infinity;
    for (let y = 0; y < cave.height; y++) for (let x = 0; x < cave.width; x++) {
      if (!cave.pass.passable(x, y, 8)) continue;
      const d = dist([x, y], arrival);
      if (d < bestDistance) { best = [x, y]; bestDistance = d; }
    }
    caveStart = best ?? arrival;
  }
  const caveReach = reachableCells(cave.pass, caveStart);
  const ringCave = [];
  for (let dy = -6; dy <= 6; dy++) {
    for (let dx = -6; dx <= 6; dx++) {
      const x = arrival[0] + dx, y = arrival[1] + dy;
      if (x < 0 || y < 0 || x >= cave.width || y >= cave.height) continue;
      if (caveOccupied.has(`${x},${y}`)) continue;
      if (!caveReach.has(`${x},${y}`)) continue;
      if (!cave.pass.canMove(x, y, 2) || !cave.pass.canMove(x, y, 8)) continue;
      if (dx === 0 && dy === 0) continue;
      ringCave.push([x, y, Math.abs(dx) + Math.abs(dy)]);
    }
  }
  ringCave.sort((a, b) => a[2] - b[2] || a[1] - b[1]);
  const caveGate = ringCave[0] ?? null;
  if (!caveGate) warnings.push("no se encontró celda libre para la grieta de entrada en la Gruta");

  // destinos: primer mapa de cada episodio y su celda de entrada registrada en E4
  const targets = EPISODES.map((ep) => {
    const ids = Object.entries(eventData.maps ?? {})
      .filter(([, v]) => v.episode === ep.key)
      .map(([id, v]) => ({ id: Number(id), entry: v.entry, exit: v.exit }))
      .sort((a, b) => a.id - b.id);
    const first = ids[0];
    if (!first) warnings.push(`${ep.key}: sin mapas en el catálogo de eventos`);
    return { ...ep, mapId: first?.id ?? null, cell: first?.entry ?? null };
  });

  return { entry, exit, rifts: chosen, archivero, progreso, targets, caveGate, caveStart, arrival, hub, cave };
}

// --------------------------------------------------------------- eventos
function makeEvents(plan, baseId) {
  const events = [];
  let id = baseId;
  const riftPages = (spec, cell) => [
    page({
      gfx: graphic("UNOWN", 2, 1, { hue: spec.hue }),
      list: [...texts([`La grieta de ${spec.key} está sellada.`, "El Rotom no reconoce su firma todavía."]), cmd(0)],
    }),
    page({
      cond: condition({
        sw: spec.requireSwitch ?? 0,
        sw2: spec.requireSwitch2 ?? 0,
        variable: spec.requireVariable ?? (spec.unlock ? [264, spec.unlock] : null),
      }),
      gfx: graphic("UNOWN", 2, 1, { hue: spec.hue }),
      trigger: 1, // entrar es caminar hacia la grieta
      list: [
        ...texts([`${spec.key} — ${spec.flavor}`]),
        transfer(spec.mapId ?? HUB_ID, spec.cell?.[0] ?? plan.entry[0], spec.cell?.[1] ?? plan.entry[1], 8),
        cmd(0),
      ],
    }),
  ];
  for (const [i, spec] of plan.targets.entries()) {
    const cell = plan.rifts[i] ?? plan.entry;
    events.push(event(id++, `HUB_GRIETA_${spec.key}`, cell[0], cell[1], riftPages(spec, cell)));
  }
  const readyCheck = `begin; $game_switches[917] = [:DN_CASE_WHT, :DN_CASE_LSV, :DN_CASE_SNO, :DN_CASE_HYP, :DN_CASE_BLK, :DN_CASE_UNO].all? { |i| $PokemonBag.pbHasItem?(i) }; rescue; end`;
  if (plan.archivero) {
    events.push(event(id++, "HUB_ARCHIVERO", plan.archivero[0], plan.archivero[1], [
      page({
        cond: condition({ sw: 917 }),
        gfx: graphic("trchar000", 2, 1),
        list: [
          ...texts([
            "Archivero: las seis cartucheras están completas.",
            "La puerta del centro ya responde: la Liga Oscura te espera.",
            "Dentro hay algo que corre más rápido que cualquier nivel que hayas visto.",
          ]),
          cmd(0),
        ],
      }),
      page({
        gfx: graphic("trchar000", 2, 1),
        list: [
          script(readyCheck),
          ...texts([
            "Archivero: cada grieta que se cierra deja un registro.",
            "Los seis sellos de la Gruta son la cuenta del Nightmare.",
            "Cuando estén los seis, el Nexo se abrirá solo.",
          ]),
          script("$game_variables[277] = (883..888).count { |i| $game_switches[i] }"),
          script('pbMessage("Archivero: sellos encendidos, #{$game_variables[277]} de 6.")'),
          cmd(0),
        ],
      }),
      page({
        cond: condition({ variable: [277, 6] }),
        gfx: graphic("trchar000", 2, 1),
        list: [
          script(readyCheck),
          ...texts([
            "Archivero: los seis sellos están en su sitio.",
            "El Nexo de las Grietas te espera al final de la Gruta.",
            "Lo que decidas allí quedará registrado para siempre.",
          ]),
          cmd(0),
        ],
      }),
      page({
        cond: condition({ sw: 889 }),
        gfx: graphic("trchar000", 2, 1),
        list: [...texts(["Archivero: el registro está cerrado.", "La Grieta ya no responde. El Nightmare quedó atrás."]), cmd(0)],
      }),
    ]));
  }
  if (plan.progreso) {
    events.push(event(id++, "HUB_PROGRESO", plan.progreso[0], plan.progreso[1], [
      page({
        gfx: graphic("Object rock", 2, 1),
        list: [
          script("$game_variables[277] = (883..888).count { |i| $game_switches[i] }"),
          script('pbMessage("Sellos: #{$game_variables[277]}/6")'),
          script('pbMessage("Resonancia: #{$game_variables[265]}/100 · Anomalías: #{$game_variables[274]}/77")'),
          script('pbMessage("Rotom: nivel #{$game_variables[275]}")'),
          script('pbMessage("El Nexo sigue abierto.") if $game_switches[889]'),
          cmd(0),
        ],
      }),
    ]));
  }
  events.push(event(id++, "HUB_SALIDA", plan.exit[0], plan.exit[1], [
    page({
      gfx: graphic("Object ball special", 2, 1),
      trigger: 1, // tocar el borde inferior = salir
      list: [transfer(CAVE_ID, plan.arrival[0], plan.arrival[1], 8), cmd(0)],
    }),
  ]));
  return events;
}

function makeCaveGate(plan, baseId) {
  if (!plan.caveGate) return null;
  const [x, y] = plan.caveGate;
  return event(baseId, "HUB_GRIETA_CAVE", x, y, [
    page({
      gfx: graphic("Object ball special", 2, 1),
      list: [...texts(["Una grieta late en la roca, pero el Rotom duerme.", "(Vuelve cuando el Nightmare despierte: progreso 3.)"]), cmd(0)],
    }),
    page({
      cond: condition({ variable: [264, 3] }),
      gfx: graphic("Object ball special", 2, 1),
      trigger: 1, // se baja caminando hacia la grieta
      list: [
        ...texts(["El Rotom reconoce la firma de la grieta."]),
        transfer(HUB_ID, plan.entry[0], plan.entry[1], 8),
        cmd(0),
      ],
    }),
  ]);
}

// --------------------------------------------------------------- escritura
function writeMap(id, add) {
  const full = path.join(DATA, mapFile(id));
  fs.mkdirSync(BACKUP, { recursive: true });
  if (!fs.existsSync(path.join(BACKUP, mapFile(id)))) fs.copyFileSync(full, path.join(BACKUP, mapFile(id)));
  const map = marshalLoad(fs.readFileSync(full));
  const pairs = map.getIvar("@events").pairs;
  const kept = pairs.filter(([, e]) => !OWNS(txt(e.getIvar("@name"))));
  const removed = pairs.length - kept.length;
  const baseId = Math.max(0, ...kept.map(([k]) => (typeof k === "number" ? k : 0))) + 1;
  const added = add(baseId).filter(Boolean);
  map.setIvar("@events", new RHash([...kept, ...added.map((e) => [e.getIvar("@id"), e])]));
  if (!DRY) fs.writeFileSync(full, Buffer.from(marshalDump(map)));
  return { removed, added: added.map((e) => ({ name: txt(e.getIvar("@name")), x: e.getIvar("@x"), y: e.getIvar("@y") })) };
}

// --------------------------------------------------------------- render
/** Hoja visual del hub: mapa 2040 a 2× con las celdas de los eventos marcadas. */
async function renderHub(plan) {
  const { createCanvas, loadImage } = await import("@napi-rs/canvas");
  const outDir = path.join(ROOT, "docs", "dn_referencia", "lotes");
  fs.mkdirSync(outDir, { recursive: true });
  const parsed = parseMap(readMap(HUB_ID));
  const tilesets = marshalLoad(fs.readFileSync(path.join(DATA, "Tilesets.rxdata")));
  const name = tilesets[parsed.tilesetId].getIvar("@tileset_name").text;
  const img = await loadImage(path.join(ROOT, "pokemon_fire_ash", "Graphics", "Tilesets", `${name}.png`));
  const S = 32, Z = 2, BASE = 384;            // 0-47 vacío, 48-383 autotiles, 384+ tiles normales
  const COLS = Math.max(1, Math.floor(img.width / S));
  const canvas = createCanvas(parsed.width * S * Z, parsed.height * S * Z);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#101418";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < parsed.height; y++) {
    for (let x = 0; x < parsed.width; x++) {
      for (let z = 0; z < 3; z++) {
        const tile = tableGet(parsed.table, x, y, z);
        if (!tile) continue;
        const idx = tile - BASE;                // los tiles normales se indexan desde 384
        if (idx < 0) continue;                  // autotiles: no se dibujan (este mapa no usa)
        ctx.drawImage(img, (idx % COLS) * S, Math.floor(idx / COLS) * S, S, S, x * S * Z, y * S * Z, S * Z, S * Z);
      }
    }
  }
  const dot = (cell, color, label) => {
    if (!cell) return;
    const cx = cell[0] * S * Z + S * Z / 2, cy = cell[1] * S * Z + S * Z / 2;
    ctx.beginPath(); ctx.arc(cx, cy, S * Z * 0.42, 0, Math.PI * 2);
    ctx.fillStyle = color; ctx.globalAlpha = 0.85; ctx.fill(); ctx.globalAlpha = 1;
    ctx.lineWidth = 2; ctx.strokeStyle = "#101418"; ctx.stroke();
    if (label) {
      ctx.font = `bold ${Math.round(S * Z * 0.55)}px sans-serif`;
      ctx.fillStyle = "#101418"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(label, cx, cy + 1);
    }
  };
  dot(plan.entry, "#2ecc71", "E");
  dot(plan.exit, "#3d7bff", "S");
  dot(plan.archivero, "#ffd23d", "A");
  dot(plan.progreso, "#ff8ad8", "P");
  plan.rifts.forEach((cell, i) => cell && dot(cell, "#ff3b30", String(i + 1)));
  fs.writeFileSync(path.join(outDir, "HUB_2040.png"), canvas.toBuffer("image/png"));
  console.log(`render: docs/dn_referencia/lotes/HUB_2040.png · grieta de entrada en ${CAVE_ID} @ ${plan.caveGate.join(",")}`);
}

async function main() {
  const plan = buildPlan();
  const hudEvents = (base) => makeEvents(plan, base);
  const caveGate = (base) => [makeCaveGate(plan, base)];

  if (!VERIFY) {
    for (const sprite of ["UNOWN.png", "Object ball special.png", "Object rock.png", "trchar000.png"]) {
      if (!graphicOk(sprite)) warnings.push(`falta el gráfico de personaje ${sprite}`);
    }
  }

  const summary = {
    generatedBy: "tools/dn_build_hub_events.mjs",
    cave: { map: CAVE_ID, arrival: plan.arrival, gate: plan.caveGate },
    hub: {
      map: HUB_ID, entry: plan.entry, exit: plan.exit,
      archivero: plan.archivero, progreso: plan.progreso,
      rifts: Object.fromEntries(plan.targets.map((t, i) => [plan.rifts[i] ? t.key : t.key, { cell: plan.rifts[i] ?? plan.entry, to: t.mapId, cellTo: t.cell }])),
    },
    switches: { unlock: 882, seals: [883, 888], cleared: 889, secondRing: 920, nextRifts: [925, 926] },
    variables: { monteSilverEmissionsReadOnly: 264, epGate: 264, epGateLate: 7, seals: 277 },
    progression: { secondRingGate: "DN_LIGA_CLEARED (sw920)", secondRingVariableGate: null },
  };

  if (!VERIFY) {
    const hub = writeMap(HUB_ID, hudEvents);
    const cave = writeMap(CAVE_ID, caveGate);
    const data = JSON.parse(fs.readFileSync(EVENTS, "utf8"));
    data.hubMap = summary.hub;
    data.hubCave = summary.cave;
    if (!DRY) fs.writeFileSync(EVENTS, JSON.stringify(data, null, 2) + "\n");
    console.log(`Antesala ${HUB_ID}: ${hub.added.length} eventos (${hub.removed} reemplazados)`);
    for (const e of hub.added) console.log(`  ${e.name} @ ${e.x},${e.y}`);
    console.log(`Gruta ${CAVE_ID}: ${cave.added.length} eventos (${cave.removed} reemplazados)`);
    for (const e of cave.added) console.log(`  ${e.name} @ ${e.x},${e.y}`);
  } else {
    const failures = [];
    const ok = (cond, msg) => { if (!cond) failures.push(msg); };
    const data = JSON.parse(fs.readFileSync(EVENTS, "utf8"));
    ok(!!data.hubMap, "events_built.json: falta hubMap (corre `npm run dn:hub:events`)");
    const hub = grid(HUB_ID);
    const names = hub.events.map((e) => e.name);
    const readOnlyV264Events = [
      [HUB_ID, hub.events],
      [CAVE_ID, grid(CAVE_ID).events.filter((e) => e.name === "HUB_GRIETA_CAVE")],
    ];
    for (const [mapId, ownedEvents] of readOnlyV264Events) {
      for (const ev of ownedEvents) {
        for (const pg of ev.obj.getIvar("@pages") ?? []) {
          for (const command of pg.getIvar("@list") ?? []) {
            if (command.getIvar("@code") !== 355) continue;
            const source = txt(command.getIvar("@parameters")?.[0]);
            ok(!/\$game_variables\[264\]\s*(?:=(?!=)|\+=|-=|\*=|\/=)/.test(source),
              `Map${mapId} ${ev.name}: escribe el contador v264 de Monte Silver`);
          }
        }
      }
    }
    for (const want of ["HUB_SALIDA", "HUB_ARCHIVERO", "HUB_PROGRESO", ...plan.targets.map((t) => `HUB_GRIETA_${t.key}`)]) {
      ok(names.includes(want), `Antesala ${HUB_ID}: falta el evento ${want}`);
    }
    const cave = grid(CAVE_ID);
    ok(cave.events.some((e) => e.name === "HUB_GRIETA_CAVE"), `Gruta ${CAVE_ID}: falta la grieta de entrada`);
    const find = (name) => hub.events.find((e) => e.name === name);
    const salida = find("HUB_SALIDA");
    ok(salida && !(salida.x === plan.entry[0] && salida.y === plan.entry[1]), "la salida no puede estar en la celda de llegada (bucle)");
    const pagesOf = (ev) => (ev ? ev.obj.getIvar("@pages") ?? [] : []);
    const hubReach = reachableCells(hub.pass, plan.entry);
    ok(plan.rifts.length === plan.targets.length, `sólo hay ${plan.rifts.length}/${plan.targets.length} celdas de grieta`);
    for (const name of ["HUB_SALIDA", "HUB_ARCHIVERO", "HUB_PROGRESO", ...plan.targets.map((t) => `HUB_GRIETA_${t.key}`)]) {
      const ev = find(name);
      if (ev) ok(hubReach.has(`${ev.x},${ev.y}`), `${name}: evento fuera de la ruta transitable desde la entrada`);
    }
    for (const t of plan.targets) {
      const ev = find(`HUB_GRIETA_${t.key}`);
      ok(!!ev, `falta la grieta de ${t.key}`);
      if (!ev) continue;
      const pages = pagesOf(ev);
      ok(pages.length === 2, `${t.key}: la grieta necesita página bloqueada y página abierta`);
      const open = pages[1];
      const cond = open.getIvar("@condition");
      const expectedVariable = t.requireVariable ?? (t.unlock ? [264, t.unlock] : null);
      ok((cond?.getIvar("@switch1_valid") ?? false) === !!t.requireSwitch
        && cond?.getIvar("@switch1_id") === (t.requireSwitch ?? 1),
      `${t.key}: switch de apertura distinto de ${t.requireSwitch ?? "ninguno"}`);
      ok((cond?.getIvar("@switch2_valid") ?? false) === !!t.requireSwitch2
        && cond?.getIvar("@switch2_id") === (t.requireSwitch2 ?? 1),
      `${t.key}: segundo switch de apertura distinto de ${t.requireSwitch2 ?? "ninguno"}`);
      ok((cond?.getIvar("@variable_valid") ?? false) === !!expectedVariable
        && cond?.getIvar("@variable_id") === (expectedVariable?.[0] ?? 1)
        && cond?.getIvar("@variable_value") === (expectedVariable?.[1] ?? 0),
      `${t.key}: requisito variable no coincide con el plan`);
      if (t.key === "W7") {
        ok(t.requireSwitch === 920 && expectedVariable === null,
          "W7 debe abrirse con DN_LIGA_CLEARED (sw920), sin exigir v264≥9 (contador de Monte Silver, máximo 7)");
      }
      const codes = (open.getIvar("@list") ?? []).map((c) => c.getIvar("@code"));
      ok(codes.includes(201), `${t.key}: la página abierta no transfiere`);
      const dest = (open.getIvar("@list") ?? []).find((c) => c.getIvar("@code") === 201)?.getIvar("@parameters");
      ok(dest?.[1] === t.mapId && dest?.[2] === t.cell?.[0] && dest?.[3] === t.cell?.[1],
        `${t.key}: destino (${dest?.[1]},${dest?.[2]},${dest?.[3]}) ≠ Map${t.mapId} @ ${t.cell}`);
      if (t.mapId && t.cell) {
        const destination = grid(t.mapId);
        const targetInfo = (data.maps ?? {})[String(t.mapId)];
        const targetStart = targetInfo?.entry ?? t.cell;
        const targetReach = reachableCells(destination.pass, targetStart);
        ok(targetReach.has(`${t.cell[0]},${t.cell[1]}`), `${t.key}: destino no alcanzable en Map${t.mapId} desde ${targetStart}`);
      }
    }
    const gate = cave.events.find((e) => e.name === "HUB_GRIETA_CAVE");
    const gateOpen = pagesOf(gate).slice(-1)[0];
    ok(!!gateOpen && (gateOpen.getIvar("@list") ?? []).some((c) => c.getIvar("@code") === 201), "la grieta de entrada no transfiere a la Antesala");
    const caveReach = reachableCells(cave.pass, plan.caveStart);
    ok(!!plan.caveGate && caveReach.has(`${plan.caveGate[0]},${plan.caveGate[1]}`), "la grieta de la Gruta queda aislada de la celda de llegada");
    if (gate) ok(caveReach.has(`${gate.x},${gate.y}`), "HUB_GRIETA_CAVE no se puede alcanzar en la Gruta");
    if (warnings.length) for (const w of warnings) console.log(`  aviso: ${w}`);
    console.log(`verificación del hub jugable (${hub.events.length} eventos en ${HUB_ID}, ${cave.events.length} en ${CAVE_ID})`);
    if (failures.length) { for (const f of failures) console.error(`  FALLA: ${f}`); process.exit(1); }
    console.log("verificación del hub de eventos OK");
    return;
  }

  if (warnings.length) for (const w of warnings) console.log(`  aviso: ${w}`);
  console.log(DRY ? "(dry-run: no se escribió nada)" : "hub jugable listo");
  if (RENDER) await renderHub(plan);
}

main().catch((e) => { console.error(e); process.exit(1); });#!/usr/bin/env node
/**
 * dn_build_hub_map.mjs — construye la Antesala de las Grietas (Map2040), el hub
 * del Dimensional Nightmare.
 *
 * Es el único mapa del ciclo que **no** viene de una ficha de los mosaicos: se
 * arma con tiles del juego base, tomando la mejor «ventana jugable» de la Gruta
 * de los Testigos (Map2030) — el mapa donde el GDD sitúa las grietas.
 *
 * «Mejor ventana» = el recorte de 30×24 celdas con más superficie transitable y
 * mejor conectividad (BFS desde el borde inferior). Se copian las tres capas, se
 * registra en `MapInfos` y se heredan los metadatos del 2030.
 *
 * Uso:
 *   node tools/dn_build_hub_map.mjs --find      # muestra las mejores ventanas
 *   node tools/dn_build_hub_map.mjs             # construye (dry-run si --dry-run)
 *   node tools/dn_build_hub_map.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalLoad, marshalDump, RObject, RString } from "../web/js/marshal.js";
import { parseMap, tableGet, tableToUserDef } from "../web/js/rmxp.js";
import { TileCanvas, buildMapObject, loadSourceMap, passabilityOf, reachableCells } from "./lib/map_painter.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DATA = path.join(ROOT, "pokemon_fire_ash", "Data");
const BACKUP = path.join(ROOT, "pokemon_fire_ash", "PokeModBackups", "dimensional_nightmare_maps_originals");
const BUILT_PATH = path.join(ROOT, "content", "dimensional_nightmare_maps_built.json");
const SOURCE_ID = 2030;        // Gruta de los Testigos
const HUB_ID = 2040;           // Antesala de las Grietas
const WIDTH = 30, HEIGHT = 24; // tamaño de diseño del GDD
// Ventana elegida a ojo dentro de la Gruta: una sala amplia con un recodo, apta
// para repartir las seis grietas del hub en el perímetro.
const DEFAULT_WINDOW = [38, 20];
const TITLE = "Antesala de las Grietas";
const GREEN_TILESET_PREFIX = "DN_GB_";

const argv = process.argv.slice(2);
const FIND = argv.includes("--find");
const VERIFY = argv.includes("--verify");
const DRY = argv.includes("--dry-run");
const RENDER = argv.includes("--render");
const WINDOW_TOKEN = (() => {
  const at = argv.indexOf("--window");
  return at >= 0 && argv[at + 1] ? argv[at + 1] : null;
})();                                             // "ox,oy" para fijar la ventana a mano

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => {
  if (DRY) return;
  fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value)));
};
const S = (v) => RString.fromText(String(v));

// ------------------------------------------------------------- elegir ventana
const source = loadSourceMap(SOURCE_ID);
const pass = passabilityOf(source, source.tilesetId);

/** Métricas de una ventana: superficie transitable y conectividad desde abajo. */
function scoreWindow(ox, oy) {
  let walkable = 0;
  for (let y = 0; y < HEIGHT; y++) {
    for (let x = 0; x < WIDTH; x++) if (pass.passable(ox + x, oy + y, 8)) walkable++;
  }
  // entrada: la celda transitable más cercana al centro del borde inferior de la ventana
  let entry = null;
  for (let y = HEIGHT - 1; y >= 0 && !entry; y--) {
    for (let dx = 0; dx < WIDTH && !entry; dx++) {
      for (const x of [Math.floor(WIDTH / 2) + dx, Math.floor(WIDTH / 2) - dx]) {
        if (x < 0 || x >= WIDTH) continue;
        if (pass.passable(ox + x, oy + y, 8)) { entry = [ox + x, oy + y]; break; }
      }
    }
  }
  if (!entry) return { walkable, reachable: 0, ratio: 0, entry: null };
  const reach = reachableCells(pass, entry);
  let reachable = 0;
  let isolated = 0;
  for (let y = 0; y < HEIGHT; y++) {
    for (let x = 0; x < WIDTH; x++) {
      if (!pass.passable(ox + x, oy + y, 8)) continue;
      if (reach.has(`${ox + x},${oy + y}`)) reachable++;
      else isolated++;
    }
  }
  return { walkable, reachable, isolated, ratio: walkable ? reachable / walkable : 0, entry, entryLocal: entry ? [entry[0] - ox, entry[1] - oy] : null };
}

/** Render de un recorte del mapa fuente con su tileset (para la evidencia del hub). */
async function renderWindow(tilesetId, ox, oy, width, height) {
  const tilesets = read("Tilesets.rxdata");
  const name = tilesets[tilesetId]?.getIvar("@tileset_name")?.text;
  const png = path.join(ROOT, "pokemon_fire_ash", "Graphics", "Tilesets", `${name}.png`);
  const image = await loadImage(png);
  const COLUMNS = 8, TILE = 32;
  const canvas = createCanvas(width * TILE, height * TILE);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      for (const z of [0, 1, 2]) {
        const tile = tableGet(source.table, ox + x, oy + y, z);
        if (!tile) continue;
        ctx.drawImage(image, (tile % COLUMNS) * TILE, Math.floor(tile / COLUMNS) * TILE, TILE, TILE, x * TILE, y * TILE, TILE, TILE);
      }
    }
  }
  return canvas;
}

/** Evidencia del hub: ventana de la Gruta | mapa construido | overlay de transitabilidad. */
async function renderHubComparison(hubParsed, hubPass, entry) {
  const TILE = 32;
  const window = await renderWindow(source.tilesetId, win.ox, win.oy, WIDTH, HEIGHT);
  const built = createCanvas(WIDTH * TILE, HEIGHT * TILE);
  const bctx = built.getContext("2d");
  bctx.imageSmoothingEnabled = false;
  const tilesets = read("Tilesets.rxdata");
  const name = tilesets[source.tilesetId]?.getIvar("@tileset_name")?.text;
  const image = await loadImage(path.join(ROOT, "pokemon_fire_ash", "Graphics", "Tilesets", `${name}.png`));
  for (let y = 0; y < HEIGHT; y++) {
    for (let x = 0; x < WIDTH; x++) {
      for (const z of [0, 1, 2]) {
        const tile = tableGet(hubParsed.table, x, y, z);
        if (!tile) continue;
        bctx.drawImage(image, (tile % 8) * TILE, Math.floor(tile / 8) * TILE, TILE, TILE, x * TILE, y * TILE, TILE, TILE);
      }
    }
  }
  const overlay = createCanvas(WIDTH * TILE, HEIGHT * TILE);
  const octx = overlay.getContext("2d");
  const reach = entry ? reachableCells(hubPass, entry) : new Set();
  for (let y = 0; y < HEIGHT; y++) {
    for (let x = 0; x < WIDTH; x++) {
      const walkable = hubPass.passable(x, y, 8);
      octx.fillStyle = walkable ? (reach.has(`${x},${y}`) ? "rgba(0,220,120,0.35)" : "rgba(255,200,0,0.45)") : "rgba(220,40,40,0.45)";
      octx.fillRect(x * TILE, y * TILE, TILE, TILE);
    }
  }
  const gap = 12;
  const total = createCanvas(WIDTH * TILE * 3 + gap * 4, HEIGHT * TILE + gap * 2);
  const ctx = total.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#1a1a1a";
  ctx.fillRect(0, 0, total.width, total.height);
  ctx.drawImage(window, gap, gap);
  ctx.drawImage(built, gap * 2 + WIDTH * TILE, gap);
  ctx.globalAlpha = 0.85;
  ctx.drawImage(overlay, gap * 3 + WIDTH * TILE * 2, gap);
  ctx.globalAlpha = 1;
  const dir = path.join(ROOT, "docs", "dn_referencia", "detalle");
  fs.mkdirSync(dir, { recursive: true });
  const out = path.join(dir, `${HUB_ID}_comparacion.png`);
  fs.writeFileSync(out, total.toBuffer("image/png"));
  return out;
}

function bestWindow() {
  const candidates = [];
  for (let oy = 0; oy + HEIGHT <= source.height; oy += 2) {
    for (let ox = 0; ox + WIDTH <= source.width; ox += 2) {
      const s = scoreWindow(ox, oy);
      if (s.walkable < 40) continue;                 // demasiado muro
      if (s.ratio < 0.9) continue;                   // zonas aisladas
      candidates.push({ ox, oy, ...s, score: s.walkable * s.ratio });
    }
  }
  candidates.sort((a, b) => b.score - a.score);
  return candidates;
}

/**
 * Ventana elegida: la de `DEFAULT_WINDOW` (a ojo, una sala amplia con recodo) o la
 * forzada con `--window ox,oy`. Ambas deben estar entre las candidatas jugables.
 */
function pickWindow() {
  const candidates = bestWindow();
  if (!candidates.length) return { candidates, win: null };
  if (WINDOW_TOKEN) {
    const [ox, oy] = WINDOW_TOKEN.split(",").map(Number);
    return { candidates, win: candidates.find((c) => c.ox === ox && c.oy === oy) ?? null };
  }
  return { candidates, win: candidates.find((c) => c.ox === DEFAULT_WINDOW[0] && c.oy === DEFAULT_WINDOW[1]) ?? candidates[0] };
}

if (FIND) {
  const best = bestWindow().slice(0, 10);
  console.log(`ventanas jugables en Map${SOURCE_ID} (${source.width}×${source.height}) de ${WIDTH}×${HEIGHT}:`);
  for (const c of best) {
    console.log(`  (${String(c.ox).padStart(3)},${String(c.oy).padStart(3)}) · transitables ${c.walkable} · alcanzables ${c.reachable} (${(c.ratio * 100).toFixed(0)} %)`);
  }
  if (!best.length) console.error("ninguna ventana cumple (¿tileset de la Gruta sin pasajes?)");
  process.exit(best.length ? 0 : 1);
}

/** Comprueba que el hub reproduce exactamente la ventana elegida del mapa fuente. */
function verifyFidelity(parsed) {
  const { win: win2 } = pickWindow();
  if (!win2) return true;
  let diff = 0;
  for (let y = 0; y < HEIGHT; y++) {
    for (let x = 0; x < WIDTH; x++) {
      for (const z of [0, 1, 2]) {
        if (tableGet(parsed.table, x, y, z) !== tableGet(source.table, win2.ox + x, win2.oy + y, z)) diff++;
      }
    }
  }
  console.log(`  fidelidad: ventana (${win2.ox},${win2.oy}) reproducida con ${diff} diferencias`);
  return diff === 0;
}

if (VERIFY) {
  const file = path.join(DATA, `Map${HUB_ID}.rxdata`);
  let failures = 0;
  const ok = (condition, label) => { if (!condition) { failures++; console.error(`  FALLA: ${label}`); } };
  ok(fs.existsSync(file), `falta Map${HUB_ID}.rxdata`);
  if (fs.existsSync(file)) {
    const parsed = parseMap(marshalLoad(fs.readFileSync(file)));
    ok(parsed.width === WIDTH && parsed.height === HEIGHT, `tamaño ${parsed.width}×${parsed.height} ≠ ${WIDTH}×${HEIGHT}`);
    // El contrato Game Boy clona el tileset del hub a `DN_GB_<original>` y reasigna el
    // mapa a esa copia verde; se aceptan ambos estados (con o sin `dn:gameboy`).
    const tilesets = read("Tilesets.rxdata");
    const nameOf = (id) => tilesets[id]?.getIvar("@tileset_name")?.text ?? "";
    const greenCloneName = `${GREEN_TILESET_PREFIX}TS${source.tilesetId}`;
    const greenClone = parsed.tilesetId !== source.tilesetId && nameOf(parsed.tilesetId) === greenCloneName;
    ok(parsed.tilesetId === source.tilesetId || greenClone,
      `tileset ${parsed.tilesetId} ≠ ${source.tilesetId} (ni su copia ${greenCloneName})`);
    const hubPass = passabilityOf(parsed, parsed.tilesetId);
    let walkable = 0;
    let entry = null;
    for (let y = HEIGHT - 1; y >= 0 && !entry; y--) {
      for (let x = 0; x < WIDTH; x++) if (hubPass.passable(x, y, 8)) { entry = [x, y]; break; }
    }
    for (let y = 0; y < HEIGHT; y++) for (let x = 0; x < WIDTH; x++) if (hubPass.passable(x, y, 8)) walkable++;
    ok(!!entry, "sin entrada transitable en el borde inferior");
    if (entry) {
      const reach = reachableCells(hubPass, entry);
      let reachable = 0;
      for (let y = 0; y < HEIGHT; y++) for (let x = 0; x < WIDTH; x++) if (hubPass.passable(x, y, 8) && reach.has(`${x},${y}`)) reachable++;
      ok(reachable / walkable >= 0.9, `BFS ${((reachable / walkable) * 100).toFixed(0)} % < 90 % (umbral del hub reutilizado)`);
      console.log(`  Map${HUB_ID}: ${walkable} celdas transitables · ${reachable} alcanzables desde ${entry}`);
    }
    ok(verifyFidelity(parsed), "el hub no reproduce la ventana del fuente");
    const infos = read("MapInfos.rxdata").pairs;
    ok(infos.some(([key]) => Number(key) === HUB_ID), "falta en MapInfos");
    const metadata = read("map_metadata.dat").pairs;
    ok(metadata.some(([key]) => Number(key) === HUB_ID), "falta en map_metadata.dat");
  }
  console.log(failures === 0 ? `verificación del hub OK` : `verificación del hub con ${failures} fallos`);
  process.exit(failures === 0 ? 0 : 1);
}

const picked = pickWindow();
if (!picked.win) {
  console.error(WINDOW_TOKEN
    ? `La ventana ${WINDOW_TOKEN} no es jugable (revisa --find).`
    : "No hay ventana jugable en el mapa fuente. Revisa el tileset/pasajes del 2030.");
  process.exit(1);
}
const win = picked.win;
console.log(`ventana elegida: (${win.ox},${win.oy}) · ${win.walkable} transitables · BFS ${(win.ratio * 100).toFixed(0)} %`);

// ------------------------------------------------------------- construir mapa
const canvas = new TileCanvas(WIDTH, HEIGHT, source.tilesetId);
for (let y = 0; y < HEIGHT; y++) {
  for (let x = 0; x < WIDTH; x++) {
    for (const z of [0, 1, 2]) canvas.set(x, y, z, tableGet(source.table, win.ox + x, win.oy + y, z));
  }
}
const object = buildMapObject(canvas, { bgm: "", encounterStep: 25 });

if (!DRY) {
  fs.mkdirSync(BACKUP, { recursive: true });
  for (const file of ["MapInfos.rxdata", "map_metadata.dat"]) {
    const origin = path.join(DATA, file);
    const copy = path.join(BACKUP, file);
    if (fs.existsSync(origin) && !fs.existsSync(copy)) fs.copyFileSync(origin, copy);
  }
  write(`Map${HUB_ID}.rxdata`, object);

  const infos = read("MapInfos.rxdata");
  infos.pairs = infos.pairs.filter(([key]) => Number(key) !== HUB_ID);
  infos.pairs.push([HUB_ID, new RObject("RPG::MapInfo", [
    ["@scroll_x", 320], ["@name", S(`DN ${HUB_ID} · ${TITLE}`)], ["@expanded", false],
    ["@order", 1200], ["@scroll_y", 240], ["@parent_id", SOURCE_ID],
  ])]);
  write("MapInfos.rxdata", infos);

  const metadata = read("map_metadata.dat");
  const sourceMeta = metadata.pairs.find(([id]) => Number(id) === SOURCE_ID)?.[1];
  if (sourceMeta) {
    const meta = new RObject(sourceMeta.className, sourceMeta.ivars.map(([key, value]) => [key, value]));
    meta.setIvar("id", HUB_ID);
    metadata.pairs = metadata.pairs.filter(([id]) => Number(id) !== HUB_ID);
    metadata.pairs.push([HUB_ID, meta]);
    write("map_metadata.dat", metadata);
  }

  // se registra en el catálogo de construidos (tileset reutilizado del juego base)
  const built = fs.existsSync(BUILT_PATH) ? JSON.parse(fs.readFileSync(BUILT_PATH, "utf8")) : { maps: [] };
  built.maps = built.maps.filter((m) => m.id !== HUB_ID);
  built.maps.push({
    id: HUB_ID,
    episode: "HUB",
    title: TITLE,
    primary: null,
    reusedTileset: true,
    tilesetId: source.tilesetId,
    tiles: null,
    width: WIDTH,
    height: HEIGHT,
    bfs: { entry: win.entryLocal, reachable: win.reachable, walkable: win.walkable, ratio: win.ratio },
    source: `Map${SOURCE_ID} ventana (${win.ox},${win.oy})`,
  });
  built.maps.sort((a, b) => a.id - b.id);
  built.counts = built.maps.length;
  fs.writeFileSync(BUILT_PATH, `${JSON.stringify(built, null, 2)}\n`);
}

if (RENDER && !DRY) {
  const hubParsed = parseMap(object);
  const out = await renderHubComparison(hubParsed, passabilityOf(hubParsed, source.tilesetId), win.entryLocal);
  console.log(`  evidencia → ${path.relative(ROOT, out)}`);
}

console.log(`${DRY ? "[dry-run] " : ""}Map${HUB_ID} ${TITLE} · ${WIDTH}×${HEIGHT} · tileset ${source.tilesetId} (reutilizado) · BFS ${(win.ratio * 100).toFixed(0)} %`);#!/usr/bin/env node
/**
 * dn_build_liga.mjs — Liga Oscura: el mundo final de los creepypastas (M2).
 *
 * Construye los dos mapas nuevos (ids siguientes al ciclo) con el lenguaje visual del Nexo —el
 * mundo del código— y monta el arco de Mad Pikachu:
 *
 *   2040 Antesala        HUB_LIGA_OSCURA    puerta central; se abre con las seis cartucheras (sw 917)
 *   2141 Pórtico         llegada, salida a la Antesala, custodio, eco y acceso al Coliseo
 *   2142 Coliseo         LIGA_MPIKA (máquina de etapas en v281) + cuatro LIGA_CHISPA_n
 *
 * Arco de Mad Pikachu: el Rotom escanea «NIVEL ???, fuera de rango» y se niega a calcular la
 * batalla → hay que completar las cuatro chispas del vínculo (rama Pikachu) o las cuatro marcas de
 * velocidad (rama Raichu) → **Arceus interviene y lo nivela al límite (175)** → combate final contra
 * `DN_MPIKA_150` → cierre: se salva al Pikachu y a los mundos, con la Medalla del Vínculo y su
 * cartuchera «Badges of Mad Pikachu».
 *
 * El Pórtico conserva el lenguaje de código del Nexo; el Coliseo cambia con intención a un único
 * tileset funerario original de Fire Ash. Se compone como recinto irregular y asimétrico: bóveda
 * rota, altar teal descentrado, cuatro balizas y llegada separada de la salida.
 *
 * Uso:
 *   node tools/dn_build_liga.mjs            # mapas, eventos, trainer y arte
 *   node tools/dn_build_liga.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalDump, RObject, RHash, RSymbol } from "../web/js/marshal.js";
import { tableGet } from "../web/js/rmxp.js";
import { TileCanvas, buildMapObject, passabilityOf, reachableCells } from "./lib/map_painter.mjs";
import {
  DATA, GRAPHICS, ROOT, BUILT, EVENTS, CATALOG, Sym, S, txt, mapFile, readData, writeData, readMap, writeMap,
  backup, grid, nearestFreeCell, upsertEvents, cmd, condition, graphic, page, event, texts, script,
  transfer, selfSwitch, toneLine, readJson, writeJson, parseMap,
} from "./lib/dn_rmxp.mjs";

const argv = process.argv.slice(2);
const VERIFY = argv.includes("--verify");
const RENDER = argv.includes("--render");
const DRY = argv.includes("--dry-run");

const HUB_ID = 2040;
const PORTICO_ID = 2141;
const COLISEO_ID = 2142;
const SOURCE_ID = 2139;                       // Nexo — Pasillo de Código (estilo del mundo del código)
const COLISEO_SOURCE_ID = 1165;                // Fire Ash — torre funeraria, tileset original morado/piedra
const PORTICO_W = 22, PORTICO_H = 11;
const COLISEO_W = 30, COLISEO_H = 22;
const COLISEO_ENTRY = [14, 20];                // umbral interior: evita volver al Pórtico al aparecer
const COLISEO_EXIT = [14, 21];                 // salida única del anillo, separada del umbral

const SW = { ready: 917, ligaStarted: 918, arceus: 919, cleared: 920, pikaSaved: 921 };
const VAR = { branch: 278, sparks: 279, medals: 280, stage: 281, battle: 282 };
const STAGE = { intro: 0, prueba: 1, arceus: 2, combate: 3, cierre: 4 };
// El nivel real de combate es el techo legal (175). Antes de la intervención de
// Arceus su nivel es literalmente desconocido («???», fuera de rango) y no se
// puede vencer: el Rotom se niega a calcularlo. Sólo se vuelve medible cuando
// Arceus lo devuelve al límite o cuando el vínculo sostiene la Liga Oscura.
const MADPIKA = { type: "DN_MADPIKA", label: "MAD PIKACHU", species: "PIKACHU", level: 175, nivelMostrado: "???" };

const CASES = ["DN_CASE_WHT", "DN_CASE_LSV", "DN_CASE_SNO", "DN_CASE_HYP", "DN_CASE_BLK", "DN_CASE_UNO"];
const readyCheck = `begin; $game_switches[${SW.ready}] = [${CASES.map((c) => `:${c}`).join(", ")}].all? { |i| $PokemonBag.pbHasItem?(i) }; rescue; end`;

function tilesetFile(name) {
  const dir = path.join(GRAPHICS, "Tilesets");
  const wanted = `${name}.png`.toLowerCase();
  const match = fs.readdirSync(dir).find((file) => file.toLowerCase() === wanted);
  if (!match) throw new Error(`falta Graphics/Tilesets/${name}.png (búsqueda insensible a mayúsculas)`);
  return path.join(dir, match);
}

const SENS_LIGA = toneLine([-40, -40, -40, 0], 16, "dn:ambiente");   // tono de sala (no va pegado a una transferencia)
const SENS_HUB = toneLine([0, 0, 0, 0], 16, "dn:ambiente");

// ------------------------------------------------------------------ ventanas
function bottomEntry(pass, w, h) {
  let best = null, bestD = Infinity;
  for (let x = 0; x < w; x++) {
    const d = Math.abs(x - Math.floor(w / 2));
    if (pass.passable(x, h - 1, 8) && d < bestD) { bestD = d; best = [x, h - 1]; }
  }
  return best;
}

/** Mejor ventana w×h del mapa fuente: proporción alcanzable desde su borde inferior. */
function bestWindow(source, w, h) {
  let best = null;
  for (let oy = 0; oy + h <= source.height; oy++) {
    for (let ox = 0; ox + w <= source.width; ox++) {
      const canvas = new TileCanvas(w, h, source.tilesetId);
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          for (const z of [0, 1, 2]) canvas.set(x, y, z, tableGet(source.table, ox + x, oy + y, z));
        }
      }
      const pass = passabilityOf(canvas, source.tilesetId);
      let walkable = 0;
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (pass.passable(x, y, 8)) walkable++;
      const entry = bottomEntry(pass, w, h);
      const reach = entry ? reachableCells(pass, entry).size : 0;
      const ratio = walkable ? reach / walkable : 0;
      const score = ratio * 1000 + reach;
      if (!best || score > best.score) best = { ox, oy, walkable, reach, ratio, entry, score };
    }
  }
  return best;
}

function mostCommonFloor(source, win) {
  const count = new Map();
  for (let y = 0; y < win.h; y++) {
    for (let x = 0; x < win.w; x++) {
      const tile = tableGet(source.table, win.ox + x, win.oy + y, 0);
      if (!tile) continue;
      count.set(tile, (count.get(tile) ?? 0) + 1);
    }
  }
  return [...count.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? 1343;
}

function buildPortico(source) {
  const win = bestWindow(source, PORTICO_W, PORTICO_H);
  const canvas = new TileCanvas(PORTICO_W, PORTICO_H, source.tilesetId);
  for (let y = 0; y < PORTICO_H; y++) {
    for (let x = 0; x < PORTICO_W; x++) {
      for (const z of [0, 1, 2]) canvas.set(x, y, z, tableGet(source.table, win.ox + x, win.oy + y, z));
    }
  }
  return { canvas, win };
}

/**
 * Coliseo: cámara de piedra tomada de un solo tileset original de Fire Ash (torre funeraria).
 * Se conserva la lectura pixel-art del tileset; el plano no remuestrea ni mezcla capturas: recorta
 * el santuario fuente, abre una galería lateral orgánica y talla una llegada serpenteante.
 */
function buildColiseo(source) {
  const sourcePass = passabilityOf(source, source.tilesetId);
  const floorCounts = new Map();
  for (let y = 0; y < source.height; y++) for (let x = 0; x < source.width; x++) {
    const tile = tableGet(source.table, x, y, 0);
    if (tile >= 384 && sourcePass.passable(x, y, 8)) floorCounts.set(tile, (floorCounts.get(tile) ?? 0) + 1);
  }
  const floor = [...floorCounts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
  if (!floor) throw new Error(`Map${COLISEO_SOURCE_ID}: no se pudo identificar el suelo transitable`);

  const canvas = new TileCanvas(COLISEO_W, COLISEO_H, source.tilesetId);
  const voidTile = tableGet(source.table, 0, 0, 0);
  if (sourcePass.passable(0, 0, 8)) throw new Error(`Map${COLISEO_SOURCE_ID}: el tile de vacío del borde no bloquea el movimiento`);
  canvas.fillAll(0, voidTile);
  canvas.fillAll(1, 0);
  canvas.fillAll(2, 0);
  const copyCell = (sx, sy, dx, dy) => {
    if (sx < 0 || sy < 0 || sx >= source.width || sy >= source.height) return;
    for (const z of [0, 1, 2]) canvas.set(dx, dy, z, tableGet(source.table, sx, sy, z));
  };
  const clearCell = (x, y) => {
    canvas.set(x, y, 0, floor);
    canvas.set(x, y, 1, 0);
    canvas.set(x, y, 2, 0);
  };

  // Núcleo de 25×22 sin escalar (sin estirar lápidas/columnas); el margen asimétrico queda abierto.
  for (let y = 0; y < COLISEO_H; y++) for (let x = 0; x < COLISEO_W; x++) copyCell(x - 2, y + 1, x, y);

  // Costura oriental: la escalera desemboca en una senda de anchura variable, con recodo y alcoba.
  const wing = [
    [21, 9], [22, 9], [23, 9],
    [21, 10], [22, 10], [23, 10], [24, 10],
    [21, 11], [22, 11], [23, 11], [24, 11],
    [22, 12], [23, 12], [24, 12], [25, 12], [26, 12],
    [24, 13], [25, 13], [26, 13], [27, 13],
    [26, 14], [27, 14], [28, 14], [29, 14],
    [27, 15], [28, 15],
  ];
  for (const [x, y] of wing) clearCell(x, y);

  // La escalera occidental colapsó: un borde roto asimétrico sustituye su espejo intacto.
  const collapse = [[2, 9], [3, 9], [2, 10], [3, 10], [4, 10], [2, 11], [3, 11], [4, 11], [3, 12], [4, 12], [5, 12], [4, 13]];
  for (const [x, y] of collapse) {
    canvas.set(x, y, 0, voidTile);
    canvas.set(x, y, 1, 0);
    canvas.set(x, y, 2, 0);
  }

  // Una fisura abre la bóveda por el nordeste; el resto del perímetro conserva la lectura de arco.
  for (const [x, y] of [[18, 1], [19, 1], [19, 2], [20, 2], [21, 3]]) clearCell(x, y);

  // Dos lápidas aisladas reaparecen en la alcoba, no como espejo de los hileros del santuario.
  copyCell(7, 5, 28, 13);
  copyCell(7, 5, 29, 15);

  // Senda de regreso en S: bordea el altar y corta una única hilera de sepulcros, sin calle recta.
  const procession = [[14, 21], [14, 20], [15, 19], [14, 18], [13, 17], [14, 16], [15, 15], [14, 14]];
  const carveLine = (from, to) => {
    let [x, y] = from;
    const [tx, ty] = to;
    const dx = Math.abs(tx - x), sx = x < tx ? 1 : -1;
    const dy = -Math.abs(ty - y), sy = y < ty ? 1 : -1;
    let error = dx + dy;
    while (true) {
      if (x >= 0 && y >= 0 && x < COLISEO_W && y < COLISEO_H) clearCell(x, y);
      if (x === tx && y === ty) break;
      const twice = 2 * error;
      if (twice >= dy) { error += dy; x += sx; }
      if (twice <= dx) { error += dx; y += sy; }
    }
  };
  for (let i = 0; i < procession.length - 1; i++) carveLine(procession[i], procession[i + 1]);

  // Elimina tres lápidas que repetían el espejo; el hueco irregular deja un atajo visual, no obligatorio.
  for (const [x, y] of [[9, 4], [10, 4], [21, 4], [21, 6], [22, 6], [7, 16]]) clearCell(x, y);

  const plazas = [[7, 6], [20, 5], [9, 17], [27, 13]];
  for (const [x, y] of plazas) clearCell(x, y);
  for (const [x, y] of [COLISEO_ENTRY, COLISEO_EXIT]) clearCell(x, y);

  const pass = passabilityOf(canvas, canvas.tilesetId);
  const reached = reachableCells(pass, COLISEO_ENTRY);
  for (const [x, y] of [[14, 11], ...plazas, COLISEO_EXIT]) {
    if (!reached.has(`${x},${y}`)) throw new Error(`Coliseo: ${x},${y} quedó aislado en Map${COLISEO_SOURCE_ID}`);
  }
  return { canvas, floor, plazas, source: COLISEO_SOURCE_ID };
}

// ------------------------------------------------------------------ registro de mapas
function registerMap(id, title, canvas, sourceId, parentId, entryCell = null) {
  const object = buildMapObject(canvas, { bgm: "", encounterStep: 25 });
  const parsed = { width: canvas.width, height: canvas.height };
  const pass = passabilityOf(canvas, canvas.tilesetId);
  const entry = entryCell ?? bottomEntry(pass, parsed.width, parsed.height) ?? [Math.floor(parsed.width / 2), parsed.height - 1];
  if (!pass.passable(entry[0], entry[1], 8)) throw new Error(`Map${id}: entrada ${entry} no transitable`);
  const reach = reachableCells(pass, entry).size;
  let walkable = 0;
  for (let y = 0; y < parsed.height; y++) for (let x = 0; x < parsed.width; x++) if (pass.passable(x, y, 8)) walkable++;
  if (!DRY) {
    backup(mapFile(id));
    for (const file of ["MapInfos.rxdata", "map_metadata.dat"]) backup(file);
    writeMap(id, object);
    const infos = readData("MapInfos.rxdata");
    infos.pairs = infos.pairs.filter(([key]) => Number(key) !== id);
    infos.pairs.push([id, new RObject("RPG::MapInfo", [
      ["@scroll_x", 320], ["@name", S(`DN ${id} · ${title}`)], ["@expanded", false],
      ["@order", 1300 + (id - PORTICO_ID)], ["@scroll_y", 240], ["@parent_id", parentId],
    ])]);
    writeData("MapInfos.rxdata", infos);
    const metadata = readData("map_metadata.dat");
    const sourceMeta = metadata.pairs.find(([key]) => Number(key) === sourceId)?.[1];
    if (sourceMeta) {
      const copy = new RObject(sourceMeta.className, sourceMeta.ivars.map(([key, value]) => [key, value]));
      copy.setIvar("id", id);
      metadata.pairs = metadata.pairs.filter(([key]) => Number(key) !== id);
      metadata.pairs.push([id, copy]);
      writeData("map_metadata.dat", metadata);
    }
    const built = readJson(BUILT);
    built.maps = built.maps.filter((m) => m.id !== id);
    built.maps.push({
      id, episode: "LIGA", title, primary: null, reusedTileset: true, tilesetId: canvas.tilesetId, tiles: null,
      width: parsed.width, height: parsed.height,
      bfs: { entry, reachable: reach, walkable, ratio: walkable ? reach / walkable : 0 },
      source: `Map${sourceId} · tileset funerario Fire Ash + cámara recortada y galería asimétrica`,
    });
    built.maps.sort((a, b) => a.id - b.id);
    built.counts = built.maps.length;
    writeJson(BUILT, built);
  }
  return { object, entry, reach, walkable, ratio: walkable ? reach / walkable : 0 };
}

// ------------------------------------------------------------------ arte y trainer
async function buildArt() {
  const front = path.join(GRAPHICS, "Pokemon", "Front", "PIKACHU.png");
  if (!fs.existsSync(front)) return { trainer: false, overworld: false, reason: "falta PIKACHU.png" };
  const img = await loadImage(front);
  const trainer = path.join(GRAPHICS, "Trainers", "DN_MADPIKA.png");
  const overworld = path.join(GRAPHICS, "Characters", "DN_MADPIKA.png");
  const tint = (ctx, w, h) => {
    ctx.globalCompositeOperation = "source-atop";
    ctx.fillStyle = "rgba(170, 20, 20, 0.30)";
    ctx.fillRect(0, 0, w, h);
    ctx.globalCompositeOperation = "source-over";
  };
  if (!DRY) {
    const t = createCanvas(169, 169);
    const tc = t.getContext("2d");
    tc.imageSmoothingEnabled = false;
    tc.drawImage(img, 0, 0, img.width, img.height, 24, 30, 121, 121);
    tint(tc, 169, 169);
    fs.writeFileSync(trainer, t.toBuffer("image/png"));

    const frame = 48;
    const sheet = createCanvas(frame * 4, frame * 4);
    const sc = sheet.getContext("2d");
    sc.imageSmoothingEnabled = false;
    for (let y = 0; y < 4; y++) {
      for (let x = 0; x < 4; x++) {
        const cell = createCanvas(frame, frame);
        const cc = cell.getContext("2d");
        cc.imageSmoothingEnabled = false;
        const shift = x % 2 === 1 ? 1 : 0;
        cc.drawImage(img, 0, 0, img.width, img.height, 4, 2 + shift, frame - 8, frame - 8);
        tint(cc, frame, frame);
        sc.drawImage(cell, x * frame, y * frame);
      }
    }
    fs.writeFileSync(overworld, sheet.toBuffer("image/png"));
  }
  return { trainer: true, overworld: true };
}

function installTrainerType() {
  const tt = readData("trainer_types.dat");
  if (tt.pairs.some(([key]) => txt(key) === MADPIKA.type)) return { added: false };
  const [, base] = tt.pairs.find(([key]) => txt(key) === "GENTLEMAN") ?? [];
  if (!base) throw new Error("no existe GENTLEMAN en trainer_types.dat");
  const clone = new RObject(base.className, base.ivars.map(([key, value]) => [key, value]));
  const numbers = tt.pairs.map(([, value]) => value.getIvar("@id_number")).filter((n) => typeof n === "number");
  clone.setIvar("@id", Sym(MADPIKA.type));
  clone.setIvar("@id_number", Math.max(-1, ...numbers) + 1);
  clone.setIvar("@real_name", S("Mad Pikachu"));
  clone.setIvar("@base_money", 255);
  tt.pairs.push([Sym(MADPIKA.type), clone]);
  backup("trainer_types.dat");
  if (!DRY) writeData("trainer_types.dat", tt);
  return { added: true };
}

function pokemonHash({ species, level }) {
  return new RHash([[Sym("species"), Sym(species)], [Sym("level"), level]]);
}

function installTrainer() {
  const trainers = readData("trainers.dat");
  const previo = trainers.pairs.find(([key]) => Array.isArray(key) && txt(key[1]) === MADPIKA.label);
  if (previo) {
    // El techo legal subió de 150 a 175: Mad Pikachu pelea al nuevo límite.
    // Sin esta migración el entrenador se queda con el nivel de la instalación
    // anterior y la verificación lo rechaza.
    const porNombre = (a, b) => txt(a) === txt(b);
    let cambiado = false;
    for (const mon of (previo[1].getIvar("@pokemon") ?? [])) {
      if (mon && mon.get && mon.get(Sym("level"), porNombre) !== MADPIKA.level) {
        mon.set(Sym("level"), MADPIKA.level, porNombre);
        cambiado = true;
      }
    }
    if (cambiado) {
      backup("trainers.dat");
      if (!DRY) writeData("trainers.dat", trainers);
      return { added: false, migrado: true };
    }
    return { added: false };
  }
  const next = Math.max(-1, ...trainers.pairs.filter(([key]) => typeof key === "number").map(([key]) => key)) + 1;
  const key = [Sym(MADPIKA.type), S(MADPIKA.label), 0];
  const obj = new RObject("GameData::Trainer", [
    ["@id", key], ["@id_number", next], ["@trainer_type", key[0]],
    ["@real_name", S(MADPIKA.label)], ["@version", 0], ["@items", [Sym("FULLRESTORE")]],
    ["@real_lose_text", S("...el vínculo aguanta.")], ["@numpkmn", 0], ["@guara", 0],
    ["@pokemon", [pokemonHash(MADPIKA)]],
  ]);
  trainers.pairs.push([next, obj], [key, obj]);
  backup("trainers.dat");
  if (!DRY) writeData("trainers.dat", trainers);
  return { added: true, idNumber: next };
}

// ------------------------------------------------------------------ eventos
/** Celda libre alcanzable dentro de un mapa nuevo (se planifica sobre el canvas, sin eventos). */
function freeFromCanvas(canvas, from, maxDistance = 10) {
  const pass = passabilityOf(canvas, canvas.tilesetId);
  const entry = bottomEntry(pass, canvas.width, canvas.height) ?? [Math.floor(canvas.width / 2), canvas.height - 1];
  const reach = reachableCells(pass, entry);
  const empty = { width: canvas.width, height: canvas.height, occupied: new Set(), pass };
  return nearestFreeCell(empty, from, { maxDistance, allowed: reach });
}

function buildPorticoEvents(baseId, plan) {
  const events = [];
  let id = baseId;
  events.push(event(id++, "LIGA_LLEGADA", plan.entry[0], plan.entry[1], [
    page({ list: [...texts(["Liga Oscura — Pórtico del Código.", "Vienes de la Antesala. Aquí se juntan las seis firmas, y una más."]), script(SENS_LIGA), cmd(0)] }),
  ]));
  events.push(event(id++, "LIGA_CUSTODIO", plan.custodio[0], plan.custodio[1], [
    page({
      cond: condition({ sw: SW.cleared }),
      gfx: graphic("trchar000", 2, 1),
      list: [...texts(["Custodio: el pulso volvió a su sitio.", "Los mundos respiran. Mad Pikachu te espera en la Antesala, ya sin tormenta."]), cmd(0)],
    }),
    page({
      gfx: graphic("trchar000", 2, 1),
      list: [...texts([
        "Custodio: aquí llegan los que cierran mundos, no los que ganan batallas.",
        "Arriba está el Coliseo. Lo que vive ahí no se mide en niveles normales.",
        "Si llevas un Pikachu, escúchalo antes de atacar. Si llevas un Raichu, ni lo intentes: corre.",
      ]), cmd(0)],
    }),
  ]));
  events.push(event(id++, "LIGA_ECO", plan.eco[0], plan.eco[1], [
    page({
      gfx: graphic("UNOWN", 2, 1, { hue: 200, opacity: 140 }),
      list: [...texts(["Un eco repite tu último paso.", "Después repite el de otra persona. Después el de nadie."]), cmd(0)],
    }),
  ]));
  events.push(event(id++, "LIGA_ACCESO_COLISEO", plan.acceso[0], plan.acceso[1], [
    page({ gfx: graphic("Object ball special", 2, 1), trigger: 1, list: [...texts(["La puerta del Coliseo cede."]), transfer(COLISEO_ID, plan.coliseoEntry[0], plan.coliseoEntry[1], 8), cmd(0)] }),
  ]));
  events.push(event(id++, "LIGA_SALIDA", plan.salida[0], plan.salida[1], [
    page({ gfx: graphic("Object ball special", 2, 1), trigger: 1, list: [...texts(["Vuelves a la Antesala de las Grietas."]), script(SENS_HUB), transfer(HUB_ID, plan.hubCell[0], plan.hubCell[1], 8), cmd(0)] }),
  ]));
  return events;
}

/** Un paso de la prueba: cuenta la chispa y, con las cuatro, llama a Arceus. */
function sparkEvent(id, name, cell, index, branch) {
  return event(id, name, cell[0], cell[1], [
    page({
      cond: condition({ self: "A" }),
      gfx: graphic("Object ball special", 2, 1, { opacity: 90 }),
      list: [...texts(["La chispa ya está contigo."]), cmd(0)],
    }),
    page({
      gfx: graphic("Object ball special", 2, 1, { hue: 32 + index * 24 }),
      list: [
        script([
          "begin",
          `  $game_variables[${VAR.sparks}] = [$game_variables[${VAR.sparks}] + 1, 4].min`,
          `  $game_variables[${VAR.stage}] = ${STAGE.arceus} if $game_variables[${VAR.sparks}] >= 4`,
          "rescue",
          "end",
        ].join("\n")),
        ...texts([
          branch === 2
            ? `Marca de velocidad ${index + 1}: la alcanzas por un pelo.`
            : `Chispa del vínculo ${index + 1}: el Coliseo se sostiene un poco más.`,
          "Rotom: «Quedan #{$game_variables[279]} de 4 chispas.»",
        ]),
        selfSwitch("A"),
        cmd(0),
      ],
    }),
  ]);
}

function buildColiseoEvents(baseId, plan) {
  const events = [];
  let id = baseId;
  events.push(event(id++, "LIGA_ENTRADA_COLISEO", plan.entry[0], plan.entry[1], [
    page({ list: [...texts(["Coliseo del Vínculo.", "El suelo tiembla al ritmo de algo que corre sin parar."]), script(SENS_LIGA), cmd(0)] }),
  ]));
  events.push(event(id++, "LIGA_MPIKA", plan.mpika[0], plan.mpika[1], [
    page({
      cond: condition({ variable: [VAR.stage, STAGE.intro] }),
      gfx: graphic("DN_MADPIKA", 2, 1),
      list: [
        script(SENS_LIGA),
        ...texts([
          "El Coliseo se cierra. Algo pequeño se pone de pie en el centro.",
          "Rotom: «Lectura imposible. NIVEL ???. FUERA DE RANGO.»",
          "Rotom: «No puedo calcular esta batalla. No es un combate: es una tormenta.»",
          "Rotom: «Y escúchame bien: así no se puede ganar. Con ese nivel no hay",
          "golpe que valga. Sólo hay dos caminos: que ARCEUS lo devuelva al límite",
          "legal (" + MADPIKA.level + "), o sostener tú el vínculo en la Liga Oscura hasta el final.»",
        ]),
        script([
          "begin",
          "  v = 3",
          "  $Trainer.party.each do |p|",
          "    next if !p",
          "    s = p.species.to_s.upcase",
          "    v = 2 if s.include?(\"RAICHU\")",
          "    v = 1 if s.include?(\"PIKACHU\") && v != 2",
          "  end",
          `  $game_variables[${VAR.branch}] = v`,
          "rescue",
          `  $game_variables[${VAR.branch}] = 3`,
          "end",
        ].join("\n")),
        cmd(111, [0, S(`$game_variables[${VAR.branch}] == 1`)]),
        ...texts(["Mad Pikachu te mira y baja la guardia un instante.", "Rotom: «Reconoce a los suyos. Quiere medir el vínculo, no la fuerza.»"], 1),
        cmd(411, [], 1),
        cmd(111, [0, S(`$game_variables[${VAR.branch}] == 2`)], 1),
        ...texts(["Mad Pikachu no duda ni un segundo: ya está encima de ti.", "Rotom: «Su velocidad es imparable. Aquí no se gana por fuerza: hay que sostener el vínculo.»"], 2),
        cmd(411, [], 2),
        ...texts(["Mad Pikachu te estudia como si fueras código.", "Rotom: «No hay Pikachu ni Raichu en el equipo. Aun así, quiere verte intentarlo.»"], 2),
        cmd(412, [], 1),
        cmd(412, [], 0),
        ...texts(["Cuatro chispas del vínculo sostienen el Coliseo.", "Si se apagan, la tormenta se lleva el mundo entero."]),
        script([`begin; $game_variables[${VAR.stage}] = ${STAGE.prueba}; $game_switches[${SW.ligaStarted}] = true; rescue; end`].join("\n")),
        cmd(0),
      ].flat(),
    }),
    page({
      cond: condition({ variable: [VAR.stage, STAGE.prueba] }),
      gfx: graphic("DN_MADPIKA", 2, 1),
      list: [...texts(["Rotom: «Chispas del vínculo: #{$game_variables[279]}/4.»", "Mad Pikachu espera, recorriendo el Coliseo en círculos imposibles."]), cmd(0)],
    }),
    page({
      cond: condition({ variable: [VAR.stage, STAGE.arceus] }),
      gfx: graphic("DN_MADPIKA", 2, 1),
      list: [
        script(toneLine([240, 240, 255, 0], 8, "dn:ambiente")),
        ...texts([
          "Las cuatro chispas se alinean y el Coliseo se queda en silencio.",
          "Una luz original baja por el centro: ARCEUS.",
          "ARCEUS: «Un nivel que no existe no puede sostener un mundo.»",
          `ARCEUS: «Se te devuelve al límite: ${MADPIKA.level}. Ahora el vínculo sí puede medirse.»`,
        ]),
        script([`begin; $game_switches[${SW.arceus}] = true; $game_variables[${VAR.stage}] = ${STAGE.combate}; rescue; end`].join("\n")),
        script(toneLine([-40, -40, -40, 0], 16, "dn:ambiente")),
        cmd(0),
      ],
    }),
    page({
      cond: condition({ variable: [VAR.stage, STAGE.combate] }),
      gfx: graphic("DN_MADPIKA", 2, 1),
      list: [
        ...texts(["Mad Pikachu baja al suelo. Ahora se puede pelear."]),
        script([
          "begin",
          `  $game_variables[${VAR.battle}] = pbTrainerBattle(PBTrainer.new("${MADPIKA.type}", "${MADPIKA.label}"), false, "", true) ? 1 : 0`,
          "rescue",
          `  $game_variables[${VAR.battle}] = 0`,
          "end",
        ].join("\n")),
        cmd(111, [0, S(`$game_variables[${VAR.battle}] == 1`)]),
        ...texts([
          "Mad Pikachu cae de rodillas, agotado, sin entender por qué ya no puede correr.",
          "Rotom: «No lo debilita el golpe: lo sostiene el vínculo.»",
          "El Coliseo se apaga. Los seis mundos respiran.",
          "Rotom: «Medalla del Vínculo obtenida. Cartuchera: Badges of Mad Pikachu.»",
        ], 1),
        script([`begin; pbReceiveItem(:DN_MEDAL_MPK); pbReceiveItem(:DN_CASE_MPK); $game_switches[${SW.cleared}] = true; $game_switches[${SW.pikaSaved}] = true; $game_variables[${VAR.stage}] = ${STAGE.cierre}; rescue; pbMessage("(medalla de la Liga pendiente de registrar)"); end`].join("\n"), 1),
        cmd(412, [], 0),
        cmd(111, [0, S(`$game_variables[${VAR.battle}] == 0`)]),
        ...texts(["Mad Pikachu te devuelve al Pórtico con un empujón de estática.", "Rotom: «El vínculo aguantó, pero no alcanzó. Inténtalo otra vez.»"], 1),
        transfer(PORTICO_ID, plan.porticoEntry[0], plan.porticoEntry[1], 8, 1),
        cmd(412, [], 0),
        cmd(0),
      ].flat(),
    }),
    page({
      cond: condition({ variable: [VAR.stage, STAGE.cierre] }),
      gfx: graphic("DN_MADPIKA", 2, 1),
      list: [...texts(["Mad Pikachu duerme en el centro del Coliseo.", "Ya no hay tormenta: los mundos creepypasta quedaron atrás."]), cmd(0)],
    }),
  ]));
  plan.sparks.forEach((cell, index) => {
    events.push(sparkEvent(id++, `LIGA_CHISPA_${index + 1}`, cell, index, plan.branch));
  });
  events.push(event(id++, "LIGA_SALIDA_COLISEO", plan.salida[0], plan.salida[1], [
    page({ gfx: graphic("Object ball special", 2, 1), trigger: 1, list: [...texts(["Bajas de nuevo al Pórtico."]), transfer(PORTICO_ID, plan.porticoEntry[0], plan.porticoEntry[1], 8), cmd(0)] }),
  ]));
  return events;
}

/** Puerta central de la Antesala: sólo se abre con las seis cartucheras. */
function buildHubGate(plan) {
  return [
    event(plan.id, "HUB_LIGA_OSCURA", plan.cell[0], plan.cell[1], [
      page({
        cond: condition({ sw: SW.ready }),
        gfx: graphic("Object ball special", 2, 1, { hue: 300 }),
        trigger: 1,
        list: [...texts(["La puerta de la Liga Oscura se abre.", "Seis firmas sostienen el mundo del código."]), script(SENS_LIGA), transfer(PORTICO_ID, plan.porticoEntry[0], plan.porticoEntry[1], 8), cmd(0)],
      }),
      page({
        gfx: graphic("Object ball special", 2, 1, { hue: 300, opacity: 160 }),
        list: [
          script(readyCheck),
          ...texts(["Una puerta de código espera las seis firmas.", "Rotom: «Cartucheras listas para la Liga: comprueba la Antesala.»"]),
          script('pbMessage("Rotom: «Cartucheras: #{(1..6).count { |i| $PokemonBag.pbHasItem?([:DN_CASE_WHT, :DN_CASE_LSV, :DN_CASE_SNO, :DN_CASE_HYP, :DN_CASE_BLK, :DN_CASE_UNO][i-1]) }} de 6.»")'),
          cmd(0),
        ],
      }),
    ]),
  ];
}

// ------------------------------------------------------------------ plan y escritura
async function buildPlan() {
  const source = parseMap(readMap(SOURCE_ID));
  const coliseoSource = parseMap(readMap(COLISEO_SOURCE_ID));
  const built = readJson(BUILT);
  const hubMeta = built.maps.find((m) => m.id === HUB_ID);
  const hubCell = readJson(EVENTS).hubMap?.entry ?? hubMeta?.bfs?.entry ?? [15, 22];

  const portico = buildPortico(source);
  const coliseo = buildColiseo(coliseoSource);
  const regPortico = registerMap(PORTICO_ID, "Liga Oscura — Pórtico del Código", portico.canvas, SOURCE_ID, 2140);
  const regColiseo = registerMap(COLISEO_ID, "Liga Oscura — Coliseo del Vínculo", coliseo.canvas, COLISEO_SOURCE_ID, PORTICO_ID, COLISEO_ENTRY);

  const pEntry = regPortico.entry;
  const cEntry = regColiseo.entry;
  const pAccess = { cell: freeFromCanvas(portico.canvas, [Math.floor(PORTICO_W / 2), 0], 8) };
  const pCustodio = { cell: freeFromCanvas(portico.canvas, [Math.floor(PORTICO_W / 2) - 5, Math.floor(PORTICO_H / 2)], 8) };
  const pEco = { cell: freeFromCanvas(portico.canvas, [Math.floor(PORTICO_W / 2) + 5, Math.floor(PORTICO_H / 2)], 8) };
  const pSalida = { cell: freeFromCanvas(portico.canvas, [3, PORTICO_H - 1], 6) };

  const cMpika = { cell: [14, 11] };                // sobre el sello teal central de la bóveda
  const cSparks = coliseo.plazas.map((cell) => cell);
  const cSalida = { cell: [14, COLISEO_H - 1] };   // puerta inferior, junto a la llegada

  const hub = grid(HUB_ID);
  const hubReach = reachableCells(hub.pass, hubGateEntry(hub));
  const gateCell = nearestFreeCell(hub, [Math.floor(hub.width / 2), Math.floor(hub.height / 2)], { maxDistance: 10, allowed: hubReach });

  return { source, portico, coliseo, regPortico, regColiseo, hubCell, hub, gateCell,
    pEntry, cEntry, pAccess, pCustodio, pEco, pSalida, cMpika, cSparks, cSalida };
}

function hubGateEntry(hub) {
  const built = readJson(BUILT).maps.find((m) => m.id === HUB_ID);
  return built?.bfs?.entry ?? [Math.floor(hub.width / 2), hub.height - 2];
}

// ------------------------------------------------------------------ render
async function renderLiga(plan) {
  const { createCanvas, loadImage } = await import("@napi-rs/canvas");
  const { tableGet } = await import("../web/js/rmxp.js");
  const S = 32, Z = 2, BASE = 384;
  const tilesets = readData("Tilesets.rxdata");
  const panels = [];
  const marks = {
    [PORTICO_ID]: [
      [plan.pEntry, "#2ecc71", "E"], [plan.pSalida.cell, "#3d7bff", "S"],
      [plan.pAccess.cell, "#ffd23d", "C"], [plan.pCustodio.cell, "#ff8ad8", "N"], [plan.pEco.cell, "#b06ad8", "e"],
    ],
    [COLISEO_ID]: [
      [plan.cEntry, "#2ecc71", "E"], [plan.cMpika.cell, "#ff3b30", "M"],
      ...plan.cSparks.map((cell, i) => [cell, "#00d0ff", String(i + 1)]),
      [plan.cSalida.cell, "#3d7bff", "S"],
    ],
  };
  for (const id of [PORTICO_ID, COLISEO_ID]) {
    const map = parseMap(readMap(id));
    const width = map.width, height = map.height;
    const tilesetId = map.tilesetId;
    const name = tilesets[tilesetId]?.getIvar("@tileset_name")?.text;
    const img = await loadImage(tilesetFile(name));
    const cols = Math.max(1, Math.floor(img.width / S));
    const canvas = createCanvas(width * S * Z, height * S * Z);
    const ctx = canvas.getContext("2d");
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = "#101418";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        for (let z = 0; z < 3; z++) {
          const tile = tableGet(map.table, x, y, z);
          if (!tile || tile < BASE) continue;
          const k = tile - BASE;
          ctx.drawImage(img, (k % cols) * S, Math.floor(k / cols) * S, S, S, x * S * Z, y * S * Z, S * Z, S * Z);
        }
      }
    }
    for (const [cell, color, label] of marks[id]) {
      if (!cell) continue;
      const cx = cell[0] * S * Z + S, cy = cell[1] * S * Z + S;
      ctx.beginPath(); ctx.arc(cx, cy, S * Z * 0.42, 0, Math.PI * 2);
      ctx.fillStyle = color; ctx.globalAlpha = 0.85; ctx.fill(); ctx.globalAlpha = 1;
      ctx.lineWidth = 2; ctx.strokeStyle = "#101418"; ctx.stroke();
      ctx.font = `bold ${Math.round(S * Z * 0.5)}px sans-serif`;
      ctx.fillStyle = "#101418"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText(label, cx, cy + 1);
    }
    panels.push({ canvas, label: `${id}` });
  }
  const gap = 24, labelH = 34;
  const total = createCanvas(Math.max(...panels.map((p) => p.canvas.width)) , panels.reduce((sum, p) => sum + p.canvas.height + labelH, 0) + gap);
  const octx = total.getContext("2d");
  octx.fillStyle = "#1b1f24";
  octx.fillRect(0, 0, total.width, total.height);
  let y = labelH / 2;
  for (const panel of panels) {
    octx.fillStyle = "#e8e8e8";
    octx.font = "bold 20px sans-serif";
    octx.textAlign = "left";
    octx.fillText(`Map${panel.label} — Liga Oscura`, 12, y + 8);
    y += labelH;
    octx.drawImage(panel.canvas, 0, y);
    y += panel.canvas.height + gap / 2;
  }
  const out = path.join(ROOT, "docs", "dn_referencia", "lotes", "LIGA_2141_2142.png");
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, total.toBuffer("image/png"));
  console.log(`render: ${path.relative(ROOT, out)}`);
}

// ------------------------------------------------------------------ verificación
function axisMismatch(map, axis) {
  let mismatch = 0, total = 0;
  for (let y = 0; y < map.height; y++) for (let x = 0; x < map.width; x++) {
    const ox = axis === "x" ? map.width - 1 - x : x;
    const oy = axis === "y" ? map.height - 1 - y : y;
    if (y * map.width + x >= oy * map.width + ox) continue;
    total++;
    if (tableGet(map.table, x, y, 0) !== tableGet(map.table, ox, oy, 0)) mismatch++;
  }
  return total ? mismatch / total : 0;
}

function verify() {
  const failures = [];
  const ok = (cond, msg) => { if (!cond) failures.push(msg); };
  const built = readJson(BUILT);
  for (const [id, w, h] of [[PORTICO_ID, PORTICO_W, PORTICO_H], [COLISEO_ID, COLISEO_W, COLISEO_H]]) {
    const meta = built.maps.find((m) => m.id === id);
    ok(!!meta, `falta el mapa ${id} en el catálogo de construidos`);
    if (!meta) continue;
    const file = path.join(DATA, mapFile(id));
    ok(fs.existsSync(file), `falta ${mapFile(id)}`);
    const map = readMap(id);
    const parsed = { width: map.getIvar("@width"), height: map.getIvar("@height") };
    ok(parsed.width === w && parsed.height === h, `${id}: tamaño ${parsed.width}×${parsed.height} ≠ ${w}×${h}`);
    ok(readData("MapInfos.rxdata").pairs.some(([key]) => Number(key) === id), `${id}: falta en MapInfos`);
    ok(readData("map_metadata.dat").pairs.some(([key]) => Number(key) === id), `${id}: falta en map_metadata.dat`);
    const g = grid(id);
    ok((meta.bfs?.ratio ?? 0) >= 0.9, `${id}: BFS ${((meta.bfs?.ratio ?? 0) * 100).toFixed(0)} % (< 90 %)`);
    ok(g.events.length > 0, `${id}: sin eventos`);
    if (id === COLISEO_ID) {
      const horizontal = axisMismatch(g.parsed, "x");
      const vertical = axisMismatch(g.parsed, "y");
      ok(horizontal > 0.12 && vertical > 0.12, `${id}: composición demasiado simétrica (X ${(horizontal * 100).toFixed(0)} %, Y ${(vertical * 100).toFixed(0)} %)`);
      const entry = meta.bfs?.entry ?? COLISEO_ENTRY;
      const reached = reachableCells(g.pass, entry);
      for (const name of ["LIGA_ENTRADA_COLISEO", "LIGA_MPIKA", "LIGA_CHISPA_1", "LIGA_CHISPA_2", "LIGA_CHISPA_3", "LIGA_CHISPA_4", "LIGA_SALIDA_COLISEO"]) {
        const point = g.events.find((e) => e.name === name);
        ok(!!point, `Coliseo: falta ${name}`);
        if (point) ok(reached.has(`${point.x},${point.y}`), `Coliseo: ${name} no es alcanzable desde ${entry}`);
      }
      const exit = g.events.find((e) => e.name === "LIGA_SALIDA_COLISEO");
      ok(!exit || entry[0] !== exit.x || entry[1] !== exit.y, "Coliseo: la llegada coincide con el evento de salida (transferencia de retorno inmediata)");
    }
  }
  const portico = grid(PORTICO_ID);
  for (const name of ["LIGA_LLEGADA", "LIGA_CUSTODIO", "LIGA_ECO", "LIGA_ACCESO_COLISEO", "LIGA_SALIDA"]) {
    ok(portico.events.some((e) => e.name === name), `Pórtico ${PORTICO_ID}: falta ${name}`);
  }
  const coliseo = grid(COLISEO_ID);
  for (const name of ["LIGA_ENTRADA_COLISEO", "LIGA_MPIKA", "LIGA_CHISPA_1", "LIGA_CHISPA_2", "LIGA_CHISPA_3", "LIGA_CHISPA_4", "LIGA_SALIDA_COLISEO"]) {
    ok(coliseo.events.some((e) => e.name === name), `Coliseo ${COLISEO_ID}: falta ${name}`);
  }
  const mpika = coliseo.events.find((e) => e.name === "LIGA_MPIKA");
  ok(!!mpika && mpika.pages.length === 5, "LIGA_MPIKA: hacen falta 5 etapas (intro · prueba · Arceus · combate · cierre)");
  const stageOf = (pageObj) => pageObj?.getIvar("@condition")?.getIvar("@variable_value");
  const textsOf = (pageObj) => JSON.stringify((pageObj?.getIvar("@list") ?? []).map((c) => (c.getIvar("@parameters") ?? []).map((p) => txt(p)).join(" ")));
  if (mpika) {
    ok(stageOf(mpika.pages[2]) === STAGE.arceus, "LIGA_MPIKA: la etapa de Arceus no está en la página correcta");
    ok(textsOf(mpika.pages[2]).includes("ARCEUS"), "LIGA_MPIKA: la escena de Arceus no lo nombra");
    ok(textsOf(mpika.pages[2]).includes(String(MADPIKA.level)), `LIGA_MPIKA: Arceus no nivela a ${MADPIKA.level}`);
    ok(textsOf(mpika.pages[2]).includes(`[${SW.arceus}]`) || textsOf(mpika.pages[2]).includes(String(SW.arceus)), "LIGA_MPIKA: Arceus no enciende su switch");
    ok(textsOf(mpika.pages[3]).includes(`PBTrainer.new(\\"${MADPIKA.type}\\"`), "LIGA_MPIKA: el combate final no invoca al trainer de Mad Pikachu");
    ok(textsOf(mpika.pages[3]).includes("DN_MEDAL_MPK") && textsOf(mpika.pages[3]).includes("DN_CASE_MPK"), "LIGA_MPIKA: el cierre no entrega medalla y cartuchera");
    ok(textsOf(mpika.pages[0]).includes(`[${VAR.branch}]`), "LIGA_MPIKA: la intro no detecta la rama (Pikachu/Raichu)");
  }
  const sparks = coliseo.events.filter((e) => e.name.startsWith("LIGA_CHISPA_"));
  ok(sparks.length === 4, `Coliseo: ${sparks.length} chispas (se esperan 4)`);
  for (const spark of sparks) ok(spark.pages.length === 2, `${spark.name}: necesita página de recogida y de repetida`);
  // trainer y arte
  const tt = readData("trainer_types.dat");
  ok(tt.pairs.some(([key]) => txt(key) === MADPIKA.type), `trainer_types.dat: falta ${MADPIKA.type}`);
  const trainers = readData("trainers.dat");
  const rec = trainers.pairs.find(([key]) => Array.isArray(key) && txt(key[1]) === MADPIKA.label);
  ok(!!rec, `trainers.dat: falta el entrenador ${MADPIKA.label}`);
  if (rec) {
    const team = rec[1].getIvar("@pokemon") ?? [];
    ok(team.length === 1, `${MADPIKA.label}: ${team.length} Pokémon (se espera 1)`);
    const mon = team[0];
    const byName = (a, b) => txt(a) === txt(b);
    ok(txt(mon.get(Sym("species"), byName)) === MADPIKA.species, `${MADPIKA.label}: especie ≠ ${MADPIKA.species}`);
    ok(mon.get(Sym("level"), byName) === MADPIKA.level, `${MADPIKA.label}: nivel ≠ ${MADPIKA.level} (Arceus lo nivela al límite)`);
  }
  ok(fs.existsSync(path.join(GRAPHICS, "Trainers", "DN_MADPIKA.png")), "falta Graphics/Trainers/DN_MADPIKA.png");
  ok(fs.existsSync(path.join(GRAPHICS, "Characters", "DN_MADPIKA.png")), "falta Graphics/Characters/DN_MADPIKA.png");
  // puerta del hub
  const hub = grid(HUB_ID);
  const gate = hub.events.find((e) => e.name === "HUB_LIGA_OSCURA");
  ok(!!gate, `Antesala ${HUB_ID}: falta HUB_LIGA_OSCURA`);
  if (gate) {
    const open = gate.pages[0];
    ok(open.getIvar("@condition")?.getIvar("@switch1_id") === SW.ready, "HUB_LIGA_OSCURA: la apertura no depende de las seis cartucheras");
    const openText = textsOf(open);
    ok(openText.includes(String(PORTICO_ID)), "HUB_LIGA_OSCURA: no transfiere al Pórtico");
  }
  console.log(`verificación de la Liga Oscura (mapas ${PORTICO_ID}/${COLISEO_ID}, trainer ${MADPIKA.label} nv ${MADPIKA.level}, ${sparks.length} chispas)`);
  console.log(`  Pórtico BFS ${((readJson(BUILT).maps.find((m) => m.id === PORTICO_ID)?.bfs?.ratio ?? 0) * 100).toFixed(0)} % · Coliseo BFS ${((readJson(BUILT).maps.find((m) => m.id === COLISEO_ID)?.bfs?.ratio ?? 0) * 100).toFixed(0)} %`);
  if (failures.length) { for (const f of failures) console.error(`  FALLA: ${f}`); process.exit(1); }
  console.log("verificación de la Liga OK");
}

// ------------------------------------------------------------------ main
if (VERIFY) {
  verify();
} else {
  const plan = await buildPlan();
  if (!plan.gateCell || !plan.cMpika.cell || plan.cSparks.some((c) => !c)) {
    console.error("No se pudieron resolver todas las celdas del plan:", JSON.stringify({ gate: plan.gateCell, mpika: plan.cMpika.cell, sparks: plan.cSparks }));
    process.exit(1);
  }
  const porticoSpec = {
    entry: plan.pEntry, custodio: plan.pCustodio.cell, eco: plan.pEco.cell, acceso: plan.pAccess.cell, salida: plan.pSalida.cell,
    coliseoEntry: plan.cEntry, hubCell: plan.hubCell,
  };
  const coliseoSpec = { entry: plan.cEntry, mpika: plan.cMpika.cell, sparks: plan.cSparks, branch: 1, salida: plan.cSalida.cell, porticoEntry: plan.pEntry };
  const gateSpec = { id: 1, cell: plan.gateCell, porticoEntry: plan.pEntry };
  const portico = DRY
    ? { added: buildPorticoEvents(1, porticoSpec).map((e) => ({ name: txt(e.getIvar("@name")), x: e.getIvar("@x"), y: e.getIvar("@y") })) }
    : upsertEvents(PORTICO_ID, ["LIGA_LLEGADA", "LIGA_CUSTODIO", "LIGA_ECO", "LIGA_ACCESO_COLISEO", "LIGA_SALIDA"], (baseId) => buildPorticoEvents(baseId, porticoSpec), { dry: DRY });
  const coliseo = DRY
    ? { added: buildColiseoEvents(1, coliseoSpec).map((e) => ({ name: txt(e.getIvar("@name")), x: e.getIvar("@x"), y: e.getIvar("@y") })) }
    : upsertEvents(COLISEO_ID, ["LIGA_ENTRADA_COLISEO", "LIGA_MPIKA", "LIGA_CHISPA_1", "LIGA_CHISPA_2", "LIGA_CHISPA_3", "LIGA_CHISPA_4", "LIGA_SALIDA_COLISEO"], (baseId) => buildColiseoEvents(baseId, coliseoSpec), { dry: DRY });
  const gate = upsertEvents(HUB_ID, ["HUB_LIGA_OSCURA"], (baseId) => buildHubGate({ ...gateSpec, id: baseId }), { dry: DRY });
  if (!DRY) {
    const data = readJson(EVENTS);
    data.liga = {
      maps: { portico: PORTICO_ID, coliseo: COLISEO_ID },
      gate: { map: HUB_ID, event: "HUB_LIGA_OSCURA", cell: plan.gateCell },
      entry: { portico: plan.pEntry, coliseo: plan.cEntry },
      exit: { portico: plan.pSalida.cell, coliseo: plan.cSalida.cell },
      mpika: plan.cMpika.cell,
      sparks: plan.cSparks,
      switches: SW, variables: VAR, stage: STAGE,
      trainer: `${MADPIKA.type}/${MADPIKA.label} nv ${MADPIKA.level}`,
    };
    writeJson(EVENTS, data);
  }
  const art = await buildArt();
  const type = installTrainerType();
  const trainer = installTrainer();
  console.log(`Liga Oscura: Map${PORTICO_ID} ${PORTICO_W}×${PORTICO_H} (BFS ${(plan.regPortico.ratio * 100).toFixed(0)} %, ventana ${plan.portico.win.ox},${plan.portico.win.oy})`);
  console.log(`  Map${COLISEO_ID} ${COLISEO_W}×${COLISEO_H} (BFS ${(plan.regColiseo.ratio * 100).toFixed(0)} %, planta orgánica asimétrica, entrada interior ${COLISEO_ENTRY.join(",")} / salida ${COLISEO_EXIT.join(",")})`);
  console.log(`  eventos: Pórtico ${portico.added.length} · Coliseo ${coliseo.added.length} · Antesala ${gate.added.length}`);
  if (DRY) for (const group of [portico, coliseo, gate]) for (const e of group.added) console.log(`    · ${e.name} @ ${e.x},${e.y}`);
  console.log(`  Mad Pikachu: tipo ${type.added ? "creado" : "ya existía"} · trainer ${trainer.added ? `#${trainer.idNumber}` : "ya existía"} · arte ${art.trainer ? "OK" : art.reason}`);
  if (RENDER) await renderLiga(plan);
}#!/usr/bin/env node
/**
 * Genera la dirección visual previa para cada mapa del Dimensional Nightmare,
 * además del resumen de dirección de arte para Monte Silver y La Ruta de Dios.
 * Aplica el flujo de Director de Diseño de Niveles Autónomo (16-bits):
 *   1. Autoselección de Variables (Bioma/Subtema, Atmósfera, Paleta)
 *   2. Estructura Orgánica (Asimetría total, rutas quebradas y relieve por alturas)
 *   3. Detalle y Decoración / Clutter (4–6 elementos específicos por mapa)
 *   4. Servicios urbanos por contexto (Centro Pokémon y Tienda explícitos en ciudades)
 * Uso: node tools/dn_build_visual_plan.mjs [--check]
 */
