  const tiles = [];                  // { index, hash, uses, blank }
  const maps = [];
  for (const entry of entries) {
    const px = prepareSlice(entry);
    const cols = Math.floor(px.width / TILE);
    const rows = Math.floor(px.height / TILE);
    const matrix = [];
    for (let r = 0; r < rows; r++) {
      const row = [];
      for (let c = 0; c < cols; c++) {
        const x0 = c * TILE;
