  // Puntúa cada par (recurso, archivo) y asigna de mayor a menor: evita que
  // «4 EL TRONO DEL REY UNOWN» caiga en R3 por la palabra "rey".
  const scoreOf = (resource, file) => {
    const base = path.basename(file.name, path.extname(file.name)).toLowerCase();
    if (base === resource.key) return 1000;
    const n = resource.key[1];
    let score = 0;
    if (new RegExp(`^\\s*(r?0?${n})\\b`).test(base)) score += 100;
    if (base.includes(resource.key.replace(/_/g, " "))) score += 80;
    for (const token of resource.tokens) if (base.includes(token)) score += 20;
    for (const token of resource.exclude ?? []) if (base.includes(token)) score -= 200;
    return score;
  };
  const candidates = [];
  for (const resource of RESOURCES) {
    if (found.has(resource.key)) continue;
    for (const file of files) {
      if (used.has(file.full)) continue;
      const score = scoreOf(resource, file);
      if (score > 0) candidates.push({ resource, file, score });
    }
  }
  candidates.sort((a, b) => b.score - a.score);
  for (const { resource, file } of candidates) {
    if (found.has(resource.key) || used.has(file.full)) continue;
    found.set(resource.key, file);
    used.add(file.full);
  }
  const leftovers = files.filter((f) => !used.has(f.full));
  const unassigned = [];
  for (const resource of RESOURCES) {
    if (found.has(resource.key)) continue;
    const next = leftovers.shift();
    if (next) { found.set(resource.key, next); used.add(next.full); }
    else unassigned.push(resource);
  }
  return { found, files, unassigned, leftovers, mapping, unresolvedMapping };
}

// ------------------------------------------------------------------- píxeles
const luminance = (r, g, b) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

async function loadPixels(file) {
  const img = await loadImage(file);
  const canvas = createCanvas(img.width, img.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(img, 0, 0);
  const { data } = ctx.getImageData(0, 0, img.width, img.height);
  return { width: img.width, height: img.height, data, canvas, ctx };
}

/** Filas/columnas que son casi enteramente oscuras → separadores de la rejilla. */
function findSeparators(px, { dark = 40, ratio = 0.88 } = {}) {
  const { width, height, data } = px;
  const rows = [];
  const cols = [];
  for (let y = 0; y < height; y++) {
    let dark_count = 0;
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 16 || luminance(data[i], data[i + 1], data[i + 2]) < dark) dark_count++;
    }
    if (dark_count / width >= ratio) rows.push(y);
  }
  for (let x = 0; x < width; x++) {
    let dark_count = 0;
    for (let y = 0; y < height; y++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 16 || luminance(data[i], data[i + 1], data[i + 2]) < dark) dark_count++;
    }
    if (dark_count / height >= ratio) cols.push(x);
  }
  return { rows: groupRuns(rows), cols: groupRuns(cols) };
}

/** Agrupa índices contiguos en bandas [start, end]. */
function groupRuns(values) {
  const runs = [];
  for (const v of values) {
    const last = runs[runs.length - 1];
    if (last && v <= last[1] + 1) last[1] = v;
    else runs.push([v, v]);
  }
  return runs.map(([a, b]) => [a, b]);
}

/** Intervalos entre bandas (excluyendo bordes) + filtro de bandas finas (títulos/etiquetas). */
function cellsBetween(runs, total, minSize) {
  const bounds = [0, ...runs.flat(), total];
  const cells = [];
  for (let i = 0; i < bounds.length - 1; i += 2) {
    const start = i === 0 ? 0 : bounds[i] + 1;
    const end = i + 1 >= bounds.length ? total - 1 : bounds[i + 1] - 1;
    if (end - start + 1 >= minSize) cells.push([start, end]);
  }
  return cells;
}

/** Si la autodetección no cuadra, divide uniformemente. */
function uniformCells(total, count, { header = 0, footer = 0 } = {}) {
  const usable = total - header - footer;
  const size = Math.floor(usable / count);
  return Array.from({ length: count }, (_, i) => {
    const start = header + i * size;
    return [start, Math.min(header + (i + 1) * size - 1, total - 1)];
  });
}

function contentBBox(px, [x0, y0, x1, y1], { dark = 24 } = {}) {
  const { width, data } = px;
  let minX = x1, maxX = x0, minY = y1, maxY = y0;
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 16) continue;
      if (luminance(data[i], data[i + 1], data[i + 2]) > dark) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  if (minX > maxX || minY > maxY) return [x0, y0, x1, y1];
  return [minX, minY, maxX, maxY];
}

function paletteOf(px, [x0, y0, x1, y1], top = 10) {
  const { width, data } = px;
  const counts = new Map();
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 16) continue;
      const key = ((data[i] >> 4) << 8) | ((data[i + 1] >> 4) << 4) | (data[i + 2] >> 4);
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, top)
    .map(([key, count]) => {
      const hex = ((key >> 8) & 0xf) * 17, g = ((key >> 4) & 0xf) * 17, b = (key & 0xf) * 17;
      return { hex: `#${[hex, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`, count };
    });
}

function meanLuminance(px, [x0, y0, x1, y1]) {
  const { width, data } = px;
  let sum = 0, n = 0;
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const i = (y * width + x) * 4;
      if (data[i + 3] < 16) continue;
      sum += luminance(data[i], data[i + 1], data[i + 2]);
      n++;
    }
  }
  return n ? +(sum / n).toFixed(1) : 0;
}

/** Huella de 8×8 para detectar fichas repetidas entre recursos. */
function fingerprint(px, [x0, y0, x1, y1]) {
  const { width, data } = px;
  const cells = 8;
  const out = [];
  for (let cy = 0; cy < cells; cy++) {
    for (let cx = 0; cx < cells; cx++) {
      const sx = x0 + Math.floor(((x1 - x0 + 1) * cx) / cells);
      const ex = x0 + Math.floor(((x1 - x0 + 1) * (cx + 1)) / cells) - 1;
      const sy = y0 + Math.floor(((y1 - y0 + 1) * cy) / cells);
      const ey = y0 + Math.floor(((y1 - y0 + 1) * (cy + 1)) / cells) - 1;
      let sum = 0, n = 0;
      for (let y = sy; y <= Math.max(sy, ey); y++) {
        for (let x = sx; x <= Math.max(sx, ex); x++) {
          const i = (y * width + x) * 4;
          sum += luminance(data[i], data[i + 1], data[i + 2]);
          n++;
        }
      }
      out.push(Math.round((sum / Math.max(1, n)) / 16));
    }
  }
  return out.map((v) => v.toString(16)).join("");
}

/** Factor de escala entero (1–4) que haría la ficha múltiplo de 16 px. */
function scaleGuess(w, h) {
  for (const factor of [1, 2, 3, 4]) {
    if (w % factor === 0 && h % factor === 0 && (w / factor) % 16 === 0 && (h / factor) % 16 === 0) return factor;
  }
  return 1;
}

// --------------------------------------------------------------- integración
async function ingestResource(resource, file, layout) {
  if (!file) return null;
  const px = await loadPixels(file.full);
  const { rows: rowRuns, cols: colRuns } = findSeparators(px);
  const minRow = Math.floor(px.height / (resource.rows * 4));
  const minCol = Math.floor(px.width / (resource.cols * 4));
  let rowCells = cellsBetween(rowRuns, px.height, minRow);
  let colCells = cellsBetween(colRuns, px.width, minCol);
  let mode = "auto";
  if (rowCells.length !== resource.rows || colCells.length !== resource.cols) {
    rowCells = uniformCells(px.height, resource.rows, layout);
    colCells = uniformCells(px.width, resource.cols, layout);
    mode = "uniform";
  }
  const dir = path.join(SLICES, resource.key);
  fs.mkdirSync(dir, { recursive: true });

  const slices = [];
  let index = 0;
  rowCells.forEach(([cy0, cy1], row) => {
    colCells.forEach(([cx0, cx1], col) => {
      index++;
      const bbox = contentBBox(px, [cx0, cy0, cx1, cy1]);
      const w = bbox[2] - bbox[0] + 1;
      const h = bbox[3] - bbox[1] + 1;
      const canvas = createCanvas(w, h);
      const ctx = canvas.getContext("2d");
      ctx.drawImage(px.canvas, bbox[0], bbox[1], w, h, 0, 0, w, h);
      const name = `${String(index).padStart(2, "0")}.png`;
      fs.writeFileSync(path.join(dir, name), canvas.toBuffer("image/png"));
      const factor = scaleGuess(w, h);
      slices.push({
        index,
        row: row + 1,
        col: col + 1,
        file: path.relative(ROOT, path.join(dir, name)),
        width: w,
        height: h,
        scaleGuess: factor,
        tilesWide: Math.round(w / factor / 16),
        tilesHigh: Math.round(h / factor / 16),
        exact16: w % 16 === 0 && h % 16 === 0,
        luminance: meanLuminance(px, bbox),
        palette: paletteOf(px, bbox),
        fingerprint: fingerprint(px, bbox),
      });
    });
  });

  return {
    key: resource.key,
    label: resource.label,
    source: path.relative(ROOT, file.full),
    image: { width: px.width, height: px.height },
    grid: { rows: resource.rows, cols: resource.cols, mode, rowRuns: rowRuns.length, colRuns: colRuns.length },
    expects: resource.expect,
    slices,
  };
}

function reportFound({ found, files, unassigned, leftovers, mapping, unresolvedMapping }, dirs = INPUT_DIRS) {
  const home = path.relative(ROOT, dirs[0]) || "Mapas/crepypasta";
  console.log(`Carpetas de recursos: ${dirs.map((dir) => path.relative(ROOT, dir)).join(", ")}`);
  if (mapping?.file) console.log(`Asignación explícita: ${path.relative(ROOT, mapping.file)}`);
  console.log(`Archivos de imagen encontrados: ${files.length}`);
  for (const resource of RESOURCES) {
    const file = found.get(resource.key);
    const origin = file ? path.relative(ROOT, file.full) : "— falta —";
    console.log(`  ${file ? "OK " : "FALTA"} ${resource.key.padEnd(20)} ← ${origin}`);
  }
  if (unresolvedMapping?.length) {
    console.log("\nmapping.json apunta a archivos que no encuentro:");
    for (const line of unresolvedMapping) console.log(`  - ${line}`);
  }
  if (!files.length) console.log(`\nNo hay imágenes en ${dirs.map((d) => path.relative(ROOT, d)).join(" ni ")}.`);
  if (unassigned.length) {
    console.log("\nSin archivo asignado: " + unassigned.map((r) => r.key).join(", "));
    console.log("Nombra los mosaicos como indica reference/dimensional_nightmare/README.md.");
    console.log("Documento de referencia: docs/DIMENSIONAL_NIGHTMARE/12_PLAN_DE_RECREACION_DE_MAPAS.md");
    return false;
  }
  if (leftovers.length) {
    console.log(`\nAviso: ${leftovers.length} imagen(es) sin usar (¿Mapas/Atlas? se ignora en esta fase).`);
  }
  return true;
}

// ------------------------------------------------------------------ fixtures
/** Genera 7 mosaicos sintéticos con la rejilla real de cada recurso (para probar el pipeline). */
function generateFixtures() {
  fs.mkdirSync(FIXTURES, { recursive: true });
  const CELL = 96, GAP = 8, HEADER = 48;
  const defs = [
    ["r1_glitch_city.png", 4, 4, "GLITCH CITY COMPILATION"],
    ["r2_dark_forest.png", 4, 4, "CREEPY DARK FOREST"],
    ["r3_king_unown.png", 1, 1, "KING UNOWN"],
    ["r4_trono_unown.png", 4, 4, "EL TRONO DEL REY UNOWN"],
    ["r5_pueblos_tumbas.png", 4, 4, "PUEBLOS Y TUMBAS"],
    ["r6_snowy_mountain.png", 5, 3, "CREEPY SNOWY MOUNTAIN"],
    ["r7_catacumbas.png", 4, 4, "CATACUMBAS DE LAVANDA"],
  ];
  for (const [name, cols, rows, title] of defs) {
    const w = cols * CELL + (cols + 1) * GAP;
    const h = HEADER + rows * CELL + (rows + 1) * GAP;
    const canvas = createCanvas(w, h);
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = "#fff";
    ctx.font = "22px sans-serif";
    ctx.fillText(title, 12, 30);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const px = GAP + c * (CELL + GAP);
        const py = HEADER + GAP + r * (CELL + GAP);
        ctx.fillStyle = `rgb(${30 + r * 35},${70 + c * 30},${110 + ((r + c) % 3) * 30})`;
        ctx.fillRect(px, py, CELL, CELL);
        ctx.fillStyle = "#e8e8d0";
        ctx.fillRect(px + 10, py + 10, 20, 20);
        ctx.fillRect(px + 60, py + 60, 18, 18);
      }
    }
    fs.writeFileSync(path.join(FIXTURES, name), canvas.toBuffer("image/png"));
  }
  console.log(`fixtures: ${defs.length} mosaicos sintéticos → ${path.relative(ROOT, FIXTURES)}/`);
}

// ------------------------------------------------------------------ selftest
async function selftest() {
  const cell = 64, gap = 6, header = 40, cols = 4, rows = 4;
  const width = cols * cell + (cols + 1) * gap;
  const height = header + rows * cell + (rows + 1) * gap;
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = "#ffffff";
  ctx.font = "16px sans-serif";
  ctx.fillText("SELFTEST", 10, 24);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = gap + c * (cell + gap);
      const y = header + gap + r * (cell + gap);
      ctx.fillStyle = `rgb(${40 + r * 40}, ${90 + c * 30}, ${120 + r * 20})`;
      ctx.fillRect(x, y, cell, cell);
      ctx.fillStyle = "#f0f0f0";
      ctx.fillRect(x + 8, y + 8, 12, 12);
    }
  }
  const fixture = path.join(REF, "selftest.png");
  fs.mkdirSync(REF, { recursive: true });
  fs.writeFileSync(fixture, canvas.toBuffer("image/png"));
  const px = await loadPixels(fixture);
  const { rows: rr, cols: cr } = findSeparators(px);
  const minRow = Math.floor(px.height / 16);
  const minCol = Math.floor(px.width / 16);
  const rowCells = cellsBetween(rr, px.height, minRow);
  const colCells = cellsBetween(cr, px.width, minCol);
  const ok = rowCells.length === rows && colCells.length === cols;
  console.log(`selftest: separadores filas=${rr.length} columnas=${cr.length} → celdas ${colCells.length}×${rowCells.length} (esperado ${cols}×${rows})`);
  if (!ok) {
    console.error("selftest FALLO: la autodetección no reconstruyó la rejilla.");
    process.exitCode = 1;
    return;
  }
  const bbox = contentBBox(px, [colCells[0][0], rowCells[0][0], colCells[0][1], rowCells[0][1]]);
  console.log(`selftest OK · primera ficha ${bbox[2] - bbox[0] + 1}×${bbox[3] - bbox[1] + 1} px (celda ${cell}×${cell})`);
  fs.rmSync(fixture, { force: true });
}

// ---------------------------------------------------------------------- main
if (SELFTEST) {
  await selftest();
  process.exit(process.exitCode ?? 0);
}

const layoutOverrides = readLayout();
const sourceDirs = FIXTURES_MODE ? (generateFixtures(), [FIXTURES]) : INPUT_DIRS;
const discovered = discoverSources(sourceDirs);
const complete = reportFound(discovered, sourceDirs);
if (CHECK_ONLY) process.exit(complete ? 0 : 1);
if (!complete) {
  // Ingesta parcial: si falta algún mosaico se ingesta lo que sí hay y se
  // deja constancia en el índice. Bloquearlo todo por un recurso pendiente
  // dejaba el resto del pipeline — y sus 101 mapas — sin poder avanzar.
  if (discovered.found.size === 0) {
    console.error("No hay ningún mosaico asignado: no se puede ingestar nada.");
    process.exit(1);
  }
  const faltan = RESOURCES.filter((r) => !discovered.found.has(r.key)).map((r) => r.key);
  console.log(`\nAviso: faltan ${faltan.length} mosaico(s) (${faltan.join(", ")}).`);
  console.log("Se ingesta sólo lo disponible; el índice marca los pendientes.");
}

fs.mkdirSync(SLICES, { recursive: true });
const index = {
  title: "Dimensional Nightmare — catálogo de referencia visual",
  generatedBy: "tools/dn_ingest_reference.mjs",
  fixture: FIXTURES_MODE,
  note: "Cada ficha es la referencia de UN mapa del GDD (docs/DIMENSIONAL_NIGHTMARE/11_ASIGNACION_DE_RECURSOS.md).",
  pending: RESOURCES.filter((r) => !discovered.found.has(r.key)).map((r) => ({ key: r.key, label: r.label })),
  resources: [],
};
let total = 0, mismatches = [];
for (const resource of RESOURCES) {
  const layout = layoutOverrides[resource.key] ?? {};
  const entry = await ingestResource(resource, discovered.found.get(resource.key), layout);
  if (!entry) continue;
  total += entry.slices.length;
  if (entry.slices.length !== resource.expect) {
    mismatches.push(`${resource.key}: ${entry.slices.length} fichas (se esperaban ${resource.expect})`);
  }
  index.resources.push(entry);
  console.log(`${resource.key}: ${entry.slices.length}/${resource.expect} fichas · rejilla ${entry.grid.mode} · ${entry.image.width}×${entry.image.height}px`);
}
fs.writeFileSync(INDEX_PATH, JSON.stringify(index, null, 2));
console.log(`\nTotal: ${total} fichas → ${path.relative(ROOT, INDEX_PATH)}`);
if (mismatches.length) {
  console.warn("Avisos de rejilla (revisa layout.json):\n  " + mismatches.join("\n  "));
  process.exitCode = 1;
}#!/usr/bin/env node
/**
 * Dimensional Nightmare — arte de prioridad ALTA (doc 08) + cableado en el juego.
 *
 * Toma los originales de `reference/dimensional_nightmare/art_src/` (arte propio, NO derivado de
 * los mosaicos: por eso sí puede empaquetarse), les quita el fondo magenta, los recorta, los
 * reduce por media de área al tamaño final, los cuantiza a ≤32 colores y los escribe en
 * `pokemon_fire_ash/Graphics/` con vecino más cercano (pixel art nítido).
 *
 * Después cablea el arte:
 *   - tipo de entrenador `DN_KINGGUS` (clon de GENTLEMAN) → el jefe de EP06 se ve como KINGGUS;
 *   - registro del entrenador `DN_EP06_A` → pasa a tipo DN_KINGGUS (clave + @trainer_type);
 *   - evento `EV_EP06_JEFE` (Map2135) → secuencia registrada `dn_kinggus_final_sequence` (forma intermedia + final);
 *   - `NPC_KINGGUS` (Map2135) → gráfico de personaje `DN_KINGGUS`;
 *   - `EV_EP01_JEFE` (Map2056) → gráfico de personaje `DN_WHITE_HAND`.
 * El catálogo `content/dimensional_nightmare_events.json` se actualiza igual, para que regenerar
 * eventos/trainers con las herramientas dn reproduzca el mismo resultado.
 *
 * Uso:
 *   node tools/dn_install_art.mjs            # procesa, escribe y cablea
 *   node tools/dn_install_art.mjs --verify   # sólo comprueba (no escribe)
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { createCanvas, loadImage } from "@napi-rs/canvas";
import { marshalLoad, marshalDump, RObject, RString, RSymbol } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const SRC = path.join(ROOT, "reference", "dimensional_nightmare", "art_src");
const MANIFEST = path.join(ROOT, "content", "dimensional_nightmare_art.json");
const CATALOG = path.join(ROOT, "content", "dimensional_nightmare_events.json");
const BACKUP = path.join(GAME, "PokeModBackups", "dimensional_nightmare_art_originals");
const DATA = path.join(GAME, "Data");
const VERIFY = process.argv.includes("--verify");

const S = (v) => RString.fromText(String(v));
const sha1 = (buf) => crypto.createHash("sha1").update(buf).digest("hex").slice(0, 12);
const readData = (f) => marshalLoad(fs.readFileSync(path.join(DATA, f)));
const txt = (v) => (v && v.text !== undefined ? v.text : v && v.name !== undefined ? v.name : String(v));

// ------------------------------------------------------------------ especificaciones
/** Cada salida: fuente, destino, tamaño final (px) y alineación del recorte. */
const SPECS = [
  { id: "kinggus_front", src: "kinggus_form1.png", out: "Graphics/Pokemon/Front/DN_KINGGUS.png", w: 64, h: 64, align: "bottom", use: "battler forma 1 (soporte arte)" },
  { id: "kinggus_final", src: "kinggus_final.png", out: "Graphics/Pokemon/Front/DN_KINGGUS_FINAL.png", w: 64, h: 64, align: "bottom", use: "battler forma final" },
  { id: "kinggus_trainer", src: "kinggus_form1.png", out: "Graphics/Trainers/DN_KINGGUS.png", w: 128, h: 128, align: "bottom", use: "sprite de entrenador del jefe EP06" },
  { id: "kinggus_over", src: "kinggus_over.png", out: "Graphics/Characters/DN_KINGGUS.png", w: 128, h: 128, cell: 32, align: "bottom", use: "overworld (hoja 4×4 de 32 px)" },
  { id: "white_hand_over", src: "white_hand.png", out: "Graphics/Characters/DN_WHITE_HAND.png", w: 384, h: 384, cell: 96, align: "bottom", use: "altar de la Mano Blanca (hoja 4×4 de 96 px)" },
  { id: "white_hand_pic", src: "white_hand.png", out: "Graphics/Pictures/DN_WHITE_HAND.png", w: 96, h: 96, align: "center", use: "escena (pantalla/altar)" },
  { id: "unown_fragment", src: "unown_fragment.png", out: "Graphics/Items/DN_UNOWN_FRAGMENT.png", w: 48, h: 48, align: "center", use: "icono de objeto" },
];

const MAGENTA = (r, g, b) => r > 170 && b > 170 && g < 110;
const PALETTE_MAX = 32;

// ------------------------------------------------------------------ utilidades de imagen
async function loadKeyed(file) {
  const img = await loadImage(path.join(SRC, file));
  const canvas = createCanvas(img.width, img.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(img, 0, 0);
  const { data } = ctx.getImageData(0, 0, img.width, img.height);
  for (let i = 0; i < data.length; i += 4) {
    data[i + 3] = MAGENTA(data[i], data[i + 1], data[i + 2]) ? 0 : 255;
  }
  return { px: data, w: img.width, h: img.height };
}

function contentBox({ px, w, h }) {
  let x0 = w, y0 = h, x1 = -1, y1 = -1;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (px[(y * w + x) * 4 + 3] === 0) continue;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
    }
  }
  if (x1 < 0) throw new Error("imagen sin contenido tras quitar el fondo");
  return { x0, y0, x1, y1 };
}

/** Reduce por media de área (box filter) y cuantiza. Devuelve {px,w,h} del recorte final. */
function resampleToCell(src, box, cellW, cellH, align) {
  const bw = box.x1 - box.x0 + 1;
  const bh = box.y1 - box.y0 + 1;
  const scale = Math.min(cellW / bw, cellH / bh);
  const cw = Math.max(1, Math.min(cellW, Math.round(bw * scale)));
  const ch = Math.max(1, Math.min(cellH, Math.round(bh * scale)));
  const ox = Math.floor((cellW - cw) / 2);
  const oy = align === "bottom" ? cellH - ch : Math.floor((cellH - ch) / 2);
  const out = new Uint8ClampedArray(cellW * cellH * 4);
  for (let y = 0; y < ch; y++) {
    const sy0 = box.y0 + Math.floor((y * bh) / ch);
    const sy1 = Math.max(sy0 + 1, box.y0 + Math.floor(((y + 1) * bh) / ch));
    for (let x = 0; x < cw; x++) {
      const sx0 = box.x0 + Math.floor((x * bw) / cw);
      const sx1 = Math.max(sx0 + 1, box.x0 + Math.floor(((x + 1) * bw) / cw));
      let r = 0, g = 0, b = 0, a = 0, n = 0;
      for (let sy = sy0; sy < sy1; sy++) {
        for (let sx = sx0; sx < sx1; sx++) {
          const i = (sy * src.w + sx) * 4;
          const al = src.px[i + 3] / 255;
          const w = al; // media ponderada por alfa (fondo transparente no ensucia)
          r += src.px[i] * w; g += src.px[i + 1] * w; b += src.px[i + 2] * w;
          a += src.px[i + 3];
          n += 255;
        }
      }
      const i = ((y + oy) * cellW + (x + ox)) * 4;
      const alpha = a / n;
      if (alpha >= 0.5) {
        const sum = (r + g + b) / 255 || 1;
        out[i] = r / sum; out[i + 1] = g / sum; out[i + 2] = b / sum; out[i + 3] = 255;
      }
    }
  }
  return { px: out, w: cellW, h: cellH };
}

/** Median-cut compacto → paleta de ≤max colores; luego mapea cada píxel al color más cercano. */
function quantize(cell, max = PALETTE_MAX) {
  const buckets = [];
  const all = [];
  for (let i = 0; i < cell.px.length; i += 4) {
    if (cell.px[i + 3] > 0) all.push([cell.px[i], cell.px[i + 1], cell.px[i + 2]]);
  }
  if (!all.length) return cell;
  buckets.push(all);
  while (buckets.length < max) {
    let best = -1, bestRange = -1, bestCh = 0;
    buckets.forEach((b, idx) => {
      if (b.length < 2) return;
      for (let ch = 0; ch < 3; ch++) {
        const vals = b.map((p) => p[ch]);
        const range = Math.max(...vals) - Math.min(...vals);
        if (range > bestRange) { bestRange = range; best = idx; bestCh = ch; }
      }
    });
    if (best < 0 || bestRange < 4) break;
    const b = buckets[best];
    b.sort((p, q) => p[bestCh] - q[bestCh]);
    const mid = Math.floor(b.length / 2);
    buckets.splice(best, 1, b.slice(0, mid), b.slice(mid));
  }
  const palette = buckets.filter((b) => b.length).map((b) => {
    const n = b.length;
    return [Math.round(b.reduce((s, p) => s + p[0], 0) / n), Math.round(b.reduce((s, p) => s + p[1], 0) / n), Math.round(b.reduce((s, p) => s + p[2], 0) / n)];
  });
  const nearest = (r, g, b) => {
    let best = 0, bestD = Infinity;
    palette.forEach(([pr, pg, pb], i) => {
      const d = (r - pr) ** 2 + (g - pg) ** 2 + (b - pb) ** 2;
      if (d < bestD) { bestD = d; best = i; }
    });
    return palette[best];
  };
  const out = new Uint8ClampedArray(cell.px);
  for (let i = 0; i < out.length; i += 4) {
    if (out[i + 3] === 0) { out[i + 3] = 0; continue; }
    const [r, g, b] = nearest(out[i], out[i + 1], out[i + 2]);
    out[i] = r; out[i + 1] = g; out[i + 2] = b; out[i + 3] = 255;
  }
  return { px: out, w: cell.w, h: cell.h };
}

function toCanvas(cell) {
  const canvas = createCanvas(cell.w, cell.h);
  const ctx = canvas.getContext("2d");
  const img = ctx.createImageData(cell.w, cell.h);
  img.data.set(cell.px);
  ctx.putImageData(img, 0, 0);
  return canvas;
}

/** Hoja 4×4 (RMXP): filas abajo/izq/der/arriba; columnas 0‑3 = reposo, paso, reposo, paso. */
function buildSheet(cell, cellSize) {
  const sheet = { px: new Uint8ClampedArray(cellSize * 4 * cellSize * 4 * 4), w: cellSize * 4, h: cellSize * 4 };
  const blit = (src, dx, dy, mirror, shiftY) => {
    for (let y = 0; y < cellSize; y++) {
      for (let x = 0; x < cellSize; x++) {
        const s = (y * cellSize + x) * 4;
        if (src.px[s + 3] === 0) continue;
        const tx = mirror ? dx + (cellSize - 1 - x) : dx + x;
        const ty = dy + y + shiftY;
        if (tx < 0 || ty < 0 || tx >= sheet.w || ty >= sheet.h) continue;
        const d = (ty * sheet.w + tx) * 4;
        sheet.px[d] = src.px[s]; sheet.px[d + 1] = src.px[s + 1]; sheet.px[d + 2] = src.px[s + 2]; sheet.px[d + 3] = 255;
      }
    }
  };
  for (let dir = 0; dir < 4; dir++) {
    const mirror = dir === 1;
    for (let f = 0; f < 4; f++) {
      const shiftY = f % 2 === 1 ? 1 : 0;
      blit(cell, f * cellSize, dir * cellSize, mirror, shiftY);
    }
  }
  return sheet;
}

function countColors(cell) {
  const seen = new Set();
  for (let i = 0; i < cell.px.length; i += 4) if (cell.px[i + 3] > 0) seen.add(`${cell.px[i]},${cell.px[i + 1]},${cell.px[i + 2]}`);
  return seen.size;
}

function hasTransparency(cell) {
  for (let i = 3; i < cell.px.length; i += 4) if (cell.px[i] === 0) return true;
  return false;
}

// ------------------------------------------------------------------ construcción de assets
async function buildAssets() {
  const cache = new Map();
  const results = [];
  for (const spec of SPECS) {
    if (!cache.has(spec.src)) cache.set(spec.src, await loadKeyed(spec.src));
    const src = cache.get(spec.src);
    const box = contentBox(src);
    const cellW = spec.cell ?? spec.w;
    const cellH = spec.cell ?? spec.h;
    const cell = quantize(resampleToCell(src, box, cellW, cellH, spec.align));
    const final = spec.cell ? buildSheet(cell, spec.cell) : cell;
    const canvas = toCanvas(final);
    const png = canvas.toBuffer("image/png");
    const abs = path.join(GAME, spec.out);
    results.push({
      id: spec.id, out: spec.out, use: spec.use, source: spec.src,
      sourceSha1: sha1(fs.readFileSync(path.join(SRC, spec.src))), sha1: sha1(png),
      w: final.w, h: final.h, colors: countColors(cell), transparent: hasTransparency(cell),
      bytes: png.length, png, abs,
    });
  }
  return results;
}

// ------------------------------------------------------------------ cableado
function backup(file) {
  fs.mkdirSync(BACKUP, { recursive: true });
  const dest = path.join(BACKUP, file);
  if (!fs.existsSync(dest)) fs.copyFileSync(path.join(DATA, file), dest);
}

function installTrainerType() {
  backup("trainer_types.dat");
  const tt = readData("trainer_types.dat");
  if (tt.pairs.some(([k]) => txt(k) === "DN_KINGGUS")) return { added: false };
  const [, base] = tt.pairs.find(([k]) => txt(k) === "GENTLEMAN") ?? [];
  if (!base) throw new Error("no existe GENTLEMAN en trainer_types.dat");
  const clone = new RObject(base.className, base.ivars.map(([k, v]) => [k, v]));
  const numbers = tt.pairs.map(([, v]) => v.getIvar("@id_number")).filter((n) => typeof n === "number");
  clone.setIvar("@id", new RSymbol("DN_KINGGUS"));
  clone.setIvar("@id_number", Math.max(-1, ...numbers) + 1);
  clone.setIvar("@real_name", S("KINGGUS"));
  clone.setIvar("@base_money", 200);
  tt.pairs.push([new RSymbol("DN_KINGGUS"), clone]);
  if (!VERIFY) fs.writeFileSync(path.join(DATA, "trainer_types.dat"), Buffer.from(marshalDump(tt)));
  return { added: true };
}

function installTrainerRecord() {
  backup("trainers.dat");
  const trainers = readData("trainers.dat");
  let touched = 0;
  for (const [key, value] of trainers.pairs) {
    if (!Array.isArray(key) || txt(key[1]) !== "KINGGUS") continue;
    if (key[0] instanceof RSymbol && key[0].name !== "DN_KINGGUS") { key[0] = new RSymbol("DN_KINGGUS"); touched++; }
    if (value?.setIvar) value.setIvar("@trainer_type", new RSymbol("DN_KINGGUS"));
  }
  if (!VERIFY && touched) fs.writeFileSync(path.join(DATA, "trainers.dat"), Buffer.from(marshalDump(trainers)));
  return { touched };
}

/** Textos de los comandos de script (código 355) de todas las páginas de un evento. */
function scriptTexts(map, eventName) {
  const ev = (map.getIvar("@events")?.pairs ?? []).find(([, e]) => txt(e.getIvar("@name")) === eventName);
  const out = [];
  for (const page of ev?.[1].getIvar("@pages") ?? []) {
    for (const cmd of page.getIvar("@list") ?? []) {
      for (const p of cmd.getIvar?.("@parameters") ?? []) if (p && typeof p.text === "string") out.push(p);
    }
  }
  return out;
}

/** Cambia el gráfico de un evento (todas sus páginas). */
function setEventGraphic(map, name, graphic) {
  const evs = map.getIvar("@events")?.pairs ?? [];
  const ev = evs.find(([, e]) => txt(e.getIvar("@name")) === name);
  if (!ev) return false;
  for (const page of ev[1].getIvar("@pages") ?? []) {
    const g = page.getIvar("@graphic");
    if (g?.getIvar("@character_name")) g.setIvar("@character_name", S(graphic));
  }
  return true;
}

/** Reescribe el tipo del entrenador en los scripts de las páginas de un evento. */
function rewriteBattleType(map, eventName, from, to) {
  const needle = `PBTrainer.new("${from}"`;
  let hits = 0;
  for (const p of scriptTexts(map, eventName)) {
    if (!p.text.includes(needle)) continue;
    p.text = p.text.split(needle).join(`PBTrainer.new("${to}"`);
    hits++;
  }
  return hits;
}

function wireMapEvents(file, edits) {
  const full = path.join(DATA, file);
  backup(file);
  const map = marshalLoad(fs.readFileSync(full));
  const done = edits.map((e) => (e.graphic ? setEventGraphic(map, e.event, e.graphic) : rewriteBattleType(map, e.event, e.from, e.to) > 0));
  if (!VERIFY && done.some(Boolean)) fs.writeFileSync(full, Buffer.from(marshalDump(map)));
  return edits.map((e, i) => ({ ...e, applied: done[i] }));
}

function updateCatalog() {
  const data = JSON.parse(fs.readFileSync(CATALOG, "utf8"));
  const ep = (data.episodes ?? []).find((e) => e.key === "EP06");
  const before = ep?.boss?.phaseA?.type;
  if (ep?.boss?.phaseA) ep.boss.phaseA.type = "DN_KINGGUS";
  if (!VERIFY) fs.writeFileSync(CATALOG, JSON.stringify(data, null, 2) + "\n");
  return { before, after: ep?.boss?.phaseA?.type };
}

// ------------------------------------------------------------------ verificación
function verifyAssets(manifest) {
  const failures = [];
  for (const item of manifest.assets ?? []) {
    const abs = path.join(GAME, item.out);
    if (!fs.existsSync(abs)) { failures.push(`${item.out}: no existe`); continue; }
    const buf = fs.readFileSync(abs);
    const img = createCanvas(1, 1); // sólo para dimensiones: se lee la cabecera PNG
    const w = buf.readUInt32BE(16), h = buf.readUInt32BE(20);
    if (w !== item.w || h !== item.h) failures.push(`${item.out}: ${w}×${h} ≠ ${item.w}×${item.h}`);
    // `sha1` es el arte original generado; `gbSha1` la misma pieza tras el contrato
    // Game Boy (dn:gameboy recolorea todo DN_* en el sitio). Cualquiera de los dos
    // es un estado válido y reproducible.
    const actual = sha1(buf);
    if (actual !== item.sha1 && actual !== item.gbSha1) failures.push(`${item.out}: hash distinto al manifiesto`);
    if (item.colors > PALETTE_MAX) failures.push(`${item.out}: ${item.colors} colores (máx ${PALETTE_MAX})`);
    if (!item.transparent) failures.push(`${item.out}: sin transparencia (fondo no recortado)`);
    void img;
  }
  return failures;
}

function verifyWiring() {
  const failures = [];
  const push = (ok, msg) => { if (!ok) failures.push(msg); };
  const tt = readData("trainer_types.dat");
  const entry = tt.pairs.find(([k]) => txt(k) === "DN_KINGGUS");
  push(!!entry, "trainer_types.dat: falta DN_KINGGUS");
  push(entry?.[1]?.getIvar("@id_number") > 0, "DN_KINGGUS: sin @id_number");
  const trainers = readData("trainers.dat");
  const rec = trainers.pairs.find(([k]) => Array.isArray(k) && txt(k[1]) === "KINGGUS");
  push(!!rec, "trainers.dat: falta el registro del jefe KINGGUS");
  push(rec && txt(rec[1].getIvar("@trainer_type")) === "DN_KINGGUS", "trainers.dat: el jefe EP06 no usa el tipo DN_KINGGUS");
  const m2135 = marshalLoad(fs.readFileSync(path.join(DATA, "Map2135.rxdata")));
  const m2056 = marshalLoad(fs.readFileSync(path.join(DATA, "Map2056.rxdata")));
  const graphicOf = (map, name) => {
    const ev = (map.getIvar("@events")?.pairs ?? []).find(([, e]) => txt(e.getIvar("@name")) === name);
    return txt(ev?.[1].getIvar("@pages")?.[0]?.getIvar("@graphic")?.getIvar("@character_name"));
  };
  push(graphicOf(m2135, "NPC_KINGGUS") === "DN_KINGGUS", "Map2135: NPC_KINGGUS sin gráfico DN_KINGGUS");
  push(graphicOf(m2056, "EV_EP01_JEFE") === "DN_WHITE_HAND", "Map2056: EV_EP01_JEFE sin gráfico DN_WHITE_HAND");
  const battleCalls = scriptTexts(m2135, "EV_EP06_JEFE").map((p) => p.text).join("\n");
  push(battleCalls.includes("dn_kinggus_final_sequence"), "Map2135: falta la secuencia intermedia + forma final de KINGGUS");
  push(!battleCalls.includes('PBTrainer.new("GENTLEMAN"'), "Map2135: la batalla de EP06 sigue con GENTLEMAN");
  const catalog = JSON.parse(fs.readFileSync(CATALOG, "utf8"));
  push((catalog.episodes ?? []).find((e) => e.key === "EP06")?.boss?.phaseA?.type === "DN_KINGGUS", "catálogo: EP06 sigue con el tipo antiguo");
  return failures;
}

// ------------------------------------------------------------------ main
async function main() {
  if (VERIFY) {
    if (!fs.existsSync(MANIFEST)) { console.error("No hay manifiesto de arte; corre `npm run dn:art`."); process.exit(1); }
    const manifest = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
    const failures = [...verifyAssets(manifest), ...verifyWiring()];
    console.log(`verificación de arte (${manifest.assets.length} assets + cableado)`);
    for (const item of manifest.assets) console.log(`  ${item.out} · ${item.w}×${item.h} · ${item.colors} colores · ${item.use}${item.gbSha1 ? " · paleta GB" : ""}`);
    if (failures.length) { for (const f of failures) console.error(`  FALLA: ${f}`); process.exit(1); }
    console.log("verificación de arte OK");
    return;
  }

  const assets = await buildAssets();
  for (const a of assets) {
    fs.mkdirSync(path.dirname(a.abs), { recursive: true });
    fs.writeFileSync(a.abs, a.png);
    console.log(`  ${a.out} · ${a.w}×${a.h} · ${a.colors} colores · ${(a.bytes / 1024).toFixed(1)} KB`);
  }
  const manifest = {
    title: "Dimensional Nightmare — arte de prioridad ALTA (doc 08)",
    generatedBy: "tools/dn_install_art.mjs",
    note: "Arte original generado para el mod (no derivado de los mosaicos). Sí puede empaquetarse.",
    paletteMax: PALETTE_MAX,
    assets: assets.map(({ png, abs, ...rest }) => rest),
  };
  fs.writeFileSync(MANIFEST, JSON.stringify(manifest, null, 2) + "\n");

  const type = installTrainerType();
  const record = installTrainerRecord();
  const wire2135 = wireMapEvents("Map2135.rxdata", [
    { event: "NPC_KINGGUS", graphic: "DN_KINGGUS" },
  ]);
  const wire2056 = wireMapEvents("Map2056.rxdata", [{ event: "EV_EP01_JEFE", graphic: "DN_WHITE_HAND" }]);
  const catalog = updateCatalog();

  console.log(`cableado: tipo DN_KINGGUS ${type.added ? "creado" : "ya existía"} · registro del jefe ${record.touched ? "migrado" : "ya estaba"}`);
  for (const w of [...wire2135, ...wire2056]) console.log(`  ${w.event}: ${w.applied ? "listo" : "revisar"}${w.graphic ? ` (gráfico ${w.graphic})` : ` (tipo ${w.from}→${w.to})`}`);
  console.log(`catálogo EP06: ${catalog.before} → ${catalog.after}`);
}

main().catch((e) => { console.error(e); process.exit(1); });#!/usr/bin/env node
/**
 * dn_name_flags.mjs — pone nombre a las switches y variables del Dimensional Nightmare en
 * `System.rxdata`.
 *
 * Sin nombre, las flags del ciclo (switches 882–935 y variables DN 265–307) aparecen como «—» en el editor de RMXP y en
 * la lista de eventos, y es fácil pisar una ajena. v264 queda fuera del rango DN: es el contador de emisiones selladas
 * de Monte Silver, que el Nightmare sólo consulta. Esta herramienta:
 *   1. extiende las listas hasta el último índice que usa el ciclo;
 *   2. escribe el nombre de cada flag DN (sólo si el hueco está vacío o ya es DN);
 *   3. **rechaza** tocar cualquier nombre de Atlas o de La Ruta de Dios, y avisa si detecta
 *      colisiones entre dos herramientas del propio ciclo.
 *
 * Uso:
 *   node tools/dn_name_flags.mjs            # nombra (idempotente)
 *   node tools/dn_name_flags.mjs --verify
 */
import { S, txt, readData, writeData, backup } from "./lib/dn_rmxp.mjs";

const VERIFY = process.argv.includes("--verify");
const FOREIGN = /ATLAS|RUTA_DE_DIOS|ARCEUS_CINEMATIC|SNOWPOINT/i;

