/**
 * Extracción forense de ROMs invitadas.
 *
 * Toma cada ROM de `roms pokemon/` y la desarma en una carpeta propia con todo
 * lo que se puede reconstruir: cabecera, catálogos (especies, objetos,
 * movimientos...), sprites, tiles, textos/diálogos y un censo de bloques
 * comprimidos que alimenta la extracción de mapas.
 *
 * Todo se hace con decodificadores reales (LZ77/RLE de la BIOS de GBA,
 * descompresor de sprites de Gen 1, paletas BGR555, tiles 4 bpp) y cada hallazgo
 * se guarda con su desplazamiento dentro de la ROM para poder volver a él.
 *
 * Uso:
 *   node tools/forense_roms.mjs
 *   node tools/forense_roms.mjs --rom "roms pokemon/GlazedESPB6.gba"
 *   node tools/forense_roms.mjs --solo nombres
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync } from 'node:fs';
import { join, basename, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';

import { pngIndizado } from './forense/png.mjs';
import * as GBA from './forense/gba.mjs';
import * as GB from './forense/gb.mjs';

const RAIZ = join(dirname(fileURLToPath(import.meta.url)), '..');
const ROMS_DIR = join(RAIZ, 'roms pokemon');

const arg = (nombre, defecto = null) => {
  const i = process.argv.indexOf(`--${nombre}`);
  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith('--') ? process.argv[i + 1] : defecto;
};
const SOLO = arg('solo');
const ROM_ARG = arg('rom');

const PALETA_GRIS = [[255, 255, 255, 0], [176, 176, 176, 255], [96, 96, 96, 255], [0, 0, 0, 255]];
const PALETA_VACIA = Array.from({ length: 16 }, (_, i) => [i * 16, i * 16, i * 16, i === 0 ? 0 : 255]);

const asegurar = (dir) => { mkdirSync(dir, { recursive: true }); return dir; };
const escribir = (ruta, contenido) => { writeFileSync(ruta, contenido); };
const escribirJSON = (ruta, datos) => escribir(ruta, JSON.stringify(datos, null, 2));

function slugDe(archivo) {
  return basename(archivo, extname(archivo)).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

/* ───────────────────────────── utilidades comunes ──────────────────────── */

/**
 * Métricas de "parece un sprite de verdad": proporción de transparente, anillo
 * exterior de 2 px limpio (los monstruos de Gen 1 se dibujan con margen) y
 * longitud media de trazo. Se calibraron con la cadena de frontales del banco
 * 0x13 de FactoryAdventure: cero 0,54-0,87 · anillo 0,87-1,00 · trazo 1,0-1,5.
 */
function metricasSprite(r) {
  const { px, ancho: w, alto: h } = r;
  const anillo = (m) => {
    let total = 0;
    let vacios = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (x < m || y < m || x >= w - m || y >= h - m) { total++; if (!px[y * w + x]) vacios++; }
      }
    }
    return vacios / total;
  };
  let cero = 0;
  let trazos = 0;
  let pixeles = 0;
  for (let y = 0; y < h; y++) {
    let ant = -1;
    for (let x = 0; x < w; x++) {
      const v = px[y * w + x];
      if (v === 0) cero++;
      if (v !== ant) trazos++;
      ant = v;
      if (v) pixeles++;
    }
  }
  return {
    cero: cero / (w * h),
    anillo: anillo(2),
    trazo: pixeles / Math.max(1, trazos),
    w,
    h,
  };
}

const pareceSprite = (m) => m.cero >= 0.40 && m.cero <= 0.95 && m.anillo >= 0.85 && m.trazo >= 0.8 && m.trazo <= 4.0;

/* ──────────────────────────────────── GBA ─────────────────────────────── */

function forenseGBA(data, salida, nombre) {
  const cabecera = GBA.leerCabeceraGBA(data);
  escribirJSON(join(salida, '00_cabecera.json'), cabecera);
  console.log(`  · cabecera: ${cabecera.titulo} [${cabecera.codigo}] ${(data.length / 1048576).toFixed(1)} MB`);

  const indice = { juego: nombre, plataforma: 'GBA', cabecera, hallazgos: {} };

  /* nombres de especie */
  const nombres = GBA.buscarTablaNombres(data, 60) || GBA.buscarTablaNombres(data, 25);
  if (nombres) {
    const dirPoke = asegurar(join(salida, 'pokemon'));
    escribirJSON(join(dirPoke, 'nombres.json'), {
      offsetTabla: nombres.base,
      cantidad: nombres.nombres.length,
      nombres: nombres.nombres,
      otrasCandidatas: nombres.candidatos,
    });
    // las tablas secundarias suelen ser continuaciones (el hack parte el bloque)
    const extras = nombres.candidatos.slice(1).map((c) => {
      const lista = [];
      for (let i = 0; i < c.n; i++) {
        const e = data.subarray(c.base + i * 11, c.base + i * 11 + 11);
        lista.push({ indice: i, nombre: GBA.decodificarTextoGBA(e).texto, offset: c.base + i * 11 });
      }
      return { offsetTabla: c.base, cantidad: c.n, nombres: lista };
    });
    if (extras.length) escribirJSON(join(dirPoke, 'nombres_tablas_secundarias.json'), extras);
    indice.hallazgos.nombresEspecie = { offset: nombres.base, cantidad: nombres.nombres.length };
    console.log(`  · nombres de especie: ${nombres.nombres.length} (tabla en 0x${nombres.base.toString(16)})`);
  } else {
    console.log('  · sin tabla de nombres todavía');
  }
  const nEspecies = nombres ? nombres.nombres.length : 0;

  /* sprites: sirven también de referencia para el número de especies */
  const tablasSprites = GBA.buscarTablaSprites(data, 0x800, 40);
  const referencia = Math.max(nEspecies, tablasSprites.length ? tablasSprites[0].n : 0);
  const cercana = (tablas) => tablas
    .filter((t) => t.n > 20)
    .sort((a, b) => Math.abs(a.n - referencia) - Math.abs(b.n - referencia))[0];

  /* estadísticas base */
  if (referencia) {
    const tablas = GBA.buscarEstadisticasBase(data, referencia);
    const mejor = cercana(tablas);
    if (mejor) {
      const stats = GBA.interpretarEstadisticas(data, mejor.base, mejor.n);
      escribirJSON(join(salida, 'pokemon', 'estadisticas_base.json'), {
        offsetTabla: mejor.base,
        cantidad: mejor.n,
        entradaBytes: 28,
        entradas: stats,
      });
      indice.hallazgos.estadisticasBase = { offset: mejor.base, cantidad: mejor.n };
      console.log(`  · estadísticas base: ${mejor.n} especies (0x${mejor.base.toString(16)})`);
    }
    const evos = GBA.buscarEvoluciones(data, referencia);
    const e = cercana(evos);
    if (e) {
      escribirJSON(join(salida, 'pokemon', 'evoluciones.json'), {
        offsetTabla: e.base,
        cantidad: e.n,
        entradas: GBA.interpretarEvoluciones(data, e.base, e.n),
      });
      console.log(`  · evoluciones: ${e.n} especies (0x${e.base.toString(16)})`);
    }
    const aprender = GBA.buscarAprendizaje(data, referencia);
    const t = cercana(aprender);
    if (t) {
      escribirJSON(join(salida, 'pokemon', 'aprendizaje_nivel.json'), {
        offsetTabla: t.base,
        cantidad: t.n,
        entradas: GBA.interpretarAprendizaje(data, t),
      });
      console.log(`  · aprendizaje por nivel: ${t.n} especies (0x${t.base.toString(16)})`);
    }
  }

  /* volcado de los sprites localizados */
  if (tablasSprites.length) {
    const paletas = GBA.buscarTablaPaletas(data, Math.max(30, Math.min(nEspecies || 40, 60)));
    const paletaUsar = paletas[0];
    const dirSprites = asegurar(join(salida, 'sprites'));
    const usadas = tablasSprites.slice(0, 2);
    usadas.forEach((tabla, k) => {
      const carpeta = asegurar(join(dirSprites, k === 0 ? 'frontal' : 'trasero'));
      const listado = [];
      tabla.entradas.forEach((entrada, i) => {
        const r = GBA.lz77(data, entrada.offset);
        if (!r) return;
        const img = GBA.tiles4bpp(r.datos, 8, 8);
        let paleta = PALETA_VACIA;
        if (paletaUsar && paletaUsar.entradas[i]) paleta = GBA.leerPaleta(data, paletaUsar.entradas[i].offset, 16);
        const nombre = (nombres && nombres.nombres[i]) ? nombres.nombres[i].nombre : `especie_${i}`;
        const archivo = join(carpeta, `${String(i).padStart(3, '0')}_${nombre}.png`);
        escribir(archivo, pngIndizado(img.w, img.h, img.px, paleta));
        listado.push({ indice: i, nombre, archivo: archivo.replace(salida, '').replace(/^\//, ''), offsetSprite: entrada.offset, tamano: r.tam, offsetPaleta: paletaUsar && paletaUsar.entradas[i] ? paletaUsar.entradas[i].offset : null });
      });
      escribirJSON(join(carpeta, 'indice.json'), { offsetTabla: tabla.base, cantidad: listado.length, sprites: listado });
      indice.hallazgos[k === 0 ? 'spritesFrontales' : 'spritesTraseros'] = { offsetTabla: tabla.base, cantidad: listado.length };
      console.log(`  · sprites ${k === 0 ? 'frontales' : 'traseros'}: ${listado.length} (tabla 0x${tabla.base.toString(16)})`);
    });
  }

  /* iconos */
  const iconos = GBA.buscarTablaIconos(data, Math.max(30, Math.min(nEspecies || 40, 60)));
  if (iconos.length) {
    const tabla = iconos[0];
    const dir = asegurar(join(salida, 'sprites', 'iconos'));
    const imagenes = [];
    tabla.entradas.forEach((entrada, i) => {
      const r = GBA.lz77(data, entrada.offset);
      if (!r) return;
      imagenes.push({ i, img: GBA.tiles4bpp(r.datos, 4, 4) });
    });
    if (imagenes.length) {
      const hoja = GBA.hojaSprites(imagenes.map((x) => x.img), 16);
      escribir(join(dir, 'iconos.png'), pngIndizado(hoja.w, hoja.h, hoja.px, PALETA_VACIA));
      escribirJSON(join(dir, 'indice.json'), { offsetTabla: tabla.base, cantidad: imagenes.length, columnas: 16 });
      indice.hallazgos.iconos = { offsetTabla: tabla.base, cantidad: imagenes.length };
      console.log(`  · iconos: ${imagenes.length} en hoja (tabla 0x${tabla.base.toString(16)})`);
    }
  }

  /* catálogos de texto (objetos, movimientos, habilidades, tipos, mapas…) */
  const tablasTexto = GBA.buscarTablasTexto(data, { minEntradas: 16, minLargo: 2 });
  if (tablasTexto.length) {
    const dir = asegurar(join(salida, 'catalogos'));
    const resumen = tablasTexto.slice(0, 24).map((t, i) => {
      const archivo = `tabla_${String(i).padStart(2, '0')}_${t.n}.json`;
      escribirJSON(join(dir, archivo), { offsetTabla: t.base, cantidad: t.n, textos: t.textos });
      return { archivo, offsetTabla: t.base, cantidad: t.n, muestra: t.textos.slice(0, 4).map((x) => x.texto) };
    });
    escribirJSON(join(dir, 'indice.json'), resumen);
    indice.hallazgos.tablasTexto = { cantidad: tablasTexto.length, resumen: resumen.map((r) => ({ cantidad: r.cantidad, offset: r.offsetTabla })) };
    console.log(`  · tablas de texto: ${tablasTexto.length} (la mayor de ${tablasTexto[0].n} entradas)`);
  }

  /* textos y diálogos */
  const cadenasGBA = GBA.buscarCadenasGBA(data, 12);
  if (cadenasGBA.length) {
    const dir = asegurar(join(salida, 'dialogos'));
    escribirJSON(join(dir, 'textos.json'), { total: cadenasGBA.length, textos: cadenasGBA });
    escribir(join(dir, 'dialogos.txt'), cadenasGBA.map((c) => `; 0x${c.offset.toString(16)}\n${c.texto}`).join('\n\n'));
    indice.hallazgos.textos = cadenasGBA.length;
    console.log(`  · textos/diálogos: ${cadenasGBA.length} cadenas`);
  }

  /* censo de bloques comprimidos → material de mapas y tiles */
  const censo = GBA.censoComprimidos(data);
  if (censo.length) {
    const dir = asegurar(join(salida, 'tiles'));
    escribirJSON(join(dir, 'censo_comprimidos.json'), { total: censo.length, bloques: censo });
    // una muestra de bloques con pinta de tileset se exporta como PNG
    const candidatos = censo.filter((b) => b.tam % 32 === 0 && b.tam >= 64 && b.tam <= 0x4000).slice(0, 60);
    const dirTiles = asegurar(join(dir, 'muestra'));
    const exportados = [];
    candidatos.forEach((b, i) => {
      const r = GBA.descomprimirEn(data, b.offset);
      if (!r) return;
      const tiles = Math.floor(r.tam / 32);
      const columnas = Math.min(16, tiles);
      const filas = Math.ceil(tiles / columnas);
      const img = GBA.tiles4bpp(r.datos, columnas, filas);
      const archivo = join(dirTiles, `tiles_${String(i).padStart(3, '0')}_0x${b.offset.toString(16)}.png`);
      escribir(archivo, pngIndizado(img.w, img.h, img.px, PALETA_VACIA));
      exportados.push({ offset: b.offset, tipo: b.tipo, tam: r.tam, tiles, archivo: archivo.replace(salida, '').replace(/^\//, '') });
    });
    escribirJSON(join(dirTiles, 'indice.json'), exportados);
    indice.hallazgos.tilesExportados = exportados.length;
    const porTamano = new Map();
    for (const b of censo) porTamano.set(b.tam, (porTamano.get(b.tam) || 0) + 1);
    escribirJSON(join(dir, 'tamanos.json'), [...porTamano.entries()].sort((a, b) => b[1] - a[1]).slice(0, 40));
    indice.hallazgos.bloquesComprimidos = censo.length;
    console.log(`  · bloques comprimidos: ${censo.length} (${censo.filter((b) => b.tipo === 'lz77').length} LZ77, ${censo.filter((b) => b.tipo === 'rle').length} RLE)`);
  }

  return indice;
}

/* ───────────────────────────────────── GB ─────────────────────────────── */

function forenseGB(data, salida, nombre) {
  const cabecera = GB.leerCabeceraGB(data);
  escribirJSON(join(salida, '00_cabecera.json'), cabecera);
  console.log(`  · cabecera: ${cabecera.titulo} (${cabecera.plataforma}, ${(data.length / 1048576).toFixed(1)} MB)`);
  const indice = { juego: nombre, plataforma: cabecera.plataforma, cabecera, hallazgos: {} };

  /* nombres de especie */
  const t = GB.buscarTablaNombresGB(data, 20);
  if (t) {
    escribirJSON(join(asegurar(join(salida, 'pokemon')), 'nombres.json'), {
      offsetTabla: t.base,
      cantidad: t.nombres.length,
      nombres: t.nombres,
      otrasCandidatas: t.candidatos,
    });
    indice.hallazgos.nombresEspecie = { offset: t.base, cantidad: t.nombres.length };
    console.log(`  · nombres de especie: ${t.nombres.length} (tabla 0x${t.base.toString(16)}) → ${t.nombres.slice(0, 6).map((n) => n.nombre).join(', ')}`);
  }

  /* sprites: se recorre la ROM buscando flujos válidos que encadenen */
  const dirSprites = asegurar(join(salida, 'sprites'));
  const buenos = new Map();
  for (let o = 0; o + 1 < data.length; o++) {
    const b = data[o];
    if (((b >> 4) & 0xf) < 1 || ((b >> 4) & 0xf) > 8 || (b & 0xf) < 1 || (b & 0xf) > 8) continue;
    const r = GB.descomprimirSprite(data, o, { variante: 'bandera' });
    if (!r) continue;
    if (pareceSprite(metricasSprite(r))) buenos.set(o, r);
  }
  const vistos = new Set();
  const cadenas = [];
  const ordenados = Array.from(buenos.keys()).sort((a, b) => a - b);
  for (const o of ordenados) {
    if (vistos.has(o)) continue;
    const cadena = [];
    let actual = o;
    while (buenos.has(actual) && !vistos.has(actual)) {
      vistos.add(actual);
      cadena.push({ offset: actual, sprite: buenos.get(actual) });
      actual += buenos.get(actual).consumido;
    }
    if (cadena.length >= 3) cadenas.push(cadena);
  }
  cadenas.sort((a, b) => b.length - a.length);
  const totalSprites = cadenas.reduce((n, c) => n + c.length, 0);
  const listado = [];
  cadenas.forEach((cadena, ci) => {
    const carpeta = asegurar(join(dirSprites, `cadena_${String(ci).padStart(2, '0')}_${cadena[0].sprite.ancho}x${cadena[0].sprite.alto}`));
    cadena.forEach(({ offset, sprite }, i) => {
      const archivo = join(carpeta, `${String(i).padStart(3, '0')}_0x${offset.toString(16)}.png`);
      escribir(archivo, pngIndizado(sprite.ancho, sprite.alto, sprite.px, PALETA_GRIS));
      listado.push({ cadena: ci, indice: i, offset, tamano: `${sprite.ancho}x${sprite.alto}`, bytes: sprite.consumido, modo: sprite.modo, archivo: archivo.replace(salida, '').replace(/^\//, '') });
    });
  });
  escribirJSON(join(dirSprites, 'indice.json'), { cadenas: cadenas.length, total: totalSprites, sprites: listado });
  indice.hallazgos.sprites = { cadenas: cadenas.length, total: totalSprites };
  console.log(`  · sprites: ${totalSprites} en ${cadenas.length} cadenas contiguas`);

  /* textos y diálogos */
  const cadenasTexto = GB.buscarCadenasGB(data, 12);
  if (cadenasTexto.length) {
    const dir = asegurar(join(salida, 'dialogos'));
    escribirJSON(join(dir, 'textos.json'), { total: cadenasTexto.length, textos: cadenasTexto });
    escribir(join(dir, 'dialogos.txt'), cadenasTexto.map((c) => `; 0x${c.offset.toString(16)}\n${c.texto}`).join('\n\n'));
    indice.hallazgos.textos = cadenasTexto.length;
    console.log(`  · textos/diálogos: ${cadenasTexto.length} cadenas`);
  }
  return indice;
}

/* ────────────────────────────────── programa ──────────────────────────── */

const roms = ROM_ARG ? [ROM_ARG] : existsSync(ROMS_DIR)
  ? readdirSync(ROMS_DIR).filter((f) => /\.(gba|gb|gbc)$/i.test(f)).map((f) => join(ROMS_DIR, f))
  : [];

if (!roms.length) {
  console.log(`No hay ROMs en ${ROMS_DIR}. Deja ahí los archivos .gba/.gb/.gbc.`);
  process.exit(0);
}

const resumenGeneral = [];
for (const ruta of roms) {
  const nombre = basename(ruta);
  const slug = slugDe(nombre);
  const salida = asegurar(join(ROMS_DIR, slug));
  console.log(`\n═══ ${nombre} ═══`);
  const data = readFileSync(ruta);
  const esGBA = /\.gba$/i.test(nombre);
  const indice = esGBA ? forenseGBA(data, salida, nombre) : forenseGB(data, salida, nombre);
  indice.rom = nombre;
  indice.slug = slug;
  escribirJSON(join(salida, '01_indice.json'), indice);
  resumenGeneral.push({ rom: nombre, slug, plataforma: indice.plataforma, hallazgos: indice.hallazgos });
}

escribirJSON(join(ROMS_DIR, '00_resumen.json'), { generado: new Date().toISOString(), roms: resumenGeneral });
console.log(`\n✔ Extracción forense terminada: ${resumenGeneral.length} ROM(s). Resumen en "roms pokemon/00_resumen.json"`);#!/usr/bin/env node
/**
 * Mapas, NPCs, cinemáticas y flags de un ROM hack de GBA (Pokémon Gen 3).
 *
 * Segunda fase del análisis de los ROM invitados. Trabaja sin offsets
 * prefijados: localiza las estructuras por su forma, igual que haría un
 * AdvanceMap, y a partir de ahí reconstruye el esqueleto jugable:
 *
 *   1. MapLayout   → ancho/alto, tilesets (primario y secundario)
 *   2. MapHeader   → música, tipo de mapa, tiempo, conexiones
 *   3. MapEvents   → NPCs (sprite, x, y, movimiento, tipo de entrenador,
 *                    script y flag), warps, triggers y signos
 *   4. Scripts     → minería de patrones sobre el bytecode para recuperar
 *                    los diálogos (msgbox), las flags usadas (setflag,
 *                    clearflag, checkflag), los combates (trainerbattle),
 *                    los movimientos de cámara/personaje y las entregas
 *
 * No es un desensamblador completo: es una minería por patrones sobre la
 * ventana de cada script, así que puede tener algún falso positivo. Lo que
 * importa es que da el *material* (textos, flags, batallas) para reescribir
 * estas escenas con contenido original en Atlas Mil.
 *
 * Uso:
 *   node tools/gba_maps_events.mjs --rom reference/roms_invitadas/entrada/GlazedESPB6.gba
 *   node tools/gba_maps_events.mjs --dir reference/roms_invitadas/entrada
 *
 * Salida (reference/roms_invitadas/<slug>/, ignorada por Git):
 *   mapas_npcs.json · informe_mapas.md · pbs/{npcs,cutscenes,flags,warps}.txt
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT_ROOT = () => (process.env.ROM_OUT_DIR ? path.resolve(process.env.ROM_OUT_DIR) : path.join(ROOT, "reference", "roms_invitadas"));

const arg = (name, fallback = null) => {
  const key = `--${name}`;
  const i = process.argv.indexOf(key);
  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : fallback;
};
const ROM = arg("rom");
const DIR = arg("dir");
const MAX_MAPS = Number(arg("max-maps", "0")) || 0;

// ------------------------------------------------------------------- charmap
const CHAR = new Array(256).fill(null);
{
  const set = (b, t) => (CHAR[b] = t);
  set(0x00, " ");
  for (let i = 0; i < 26; i += 1) set(0xbb + i, String.fromCharCode(65 + i));
  for (let i = 0; i < 26; i += 1) set(0xd5 + i, String.fromCharCode(97 + i));
  for (let i = 0; i < 10; i += 1) set(0xa1 + i, String(i));
  Object.entries({
    0xab: "!", 0xac: "?", 0xad: ".", 0xae: "-", 0xaf: "·", 0xb8: ",", 0xb9: "×", 0xba: "/",
    0xb5: "♂", 0xb6: "♀", 0xb0: "…", 0xf0: ":", 0x2d: "+", 0x2c: "&", 0x2f: ";",
    0x51: "¿", 0x52: "¡", 0x53: "[PK]", 0x54: "[MN]",
    0x01: "À", 0x02: "Á", 0x03: "Â", 0x04: "Ç", 0x05: "È", 0x06: "É", 0x07: "Ê", 0x08: "Ë",
    0x09: "Ì", 0x0a: "Í", 0x0b: "Î", 0x0c: "Ï", 0x0d: "Ò", 0x0e: "Ó", 0x0f: "Ô", 0x10: "Œ",
    0x11: "Ù", 0x12: "Ú", 0x13: "Û", 0x14: "Ñ", 0x15: "ß", 0x16: "à", 0x17: "á", 0x18: "â",
    0x19: "ç", 0x1a: "è", 0x1b: "é", 0x1c: "ê", 0x1d: "ë", 0x1e: "ì", 0x1f: "í", 0x20: "î",
    0x21: "ï", 0x22: "ò", 0x23: "ó", 0x24: "ô", 0x25: "œ", 0x26: "ù", 0x27: "ú", 0x28: "û",
    0x29: "ñ", 0x2a: "º", 0x2b: "ª",
  }).forEach(([b, t]) => set(Number(b), t));
  for (let b = 0xf7; b <= 0xfe; b += 1) set(b, "");
}
const textoEn = (data, off, max = 400) => {
  let out = "";
  for (let i = 0; i < max; i += 1) {
    const b = data[off + i];
    if (b === undefined) break;
    if (b === 0xff) break;
    const c = CHAR[b];
    out += c === null || c === undefined ? "" : c;
  }
  return out.replace(/\s+/g, " ").trim();
};

const u32 = (d, o) => (d[o] | (d[o + 1] << 8) | (d[o + 2] << 16) | (d[o + 3] << 24)) >>> 0;
const u16 = (d, o) => d[o] | (d[o + 1] << 8);
const s16 = (d, o) => {
  const v = u16(d, o);
  return v > 0x7fff ? v - 0x10000 : v;
};
const esPtr = (v, len) => v >= 0x08000000 && v - 0x08000000 < len - 4;

// --------------------------------------------------------------- MapLayout
// struct MapLayout { s32 width; s32 height; u16* border; u16* map;
//                    Tileset* primary; Tileset* secondary; u8 bw; u8 bh; }
/** struct Tileset { u8 isCompressed; u8 isSecondary; ptr tiles; ptr palettes;
 *                   ptr metatiles; ptr metatileAttrs; … } */
function tilesetValido(data, ptr, len) {
  const o = ptr - 0x08000000;
  if (o < 0 || o + 24 >= len) return false;
  if (data[o] > 1 || data[o + 1] > 1) return false;
  const validos = [4, 8, 12, 16].filter((k) => esPtr(u32(data, o + k), len)).length;
  return validos >= 3;
}

function buscarMapLayouts(data) {
  const len = data.length;
  const hallados = [];
  for (let off = 0; off + 26 <= len; off += 4) {
    const width = u32(data, off);
    if (width < 8 || width > 200) continue;
    const height = u32(data, off + 4);
    if (height < 8 || height > 200) continue;
    const border = u32(data, off + 8);
    if (!esPtr(border, len)) continue;
    const map = u32(data, off + 12);
    if (!esPtr(map, len)) continue;
    const prim = u32(data, off + 16);
    const sec = u32(data, off + 20);
    if (!esPtr(prim, len) || !esPtr(sec, len)) continue;
    // Un hack puede servir el mapa comprimido (LZ77, mágico 0x10) o sin comprimir:
    // lo que decide es que los dos tilesets apunten a estructuras coherentes.
    if (!tilesetValido(data, prim, len) && !tilesetValido(data, sec, len)) continue;
    const bw = data[off + 24];
    const bh = data[off + 25];
    if (bw > 8 || bh > 8) continue;
    hallados.push({ off, width, height, map, prim, sec, bw, bh, comprimido: data[map - 0x08000000] === 0x10 });
  }
  return hallados;
}

/** Índice inverso: para cada dirección objetivo, qué posiciones la apuntan. */
function indiceInverso(data, objetivos) {
  const set = new Set(objetivos);
  const idx = new Map();
  const len = data.length - 3;
  for (let off = 0; off < len; off += 1) {
    const v = u32(data, off);
    if (!set.has(v)) continue;
    if (!idx.has(v)) idx.set(v, []);
    idx.get(v).push(off);
  }
  return idx;
}

// --------------------------------------------------------------- MapHeader
// struct MapHeader { MapLayout* mapLayout (0x00); MapEvents* events (0x04);
//   MapScripts* scripts (0x08); MapConnections* connections (0x0C);
//   u16 music (0x10); u16 mapLayoutId (0x12); u8 regionMapSectionId (0x14);
//   u8 weather (0x15); u8 mapType (0x16); u8 filler (0x17); ... }
function buscarHeaders(data, layouts) {
  const len = data.length;
  const idx = indiceInverso(data, layouts.map((l) => l.off + 0x08000000));
  const headers = [];
  for (const layout of layouts) {
    const refs = idx.get(layout.off + 0x08000000) || [];
    for (const ref of refs) {
      const events = u32(data, ref + 4);
      if (!esPtr(events, len)) continue;
      const scripts = u32(data, ref + 8);
      if (!esPtr(scripts, len)) continue;
      const conns = u32(data, ref + 12);
      if (conns !== 0 && !esPtr(conns, len)) continue;
      const music = u16(data, ref + 16);
      if (music > 0x600) continue;
      const weather = data[ref + 0x15];
      if (weather > 20) continue;
      const mapType = data[ref + 0x16];
      if (mapType > 12) continue;
      headers.push({ off: ref, layout, events, scripts, conns, music, weather, mapType });
      break;
    }
  }
  return headers;
}

/** Agrupa las referencias a headers en bancos: punteros contiguos. */
function buscarBancos(data, headers) {
  const idx = indiceInverso(data, headers.map((h) => h.off + 0x08000000));
  const referencias = [];
  for (const h of headers) {
    for (const ref of idx.get(h.off + 0x08000000) || []) referencias.push({ ref, header: h });
  }
  referencias.sort((a, b) => a.ref - b.ref);
  const bancos = [];
  let actual = [];
  for (const r of referencias) {
    if (actual.length && r.ref === actual[actual.length - 1].ref + 4) actual.push(r);
    else {
      if (actual.length >= 3) bancos.push(actual);
      actual = [r];
    }
  }
  if (actual.length >= 3) bancos.push(actual);
  return bancos.filter((b) => b.length >= 3);
}

// ----------------------------------------------------------------- eventos
// struct MapEvents { u8 numNPCs; u8 numWarps; u8 numTriggers; u8 numSigns;
//                    ObjectEvent* npcs; WarpEvent* warps; CoordEvent* triggers; BgEvent* signs; }
// struct ObjectEvent (tabla estática) { u8 localId; u8 graphicsId; u8 kind; u8 pad;
//   s16 x; s16 y; u8 elevation; u8 movementType; u8 rangeX:4/rangeY:4;
//   u16 trainerType; u16 trainerRange; u8* script; u16 flagId; u8 filler[2]; } = 24 bytes
const NPC_SIZE = 24;
function leerEventos(data, eventsPtr) {
  const off = eventsPtr - 0x08000000;
  if (off < 0 || off + 20 > data.length) return null;
  const numNpcs = data[off];
  const numWarps = data[off + 1];
  const numTriggers = data[off + 2];
  const numSigns = data[off + 3];
  const npcs = [];
  const npcPtr = u32(data, off + 4);
  if (esPtr(npcPtr, data.length) && numNpcs > 0 && numNpcs < 200) {
    const base = npcPtr - 0x08000000;
    for (let i = 0; i < numNpcs; i += 1) {
      const o = base + i * NPC_SIZE;
      if (o + NPC_SIZE > data.length) break;
      npcs.push({
        localId: data[o + 0],
        sprite: data[o + 1],
        x: s16(data, o + 4),
        y: s16(data, o + 6),
        elevation: data[o + 8],
        movimiento: data[o + 9],
        tipoEntrenador: u16(data, o + 0x0c),
        rangoEntrenador: u16(data, o + 0x0e),
        script: u32(data, o + 0x10),
        flag: u16(data, o + 0x14),
      });
    }
  }
  const warps = [];
  const warpPtr = u32(data, off + 8);
  if (esPtr(warpPtr, data.length) && numWarps > 0 && numWarps < 100) {
    const base = warpPtr - 0x08000000;
    for (let i = 0; i < numWarps; i += 1) {
      const o = base + i * 8;
      if (o + 8 > data.length) break;
      // WarpEvent Gen III: x, y, elevation, warpId, mapNum, mapGroup.
      // Antes estos dos últimos bytes se publicaban como «destino/salida», lo
      // que impedía reconstruir el grafo completo entre bancos.
      warps.push({
        x: s16(data, o), y: s16(data, o + 2), elevation: data[o + 4],
        warpId: data[o + 5], mapaDestino: data[o + 6], bancoDestino: data[o + 7],
      });
    }
  }
  return { numNpcs, numWarps, numTriggers, numSigns, npcs, warps, npcPtr, warpPtr };
}

// ----------------------------------------------------------------- scripts
// Minería de patrones sobre la ventana de cada script. Los opcodes usados
// están comprobados sobre la ROM (lock/faceplayer, loadpointer+callstd,
// checkflag/setflag/clearflag, setvar, applymovement); no es un desensamblado
// completo, así que puede haber algún falso positivo, pero no pierde diálogos.
//
// Opcodes validados en Glazed (base Esmeralda):
//   0x02 end · 0x03 return · 0x04 call · 0x05 goto · 0x06 goto_if <cond> <ptr>
//   0x09 callstd <tipo>   · 0x0F loadpointer <banco> <ptr>   (el texto)
//   0x16 setvar <var> <valor> · 0x17 addvar · 0x18 subvar
//   0x29 setflag · 0x2A clearflag · 0x2B checkflag
//   0x4F applymovement <id> <ptr> · 0x51 waitmovement <id>
//   0x5A faceplayer · 0x6A lock · 0x6B release
const VENTANA = 2048;
function minarScript(data, ptr) {
  const start = ptr - 0x08000000;
  if (start < 0 || start >= data.length) return null;
  const fin = Math.min(data.length, start + VENTANA);
  const pasos = [];
  const flags = new Set();
  const variables = new Set();
  const textos = [];
  for (let o = start; o < fin - 6; o += 1) {
    const op = data[o];
    // loadpointer <banco> <ptr>: es como se muestra un diálogo (msgbox).
    if (op === 0x0f && data[o + 1] <= 0x02) {
      const p = u32(data, o + 2);
      if (esPtr(p, data.length)) {
        const t = textoEn(data, p - 0x08000000);
        if (t.length > 3 && !/\{[0-9a-f]{2}\}/.test(t.slice(0, 60))) {
          textos.push(t);
          pasos.push({ tipo: "texto", en: o - start, valor: t.slice(0, 240) });
        }
        o += 5;
      }
      continue;
    }
    if (op === 0x09) {
      pasos.push({ tipo: "llamada_estandar", en: o - start, valor: data[o + 1] });
      o += 1;
      continue;
    }
    if (op === 0x29 || op === 0x2a || op === 0x2b) {
      const flag = u16(data, o + 1);
      if (flag > 0 && flag < 0x4000) {
        flags.add(flag);
        pasos.push({ tipo: op === 0x29 ? "setflag" : op === 0x2a ? "clearflag" : "checkflag", en: o - start, valor: flag });
      }
      o += 2;
      continue;
    }
    if (op === 0x16 || op === 0x17 || op === 0x18) {
      const variable = u16(data, o + 1);
      if (variable >= 0x4000 && variable < 0x9000) {
        variables.add(variable);
        pasos.push({ tipo: op === 0x16 ? "setvar" : op === 0x17 ? "addvar" : "subvar", en: o - start, valor: variable });
      }
      o += 4;
      continue;
    }
    if (op === 0x4f) {
      const p = u32(data, o + 3);
      if (esPtr(p, data.length)) pasos.push({ tipo: "movimiento", en: o - start, valor: u16(data, o + 1) });
      o += 6;
      continue;
    }
    if (op === 0x51) {
      pasos.push({ tipo: "esperar_movimiento", en: o - start, valor: u16(data, o + 1) });
      o += 2;
      continue;
    }
    if (op === 0x5a) {
      pasos.push({ tipo: "mirar_jugador", en: o - start });
      continue;
    }
    if (op === 0x6a) {
      pasos.push({ tipo: "bloquear", en: o - start });
      continue;
    }
    if (op === 0x6b) {
      pasos.push({ tipo: "liberar", en: o - start });
      continue;
    }
    if (op === 0x02 || op === 0x03) {
      pasos.push({ tipo: op === 0x02 ? "fin" : "retorno", en: o - start });
      if (o - start > 8) break; // fin plausible del script
      continue;
    }
  }
  if (!pasos.length) return null;
  return { pasos: pasos.sort((a, b) => a.en - b.en).slice(0, 40), textos, flags: [...flags], variables: [...variables] };
}

// ------------------------------------------------------------------ informe
function analizar(file) {
  const data = fs.readFileSync(file);
  const t0 = Date.now();
  const slug = path.basename(file).replace(/\.(gba|gb|gbc)$/i, "");
  const layouts = buscarMapLayouts(data);
  const headers = buscarHeaders(data, layouts);
  const bancos = buscarBancos(data, headers);

  const mapas = [];
  let vistos = 0;
  for (let bancoId = 0; bancoId < bancos.length; bancoId += 1) {
    const banco = bancos[bancoId];
    for (let i = 0; i < banco.length; i += 1) {
      const h = banco[i].header;
      const eventos = leerEventos(data, h.events) || { npcs: [], warps: [] };
      const scripts = [];
      const flags = new Set();
      const variables = new Set();
      const textos = [];
      for (const npc of eventos.npcs || []) {
        const s = minarScript(data, npc.script);
        if (s) {
          scripts.push({ npc: npc.localId, sprite: npc.sprite, x: npc.x, y: npc.y, tipoEntrenador: npc.tipoEntrenador, pasos: s.pasos, textos: s.textos.slice(0, 3) });
          for (const f of s.flags) flags.add(f);
          textos.push(...s.textos.slice(0, 2));
          for (const v of s.variables || []) variables.add(v);
        }
        if (npc.flag) flags.add(npc.flag);
      }
      mapas.push({
        banco: bancoId,
        indice: i,
        header: h.off,
        ancho: h.layout.width,
        alto: h.layout.height,
        musica: h.music,
        clima: h.weather,
        tipo: h.mapType,
        npcs: (eventos.npcs || []).length,
        warps: (eventos.warps || []).length,
        warpsDetalle: eventos.warps || [],
        npcsDetalle: eventos.npcs || [],
        scripts,
        flags: [...flags],
        variables: [...variables],
        textos: textos.slice(0, 3),
      });
      vistos += 1;
      if (MAX_MAPS && vistos >= MAX_MAPS) break;
    }
    if (MAX_MAPS && vistos >= MAX_MAPS) break;
  }

  const totalNpcs = mapas.reduce((a, m) => a + m.npcs, 0);
  const totalTextos = mapas.reduce((a, m) => a + m.scripts.reduce((b, s) => b + (s.textos.length || 0), 0), 0);
  const flagsGlobal = new Map();
  for (const m of mapas) for (const f of m.flags) flagsGlobal.set(f, (flagsGlobal.get(f) || 0) + 1);
  const variablesGlobal = new Set();
  for (const m of mapas) for (const v of m.variables) variablesGlobal.add(v);

  const salida = {
    slug,
    rom: path.basename(file),
    generadoEn: new Date().toISOString(),
    resumen: {
      duracionSegundos: Number(((Date.now() - t0) / 1000).toFixed(1)),
      layouts: layouts.length,
      headers: headers.length,
      bancos: bancos.length,
      mapas: mapas.length,
      npcs: totalNpcs,
      lineasDialogo: totalTextos,
      flagsDistintas: flagsGlobal.size,
      variablesDistintas: variablesGlobal.size,
    },
    mapas,
    flagsMasUsadas: [...flagsGlobal.entries()].sort((a, b) => b[1] - a[1]).slice(0, 60),
  };

  const outDir = path.join(OUT_ROOT(), slug);
  fs.mkdirSync(path.join(outDir, "pbs"), { recursive: true });
  fs.writeFileSync(path.join(outDir, "mapas_npcs.json"), `${JSON.stringify(salida, null, 2)}\n`);

  // NPC por mapa
  const lineasNpc = mapas.map(
    (m) => `MAPA header=0x${m.header.toString(16).toUpperCase()} ${m.ancho}×${m.alto} música=${m.musica} clima=${m.clima} tipo=${m.tipo} · ${m.npcs} NPCs, ${m.warps} warps\n` +
      m.npcsDetalle.map((n) => `  NPC local=${n.localId} sprite=${n.sprite} (${n.x},${n.y}) mov=${n.movimiento} entrenador=${n.tipoEntrenador} rango=${n.rangoEntrenador} flag=${n.flag} script=0x${(n.script >>> 0).toString(16).toUpperCase()}`).join("\n")
  );
  fs.writeFileSync(path.join(outDir, "pbs", "npcs.txt"), `# ${totalNpcs} NPCs en ${mapas.length} mapas\n${lineasNpc.join("\n")}\n`);

  // Cinemáticas: secuencia de pasos por NPC con diálogo
  const lineasCut = [];
  for (const m of mapas) {
    if (!m.scripts.length) continue;
    lineasCut.push(`# ============================== MAPA 0x${m.header.toString(16).toUpperCase()} (${m.ancho}×${m.alto})`);
    for (const s of m.scripts) {
      lineasCut.push(`--- NPC ${s.npc} (sprite ${s.sprite}) en (${s.x},${s.y})${s.tipoEntrenador ? ` · entrenador ${s.tipoEntrenador}` : ""}`);
      for (const paso of s.pasos) {
        if (paso.tipo === "texto") lineasCut.push(`    «${paso.valor}»`);
        else lineasCut.push(`    [${paso.tipo}] ${paso.valor ?? ""}`);
      }
    }
  }
  fs.writeFileSync(path.join(outDir, "pbs", "cutscenes.txt"), `# Cinemáticas reconstruidas: ${mapas.length} mapas\n${lineasCut.join("\n")}\n`);

  // Flags con ejemplo de texto
  const ejemploPorFlag = new Map();
  for (const m of mapas) {
    for (const s of m.scripts) {
      for (const f of m.flags) {
        if (!ejemploPorFlag.has(f) && s.textos.length) ejemploPorFlag.set(f, s.textos[0].slice(0, 120));
      }
    }
  }
  fs.writeFileSync(
    path.join(outDir, "pbs", "flags.txt"),
    `# ${flagsGlobal.size} flags detectadas en scripts y NPCs\n` +
      salida.flagsMasUsadas.map(([f, n]) => `FLAG 0x${f.toString(16).toUpperCase()} (${f})\tusos=${n}\tejemplo: ${ejemploPorFlag.get(f) || "—"}`).join("\n") +
      "\n"
  );

  const informe = `# Mapas, NPCs y cinemáticas: ${salida.rom}

Generado ${salida.generadoEn} en ${salida.resumen.duracionSegundos}s · _minería de patrones, no desensamblado_

| Dato | Valor |
|---|---:|
| MapLayouts detectados | ${salida.resumen.layouts} |
| Cabeceras de mapa | ${salida.resumen.headers} |
| Bancos de mapas | ${salida.resumen.bancos} |
| Mapas reconstruidos | ${salida.resumen.mapas} |
| NPCs | ${salida.resumen.npcs} |
| Líneas de diálogo recuperadas | ${salida.resumen.lineasDialogo} |
| Flags distintas | ${salida.resumen.flagsDistintas} |
| Variables distintas | ${salida.resumen.variablesDistintas} |

## Flags más usadas

${salida.flagsMasUsadas.slice(0, 20).map(([f, n]) => `- **0x${f.toString(16).toUpperCase()}** (${f}) — ${n} usos · _${ejemploPorFlag.get(f) || "sin ejemplo"}_`).join("\n")}

## Mapas con más NPCs

${mapas
  .slice()
  .sort((a, b) => b.npcs - a.npcs)
  .slice(0, 12)
  .map((m) => `- 0x${m.header.toString(16).toUpperCase()} · ${m.ancho}×${m.alto} · música ${m.musica} · ${m.npcs} NPCs, ${m.warps} warps`)
  .join("\n")}

## Ejemplo de cinemática reconstruida

${
  (mapas.find((m) => m.scripts.length && m.scripts.some((s) => s.textos.length)) || { scripts: [] }).scripts
    .slice(0, 1)
    .map((s) => s.pasos.slice(0, 14).map((p) => (p.tipo === "texto" ? `> ${p.valor}` : `- [${p.tipo}] ${p.valor ?? ""}`)).join("\n"))
}
`;
  fs.writeFileSync(path.join(outDir, "informe_mapas.md"), informe);
  console.log(
    `${slug}: ${salida.resumen.mapas} mapas · ${totalNpcs} NPCs · ${salida.resumen.lineasDialogo} diálogos · ` +
      `${salida.resumen.flagsDistintas} flags · ${salida.resumen.variablesDistintas} variables (${salida.resumen.duracionSegundos}s)`
  );
  return salida;
}

const objetivos = ROM
  ? [ROM]
  : DIR
    ? fs.readdirSync(DIR).filter((f) => /\.gba$/i.test(f)).map((f) => path.join(DIR, f))
    : [];
if (!objetivos.length) {
  console.log("Uso: node tools/gba_maps_events.mjs --rom <archivo.gba> | --dir <carpeta>");
  process.exit(1);
}
for (const objetivo of objetivos) analizar(objetivo);#!/usr/bin/env node
/**
 * generar_assets_pokegods.mjs — convierte el arte conceptual de los Pokégods
 * en los formatos reales del proyecto Fire Ash.
 *
 *   Graphics/Pokemon/Front/<NOMBRE>.png      96×96   (vista frontal)
 *   Graphics/Pokemon/Back/<NOMBRE>.png       96×96   (vista trasera)
 *   Graphics/Pokemon/Icons/<NOMBRE>.png     128×64   (hoja de 8 iconos 32×32)
 *   Graphics/Characters/<NOMBRE>.png        256×256  (hoja 4×4 de 64×64:
 *                                                    fila 0 abajo, 1 izq.,
 *                                                    2 dcha., 3 arriba)
 *
 * El proceso es 100 % por código: quita el fondo blanco, recorta, reescala con
 * conservación de proporción, reduce la paleta (median cut) y compone las hojas.
 *
 * Uso:
 *   node tools/generar_assets_pokegods.mjs [--src reference/pokegods/concepto]
 *                                          [--juego pokemon_fire_ash]
 *                                          [--colores 48]
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync } from 'node:fs';
import { inflateSync, deflateSync } from 'node:zlib';
import { join, basename } from 'node:path';

/* ───────────────────────────────── PNG ───────────────────────────────── */

const TABLA_CRC = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();

function crc32(buf) {
  let c = -1;
  for (let i = 0; i < buf.length; i++) c = TABLA_CRC[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
}

function chunk(tipo, datos) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(datos.length);
  const td = Buffer.concat([Buffer.from(tipo, 'ascii'), datos]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}

/** Decodifica un PNG (8 bits, tipos 0/2/3/4/6) a RGBA. */
export function decodificarPNG(ruta) {
  const d = readFileSync(ruta);
  let i = 8;
  const idat = [];
  let w = 0, h = 0, prof = 8, ctype = 6, plte = null, trns = null;
  while (i < d.length) {
    const ln = d.readUInt32BE(i);
    const tipo = d.subarray(i + 4, i + 8).toString('ascii');
    const dat = d.subarray(i + 8, i + 8 + ln);
    if (tipo === 'IHDR') { w = dat.readUInt32BE(0); h = dat.readUInt32BE(4); prof = dat[8]; ctype = dat[9]; }
    else if (tipo === 'IDAT') idat.push(dat);
    else if (tipo === 'PLTE') plte = dat;
    else if (tipo === 'tRNS') trns = dat;
    i += 12 + ln;
  }
  if (![1, 2, 4, 8].includes(prof)) throw new Error(`profundidad de bits no soportada: ${prof}`);
  const raw = inflateSync(Buffer.concat(idat));
  const canales = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ctype];
  const bpp = Math.max(1, Math.floor(canales * prof / 8));   // bytes por píxel (filtro)
  const stride = Math.ceil(w * canales * prof / 8);          // bytes por fila
  const px = Buffer.alloc(h * stride);
  let p = 0;
  let prev = Buffer.alloc(stride);
  for (let y = 0; y < h; y++) {
    const f = raw[p++];
    const fila = Buffer.from(raw.subarray(p, p + stride));
    p += stride;
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? fila[x - bpp] : 0;
      const b = prev[x];
      const c = x >= bpp ? prev[x - bpp] : 0;
      if (f === 1) fila[x] = (fila[x] + a) & 255;
      else if (f === 2) fila[x] = (fila[x] + b) & 255;
      else if (f === 3) fila[x] = (fila[x] + ((a + b) >> 1)) & 255;
      else if (f === 4) {
        const pp = a + b - c;
        const pa = Math.abs(pp - a), pb = Math.abs(pp - b), pc = Math.abs(pp - c);
        const pr = (pa <= pb && pa <= pc) ? a : (pb <= pc ? b : c);
        fila[x] = (fila[x] + pr) & 255;
      }
    }
    fila.copy(px, y * stride);
    prev = fila;
  }
  const rgba = new Uint8Array(w * h * 4);
  // índice de un píxel para imágenes indexadas / escala de grises de < 8 bits
  const indice = (x, y) => {
    if (prof === 8) return px[y * stride + x * canales];
    const bitPos = y * stride * 8 + x * canales * prof;
    const byte = px[bitPos >> 3];
    const shift = 8 - prof - (bitPos & 7);
    return (byte >> shift) & ((1 << prof) - 1);
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = y * stride + x * bpp;
      const o = (y * w + x) * 4;
      if (ctype === 6) { rgba[o] = px[s]; rgba[o + 1] = px[s + 1]; rgba[o + 2] = px[s + 2]; rgba[o + 3] = px[s + 3]; }
      else if (ctype === 2) { rgba[o] = px[s]; rgba[o + 1] = px[s + 1]; rgba[o + 2] = px[s + 2]; rgba[o + 3] = 255; }
      else if (ctype === 0) {
        const v = prof === 8 ? px[s] : Math.round(indice(x, y) * 255 / ((1 << prof) - 1));
        rgba[o] = rgba[o + 1] = rgba[o + 2] = v; rgba[o + 3] = 255;
      }
      else if (ctype === 4) { rgba[o] = rgba[o + 1] = rgba[o + 2] = px[s]; rgba[o + 3] = px[s + 1]; }
      else if (ctype === 3) {
        const idx = indice(x, y);
        rgba[o] = plte[idx * 3]; rgba[o + 1] = plte[idx * 3 + 1]; rgba[o + 2] = plte[idx * 3 + 2];
        rgba[o + 3] = trns && idx < trns.length ? trns[idx] : 255;
      }
    }
  }
  return { w, h, rgba };
}

/** Escribe un PNG RGBA de 8 bits. */
export function escribirPNG(ruta, w, h, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  let p = 0;
  for (let y = 0; y < h; y++) {
    raw[p++] = 0;
    for (let x = 0; x < w * 4; x++) raw[p++] = rgba[y * w * 4 + x];
  }
  mkdirSync(ruta.substring(0, ruta.lastIndexOf('/')), { recursive: true });
  writeFileSync(ruta, Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]));
}

/* ────────────────────────────── procesado ────────────────────────────── */

/** Quita el fondo blanco por inundación desde los bordes. */
export function quitarFondo(img, umbral = 232) {
  const { w, h, rgba } = img;
  const alpha = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) alpha[i] = rgba[i * 4 + 3] > 8 ? 1 : 0;
  const esBlanco = (i) => {
    const o = i * 4;
    return alpha[i] === 1 && rgba[o] >= umbral && rgba[o + 1] >= umbral && rgba[o + 2] >= umbral;
  };
  const cola = [];
  for (let x = 0; x < w; x++) { if (esBlanco(x)) cola.push(x); if (esBlanco((h - 1) * w + x)) cola.push((h - 1) * w + x); }
  for (let y = 0; y < h; y++) { if (esBlanco(y * w)) cola.push(y * w); if (esBlanco(y * w + w - 1)) cola.push(y * w + w - 1); }
  while (cola.length) {
    const i = cola.pop();
    if (!esBlanco(i)) continue;
    alpha[i] = 0;
    const x = i % w, y = (i - x) / w;
    if (x > 0) cola.push(i - 1);
    if (x < w - 1) cola.push(i + 1);
    if (y > 0) cola.push(i - w);
    if (y < h - 1) cola.push(i + w);
  }
  // bordes suaves: los píxeles casi blancos pegados al fondo se atenúan
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (alpha[i] !== 1) continue;
      const o = i * 4;
      const min = Math.min(rgba[o], rgba[o + 1], rgba[o + 2]);
      if (min < 200) continue;
      let vecinoFondo = false;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx, ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (alpha[ny * w + nx] === 0) { vecinoFondo = true; break; }
      }
      if (vecinoFondo) alpha[i] = Math.max(0, Math.min(1, (255 - min) / 48));
    }
  }
  const salida = new Uint8Array(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    salida[i * 4] = rgba[i * 4];
    salida[i * 4 + 1] = rgba[i * 4 + 1];
    salida[i * 4 + 2] = rgba[i * 4 + 2];
    salida[i * 4 + 3] = Math.round(alpha[i] * (rgba[i * 4 + 3] / 255) * 255);
  }
  return { w, h, rgba: salida };
}

/** Caja envolvente de los píxeles opacos. */
function recortar(img) {
  const { w, h, rgba } = img;
  let x0 = w, y0 = h, x1 = -1, y1 = -1;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (rgba[(y * w + x) * 4 + 3] > 12) {
        if (x < x0) x0 = x; if (x > x1) x1 = x;
        if (y < y0) y0 = y; if (y > y1) y1 = y;
      }
    }
  }
  if (x1 < 0) return img;
  const nw = x1 - x0 + 1, nh = y1 - y0 + 1;
  const out = new Uint8Array(nw * nh * 4);
  for (let y = 0; y < nh; y++) {
    for (let x = 0; x < nw; x++) {
      const s = ((y + y0) * w + (x + x0)) * 4, d = (y * nw + x) * 4;
      out[d] = rgba[s]; out[d + 1] = rgba[s + 1]; out[d + 2] = rgba[s + 2]; out[d + 3] = rgba[s + 3];
    }
  }
  return { w: nw, h: nh, rgba: out };
}

/** Reescalado bilineal con alfa. */
export function escalar(img, nw, nh) {
  const { w, h, rgba } = img;
  const out = new Uint8Array(nw * nh * 4);
  for (let y = 0; y < nh; y++) {
    const sy = (y + 0.5) * h / nh - 0.5;
    const y0 = Math.max(0, Math.floor(sy)), y1 = Math.min(h - 1, y0 + 1);
    const fy = sy - y0;
    for (let x = 0; x < nw; x++) {
      const sx = (x + 0.5) * w / nw - 0.5;
      const x0 = Math.max(0, Math.floor(sx)), x1 = Math.min(w - 1, x0 + 1);
      const fx = sx - x0;
      const i00 = (y0 * w + x0) * 4, i10 = (y0 * w + x1) * 4;
      const i01 = (y1 * w + x0) * 4, i11 = (y1 * w + x1) * 4;
      const d = (y * nw + x) * 4;
      for (let c = 0; c < 4; c++) {
        const a = rgba[i00 + c] * (1 - fx) + rgba[i10 + c] * fx;
        const b = rgba[i01 + c] * (1 - fx) + rgba[i11 + c] * fx;
        out[d + c] = Math.round(a * (1 - fy) + b * fy);
      }
    }
  }
  return { w: nw, h: nh, rgba: out };
}

/** Reduce la paleta con median cut (sólo píxeles opacos). */
export function reducirPaleta(img, n = 48) {
  const { w, h, rgba } = img;
  const puntos = [];
  for (let i = 0; i < w * h; i++) {
    if (rgba[i * 4 + 3] > 8) puntos.push([rgba[i * 4], rgba[i * 4 + 1], rgba[i * 4 + 2], i]);
  }
  if (puntos.length < n) return img;
  let cajas = [puntos];
  while (cajas.length < n) {
    let bi = -1, mejor = -1;
    for (let k = 0; k < cajas.length; k++) {
      if (cajas[k].length < 2) continue;
      const cj = cajas[k];
      const mn = [255, 255, 255], mx = [0, 0, 0];
      for (const p of cj) for (let c = 0; c < 3; c++) { if (p[c] < mn[c]) mn[c] = p[c]; if (p[c] > mx[c]) mx[c] = p[c]; }
      const rango = Math.max(mx[0] - mn[0], mx[1] - mn[1], mx[2] - mn[2]);
      if (rango > mejor) { mejor = rango; bi = k; }
    }
    if (bi < 0 || mejor <= 0) break;
    const cj = cajas[bi];
    const mn = [255, 255, 255], mx = [0, 0, 0];
    for (const p of cj) for (let c = 0; c < 3; c++) { if (p[c] < mn[c]) mn[c] = p[c]; if (p[c] > mx[c]) mx[c] = p[c]; }
    let ch = 0, m = -1;
    for (let c = 0; c < 3; c++) { const d = mx[c] - mn[c]; if (d > m) { m = d; ch = c; } }
    cj.sort((a, b) => a[ch] - b[ch]);
    const mitad = cj.length >> 1;
    cajas.splice(bi, 1, cj.slice(0, mitad), cj.slice(mitad));
  }
  const salida = new Uint8Array(rgba);
  for (const cj of cajas) {
    if (!cj.length) continue;
    let r = 0, g = 0, b = 0;
    for (const p of cj) { r += p[0]; g += p[1]; b += p[2]; }
    r = Math.round(r / cj.length); g = Math.round(g / cj.length); b = Math.round(b / cj.length);
    for (const p of cj) { const o = p[3] * 4; salida[o] = r; salida[o + 1] = g; salida[o + 2] = b; }
  }
  return { w, h, rgba: salida };
}

/** Coloca la imagen centrada en un lienzo cuadrado, conservando proporción. */
export function encajarEn(img, lado) {
  const esc = Math.min(lado / img.w, lado / img.h);
  const red = escalar(img, Math.max(1, Math.round(img.w * esc)), Math.max(1, Math.round(img.h * esc)));
  const lienzo = new Uint8Array(lado * lado * 4);
  const ox = Math.floor((lado - red.w) / 2), oy = Math.floor((lado - red.h) / 2);
  for (let y = 0; y < red.h; y++) {
    for (let x = 0; x < red.w; x++) {
      const s = (y * red.w + x) * 4, d = ((y + oy) * lado + (x + ox)) * 4;
      lienzo[d] = red.rgba[s]; lienzo[d + 1] = red.rgba[s + 1];
      lienzo[d + 2] = red.rgba[s + 2]; lienzo[d + 3] = red.rgba[s + 3];
    }
  }
  return { w: lado, h: lado, rgba: lienzo };
}

function espejar(img) {
  const { w, h, rgba } = img;
  const out = new Uint8Array(rgba.length);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = (y * w + x) * 4, d = (y * w + (w - 1 - x)) * 4;
      out[d] = rgba[s]; out[d + 1] = rgba[s + 1]; out[d + 2] = rgba[s + 2]; out[d + 3] = rgba[s + 3];
    }
  }
  return { w, h, rgba: out };
}

function pegar(lienzo, lado, img, celdaX, celdaY, tamCelda) {
  const enc = encajarEn(img, tamCelda);
  for (let y = 0; y < enc.h; y++) {
    for (let x = 0; x < enc.w; x++) {
      const s = (y * enc.w + x) * 4;
      const d = ((celdaY * tamCelda + y) * lado + celdaX * tamCelda + x) * 4;
      lienzo[d] = enc.rgba[s]; lienzo[d + 1] = enc.rgba[s + 1];
      lienzo[d + 2] = enc.rgba[s + 2]; lienzo[d + 3] = enc.rgba[s + 3];
    }
  }
}

/** Prepara el arte: quita el fondo y recorta (la paleta se reduce al final,
 *  ya reescalado, para que la interpolación no vuelva a crear colores). */
export function preparar(ruta) {
  let img = decodificarPNG(ruta);
  img = quitarFondo(img);
  img = recortar(img);
  return img;
}

/* ──────────────────────────────── programa ───────────────────────────── */

function main() {
  const args = process.argv.slice(2);
  const get = (k, def) => (args.includes(k) ? args[args.indexOf(k) + 1] : def);
  const src = get('--src', 'reference/pokegods/concepto');
  const juego = get('--juego', 'pokemon_fire_ash');
  const colores = parseInt(get('--colores', '48'), 10);

  if (!existsSync(src)) { console.error(`No existe ${src}`); process.exit(1); }
  const frentes = readdirSync(src).filter((f) => /\.png$/i.test(f) && !/_back\.png$/i.test(f));
  if (!frentes.length) { console.error(`No hay arte en ${src}`); process.exit(1); }

  const gFront = join(juego, 'Graphics/Pokemon/Front');
  const gBack = join(juego, 'Graphics/Pokemon/Back');
  const gIcons = join(juego, 'Graphics/Pokemon/Icons');
  const gChars = join(juego, 'Graphics/Characters');
  for (const d of [gFront, gBack, gIcons, gChars]) mkdirSync(d, { recursive: true });

  const manifesto = [];
  for (const f of frentes.sort()) {
    const nombre = basename(f, '.png').replace(/_front$/i, '').toUpperCase();
    const frente = preparar(join(src, f));
    const rutaBack = join(src, `${nombre}_back.png`);
    const detras = existsSync(rutaBack) ? preparar(rutaBack) : frente;

    const f96 = reducirPaleta(encajarEn(frente, 96), colores);
    const b96 = reducirPaleta(encajarEn(detras, 96), colores);
    escribirPNG(join(gFront, `${nombre}.png`), 96, 96, f96.rgba);
    escribirPNG(join(gBack, `${nombre}.png`), 96, 96, b96.rgba);

    // hoja de iconos: 4×2 celdas de 32×32
    const iconos = new Uint8Array(128 * 64 * 4);
    for (let cy = 0; cy < 2; cy++) for (let cx = 0; cx < 4; cx++) pegar(iconos, 128, frente, cx, cy, 32);
    escribirPNG(join(gIcons, `${nombre}.png`), 128, 64, reducirPaleta({ w: 128, h: 64, rgba: iconos }, Math.round(colores / 2)).rgba);

    // hoja de personaje: 4×4 celdas de 64×64 (abajo / izq / dcha / arriba)
    const chars = new Uint8Array(256 * 256 * 4);
    for (let f2 = 0; f2 < 4; f2++) {
      pegar(chars, 256, frente, f2, 0, 64);          // abajo
      pegar(chars, 256, frente, f2, 1, 64);          // izquierda
      pegar(chars, 256, espejar(frente), f2, 2, 64); // derecha
      pegar(chars, 256, detras, f2, 3, 64);          // arriba
    }
    escribirPNG(join(gChars, `${nombre}.png`), 256, 256, reducirPaleta({ w: 256, h: 256, rgba: chars }, colores).rgba);

    manifesto.push({
      nombre,
      frontal: `Graphics/Pokemon/Front/${nombre}.png`,
      trasero: `Graphics/Pokemon/Back/${nombre}.png`,
      icono: `Graphics/Pokemon/Icons/${nombre}.png`,
      personaje: `Graphics/Characters/${nombre}.png`,
      vista_trasera_propia: existsSync(rutaBack),
      colores_paleta: colores,
    });
    console.log(`  ✔ ${nombre.padEnd(12)} Front 96×96 · Back 96×96 · Icons 128×64 · Characters 256×256${existsSync(rutaBack) ? '' : '  (trasera desde el frontal)'}`);
  }

  mkdirSync('content', { recursive: true });
  const rutaManifiesto = 'content/pokegods_assets.json';
  // el manifiesto se fusiona: cada ejecución aporta su lote sin borrar el anterior
  let previo = { pokegods: [] };
  if (existsSync(rutaManifiesto)) {
    try { previo = JSON.parse(readFileSync(rutaManifiesto, 'utf8')); } catch { previo = { pokegods: [] }; }
  }
  const fusion = new Map((previo.pokegods || []).map((p) => [p.nombre, p]));
  for (const p of manifesto) fusion.set(p.nombre, p);
  writeFileSync(rutaManifiesto, JSON.stringify({
    generado: new Date().toISOString(),
    origen: src,
    destino: juego,
    formatos: { Front: '96x96', Back: '96x96', Icons: '128x64 (8 celdas 32x32)', Characters: '256x256 (4x4 celdas 64x64: abajo/izq/dcha/arriba)' },
    pokegods: [...fusion.values()].sort((a, b) => a.nombre.localeCompare(b.nombre)),
  }, null, 2));
  console.log(`\n✔ ${manifesto.length} Pokégods convertidos · manifiesto: content/pokegods_assets.json`);
}

if (process.argv[1] && process.argv[1].endsWith('generar_assets_pokegods.mjs')) main();#!/usr/bin/env node
/**
 * Generates the exhaustive, deterministic QA corpus for the Arceus Omega phase.
 * Every row is executable input for verify_arceus_omega_matrix.mjs, not prose.
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(import.meta.dirname, "..");
const OUTPUT = path.join(ROOT, "content", "arceus_omega_qa_matrix.jsonl");
const COUNT = 300_000;
const realms = ["DIMENSIONAL_NIGHTMARE", "ATLAS_MIL", "RUTA_DE_DIOS"];
const stages = ["PROLOGUE_CPU", "PLATE_ROULETTE", "LAW_REWRITE", "ASH_WILL", "GENESIS_COLLAPSE", "VERDICT"];
const failures = ["none", "before_snapshot", "after_snapshot", "during_cpu", "before_turn", "after_turn", "during_capture", "during_rollback", "save_hotkey", "direct_file_drift"];
const saveKeys = ["player", "game_system", "pokemon_system", "switches", "variables", "self_switches", "game_screen", "global_metadata", "map_metadata", "bag", "storage_system"];
const mapChecks = ["walkability", "exit_reachability", "event_collision", "layer_occlusion", "tileset_bounds", "tone_release", "transition_return", "postgame_continuity"];

fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
const out = fs.createWriteStream(OUTPUT);
out.write(JSON.stringify({ kind: "manifest", schema: 1, cases: COUNT, generatedBy: "generate_arceus_omega_qa_matrix.mjs" }) + "\n");
for (let id = 0; id < COUNT; id++) {
  const family = id < 120_000 ? "transaction" : id < 210_000 ? "battle" : "map";
  const realm = realms[id % realms.length];
  const stage = stages[Math.floor(id / realms.length) % stages.length];
  const failure = failures[Math.floor(id / 17) % failures.length];
  const seed = ((id + 1) * 2654435761) >>> 0;
  const expected = family === "transaction"
    ? { rollback: saveKeys[(id >>> 2) % saveKeys.length], diskStable: true, saveBlocked: failure === "save_hotkey", canonical: id % 97 === 0 ? "capture" : "none" }
    : family === "battle"
      ? { phase: (id % 6) + 1, cpuChoice: seed % 4, deterministic: true, escape: false, visibleCue: true }
      : { check: mapChecks[id % mapChecks.length], passable: id % 19 !== 0, recoveryRoute: true, visitor: "ASH_POSTGAME" };
  out.write(JSON.stringify({ id, family, realm, stage, failure, seed, expected }) + "\n");
}
out.end();
out.on("finish", () => console.log(`OK: ${COUNT.toLocaleString("en-US")} substantive QA cases -> ${path.relative(ROOT, OUTPUT)}`));#!/usr/bin/env node
