const imageCache = new Map();
const directoryCache = new Map();
function resolveGraphic(directory, name) {
  if (!name || !fs.existsSync(directory)) return null;
  if (!directoryCache.has(directory)) {
    directoryCache.set(directory, new Map(fs.readdirSync(directory).map((filename) => [filename.toLowerCase(), filename])));
  }
  const files = directoryCache.get(directory);
  for (const candidate of [name, `${name}.png`, `${name}.PNG`, `${name}.jpg`, `${name}.jpeg`]) {
    const actual = files.get(candidate.toLowerCase());
    if (actual) return path.join(directory, actual);
  }
  return null;
}
async function graphic(kind, name) {
  const file = resolveGraphic(graphicsRoots[kind], name);
  if (!file) return null;
  if (!imageCache.has(file)) imageCache.set(file, loadImage(file));
  return imageCache.get(file);
}

function loadMapIndex() {
  const mapInfos = mapListFromInfos(readMarshalData("MapInfos.rxdata"));
  const byId = new Map(mapInfos.map((entry) => [entry.id, entry]));
  for (const id of REQUESTED_IDS) {
    if (!byId.has(id)) throw new Error(`MapInfos.rxdata no contiene Map${id}`);
    const mapPath = path.join(DATA, `Map${id}.rxdata`);
    if (!fs.existsSync(mapPath)) throw new Error(`Falta ${path.relative(ROOT, mapPath)}`);
  }
  if (hierarchy.maps.length !== 1000 || atlasCatalog.maps.length !== 1000) {
    throw new Error(`Los catálogos de Atlas no contienen 1.000 filas (${hierarchy.maps.length}/${atlasCatalog.maps.length})`);
  }
  if (new Set(REQUESTED_IDS).size !== REQUESTED_IDS.length) {
    throw new Error(`La selección contiene IDs repetidos (${REQUESTED_IDS.length})`);
  }
  assertIdTitles(byId);
  return byId;
}

function assertIdTitles(mapInfoById) {
  const titleContains = (id, phrase) => (mapInfoById.get(id)?.name ?? "").toLowerCase().includes(phrase.toLowerCase());
  if (!titleContains(2021, "Falda")) throw new Error("Map2021 debe ser Monte Silver — Falda");
  if (!titleContains(2030, "Gruta de los Testigos")) throw new Error("Map2030 debe ser la Gruta de los Testigos; no se generará la aproximación sobre este ID");
  if (!titleContains(2022, "Cumbre")) throw new Error("Map2022 debe ser Monte Silver — Cumbre");
  if (!titleContains(2038, "Aproximación Celestial")) throw new Error("Map2038 debe ser la aproximación celestial de La Ruta de Dios");
  for (let id = 2031; id <= 2037; id++) {
    if (!titleContains(id, "La Ruta de Dios")) throw new Error(`Map${id} debe conservar uno de los siete pisos de La Ruta de Dios`);
  }
}

function summarizeMaps(mapInfoById) {
  const summaries = new Map();
  for (const id of REQUESTED_IDS) {
    const raw = fs.readFileSync(path.join(DATA, `Map${id}.rxdata`));
    const parsed = parseMap(marshalLoad(raw));
    const events = parsed.events.map(({ obj }) => parseEvent(obj));
    summaries.set(id, {
      id,
      title: mapInfoById.get(id)?.name || `Mapa ${id}`,
      width: parsed.width,
      height: parsed.height,
      tilesetId: parsed.tilesetId,
      eventCount: events.length,
      eventNames: events.map((event) => event.name).filter(Boolean),
    });
  }
  return summaries;
}

function atlasCategory(hierarchyEntry) {
  if (hierarchyEntry.tier === 1) return "Tier 1 · ancla artesanal";
  if (hierarchyEntry.tier === 2) return "Tier 2 · ruta estable";
  return "Tier 3 · eco dimensional";
}
function atlasDescription(entry, summary) {
  const source = `${entry.sourceName || entry.mapName || "escenario de Atlas"} (Map${entry.sourceId ?? "—"})`;
  if (entry.tier === 1) {
    const blueprint = tier1ById.get(Number(entry.mapId));
    const seed = tier1SeedById.get(Number(entry.mapId));
    const identity = blueprint?.biome?.identity || seed?.biome || "ancla narrativa del sector";
    const promise = blueprint?.oneSentencePromise || seed?.coreMystery || seed?.globalImportance;
    return `Ancla artesanal basada en ${source}. Identidad del lugar: ${identity}. Episodio: ${promise || "articula el sello y la historia del sector."}`;
  }
  if (entry.tier === 2) {
    const blueprint = tier2ById.get(Number(entry.mapId));
    if (blueprint) {
      return `Ruta estable basada en ${source}. Objetivo: ${blueprint.objective} Mecánica de referencia: ${blueprint.mechanic?.name || "interacción local"}. Promesa: ${blueprint.promise}`;
    }
    return `Ruta estable de ${source} dentro de ${entry.sectorName}; el plano la clasifica como Tier 2 con mecánica local, decisión persistente y retorno libre.`;
  }
  const localRule = tier3ById.get(Number(entry.mapId));
  if (localRule) {
    const counterplay = localRule.rule?.rules?.[0];
    return `Eco dimensional de ${source}. Anomalía documentada: ${localRule.anomaly} Regla local: ${localRule.rule?.name || localRule.variant || "regla de navegación"}.${counterplay ? ` Primer contrajuego: ${counterplay}` : ""}`;
  }
  const hasAtlasChallenge = summary.eventNames.some((name) => /atlas desafío/i.test(name));
  return `Eco dimensional de ${source} en el sector ${entry.sectorName}. La ficha de jerarquía lo ubica en Tier 3; ${hasAtlasChallenge ? "conserva un evento de desafío Atlas" : "su lectura se centra en el espacio heredado y su baliza"}, junto con la navegación y el retorno de referencia del Atlas.`;
}

function extraDescription(id) {
  if (MULTIVERSE_DESCRIPTIONS.has(id)) return MULTIVERSE_DESCRIPTIONS.get(id);
  return EXTRA_DESCRIPTIONS.get(id) || "Mapa complementario del proyecto; la ficha se limita a su título de MapInfos y los datos compilados presentes.";
}
function cleanMarkdown(value) {
  return String(value ?? "—").replaceAll("|", "\\|").replaceAll("\r", " ").replaceAll("\n", " ").trim();
}
function mapFactLine(summary) {
  return `**Datos compilados:** ${summary.width}×${summary.height} tiles; ${summary.eventCount} eventos; tileset ${summary.tilesetId}.`;
}

function buildReport(summaries) {
  const lines = [
    `# Informe referencial de mapas — ${REQUESTED_IDS.length.toLocaleString("es-ES")} fichas`,
    "",
    `**Generado:** ${new Date().toISOString().slice(0, 10)}`,
    `**Alcance:** Atlas Mil (Map1021–Map2020) y ${OTHER_IDS.length} mapas complementarios en Otros_Mapas_16.png.`,
    "",
    "> Este informe y sus mosaicos son referencias estáticas elaboradas a partir de MapInfos, datos RMXP, catálogos de contenido y gráficos del proyecto. No equivalen a una prueba dentro de Kirin ni de Game.exe; no se afirma aquí que se haya ejecutado el juego.",
    "",
    "## Asignación de IDs y alcance",
    "",
    "- **Atlas Mil:** Map1021–Map2020, 1.000 mapas organizados en 40 sectores y 15 hojas visuales.",
    "- **Isla Espejo:** Map997–Map999 (3 mapas).",
    "- **Panteón Pokégod:** Map1020 (1 mapa).",
    "- **Monte Silver:** Falda Map2021, Gruta de los Testigos Map2030 y Cumbre Map2022.",
    "- **Multiverso Creepypasta:** siete emisiones, Map2023–Map2029.",
    "- **La Ruta de Dios:** siete pisos Map2031–Map2037 y aproximación celestial Map2038.",
    "- **Vía de las Nueve Eras:** Map2195 (vía de nueve distritos) y Map2196 (Gimnasio Atlas · Las Nueve Eras).",
    "- **Dimensiones del DLC:** Map2200–2201 (Glazed), Map2210–2211 (Light Platinum), Map2220–2221 (Team Rocket), Map2230 (Avenida), Map2240–2241 (Liquid Crystal), Map2242–2243 (TFOH), Map2244–2245 (Factory Adventure) y Map2250–2257 (ocho gimnasios de Atlas).",
    "",
    "**Colisión evitada:** Map2030 sigue siendo la Gruta de los Testigos. La aproximación de La Ruta de Dios está en Map2038; los pisos permanecen en Map2031–Map2037.",
    "",
    "## Cómo leer las fichas",
    "",
    "Cada ficha conserva el título registrado en `MapInfos.rxdata`, la categoría/sector del catálogo del proyecto y las dimensiones y cantidad de eventos leídas del mapa compilado. Las descripciones Tier 1 y Tier 2 se apoyan en sus blueprints; las Tier 3, en sus reglas o en la jerarquía y los eventos disponibles. Para los mapas complementarios se usan los catálogos y documentos del proyecto.",
    "",
  ];

  for (const sector of [...atlasCatalog.sectors].sort((a, b) => a.id - b.id)) {
    const sectorEntries = hierarchy.maps
      .filter((entry) => Number(entry.sector) === Number(sector.id))
      .sort((a, b) => Number(a.mapId) - Number(b.mapId));
    if (sectorEntries.length !== 25) throw new Error(`Sector ${sector.id} debe tener 25 mapas, tiene ${sectorEntries.length}`);
    const first = sectorEntries[0].mapId;
    const last = sectorEntries.at(-1).mapId;
    lines.push(`## Sector ${String(sector.id).padStart(2, "0")} — ${sector.name} (${sector.faction}) · Map${first}–Map${last}`, "");
    for (const entry of sectorEntries) {
      const id = Number(entry.mapId);
      const summary = summaries.get(id);
      if (!summary) throw new Error(`Falta resumen de Map${id}`);
      const desc = atlasDescription(entry, summary);
      lines.push(
        `### Map${id} — ${cleanMarkdown(summary.title)}`,
        `- **Categoría:** Atlas Mil · ${cleanMarkdown(sector.name)} · ${cleanMarkdown(atlasCategory(entry))}.`,
        `- **Referencia:** ${cleanMarkdown(desc)}`,
        `- ${mapFactLine(summary)}`,
        "",
      );
    }
  }

  lines.push(`## Mapas complementarios — ${OTHER_IDS.length} fichas`, "");
  for (const group of OTHER_GROUPS) {
    lines.push(`## ${group.name}`, "");
    for (const id of group.ids) {
      const summary = summaries.get(id);
      if (!summary) throw new Error(`Falta resumen de Map${id}`);
      lines.push(
        `### Map${id} — ${cleanMarkdown(summary.title)}`,
        `- **Categoría:** ${cleanMarkdown(group.name)}.`,
        `- **Referencia:** ${cleanMarkdown(extraDescription(id))}`,
        `- ${mapFactLine(summary)}`,
        "",
      );
    }
  }
  lines.push("## Límites de esta referencia", "", "Los mosaicos son renders estáticos de los mapas compilados con sus tilesets y gráficos disponibles. No validan por sí mismos pasabilidad en ejecución, transferencias, eventos en tiempo real, compatibilidad Android/Kirin ni funcionamiento en Game.exe. Para esas comprobaciones hace falta ejecutar el juego y realizar una prueba manual.", "");
  return `${lines.join("\n").replace(/\n+$/, "")}\n`;
}

const tilesetRaw = readMarshalData("Tilesets.rxdata");
const tilesets = new Map();
for (let index = 1; index < tilesetRaw.length; index++) {
  if (!tilesetRaw[index]) continue;
  const parsed = parseTileset(tilesetRaw[index]);
  tilesets.set(parsed.id, parsed);
}

async function renderMapBuffer(buffer) {
  const map = parseMap(marshalLoad(buffer));
  const tileset = tilesets.get(map.tilesetId);
  if (!tileset) throw new Error(`Map usa Tileset ${map.tilesetId}, ausente en Tilesets.rxdata`);
  const tilesetImage = await graphic("tileset", tileset.tilesetName);
  if (!tilesetImage) throw new Error(`Falta Graphics/Tilesets/${tileset.tilesetName}`);
  const autotiles = await Promise.all(tileset.autotiles.map((name) => graphic("autotile", name)));
  const canvas = createCanvas(Math.max(1, map.width * 32), Math.max(1, map.height * 32));
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#252b34";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const drawAutotile = (image, pattern, dx, dy) => {
    if (!image) return;
    if (image.width < 96 || image.height < 128) {
      const width = Math.min(32, image.width);
      const height = Math.min(32, image.height);
      if (width && height) ctx.drawImage(image, 0, 0, width, height, dx, dy, 32, 32);
      return;
    }
    for (let quarter = 0; quarter < 4; quarter++) {
      const part = autotileParts[pattern]?.[quarter] ?? autotileParts[0][quarter];
      const source = part - 1;
      const sx = (source % 6) * 16;
      const sy = Math.floor(source / 6) * 16;
      ctx.drawImage(image, sx, sy, 16, 16, dx + (quarter % 2) * 16, dy + Math.floor(quarter / 2) * 16, 16, 16);
    }
  };
  const drawTile = (tileId, x, y) => {
    if (!tileId) return;
    if (tileId >= 384) {
      const source = tileId - 384;
      const sx = (source % 8) * 32;
      const sy = Math.floor(source / 8) * 32;
      if (sx + 32 <= tilesetImage.width && sy + 32 <= tilesetImage.height) {
        ctx.drawImage(tilesetImage, sx, sy, 32, 32, x, y, 32, 32);
      }
      return;
    }
    if (tileId >= 48) {
      const index = Math.floor(tileId / 48) - 1;
      drawAutotile(autotiles[index], tileId % 48, x, y);
    }
  };

  // RMXP Table access is intentionally routed through tableGet from web/js/rmxp.js.
  for (let z = 0; z < 3; z++) {
    for (let y = 0; y < map.height; y++) {
      for (let x = 0; x < map.width; x++) {
        drawTile(tableGet(map.table, x, y, z), x * 32, y * 32);
      }
    }
  }

  const events = map.events.map(({ obj }) => parseEvent(obj)).sort((a, b) => a.y - b.y || a.id - b.id);
  for (const event of events) {
    const display = event.pages.map((page) => page.graphic).find((entry) => entry?.charName || entry?.tileId);
    if (!display || display.opacity === 0) continue;
    if (display.tileId) {
      drawTile(display.tileId, event.x * 32, event.y * 32);
      continue;
    }
    const image = await graphic("character", display.charName);
    if (!image) continue;
    const frameWidth = Math.floor(image.width / 4);
    const frameHeight = Math.floor(image.height / 4);
    if (!frameWidth || !frameHeight) continue;
    const row = ({ 2: 0, 4: 1, 6: 2, 8: 3 })[display.direction] ?? 0;
    const column = Math.max(0, Math.min(3, Number(display.pattern ?? 0)));
    ctx.globalAlpha = Number(display.opacity ?? 255) / 255;
    ctx.drawImage(image, column * frameWidth, row * frameHeight, frameWidth, frameHeight,
      event.x * 32 + (32 - frameWidth) / 2, event.y * 32 + 32 - frameHeight, frameWidth, frameHeight);
    ctx.globalAlpha = 1;
  }
  return canvas;
}

function wrapText(ctx, text, maxWidth, maxLines = 2) {
  const words = String(text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let current = "";
  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;
    if (current && ctx.measureText(candidate).width > maxWidth) {
      lines.push(current);
      current = word;
    } else current = candidate;
  }
  if (current) lines.push(current);
  if (lines.length > maxLines) {
    lines.length = maxLines;
    let last = lines[maxLines - 1];
    while (last && ctx.measureText(`${last}…`).width > maxWidth) last = last.slice(0, -1).trimEnd();
    lines[maxLines - 1] = `${last}…`;
  }
  return lines;
}
function clipText(ctx, text, maxWidth) {
  let value = String(text || "");
  while (value && ctx.measureText(`${value}…`).width > maxWidth) value = value.slice(0, -1).trimEnd();
  return value === text ? value : `${value}…`;
}
function categoryForCard(id) {
  const entry = hierarchyById.get(id);
  if (entry) return `ATLAS · S${String(entry.sector).padStart(2, "0")} · TIER ${entry.tier}`;
  for (const group of OTHER_GROUPS) if (group.ids.includes(id)) return group.name.toUpperCase();
  return "MAPA";
}

const SHEET_COLUMNS = 5;
const CARD_WIDTH = 360;
const CARD_HEIGHT = 232;
const HEADER_HEIGHT = 72;
const SHEET_ROWS = 14;

async function renderSheet(entries, title, subtitle, outputPath, summaries, mapInfoById) {
  const rows = Math.max(1, Math.ceil(entries.length / SHEET_COLUMNS));
  const width = SHEET_COLUMNS * CARD_WIDTH;
  const height = HEADER_HEIGHT + rows * CARD_HEIGHT;
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = "#10151c";
  ctx.fillRect(0, 0, width, height);

  ctx.fillStyle = "#171f29";
  ctx.fillRect(0, 0, width, HEADER_HEIGHT);
  ctx.fillStyle = "#f0d18c";
  ctx.font = "bold 24px sans-serif";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(clipText(ctx, title, width - 32), 16, 30);
  ctx.fillStyle = "#bdc9d7";
  ctx.font = "13px sans-serif";
  ctx.fillText(clipText(ctx, subtitle, width - 32), 16, 51);
  ctx.fillStyle = "#8593a4";
  ctx.font = "11px sans-serif";
  ctx.fillText("Render estático de referencia · no sustituye prueba dentro del juego", 16, 67);

  for (let index = 0; index < entries.length; index++) {
    const id = typeof entries[index] === "number" ? entries[index] : Number(entries[index].mapId);
    const summary = summaries.get(id);
    if (!summary) throw new Error(`No hay ficha resumida para Map${id}`);
    const x = (index % SHEET_COLUMNS) * CARD_WIDTH;
    const y = HEADER_HEIGHT + Math.floor(index / SHEET_COLUMNS) * CARD_HEIGHT;

    ctx.fillStyle = "#1a222c";
    ctx.fillRect(x + 1, y + 1, CARD_WIDTH - 2, CARD_HEIGHT - 2);
    ctx.strokeStyle = "#34404d";
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, CARD_WIDTH - 1, CARD_HEIGHT - 1);

    ctx.fillStyle = "#9ec6ed";
    ctx.font = "bold 11px sans-serif";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(clipText(ctx, `MAP ${id} · ${categoryForCard(id)}`, CARD_WIDTH - 20), x + 10, y + 16);

    ctx.fillStyle = "#f1ebdd";
    ctx.font = "bold 15px sans-serif";
    const titleLines = wrapText(ctx, summary.title, CARD_WIDTH - 22, 2);
    ctx.fillText(titleLines[0] || "(sin título)", x + 10, y + 36);
    if (titleLines[1]) ctx.fillText(titleLines[1], x + 10, y + 53);

    const mapCanvas = await renderMapBuffer(fs.readFileSync(path.join(DATA, `Map${id}.rxdata`)));
    const boxX = x + 9;
    const boxY = y + 62;
    const boxWidth = CARD_WIDTH - 18;
    const boxHeight = 150;
    ctx.fillStyle = "#252b34";
    ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
    const scale = Math.min(boxWidth / mapCanvas.width, boxHeight / mapCanvas.height);
    const drawWidth = Math.max(1, Math.round(mapCanvas.width * scale));
    const drawHeight = Math.max(1, Math.round(mapCanvas.height * scale));
    const drawX = Math.round(boxX + (boxWidth - drawWidth) / 2);
    const drawY = Math.round(boxY + (boxHeight - drawHeight) / 2);
    ctx.drawImage(mapCanvas, 0, 0, mapCanvas.width, mapCanvas.height, drawX, drawY, drawWidth, drawHeight);

    ctx.fillStyle = "#aeb9c7";
    ctx.font = "11px sans-serif";
    ctx.fillText(`${summary.width}×${summary.height} · ${summary.eventCount} eventos · tileset ${summary.tilesetId}`, x + 10, y + 226);

    // Las superficies nativas son mucho mayores que sus miniaturas. Liberarlas
    // enseguida evita acumular cientos de canvas completos en ejecuciones largas.
    mapCanvas.width = 0;
    mapCanvas.height = 0;
    if (global.gc && index % 10 === 9) global.gc();
  }

  const png = canvas.toBuffer("image/png");
  fs.writeFileSync(outputPath, png);
  canvas.width = 0;
  canvas.height = 0;
  if (global.gc) global.gc();
  const fileSize = fs.statSync(outputPath).size;
  console.log(`PNG ${path.relative(ROOT, outputPath)} · ${entries.length} mapas · ${(fileSize / 1024 / 1024).toFixed(2)} MiB`);
}

function atlasSheetBatches() {
  const batches = [];
  const baseSize = Math.floor(ATLAS_IDS.length / 15);
  const remainder = ATLAS_IDS.length % 15;
  let cursor = 0;
  for (let sheetIndex = 0; sheetIndex < 15; sheetIndex++) {
    const count = baseSize + (sheetIndex < remainder ? 1 : 0);
    const entries = ATLAS_IDS.slice(cursor, cursor + count);
    cursor += count;
    batches.push({ sheetIndex, entries });
  }
  if (cursor !== ATLAS_IDS.length || batches.some((batch) => batch.entries.length > SHEET_COLUMNS * SHEET_ROWS)) {
    throw new Error("La división de Atlas Mil en 15 mosaicos no cuadra");
  }
  return batches;
}

function expectedZipEntries() {
  return [
    ...EXPECTED_IMAGE_NAMES.map((name) => `${ZIP_FOLDER_NAME}/${name}`),
    REPORT_NAME,
  ].sort();
}
function verifyReport(summaries) {
  if (!fs.existsSync(REPORT_PATH)) throw new Error(`Falta ${path.relative(ROOT, REPORT_PATH)}`);
  const report = fs.readFileSync(REPORT_PATH, "utf8");
  for (const id of REQUESTED_IDS) {
    if (!report.includes(`### Map${id} —`)) throw new Error(`El informe no contiene una ficha para Map${id}`);
  }
  const withoutDate = (text) => text.replace(/^\*\*Generado:\*\* .*$/m, "**Generado:**");
  if (withoutDate(report) !== withoutDate(buildReport(summaries))) throw new Error("El informe está desactualizado respecto a los mapas/catálogos: ejecuta --refresh-report");
  const headings = [...report.matchAll(/^### Map\d+ —/gm)].length;
  if (headings !== REQUESTED_IDS.length) throw new Error(`El informe contiene ${headings} fichas, se esperaban ${REQUESTED_IDS.length}`);
  for (const required of [
    "Map2030 sigue siendo la Gruta de los Testigos",
    "Map2038",
    "Map2031–Map2037",
    "No equivalen a una prueba dentro de Kirin ni de Game.exe",
  ]) {
    if (!report.includes(required)) throw new Error(`Falta en el informe la nota obligatoria: ${required}`);
  }
}
async function verifyImages() {
  for (const name of EXPECTED_IMAGE_NAMES) {
    const file = path.join(OUTPUT_DIR, name);
    if (!fs.existsSync(file)) throw new Error(`Falta ${path.relative(ROOT, file)}`);
    const image = await loadImage(file);
    if (image.width < 1000 || image.height < 500) throw new Error(`${name} tiene dimensiones inesperadas (${image.width}×${image.height})`);
    console.log(`PNG OK ${name} · ${image.width}×${image.height} · ${(fs.statSync(file).size / 1024 / 1024).toFixed(2)} MiB`);
  }
}
function verifyZip() {
  if (!fs.existsSync(ZIP_PATH)) throw new Error(`Falta ${path.relative(ROOT, ZIP_PATH)}`);
  const zip = readZipIndex(ZIP_PATH);
  const expected = expectedZipEntries();
  const actual = [...zip.entries.keys()].sort();
  if (actual.length !== expected.length || actual.some((name, index) => name !== expected[index])) {
    throw new Error(`El ZIP no contiene exactamente los 16 mosaicos y el informe (${actual.length} entradas)`);
  }
  for (const name of expected) {
    const source = name === REPORT_NAME ? REPORT_PATH : path.join(ROOT, "Scripts_corregido", name);
    if (!readZipEntry(zip, name).equals(fs.readFileSync(source))) throw new Error(`Contenido desactualizado en el ZIP: ${name}`);
  }
  console.log(`ZIP OK ${path.relative(ROOT, ZIP_PATH)} · ${expected.length} archivos · ${(fs.statSync(ZIP_PATH).size / 1024 / 1024).toFixed(2)} MiB`);
}

async function verifyAll() {
  const mapInfoById = loadMapIndex();
  const summaries = summarizeMaps(mapInfoById);
  if (summaries.size !== REQUESTED_IDS.length) throw new Error(`Se leyeron ${summaries.size} mapas, no ${REQUESTED_IDS.length}`);
  verifyReport(summaries);
  await verifyImages();
  verifyZip();
  console.log(`Verificación referencial OK: 1.000 mapas de Atlas Mil + ${OTHER_IDS.length} mapas complementarios. No es una prueba en Game.exe/Kirin.`);
}

async function createMissing() {
  const mapInfoById = loadMapIndex();
  const summaries = summarizeMaps(mapInfoById);
  if (summaries.size !== REQUESTED_IDS.length) throw new Error(`Se leyeron ${summaries.size} mapas, no ${REQUESTED_IDS.length}`);
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });

  let updated = false;
  if (FORCE || REFRESH_REPORT || !fs.existsSync(REPORT_PATH)) {
    updated = true;
    fs.writeFileSync(REPORT_PATH, buildReport(summaries), "utf8");
    console.log(`Informe ${path.relative(ROOT, REPORT_PATH)} · ${REQUESTED_IDS.length.toLocaleString("es-ES")} fichas`);
  } else {
    console.log(`Conservo el informe existente: ${path.relative(ROOT, REPORT_PATH)}`);
  }

  for (const { sheetIndex, entries } of atlasSheetBatches()) {
    const name = `Atlas_${String(sheetIndex + 1).padStart(2, "0")}.png`;
    const output = path.join(OUTPUT_DIR, name);
    if (fs.existsSync(output) && !FORCE) {
      console.log(`Conservo el mosaico existente: ${path.relative(ROOT, output)}`);
      continue;
    }
    const first = entries[0];
    const last = entries.at(-1);
    const subtitle = `Map${first}–Map${last} · ${entries.length} mapas · hojas 01–15 de Atlas Mil`;
    updated = true;
    await renderSheet(entries, `ATLAS MIL · MOSAICO ${String(sheetIndex + 1).padStart(2, "0")} / 15`, subtitle, output, summaries, mapInfoById);
  }

  const otherOutput = path.join(OUTPUT_DIR, "Otros_Mapas_16.png");
  if (!fs.existsSync(otherOutput) || FORCE) {
    updated = true;
    const entries = OTHER_GROUPS.flatMap((group) => group.ids);
    await renderSheet(entries, "MAPAS COMPLEMENTARIOS · MOSAICO 16 / 16",
      `${OTHER_IDS.length} mapas · Isla Espejo · Panteón Pokégod · Monte Silver · Multiverso Creepypasta · La Ruta de Dios · Vía de las Nueve Eras · Dimensiones del DLC`,
      otherOutput, summaries, mapInfoById);
  } else {
    console.log(`Conservo el mosaico existente: ${path.relative(ROOT, otherOutput)}`);
  }

  if (fs.existsSync(ZIP_PATH) && !updated) {
    console.log(`Conservo el ZIP existente: ${path.relative(ROOT, ZIP_PATH)}`);
  } else {
    const extraFiles = Object.fromEntries([
      ...EXPECTED_IMAGE_NAMES.map((name) => [`${ZIP_FOLDER_NAME}/${name}`, fs.readFileSync(path.join(OUTPUT_DIR, name))]),
      [REPORT_NAME, fs.readFileSync(REPORT_PATH)],
    ]);
    const emptyRoot = fs.mkdtempSync(path.join(os.tmpdir(), "mapas-referenciales-"));
    try {
      writeZip({ root: emptyRoot, destination: ZIP_PATH, extraFiles, timestamp: new Date(Date.UTC(2026, 8, 30)) });
    } finally {
      fs.rmSync(emptyRoot, { recursive: true, force: true });
    }
    console.log(`ZIP ${path.relative(ROOT, ZIP_PATH)} · ${Object.keys(extraFiles).length} archivos`);
  }

  await verifyAll();
}

if (VERIFY_ONLY) await verifyAll();
else await createMissing();#!/usr/bin/env node
/**
 * Inventario de solo lectura de un ROM hack de GBA (Pokémon Gen 3).
 *
 * Los ROM invitados de referencia (Glazed, Light Platinum, Pokémon Team Rocket)
 * son ROMs de Game Boy Advance, no proyectos de RPG Maker XP: no se abren con
 * Pokémon Studio ni con el analizador de Essentials. Este analizador les saca
 * el esqueleto jugable directamente de la ROM:
 *
 *   · identificación: título interno, código de juego, ROM base y tamaño
 *   · tablas de nombres: especies, movimientos, objetos, habilidades
 *   · clases de entrenador
 *   · batallas: tabla de entrenadores con equipo, niveles, objetos y movimientos
 *   · inventario de recursos comprimidos (LZ77): sprites y demás gráficos
 *   · censo de texto: cuánto diálogo hay y dónde
 *
 * No copia sprites, música ni mapas al repositorio: sólo metadatos y texto,
 * que es lo que hace falta para reescribir las ideas con contenido original.
 *
 * Uso:
 *   node tools/inspect_gba_rom.mjs --rom reference/roms_invitadas/entrada/GlazedESPB6.gba
 *   node tools/inspect_gba_rom.mjs --dir reference/roms_invitadas/entrada   (todos los .gba/.gb)
 *
 * Salida (reference/roms_invitadas/<slug>/, ignorada por Git):
 *   gba_inventory.json · informe_gba.md · pbs/{pokemon,moves,items,abilities,trainers}.txt
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT_ROOT = () => (process.env.ROM_OUT_DIR ? path.resolve(process.env.ROM_OUT_DIR) : path.join(ROOT, "reference", "roms_invitadas"));

const arg = (name, fallback = null) => {
  const key = `--${name}`;
  const i = process.argv.indexOf(key);
  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : fallback;
};
const ROM = arg("rom");
const DIR = arg("dir");

// ---------------------------------------------------------------- charmap GBA
// Tabla estándar de la 3ª generación. Se valida buscando "BULBASAUR" en la ROM.
const CHAR = new Array(256).fill(null);
{
  const set = (byte, text) => (CHAR[byte] = text);
  set(0x00, " ");
  for (let i = 0; i < 26; i += 1) set(0xbb + i, String.fromCharCode(65 + i)); // A-Z
  for (let i = 0; i < 26; i += 1) set(0xd5 + i, String.fromCharCode(97 + i)); // a-z
  for (let i = 0; i < 10; i += 1) set(0xa1 + i, String(i)); // 0-9
  set(0xab, "!");
  set(0xac, "?");
  set(0xad, ".");
  set(0xae, "-");
  set(0xaf, "·");
  set(0xb8, ",");
  set(0xb9, "×");
  set(0xba, "/");
  set(0xb5, "♂");
  set(0xb6, "♀");
  set(0xb0, "…");
  set(0xf0, ":");
  set(0x2d, "+");
  set(0x2c, "&");
  set(0x2f, ";");
  set(0x51, "¿");
  set(0x52, "¡");
  set(0x53, "[PK]");
  set(0x54, "[MN]");
  set(0x71, "[>]");
  // Acentos y eñes de la tabla estándar de la 3ª generación.
  const acentos = {
    0x01: "À", 0x02: "Á", 0x03: "Â", 0x04: "Ç", 0x05: "È", 0x06: "É", 0x07: "Ê", 0x08: "Ë",
    0x09: "Ì", 0x0a: "Í", 0x0b: "Î", 0x0c: "Ï", 0x0d: "Ò", 0x0e: "Ó", 0x0f: "Ô", 0x10: "Œ",
    0x11: "Ù", 0x12: "Ú", 0x13: "Û", 0x14: "Ñ", 0x15: "ß", 0x16: "à", 0x17: "á", 0x18: "â",
    0x19: "ç", 0x1a: "è", 0x1b: "é", 0x1c: "ê", 0x1d: "ë", 0x1e: "ì", 0x1f: "í", 0x20: "î",
    0x21: "ï", 0x22: "ò", 0x23: "ó", 0x24: "ô", 0x25: "œ", 0x26: "ù", 0x27: "ú", 0x28: "û",
    0x29: "ñ", 0x2a: "º", 0x2b: "ª", 0x68: "â", 0x6f: "í",
  };
  for (const [byte, texto] of Object.entries(acentos)) set(Number(byte), texto);
  // Códigos de control de texto: se aceptan dentro de un nombre, pero no se imprimen.
  for (let b = 0xf7; b <= 0xfe; b += 1) set(b, "");
}
const decode = (data, offset, length) => {
  let out = "";
  for (let i = 0; i < length; i += 1) {
    const b = data[offset + i];
    if (b === 0xff) break;
    const c = CHAR[b];
    out += c === null || c === undefined ? "" : c;
  }
  return out.trim();
};

// -------------------------------------------------------------- identificación
const BASES = {
  BPEE: "Esmeralda",
  BPRE: "Rojo Fuego",
  BPGE: "Verde Hoja",
  AXVE: "Rubí",
  AXPE: "Zafiro",
};

function identificar(data, file) {
  let title = "";
  let code = "";
  let maker = "";
  let rev = 0;
  if (data.length >= 0xc0) {
    title = Buffer.from(data.subarray(0xa0, 0xac)).toString("latin1").replace(/\0/g, "").trim();
    code = Buffer.from(data.subarray(0xac, 0xb0)).toString("latin1");
    maker = Buffer.from(data.subarray(0xb0, 0xb2)).toString("latin1");
    rev = data[0xbc] ?? 0;
  }
  return {
    archivo: path.basename(file),
    tamaño: data.length,
    tituloInterno: title,
    codigo: code,
    maker,
    revision: rev,
    romBase: BASES[code] || (code ? `desconocida (${code})` : "¿GB/GBC?"),
  };
}

// ------------------------------------------------------ descubrimiento de tablas
/** ¿Es una entrada de nombre plausible? Termina en 0xFF y se decodifica. */
function entradaValida(data, off, stride) {
  if (off < 0 || off + stride > data.length) return false;
  let letras = 0;
  let terminado = false;
  for (let i = 0; i < stride; i += 1) {
    const b = data[off + i];
    if (terminado) {
      // Tras el terminador sólo hay relleno: ceros… y a veces más 0xFF.
      if (b !== 0x00 && b !== 0xff) return false;
      continue;
    }
    if (b === 0xff) {
      terminado = true;
      continue;
    }
    if (b === 0x00) continue; // espacio
    if (CHAR[b] === null || CHAR[b] === undefined) return false;
    letras += 1;
  }
  return terminado && letras > 0;
}

// Codificador inverso para buscar nombres conocidos dentro de la ROM.
const BYTE = new Map();
for (let b = 0; b < 256; b += 1) if (CHAR[b]) BYTE.set(CHAR[b], b);
const codificar = (texto) => {
  const out = [];
  for (const ch of texto.toUpperCase()) {
    const b = BYTE.get(ch) ?? BYTE.get(ch.toLowerCase());
    if (b === undefined || b === 0) return null;
    out.push(b);
  }
  return Buffer.from(out);
};

// Nombres que anclan cada tabla. Se prueban en español y en inglés porque los
// hacks están traducidos y las tablas se repunterizan al insertar contenido.
const ANCLAS = {
  especies: ["BULBASAUR"],
  movimientos: ["PLACAJE", "TACKLE", "DESTRUCTOR", "GOLPE CUERPO", "LATIGO"],
  objetos: ["POKEBALL", "POCION", "POKéBALL", "BICICLETA", "BASTON"],
  habilidades: ["STENCH", "HEDOR", "DRIZZLE", "LLOVIZNA", "INTIMIDATE"],
  clases_entrenador: ["ENTRENADOR", "RANGER", "AQUA", "CAMPER", "ALPINISTA"],
};

function buscarTablas(data) {
  const runs = [];
  for (const stride of [10, 11, 12, 13, 14, 16]) {
    let i = 0;
    while (i + stride <= data.length) {
      const first = data[i];
      if ((first !== 0xff && first !== 0x00 && CHAR[first] != null) && entradaValida(data, i, stride)) {
        let start = i;
        while (entradaValida(data, start - stride, stride)) start -= stride;
        let end = i;
        while (entradaValida(data, end + stride, stride)) end += stride;
        runs.push({ inicio: start, fin: end, stride, count: Math.floor((end - start) / stride) + 1, huecos: 0 });
        i = end + stride;
      } else {
        i += 1;
      }
    }
  }
  for (const r of runs) {
    r.nombres = [];
    for (let k = 0; k < r.count; k += 1) r.nombres.push(decode(data, r.inicio + k * r.stride, r.stride));
    r.muestra = r.nombres.slice(0, 5);
  }
  runs.sort((a, b) => b.count - a.count);

  // Selección por ancla: la tabla es la serie que contiene ese nombre exacto.
  const porTipo = {};
  for (const [tipo, anclas] of Object.entries(ANCLAS)) {
    for (const ancla of anclas) {
      const buscado = ancla.toUpperCase();
      const hit = runs.find((r) => r.nombres.some((n) => n.toUpperCase() === buscado));
      if (hit) {
        porTipo[tipo] = hit;
        porTipo[tipo].ancla = ancla;
        break;
      }
    }
  }
  // Fragmentos: series del mismo ancho cerca de la tabla principal (los hacks
  // suelen partir las tablas al insertar datos).
  for (const [tipo, tabla] of Object.entries(porTipo)) {
    const cercanos = runs
      .filter((r) => r !== tabla && r.stride === tabla.stride && Math.abs(r.inicio - tabla.inicio) < 0x20000 && r.count >= 20)
      .sort((a, b) => b.count - a.count)
      .slice(0, 3);
    tabla.fragmentos = cercanos.map((f) => ({ inicio: f.inicio, count: f.count, muestra: f.muestra }));
    tabla.entradasTotales = tabla.count + cercanos.reduce((a, f) => a + f.count, 0);
  }
  const ordenadas = Object.values(porTipo).sort((a, b) => b.count - a.count);
  return { todas: runs.slice(0, 14), porTipo, tablasOrdenadas: ordenadas };
}

// ------------------------------------------------------------------ entrenadores
const u32 = (data, off) => (data[off] | (data[off + 1] << 8) | (data[off + 2] << 16) | (data[off + 3] << 24)) >>> 0;
const u16 = (data, off) => data[off] | (data[off + 1] << 8);
const ptrValido = (v, len) => v >= 0x08000000 && v - 0x08000000 < len;

/**
 * Estructura de entrenador de la 3ª generación (40 bytes):
 * 0x00 partyFlags · 0x01 trainerClass · 0x02 género · 0x03 música · 0x04 sprite(?) ·
 * 0x04 name[12] · 0x10 items[4] · 0x18 doubleBattle · 0x1C aiFlags · 0x20 partySize · 0x24 partyPtr
 */
function buscarEntrenadores(data) {
  const SIZE = 40;
  const candidatos = [];
  const max = data.length - SIZE;
  for (let off = 0; off < max; off += 1) {
    const partyFlags = data[off];
    if (partyFlags > 3) continue;
    const trainerClass = data[off + 1];
    if (trainerClass < 1 || trainerClass > 200) continue;
    const trainerPic = data[off + 3];
    if (trainerPic > 0xff) continue;
    // 0x02 es (música << 1) | género: no sirve para filtrar por rango.
    const gender = data[off + 2] & 1;
    const name = decode(data, off + 4, 12); // trainerName[12] empieza en 0x04
    if (!name) continue;
    const partySize = u32(data, off + 32);
    if (partySize < 1 || partySize > 6) continue;
    const partyPtr = u32(data, off + 36);
    if (!ptrValido(partyPtr, data.length)) continue;
    const items = [0, 1, 2, 3].map((k) => u16(data, off + 16 + k * 2)); // items[4] en 0x10
    if (items.some((it) => it > 900)) continue;
    candidatos.push({ off, partyFlags, trainerClass, gender, name, partySize, partyPtr: partyPtr - 0x08000000, items: items.filter(Boolean) });
    if (candidatos.length > 200000) break;
  }
  // Nos quedamos con la serie más larga de estructuras contiguas de 40 bytes.
  const offsets = new Set(candidatos.map((c) => c.off));
  let mejor = { inicio: 0, count: 0 };
  let actual = { inicio: 0, count: 0 };
  for (const c of candidatos) {
    if (actual.count && c.off === actual.inicio + actual.count * SIZE) actual.count += 1;
    else actual = { inicio: c.off, count: 1 };
    if (actual.count > mejor.count) mejor = { ...actual };
  }
  if (!mejor.count || mejor.count < 20) return { total: 0, muestra: [], series: mejor.count };
  const porOff = new Map(candidatos.map((c) => [c.off, c]));
  const entrenadores = [];
  for (let k = 0; k < mejor.count; k += 1) {
    const c = porOff.get(mejor.inicio + k * SIZE);
    if (!c) continue;
    const party = [];
    for (let p = 0; p < c.partySize; p += 1) {
      const base = c.partyPtr + p * 8;
      if (base + 8 > data.length) break;
      // TrainerMon: iv(u16) + nivel(u8) + relleno(u8) + especie(u16) + objeto(u16 si partyFlags&1)
      party.push({ nivel: data[base + 2], especie: u16(data, base + 4), objeto: c.partyFlags & 1 ? u16(data, base + 6) : 0 });
    }
    entrenadores.push({
      id: k,
      clase: c.trainerClass,
      nombre: c.name,
      objetos: c.items,
      equipo: party,
    });
  }
  return { total: entrenadores.length, inicio: mejor.inicio, muestra: entrenadores.slice(0, 40), todos: entrenadores };
}

// ------------------------------------------------------------------------ LZ77
function inventarioLZ77(data) {
  const blobs = [];
  const max = data.length - 4;
  for (let off = 0; off < max; off += 1) {
    if (data[off] !== 0x10) continue;
    const size = data[off + 1] | (data[off + 2] << 8) | (data[off + 3] << 16);
    if (size < 0x40 || size > 0x40000 || off + 4 + size > data.length) continue;
    blobs.push({ offset: off, descomprimido: size });
  }
  const porTam = new Map();
  for (const b of blobs) {
    const k = b.descomprimido;
    porTam.set(k, (porTam.get(k) || 0) + 1);
  }
  const clasificar = (n) => {
    if (n === 2048) return "sprite 64×64 (4 bpp) — Pokémon frente/espalda";
    if (n === 4096) return "sprite 64×64 (8 bpp)";
    if (n === 512) return "icono 32×32 (4 bpp)";
    if (n === 640) return "icono 32×32 + paleta";
    if (n >= 0x1000 && n <= 0x8000) return "gráfico grande (fondo/tileset/interfaz)";
    return "otro";
  };
  return {
    total: blobs.length,
    porTamaño: [...porTam.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12).map(([tam, n]) => ({ tam, n, clase: clasificar(tam) })),
  };
}

// ----------------------------------------------------------------------- informe
function renderInforme(inv) {
  const fila = (t) => `| ${t.tipo} | ${t.count} | ${t.stride} | 0x${t.inicio.toString(16).toUpperCase()} | ${t.muestra.filter(Boolean).slice(0, 4).join(", ")} |`;
  return `# Inventario GBA: ${inv.identificacion.archivo}

- **ROM base**: ${inv.identificacion.romBase} (código ${inv.identificacion.codigo || "—"}, revisión ${inv.identificacion.revision})
- **Título interno**: ${inv.identificacion.tituloInterno || "—"}
- **Tamaño**: ${(inv.identificacion.tamaño / 1048576).toFixed(1)} MB
- Análisis: ${inv.resumen.duracionSegundos}s · generado ${inv.generadoEn}

_Sólo metadatos y texto: ningún sprite, música ni mapa del ROM se copia a Fire Ash._

## Tablas de nombres encontradas

| Tipo | Entradas | Ancho | Offset | Muestra |
|---|---:|---:|---|---|
${Object.entries(inv.tablas.porTipo)
  .map(([tipo, t]) => fila({ tipo, count: t.count, stride: t.stride, inicio: t.inicio, muestra: t.muestra }))
  .join("\n")}

## Batallas

${inv.batallas.total} entrenadores detectados (serie contigua de estructuras de 40 bytes).
Equipo medio: ${inv.batallas.estadisticas ? inv.batallas.estadisticas.equipoMedio : "—"} Pokémon ·
nivel medio: ${inv.batallas.estadisticas ? inv.batallas.estadisticas.nivelMedio : "—"}.

${
  inv.batallas.muestra
    .slice(0, 15)
    .map(
      (t) =>
        `- **${t.nombre}** (clase ${t.clase}${t.objetos.length ? `, objetos: ${t.objetos.join("/")}` : ""}) — ` +
        t.equipo.map((p) => `#${p.especie} Nv${p.nivel}${p.objeto ? `+obj${p.objeto}` : ""}`).join(", ")
    )
    .join("\n") || "_No se detectó la tabla de entrenadores con este patrón._"
}

## Recursos comprimidos (LZ77)

${inv.lz77.total} bloques. Tamaños más repetidos:

${inv.lz77.porTamaño.map((p) => `- ${p.n} bloques de ${p.tam} bytes — ${p.clase}`).join("\n")}
`;
}

// ------------------------------------------------------------------ principal
function analizar(file) {
  const data = fs.readFileSync(file);
  const t0 = Date.now();
  const id = identificar(data, file);
  const tablas = buscarTablas(data);
  const batallas = buscarEntrenadores(data);
  const lz77 = inventarioLZ77(data);

  const nivelMedio = batallas.todos && batallas.todos.length
    ? Number(
        (
          batallas.todos.reduce((a, t) => a + t.equipo.reduce((b, p) => b + p.nivel, 0), 0) /
          batallas.todos.reduce((a, t) => a + t.equipo.length, 0)
        ).toFixed(1)
      )
    : null;
  const equipoMedio = batallas.todos && batallas.todos.length
    ? Number((batallas.todos.reduce((a, t) => a + t.equipo.length, 0) / batallas.todos.length).toFixed(2))
    : null;

  const inv = {
    slug: id.archivo.replace(/\.(gba|gb|gbc)$/i, ""),
    generadoEn: new Date().toISOString(),
    identificacion: id,
    resumen: {
      duracionSegundos: Number(((Date.now() - t0) / 1000).toFixed(1)),
      especies: tablas.porTipo.especies ? tablas.porTipo.especies.count : 0,
      movimientos: tablas.porTipo.movimientos ? tablas.porTipo.movimientos.count : 0,
      objetos: tablas.porTipo.objetos ? tablas.porTipo.objetos.count : 0,
      habilidades: tablas.porTipo.habilidades ? tablas.porTipo.habilidades.count : 0,
      entrenadores: batallas.total,
      bloquesLZ77: lz77.total,
    },
    tablas,
    batallas: { total: batallas.total, inicio: batallas.inicio, estadisticas: { equipoMedio, nivelMedio }, muestra: batallas.muestra || [] },
    lz77,
  };

  const outDir = path.join(OUT_ROOT(), inv.slug);
  fs.mkdirSync(path.join(outDir, "pbs"), { recursive: true });
  fs.writeFileSync(path.join(outDir, "gba_inventory.json"), `${JSON.stringify(inv, null, 2)}\n`);
  fs.writeFileSync(path.join(outDir, "informe_gba.md"), renderInforme(inv));

  // Exportación tipo PBS / Pokémon Studio (sólo nombres y estructuras).
  const volcar = (nombre, tabla) => {
    if (!tabla) return;
    const lineas = [];
    for (let i = 0; i < tabla.count; i += 1) {
      const valor = decode(data, tabla.inicio + i * tabla.stride, tabla.stride);
      lineas.push(`${i}\t${valor}`);
    }
    fs.writeFileSync(path.join(outDir, "pbs", nombre), `# ${tabla.count} entradas (ancho ${tabla.stride}, offset 0x${tabla.inicio.toString(16).toUpperCase()})\n${lineas.join("\n")}\n`);
  };
  volcar("pokemon.txt", tablas.porTipo.especies);
  volcar("moves.txt", tablas.porTipo.movimientos);
  volcar("items.txt", tablas.porTipo.objetos);
  volcar("abilities.txt", tablas.porTipo.habilidades);
  volcar("trainerclasses.txt", tablas.porTipo.clases_entrenador);

  if (batallas.todos && batallas.todos.length) {
    const nombresEspecie = tablas.porTipo.especies
      ? (i) => decode(data, tablas.porTipo.especies.inicio + i * tablas.porTipo.especies.stride, tablas.porTipo.especies.stride)
      : (i) => `#${i}`;
    const lineas = batallas.todos.map(
      (t) =>
        `#-------------------------------\n[CLASE_${t.clase},${t.nombre}]\n` +
        (t.objetos.length ? `Items = ${t.objetos.join(",")}\n` : "") +
        t.equipo.map((p) => `Pokemon = ${nombresEspecie(p.especie)},${p.nivel}${p.objeto ? `,ITEM_${p.objeto}` : ""}`).join("\n")
    );
    fs.writeFileSync(
      path.join(outDir, "pbs", "trainers.txt"),
      `# ${batallas.todos.length} entrenadores detectados en la ROM\n${lineas.join("\n")}\n`
    );
  }

  console.log(
    `${inv.slug}: ${id.romBase} · especies ${inv.resumen.especies} · movimientos ${inv.resumen.movimientos} · ` +
      `objetos ${inv.resumen.objetos} · habilidades ${inv.resumen.habilidades} · entrenadores ${inv.resumen.entrenadores} · ` +
      `bloques LZ77 ${inv.resumen.bloquesLZ77} (${inv.resumen.duracionSegundos}s)`
  );
  console.log(`→ ${path.relative(ROOT, outDir)}/informe_gba.md`);
  return inv;
}

const objetivos = ROM
  ? [ROM]
  : DIR
    ? fs
        .readdirSync(DIR)
        .filter((f) => /\.(gba|gb|gbc)$/i.test(f))
        .map((f) => path.join(DIR, f))
    : [];

if (!objetivos.length) {
  console.log("Uso: node tools/inspect_gba_rom.mjs --rom <archivo.gba> | --dir <carpeta>");
  process.exit(1);
}
for (const objetivo of objetivos) analizar(objetivo);#!/usr/bin/env node
/**
 * Inventario de solo lectura de un ROM hack invitado (RPG Maker XP / Essentials).
 *
 * Para qué sirve: cuando el jugador trae un ROM de referencia (Glazed, Light
 * Platinum, Pokémon Team Rocket...), este analizador le saca el esqueleto
 * jugable sin abrir Pokémon Studio:
 *
 *   · mapas: nombre, tamaño, tileset, eventos, páginas, comandos y textos
 *   · flags: nombres reales de switches y variables (Data/System.rxdata)
 *   · NPCs: nombres de evento, sprite que usan y dónde están
 *   · cinemáticas: CommonEvents + bloques de texto ShowText por mapa
 *   · música: BGM/BGS/ME/SE referenciados y presentes
 *   · sprites: hojas de Characters/Battlers/Tilesets con dimensiones y fotogramas
 *   · batallas: entrenadores de Data/trainers.dat (si es formato Essentials)
 *
 * Lo que NO hace, a propósito: no copia sprites, música ni mapas del ROM al
 * nuestro. Sólo produce un inventario y un informe para inspirar contenido
 * original. Ningún recurso con derechos ajenos entra en el repositorio.
 *
 * Uso:
 *   node tools/inspect_guest_rom.mjs --dir /ruta/al/juego --slug team_rocket
 *   node tools/inspect_guest_rom.mjs --zip /ruta/al/juego.zip --slug glazed
 *   node tools/inspect_guest_rom.mjs --dir ... --slug x --limit-maps 200
 *
 * Salidas (carpeta reference/roms_invitadas/<slug>/, ignorada por git):
 *   inventory.json  · informe.md  · pbs/ (exportación tipo Pokémon Studio)
 */
import fs from "node:fs";
import os from "node:os";
import { execFileSync, spawnSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT_ROOT = path.join(ROOT, "reference", "roms_invitadas");
/** Carpeta de salida: se puede redirigir con ROM_OUT_DIR para las autopruebas. */
const outputRoot = () => (process.env.ROM_OUT_DIR ? path.resolve(process.env.ROM_OUT_DIR) : OUT_ROOT);

const arg = (name, fallback = null) => {
  const key = `--${name}`;
  const i = process.argv.indexOf(key);
  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : fallback;
};
const FLAGS = new Set(process.argv.filter((a) => a.startsWith("--") && !a.includes("=")));
const DIR = arg("dir");
const ZIP = arg("zip");
const SLUG = arg("slug", "invitado");
const LIMIT = Number(arg("limit-maps", "0")) || 0;

const ivars = (obj) => {
  if (!obj || !Array.isArray(obj.ivars)) return {};
  return Object.fromEntries(obj.ivars.map(([k, v]) => [k, v]));
};
/** Campos de un objeto marshal: ivars (@clave) o pares de RHash (clave sin arroba). */
const fields = (obj) => {
  if (!obj) return {};
  if (Array.isArray(obj.ivars) && obj.ivars.length) return Object.fromEntries(obj.ivars);
  if (Array.isArray(obj.pairs)) {
    return Object.fromEntries(obj.pairs.map(([k, v]) => [String((k && (k.text ?? k.name ?? k)) ?? ""), v]));
  }
  return {};
};
/** Texto de un RString, RSymbol o símbolo serializado ([bytes, ivars, 0]). */
const text = (v) => {
  if (v == null) return "";
  if (typeof v === "string") return v;
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (typeof v === "object") {
    if (typeof v.text === "string") return v.text;
    if (typeof v.name === "string") return v.name; // RSymbol
    if (Array.isArray(v)) return text(v[0]);
  }
  return "";
};
const num = (v) => {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && Number.isFinite(Number(v))) return Number(v);
  if (v && typeof v === "object" && "value" in v) return Number(v.value) || 0;
  return 0;
};

/** Dimensiones de un PNG leyendo sólo la cabecera (rápido, sin decodificar). */
function pngSize(file) {
  try {
    const fd = fs.openSync(file, "r");
    const buf = Buffer.alloc(24);
    fs.readSync(fd, buf, 0, 24, 0);
    fs.closeSync(fd);
    if (buf.readUInt32BE(0) !== 0x89504e47) return null;
    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
  } catch {
    return null;
  }
}

function findGameRoot(start) {
  const candidates = [start, path.join(start, "Data"), path.join(start, "Game"), path.join(start, "game")];
  for (const c of candidates) if (fs.existsSync(path.join(c, "MapInfos.rxdata"))) return c;
  // Búsqueda acotada: subdirectorios inmediatos que parezcan un juego RMXP.
  if (fs.existsSync(start)) {
    for (const entry of fs.readdirSync(start, { withFileTypes: true }).slice(0, 50)) {
      if (!entry.isDirectory()) continue;
      const c = path.join(start, entry.name, "Data");
      if (fs.existsSync(path.join(c, "MapInfos.rxdata"))) return c;
    }
  }
  return null;
}

function listDir(dir, exts) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isFile() && exts.some((x) => e.name.toLowerCase().endsWith(x)))
    .map((e) => e.name)
    .sort();
}

/** Recorre comandos de evento y clasifica lo interesante. */
function scanCommands(list, sink) {
  let i = 0;
  let pendingText = [];
  while (i < list.length) {
    const cmd = list[i];
    const d = ivars(cmd);
    const code = num(d["@code"]);
    const params = Array.isArray(d["@parameters"]) ? d["@parameters"] : [];
    if (code === 101 || code === 401) {
      const line = text(params[0]);
      if (line.trim()) pendingText.push(line.trim());
    } else if (pendingText.length) {
      sink.texts.push(pendingText.join(" "));
      sink.textLines += pendingText.length;
      pendingText = [];
    }
    if (code === 111 || code === 121 || code === 122) {
      // Condición por switch (111) y control de switches (121/122).
      const sid = code === 111 ? num(params[0]) : num(params[0]);
      if (sid > 0) sink.switches[sid] = (sink.switches[sid] || 0) + 1;
    }
    if (code === 112 || code === 122 || code === 123) {
      const vid = num(code === 123 ? params[0] : params[0]);
      if (vid > 0) sink.variables[vid] = (sink.variables[vid] || 0) + 1;
    }
    if (code === 355 || code === 655) {
      // Script de Essentials: guardamos sólo la primera línea, como pista.
      const script = text(params[0]);
      const head = script.split("\n")[0].slice(0, 120);
      if (head.trim()) sink.scriptsHeads.push(head.trim());
    }
    if (code === 241 || code === 245 || code === 249 || code === 250) {
      const p = text(params[0]);
      if (p) sink.audioRefs.add(p);
    }
    if (code === 209 || code === 208) {
      // Mostrar animación / mover evento: cinemática.
      sink.cinematicCommands += 1;
    }
    i += 1;
  }
  if (pendingText.length) {
    sink.texts.push(pendingText.join(" "));
    sink.textLines += pendingText.length;
  }
}

const newSink = () => ({
  texts: [],
  textLines: 0,
  switches: {},
  variables: {},
  scriptsHeads: [],
  audioRefs: new Set(),
  cinematicCommands: 0,
});


/** Entrenadores: soporta Essentials moderno (RHash de GameData::Trainer) y legacy (Array). */
function readTrainers(file) {
  if (!fs.existsSync(file)) return { total: 0, format: "sin archivo", sample: [], partyStats: null };
  let raw;
  try {
    raw = marshalLoad(fs.readFileSync(file));
  } catch (error) {
    return { total: 0, format: `no legible: ${error.message}`, sample: [], partyStats: null };
  }
  const entries = raw && raw.pairs ? raw.pairs.map(([, v]) => v) : Array.isArray(raw) ? raw : [];
  const rows = [];
  let partySum = 0;
  let partyMax = 0;
  for (const e of entries) {
    if (e && e.className === "GameData::Trainer") {
      const d = fields(e);
      const party = Array.isArray(d["@pokemon"]) ? d["@pokemon"] : [];
      partySum += party.length;
      partyMax = Math.max(partyMax, party.length);
      rows.push({
        id: text(d["@id"]),
        trainerType: text(d["@trainer_type"] ?? d["trainer_type"]),
        name: text(d["@name"]),
        version: num(d["@version"]),
        loseText: text(d["@lose_text"]).slice(0, 120),
        items: Array.isArray(d["@items"]) ? d["@items"].map((i) => text(i)) : [],
        party: party.map((p) => {
          const pd = fields(p);
          return {
            species: text(pd["@species"] ?? pd["species"]),
            level: num(pd["@level"] ?? pd["level"]),
            item: text(pd["@item"] ?? pd["item"]),
            moves: Array.isArray(pd["@moves"] ?? pd["moves"]) ? (pd["@moves"] ?? pd["moves"]).map((m) => text(m)).filter(Boolean) : [],
            ability: text(pd["@ability"] ?? pd["ability"]),
            gender: num(pd["@gender"] ?? pd["gender"]),
            form: num(pd["@form"] ?? pd["form"]),
            shiny: Boolean(pd["@shiny"] ?? pd["shiny"]),
          };
        }),
      });
    } else if (Array.isArray(e) && e.length >= 4) {
      // Formato legacy: [tipo, nombre, partido] con party = [especie, nivel, ...]
      const [type, name, , party] = e;
      const list = Array.isArray(party) ? party : [];
      partySum += list.length;
      partyMax = Math.max(partyMax, list.length);
      rows.push({
        id: "",
        trainerType: text(type),
        name: text(name),
        version: 0,
        loseText: "",
        items: [],
        party: list.map((p) => ({ species: text(p && p[2]), level: num(p && p[3]) })),
      });
    }
  }
  const partyStats = rows.length
    ? { promedio: Number((partySum / rows.length).toFixed(2)), maximo: partyMax }
    : null;
  return {
    total: rows.length,
    format: entries.length && entries[0] && entries[0].className ? entries[0].className : "legacy",
    partyStats,
    sample: rows.slice(0, 40),
    todos: rows,
  };
}

/** Catálogo genérico de un .dat de Essentials: id, nombre y campos ligeros. */
function readDataCatalog(file, key) {
  try {
    const raw = marshalLoad(fs.readFileSync(file));
    const entries = raw && raw.pairs ? raw.pairs.map(([, v]) => v) : Array.isArray(raw) ? raw : [];
    const rows = entries
      .map((e) => (e && (e.ivars || e.pairs) ? fields(e) : Array.isArray(e) ? { id: e[0], name: e[1] } : null))
      .filter(Boolean)
      .slice(0, 2000)
      .map((d) => ({
        id: text(d["@id"] ?? d["id"]),
        name: text(d["@name"] ?? d["name"]) || text(d["@real_name"] ?? d["real_name"]) || text(d["@id"] ?? d["id"]),
        extra:
          key === "moves"
            ? { tipo: text(d["@type"] ?? d["type"]), categoria: num(d["@category"] ?? d["category"]), potencia: num(d["@power"] ?? d["power"]) }
            : key === "species"
              ? { tipo1: text(d["@type1"] ?? d["type1"]), tipo2: text(d["@type2"] ?? d["type2"]), forma: num(d["@form"] ?? d["form"]) }
              : {},
      }));
    return { total: entries.length, className: entries[0] && entries[0].className ? entries[0].className : "legacy", filas: rows };
  } catch (error) {
    return { total: 0, className: `no legible: ${error.message}`, filas: [] };
  }
}

function inspect() {
  if (!DIR && !ZIP) throw new Error("Falta --dir <carpeta> o --zip <archivo>.");
  let base = DIR;
  let tempDir = null;
  if (ZIP) {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), `rom-${SLUG}-`));
    base = tempDir;
    execFileSync("unzip", ["-qq", "-o", ZIP, "-d", tempDir]);
  }
  const dataDir = findGameRoot(base);
  if (!dataDir) throw new Error(`No encontré Data/MapInfos.rxdata dentro de ${base}`);
  const gameRoot = path.dirname(dataDir);
  const started = Date.now();

  // ---- Mapas -------------------------------------------------------------
  const infos = marshalLoad(fs.readFileSync(path.join(dataDir, "MapInfos.rxdata")));
  const mapNames = new Map();
  for (const [k, v] of infos.pairs || []) {
    const id = num(k.value !== undefined ? k.value : k);
    const d = ivars(v);
    mapNames.set(id, { name: text(d["@name"]), parent: num(d["@parent_id"]), order: num(d["@order"]) });
  }
  const mapFiles = fs
    .readdirSync(dataDir)
    .filter((f) => /^Map\d+\.rxdata$/.test(f))
    .map((f) => ({ file: f, id: Number(f.match(/\d+/)[0]) }))
    .sort((a, b) => a.id - b.id);
  const chosen = LIMIT > 0 ? mapFiles.slice(0, LIMIT) : mapFiles;

  const maps = [];
  const sink = newSink();
  const spriteUse = new Map();
  let eventsTotal = 0;
  let pagesTotal = 0;
  let commandsTotal = 0;
  for (const { file, id } of chosen) {
    const map = marshalLoad(fs.readFileSync(path.join(dataDir, file)));
    const d = ivars(map);
    const events = (d["@events"] && d["@events"].pairs) || [];
    let pages = 0;
    let commands = 0;
    const npcs = [];
    for (const [ek, ev] of events) {
      const ed = ivars(ev);
      const eventId = num(ek.value !== undefined ? ek.value : ek);
      const name = text(ed["@name"]);
      const pagesList = Array.isArray(ed["@pages"]) ? ed["@pages"] : [];
      pages += pagesList.length;
      for (const p of pagesList) {
        const pd = ivars(p);
        const graphic = ivars(pd["@graphic"]);
        const charName = text(graphic["@character_name"]);
        const list = Array.isArray(pd["@list"]) ? pd["@list"] : [];
        commands += list.length;
        scanCommands(list, sink);
        if (charName) {
          spriteUse.set(charName, (spriteUse.get(charName) || 0) + 1);
          npcs.push({ id: eventId, name, sprite: charName, x: num(ed["@x"]), y: num(ed["@y"]) });
        }
      }
    }
    eventsTotal += events.length;
    pagesTotal += pages;
    commandsTotal += commands;
    maps.push({
      id,
      name: mapNames.get(id)?.name ?? "",
      parent: mapNames.get(id)?.parent ?? 0,
      width: num(d["@width"]),
      height: num(d["@height"]),
      tilesetId: num(d["@tileset_id"]),
      events: events.length,
      pages,
      commands,
      npcs: npcs.slice(0, 12),
    });
  }

  // ---- Flags: nombres reales de switches y variables ---------------------
  const systemFile = path.join(dataDir, "System.rxdata");
  let switchNames = [];
  let variableNames = [];
  if (fs.existsSync(systemFile)) {
    const sys = ivars(marshalLoad(fs.readFileSync(systemFile)));
    const asArray = (v) => {
      const arr = Array.isArray(v) ? v : v && Array.isArray(v.value) ? v.value : [];
      return arr.map((x) => text(x && x.text !== undefined ? x : x)).map((s) => (s == null ? "" : String(s)));
    };
    switchNames = asArray(sys["@switches"]);
    variableNames = asArray(sys["@variables"]);
  }

  // ---- Cinemáticas: CommonEvents ----------------------------------------
  let commonEvents = [];
  const commonFile = path.join(dataDir, "CommonEvents.rxdata");
  if (fs.existsSync(commonFile)) {
    const ce = marshalLoad(fs.readFileSync(commonFile));
    const arr = Array.isArray(ce) ? ce : (ce.pairs || []).map(([, v]) => v);
    commonEvents = arr
      .map((v, idx) => {
        const d = ivars(v);
        const s = newSink();
        scanCommands(Array.isArray(d["@list"]) ? d["@list"] : [], s);
        return {
          id: num(d["@id"]) || idx,
          name: text(d["@name"]),
          trigger: num(d["@trigger"]),
          switchId: num(d["@switch_id"]),
          commands: (d["@list"] || []).length,
          textLines: s.textLines,
          preview: s.texts.slice(0, 3).map((t) => t.slice(0, 160)),
        };
      })
      .filter((c) => c.commands > 0);
  }

  // ---- Batallas: trainers.dat (Essentials v17–v21) ------------------------
  const trainers = readTrainers(path.join(dataDir, "trainers.dat"));

  // --- Catálogos de datos (especies, movimientos, objetos) -----------------
  const catalogos = {};
  for (const key of ["species", "moves", "items", "abilities", "types"]) {
    const file = path.join(dataDir, `${key}.dat`);
    if (fs.existsSync(file)) catalogos[key] = readDataCatalog(file, key);
  }

  // ---- Recursos ---------------------------------------------------------
  const G = path.join(gameRoot, "Graphics");
  const spriteDirs = {
    characters: path.join(G, "Characters"),
    entrenadores: path.join(G, "Trainers"),
    pokemon_frontal: path.join(G, "Pokemon", "Front"),
    pokemon_trasero: path.join(G, "Pokemon", "Back"),
    iconos_pokemon: path.join(G, "Pokemon", "Icons"),
    battlers: path.join(G, "Battlers"),
    tilesets: path.join(G, "Tilesets"),
    autotiles: path.join(G, "Autotiles"),
    panoramas: path.join(G, "Panoramas"),
    nieblas: path.join(G, "Fogs"),
    fondos_de_combate: path.join(G, "Battlebacks"),
    objetos: path.join(G, "Items"),
    iconos: path.join(G, "Icons"),
    ventanas: path.join(G, "Windowskins"),
    titulos: path.join(G, "Titles"),
    transiciones: path.join(G, "Transitions"),
    imagenes: path.join(G, "Pictures"),
  };
  const graphics = {};
  for (const [key, dir] of Object.entries(spriteDirs)) {
    const files = listDir(dir, [".png"]);
    graphics[key] = {
      count: files.length,
      files: files.slice(0, 400).map((f) => {
        const size = pngSize(path.join(dir, f));
        return {
          name: f,
          ...(size || {}),
          frames: size ? Math.max(1, Math.round(size.w / (size.h / 4 || 1))) : null,
          usos: key === "characters" ? spriteUse.get(path.basename(f, ".png")) || 0 : undefined,
        };
      }),
    };
  }
  const audio = {};
  for (const key of ["BGM", "BGS", "ME", "SE"]) {
    const files = listDir(path.join(gameRoot, "Audio", key), [".mid", ".midi", ".mp3", ".ogg", ".wav"]);
    audio[key] = { count: files.length, files: files.slice(0, 500) };
  }

  const inventory = {
    slug: SLUG,
    source: ZIP ? path.basename(ZIP) : path.resolve(base),
    engine: "RPG Maker XP / Pokémon Essentials",
    generadoEn: new Date().toISOString(),
    resumen: {
      mapas: maps.length,
      mapasEnMapInfos: mapNames.size,
      eventos: eventsTotal,
      paginas: pagesTotal,
      comandos: commandsTotal,
      lineasDeTexto: sink.textLines,
      switchesNombrados: switchNames.filter((s) => s.trim()).length,
      variablesNombradas: variableNames.filter((s) => s.trim()).length,
      switchesUsados: Object.keys(sink.switches).length,
      variablesUsadas: Object.keys(sink.variables).length,
      commonEvents: commonEvents.length,
      entrenadores: trainers.total,
      catalogos: Object.fromEntries(Object.entries(catalogos).map(([k, v]) => [k, v.total])),
      duracionSegundos: Number(((Date.now() - started) / 1000).toFixed(1)),
    },
    flags: {
      switches: switchNames.map((name, index) => ({ id: index, name, usos: sink.switches[index] || 0 })),
      variables: variableNames.map((name, index) => ({ id: index, name, usos: sink.variables[index] || 0 })),
    },
    mapas: maps,
    commonEvents,
    batallas: { total: trainers.total, formato: trainers.format, estadisticasEquipo: trainers.partyStats, muestra: trainers.sample },
    catalogos,
    graficos: graphics,
    audio,
    audioReferenciadoEnEventos: [...sink.audioRefs].sort(),
    spritesMasUsados: [...spriteUse.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 120)
      .map(([name, usos]) => ({ name, usos })),
    pistasDeScript: [...new Set(sink.scriptsHeads)].slice(0, 200),
  };

  const outDir = path.join(outputRoot(), SLUG);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, "inventory.json"), `${JSON.stringify(inventory, null, 2)}\n`);
  fs.writeFileSync(path.join(outDir, "informe.md"), renderReport(inventory));
  fs.mkdirSync(path.join(outDir, "pbs"), { recursive: true });
  // ---- Exportación tipo Pokémon Studio (PBS) -----------------------------
  fs.writeFileSync(
    path.join(outDir, "pbs", "mapas.txt"),
    "# id | nombre | tamaño | tileset | mapa padre | eventos\n" +
      maps.map((m) => `${m.id}\t${m.name}\t${m.width}x${m.height}\t${m.tilesetId}\t${m.parent}\t${m.events}`).join("\n") + "\n"
  );
  fs.writeFileSync(
    path.join(outDir, "pbs", "flags.txt"),
    "# switches (id, nombre, usos en eventos) y variables del ROM invitado\n" +
      inventory.flags.switches.filter((f) => f.name.trim()).map((f) => `SWITCH ${f.id}\t${f.name}\t${f.usos}`).join("\n") +
      "\n\n" +
      inventory.flags.variables.filter((f) => f.name.trim()).map((f) => `VARIABLE ${f.id}\t${f.name}\t${f.usos}`).join("\n") +
      "\n"
  );
  const batallasPbs = trainers.sample
    .map((t) => {
      const header = `[${(t.trainerType || "?").toUpperCase()},${t.name}]`;
      const items = t.items && t.items.length ? `Items = ${t.items.join(",")}\n` : "";
      const lose = t.loseText ? `Lose Text = "${t.loseText}"\n` : "";
      const party = t.party
        .map((p) => {
          const bits = [`${(p.species || "?").toUpperCase()}`, p.level || 1];
          if (p.item) bits.push(p.item.toUpperCase());
          if (p.moves && p.moves.length) bits.push(p.moves.map((m) => m.toUpperCase()).join(","));
          return `Pokemon = ${bits.join(",")}`;
        })
        .join("\n");
      return `#-------------------------------\n${header}\n${items}${lose}${party}\n`;
    })
    .join("");
  fs.writeFileSync(
    path.join(outDir, "pbs", "entrenadores.txt"),
    `# ${trainers.total} entrenadores (${trainers.format}) — muestra de ${trainers.sample.length} exportada en formato PBS\n${batallasPbs}`
  );
  for (const [key, cat] of Object.entries(catalogos)) {
    if (!cat.total) continue;
    fs.writeFileSync(
      path.join(outDir, "pbs", `${key}.txt`),
      `# ${cat.total} registros (${cat.className})\n` +
        cat.filas.map((f) => `${f.id}\t${f.name}\t${Object.entries(f.extra).map(([k, v]) => `${k}=${v}`).join(" ")}`).join("\n") +
        "\n"
    );
  }
  fs.writeFileSync(
    path.join(outDir, "pbs", "npc_sprites.txt"),
    "# sprites de personaje usados por los eventos (nombre, usos)\n" +
      inventory.spritesMasUsados.map((s2) => `${s2.name}\t${s2.usos}`).join("\n") +
      "\n"
  );
  console.log(`Inventario de ${SLUG}: ${maps.length} mapas · ${eventsTotal} eventos · ${sink.textLines} líneas de texto · ${trainers.total} entrenadores`);
  console.log(`→ ${path.relative(ROOT, outDir)}/inventory.json`);
  console.log(`→ ${path.relative(ROOT, outDir)}/informe.md`);
  if (tempDir) fs.rmSync(tempDir, { recursive: true, force: true });
  return inventory;
}

function renderReport(inv) {
  const top = (arr, key, n = 15) =>
    arr
      .slice()
      .sort((a, b) => (b[key] || 0) - (a[key] || 0))
      .slice(0, n)
      .map((m) => `- Map${m.id} · ${m.name || "(sin nombre)"} — ${m[key]} ${key === "commands" ? "comandos" : "eventos"}`)
      .join("\n");
  const flagsTop = (list) =>
    list
      .filter((f) => f.name && f.name.trim() && f.usos > 0)
      .slice(0, 40)
      .map((f) => `- [${f.id}] ${f.name} (${f.usos} usos)`)
      .join("\n");
  return `# Inventario de referencia: ${inv.slug}

Fuente: \`${inv.source}\` · ${inv.engine} · generado ${inv.generadoEn}
**Sólo metadatos: ningún sprite, música ni mapa del ROM se copia a Fire Ash.**

## Resumen

| Dato | Valor |
|---|---:|
| Mapas analizados | ${inv.resumen.mapas} de ${inv.resumen.mapasEnMapInfos} |
| Eventos | ${inv.resumen.eventos} |
| Páginas de evento | ${inv.resumen.paginas} |
| Comandos | ${inv.resumen.comandos} |
| Líneas de texto (diálogos) | ${inv.resumen.lineasDeTexto} |
| Switches con nombre | ${inv.resumen.switchesNombrados} |
| Variables con nombre | ${inv.resumen.variablesNombradas} |
| Switches usados en eventos | ${inv.resumen.switchesUsados} |
| Variables usadas en eventos | ${inv.resumen.variablesUsadas} |
| Eventos comunes (cinemáticas) | ${inv.resumen.commonEvents} |
| Entrenadores | ${inv.resumen.entrenadores} |

## Mapas con más contenido

${top(inv.mapas, "commands")}

## Mapas con más eventos

${top(inv.mapas, "events")}

## Flags más usadas (switches)

${flagsTop(inv.flags.switches) || "_Sin nombres de switch en System.rxdata._"}

## Variables más usadas

${flagsTop(inv.flags.variables) || "_Sin nombres de variable en System.rxdata._"}

## Cinemáticas (eventos comunes)

${
  inv.commonEvents
    .filter((c) => c.textLines > 0)
    .slice(0, 20)
    .map((c) => `**${c.id} · ${c.name || "(sin nombre)"}** — ${c.commands} comandos, ${c.textLines} líneas\n${c.preview.map((p) => `> ${p}`).join("\n")}`)
    .join("\n\n") || "_Sin eventos comunes con texto._"
}

## Recursos

${Object.entries(inv.graficos)
    .filter(([, v]) => v.count > 0)
    .map(([k, v]) => `- ${k}: ${v.count} archivos`)
    .join("\n")}
- Audio — BGM: ${inv.audio.BGM.count} · BGS: ${inv.audio.BGS.count} · ME: ${inv.audio.ME.count} · SE: ${inv.audio.SE.count}

## Entrenadores

${inv.batallas.total} entrenadores (${inv.batallas.formato}).
${
  inv.batallas.estadisticasEquipo
    ? `Equipo medio: ${inv.batallas.estadisticasEquipo.promedio} Pokémon · máximo: ${inv.batallas.estadisticasEquipo.maximo}.`
    : ""
}

${
  inv.batallas.muestra
    .slice(0, 12)
    .map(
      (t) =>
        `- **${t.trainerType} ${t.name}** — ${t.party.length} Pokémon (${t.party
          .map((p) => `${p.species} Nv${p.level}`)
          .join(", ")})${t.items && t.items.length ? ` · objetos: ${t.items.join(", ")}` : ""}`
    )
    .join("\n") || ""
}

## Catálogos de datos

${Object.entries(inv.catalogos || {})
  .map(([k, v]) => `- ${k}: ${v} registros`)
  .join("\n") || "_Sin catálogos .dat legibles._"}
`;
}

