const inputAt = process.argv.indexOf("--input");
const outputAt = process.argv.indexOf("--output");
const input = path.resolve(inputAt >= 0 ? process.argv[inputAt + 1] : path.join(ROOT, "content", "atlas_mil_region.pkregion"));
const output = path.resolve(outputAt >= 0 ? process.argv[outputAt + 1] : path.join(ROOT, "docs", "referencia_region_atlas_mil.png"));
const region = JSON.parse(fs.readFileSync(input, "utf8"));
const map = region.mapData;
const approvedCount = map.landmarks.filter((landmark) => landmark.pokemon.length > 0).length;
const plannedCount = map.landmarks.length - approvedCount;
const cell = 12;
const mapX = 34;
const mapY = 108;
const mapWidth = map.width * cell;
const mapHeight = map.height * cell;
const canvasWidth = 1400;
const canvasHeight = 900;
const colors = ["#9bcf63", "#77b74f", "#4d8c45", "#356044", "#80634b"];
const landmarkColors = { city: "#e05b45", town: "#eaa95d", route: "#f0d06f", cave: "#78658f", special: "#5e82c8" };
const quote = (text) => String(text).replaceAll("\\", "\\\\").replaceAll("'", "\\'");
const draw = [
  "stroke none",
  "font 'DejaVu-Sans'",
  "font-weight 700 fill '#f1ead7' font-size 28 text 34,45 'Atlas Mil · plano regional de autoría'",
  "font-weight 400 fill '#aeb9c5' font-size 15 text 34,76 'Referencia exportada desde el contrato .pkregion · 40 sectores · no es un mapa RMXP jugable'",
  `fill '#202a34' stroke '#6d7d8b' stroke-width 2 roundrectangle ${mapX - 5},${mapY - 5} ${mapX + mapWidth + 5},${mapY + mapHeight + 5} 5,5`,
  "stroke none",
];
const cellColor = (value) => value.water ? "#3398ba" : colors[Math.max(0, value.terrain)] ?? "#26313a";
for (let y = 0; y < map.height; y++) {
  let runStart = 0;
  let runColor = cellColor(map.cells[y][0]);
  for (let x = 1; x <= map.width; x++) {
    const nextColor = x < map.width ? cellColor(map.cells[y][x]) : null;
    if (nextColor !== runColor) {
      const x1 = mapX + runStart * cell;
      const y1 = mapY + y * cell;
      draw.push(`fill '${runColor}' rectangle ${x1},${y1} ${mapX + x * cell},${y1 + cell}`);
      runStart = x;
      runColor = nextColor;
    }
  }
  for (let x = 0; x < map.width; x++) if (map.cells[y][x].path) {
    const x1 = mapX + x * cell;
    const y1 = mapY + y * cell;
    draw.push(`fill '#e7bd6c' rectangle ${x1 + 3},${y1 + 3} ${x1 + cell - 3},${y1 + cell - 3}`);
  }
}
for (const landmark of map.landmarks) {
  const number = Number(landmark.id.slice(-2));
  const x = mapX + landmark.x * cell;
  const y = mapY + landmark.y * cell;
  const width = landmark.width * cell;
  const height = landmark.height * cell;
  draw.push(`fill '${landmarkColors[landmark.type]}' stroke '#fff4d6' stroke-width 1.5 roundrectangle ${x},${y} ${x + width},${y + height} 4,4`);
  draw.push(`stroke none fill '#10161e' font-weight 700 font-size 10 text ${x + 5},${y + height / 2 + 4} '${String(number).padStart(2, "0")}'`);
}
const panelX = mapX + mapWidth + 28;
draw.push(`fill '#18212b' stroke '#455463' stroke-width 1 roundrectangle ${panelX},${mapY - 5} ${panelX + 350},${mapY + mapHeight + 5} 6,6`);
draw.push(`stroke none fill '#f1ead7' font-weight 700 font-size 18 text ${panelX + 18},${mapY + 28} 'Sectores'`);
for (const [index, landmark] of map.landmarks.entries()) {
  const column = Math.floor(index / 20);
  const row = index % 20;
  const x = panelX + 18 + column * 170;
  const y = mapY + 58 + row * 28;
  const number = Number(landmark.id.slice(-2));
  const approved = landmark.pokemon.length > 0;
  draw.push(`fill '${approved ? "#69b578" : "#65707d"}' roundrectangle ${x},${y - 11} ${x + 15},${y + 4} 3,3`);
  draw.push(`fill '#dce4e9' font-weight 400 font-size 9 text ${x + 21},${y + 1} '${String(number).padStart(2, "0")} ${quote(landmark.name.slice(0, 20))}'`);
}
const legendY = mapY + 642;
draw.push(`fill '#f1ead7' font-weight 700 font-size 14 text ${panelX + 18},${legendY} 'Estado de contenido'`);
draw.push(`fill '#69b578' roundrectangle ${panelX + 18},${legendY + 15} ${panelX + 32},${legendY + 29} 3,3`);
draw.push(`fill '#c8d2da' font-weight 400 font-size 11 text ${panelX + 40},${legendY + 27} '${approvedCount} episodios aprobados'`);
draw.push(`fill '#65707d' roundrectangle ${panelX + 18},${legendY + 39} ${panelX + 32},${legendY + 53} 3,3`);
draw.push(`fill '#c8d2da' font-size 11 text ${panelX + 40},${legendY + 51} '${plannedCount} anclas planificadas'`);
draw.push("fill '#e2ba6d' font-size 13 text 34,862 'Uso: crítica de geografía, rutas, landmarks, encuentros y Pokédex. La salida final sigue el pipeline Essentials/RMXP con backup.'");
fs.mkdirSync(path.dirname(output), { recursive: true });
const result = spawnSync("/usr/bin/convert", ["-size", `${canvasWidth}x${canvasHeight}`, "xc:#10161e", "-draw", draw.join("\n"), output], { encoding: "utf8" });
if (result.error) throw result.error;
if (result.status !== 0) throw new Error(result.stderr || `ImageMagick terminó con código ${result.status}`);
console.log(`Referencia regional: ${path.relative(ROOT, output)} (${canvasWidth}x${canvasHeight}).`);#!/usr/bin/env node
/**
 * repair_map_data.mjs — arregla los datos de mapa que rompen el juego.
 *
 * Cubre dos fallos REALES y comprobados en este repositorio:
 *
 *  A) MAPA CON TILESET VACÍO (crash al entrar, y mapa en negro)
 *     El mapa 51 «Dungeon» (80×80) tiene `tileset_id = 7`, y el slot 7 de
 *     `Tilesets.rxdata` no tiene nombre. Al entrar —y se entra, porque el evento
 *     13 de «Rock Cave» (mapa 49) transfiere ahí— el motor hace
 *     `pbGetTileset(nil)` → `AnimatedBitmap.new(nil)` → «Filename is nil
 *     (missing graphic).» → error en pantalla. El mismo fallo deja el mapa negro.
 *     Arreglo: apuntar el mapa al tileset de su mapa padre (o al de un hermano,
 *     o al que diga `--tileset`).
 *
 *  B) SPRITE DE PERSONAJE CON CEROS DE MENOS (NPC invisible)
 *     12 nombres de sprite usados por eventos no existen en disco. Ocho de ellos
 *     son solo el mismo nombre sin los ceros de delante: los eventos piden
 *     «trchar41» y el archivo es «trchar041.png». El motor no revienta (usa un
 *     mapa de bits en blanco) pero el NPC NO SE VE. Arreglo: renombrar el campo
 *     `character_name` de esas páginas al nombre que existe de verdad.
 *
 * Lo que NO hace: no toca partidas (`Save*.rxdata`, `Game.rxdata`), no inventa
 * mapas ni gráficos, y no borra entradas de MapInfos. Todo cambio queda anotado
 * en `PokeModBackups/`.
 *
 * Uso:
 *   node tools/repair_map_data.mjs                 # informa y repara
 *   node tools/repair_map_data.mjs --dry-run       # solo informa
 *   node tools/repair_map_data.mjs --verify        # falla si queda algo roto
 *   node tools/repair_map_data.mjs --tileset 6     # tileset a usar en el caso A
 *   node tools/repair_map_data.mjs --game <ruta>
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ARGS = process.argv.slice(2);
const DRY = ARGS.includes("--dry-run");
const VERIFY = ARGS.includes("--verify");
const FORCE_TS = ARGS.includes("--tileset") ? Number(ARGS[ARGS.indexOf("--tileset") + 1]) : null;
const GAME = ARGS.includes("--game") ? path.resolve(ARGS[ARGS.indexOf("--game") + 1]) : path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const GRAFICOS = path.join(GAME, "Graphics");
const BACKUP = path.join(GAME, "PokeModBackups", "datos_reparados");

const txt = (v) => (v instanceof RString ? v.text : v == null ? "" : String(v));
const pad3 = (n) => String(n).padStart(3, "0");

if (!fs.existsSync(DATA)) { console.error(`✘ no existe ${DATA}`); process.exit(2); }

const infos = marshalLoad(new Uint8Array(fs.readFileSync(path.join(DATA, "MapInfos.rxdata"))));
const info = new Map([...infos.pairs].map(([k, v]) => [Number(k), { name: txt(v.getIvar("name")), parent: Number(v.getIvar("parent_id") || 0) }]));
const tilesets = marshalLoad(new Uint8Array(fs.readFileSync(path.join(DATA, "Tilesets.rxdata"))));
const tsNombre = (i) => { const t = tilesets[i]; return t ? txt(t.getIvar("tileset_name")) : null; };
const slotsVacios = new Set();
tilesets.forEach((t, i) => { if (!t || !txt(t.getIvar("tileset_name"))) slotsVacios.add(i); });

const mapIds = fs.readdirSync(DATA).filter((f) => /^Map\d+\.rxdata$/i.test(f)).map((f) => Number(f.replace(/\D/g, ""))).sort((a, b) => a - b);
const readMap = (id) => marshalLoad(new Uint8Array(fs.readFileSync(path.join(DATA, `Map${pad3(id)}.rxdata`))));

// Palabras reservadas del diccionario de sprites: nunca se tocan
const charDir = fs.existsSync(path.join(GRAFICOS, "Characters")) ? fs.readdirSync(path.join(GRAFICOS, "Characters")) : [];
const charBases = new Set(charDir.map((f) => f.replace(/\.[^.]+$/, "")));
const charLower = new Map(charDir.map((f) => [f.replace(/\.[^.]+$/, "").toLowerCase(), f.replace(/\.[^.]+$/, "")]));

const acciones = [];
const avisos = [];
const log = [];

// ------------------------------------------------------------------ A) tileset
function tilesetDeReemplazo(id, mapa) {
  if (FORCE_TS != null && !slotsVacios.has(FORCE_TS)) return { ts: FORCE_TS, motivo: "--tileset indicado a mano" };
  const padre = info.get(id)?.parent;
  if (padre && fs.existsSync(path.join(DATA, `Map${pad3(padre)}.rxdata`))) {
    const pm = readMap(padre);
    const t = Number(pm.getIvar("tileset_id"));
    if (!slotsVacios.has(t)) return { ts: t, motivo: `tileset del mapa padre ${padre} «${info.get(padre)?.name ?? ""}»` };
  }
  for (const otro of mapIds) {
    if (otro === id) continue;
    if (info.get(otro)?.parent !== padre) continue;
    const m = readMap(otro);
    const t = Number(m.getIvar("tileset_id"));
    if (!slotsVacios.has(t)) return { ts: t, motivo: `tileset del mapa hermano ${otro} «${info.get(otro)?.name ?? ""}»` };
  }
  // último recurso: el tileset más usado por mapas del mismo tamaño y nombre parecido
  const palabra = (info.get(id)?.name ?? "").toLowerCase().split(/\s+/)[0];
  const conteo = new Map();
  for (const otro of mapIds) {
    if (otro === id) continue;
    const nom = (info.get(otro)?.name ?? "").toLowerCase();
    if (!palabra || !nom.includes(palabra)) continue;
    const t = Number(readMap(otro).getIvar("tileset_id"));
    if (!slotsVacios.has(t)) conteo.set(t, (conteo.get(t) || 0) + 1);
  }
  const mejor = [...conteo].sort((a, b) => b[1] - a[1])[0];
  if (mejor) return { ts: mejor[0], motivo: `tileset más usado por mapas llamados «${palabra}…» (${mejor[1]} mapas)` };
  return null;
}

const mapasConTilesetRoto = [];
for (const id of mapIds) {
  const m = readMap(id);
  const tid = Number(m.getIvar("tileset_id"));
  if (!slotsVacios.has(tid) && tid >= 0 && tid < tilesets.length) continue;
  mapasConTilesetRoto.push({ id, tid, mapa: m });
}
if (mapasConTilesetRoto.length) {
  console.log(`\nA) mapas con tileset vacío o inválido: ${mapasConTilesetRoto.length}`);
  for (const { id, tid, mapa } of mapasConTilesetRoto) {
    const rep = tilesetDeReemplazo(id, mapa);
    if (!rep) { avisos.push(`mapa ${id}: tileset ${tid} inválido y sin reemplazo claro`); console.log(`   ✘ ${id} «${info.get(id)?.name}»: tileset ${tid} · sin reemplazo claro (no se toca)`); continue; }
    console.log(`   → ${id} «${info.get(id)?.name}»: tileset ${tid} → ${rep.ts} «${tsNombre(rep.ts)}» (${rep.motivo})`);
    acciones.push({ tipo: "tileset", id, de: tid, a: rep.ts });
    log.push({ tipo: "tileset", mapa: id, nombre: info.get(id)?.name, de: tid, a: rep.ts, motivo: rep.motivo });
  }
} else console.log("\nA) ✔ ningún mapa apunta a un tileset vacío");

// ------------------------------------------------- B) sprites con ceros de menos
const sprites = new Map();
for (const id of mapIds) {
  const m = readMap(id);
  for (const [, ev] of m.getIvar("events")?.pairs ?? []) {
    for (const pg of ev.getIvar("pages") || []) {
      const g = pg.getIvar("graphic");
      const cn = txt(g?.getIvar("character_name"));
      if (!cn || charBases.has(cn)) continue;
      const corregido = charLower.get(cn.toLowerCase()) ?? charLower.get(cn.replace(/^trchar0*/, "trchar0").toLowerCase());
      if (!corregido) continue;
      // solo si el nombre corregido es el mismo número (ceros de menos de verdad)
      const num = (s) => Number((s.match(/(\d+)/) || [])[1] || -1);
      if (num(corregido) !== num(cn)) continue;
      const clave = `${id}|${cn}|${corregido}`;
      if (!sprites.has(clave)) sprites.set(clave, { id, cn, corregido, paginas: 0, tipo: cn.toLowerCase() === corregido.toLowerCase() ? "ceros" : "mayúsculas" });
      sprites.get(clave).paginas++;
    }
  }
}
if (sprites.size) {
  console.log(`\nB) sprites con el nombre mal escrito (NPC invisible): ${sprites.size} combinación(es)`);
  for (const v of sprites.values()) {
    console.log(`   → mapa ${v.id} [${v.tipo}]: «${v.cn}» → «${v.corregido}» (${v.paginas} página/s)`);
    acciones.push({ tipo: "sprite", ...v });
    log.push({ tipo: "sprite", causa: v.tipo, mapa: v.id, nombre: info.get(v.id)?.name, de: v.cn, a: v.corregido, paginas: v.paginas });
  }
} else console.log("\nB) ✔ ningún sprite usa un nombre que exista con otros ceros");

// ------------------------------------------------------------------- escritura
if (!acciones.length) {
  console.log(VERIFY ? "\n✔ nada roto que reparar" : "\n✔ nada que reparar");
  process.exit(0);
}
if (DRY) {
  console.log(`\n(simulación) ${acciones.length} cambio(s) pendientes; nada escrito`);
  process.exit(VERIFY ? 1 : 0);
}
if (VERIFY) {
  console.log(`\n✘ ${acciones.length} problema(s) sin arreglar todavía`);
  process.exit(1);
}

const porMapa = new Map();
for (const a of acciones) {
  if (!porMapa.has(a.id)) porMapa.set(a.id, []);
  porMapa.get(a.id).push(a);
}
for (const [id, lista] of porMapa) {
  const file = path.join(DATA, `Map${pad3(id)}.rxdata`);
  const m = marshalLoad(new Uint8Array(fs.readFileSync(file)));
  for (const a of lista) {
    if (a.tipo === "tileset") m.setIvar("tileset_id", a.a);
    else {
      for (const [, ev] of m.getIvar("events")?.pairs ?? []) {
        for (const pg of ev.getIvar("pages") || []) {
          const g = pg.getIvar("graphic");
          if (g && txt(g.getIvar("character_name")) === a.cn) g.setIvar("character_name", new RString(a.corregido));
        }
      }
    }
  }
  fs.writeFileSync(file, Buffer.from(marshalDump(m)));
}
fs.mkdirSync(BACKUP, { recursive: true });
const logFile = path.join(BACKUP, "datos_reparados.json");
const prev = fs.existsSync(logFile) ? JSON.parse(fs.readFileSync(logFile, "utf8")) : [];
fs.writeFileSync(logFile, JSON.stringify([...prev, { cuando: new Date().toISOString(), cambios: log }], null, 2));
console.log(`\n✔ ${porMapa.size} mapa(s) reparados · anotado en ${path.relative(ROOT, logFile)}`);
if (avisos.length) { console.log("⚠ pendiente de decisión:"); avisos.forEach((a) => console.log(`   · ${a}`)); }// ============================================================================
// repair_map_metadata_classes.mjs
// ----------------------------------------------------------------------------
// Corrige el defecto de arranque "undefined class/module RPG::MapMetadata":
// los map_metadata.dat distribuidos contenían entradas serializadas como
// RPG::MapMetadata (clase de Essentials v16 que este juego, basado en el
// modelo v19 con GameData::MapMetadata, nunca define). Al hacer load_data en
// el arranque, Ruby aborta con ArgumentError antes de llegar al título.
//
// Este tool convierte cada entrada RPG::MapMetadata en GameData::MapMetadata
// (conservando sus ivars existentes y fijando @id), en los cuatro .dat que se
// distribuyen. Con --verify solo comprueba que no quede ninguna entrada mala.
//
//   node tools/repair_map_metadata_classes.mjs            # repara
//   node tools/repair_map_metadata_classes.mjs --verify   # solo comprueba
// ============================================================================

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RObject } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const TARGETS = [
  "pokemon_fire_ash/Data/map_metadata.dat",
  "Scripts_corregido/Paquete_directo/Data/map_metadata.dat",
  "Scripts_corregido/Expansion_Multiversal/Data/map_metadata.dat",
  "Scripts_corregido/Dimensional_Nightmare_QA/Data/map_metadata.dat",
];

const verify = process.argv.includes("--verify");
let malas = 0;

for (const rel of TARGETS) {
  const file = path.join(ROOT, rel);
  if (!fs.existsSync(file)) {
    console.log(`· sin archivo: ${rel}`);
    continue;
  }
  const meta = marshalLoad(fs.readFileSync(file));
  const malasAqui = meta.pairs.filter(([, o]) => o && o.className === "RPG::MapMetadata").length;
  malas += malasAqui;
  if (verify) {
    console.log(`${malasAqui ? "✘" : "✔"} ${rel}: ${malasAqui} entradas RPG::MapMetadata`);
    continue;
  }
  if (malasAqui === 0) {
    console.log(`✔ ${rel}: nada que convertir`);
    continue;
  }
  meta.pairs = meta.pairs.map(([k, o]) => {
    if (o && o.className === "RPG::MapMetadata") {
      const sano = new RObject("GameData::MapMetadata", [["@id", Number(k)]]);
      for (const [ik, iv] of o.ivars) sano.setIvar(ik, iv);
      return [k, sano];
    }
    return [k, o];
  });
  fs.writeFileSync(file, Buffer.from(marshalDump(meta)));
  console.log(`✔ ${rel}: ${malasAqui} entradas convertidas a GameData::MapMetadata`);
}

if (verify) {
  if (malas > 0) {
    console.error(`✘ quedan ${malas} entradas RPG::MapMetadata en los .dat distribuidos`);
    process.exit(1);
  }
  console.log("OK: ningún map_metadata.dat distribuido contiene RPG::MapMetadata");
} else {
  console.log(malas > 0 ? `OK: ${malas} entradas reparadas en total` : "OK: todos los .dat ya estaban sanos");
}#!/usr/bin/env node
/**
 * repair_missing_maps.mjs
 *
 * «Mapas en negro, muchas crash.»
 *
 * Fire Ash arrastra un hueco real de datos: `Data/MapInfos.rxdata` lista mapas
 * cuyo archivo `Data/MapNNNN.rxdata` NO existe. En este repositorio es el caso
 * de:
 *
 *   · **2231 — «TFOH — Cámara de la Primera Huella»**: el mapa está en la lista
 *     (y el sistema de atavíos lo tiene en rango) pero no hay archivo. En el
 *     juego, entrar ahí —o cargar una partida guardada dentro— es un error al
 *     vuelo (`No such file or directory - Data/Map2231.rxdata`). En PokeMod era
 *     el único mapa de los 3 465 que fallaba al dibujarse.
 *   · El gemelo **2243** sí tiene archivo y se llama exactamente igual (TFOH —
 *     Cámara de la Primera Huella, colgado de 2242 «TFOH — Frontera del
 *     Origen»). 2231 cuelga de 2230 («Atlas — Avenida de los Ocho Gimnasios»),
 *     que es el mismo sitio al que apunta el atavío 6 de `PokeMod_Atavios`.
 *
 * Qué hace esta herramienta, sin inventar contenido:
 *
 *   1. Localiza TODO mapa de MapInfos sin archivo.
 *   2. Para cada hueco elige la fuente más honesta, en este orden:
 *        a) un mapa del mismo padre con el MISMO nombre;
 *        b) un mapa con el MISMO nombre (el más cercano en id);
 *        c) `--reuse <origen>` explícito.
 *      Si no hay fuente clara, NO toca nada y lo reporta (mejor un aviso que
 *      contenido inventado).
 *   3. Copia el archivo origen al id que falta y deja constancia en
 *      `PokeModBackups/mapas_reparados.json` (nada de borrar entradas de la
 *      lista: eso cambiaría la numeración que usa el juego).
 *
 * Uso:
 *   node tools/repair_missing_maps.mjs                 # informa y repara
 *   node tools/repair_missing_maps.mjs --dry-run       # solo informa
 *   node tools/repair_missing_maps.mjs --reuse 2243    # fuente explícita
 *   node tools/repair_missing_maps.mjs --verify        # falla si queda algún hueco
 *
 * Sale con código 1 en `--verify` si aún hay mapas listados sin archivo.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { marshalLoad, RString } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ARGS = process.argv.slice(2);
const DRY = ARGS.includes("--dry-run");
const VERIFY = ARGS.includes("--verify");
const REUSE = ARGS.includes("--reuse") ? Number(ARGS[ARGS.indexOf("--reuse") + 1]) : 0;
const pad3 = (n) => String(n).padStart(3, "0");

// Juego completo del repo: aquí un hueco en MapInfos es un fallo de verdad
// (el jugador entra y el motor revienta).
const FULL_GAME = "pokemon_fire_ash";
// Paquetes corregidos: son parches, traen MapInfos completo pero solo los mapas
// que cambian; sus «huecos» son el resto del juego y NO se tocan.
const PACKAGES = [
  "Scripts_corregido/Paquete_directo",
  "Scripts_corregido/Dimensional_Nightmare_QA",
  "Scripts_corregido/Ciudad_Teckel_Paraiso",
  "Scripts_corregido/Expansion_Multiversal",
];
const TARGETS = [FULL_GAME, ...PACKAGES];

const txt = (v) => (v instanceof RString ? v.text : v == null ? "" : String(v));

function readInfos(dataDir) {
  const raw = marshalLoad(new Uint8Array(fs.readFileSync(path.join(dataDir, "MapInfos.rxdata"))));
  const out = [];
  for (const [k, v] of raw.pairs) {
    out.push({
      id: Number(k),
      name: txt(v.getIvar("name")),
      parent: Number(v.getIvar("parent_id") || 0),
      order: Number(v.getIvar("order") || 0),
    });
  }
  return out;
}

function audit(dataDir) {
  const infos = readInfos(dataDir);
  const withFile = new Set();
  for (const f of fs.readdirSync(dataDir)) {
    const m = f.match(/^Map(\d+)\.rxdata$/i);
    if (m) withFile.add(Number(m[1]));
  }
  const missing = infos.filter((i) => !withFile.has(i.id));
  return { infos, withFile, missing };
}

function pickSource(info, infos, withFile) {
  if (REUSE && withFile.has(REUSE)) return { id: REUSE, why: "--reuse indicado a mano" };
  const sameNameSameParent = infos
    .filter((i) => withFile.has(i.id) && i.id !== info.id && i.parent === info.parent && i.name === info.name)
    .sort((a, b) => Math.abs(a.id - info.id) - Math.abs(b.id - info.id))[0];
  if (sameNameSameParent) return { id: sameNameSameParent.id, why: "mismo nombre y mismo padre" };
  const sameName = infos
    .filter((i) => withFile.has(i.id) && i.id !== info.id && i.name === info.name)
    .sort((a, b) => Math.abs(a.id - info.id) - Math.abs(b.id - info.id))[0];
  if (sameName) return { id: sameName.id, why: "mismo nombre (gemelo del DLC)" };
  return null;
}

let fallos = 0;
let reparados = 0;
let sinSolucion = 0;

for (const rel of TARGETS) {
  const dataDir = path.join(ROOT, rel, "Data");
  if (!fs.existsSync(path.join(dataDir, "MapInfos.rxdata"))) {
    console.log(`— ${rel}: sin Data/MapInfos.rxdata (se salta)`);
    continue;
  }
  const { infos, missing, withFile } = audit(dataDir);
  console.log(`\n=== ${rel}: ${infos.length} entradas · ${withFile.size} archivos · ${missing.length} hueco(s)`);
  if (!missing.length) {
    console.log("   ✔ sin mapas listados que falten");
    continue;
  }
  if (rel !== FULL_GAME) {
    console.log(`   (paquete parcial: los ${missing.length} huecos son mapas del juego que el parche no incluye — no se tocan)`);
    continue;
  }
  for (const info of missing) {
    const src = pickSource(info, infos, withFile);
    if (!src) {
      fallos++;
      sinSolucion++;
      console.log(`   ✘ ${info.id} «${info.name}» (padre ${info.parent}): sin archivo y sin gemelo claro → no se toca`);
      continue;
    }
    const origen = path.join(dataDir, `Map${pad3(src.id)}.rxdata`);
    const destino = path.join(dataDir, `Map${pad3(info.id)}.rxdata`);
    console.log(`   → ${info.id} «${info.name}»: copia de ${src.id} (${src.why})`);
    if (DRY || VERIFY) continue;
    if (!fs.existsSync(destino)) fs.copyFileSync(origen, destino);
    const backupDir = path.join(ROOT, rel, "PokeModBackups", "mapas_reparados");
    fs.mkdirSync(backupDir, { recursive: true });
    const log = path.join(backupDir, "mapas_reparados.json");
    const prev = fs.existsSync(log) ? JSON.parse(fs.readFileSync(log, "utf8")) : [];
    prev.push({
      faltaba: info.id,
      nombre: info.name,
      padre: info.parent,
      copiadoDe: src.id,
      motivo: src.why,
      cuando: new Date().toISOString(),
    });
    fs.writeFileSync(log, JSON.stringify(prev, null, 2));
    reparados++;
  }
  // reverificación
  const after = audit(dataDir).missing.length;
  console.log(`   ${after === 0 ? "✔" : "✘"} quedan ${after} hueco(s)`);
  if (after) fallos++;
}

const huecos = missingInFullGame();
console.log(`\n${VERIFY ? "Verificación" : DRY ? "Simulación" : "Reparación"}: ${huecos} hueco(s) en el juego completo, ${reparados} reparado(s)` + (sinSolucion ? `, ${sinSolucion} sin solución automática` : ""));
function missingInFullGame() {
  const dataDir = path.join(ROOT, FULL_GAME, "Data");
  if (!fs.existsSync(path.join(dataDir, "MapInfos.rxdata"))) return 0;
  return audit(dataDir).missing.length;
}
process.exit(VERIFY && huecos ? 1 : 0);# PokeMod tools: solo biblioteca estándar de Python 3.9+. Nada que instalar.#!/usr/bin/env node
/**
 * rom_nativo_mapas.mjs — mapas y tilesets NATIVOS de las ROMs invitadas.
 *
 * A diferencia del instalador estructural (que reconstruía los mapas con tiles de
 * Fire Ash), este módulo usa los gráficos del propio ROM:
 *
 *   1. Descodifica los tilesets (tiles 4bpp LZ77/RLE, paletas BGR555 y metatiles
 *      de dos capas) y los reescala ×2 a tiles RMXP de 32×32 — los metatiles de
 *      GBA son de 16×16.
 *   2. Convierte cada mapa con sus dimensiones y su bloque de borde originales.
 *   3. La pasabilidad sale de los bits 10-11 de cada celda del mapa (donde el
 *      editor la hornea y el motor la lee con `MapGridGetCollisionAt`), no de una
 *      tabla de comportamientos. Cuando un mismo metatile aparece en celdas
 *      libres y bloqueadas se emiten dos variantes (libre / sólida) para no
 *      perder ni un solo bit de la geometría original.
 *
 * Uso:
 *   node tools/rom_nativo_mapas.mjs --extract [--dir "roms pokemon"]
 *   node tools/rom_nativo_mapas.mjs --install
 *   node tools/rom_nativo_mapas.mjs --verify
 *
 * La ROM no se versiona: el plan (content/rom_nativo.json), los tilesets
 * (Graphics/Tilesets/ROMN_*.png) y los mapas reconstruidos sí.
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { marshalLoad, marshalDump, RObject, RString } from "../web/js/marshal.js";
import { parseMap, tableGet, tableToUserDef } from "../web/js/rmxp.js";
import { lz77 } from "./forense/gba.mjs";
import { pngIndizado, pngRGBA } from "./forense/png.mjs";
import { TileCanvas } from "./lib/map_painter.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const GRAPHICS = path.join(GAME, "Graphics", "Tilesets");
const ROM_GAMES = path.join(ROOT, "roms pokemon");
const WORK = path.join(ROOT, "reference", "roms_invitadas", "rom_nativo");
const PLAN_PATH = path.join(ROOT, "content", "rom_nativo.json");
const CAMPAIGNS_PATH = path.join(ROOT, "content", "rom_campaigns_complete.json");
const BACKUP = path.join(GAME, "PokeModBackups", "rom_nativo_mapas");
const TILE = 32;
const COLUMNS = 8;
const PASS_BLOCK = 0x0f;
const BASE_ID = 384;
/** Bits del mapa de Gen 3: 0-9 metatile, 10-11 colisión, 12-15 elevación. */
const COLISION_MASK = 0x0c00;
const ELEVACION_MASK = 0xf000;

const argv = process.argv.slice(2);
const flag = (name) => argv.includes(name);
const option = (name, fallback) => {
  const at = argv.indexOf(name);
  return at >= 0 && argv[at + 1] && !argv[at + 1].startsWith("--") ? argv[at + 1] : fallback;
};
const EXTRACT = flag("--extract");
const INSTALL = flag("--install");
const VERIFY = flag("--verify");
const DRY = flag("--dry-run");
const ROM_DIR = path.resolve(option("--dir", ROM_GAMES));

const read = (file) => marshalLoad(fs.readFileSync(path.join(DATA, file)));
const write = (file, value) => { if (!DRY) fs.writeFileSync(path.join(DATA, file), Buffer.from(marshalDump(value))); };
const S = (v) => RString.fromText(String(v));
const pad3 = (n) => String(n).padStart(3, "0");
const mapFile = (id) => `Map${pad3(id)}.rxdata`;
const sha1 = (buf) => crypto.createHash("sha1").update(buf).digest("hex").slice(0, 12);
const b64 = (u16) => Buffer.from(new Uint8Array(u16.buffer, u16.byteOffset, u16.byteLength)).toString("base64");
const deB64 = (text, expected) => {
  const buf = Buffer.from(text, "base64");
  const out = new Uint16Array(buf.length / 2);
  for (let i = 0; i < out.length; i += 1) out[i] = buf.readUInt16LE(i * 2);
  if (expected && out.length !== expected) throw new Error(`celdas ${out.length} ≠ ${expected}`);
  return out;
};
const blockedOf = (celda) => ((celda & COLISION_MASK) >> 10) !== 0;
const elevationOf = (celda) => (celda & ELEVACION_MASK) >> 12;

/* ─────────────────────────────── lectura de ROM ─────────────────────────── */

const u8 = (d, o) => d[o];
const u16 = (d, o) => d[o] | (d[o + 1] << 8);
const u32 = (d, o) => (d[o] | (d[o + 1] << 8) | (d[o + 2] << 16) | (d[o + 3] << 24)) >>> 0;
const offline = (ptr) => ptr - 0x08000000;

function descomprimir(data, ptr) {
  const o = offline(ptr);
  const cabecera = data[o];
  if (cabecera === 0x10) {
    const r = lz77(data, o);
    if (!r) throw new Error(`LZ77 inválido en 0x${ptr.toString(16)}`);
    return r.datos;
  }
  if (cabecera === 0x30) {
    const tam = u32(data, o + 1) & 0xffffff;
    const salida = new Uint8Array(tam);
    let p = o + 4, q = 0;
    while (q < tam && p < data.length) {
      const cab = data[p++];
      if (cab < 0x80) { const n = cab + 1; for (let k = 0; k < n && q < tam; k += 1) salida[q++] = data[p++]; }
      else { const v = data[p++]; const n = cab - 125; for (let k = 0; k < n && q < tam; k += 1) salida[q++] = v; }
    }
    if (q < tam) throw new Error("RLE incompleto");
    return salida;
  }
  throw new Error(`compresión desconocida 0x${cabecera.toString(16)} en 0x${ptr.toString(16)}`);
}

function leerLayout(data, headerOff) {
  const layout = offline(u32(data, headerOff));
  return {
    layout,
    width: u32(data, layout),
    height: u32(data, layout + 4),
    borderPtr: u32(data, layout + 8),
    mapPtr: u32(data, layout + 12),
    prim: u32(data, layout + 16),
    sec: u32(data, layout + 20),
    borderW: Math.max(1, u8(data, layout + 24)),
    borderH: Math.max(1, u8(data, layout + 25)),
  };
}

/**
 * Carga un PAR de tilesets (primario + secundario) con el modelo real de Gen 3:
 * los índices de tile y de paleta son absolutos en un espacio unificado de 1024
 * tiles (0-511 primarios, 512-1023 secundarios) y 16 paletas (0-5 primarias,
 * 6-15 secundarias).
 */
export function cargarPar(data, primPtr, secPtr) {
  const campos = (ptr) => {
    const o = offline(ptr);
    return { comprimido: u8(data, o) === 1, tiles: u32(data, o + 4), paletas: u32(data, o + 8), metatiles: u32(data, o + 12) };
  };
  const cPrim = campos(primPtr), cSec = campos(secPtr);
  const tiles = new Uint8Array(1024 * 64);
  const paletas = new Uint32Array(16 * 16);
  const metatiles = new Uint16Array(1024 * 8);
  const nTiles = (campo, destino, maximo) => {
    const bruto = campo.comprimido ? descomprimir(data, campo.tiles) : data.subarray(offline(campo.tiles));
    const n = Math.min(maximo, Math.floor(bruto.length / 32));
    for (let t = 0; t < n; t += 1) {
      for (let i = 0; i < 32; i += 1) {
        const byte = bruto[t * 32 + i];
        tiles[(destino + t) * 64 + i * 2] = byte & 0x0f;
        tiles[(destino + t) * 64 + i * 2 + 1] = byte >> 4;
      }
    }
    return n;
  };
  /**
   * Copia paletas a los slots globales. `desde` es la entrada de la tabla de
   * origen: el motor carga las paletas del tileset secundario empezando por su
   * entrada 6 (`LoadPalette(tileset->palettes[6], 6, ...)`), así que un metatile
   * con nibble 6 usa la entrada 6 —no la 0— del bloque secundario.
   */
  const leerPaletas = (ptr, destino, desde, cuantas) => {
    const o = offline(ptr);
    for (let k = 0; k < cuantas; k += 1) {
      const p = desde + k;
      for (let c = 0; c < 16; c += 1) {
        const v = u16(data, o + (p * 16 + c) * 2);
        const r = Math.round(((v & 31) * 255) / 31);
        const g = Math.round((((v >> 5) & 31) * 255) / 31);
        const b = Math.round((((v >> 10) & 31) * 255) / 31);
        paletas[(destino + k) * 16 + c] = (r << 24) | (g << 16) | (b << 8) | (c === 0 ? 0 : 255);
      }
    }
  };
  const copiarMetatiles = (ptr, destino) => {
    const o = offline(ptr);
    for (let i = 0; i < 512; i += 1) {
      for (let k = 0; k < 8; k += 1) metatiles[(destino + i) * 8 + k] = u16(data, o + (i * 8 + k) * 2);
    }
  };
  const nPrim = nTiles(cPrim, 0, 512);
  const nSec = nTiles(cSec, 512, 512);
  leerPaletas(cPrim.paletas, 0, 0, 6);
  leerPaletas(cSec.paletas, 6, 6, 10);
  copiarMetatiles(cPrim.metatiles, 0);
  copiarMetatiles(cSec.metatiles, 512);
  return { tiles, paletas, metatiles, nPrim, nSec };
}

/** Dibuja un metatile de 16×16 (dos capas) reescalado ×2 → bloque RGBA de 32×32. */
export function renderMetatile(par, metatileId, buffer) {
  const base = (metatileId & 0x3ff) * 8;
  for (let capa = 0; capa < 2; capa += 1) {
    for (let i = 0; i < 4; i += 1) {
      const entrada = par.metatiles[base + capa * 4 + i];
      const tileId = entrada & 0x3ff;
      const hf = (entrada >> 10) & 1;
      const vf = (entrada >> 11) & 1;
      const paletaIdx = (entrada >> 12) & 0xf;
      const tile = par.tiles.subarray(tileId * 64, tileId * 64 + 64);
      const ox = (i % 2) * 16;
      const oy = Math.floor(i / 2) * 16;
      for (let y = 0; y < 8; y += 1) {
        for (let x = 0; x < 8; x += 1) {
          const color = par.paletas[paletaIdx * 16 + tile[(vf ? 7 - y : y) * 8 + (hf ? 7 - x : x)]];
          if ((color & 0xff) === 0) continue;
          for (let dy = 0; dy < 2; dy += 1) {
            for (let dx = 0; dx < 2; dx += 1) {
              const at = ((oy + y * 2 + dy) * TILE + ox + x * 2 + dx) * 4;
              buffer[at] = (color >> 24) & 0xff;
              buffer[at + 1] = (color >> 16) & 0xff;
              buffer[at + 2] = (color >> 8) & 0xff;
              buffer[at + 3] = 255;
            }
          }
        }
      }
    }
  }
}

/** PNG indexado si la paleta cabe en 255 colores; si no, RGBA. */
export function escribirPng(rgba, ancho, alto) {
  const colores = new Map();
  const indices = new Uint8Array(ancho * alto);
  let desbordado = false;
  for (let i = 0; i < ancho * alto && !desbordado; i += 1) {
    const r = rgba[i * 4], g = rgba[i * 4 + 1], b = rgba[i * 4 + 2], a = rgba[i * 4 + 3];
    const clave = a === 0 ? "t" : `${r},${g},${b}`;
    if (!colores.has(clave)) {
      if (colores.size >= 255) { desbordado = true; break; }
      colores.set(clave, colores.size + 1);
    }
    indices[i] = colores.get(clave);
  }
  if (desbordado) return pngRGBA(ancho, alto, rgba);
  const paleta = [[0, 0, 0, 0]];
  for (const clave of colores.keys()) {
    if (clave === "t") { paleta.push([0, 0, 0, 0]); continue; }
    const [r, g, b] = clave.split(",").map(Number);
    paleta.push([r, g, b, 255]);
  }
  return pngIndizado(ancho, alto, indices, paleta);
}

/* ───────────────────────────────── extracción ───────────────────────────── */

function forense(slug, romPath) {
  fs.mkdirSync(WORK, { recursive: true });
  execFileSync(process.execPath, ["tools/gba_maps_events.mjs", "--rom", romPath], {
    cwd: ROOT, env: { ...process.env, ROM_OUT_DIR: WORK }, stdio: "inherit",
  });
  const archivo = path.join(WORK, path.basename(romPath).replace(/\.(gba|gb|gbc)$/i, ""), "mapas_npcs.json");
  const json = JSON.parse(fs.readFileSync(archivo, "utf8"));
  const indice = new Map();
  for (const mapa of json.mapas) indice.set(`${mapa.banco}:${mapa.indice}`, mapa);
  return indice;
}

function extraer() {
  const plan = JSON.parse(fs.readFileSync(CAMPAIGNS_PATH, "utf8"));
  const salida = { generatedBy: "tools/rom_nativo_mapas.mjs", fuente: "ROMs invitadas (GBA)", campaigns: {} };
  let totalMapas = 0, totalTilesets = 0;
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    const romPath = path.join(ROM_DIR, campana.sourceRom);
    if (!fs.existsSync(romPath)) { console.log(`  · ${clave}: ROM ausente (${campana.sourceRom}); se omite`); continue; }
    const data = fs.readFileSync(romPath);
    const index = forense(clave, romPath);
    const pares = new Map();
    const mapas = {};
    for (const blueprint of campana.maps) {
      const ficha = index.get(`${blueprint.source.bank}:${blueprint.source.map}`);
      if (!ficha) continue;
      const layout = leerLayout(data, ficha.header);
      const clavePar = `${layout.prim}+${layout.sec}`;
      if (!pares.has(clavePar)) pares.set(clavePar, { prim: layout.prim, sec: layout.sec, par: cargarPar(data, layout.prim, layout.sec), variantes: new Map() });
      const par = pares.get(clavePar);
      const celdas = new Uint16Array(layout.width * layout.height);
      const mo = offline(layout.mapPtr);
      for (let i = 0; i < celdas.length; i += 1) {
        const celda = u16(data, mo + i * 2);
        celdas[i] = celda;
        const metatile = celda & 0x3ff;
        const bloqueado = blockedOf(celda) ? 1 : 0;
        const uso = par.variantes.get(metatile) ?? [0, 0];
        uso[bloqueado] += 1;
        par.variantes.set(metatile, uso);
      }
      const borde = new Uint16Array(layout.borderW * layout.borderH);
      const bo = offline(layout.borderPtr);
      for (let i = 0; i < borde.length; i += 1) borde[i] = u16(data, bo + i * 2);
      mapas[blueprint.mapId] = {
        banco: blueprint.source.bank, indice: blueprint.source.map, par: clavePar,
        width: layout.width, height: layout.height,
        borderWidth: layout.borderW, borderHeight: layout.borderH,
        celdas: b64(celdas), borde: b64(borde),
        elevaciones: [...new Set(Array.from(celdas, (c) => elevationOf(c)))].sort((a, b) => a - b),
        npcs: (ficha.npcsDetalle ?? []).map((n) => ({ x: n.x, y: n.y, sprite: n.sprite })),
        textos: (ficha.scripts ?? []).flatMap((s) => (s.textos ?? []).map((t) => ({ x: s.x, y: s.y, texto: t }))),
        warps: (ficha.warpsDetalle ?? []).length,
      };
      totalMapas += 1;
    }
    const tilesets = [];
    for (const [clavePar, entidad] of pares) {
      const par = entidad.par;
      // Variantes: cada metatile usado se emite libre y/o sólido según su uso real.
      // Ambas variantes por metatile: la instalación necesita la versión
      // transitable para abrir los accesos a los eventos sin cambiar el dibujo.
      const variantes = [];
      for (const [metatile] of [...entidad.variantes].sort((a, b) => a[0] - b[0])) {
        variantes.push({ metatile, bloqueado: 0 });
        variantes.push({ metatile, bloqueado: 1 });
      }
      const filas = Math.max(1, Math.ceil(variantes.length / COLUMNS));
      const ancho = COLUMNS * TILE, alto = filas * TILE;
      const rgba = new Uint8Array(ancho * alto * 4);
      const total = BASE_ID + variantes.length;
      const pasajes = new Uint16Array(total);
      const prioridades = new Uint16Array(total);
      const comportamiento = new Uint16Array(total);
      const porMetatile = {};
      variantes.forEach((variante, i) => {
        // El motor lee el tile k de la imagen del tileset como id 384+k.
        const local = BASE_ID + i;
        const buffer = new Uint8Array(TILE * TILE * 4);
        renderMetatile(par, variante.metatile, buffer);
        const col = i % COLUMNS, fila = Math.floor(i / COLUMNS);
        for (let y = 0; y < TILE; y += 1) {
          const destino = ((fila * TILE + y) * ancho + col * TILE) * 4;
          rgba.set(buffer.subarray(y * TILE * 4, y * TILE * 4 + TILE * 4), destino);
        }
        pasajes[local] = variante.bloqueado ? PASS_BLOCK : 0;
        const filaUso = porMetatile[variante.metatile] ?? [0, 0];
        filaUso[variante.bloqueado] = local;
        porMetatile[variante.metatile] = filaUso;
      });
      const nombre = `ROMN_${clave}_p${tilesets.length + 1}`;
      const bytes = escribirPng(rgba, ancho, alto);
      if (!DRY) { fs.mkdirSync(GRAPHICS, { recursive: true }); fs.writeFileSync(path.join(GRAPHICS, `${nombre}.png`), bytes); }
      tilesets.push({
        nombre, png: `${nombre}.png`, sha1: sha1(bytes), ancho, alto, tiles: variantes.length,
        porMetatile, pasajes: Array.from(pasajes), comportamiento: Array.from(comportamiento),
        prim: entidad.prim, sec: entidad.sec,
        nTilesPrim: par.nPrim, nTilesSec: par.nSec,
        bloqueados: variantes.filter((v) => v.bloqueado).length,
      });
      totalTilesets += 1;
    }
    for (const mapa of Object.values(mapas)) {
      const ts = tilesets.find((t) => `${t.prim}+${t.sec}` === mapa.par);
      const traduce = (celda) => {
        const fila = ts.porMetatile[celda & 0x3ff];
        if (!fila) return 0;
        return fila[blockedOf(celda) ? 1 : 0] || fila[0] || fila[1] || 0;
      };
      const celdas = deB64(mapa.celdas, mapa.width * mapa.height);
      const borde = deB64(mapa.borde, mapa.borderWidth * mapa.borderHeight);
      mapa.celdas = b64(Uint16Array.from(celdas, traduce));
      mapa.borde = b64(Uint16Array.from(borde, traduce));
      mapa.tileset = ts.nombre;
    }
    salida.campaigns[clave] = { rom: campana.sourceRom, tilesets, maps: mapas };
    const variantes = tilesets.reduce((suma, t) => suma + t.tiles, 0);
    console.log(`  · ${clave}: ${Object.keys(mapas).length} mapas nativos · ${tilesets.length} tilesets (${variantes} metatiles, ${tilesets.reduce((s, t) => s + t.bloqueados, 0)} sólidos)`);
  }
  salida.resumen = { mapas: totalMapas, tilesets: totalTilesets };
  if (!DRY) fs.writeFileSync(PLAN_PATH, `${JSON.stringify(salida)}\n`);
  console.log(`✅ Plan nativo: ${totalMapas} mapas · ${totalTilesets} tilesets → content/rom_nativo.json`);
}

/* ────────────────────────────────── instalación ─────────────────────────── */

function planNativo() {
  if (!fs.existsSync(PLAN_PATH)) throw new Error("Falta content/rom_nativo.json; corre --extract");
  return JSON.parse(fs.readFileSync(PLAN_PATH, "utf8"));
}

function instalarTileset(plan, guardar) {
  const raw = read("Tilesets.rxdata");
  const ids = new Map();
  for (const campana of Object.values(plan.campaigns)) {
    for (const ts of campana.tilesets) {
      const existente = raw.findIndex((e) => e && String(e.getIvar?.("@tileset_name")?.text ?? "") === ts.nombre);
      const id = existente > 0 ? existente : raw.length;
      const total = ts.total ?? (BASE_ID + ts.tiles);
      const tabla = (datos) => tableToUserDef({ dim: 1, x: total, y: 1, z: 1, data: Uint16Array.from(datos) });
      const obj = new RObject("RPG::Tileset", [
        ["@id", id],
        ["@name", S(`ROM nativo — ${ts.nombre}`)],
        ["@tileset_name", S(ts.nombre)],
        ["@autotile_names", Array.from({ length: 7 }, () => S(""))],
        ["@panorama_name", S("")], ["@panorama_hue", 0],
        ["@fog_name", S("")], ["@fog_hue", 0], ["@fog_opacity", 64],
        ["@fog_blend_type", 0], ["@fog_zoom", 200], ["@fog_sx", 0], ["@fog_sy", 0],
        ["@battleback_name", S("")],
        ["@passages", tabla(ts.pasajes)],
        ["@priorities", tabla(new Uint16Array(total))],
        ["@terrain_tags", tabla(new Uint16Array(total))],
      ]);
      if (existente > 0) raw[existente] = obj; else raw.push(obj);
      ids.set(ts.nombre, id);
      const destino = path.join(GRAPHICS, ts.png);
      const bytes = fs.existsSync(destino) ? fs.readFileSync(destino) : null;
      if (!bytes || sha1(bytes) !== ts.sha1) {
        throw new Error(`Falta el tileset nativo ${ts.png} (o no coincide su huella). Corre --extract`);
      }
    }
  }
  guardar("Tilesets.rxdata", raw);
  return ids;
}

/** id local transitable de un metatile, a partir de su variante sólida. */
function varianteLibre(planTs, idTraducido) {
  for (const fila of Object.values(planTs.porMetatile)) {
    if (fila[1] === idTraducido) return fila[0];
  }
  return idTraducido;
}

/**
 * La instalación estructural colocó NPCs, warps y puntos de retorno con SU propia
 * rejilla; sobre el mapa nativo unas pocas de esas celdas son sólidas. Aquí se
 * pinta la variante TRANSITABLE del mismo metatile (idéntico dibujo, sin colisión)
 * únicamente en las celdas ocupadas por un evento: el resto del mapa queda célula
 * a célula como la ROM. Sin esto los NPCs y los warps quedarían inalcanzables.
 */
function abrirCeldasDeEventos(canvas, objeto, planTs) {
  const pasajes = planTs.pasajes;
  const gemeloLibre = new Map();
  for (const fila of Object.values(planTs.porMetatile)) if (fila[0] && fila[1]) gemeloLibre.set(fila[1], fila[0]);
  let abiertas = 0;
  for (const [, evento] of objeto.getIvar("@events").pairs) {
    const x = Number(evento.getIvar("@x"));
    const y = Number(evento.getIvar("@y"));
    if (!canvas.inside(x, y)) continue;
    const actual = canvas.get(x, y, 0);
    if ((pasajes[actual] ?? 0) === 0) continue;
    const libre = gemeloLibre.get(actual);
    if (!libre) continue;
    canvas.set(x, y, 0, libre);
    abiertas += 1;
  }
  return abiertas;
}

function textoDeNombre(valor) {
  return valor?.bytes ? Buffer.from(valor.bytes).toString("utf8") : String(valor ?? "");
}

function instalar() {
  const plan = planNativo();
  fs.mkdirSync(BACKUP, { recursive: true });
  const blueprint = JSON.parse(fs.readFileSync(CAMPAIGNS_PATH, "utf8"));
  const meta = new Map();
  for (const campana of Object.values(blueprint.campaigns)) for (const m of campana.maps) meta.set(m.mapId, m);
  let mapas = 0, textos = 0, aperturasTotal = 0;
  const ids = instalarTileset(plan, write);
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    for (const [idTexto, mapa] of Object.entries(campana.maps)) {
      const mapId = Number(idTexto);
      const archivo = path.join(DATA, mapFile(mapId));
      const respaldo = path.join(BACKUP, mapFile(mapId));
      if (!fs.existsSync(respaldo) && fs.existsSync(archivo)) fs.copyFileSync(archivo, respaldo);
      const objeto = read(mapFile(mapId));
      const width = Number(objeto.getIvar("@width"));
      const height = Number(objeto.getIvar("@height"));
      const celdas = deB64(mapa.celdas, mapa.width * mapa.height);
      const borde = deB64(mapa.borde, mapa.borderWidth * mapa.borderHeight);
      const canvas = new TileCanvas(width, height, ids.get(mapa.tileset));
      const celda = (x, y) => (x < mapa.width && y < mapa.height
        ? celdas[y * mapa.width + x]
        : borde[(y % mapa.borderHeight) * mapa.borderWidth + (x % mapa.borderWidth)] ?? 0);
      for (let y = 0; y < height; y += 1) for (let x = 0; x < width; x += 1) canvas.set(x, y, 0, celda(x, y));
      const planTs = campana.tilesets.find((t) => t.nombre === mapa.tileset);
      const aperturas = abrirCeldasDeEventos(canvas, objeto, planTs);
      objeto.setIvar("@tileset_id", canvas.tilesetId);
      objeto.setIvar("@data", tableToUserDef(canvas.toTable()));
      // Diálogos ORIGINALES de la ROM: cada evento de campaña se corresponde, en
      // orden, con un NPC del plan estructural (nombre `..._<capítulo>_<k>`) y ese
      // NPC viene de una celda del ROM cuya conversación ya está en el plan.
      // Se inyectan las líneas del ROM sobre los mensajes del evento, sin
      // inventar texto; si el NPC no tiene guion, se conserva el andamiaje.
      const blueprint = meta.get(mapId);
      const eventos = objeto.getIvar("@events");
      for (const [, evento] of eventos.pairs) {
        const nombre = textoDeNombre(evento.getIvar("@name"));
        if (!nombre.includes("PokeMod Campaña ROM")) continue;
        const x = Number(evento.getIvar("@x"));
        const y = Number(evento.getIvar("@y"));
        let lineas = [];
        const sufijo = /_(\d+)$/.exec(nombre);
        const npc = sufijo ? (blueprint?.npcs ?? [])[Number(sufijo[1]) - 1] : null;
        if (npc) lineas = (mapa.textos ?? []).filter((t) => t.x === Number(npc.x) && t.y === Number(npc.y));
        if (!lineas.length) lineas = (mapa.textos ?? []).filter((t) => t.x === x && t.y === y);
        if (!lineas.length) continue;
        for (const pagina of evento.getIvar("@pages") ?? []) {
          const mensajes = (pagina.getIvar("@list") ?? []).filter((c) => c.getIvar("@code") === 401);
          if (!mensajes.length) continue;
          lineas.slice(0, mensajes.length).forEach((linea, i) => {
            mensajes[i].setIvar("@parameters", [S(String(linea.texto).slice(0, 240))]);
            textos += 1;
          });
          break;
        }
      }
      write(mapFile(mapId), objeto);
      aperturasTotal += aperturas;
      mapas += 1;
    }
    console.log(`  · ${clave}: ${Object.keys(campana.maps).length} mapas con gráficos nativos`);
  }
  console.log(`✅ Instalado: ${mapas} mapas nativos · ${textos} diálogos originales · ${aperturasTotal} celdas de evento habilitadas · ${ids.size} tilesets`);
}

/* ───────────────────────────────── verificación ─────────────────────────── */

function verificar() {
  const plan = planNativo();
  const crudoTilesets = read("Tilesets.rxdata");
  const idPorNombre = new Map();
  for (let i = 1; i < crudoTilesets.length; i += 1) {
    const nombre = String(crudoTilesets[i]?.getIvar?.("@tileset_name")?.text ?? "");
    if (nombre) idPorNombre.set(nombre, i);
  }
  let mapas = 0, fallos = 0, solidas = 0, libres = 0, celdasTotales = 0, pngs = 0, abiertas = 0, eventos = 0;
  const errores = [], avisos = [];
  const ok = (cond, mensaje) => { if (!cond) { fallos += 1; if (errores.length < 12) errores.push(mensaje); } };
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    for (const ts of campana.tilesets) {
      const ruta = path.join(GRAPHICS, ts.png);
      ok(fs.existsSync(ruta), `falta el tileset ${ts.png}`);
      if (!fs.existsSync(ruta)) continue;
      const bytes = fs.readFileSync(ruta);
      ok(bytes.readUInt32BE(16) === ts.ancho && bytes.readUInt32BE(20) === ts.alto,
        `${ts.png}: dimensiones ≠ ${ts.ancho}×${ts.alto}`);
      ok(sha1(bytes) === ts.sha1, `${ts.png}: huella distinta a la del plan`);
      ok((idPorNombre.get(ts.nombre) ?? 0) > 0, `${ts.nombre}: sin entrada en Tilesets.rxdata`);
      if (ts.bloqueados === 0) avisos.push(`${clave}/${ts.nombre}: sin metatiles sólidos (tileset de tránsito)`);
      pngs += 1;
    }
    const tilesetDe = new Map(campana.tilesets.map((t) => [t.nombre, t]));
    for (const [idTexto, mapa] of Object.entries(campana.maps)) {
      const mapId = Number(idTexto);
      const archivo = path.join(DATA, mapFile(mapId));
      ok(fs.existsSync(archivo), `falta Map${mapId}`);
      if (!fs.existsSync(archivo)) continue;
      const objeto = read(mapFile(mapId));
      const ts = tilesetDe.get(mapa.tileset);
      ok(Number(objeto.getIvar("@tileset_id")) === idPorNombre.get(mapa.tileset), `Map${mapId}: tileset ≠ ${mapa.tileset}`);
      const parsed = parseMap(objeto);
      const celdas = deB64(mapa.celdas, mapa.width * mapa.height);
      const solidoDe = new Map(Object.entries(ts.porMetatile).map(([metatile, fila]) => [fila[0], { metatile: Number(metatile), solido: false }]));
      for (const [metatile, fila] of Object.entries(ts.porMetatile)) {
        if (fila[1]) solidoDe.set(fila[1], { metatile: Number(metatile), solido: true });
      }
      // Celdas con evento: únicas donde se admite el gemelo transitable del mismo metatile.
      const celdasConEvento = new Set();
      for (const [, evento] of objeto.getIvar("@events").pairs) {
        const ex = Number(evento.getIvar("@x")), ey = Number(evento.getIvar("@y"));
        if (ex >= 0 && ey >= 0 && ex < mapa.width && ey < mapa.height) celdasConEvento.add(`${ex},${ey}`);
      }
      let distintos = 0, aperturasMalas = 0, fallado = "";
      for (let y = 0; y < mapa.height; y += 1) {
        for (let x = 0; x < mapa.width; x += 1) {
          const esperado = celdas[y * mapa.width + x];
          const tiene = tableGet(parsed.table, x, y, 0);
          const info = solidoDe.get(esperado) ?? { metatile: 0, solido: true };
          if (tiene !== esperado) {
            // Solo se admite el gemelo transitable del MISMO metatile (mismo dibujo)
            // y solo bajo un evento: es la única adaptación de la instalación.
            const libre = ts.porMetatile[String(info.metatile)]?.[0];
            if (info.solido && tiene === libre && celdasConEvento.has(`${x},${y}`)) abiertas += 1;
            else { distintos += 1; aperturasMalas += 1; }
          }
          if ((ts.pasajes[tiene] ?? 0) !== 0) solidas += 1; else libres += 1;
          celdasTotales += 1;
        }
      }
      ok(distintos === 0, `Map${mapId}: ${distintos} celdas no coinciden con el ROM`);
      // Accesos: todo evento sobre celda transitable y alcanzable desde el primero.
      const eventosMapa = [];
      for (const [, evento] of objeto.getIvar("@events").pairs) {
        const x = Number(evento.getIvar("@x")), y = Number(evento.getIvar("@y"));
        if (x < 0 || y < 0 || x >= mapa.width || y >= mapa.height) continue;
        eventosMapa.push({ x, y, nombre: textoDeNombre(evento.getIvar("@name")) });
      }
      const bloqueada = (x, y) => (ts.pasajes[tableGet(parsed.table, x, y, 0)] ?? 0) !== 0;
      let sobreSolida = 0;
      for (const e of eventosMapa) if (bloqueada(e.x, e.y)) { sobreSolida += 1; if (sobreSolida === 1) fallado = `Map${mapId}: "${e.nombre.slice(0, 40)}" @${e.x},${e.y}`; }
      ok(sobreSolida === 0, `${fallado} y ${sobreSolida - 1} eventos más sobre celdas sólidas`);
      // Los mapas de tránsito del ROM tienen zonas incomunicadas por diseño: cada
      // warp se alcanza desde otro mapa, así que no se exige conectividad global.
      eventos += eventosMapa.length;
      mapas += 1;
    }
  }
  const porcentaje = (solidas / Math.max(1, celdasTotales)) * 100;
  console.log(`verificación nativa: ${mapas} mapas · ${pngs} tilesets · ${eventos} eventos revisados · ${fallos} fallos`);
  console.log(`  · celdas ${celdasTotales} · sólidas ${solidas} (${porcentaje.toFixed(1)} %) · libres ${libres} · accesos abiertos ${abiertas}`);
  if (avisos.length) console.log(`  · avisos: ${avisos.length} tilesets de tránsito sin sólidos`);
  if (errores.length) { for (const e of errores) console.error(`  FALLA: ${e}`); process.exit(1); }
  if (porcentaje < 5 || porcentaje > 85) {
    console.error(`  FALLA: proporción de celdas sólidas fuera de rango razonable (${porcentaje.toFixed(1)} %)`);
    process.exit(1);
  }
  console.log("  · cada mapa usa su tileset del ROM, sus celdas, su colisión original y accesos jugables");
}

// El modo CLI solo actúa si el archivo se ejecuta directamente: así otros
// módulos (rom_nativo_sprites.mjs) pueden importar `escribirPng` sin disparar
// la extracción o la instalación.
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  if (EXTRACT) extraer();
  else if (INSTALL) instalar();
  else if (VERIFY) verificar();
  else console.log("uso: --extract | --install | --verify  (ver cabecera del archivo)");
}/**
 * rom_nativo_sprites.mjs — Sprites de personajes NATIVOS de las ROMs (Gen 3).
 *
 * Los mapas se instalaron célula a célula desde la ROM (`rom_nativo_mapas.mjs`);
 * este módulo hace lo propio con los GRÁFICOS DE LOS NPCs: extrae del ROM la
 * imagen y la paleta de cada personaje y las deja como PNG de personaje RMXP.
 *
 * Cómo se localiza todo dentro del ROM (verificado contra el código de
 * pokeemerald — `struct ObjectEventGraphicsInfo`, `overworld_frame` y
 * `sObjectEventSpritePalettes`):
 *
 *   1. `gObjectEventGraphicsInfoPointers[]`: array de punteros a structs de
 *      0x24 bytes; se reconoce porque cada struct lleva su `paletteTag` en 0x02
 *      con el rango 0x1100-0x11FF (OBJ_EVENT_PAL_TAG_*).
 *   2. `sObjectEventSpritePalettes[]`: array de structs de 8 bytes
 *      { const u16 *data; u16 tag; } con los mismos tags; la paleta son 16
 *      colores BGR555.
 *   3. La imagen del personaje: el struct (ver `struct ObjectEventGraphicsInfo`)
 *      trae en 0x08/0x0A ancho y alto en píxeles y en 0x1C un puntero a la tabla
 *      de frames. Los 9 frames (abajo, arriba, lado) están CONSECUTIVOS, 4bpp y
 *      en disposición de tiles GBA: una tira de (ancho/8) tiles de ancho por
 *      9 * (alto/8) de alto.
 *
 * El juego usa tiles RMXP de 32×32 (cada metatile de 16×16 se reescala ×2), así
 * que el sprite también se reescala ×2 (16×32 → 32×64 y 32×32 → 64×64).
 *
 * Uso:  node tools/rom_nativo_sprites.mjs --extract | --install | --verify [--dry-run] [--dir ROM_DIR]
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { marshalLoad, marshalDump, RString } from "../web/js/marshal.js";
import { escribirPng } from "./rom_nativo_mapas.mjs";

const AQUI = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(AQUI, "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const DATA = path.join(GAME, "Data");
const PERSONAJES = path.join(GAME, "Graphics", "Characters");
const PLAN_PATH = path.join(ROOT, "content", "rom_nativo.json");
const PLAN_SPRITES = path.join(ROOT, "content", "rom_nativo_sprites.json");
const CAMPAIGNS_PATH = path.join(ROOT, "content", "rom_campaigns_complete.json");
const BLUEPRINT_PATH = path.join(ROOT, "content", "rom_campaigns_complete.json");
const BACKUP = path.join(GAME, "PokeModBackups", "rom_nativo_sprites");

const args = process.argv.slice(2);
const DRY = args.includes("--dry-run");
const EXTRACT = args.includes("--extract");
const INSTALL = args.includes("--install");
const VERIFY = args.includes("--verify");
const dirArg = args.indexOf("--dir");
const ROM_DIR = path.resolve(ROOT, dirArg >= 0 ? args[dirArg + 1] : path.join(ROOT, "roms pokemon"));

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);

/* ───────────────────────────── lectura del ROM ─────────────────────────── */

const sha1 = (b) => crypto.createHash("sha1").update(b).digest("hex");
const pad3 = (n) => String(n).padStart(3, "0");

const u8 = (d, o) => d[o];
const u16 = (d, o) => d[o] | (d[o + 1] << 8);
const u32 = (d, o) => ((d[o] | (d[o + 1] << 8) | (d[o + 2] << 16) | (d[o + 3] << 24)) >>> 0);
const esPtr = (d, p) => p >= 0x08000000 && p < 0x08000000 + d.length;

/**
 * ¿El struct apunta a un ObjectEventGraphicsInfo válido? (ver cabecera)
 * Se exige, además del tamaño y el tag, que la tabla de frames empiece con una
 * entrada coherente (puntero válido y `size` = ancho×alto/2 bytes de 4bpp): ese
 * detalle es lo que distingue la tabla real de un array de punteros parecido.
 */
function esFichaGrafico(data, t) {
  if (t + 0x24 > data.length) return false;
  const tag = u16(data, t + 2);
  const ancho = u16(data, t + 8);
  const alto = u16(data, t + 10);
  // Algunos hacks reasignan los tags fuera del rango clásico 0x1100-0x11FF.
  if (tag < 0x1100 || tag > 0x1fff) return false;
  if (!(ancho >= 8 && ancho <= 64 && (ancho & 7) === 0)) return false;
  if (!(alto >= 8 && alto <= 64 && (alto & 7) === 0)) return false;
  // El struct real trae cinco punteros buenos: OAM, subconjuntos, animaciones,
  // imágenes y (opcionalmente) animaciones afines.
  if (!esPtr(data, u32(data, t + 0x10))) return false;
  if (!esPtr(data, u32(data, t + 0x14))) return false;
  if (!esPtr(data, u32(data, t + 0x18))) return false;
  const imagenes = u32(data, t + 0x1c);
  if (!esPtr(data, imagenes)) return false;
  const afines = u32(data, t + 0x20);
  if (afines !== 0 && !esPtr(data, afines)) return false;
  // Y su tabla de frames son entradas coherentes (puntero válido + tamaño exacto
  // del frame en 4bpp). Algún hack tiene una entrada con tamaño raro, así que se
  // exige el primer frame y la mayoría de los nueve.
  const tabla = imagenes - 0x08000000;
  if (tabla + 9 * 8 > data.length) return false;
  if (!esPtr(data, u32(data, tabla))) return false;
  if (u16(data, tabla + 4) !== (ancho * alto) / 2) return false;
  let correctos = 0;
  for (let f = 0; f < 9; f += 1) {
    if (esPtr(data, u32(data, tabla + f * 8)) && u16(data, tabla + f * 8 + 4) === (ancho * alto) / 2) correctos += 1;
  }
  return correctos >= 6;
}

/**
 * Busca el array `gObjectEventGraphicsInfoPointers[]` usando los graphicsId que
 * realmente usan los NPCs de la campaña: gana el array donde más de esos ids
 * resuelven a una ficha válida. Así no hay que adivinar el rango de tags ni
 * asumir que la tabla no tiene huecos (Unbound deja punteros nulos).
 */
export function tablaGraficos(data, ids = []) {
  const MAX_HUECO = 12;
  // Sin descartar solapes: un array desplazado (sub-array del real) también
  // parece válido, así que todos compiten y decide la cobertura de ids usados.
  // Los huecos largos se toleran: algunos hacks dejan tramos sin ficha.
  const HUECO_CANDIDATO = 40;
  const candidatos = [];
  for (let o = 0; o + 4 * 30 < data.length; o += 4) {
    let validos = 0, hueco = 0, i = 0;
    while (i < 60) {
      const p = u32(data, o + i * 4);
      if (esPtr(data, p) && esFichaGrafico(data, p - 0x08000000)) { validos += 1; hueco = 0; }
      else if (++hueco > HUECO_CANDIDATO) break;
      i += 1;
    }
    if (validos >= 25) candidatos.push(o);
  }
  const puntuar = (o) => {
    let cobertura = 0;
    for (const g of ids) {
      const p = u32(data, o + g * 4);
      if (esPtr(data, p) && esFichaGrafico(data, p - 0x08000000)) cobertura += 1;
    }
    let fichas = 0, hueco = 0, i = 0, ultimo = 0;
    while (i < 400) {
      const p = u32(data, o + i * 4);
      if (esPtr(data, p) && esFichaGrafico(data, p - 0x08000000)) { fichas += 1; ultimo = o + i * 4; hueco = 0; }
      else if (++hueco > MAX_HUECO) break;
      i += 1;
    }
    // Un sub-array conserva los punteros a fichas del array real pero empieza
    // desplazado: se penaliza el desplazamiento, no el número de fichas.
    return { cobertura, fichas, hasta: ultimo };
  };
  let mejor = null;
  for (const o of candidatos) {
    const m = puntuar(o);
    // Cobertura primero (la tabla real resuelve casi todos los ids usados);
    // a igualdad, la tabla MÁS LARGA gana porque un array posterior es un
    // sub-array desplazado del real.
    if (!mejor || m.cobertura > mejor.cobertura || (m.cobertura === mejor.cobertura && m.fichas > mejor.fichas)) mejor = { o, ...m };
  }
  return mejor;
}

/** ¿Es una paleta de personaje? 16 colores BGR555 con varios colores reales. */
function esPaleta(data, ptr, tag) {
  if (!(tag >= 0x1100 && tag <= 0x1fff)) return false;
  if (!esPtr(data, ptr)) return false;
  const o = ptr - 0x08000000;
  if (o + 32 > data.length) return false;
  let colores = 0;
  for (let c = 0; c < 16; c += 1) if (u16(data, o + c * 2) !== 0) colores += 1;
  return colores >= 4;
}

/**
 * Busca el array `sObjectEventSpritePalettes[]` ({ const u16 *data; u16 tag; })
 * y devuelve el que cubre más tags pedidos (los de las fichas en uso).
 */
export function tablaPaletas(data, tags = []) {
  const MAX_HUECO = 12;
  const candidatos = [];
  const vistos = new Set();
  for (let o = 0; o + 8 * 10 < data.length; o += 4) {
    if (vistos.has(o)) continue;
    let validos = 0, hueco = 0, i = 0;
    while (i < 40) {
      const p = u32(data, o + i * 8);
      const tag = u16(data, o + i * 8 + 4);
      if (esPaleta(data, p, tag)) { validos += 1; hueco = 0; }
      else if (++hueco > MAX_HUECO) break;
      i += 1;
    }
    if (validos >= 10) {
      candidatos.push(o);
      for (let k = 1; k < validos; k += 1) vistos.add(o + k * 8);
    }
  }
  const puntuar = (o) => {
    const conjunto = new Set();
    let hueco = 0, i = 0;
    while (i < 300) {
      const p = u32(data, o + i * 8);
      const tag = u16(data, o + i * 8 + 4);
      if (esPaleta(data, p, tag)) { conjunto.add(tag); hueco = 0; }
      else if (++hueco > MAX_HUECO) break;
      i += 1;
    }
    let cobertura = 0;
    for (const t of tags) if (conjunto.has(t)) cobertura += 1;
    return { cobertura, paletas: conjunto.size, conjunto };
  };
  let mejor = null;
  for (const o of candidatos) {
    const m = puntuar(o);
    if (!mejor || m.cobertura > mejor.cobertura || (m.cobertura === mejor.cobertura && m.paletas > mejor.paletas)) mejor = { o, ...m };
  }
  return mejor;
}

/** Mapa tag → puntero de la paleta de 16 colores (usa el conjunto detectado). */
export function paletasDe(data, tabla) {
  const mapa = new Map();
  if (tabla.conjunto) {
    let hueco = 0, i = 0;
    while (i < 300 && hueco <= 12) {
      const p = u32(data, tabla.o + i * 8);
      const tag = u16(data, tabla.o + i * 8 + 4);
      if (esPaleta(data, p, tag)) { if (!mapa.has(tag)) mapa.set(tag, p); hueco = 0; }
      else hueco += 1;
      i += 1;
    }
    return mapa;
  }
  for (let i = 0; i < tabla.n; i += 1) mapa.set(u16(data, tabla.o + i * 8 + 4), u32(data, tabla.o + i * 8));
  return mapa;
}

/** Paleta RGBA (16 colores) del tag indicado. */
export function paletaDe(data, paletas, tag) {
  const ptr = paletas.get(tag);
  if (!ptr) return null;
  const o = ptr - 0x08000000;
  const paleta = [];
  for (let c = 0; c < 16; c += 1) {
    const v = u16(data, o + c * 2);
    paleta.push([Math.round(((v & 31) * 255) / 31), Math.round((((v >> 5) & 31) * 255) / 31), Math.round((((v >> 10) & 31) * 255) / 31), c === 0 ? 0 : 255]);
  }
  return paleta;
}

/**
 * Ficha completa de un graphicsId: tamaño, paleta y los 9 frames en RGBA.
 * Los frames están en una tira consecutiva con tiles de 8×8 (barrido por filas).
 */
export function spriteDe(data, gfxTab, paletas, graphicsId) {
  const ptr = u32(data, gfxTab.o + graphicsId * 4);
  if (!esPtr(data, ptr)) return null;
  const st = ptr - 0x08000000;
  const ancho = u16(data, st + 8);
  const alto = u16(data, st + 10);
  const tag = u16(data, st + 2);
  const imagenes = u32(data, st + 0x1c);
  if (!esPtr(data, imagenes)) return null;
  const paleta = paletaDe(data, paletas, tag);
  if (!paleta) return null;
  // La tabla de frames son 9 structs SpriteFrameImage { const void* data; u16 size; }
  // seguidos, y los datos de esos 9 frames están a su vez consecutivos: se leen
  // los punteros de la tabla y, si alguno no cuadra, se avanza con el tamaño del
  // frame ((ancho*alto)/2 bytes, 4bpp).
  const tablaFrames = imagenes - 0x08000000;
  const primerFrame = u32(data, tablaFrames);
  if (!esPtr(data, primerFrame)) return null;
  const base = primerFrame - 0x08000000;
  const tamFrame = (ancho * alto) / 2;
  const tilesX = ancho / 8;
  const frames = [];
  for (let f = 0; f < 9; f += 1) {
    const apuntado = u32(data, tablaFrames + f * 8);
    const desde = esPtr(data, apuntado) && u16(data, tablaFrames + f * 8 + 4) === tamFrame ? apuntado - 0x08000000 : base + f * tamFrame;
    const rgba = new Uint8Array(ancho * alto * 4);
    for (let ty = 0; ty < alto / 8; ty += 1) {
      for (let tx = 0; tx < tilesX; tx += 1) {
        const src = desde + (ty * tilesX + tx) * 32;
        if (src + 32 > data.length) continue;
        for (let y = 0; y < 8; y += 1) {
          for (let x = 0; x < 8; x += 1) {
            const byte = data[src + y * 4 + (x >> 1)];
            const color = x & 1 ? byte >> 4 : byte & 0x0f;
            const px = paleta[color];
            const dx = tx * 8 + x;
            const dy = ty * 8 + y;
            const d = (dy * ancho + dx) * 4;
            rgba[d] = px[0]; rgba[d + 1] = px[1]; rgba[d + 2] = px[2]; rgba[d + 3] = px[3];
          }
        }
      }
    }
    frames.push(rgba);
  }
  return { ancho, alto, tag, frames };
}

/* ─────────────────────── composición del PNG RMXP ─────────────────────── */
/**
 * Hoja de personaje RMXP con prefijo "$" (un solo personaje, 4 columnas × 4
 * filas): fila 0 = abajo, 1 = izquierda, 2 = derecha (espejo), 3 = arriba.
 * Las columnas son el ciclo de animación [quieto, paso1, quieto, paso2], que
 * encaja con los frames del ROM (0 = quieto, 1-2 = pasos).
 */
export function hojaRmxp(sprite, escala) {
  const fw = sprite.ancho * escala;
  const fh = sprite.alto * escala;
  const ancho = fw * 4;
  const alto = fh * 4;
  const rgba = new Uint8Array(ancho * alto * 4);
  const pintar = (frame, col, fila, espejo) => {
    const src = sprite.frames[frame];
    if (!src) return;
    for (let y = 0; y < fh; y += 1) {
      for (let x = 0; x < fw; x += 1) {
        const sx = espejo ? fw - 1 - x : x;
        const s = (Math.floor(y / escala) * sprite.ancho + Math.floor(sx / escala)) * 4;
        const d = ((fila * fh + y) * ancho + col * fw + x) * 4;
        rgba[d] = src[s]; rgba[d + 1] = src[s + 1]; rgba[d + 2] = src[s + 2]; rgba[d + 3] = src[s + 3];
      }
    }
  };
  // Orden de los 9 frames en Gen 3 (tabla `overworld_frame`): 0/1/2 son las
  // poses quietas de abajo/arriba/lado y 3..8 los pasos (3-4 abajo, 5-6 arriba,
  // 7-8 lado). La hoja RMXP repite la pose quieta entre paso y paso.
  const abajo = [0, 3, 0, 4];
  const arriba = [1, 5, 1, 6];
  const lado = [2, 7, 2, 8];
  for (let c = 0; c < 4; c += 1) {
    pintar(abajo[c], c, 0, false);
    pintar(lado[c], c, 1, false);
    pintar(lado[c], c, 2, true);   // la hoja solo trae el lado izquierdo: se espeja
    pintar(arriba[c], c, 3, false);
  }
  return { rgba, ancho, alto };
}

/* ─────────────────────────────── extracción ────────────────────────────── */

function planNativo() {
  if (!fs.existsSync(PLAN_PATH)) throw new Error("Falta content/rom_nativo.json; corre --extract de rom_nativo_mapas.mjs");
  return JSON.parse(fs.readFileSync(PLAN_PATH, "utf8"));
}

/** graphicsId usados por los NPCs de la campaña, en orden. */
function spritesUsados(campana) {
  const usados = new Map();  // graphicsId → nº de usos
  for (const mapa of Object.values(campana.maps)) {
    for (const npc of mapa.npcs ?? []) {
      if (!Number.isInteger(npc.sprite) || npc.sprite < 0) continue;
      usados.set(npc.sprite, (usados.get(npc.sprite) ?? 0) + 1);
    }
  }
  return [...usados].sort((a, b) => b[1] - a[1] || a[0] - b[0]);
}

/**
 * Prepara la lectura de una campaña: detecta la tabla de gráficos con los ids
 * que usan sus NPCs y, con los tags resultantes, la tabla de paletas.
 */
export function preparar(data, campana) {
  const usados = spritesUsados(campana);
  const ids = usados.map(([id]) => id);
  const gfxTab = tablaGraficos(data, ids);
  if (!gfxTab) return null;
  const tagsUsados = [];
  for (const graphicsId of ids) {
    const p = u32(data, gfxTab.o + graphicsId * 4);
    if (esPtr(data, p)) tagsUsados.push(u16(data, p - 0x08000000 + 2));
  }
  const palTab = tablaPaletas(data, tagsUsados);
  const paletas = paletasDe(data, palTab);
  return { usados, gfxTab, palTab, paletas, tagsUsados };
}

function extraer() {
  const plan = planNativo();
  const salida = { generatedBy: "tools/rom_nativo_sprites.mjs", fuente: "ROMs invitadas (GBA)", campaigns: {} };
  let totalSprites = 0, totalBytes = 0;
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    const romPath = path.join(ROM_DIR, campana.rom);
    if (!fs.existsSync(romPath)) { console.log(`  · ${clave}: ROM ausente (${campana.rom}); se omite`); continue; }
    const data = fs.readFileSync(romPath);
    const { usados, gfxTab, palTab, paletas, tagsUsados } = preparar(data, campana);
    const escala = 2;
    const sprites = {};
    let bytes = 0;
    const faltantes = [];
    for (const [graphicsId, usos] of usados) {
      const sprite = spriteDe(data, gfxTab, paletas, graphicsId);
      if (!sprite) { faltantes.push(graphicsId); continue; }
      const hoja = hojaRmxp(sprite, escala);
      const nombre = `$ROMN_${clave}_g${graphicsId}`;
      const png = escribirPng(hoja.rgba, hoja.ancho, hoja.alto);
      if (!DRY) {
        fs.mkdirSync(PERSONAJES, { recursive: true });
        fs.writeFileSync(path.join(PERSONAJES, `${nombre}.png`), png);
      }
      sprites[graphicsId] = {
        nombre, png: `${nombre}.png`, sha1: sha1(png), ancho: hoja.ancho, alto: hoja.alto,
        frame: `${sprite.ancho}x${sprite.alto}`, tag: sprite.tag, usos,
      };
      bytes += png.length;
      totalSprites += 1;
    }
    salida.campaigns[clave] = {
      rom: campana.rom,
      gfxTab: gfxTab.o, gfxFichas: gfxTab.fichas, gfxCobertura: gfxTab.cobertura,
      palTab: palTab.o, palPaletas: palTab.paletas, palCobertura: palTab.cobertura,
      sprites, faltantes,
    };
    totalBytes += bytes;
    console.log(`  · ${clave}: ${Object.keys(sprites).length} sprites nativos (${(bytes / 1024).toFixed(0)} KB) · tabla de gráficos 0x${gfxTab.o.toString(16)} (${gfxTab.cobertura}/${usados.length} ids) · paletas 0x${palTab.o.toString(16)} (${palTab.cobertura}/${tagsUsados.length} tags)${faltantes.length ? ` · sin gráfico en la ROM: ${faltantes.slice(0, 8).join(",")}${faltantes.length > 8 ? "…" : ""} (${faltantes.length})` : ""}`);
  }
  salida.resumen = { sprites: totalSprites, bytes: totalBytes };
  if (!DRY) fs.writeFileSync(PLAN_SPRITES, `${JSON.stringify(salida)}\n`);
  console.log(`✅ Sprites nativos: ${totalSprites} personajes · ${(totalBytes / 1024).toFixed(0)} KB → content/rom_nativo_sprites.json`);
}

/* ─────────────────────────────── instalación ───────────────────────────── */

const txt = (v) => (v && v.bytes ? Buffer.from(v.bytes).toString("utf8") : String(v ?? ""));

/**
 * Los eventos de campaña se instalaron con los NPCs del plan estructural, en el
 * mismo orden que los de la ROM: el nombre termina en `_<capítulo>_<k>` y ese `k`
 * es la posición (1-based) del NPC en el plan. El plan guardó como `localId` el
 * graphicsId del ROM (el parser antiguo leía ahí ese campo), así que el mapeo
 * evento → personaje es directo y en orden, aunque la instalación haya movido
 * las celdas para evitar solapes.
 */
function planEstructural() {
  const blueprint = JSON.parse(fs.readFileSync(BLUEPRINT_PATH, "utf8"));
  const meta = new Map();
  for (const campana of Object.values(blueprint.campaigns)) {
    for (const m of campana.maps) {
      meta.set(m.mapId, (m.npcs ?? []).map((n) => ({
        graphicsId: Number(n.localId),
        x: Number(n.x),
        y: Number(n.y),
      })));
    }
  }
  return meta;
}

/** graphicsId que corresponde a un evento de campaña (o null si no aplica). */
function graphicsDeEvento(nombre, x, y, estructural, porCelda) {
  const sufijo = /_(\d+)$/.exec(nombre);
  if (sufijo) {
    const npc = (estructural ?? [])[Number(sufijo[1]) - 1];
    if (npc && Number.isInteger(npc.graphicsId)) return npc.graphicsId;
  }
  const cercano = porCelda.get(`${x},${y}`);
  return cercano ? cercano.sprite : null;
}

/** ¿El evento es un personaje (y no un warp, un cartel o el retorno)? */
const esPersonaje = (nombre) => nombre.includes("PokeMod Campaña ROM: NPC")
  || nombre.includes("PokeMod Campaña ROM: Entrenador")
  || nombre.includes("PokeMod Campaña ROM: Líder");

function instalar() {
  if (!fs.existsSync(PLAN_SPRITES)) throw new Error("Falta content/rom_nativo_sprites.json; corre --extract");
  const plan = planNativo();
  const planSpr = JSON.parse(fs.readFileSync(PLAN_SPRITES, "utf8"));
  const estructural = planEstructural();
  fs.mkdirSync(BACKUP, { recursive: true });
  let mapas = 0, asignados = 0, sinSprite = 0;
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    const fichas = planSpr.campaigns[clave]?.sprites ?? {};
    for (const [idTexto, mapa] of Object.entries(campana.maps)) {
      const mapId = Number(idTexto);
      const archivo = path.join(DATA, `Map${pad3(mapId)}.rxdata`);
      if (!fs.existsSync(archivo)) continue;
      const respaldo = path.join(BACKUP, `Map${pad3(mapId)}.rxdata`);
      if (!fs.existsSync(respaldo)) fs.copyFileSync(archivo, respaldo);
      const mapaObj = leerMapa(`Map${pad3(mapId)}.rxdata`);
      // índice de NPCs del ROM por celda
      const porCelda = new Map();
      for (const npc of mapa.npcs ?? []) porCelda.set(`${npc.x},${npc.y}`, npc);
      for (const [, evento] of mapaObj.getIvar("@events").pairs) {
        const nombre = txt(evento.getIvar("@name"));
        if (!esPersonaje(nombre)) continue;
        const x = Number(evento.getIvar("@x"));
        const y = Number(evento.getIvar("@y"));
        const graphicsId = graphicsDeEvento(nombre, x, y, estructural.get(mapId), porCelda);
        if (!Number.isInteger(graphicsId)) continue;
        const ficha = fichas[graphicsId];
        if (!ficha) { sinSprite += 1; continue; }
        for (const pagina of evento.getIvar("@pages") ?? []) {
          const g = pagina.getIvar("@graphic");
          if (!g) continue;
          g.setIvar("@character_name", string(ficha.nombre));
          g.setIvar("@character_index", 0);
          g.setIvar("@tile_id", 0);
          break;
        }
        asignados += 1;
      }
      if (!DRY) guardarMapa(`Map${pad3(mapId)}.rxdata`, mapaObj);
      mapas += 1;
    }
    console.log(`  · ${clave}: sprites nativos asignados en ${Object.keys(campana.maps).length} mapas`);
  }
  console.log(`✅ Sprites instalados: ${asignados} eventos con personaje nativo${sinSprite ? ` · ${sinSprite} sin ficha de sprite` : ""} en ${mapas} mapas`);
}

/* ─────────────────────────────── verificación ──────────────────────────── */

function verificar() {
  const plan = planNativo();
  const planSpr = JSON.parse(fs.readFileSync(PLAN_SPRITES, "utf8"));
  const estructural = planEstructural();
  let fallos = 0, revisados = 0, conNativo = 0;
  const errores = [];
  const ok = (cond, mensaje) => { if (!cond) { fallos += 1; if (errores.length < 12) errores.push(mensaje); } };
  const cacheMapas = new Map();
  for (const [clave, campana] of Object.entries(plan.campaigns)) {
    const fichas = planSpr.campaigns[clave]?.sprites ?? {};
    for (const [idTexto, mapa] of Object.entries(campana.maps)) {
      const mapId = Number(idTexto);
      const archivo = path.join(DATA, `Map${pad3(mapId)}.rxdata`);
      ok(fs.existsSync(archivo), `falta Map${mapId}`);
      if (!fs.existsSync(archivo)) continue;
      if (!cacheMapas.has(mapId)) cacheMapas.set(mapId, leerMapa(`Map${pad3(mapId)}.rxdata`));
      const objeto = cacheMapas.get(mapId);
      const porCelda = new Map();
      for (const npc of mapa.npcs ?? []) porCelda.set(`${npc.x},${npc.y}`, npc);
      for (const [, evento] of objeto.getIvar("@events").pairs) {
        const nombre = txt(evento.getIvar("@name"));
        if (!esPersonaje(nombre)) continue;
        const x = Number(evento.getIvar("@x"));
        const y = Number(evento.getIvar("@y"));
        const graphicsId = graphicsDeEvento(nombre, x, y, estructural.get(mapId), porCelda);
        if (!Number.isInteger(graphicsId)) continue;
        const ficha = fichas[graphicsId];
        if (!ficha) continue;
        revisados += 1;
        const pagina = (evento.getIvar("@pages") ?? [])[0];
        const g = pagina?.getIvar("@graphic");
        const usado = txt(g?.getIvar("@character_name"));
        if (usado !== ficha.nombre) { ok(false, `Map${mapId}: "${nombre.slice(0, 30)}" usa "${usado}" en vez de "${ficha.nombre}"`); continue; }
        const ruta = path.join(PERSONAJES, ficha.png);
        ok(fs.existsSync(ruta), `falta ${ficha.png}`);
        if (!fs.existsSync(ruta)) continue;
        const bytes = fs.readFileSync(ruta);
        ok(bytes.readUInt32BE(16) === ficha.ancho && bytes.readUInt32BE(20) === ficha.alto, `${ficha.png}: dimensiones ≠ ${ficha.ancho}×${ficha.alto}`);
        ok(sha1(bytes) === ficha.sha1, `${ficha.png}: huella distinta a la del plan`);
        conNativo += 1;
      }
    }
  }
  const totalSprites = Object.values(planSpr.campaigns).reduce((s, c) => s + Object.keys(c.sprites).length, 0);
  console.log(`verificación de sprites: ${totalSprites} personajes nativos · ${revisados} eventos revisados · ${conNativo} con sprite del ROM · ${fallos} fallos`);
  if (errores.length) { for (const e of errores) console.error(`  FALLA: ${e}`); process.exit(1); }
  console.log("  · cada NPC de campaña muestra el personaje que le asigna la ROM");
}

/* ───────────────────── lectura/escritura de Map*.rxdata ────────────────── */
const string = (v) => RString.fromText(String(v));
const leerMapa = (nombre) => marshalLoad(fs.readFileSync(path.join(DATA, nombre)));
const guardarMapa = (nombre, objeto) => { if (!DRY) fs.writeFileSync(path.join(DATA, nombre), Buffer.from(marshalDump(objeto))); };

/* ─────────────────────────────────── main ─────────────────────────────── */
if (isMain) {
  if (!EXTRACT && !INSTALL && !VERIFY) {
    console.log("uso: --extract | --install | --verify  [--dry-run] [--dir ROM_DIR]");
    process.exit(1);
  }
  if (EXTRACT) extraer();
  else if (INSTALL) instalar();
  else if (VERIFY) verificar();
}#!/usr/bin/env node
/** Instalación reproducible de referencia para Pokémon Studio 2.11.0.
 * El programa externo se conserva fuera del juego y nunca se distribuye aquí.
 */
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const REPOSITORY = "https://github.com/PokemonWorkshop/PokemonStudio.git";
const TAG = "v2.11.0";
const VERSION = "2.11.0";
const DEFAULT_DESTINATION = path.join(ROOT, "tools", ".cache", "PokemonStudio-2.11.0");

function argument(name, fallback = null) {
  const at = process.argv.indexOf(name);
  return at >= 0 ? process.argv[at + 1] : fallback;
}

function execute(command, args, options = {}) {
  const result = spawnSync(command, args, { stdio: "inherit", ...options });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`${command} ${args.join(" ")} terminó con código ${result.status}.`);
}

function assertSafeDestination(destination) {
  const cache = path.resolve(ROOT, "tools", ".cache");
  const resolved = path.resolve(destination);
  const relative = path.relative(cache, resolved);
  if (!relative || relative.startsWith("..") || path.isAbsolute(relative)) throw new Error("El destino debe estar dentro de tools/.cache.");
  return resolved;
}

function status(source) {
  const packageFile = path.join(source, "package.json");
  const packageData = fs.existsSync(packageFile) ? JSON.parse(fs.readFileSync(packageFile, "utf8")) : null;
  const electronBinary = process.platform === "win32"
    ? path.join(source, "node_modules", "electron", "dist", "electron.exe")
    : path.join(source, "node_modules", "electron", "dist", "electron");
  return {
    source,
    repository: REPOSITORY,
    expectedTag: TAG,
    expectedVersion: VERSION,
    sourcePresent: Boolean(packageData),
    detectedVersion: packageData?.version ?? null,
    versionMatches: packageData?.version === VERSION,
    dependenciesPresent: fs.existsSync(path.join(source, "node_modules")),
    electronBinaryPresent: fs.existsSync(electronBinary),
    adapterReady: fs.existsSync(path.join(ROOT, "tools", "pokemon_studio_adapter.mjs")),
    guiReady: packageData?.version === VERSION && fs.existsSync(electronBinary),
    runtimePolicy: "Pokémon Studio/PSDK permanece separado de Fire Ash/Essentials.",
  };
}

function install(destination) {
  if (!fs.existsSync(destination)) {
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    execute("git", ["clone", "--depth", "1", "--branch", TAG, REPOSITORY, destination]);
  }
  const packageData = JSON.parse(fs.readFileSync(path.join(destination, "package.json"), "utf8"));
  if (packageData.version !== VERSION) throw new Error(`Se esperaba Pokémon Studio ${VERSION}, se obtuvo ${packageData.version}.`);
  const tag = spawnSync("git", ["describe", "--tags", "--exact-match"], { cwd: destination, encoding: "utf8" });
  if (tag.status !== 0 || tag.stdout.trim() !== TAG) throw new Error(`La fuente no corresponde a ${TAG}.`);

  if (process.argv.includes("--dependencies")) {
    const adapterOnly = process.argv.includes("--adapter-only");
    execute("npm", ["ci"], {
      cwd: destination,
      env: {
        ...process.env,
        ...(adapterOnly ? { ELECTRON_SKIP_BINARY_DOWNLOAD: "1" } : {}),
        NODE_EXTRA_CA_CERTS: process.env.NODE_EXTRA_CA_CERTS || "/etc/ssl/certs/ca-certificates.crt",
      },
    });
  }
  if (process.argv.includes("--submodules")) execute("git", ["submodule", "update", "--init", "--recursive"], { cwd: destination });
  return status(destination);
}

function main() {
  const command = process.argv[2] ?? "doctor";
  const suppliedSource = argument("--source");
  const destination = command === "install"
    ? assertSafeDestination(argument("--destination", DEFAULT_DESTINATION))
    : suppliedSource ? path.resolve(suppliedSource) : assertSafeDestination(argument("--destination", DEFAULT_DESTINATION));
  if (command === "install") console.log(JSON.stringify(install(destination), null, 2));
  else if (command === "doctor") console.log(JSON.stringify(status(destination), null, 2));
  else if (command === "links") console.log(JSON.stringify({
    pokemonStudio: REPOSITORY,
    pokemonStudioTag: `https://github.com/PokemonWorkshop/PokemonStudio/releases/tag/${TAG}`,
    pokemonRegionBuilder: "https://felker.dev/pokemon-region-builder/",
  }, null, 2));
  else {
    console.log("Uso:");
    console.log("  node tools/setup_pokemon_studio.mjs install [--dependencies] [--adapter-only] [--submodules]");
    console.log("  node tools/setup_pokemon_studio.mjs doctor [--source /ruta/PokemonStudio]");
    console.log("  node tools/setup_pokemon_studio.mjs links");
  }
}

try { main(); } catch (error) { console.error(error.message); process.exitCode = 1; }#!/usr/bin/env node
/**
 * sync_paquete_directo.mjs
 *
 * Mantiene `Scripts_corregido/Paquete_directo/` — la carpeta que se descomprime
 * sobre la raíz del juego para jugar — al día con todo lo que la expansión ha
 * tocado en `pokemon_fire_ash/`.
 *
 * El paquete directo es un *overlay*, no una copia: sólo lleva los archivos
 * cambiados. Por eso la lista de lo que hay que copiar se calcula así:
 *
 *   1. Todo lo que git marca como modificado o nuevo bajo `pokemon_fire_ash/`
 *      (es decir, lo que la expansión ha creado o alterado).
 *   2. Todo lo que el paquete ya llevaba, por si una herramienta lo regeneró
 *      igual que estaba y git ya no lo marca.
 *   3. `Scripts.rxdata` se copia desde `Scripts_corregido/` (la copia con las
 *      correcciones de distribución), nunca desde el juego.
 *
 * Uso:
 *   node tools/sync_paquete_directo.mjs
 *   node tools/sync_paquete_directo.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME = path.join(ROOT, "pokemon_fire_ash");
const PACKAGE = path.join(ROOT, "Scripts_corregido");
const DIRECT = path.join(PACKAGE, "Paquete_directo");
const SCRIPTS = path.join(PACKAGE, "Scripts.rxdata");
const VERIFY_ONLY = process.argv.includes("--verify");

/**
 * Compromiso desde el que arrancó esta rama: todo lo que haya cambiado en
 * `pokemon_fire_ash/` desde ahí es contenido de la expansión y tiene que
 * viajar en el paquete. Se usa el compromiso base y no `git status` a secas
 * porque el trabajo entregado en otros turnos ya está confirmado.
 *
 * Ojo: en un clon superficial (`git clone --depth 1`, que es lo que hace
 * actions/checkout por defecto) ese compromiso no existe y `git diff` falla.
 * La herramienta se caía entera, y con ella `verify:all`. Cuando el compromiso
 * base no está disponible se cae a una red más burda pero suficiente: los
 * mapas del rango de la expansión, los datos globales y lo que el paquete ya
 * llevaba.
 */
const BASE = process.env.POKEMOD_BASE || "576c54c4b2511b851b6cec9131e6cc6feec59e9d";
const DATOS_GLOBALES = [
  "Data/Tilesets.rxdata", "Data/MapInfos.rxdata", "Data/System.rxdata",
  "Data/metadata.dat", "Data/map_metadata.dat", "Data/encounters.dat",
];

const dentroDeGit = () => {
  try { execFileSync("git", ["rev-parse", "--is-inside-work-tree"], { cwd: ROOT, stdio: "ignore" }); return true; }
  catch { return false; }
};
const baseDisponible = () => {
  try { execFileSync("git", ["cat-file", "-e", `${BASE}^{commit}`], { cwd: ROOT, stdio: "ignore" }); return true; }
  catch { return false; }
};

/**
 * Datos globales del juego: sin historial,no se puede saber qué cambió, pero
 * estos archivos son de la expansión con seguridad. Los mapas no entran: el
 * rango 2021+ no viaja entero en este paquete (Dimensional Nightmare y la
 * Expansión Multiversal se reparten en sus propios ZIP), así que incluirlos
 * daría ciento y pico de «faltas» que no lo son.
 */
function contenidosDeExpansion() {
  return new Set(DATOS_GLOBALES);
}

let MODO = "historial";
/** Archivos de `pokemon_fire_ash/` que la expansión ha creado o modificado. */
function cambiadosEnGit() {
  const rutas = new Set();
  if (!dentroDeGit()) { MODO = "sin git"; return rutas; }
  const git = (argumentos) => execFileSync("git", argumentos, {
    cwd: ROOT, encoding: "utf8", maxBuffer: 64 * 1024 * 1024,
  });
  const anadir = (texto) => {
    for (const linea of texto.split("\n")) {
      const ruta = linea.trim().replace(/^"|"$/g, "");
      if (ruta.startsWith("pokemon_fire_ash/")) rutas.add(path.relative(GAME, ruta));
    }
  };
  if (baseDisponible()) {
    anadir(git(["diff", "--name-only", BASE, "--", "pokemon_fire_ash/"]));
  } else {
    MODO = "sin historial";
    for (const ruta of contenidosDeExpansion()) rutas.add(ruta);
  }
  anadir(git(["ls-files", "--others", "--exclude-standard", "--", "pokemon_fire_ash/"]));
  return rutas;
}

/** Archivos que el paquete ya lleva (relativos a `pokemon_fire_ash/`). */
function yaEnPaquete() {
  const rutas = new Set();
  const caminar = (dir) => {
    for (const entrada of fs.readdirSync(dir, { withFileTypes: true })) {
      const absoluto = path.join(dir, entrada.name);
      if (entrada.isDirectory()) caminar(absoluto);
      else rutas.add(path.relative(DIRECT, absoluto));
    }
  };
  if (fs.existsSync(DIRECT)) caminar(DIRECT);
  return rutas;
}

const mismo = (a, b) => {
  if (!fs.existsSync(a) || !fs.existsSync(b)) return false;
  return fs.readFileSync(a).equals(fs.readFileSync(b));
};

function sincronizar() {
  const objetivos = new Set([...cambiadosEnGit(), ...yaEnPaquete()]);
  // Scripts.rxdata nunca viene del juego: la copia buena es la corregida.
  objetivos.delete(path.join("Data", "Scripts.rxdata"));
  const copiados = [];
  const intactos = [];
  for (const relativo of [...objetivos].sort()) {
    const origen = path.join(GAME, relativo);
    const destino = path.join(DIRECT, relativo);
    if (!fs.existsSync(origen)) continue;
    if (mismo(origen, destino)) { intactos.push(relativo); continue; }
    fs.mkdirSync(path.dirname(destino), { recursive: true });
    fs.copyFileSync(origen, destino);
    copiados.push(relativo);
  }
  // Las correcciones de distribución viajan en el Scripts.rxdata del paquete.
  const destinoScripts = path.join(DIRECT, "Data", "Scripts.rxdata");
  let scripts = "ya al día";
  if (!mismo(SCRIPTS, destinoScripts)) {
    fs.mkdirSync(path.dirname(destinoScripts), { recursive: true });
    fs.copyFileSync(SCRIPTS, destinoScripts);
    scripts = "actualizado";
  }
  return { copiados, intactos, scripts };
}

function verificar() {
  const errores = [];
  if (!fs.existsSync(DIRECT)) errores.push("no existe Scripts_corregido/Paquete_directo/");
  if (!fs.existsSync(SCRIPTS)) errores.push("no existe Scripts_corregido/Scripts.rxdata");
  if (errores.length) throw new Error(`Paquete directo incompleto:\n- ${errores.join("\n- ")}`);

  // 1. El Scripts.rxdata del paquete es exactamente el corregido.
  const destinoScripts = path.join(DIRECT, "Data", "Scripts.rxdata");
  if (!mismo(SCRIPTS, destinoScripts)) {
    errores.push("el paquete no usa el Scripts.rxdata corregido");
  }
  // 2. Todo lo cambiado en el juego está en el paquete y es idéntico.
  for (const relativo of [...cambiadosEnGit()].sort()) {
    const origen = path.join(GAME, relativo);
    if (relativo === path.join("Data", "Scripts.rxdata")) continue;
    if (!fs.existsSync(origen)) continue;
    const destino = path.join(DIRECT, relativo);
    if (!fs.existsSync(destino)) { errores.push(`falta en el paquete: ${relativo}`); continue; }
    if (!mismo(origen, destino)) errores.push(`desincronizado: ${relativo}`);
  }
  if (errores.length) throw new Error(`Paquete directo desincronizado (${errores.length}):\n- ${errores.join("\n- ")}`);

  let total = 0;
  const contar = (dir) => {
    for (const entrada of fs.readdirSync(dir, { withFileTypes: true })) {
      const absoluto = path.join(dir, entrada.name);
      if (entrada.isDirectory()) contar(absoluto); else total += 1;
    }
  };
  contar(DIRECT);
  const origen = MODO === "sin historial"
    ? "sólo lo que el paquete ya lleva (el clon no trae el compromiso base)"
    : `cambios desde ${BASE.slice(0, 8)}`;
  console.log(`✔ Paquete directo sincronizado: ${total} archivos, todos idénticos a pokemon_fire_ash/ `
    + `(Scripts.rxdata desde Scripts_corregido/). Origen de la lista: ${origen}.`);
}

if (!VERIFY_ONLY) {
  const { copiados, intactos, scripts } = sincronizar();
  console.log(`  · Scripts.rxdata: ${scripts}`);
  for (const relativo of copiados) console.log(`  · copiado: ${relativo}`);
  if (intactos.length) console.log(`  · ${intactos.length} archivos ya estaban al día`);
}
verificar();#!/usr/bin/env node
/**
 * Sincroniza el paquete directo de La Ruta de Dios después de regenerar los
 * datos jugables.
 *
 * No reemplaza Scripts_corregido/Scripts.rxdata completo: conserva las seis
 * correcciones de distribución (Grandeur Club, colisiones y guardado) y sólo
 * actualiza la sección PokeMod_RutaDeDios desde el script ejecutable.
 *
 * Uso:
 *   node tools/sync_ruta_de_dios_package.mjs
 *   node tools/sync_ruta_de_dios_package.mjs --verify
 */
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { assertSameFile } from "./lib/package_integrity.mjs";
import { marshalDump, marshalLoad } from "../web/js/marshal.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const GAME_DATA = path.join(ROOT, "pokemon_fire_ash", "Data");
const PACKAGE = path.join(ROOT, "Scripts_corregido");
const DIRECT = path.join(PACKAGE, "Paquete_directo");
const VERIFY_ONLY = process.argv.includes("--verify");

const DATA_FILES = [
  "Map2031.rxdata", "Map2032.rxdata", "Map2033.rxdata", "Map2034.rxdata",
  "Map2035.rxdata", "Map2036.rxdata", "Map2037.rxdata", "Map2038.rxdata",
  "Map2030.rxdata",
  "Map513.rxdata", "Map625.rxdata", "MapInfos.rxdata", "Scripts.rxdata",
  "System.rxdata", "encounters.dat", "map_metadata.dat",
];
const ASSET_FILES = [
  ["Graphics/Characters/ARCEUS.png", "Graphics/Characters/ARCEUS.png"],
  ["Graphics/Characters/ARCEUS_GATE.png", "Graphics/Characters/ARCEUS_GATE.png"],
  ["Graphics/Characters/ARC_Cynthia.png", "Graphics/Characters/ARC_Cynthia.png"],
  ["Graphics/Characters/ARC_Ethan.png", "Graphics/Characters/ARC_Ethan.png"],
  ["Graphics/Characters/ARC_Steven.png", "Graphics/Characters/ARC_Steven.png"],
  ["Graphics/Characters/DIALGA.png", "Graphics/Characters/DIALGA.png"],
  ["Graphics/Characters/Object ball special.png", "Graphics/Characters/Object ball special.png"],
  ["Graphics/Characters/PALKIA.png", "Graphics/Characters/PALKIA.png"],
  ["Graphics/Characters/SECRET_Red.png", "Graphics/Characters/SECRET_Red.png"],
  ["Graphics/Characters/SECRET_Volo.png", "Graphics/Characters/SECRET_Volo.png"],
  ["Graphics/Characters/SQUIRTLE.png", "Graphics/Characters/SQUIRTLE.png"],
  ["Graphics/Trainers/ARC_Cynthia_back.png", "Graphics/Trainers/ARC_Cynthia_back.png"],
  ["Graphics/Trainers/ARC_Steven_back.png", "Graphics/Trainers/ARC_Steven_back.png"],
  ["Graphics/Trainers/ARC_Ethan_back.png", "Graphics/Trainers/ARC_Ethan_back.png"],
  ["Graphics/Trainers/ARC_Ethan.png", "Graphics/Trainers/ARC_Ethan.png"],
  ["Graphics/Trainers/SECRET_Red_back.png", "Graphics/Trainers/SECRET_Red_back.png"],
  ["Graphics/Trainers/SECRET_Volo_back.png", "Graphics/Trainers/SECRET_Volo_back.png"],
  ["Audio/BGM/Legend Sinnoh.ogg", "Audio/BGM/Legend Sinnoh.ogg"],
  ["Audio/BGM/secretvolo.ogg", "Audio/BGM/secretvolo.ogg"],
  // R14: el cosmos de la Cima y la Forma Origen de mil brazos viajan con el paquete.
  ["Graphics/Battlebacks/genesis1_bg.png", "Graphics/Battlebacks/genesis1_bg.png"],
  ["Graphics/Battlebacks/genesis2_bg.png", "Graphics/Battlebacks/genesis2_bg.png"],
  ["Graphics/Battlebacks/genesis3_bg.png", "Graphics/Battlebacks/genesis3_bg.png"],
  ["Graphics/Battlebacks/genesis1_base0.png", "Graphics/Battlebacks/genesis1_base0.png"],
  ["Graphics/Battlebacks/genesis1_base1.png", "Graphics/Battlebacks/genesis1_base1.png"],
  ["Graphics/Pokemon/Front/ARCEUS_18.png", "Graphics/Pokemon/Front/ARCEUS_18.png"],
  ["Graphics/Pokemon/Back/ARCEUS_18.png", "Graphics/Pokemon/Back/ARCEUS_18.png"],
  // R15: las siete pistas del duelo (una por fase + Primigenia) viajaban sólo en
  // la carpeta del juego; sin ellas el Paquete_directo sonaba en silencio. La
  // auditoría de recursos ahora exige que el distributable tenga cada pista.
  ["Audio/BGM/Legend Creation Trio.ogg", "Audio/BGM/Legend Creation Trio.ogg"],
  ["Audio/BGM/Battle! Legendary Raid.ogg", "Audio/BGM/Battle! Legendary Raid.ogg"],
  ["Audio/BGM/Battle! Eternatus - Phase 1.ogg", "Audio/BGM/Battle! Eternatus - Phase 1.ogg"],
  ["Audio/BGM/Battle! Eternatus - Phase 2.ogg", "Audio/BGM/Battle! Eternatus - Phase 2.ogg"],
  ["Audio/BGM/Battle! Eternatus - Phase 3.ogg", "Audio/BGM/Battle! Eternatus - Phase 3.ogg"],
  ["Audio/BGM/Battle! Ultra Necrozma.ogg", "Audio/BGM/Battle! Ultra Necrozma.ogg"],
];

function readScripts(file) {
  return marshalLoad(fs.readFileSync(file));
}
function scriptName(row) {
  return row?.[1]?.text ?? String(row?.[1] ?? "");
}
function routeRow(scripts) {
  return scripts.find((row) => scriptName(row) === "PokeMod_RutaDeDios");
}
function ensureFiles() {
  const required = [
    path.join(GAME_DATA, "Scripts.rxdata"),
    path.join(PACKAGE, "Scripts.rxdata"),
  ];
  for (const file of required) if (!fs.existsSync(file)) throw new Error(`Falta ${file}`);
  if (!routeRow(readScripts(required[0]))) throw new Error("El script ejecutable no contiene PokeMod_RutaDeDios");
  if (!routeRow(readScripts(required[1]))) throw new Error("El paquete no contiene PokeMod_RutaDeDios");
}
function syncScripts() {
  const gameScripts = readScripts(path.join(GAME_DATA, "Scripts.rxdata"));
  const packageScripts = readScripts(path.join(PACKAGE, "Scripts.rxdata"));
  routeRow(packageScripts)[2] = routeRow(gameScripts)[2];
  fs.writeFileSync(path.join(PACKAGE, "Scripts.rxdata"), Buffer.from(marshalDump(packageScripts)));
  fs.mkdirSync(path.join(DIRECT, "Data"), { recursive: true });
  fs.copyFileSync(path.join(PACKAGE, "Scripts.rxdata"), path.join(DIRECT, "Data", "Scripts.rxdata"));
}
function syncFiles() {
  for (const file of DATA_FILES) {
    // Scripts.rxdata no viene del juego: el paquete lleva la copia corregida
    // (colisiones, guardado y Grandeur Club), no el original de pokemon_fire_ash.
    if (file === "Scripts.rxdata") continue;
    const source = path.join(GAME_DATA, file);
    const destination = path.join(DIRECT, "Data", file);
    if (!fs.existsSync(source)) throw new Error(`Falta el dato jugable ${source}`);
    fs.copyFileSync(source, destination);
  }
  for (const [sourceName, destinationName] of ASSET_FILES) {
    const source = path.join(ROOT, "pokemon_fire_ash", sourceName);
    const destination = path.join(DIRECT, destinationName);
    if (!fs.existsSync(source)) throw new Error(`Falta el recurso ${source}`);
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.copyFileSync(source, destination);
  }
}
function zipPackage() {
  execFileSync(process.execPath, [path.join(ROOT, "tools", "build_direct_package.mjs")], { stdio: "inherit" });
  return path.join(PACKAGE, "Fire_Ash_Paquete_Directo.zip");
}
function verify() {
  ensureFiles();
  const game = readScripts(path.join(GAME_DATA, "Scripts.rxdata"));
  const packaged = readScripts(path.join(PACKAGE, "Scripts.rxdata"));
  const gameRoute = routeRow(game);
  const packageRoute = routeRow(packaged);
  if (Buffer.from(gameRoute[2].bytes).compare(Buffer.from(packageRoute[2].bytes)) !== 0) {
    throw new Error("La sección PokeMod_RutaDeDios del paquete está desactualizada");
  }
  for (const file of DATA_FILES) {
    const source = file === "Scripts.rxdata" ? path.join(PACKAGE, file) : path.join(GAME_DATA, file);
    assertSameFile(source, path.join(DIRECT, "Data", file));
  }
  for (const [sourceName, destinationName] of ASSET_FILES) {
    assertSameFile(path.join(ROOT, "pokemon_fire_ash", sourceName), path.join(DIRECT, destinationName));
  }
  const packagedScripts = fs.readFileSync(path.join(PACKAGE, "Scripts.rxdata"));
  const directScripts = fs.readFileSync(path.join(DIRECT, "Data", "Scripts.rxdata"));
  if (!packagedScripts.equals(directScripts)) {
    throw new Error("Paquete_directo/Data/Scripts.rxdata no es la copia corregida con las correcciones de distribución");
  }
  execFileSync(process.execPath, [path.join(ROOT, "tools", "build_direct_package.mjs"), "--verify"], { stdio: "inherit" });
  console.log("OK: Paquete_directo y ZIP sincronizados con PokeMod_RutaDeDios");
}

ensureFiles();
if (VERIFY_ONLY) {
  verify();
} else {
  syncScripts();
  syncFiles();
  const zip = zipPackage();
  console.log(`OK: paquete directo sincronizado (${path.relative(ROOT, zip)})`);
  verify();
}import fs from "node:fs";
import path from "node:path";
