export const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");
export const qa={noBagLock:true,noImpossibleBattle:true,freeReturn:true,allAssetsExist:true,allDataIdsExist:true,notSimilarToPreviousContent:true,creepypastaIsOptInAndNonDestructive:true};
export const banned=["Soy un entrenador","Qué gran combate","Este Pokémon es muy fuerte","Según la Pokédex","Debes derrotarme"];
export const D=(before,during,after,optional)=>({before,during,after,optional});
export const N=(name,sprite,role,reason,conflict,want,fear,tic,dialogue)=>({name,sprite,role,reasonForBeingHere:reason,personalConflict:conflict,want,fear,verbalTic:tic,dialogue});
export const P=(species,level,narrativeRole,moves,item,whyItBelongs)=>({species,level,narrativeRole,moves,item,whyItBelongs});

export function build(d){
  return {mapId:d.id,tier:1,title:d.title,oneSentencePromise:d.promise,
    ...(Number.isInteger(d.prerequisiteSeals)?{prerequisiteSeals:d.prerequisiteSeals}:{}),
    biome:{identity:d.identity,visualStorytelling:d.visual,ambientChanges:d.ambient,assetManifest:[...new Map(d.npcs.map(n=>[n.sprite,{type:"character",id:n.sprite,exists:true}])).values()]},
    narrative:d.narrative,voiceProfile:{...d.voice,forbiddenPhrases:banned},npcs:d.npcs,battle:d.battle,
    cutscene:{trigger:d.steps[0],steps:d.steps.map((action,i)=>({order:i+1,eventCommand:i===3?"Show Choices":i===5?"Trainer Battle canLose":"RMXP event command",actor:i===3?"Jugador":i===5?d.battle.trainerName:"Escena",action,stateChange:i===6?`switch${d.flag}=true`:i===7?"map_state=resolved":null})),decision:d.decision,failurePath:"La derrota devuelve al jugador al punto de curación; no altera la decisión ni bloquea la salida.",reentryPath:"La escena omite la introducción ya vista y permite repetir únicamente la prueba pendiente."},
    reward:d.reward,
    flags:{globalSwitches:[{id:d.flag,name:`POKEMOD ATLAS SEAL ${String(d.flag-707).padStart(2,"0")}`,setWhen:"Tras resolver la decisión y vencer.",readWhen:"Archivo Final y continuidad sectorial."}],variables:[{id:103,name:"POKEMOD ATLAS NARRATIVE SEALS",operation:"Incrementar una vez, protegido por self-switch A."}],selfSwitches:[{event:"Conductor de escena",letter:"A",purpose:"Bloquear recompensa repetida."},{event:d.npcs[0].name,letter:"B",purpose:"Diálogo posterior."}]},
    exits:[{destination:1001,condition:"always",purpose:"Retorno incondicional a Puerto Horizonte."}],qaClaims:qa};
}

export function writeBatch(batch,rows,fileName){
  const out={batch,iteration:1,blueprints:rows.map(build)};
  fs.writeFileSync(path.join(ROOT,"content",fileName),JSON.stringify(out,null,2)+"\n");
  console.log(`Batch ${String(batch).padStart(2,"0")} generado: ${out.blueprints.length} blueprints.`);
}#!/usr/bin/env node
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";
import { marshalLoad, RString } from "../web/js/marshal.js";
import { readZipEntry, readZipIndex } from "./lib/zip_writer.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CORRECTED = path.join(ROOT, "Scripts_corregido", "Scripts.rxdata");
const DIRECT = path.join(ROOT, "Scripts_corregido", "Paquete_directo", "Data", "Scripts.rxdata");
const ZIP = path.join(ROOT, "Scripts_corregido", "Fire_Ash_Paquete_Directo.zip");
const scripts = marshalLoad(fs.readFileSync(CORRECTED));
const getCode = (name) => {
  const row = scripts.find((entry) => (entry[1] instanceof RString ? entry[1].text : String(entry[1])) === name);
  assert.ok(row, `debe existir la sección ${name}`);
  return zlib.inflateSync(Buffer.from(row[2].bytes)).toString("utf8");
};

const safety = getCode("Game_Screen");
assert.match(safety, /module PokeModToneSafety/);
assert.ok(safety.includes("value.match(") && safety.includes("match.captures.map"), "solo interpreta el formato Tone.new conocido");
assert.match(safety, /Tone\.new\(\*match\.captures\.map \{ \|component\| component\.to_f \}\)/);
assert.match(safety, /return Tone\.new\(0, 0, 0, 0\)/);
for (const name of ["Game_Screen", "Game_Picture"]) {
  const code = getCode(name);
  assert.ok(code.includes("tone = PokeModToneSafety.normalize(tone)"), `${name} normaliza el tono recibido`);
  assert.ok(code.includes("@tone = PokeModToneSafety.normalize(@tone)"), `${name} repara el tono actual`);
  assert.ok(code.includes("@tone_target = PokeModToneSafety.normalize(@tone_target)"), `${name} repara el tono objetivo`);
}

const corrected = fs.readFileSync(CORRECTED);
assert.ok(corrected.equals(fs.readFileSync(DIRECT)), "el paquete directo usa el Scripts.rxdata corregido");
const archive = readZipIndex(ZIP);
assert.ok(corrected.equals(readZipEntry(archive, "Data/Scripts.rxdata")), "el ZIP incluye el Scripts.rxdata corregido");
console.log("tone safety: recuperación String→Tone, pantallas/imágenes y paquete OK");#!/usr/bin/env node
/**
 * unpack_assets.mjs — Desempaquetador de assets de las ROMs invitadas.
 *
 * Saca TODOS los assets gráficos y de texto que se pueden decodificar de cada
 * ROM y los deja en una carpeta propia (fuera del juego) lista para usarlos
 * como material de referencia para Fire Ash.
 *
 *   GB / GBC  → sprites de Pokémon (frontal + trasero), descompresión RLE de
 *               1ª generación, emparejados con su especie mediante la tabla de
 *                estadísticas base (paso 28, punteros en +0x0B y +0x0D).
 *   GBA       → bloques LZ77 (compresión estándar de la BIOS de GBA),
 *               exportados como tiles 4bpp + PNG con paleta de grises.
 *
 * Uso:
 *   node tools/unpack_assets.mjs [--dir <carpeta_entrada>] [--salida <dir>]
 *
 * Nada de esto se copia al juego: se guarda en reference/roms_invitadas/<rom>/assets
 * (carpeta ignorada por git) como material de referencia.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { readdirSync } from 'node:fs';
import { join, basename, extname } from 'node:path';
import { deflateSync } from 'node:zlib';

/* ──────────────────────────── PNG mínimo (indexado 8 bits) ───────────────── */

function crc32(buf) {
  let c, crc = 0xFFFFFFFF;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xFF;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function chunk(tipo, datos) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(datos.length);
  const td = Buffer.concat([Buffer.from(tipo, 'ascii'), datos]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}

/** Escribe un PNG indexado de 8 bits. `pix` = array de índices (w*h). */
function escribirPNG(ruta, w, h, pix, paleta) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8;   // profundidad
  ihdr[9] = 3;   // indexado
  const plte = Buffer.concat(paleta.map(([r, g, b]) => Buffer.from([r, g, b])));
  const raw = Buffer.alloc((w + 1) * h);
  let p = 0;
  for (let y = 0; y < h; y++) {
    raw[p++] = 0; // filtro none
    for (let x = 0; x < w; x++) raw[p++] = pix[y * w + x] & 0xFF;
  }
  const png = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
    chunk('IHDR', ihdr),
    chunk('PLTE', plte),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
  writeFileSync(ruta, png);
  return png.length;
}

const PALETA_DMG = [[255, 255, 255], [176, 176, 176], [96, 96, 96], [0, 0, 0]];
const PALETA_GRIS = Array.from({ length: 16 }, (_, i) => {
  const v = (i * 17) & 0xFF;
  return [v, v, v];
});

/* ─────────────────────── Sprites de 1ª generación (GB) ───────────────────── */

// Tablas de decodificación diferencial (pret/pokered home/uncompress.asm)
const TABLA_0 = [0x01, 0x32, 0x76, 0x45, 0xFE, 0xCD, 0x89, 0xBA];
const TABLA_1 = [0xFE, 0xCD, 0x89, 0xBA, 0x01, 0x32, 0x76, 0x45];

/** DifferentialDecodeNybble */
function decodificarNybble(n, e) {
  const c = n & 1;
  const idx = n >> 1;
  const t = (e & 1) ? TABLA_1[idx] : TABLA_0[idx];
  return c ? (t & 0x0F) : (t >> 4);
}

/**
 * SpriteDifferentialDecode (in-place sobre un plano).
 * Recorre el plano por FILAS (todas las columnas de tile de una fila, luego la
 * siguiente): el último nybble decodificado se arrastra entre tiles de la misma
 * fila y se reinicia al empezar cada fila (tal y como hace la ROM).
 */
function deltaDecodificar(buf, wt, ht) {
  const alto = ht * 8;
  for (let r = 0; r < alto; r++) {
    let e = 0;                       // se reinicia en cada fila
    for (let g = 0; g < wt; g++) {
      const idx = g * alto + r;
      const b = buf[idx];
      const altoN = decodificarNybble(b >> 4, e);
      const bajoN = decodificarNybble(b & 0x0F, altoN);
      buf[idx] = (altoN << 4) | bajoN;
      e = bajoN;                     // se arrastra al siguiente tile de la fila
    }
  }
}

/** Lector de bits MSB-first (ReadNextInputBit de la ROM) */
class Bits {
  constructor(data, pos) { this.d = data; this.pos = pos; this.cont = 1; this.cur = 0; }
  bit() {
    if (--this.cont === 0) {
      if (this.pos >= this.d.length) throw new Error('EOF');
      this.cur = this.d[this.pos++];
      this.cont = 8;
    }
    this.cur = ((this.cur << 1) | (this.cur >> 7)) & 0xFF; // rlca
    return this.cur & 1;
  }
}

/**
 * Descomprime un sprite de 1ª generación empezando en `offset`.
 * Devuelve null si los datos no son un sprite válido.
 */
export function descomprimirSpriteGB(data, offset) {
  const dim = data[offset];
  let wt = dim >> 4, ht = dim & 0x0F;
  if (wt === 0) wt = 32;
  if (ht === 0) ht = 32;
  if (wt > 7 || ht > 7) return null;
  const ancho = wt * 8, alto = ht * 8;
  const tamPlano = wt * ht * 8;
  if (tamPlano > 392) return null;

  const r = new Bits(data, offset + 1);
  const planos = [new Uint8Array(392), new Uint8Array(392)];
  let modo = 0;
  let flag0 = 0;

  try {
    flag0 = r.bit();
    for (let trozo = 0; trozo < 2; trozo++) {
      const buf = planos[(flag0 ^ trozo) & 1];
      const st = { x: 0, y: 0, bo: 3, ptr: 0, cache: 0 };
      const mover = () => {
        st.y++;
        if (st.y === alto) {
          st.y = 0;
          if (st.bo !== 0) { st.bo--; st.ptr = st.cache; }
          else {
            st.bo = 3; st.x += 8;
            if (st.x === ancho) return true;      // plano completo
            st.ptr++; st.cache = st.ptr;
          }
        } else st.ptr++;
        return false;
      };
      const escribir = (par) => {
        if (st.ptr < 392) buf[st.ptr] |= (par & 3) << (2 * st.bo);
      };

      if (trozo === 1) {
        const b = r.bit();
        modo = b ? r.bit() + 1 : 0;
      }

      let literal = r.bit() === 1;
      let terminado = false;
      while (!terminado) {
        if (literal) {
          while (true) {
            const hi = r.bit(), lo = r.bit();
            const par = (hi << 1) | lo;
            if (par === 0) { literal = false; break; }
            escribir(par);
            if (mover()) { terminado = true; break; }
          }
        } else {
          let c = 0;
          while (r.bit()) { if (++c > 20) return null; }
          const off = (1 << (c + 1)) - 1;
          let v = 0;
          for (let i = 0; i <= c; i++) v = (v << 1) | r.bit();
          let total = (off + v) & 0xFFFF;
          while (true) {
            escribir(0);
            if (mover()) { terminado = true; break; }
            total = (total - 1) & 0xFFFF;
            if (total === 0) break;
          }
          literal = true;
        }
      }
    }
  } catch {
    return null;
  }

  // UnpackSprite: el orden de los planos depende del primer bit del stream.
  const [p1, p2] = planos;
  const primero = (flag0 & 1) === 0 ? p1 : p2;   // primer trozo del stream
  const segundo = (flag0 & 1) === 0 ? p2 : p1;   // segundo trozo
  if (modo === 0) {
    deltaDecodificar(p1, wt, ht);
    deltaDecodificar(p2, wt, ht);
  } else if (modo === 1) {
    deltaDecodificar(primero, wt, ht);
    for (let i = 0; i < tamPlano; i++) segundo[i] ^= primero[i];
  } else {
    deltaDecodificar(segundo, wt, ht);
    deltaDecodificar(primero, wt, ht);
    for (let i = 0; i < tamPlano; i++) segundo[i] ^= primero[i];
  }

  return { ancho, alto, wt, ht, p1, p2, modo, consumido: r.pos - offset, flag0, tamPlano };
}

/** Une los dos planos 1bpp en una matriz de píxeles 0-3. */
export function planosAPixeles(sp) {
  const { ancho, alto, wt, p1, p2 } = sp;
  const pix = new Uint8Array(ancho * alto);
  for (let g = 0; g < wt; g++) {
    const base = g * alto;
    for (let y = 0; y < alto; y++) {
      const b1 = p1[base + y], b2 = p2[base + y];
      for (let x = 0; x < 8; x++) {
        const bit = 7 - x;
        pix[y * ancho + g * 8 + x] = (((b2 >> bit) & 1) << 1) | ((b1 >> bit) & 1);
      }
    }
  }
  return pix;
}

/** Coloca un sprite frontal en un lienzo de 56×56 (centrado abajo, como la ROM). */
export function centrarFrontal(pix, sp) {
  const W = 56, H = 56;
  const salida = new Uint8Array(W * H);
  const xoff = sp.wt === 6 ? 8 : (7 - sp.wt) * 4;
  const yoff = (7 - sp.ht) * 8;
  for (let y = 0; y < sp.alto; y++) {
    for (let x = 0; x < sp.ancho; x++) {
      const dy = y + yoff, dx = x + xoff;
      if (dx >= 0 && dx < W && dy >= 0 && dy < H) salida[dy * W + dx] = pix[y * sp.ancho + x];
    }
  }
  return salida;
}

/** Trasero: la ROM lo amplía ×2 y descarta la última fila/columna de tiles. */
export function ampliarTrasero(pix, sp) {
  const W = 56, H = 56;
  const salida = new Uint8Array(W * H);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      salida[y * W + x] = pix[(y >> 1) * sp.ancho + (x >> 1)] || 0;
    }
  }
  return salida;
}

/* ── mapa de caracteres de 1ª generación ── */
export function decodificarTextoGB(bytes) {
  let s = '';
  for (const b of bytes) {
    if (b === 0x50) break;
    if (b >= 0x80 && b <= 0x99) s += String.fromCharCode(65 + b - 0x80);
    else if (b === 0x7F) s += ' ';
    else if (b >= 0xF6 && b <= 0xFF) s += String(b - 0xF6);
    else s += `{${b.toString(16).toUpperCase().padStart(2, '0')}}`;
  }
  return s.trim();
}

/** Recorre la tabla de nombres de especie (10 bytes por entrada). */
export function leerNombresGB(data, base, tolerante = true) {
  const nombres = [];
  let o = base;
  while (o + 10 <= data.length) {
    const e = data.subarray(o, o + 10);
    let letras = 0;
    for (const b of e) if (b >= 0x80 && b <= 0x99) letras++;
    if (!tolerante && letras === 0) break;
    if (letras < 2) break;
    nombres.push({ indice: nombres.length, offset: o, nombre: decodificarTextoGB(e) });
    o += 10;
    if (nombres.length > 400) break;
  }
  return nombres;
}

/**
 * Localiza todos los sprites del ROM:
 *  1) prueba todos los offsets cuyo primer byte es una dimensión válida,
 *  2) descarta los que no tienen el tamaño comprimido propio de un sprite real,
 *  3) encadena los que están seguidos (los bancos gráficos son contiguos).
 */
export function buscarSpritesGB(data) {
  const rango = { '7,7': [150, 650], '6,6': [120, 550], '5,5': [80, 450], '4,4': [30, 320] };
  const validos = new Map();
  for (let o = 0; o < data.length - 2; o++) {
    const dim = data[o];
    // un sprite válido de la 1ª generación es cuadrado: 4x4, 5x5, 6x6 o 7x7 tiles
    if (!((dim >> 4) >= 4 && (dim >> 4) <= 7 && (dim >> 4) === (dim & 0xF))) continue;
    const sp = descomprimirSpriteGB(data, o);
    if (!sp) continue;
    const rg = rango[`${sp.wt},${sp.ht}`];
    if (rg && (sp.consumido < rg[0] || sp.consumido > rg[1])) continue;
    validos.set(o, sp);
  }
  const usados = new Set();
  const cadenas = [];
  for (const o of [...validos.keys()].sort((a, b) => a - b)) {
    if (usados.has(o)) continue;
    const cad = [o];
    usados.add(o);
    let cur = o;
    while (cad.length < 400) {
      const L = validos.get(cur).consumido;
      let sig = null;
      for (const pad of [0, 1, 2]) {
        const n = cur + L + pad;
        if (validos.has(n) && !usados.has(n)) { sig = n; break; }
      }
      if (sig === null) break;
      cad.push(sig);
      usados.add(sig);
      cur = sig;
    }
    if (cad.length >= 3) cadenas.push(cad);
  }
  cadenas.sort((a, b) => b.length - a.length);
  return { validos, cadenas };
}

/**
 * Encuentra la tabla de estadísticas base buscando dónde aparecen los punteros
 * de 16 bits de los sprites: paso 28, frontal en +0x0B, trasero en +0x0D.
 */
export function encontrarTablaBaseStats(data, sprites, cadenas, nEspecies) {
  // índice valor de 16 bits -> posiciones donde aparece (una sola pasada)
  const indice = new Map();
  for (let i = 0; i + 1 < data.length; i++) {
    const v = data[i] | (data[i + 1] << 8);
    if (v < 0x4000 || v >= 0x8000) continue;
    let l = indice.get(v);
    if (!l) indice.set(v, (l = []));
    l.push(i);
  }
  const ptrDe = (o) => 0x4000 + (o - Math.floor(o / 0x4000) * 0x4000);

  // 1) votación con el primer sprite de cada banco gráfico
  const votos = new Map();
  for (const cad of cadenas.slice(0, 60)) {
    const pos = indice.get(ptrDe(cad[0])) || [];
    for (const p of pos) {
      if (p > 0x80000) continue;
      for (let k = 0; k < 220; k++) {
        const T = p - 0x0B - 28 * k;
        if (T < 0) break;
        votos.set(T, (votos.get(T) || 0) + 1);
      }
    }
  }
  // 2) los finalistas se puntúan con el emparejamiento real:
  //    en la ROM el trasero está justo después del frontal.
  const finalistas = [...votos.entries()].sort((a, b) => b[1] - a[1]).slice(0, 300).map(([T]) => T);
  let mejor = null;
  for (const T of finalistas) {
    const pares = emparejarEspecies(data, { base: T }, sprites, nEspecies);
    let res = 0, ady = 0;
    for (const p of pares) {
      if (p.frontal === null) continue;
      res++;
      if (p.trasero !== null) {
        const d = p.trasero - p.frontal - sprites.get(p.frontal).consumido;
        if (d >= 0 && d <= 2) ady++;
      }
    }
    const puntos = ady * 2 + res;
    if (!mejor || puntos > mejor.puntos) mejor = { base: T, puntos, res, ady, votos: votos.get(T) };
  }
  return mejor;
}

/** Empareja cada especie con sus dos sprites usando la tabla anterior. */
export function emparejarEspecies(data, tabla, sprites, nNombres) {
  const { base } = tabla;
  const salida = [];
  const resolver = (ptr) => {
    if (ptr < 0x4000 || ptr >= 0x8000) return null;
    const off = ptr - 0x4000;
    for (let banco = 1; banco < 64; banco++) {
      const abs = banco * 0x4000 + off;
      if (sprites.has(abs)) return abs;
    }
    return null;
  };
  for (let i = 0; i < nNombres; i++) {
    const e = base + 28 * i;
    if (e + 14 >= data.length) break;
    const ptrF = data[e + 0x0B] | (data[e + 0x0C] << 8);
    const ptrT = data[e + 0x0D] | (data[e + 0x0E] << 8);
    salida.push({ indice: i, ptrFrontal: ptrF, ptrTrasero: ptrT, frontal: resolver(ptrF), trasero: resolver(ptrT) });
  }
  return salida;
}

/* ─────────────────────────────── GBA: LZ77 ──────────────────────────────── */

/** LZ77 de la BIOS de GBA (variante LZ10). Devuelve null si no encaja. */
export function lz77Descomprimir(data, off, maxSalida = 0x40000) {
  if (off + 4 > data.length) return null;
  if (data[off] !== 0x10) return null;
  const tam = data[off + 1] | (data[off + 2] << 8) | (data[off + 3] << 16);
  if (tam <= 0 || tam > maxSalida) return null;
  const salida = Buffer.alloc(tam);
  let p = off + 4, d = 0;
  while (d < tam && p < data.length) {
    const flags = data[p++];
    for (let i = 0; i < 8 && d < tam && p < data.length; i++) {
      if (flags & (0x80 >> i)) {
        const b1 = data[p++], b2 = data[p++];
        const len = (b1 >> 4) + 3;
        const disp = (((b1 & 0x0F) << 8) | b2) + 1;
        if (disp > d) return null;
        for (let k = 0; k < len && d < tam; k++) salida[d++] = salida[d - disp];
      } else {
        salida[d++] = data[p++];
      }
    }
  }
  return d === tam ? salida : null;
}

/** Renderiza datos de tiles 4bpp como PNG (16 colores, paleta de grises). */
export function tiles4bppAPixeles(buf, anchoTiles = 16) {
  const nTiles = Math.floor(buf.length / 32);
  if (!nTiles) return null;
  const px = anchoTiles * 8;
  const filas = Math.ceil(nTiles / anchoTiles) * 8;
  const pix = new Uint8Array(px * filas);
  for (let t = 0; t < nTiles; t++) {
    const tx = (t % anchoTiles) * 8, ty = Math.floor(t / anchoTiles) * 8;
    for (let y = 0; y < 8; y++) {
      for (let x = 0; x < 8; x++) {
        const b = buf[t * 32 + y * 4 + (x >> 1)];
        const v = (x & 1) ? (b >> 4) : (b & 0x0F);
        const px1 = tx + x, py = ty + y;
        if (py < filas && px1 < px) pix[py * px + px1] = v;
      }
    }
  }
  return { pix, w: px, h: filas, nTiles };
}

function escanearLZ77(data) {
  const bloques = [];
  for (let o = 0; o < data.length - 4; o++) {
    if (data[o] !== 0x10) continue;
    const tam = data[o + 1] | (data[o + 2] << 8) | (data[o + 3] << 16);
    if (tam < 64 || tam > 0x40000 || o + 4 + tam > data.length + 64) continue;
    const dec = lz77Descomprimir(data, o);
    if (!dec) continue;
    // descarta bloques que no parecen gráficos (demasiado uniformes)
    let distintos = new Set();
    for (let i = 0; i < Math.min(dec.length, 512); i++) distintos.add(dec[i]);
    if (distintos.size < 4) continue;
    bloques.push({ offset: o, tam, datos: dec });
    o += 3;
  }
  return bloques;
}

/* ──────────────────────────────── programa ──────────────────────────────── */

function slug(nombre) {
  return basename(nombre, extname(nombre)).replace(/[^\w.-]+/g, '_');
}

function procesarGB(ruta, salidaDir) {
  const data = readFileSync(ruta);
  const nombre = basename(ruta);
  console.log(`\n═══ ${nombre} (${data.length} bytes, GB/GBC) ═══`);

  // 1) nombres de especie
  const nombres = leerNombresGB(data, 0x1C236);
  console.log(`  Especies en la tabla de nombres: ${nombres.length}`);

  // 2) sprites
  const { validos, cadenas } = buscarSpritesGB(data);
  console.log(`  Sprites decodificados: ${validos.size} (${cadenas.length} bancos gráficos)`);

  // 3) tabla de estadísticas base y emparejamiento
  const tabla = encontrarTablaBaseStats(data, validos, cadenas, nombres.length);
  let pares = [];
  if (tabla) {
    console.log(`  Tabla de estadísticas base: 0x${tabla.base.toString(16).toUpperCase()} (paso 28, ${tabla.ady} traseros contiguos, ${tabla.res} frontales)`);
    pares = emparejarEspecies(data, tabla, validos, nombres.length);
    const conAmbos = pares.filter((p) => p.frontal !== null && p.trasero !== null).length;
    const conFrontal = pares.filter((p) => p.frontal !== null).length;
    console.log(`  Especies emparejadas: ${conFrontal} con frontal, ${conAmbos} con frontal+trasero`);
  }

  // 4) exportar PNG
  const dirSprites = join(salidaDir, 'sprites');
  mkdirSync(dirSprites, { recursive: true });
  const inventario = [];
  for (const p of pares) {
    const nom = nombres[p.indice]?.nombre || `SIN_NOMBRE_${p.indice}`;
    const limpio = nom.replace(/[^A-Za-z0-9{}]/g, '_').toUpperCase();
    const fila = { indice: p.indice, nombre: nom, archivos: {} };
    if (p.frontal !== null) {
      const sp = validos.get(p.frontal);
      const pix = planosAPixeles(sp);
      const lienzo = centrarFrontal(pix, sp);
      const f = join(dirSprites, `${String(p.indice).padStart(3, '0')}_${limpio}_frontal.png`);
      escribirPNG(f, 56, 56, lienzo, PALETA_DMG);
      fila.archivos.frontal = basename(f);
      fila.frontal = { offset: `0x${p.frontal.toString(16)}`, tiles: `${sp.wt}x${sp.ht}`, modo: sp.modo, bytes: sp.consumido };
    }
    if (p.trasero !== null) {
      const sp = validos.get(p.trasero);
      const pix = planosAPixeles(sp);
      const lienzo = ampliarTrasero(pix, sp);
      const f = join(dirSprites, `${String(p.indice).padStart(3, '0')}_${limpio}_trasero.png`);
      escribirPNG(f, 56, 56, lienzo, PALETA_DMG);
      fila.archivos.trasero = basename(f);
      fila.trasero = { offset: `0x${p.trasero.toString(16)}`, tiles: `${sp.wt}x${sp.ht}`, modo: sp.modo, bytes: sp.consumido };
    }
    if (fila.archivos.frontal || fila.archivos.trasero) inventario.push(fila);
  }

  // 5) sprites sueltos (no emparejados): entrenadores y otros gráficos
  const emparejados = new Set();
  for (const p of pares) { if (p.frontal !== null) emparejados.add(p.frontal); if (p.trasero !== null) emparejados.add(p.trasero); }
  const dirOtros = join(salidaDir, 'sprites_sin_emparejar');
  mkdirSync(dirOtros, { recursive: true });
  const sueltos = [];
  for (const cad of cadenas) {
    for (const o of cad) {
      if (emparejados.has(o)) continue;
      const sp = validos.get(o);
      if (sp.ht < 5) continue; // los 4x4 sueltos suelen ser traseros sin emparejar
      const pix = planosAPixeles(sp);
      const lienzo = centrarFrontal(pix, sp);
      const f = join(dirOtros, `b${String(Math.floor(o / 0x4000)).padStart(2, '0')}_0x${o.toString(16).padStart(5, '0')}_${sp.wt}x${sp.ht}.png`);
      escribirPNG(f, 56, 56, lienzo, PALETA_DMG);
      sueltos.push({ archivo: basename(f), offset: `0x${o.toString(16)}`, tiles: `${sp.wt}x${sp.ht}`, modo: sp.modo });
    }
  }
  console.log(`  Sprites sueltos (entrenadores/otros): ${sueltos.length}`);

  // 6) textos: tabla de nombres exportada
  writeFileSync(join(salidaDir, 'especies.txt'),
    nombres.map((n) => `${String(n.indice).padStart(3, '0')}\t${n.nombre}\t0x${n.offset.toString(16)}`).join('\n') + '\n');

  const indice = {
    rom: nombre, tipo: 'GB/GBC', tamano: data.length,
    especies: nombres.length,
    sprites_decodificados: validos.size,
    bancos_graficos: cadenas.slice(0, 12).map((c) => ({ inicio: `0x${c[0].toString(16)}`, n: c.length })),
    tabla_base_stats: tabla ? `0x${tabla.base.toString(16)}` : null,
    emparejados: inventario.length,
    sueltos: sueltos.length,
    sprites: inventario,
    sprites_sueltos: sueltos,
  };
  writeFileSync(join(salidaDir, 'indice_assets.json'), JSON.stringify(indice, null, 2));
  return indice;
}

function procesarGBA(ruta, salidaDir) {
  const data = readFileSync(ruta);
  const nombre = basename(ruta);
  console.log(`\n═══ ${nombre} (${data.length} bytes, GBA) ═══`);
  const bloques = escanearLZ77(data);
  console.log(`  Bloques LZ77 válidos: ${bloques.length}`);

  const dirGraficos = join(salidaDir, 'graficos_lz77');
  const dirDatos = join(salidaDir, 'datos_lz77');
  mkdirSync(dirGraficos, { recursive: true });
  mkdirSync(dirDatos, { recursive: true });

  const inventario = [];
  const graficos = bloques.filter((b) => b.tam % 32 === 0 && b.tam >= 512);
  for (const b of graficos) {
    const hex = b.offset.toString(16).padStart(6, '0');
    writeFileSync(join(dirDatos, `lz_${hex}.bin`), b.datos);
    const img = tiles4bppAPixeles(b.datos, 16);
    if (!img) continue;
    const f = join(dirGraficos, `lz_${hex}.png`);
    escribirPNG(f, img.w, img.h, img.pix, PALETA_GRIS);
    inventario.push({ offset: `0x${b.offset.toString(16)}`, descomprimido: b.tam, tiles: img.nTiles, png: basename(f), bin: `lz_${hex}.bin` });
  }
  console.log(`  Gráficos exportados: ${inventario.length} PNG + ${graficos.length} BIN`);

  const indice = {
    rom: nombre, tipo: 'GBA', tamano: data.length,
    bloques_lz77: bloques.length,
    graficos_exportados: inventario.length,
    bloques: inventario,
  };
  writeFileSync(join(salidaDir, 'indice_assets.json'), JSON.stringify(indice, null, 2));
  return indice;
}

function main() {
  const args = process.argv.slice(2);
  const dirIn = (args.includes('--dir') ? args[args.indexOf('--dir') + 1] : null) || 'reference/roms_invitadas/entrada';
  const salidaBase = (args.includes('--salida') ? args[args.indexOf('--salida') + 1] : null) || 'reference/roms_invitadas';

  if (!existsSync(dirIn)) {
    console.error(`No existe la carpeta de entrada: ${dirIn}`);
    process.exit(1);
  }
  const roms = readdirSync(dirIn).filter((f) => /\.(gba|gb|gbc)$/i.test(f));
  if (!roms.length) {
    console.error(`No hay ROMs en ${dirIn}`);
    process.exit(1);
  }

  console.log(`Desempaquetando ${roms.length} ROM(s) de ${dirIn} → ${salidaBase}/<rom>/assets`);
  const resumen = [];
  for (const f of roms.sort()) {
    const ruta = join(dirIn, f);
    const s = slug(f);
    const salida = join(salidaBase, s, 'assets');
    mkdirSync(salida, { recursive: true });
    const indice = /\.gb$/i.test(f) ? procesarGB(ruta, salida) : procesarGBA(ruta, salida);
    resumen.push({ rom: f, carpeta: salida, ...indice });
  }

  // informe global
  const lineas = ['# Assets desempaquetados de las ROMs invitadas', ''];
  for (const r of resumen) {
    lineas.push(`## ${r.rom} (${r.tipo})`);
    lineas.push(`- Carpeta: \`${r.carpeta}\``);
    if (r.tipo === 'GB/GBC') {
      lineas.push(`- Especies identificadas: **${r.especies}**`);
      lineas.push(`- Sprites decodificados: **${r.sprites_decodificados}** (frontal+trasero emparejados: ${r.emparejados}, sueltos: ${r.sueltos})`);
      lineas.push(`- Tabla de estadísticas base: ${r.tabla_base_stats}`);
    } else {
      lineas.push(`- Bloques LZ77 válidos: **${r.bloques_lz77}**`);
      lineas.push(`- Gráficos exportados: **${r.graficos_exportados}** (PNG + BIN)`);
    }
    lineas.push('');
  }
  writeFileSync(join(salidaBase, 'ASSETS_DESEMPAQUETADOS.md'), lineas.join('\n'));
  console.log(`\n✔ Informe: ${join(salidaBase, 'ASSETS_DESEMPAQUETADOS.md')}`);
}

if (process.argv[1] && process.argv[1].endsWith('unpack_assets.mjs')) main();#!/usr/bin/env node
/**
 * unpack_gba_mons.mjs — extrae los sprites de Pokémon de los ROM de GBA con su
 * nombre y su paleta reales, localizando las tablas del motor de 3ª generación:
 *
 *   gMonFrontPicTable   paso 8  → { puntero LZ77 (4B), tamaño (2B), tag (2B) }
 *   gMonBackPicTable    paso 8  → idem
 *   gMonPaletteTable    paso 4  → puntero a paleta de 16 colores (32 B)
 *   gMonIconTable       paso 4  → puntero a icono 32×32 (0x200 B, sin comprimir)
 *   tabla de nombres    paso 11 → 11 bytes por especie, charmap de 3ª gen
 *
 * Salida: reference/roms_invitadas/<rom>/assets/mons/
 *   <nnn>_<NOMBRE>_front.png · _back.png · _icon.png · paletas/*.pal · mons.json
 *
 * Uso: node tools/unpack_gba_mons.mjs [--dir reference/roms_invitadas/entrada]
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync } from 'node:fs';
import { join, basename, extname } from 'node:path';
import { deflateSync } from 'node:zlib';
import { lz77Descomprimir } from './unpack_assets.mjs';

/* ─────────────────────────────── PNG RGBA ────────────────────────────── */
const TABLA_CRC = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c; }
  return t;
})();
function crc32(buf) { let c = -1; for (let i = 0; i < buf.length; i++) c = TABLA_CRC[(c ^ buf[i]) & 0xFF] ^ (c >>> 8); return (c ^ -1) >>> 0; }
function chunk(t, d) {
  const l = Buffer.alloc(4); l.writeUInt32BE(d.length);
  const td = Buffer.concat([Buffer.from(t, 'ascii'), d]);
  const c = Buffer.alloc(4); c.writeUInt32BE(crc32(td));
  return Buffer.concat([l, td, c]);
}
function escribirPNG(ruta, w, h, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  let p = 0;
  for (let y = 0; y < h; y++) { raw[p++] = 0; for (let x = 0; x < w * 4; x++) raw[p++] = rgba[y * w * 4 + x]; }
  mkdirSync(ruta.substring(0, ruta.lastIndexOf('/')), { recursive: true });
  writeFileSync(ruta, Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
    chunk('IHDR', ihdr), chunk('IDAT', deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0)),
  ]));
}

/* ────────────────────────── mapa de caracteres GBA ────────────────────── */
export function decodificarTextoGBA(bytes) {
  let s = '';
  for (const b of bytes) {
    if (b === 0xFF) break;
    if (b === 0x00) { s += ' '; continue; }
    if (b >= 0xBB && b <= 0xD4) { s += String.fromCharCode(65 + b - 0xBB); continue; }   // A-Z
    if (b >= 0xD5 && b <= 0xEE) { s += String.fromCharCode(97 + b - 0xD5); continue; }   // a-z
    if (b >= 0xA1 && b <= 0xAA) { s += String(b - 0xA1); continue; }                     // 0-9
    if (b === 0xB4) { s += '-'; continue; }
    if (b === 0xB0) { s += '...'; continue; }
    s += `{${b.toString(16).toUpperCase().padStart(2, '0')}}`;
  }
  return s.trim();
}

/** Busca la tabla de nombres de especie (11 bytes por entrada). */
export function buscarTablaNombres(data, minEntradas = 40) {
  let mejor = null;
  for (let o = 0; o + 11 < data.length; o++) {
    if (data[o + 10] !== 0xFF) continue;
    let n = 0;
    while (o + n * 11 + 11 <= data.length) {
      const e = data.subarray(o + n * 11, o + n * 11 + 11);
      if (e[10] !== 0xFF) break;
      let letras = 0;
      for (let k = 0; k < 10; k++) if ((e[k] >= 0xBB && e[k] <= 0xEE) || e[k] === 0x00) letras++;
      if (letras < 7) break;
      n++;
      if (n > 900) break;
    }
    if (n >= minEntradas && (!mejor || n > mejor.n)) mejor = { base: o, n };
    if (mejor) o += Math.max(0, mejor.n * 11 - 1);
  }
  if (!mejor) return null;
  const nombres = [];
  for (let i = 0; i < mejor.n; i++) {
    nombres.push(decodificarTextoGBA(data.subarray(mejor.base + i * 11, mejor.base + i * 11 + 11)));
  }
  return { base: mejor.base, nombres };
}

/** Busca tablas de sprites: paso 8 (puntero LZ77 + tamaño) o paso 4 (puntero). */
export function buscarTablasPunteros(data, opciones) {
  const { paso, minEntradas = 40, validar } = opciones;
  const halladas = [];
  for (let o = 0; o + paso < data.length; o++) {
    let n = 0;
    while (o + n * paso + paso <= data.length) {
      const ptr = data.readUInt32LE(o + n * paso);
      const off = ptr - 0x08000000;
      if (off < 0 || off >= data.length) break;
      if (!validar(data, off, o + n * paso)) break;
      n++;
      if (n > 900) break;
    }
    if (n >= minEntradas) {
      halladas.push({ base: o, n });
      o += n * paso - 1;
    }
  }
  halladas.sort((a, b) => b.n - a.n || a.base - b.base);
  return halladas;
}

const esLZ77 = (data, off) => data[off] === 0x10;
const tamEsperado = (data, off, esperado) => {
  const t = data.readUInt32LE(off + 1) & 0xFFFFFF;
  return t === esperado;
};

/** Paleta de 16 colores en formato 15-bit BGR (GBA). */
export function leerPaleta(data, off) {
  const pal = [];
  for (let i = 0; i < 16; i++) {
    const v = data.readUInt16LE(off + i * 2);
    const r = (v & 0x1F) << 3, g = ((v >> 5) & 0x1F) << 3, b = ((v >> 10) & 0x1F) << 3;
    pal.push([Math.min(255, r * 255 / 248), Math.min(255, g * 255 / 248), Math.min(255, b * 255 / 248)]);
  }
  return pal;
}

/** Renderiza tiles 4bpp (índice 0 transparente) con una paleta dada. */
export function renderizar(datos, paleta, tilesAncho, escala = 2) {
  const w = tilesAncho * 8;
  const altoTiles = Math.floor(datos.length / 32 / tilesAncho);
  const h = altoTiles * 8;
  const rgba = new Uint8Array(w * escala * h * escala * 4);
  for (let t = 0; t < tilesAncho * altoTiles; t++) {
    const tx = (t % tilesAncho) * 8, ty = Math.floor(t / tilesAncho) * 8;
    for (let y = 0; y < 8; y++) {
      for (let x = 0; x < 8; x++) {
        const b = datos[t * 32 + y * 4 + (x >> 1)] || 0;
        const idx = (x & 1) ? (b >> 4) : (b & 0x0F);
        if (idx === 0) continue;
        const [r, g, bl] = paleta[idx];
        for (let dy = 0; dy < escala; dy++) {
          for (let dx = 0; dx < escala; dx++) {
            const px = (tx + x) * escala + dx, py = (ty + y) * escala + dy;
            const o = (py * w * escala + px) * 4;
            rgba[o] = r; rgba[o + 1] = g; rgba[o + 2] = bl; rgba[o + 3] = 255;
          }
        }
      }
    }
  }
  return { w: w * escala, h: h * escala, rgba };
}

/* ──────────────────────────────── programa ───────────────────────────── */

function procesar(ruta, salidaDir) {
  const data = readFileSync(ruta);
  const nombre = basename(ruta);
  console.log(`\n═══ ${nombre} ═══`);

  const nombres = buscarTablaNombres(data);
  if (!nombres) { console.log('  sin tabla de nombres'); return null; }
  console.log(`  Nombres de especie: ${nombres.nombres.length} (tabla 0x${nombres.base.toString(16)})`);

  // frontal y trasero: paso 8, puntero a LZ77 de 0x800 bytes (64×64 4bpp)
  const pics = buscarTablasPunteros(data, {
    paso: 8, minEntradas: 40,
    validar: (d, off, pos) => {
      if (!esLZ77(d, off)) return false;
      const tam = d.readUInt16LE(pos + 4);
      return (tam === 0x800 || tam === 0x1000) && tamEsperado(d, off, tam);
    },
  });
  console.log(`  Tablas de sprites 64×64: ${pics.map((p) => `0x${p.base.toString(16)} (${p.n})`).join(', ') || 'ninguna'}`);

  // paletas: paso 4 → 32 bytes con 16 colores válidos
  const pals = buscarTablasPunteros(data, {
    paso: 4, minEntradas: 40,
    validar: (d, off) => {
      if (off + 32 > d.length) return false;
      for (let i = 0; i < 16; i++) {
        const v = d.readUInt16LE(off + i * 2);
        if (v & 0x8000) return false;
      }
      // al menos 3 colores distintos y ninguno totalmente negro repetido 16 veces
      const s = new Set();
      for (let i = 0; i < 16; i++) s.add(d.readUInt16LE(off + i * 2));
      return s.size >= 3;
    },
  });
  console.log(`  Tablas de paletas: ${pals.map((p) => `0x${p.base.toString(16)} (${p.n})`).join(', ') || 'ninguna'}`);

  // iconos: paso 4 → 0x200 bytes sin comprimir (32×32 4bpp)
  const iconosT = buscarTablasPunteros(data, {
    paso: 4, minEntradas: 40,
    validar: (d, off) => off + 0x200 <= d.length && !esLZ77(d, off),
  });
  console.log(`  Tablas de iconos: ${iconosT.map((p) => `0x${p.base.toString(16)} (${p.n})`).join(', ') || 'ninguna'}`);

  const tFrontal = pics[0], tTrasero = pics[1];
  const tPaleta = pals.find((p) => !tFrontal || p.base > tFrontal.base) || pals[0];
  const tIconos = iconosT.find((p) => !tFrontal || p.base > tFrontal.base) || iconosT[0];

  const dirPal = join(salidaDir, 'mons/paletas');
  mkdirSync(dirPal, { recursive: true });
  const inventario = [];
  const total = Math.min(nombres.nombres.length, tFrontal ? tFrontal.n : 0);

  for (let i = 1; i < total; i++) {
    const nom = (nombres.nombres[i] || `SIN_NOMBRE_${i}`).replace(/[^A-Za-z0-9{}]/g, '_').toUpperCase();
    const etiqueta = `${String(i).padStart(3, '0')}_${nom}`;
    let paleta = null;
    if (tPaleta && i < tPaleta.n) {
      const ptr = data.readUInt32LE(tPaleta.base + i * 4);
      const off = ptr - 0x08000000;
      if (off >= 0 && off + 32 <= data.length) {
        paleta = leerPaleta(data, off);
        writeFileSync(join(dirPal, `${etiqueta}.pal`), Buffer.from(
          paleta.flatMap(([r, g, b]) => [Math.round(r), Math.round(g), Math.round(b)])));
      }
    }
    if (!paleta) continue;
    const fila = { indice: i, nombre: nombres.nombres[i], archivos: {} };

    const exportar = (tabla, sufijo, tilesAncho, escala) => {
      if (!tabla || i >= tabla.n) return;
      const ptr = data.readUInt32LE(tabla.base + i * 8);
      const off = ptr - 0x08000000;
      const dec = lz77Descomprimir(data, off);
      if (!dec) return;
      const img = renderizar(dec, paleta, tilesAncho, escala);
      const f = join(salidaDir, 'mons', `${etiqueta}_${sufijo}.png`);
      escribirPNG(f, img.w, img.h, img.rgba);
      fila.archivos[sufijo] = basename(f);
    };
    exportar(tFrontal, 'front', 8, 2);
    exportar(tTrasero, 'back', 8, 2);

    if (tIconos && i < tIconos.n) {
      const ptr = data.readUInt32LE(tIconos.base + i * 4);
      const off = ptr - 0x08000000;
      if (off >= 0 && off + 0x200 <= data.length) {
        const img = renderizar(data.subarray(off, off + 0x200), paleta, 4, 3);
        const f = join(salidaDir, 'mons', `${etiqueta}_icon.png`);
        escribirPNG(f, img.w, img.h, img.rgba);
        fila.archivos.icon = basename(f);
      }
    }
    if (Object.keys(fila.archivos).length) inventario.push(fila);
  }

  console.log(`  Especies exportadas: ${inventario.length}`);
  const indice = {
    rom: nombre,
    tablas: {
      nombres: `0x${nombres.base.toString(16)}`,
      frontales: tFrontal ? `0x${tFrontal.base.toString(16)} (${tFrontal.n})` : null,
      traseros: tTrasero ? `0x${tTrasero.base.toString(16)} (${tTrasero.n})` : null,
      paletas: tPaleta ? `0x${tPaleta.base.toString(16)} (${tPaleta.n})` : null,
      iconos: tIconos ? `0x${tIconos.base.toString(16)} (${tIconos.n})` : null,
    },
    especies: inventario,
  };
  writeFileSync(join(salidaDir, 'mons/mons.json'), JSON.stringify(indice, null, 2));
  writeFileSync(join(salidaDir, 'mons/especies.txt'),
    nombres.nombres.map((n, i) => `${String(i).padStart(3, '0')}\t${n}`).join('\n') + '\n');
  return indice;
}

function main() {
  const args = process.argv.slice(2);
  const dirIn = (args.includes('--dir') ? args[args.indexOf('--dir') + 1] : null) || 'reference/roms_invitadas/entrada';
  const salidaBase = (args.includes('--salida') ? args[args.indexOf('--salida') + 1] : null) || 'reference/roms_invitadas';
  const roms = readdirSync(dirIn).filter((f) => /\.gba$/i.test(f));
  const resumen = [];
  for (const f of roms.sort()) {
    const s = basename(f, extname(f)).replace(/[^\w.-]+/g, '_');
    const salida = join(salidaBase, s, 'assets');
    mkdirSync(salida, { recursive: true });
    const r = procesar(join(dirIn, f), salida);
    if (r) resumen.push({ rom: f, ...r });
  }
  writeFileSync('content/mons_invitados.json', JSON.stringify(resumen.map((r) => ({
    rom: r.rom, tablas: r.tablas, especies: r.especies.length,
  })), null, 2));
  console.log('\n✔ Resumen: content/mons_invitados.json');
}

if (process.argv[1] && process.argv[1].endsWith('unpack_gba_mons.mjs')) main();#!/usr/bin/env node
/**
 * Prepara un ROM invitado para el analizador: localiza el archivo, lo
 * descomprime si hace falta y deja lista la carpeta con Data/MapInfos.rxdata.
 *
 * Admite ZIP (con o sin contraseña), RAR de varias partes (si el sistema tiene
 * unrar/unar/7z/bsdtar) y carpetas ya descomprimidas. La contraseña se prueba
 * con la lista que indique el jugador (--clave a, --clave b) o con la serie
 * numérica típica que él mismo dio (1, 12, 123, …, 12345678).
 *
 * Uso:
 *   node tools/unpack_guest_rom.mjs --entrada reference/roms_invitadas/entrada
 *   node tools/unpack_guest_rom.mjs --entrada juegos/glazed.rar --slug glazed
 *   node tools/unpack_guest_rom.mjs --entrada juegos/ --slug team_rocket --clave 12345678
 *
 * Salida: reference/roms_invitadas/<slug>/juego/… (carpeta ignorada por Git).
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT_ROOT = path.join(ROOT, "reference", "roms_invitadas");

const arg = (name, fallback = null) => {
  const key = `--${name}`;
  const i = process.argv.indexOf(key);
  return i >= 0 && process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : fallback;
};
const allArgs = (name) => {
  const key = `--${name}`;
  const out = [];
  for (let i = 0; i < process.argv.length; i += 1) {
    if (process.argv[i] === key && process.argv[i + 1] && !process.argv[i + 1].startsWith("--")) out.push(process.argv[i + 1]);
  }
  return out;
};
const ENTRADA = arg("entrada");
const SLUG = arg("slug", "invitado");
const CLAVES = allArgs("clave");

const which = (bin) => {
  try {
    execFileSync("command", ["-v", bin], { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
};

const esJuego = (dir) => fs.existsSync(path.join(dir, "Data", "MapInfos.rxdata"));
const esRaizDeJuego = (dir) => fs.existsSync(path.join(dir, "MapInfos.rxdata"));

/** Busca, dentro de un árbol, la carpeta que contiene Data/MapInfos.rxdata. */
function buscarJuego(dir, profundidad = 3) {
  if (esJuego(dir)) return path.join(dir, "Data");
  if (esRaizDeJuego(dir)) return dir;
  if (profundidad <= 0) return null;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const found = buscarJuego(path.join(dir, entry.name), profundidad - 1);
    if (found) return found;
  }
  return null;
}

function archivosDe(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isFile())
    .map((e) => path.join(dir, e.name));
}

/** Encuentra el archivo contenedor: prioriza el .rar/.zip que empiece el juego. */
function encontrarContenedor(dir) {
  const files = archivosDe(dir);
  const rar = files.filter((f) => /\.rar$/i.test(f) || /\.r\d{2}$/i.test(f) || /\.part\d+\.rar$/i.test(f));
  const zip = files.filter((f) => /\.zip$/i.test(f) || /\.7z$/i.test(f));
  const ordenar = (a, b) => fs.statSync(b).size - fs.statSync(a).size;
  return rar.sort(ordenar)[0] || zip.sort(ordenar)[0] || null;
}

const CANDIDATOS_CLAVE = () => {
  const base = ["", "1", "12", "123", "1234", "12345", "123456", "1234567", "12345678"];
  return [...new Set([...CLAVES, ...base])];
};

function intentar(bin, args) {
  try {
    execFileSync(bin, args, { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

function descomprimirZip(archivo, destino) {
  fs.mkdirSync(destino, { recursive: true });
  for (const clave of CANDIDATOS_CLAVE()) {
    const args = ["-qq", "-o", clave ? `-P${clave}` : "-P", archivo, "-d", destino];
    if (intentar("unzip", args.filter((a) => a !== "-P"))) return { ok: true, herramienta: "unzip", clave };
    if (clave && intentar("unzip", args)) return { ok: true, herramienta: "unzip", clave };
  }
  return { ok: false };
}

function descomprimirRar(archivo, destino) {
  const herramientas = [
    { bin: "unrar", args: (clave) => ["x", "-y", clave ? `-p${clave}` : "-p-", archivo, `${destino}/`] },
    { bin: "unar", args: (clave) => ["-f", "-o", destino, clave ? `-p${clave}` : "-p", archivo] },
    { bin: "7z", args: (clave) => ["x", "-y", clave ? `-p${clave}` : "-p", `-o${destino}`, archivo] },
    { bin: "7za", args: (clave) => ["x", "-y", clave ? `-p${clave}` : "-p", `-o${destino}`, archivo] },
    { bin: "7zr", args: (clave) => ["x", "-y", clave ? `-p${clave}` : "-p", `-o${destino}`, archivo] },
    { bin: "bsdtar", args: (clave) => ["-xf", archivo, "-C", destino, ...(clave ? [`--passphrase`, clave] : [])] },
  ];
  const disponible = herramientas.find((h) => which(h.bin));
  if (!disponible) return { ok: false, sinHerramienta: true };
  fs.mkdirSync(destino, { recursive: true });
  for (const clave of CANDIDATOS_CLAVE()) {
    if (intentar(disponible.bin, disponible.args(clave))) return { ok: true, herramienta: disponible.bin, clave };
  }
  return { ok: false, herramienta: disponible.bin };
}

function preparar() {
  if (!ENTRADA) throw new Error("Falta --entrada <carpeta o archivo>.");
  const entrada = path.resolve(ENTRADA);
  if (!fs.existsSync(entrada)) {
    throw new Error(
      `No encuentro ${ENTRADA}. Sube el juego a reference/roms_invitadas/entrada/ ` +
        "(carpeta ignorada por Git) y vuelve a ejecutar este comando."
    );
  }
  const destino = path.join(OUT_ROOT, SLUG);
  const juegoDir = path.join(destino, "juego");

  // 1) ¿Ya es un juego descomprimido?
  if (fs.statSync(entrada).isDirectory()) {
    const data = buscarJuego(entrada);
    if (data) {
      console.log(`El juego ya está descomprimido: ${path.relative(ROOT, data)}`);
      console.log(`Siguiente paso: node tools/inspect_guest_rom.mjs --dir "${path.dirname(data)}" --slug ${SLUG}`);
      return;
    }
  }

  // 2) Localizar el contenedor
  const contenedor = fs.statSync(entrada).isDirectory() ? encontrarContenedor(entrada) : entrada;
  if (!contenedor) {
    throw new Error(
      `No hay ningún .zip ni .rar en ${entrada}. Sube la carpeta ya descomprimida ` +
        "(con Data/, Graphics/ y Audio/) o un ZIP."
    );
  }
  console.log(`Contenedor: ${path.basename(contenedor)} (${(fs.statSync(contenedor).size / 1048576).toFixed(1)} MB)`);

  // 3) Descomprimir
  fs.mkdirSync(juegoDir, { recursive: true });
  const resultado = /\.zip$/i.test(contenedor)
    ? descomprimirZip(contenedor, juegoDir)
    : descomprimirRar(contenedor, juegoDir);
  if (!resultado.ok) {
    if (resultado.sinHerramienta) {
      throw new Error(
        "Este entorno no tiene ningún descompresor de RAR (ni unrar, ni unar, ni 7z, ni bsdtar) y no se " +
          "puede instalar uno: apt no tiene red y libunrar no está disponible.\n" +
          "Soluciones, de mejor a peor:\n" +
          "  1. Descomprime el RAR en tu PC y sube la carpeta (Data/, Graphics/, Audio/).\n" +
          "  2. Vuelve a comprimirlo como ZIP y súbelo así: el ZIP sí se puede abrir aquí.\n" +
          "  3. Súbelo también como .7z si ya lo tienes en ese formato."
      );
    }
    throw new Error(
      `No pude abrir ${path.basename(contenedor)} con ${resultado.herramienta}. ` +
        "Prueba a pasar la contraseña con --clave <contraseña>."
    );
  }
  console.log(`Descomprimido con ${resultado.herramienta}${resultado.clave ? ` (contraseña "${resultado.clave}")` : " (sin contraseña)"}`);

  // 4) Localizar el juego dentro de lo extraído
  const data = buscarJuego(juegoDir);
  if (!data) {
    throw new Error(
      `Se descomprimió pero no encuentro Data/MapInfos.rxdata en ${path.relative(ROOT, juegoDir)}. ` +
        "Puede ser un parche (.ups/.ips/.xdelta) que hay que aplicar sobre un ROM base antes de analizarlo."
    );
  }
  console.log(`Juego listo: ${path.relative(ROOT, data)}`);
  console.log(`Siguiente paso: node tools/inspect_guest_rom.mjs --dir "${path.dirname(data)}" --slug ${SLUG}`);
}

