export async function renderEventsTab(view) {
  if (!S.currentMap) S.currentMap = S.tree[0]?.id;
  view.innerHTML = `<div class="wrap"><p class="muted">Cargando…</p></div>`;
  const rec = await loadMap(S.currentMap);
  if (!rec.parsed.events.length) {
    view.innerHTML = `<div class="wrap"><div class="card">
      <h3>Mapa ${S.currentMap} sin eventos</h3>
      <button class="btn" id="ev-pickmap">Cambiar de mapa</button></div></div>`;
    view.querySelector("#ev-pickmap").onclick = () => mapPickerModal("Mapa", (id) => { S.currentMap = id; S.currentEvent = null; renderEventsTab(view); });
    return;
  }
  if (!S.currentEvent || !rec.parsed.events.some((e) => e.id === S.currentEvent)) {
    S.currentEvent = rec.parsed.events[0].id;
    S.currentPage = 0;
  }
  const evObj = rec.parsed.events.find((e) => e.id === S.currentEvent).obj;
  const ev = parseEvent(evObj);
  if (S.currentPage >= ev.pages.length) S.currentPage = 0;
  const pg = ev.pages[S.currentPage];

  view.innerHTML = `
  <div class="wrap">
    <div class="card">
      <div class="row wrap">
        <button class="btn small" id="ev-map">Mapa ${S.currentMap}</button>
        <button class="btn small" id="ev-ev">Ev.${ev.id}: ${esc(ev.name)} @(${ev.x},${ev.y})</button>
        <button class="btn small primary" id="ev-save">Guardar mapa</button>
      </div>
      <div class="row wrap" style="margin-top:8px">
        <label>Nombre <input id="f-name" class="inp" value="${esc(ev.name)}" /></label>
        <label>X <input id="f-x" class="inp num" type="number" value="${ev.x}" /></label>
        <label>Y <input id="f-y" class="inp num" type="number" value="${ev.y}" /></label>
      </div>
      <div class="pagetabs">${ev.pages.map((p, i) => `<button class="chip${i === S.currentPage ? " sel" : ""}" data-pg="${i}">Pág ${i + 1}</button>`).join("")}</div>
    </div>
    <div class="card">
      <h3>Página ${S.currentPage + 1} — condiciones y aspecto</h3>
      <div class="formgrid">
        <label class="check"><input type="checkbox" id="c-sw1v" ${pg.condition?.switch1 ? "checked" : ""} /> Switch 1</label>
        <input id="c-sw1" class="inp num" type="number" min="1" value="${pg.condition?.switch1 || 1}" />
        <span class="muted small" id="c-sw1n"></span>
        <label class="check"><input type="checkbox" id="c-sw2v" ${pg.condition?.switch2 ? "checked" : ""} /> Switch 2</label>
        <input id="c-sw2" class="inp num" type="number" min="1" value="${pg.condition?.switch2 || 1}" />
        <span class="muted small" id="c-sw2n"></span>
        <label class="check"><input type="checkbox" id="c-varv" ${pg.condition?.variable ? "checked" : ""} /> Variable ≥</label>
        <span><input id="c-var" class="inp num" type="number" min="1" value="${pg.condition?.variable?.id || 1}" />
        <input id="c-varval" class="inp num" type="number" value="${pg.condition?.variable?.value || 0}" /></span>
        <span class="muted small" id="c-varn"></span>
        <label class="check"><input type="checkbox" id="c-selfv" ${pg.condition?.selfSwitch ? "checked" : ""} /> Self-switch</label>
        <select id="c-self" class="inp">${["A", "B", "C", "D"].map((l) => `<option${pg.condition?.selfSwitch === l ? " selected" : ""}>${l}</option>`).join("")}</select>
        <span></span>
      </div>
      <div class="row wrap" style="margin-top:8px">
        <label>Disparador <select id="f-trig" class="inp">${TRIGGERS.map((t, i) => `<option value="${i}"${pg.trigger === i ? " selected" : ""}>${t}</option>`).join("")}</select></label>
        <label>Movimiento <select id="f-mv" class="inp">${MOVE_TYPES.map((t, i) => `<option value="${i}"${pg.moveType === i ? " selected" : ""}>${t}</option>`).join("")}</select></label>
      </div>
      <div class="row wrap">
        ${[["walkAnime", "Anim.caminar", pg.walkAnime], ["stepAnime", "Anim.quieto", pg.stepAnime], ["dirFix", "Fijar dir.", pg.dirFix], ["through", "Atravesar", pg.through], ["alwaysTop", "Siempre arriba", pg.alwaysTop]].map(([k, l, v]) =>
          `<label class="check"><input type="checkbox" data-opt="${k}" ${v ? "checked" : ""} /> ${l}</label>`).join("")}
      </div>
      <div class="row wrap" style="margin-top:8px;align-items:flex-end">
        <canvas id="spr-prev" width="64" height="64" class="sprprev"></canvas>
        <div>
          <div class="muted small">Gráfico: <b id="spr-name">${esc(pg.graphic?.charName || "(ninguno)")}</b></div>
          <button class="btn small" id="f-spr">Cambiar sprite</button>
        </div>
        <label>Dir. <select id="f-dir" class="inp">${[[2, "↓"], [4, "←"], [6, "→"], [8, "↑"]].map(([v, l]) => `<option value="${v}"${pg.graphic?.direction === v ? " selected" : ""}>${l}</option>`).join("")}</select></label>
        <label>Paso <select id="f-pat" class="inp">${[0, 1, 2, 3].map((v) => `<option${pg.graphic?.pattern === v ? " selected" : ""}>${v}</option>`).join("")}</select></label>
      </div>
    </div>
    <div class="card">
      <div class="row" style="justify-content:space-between"><h3>Comandos</h3>
        <span><button class="btn small" id="cmd-add">+ Añadir</button></span></div>
      <div id="cmdlist"></div>
    </div>
  </div>`;

  const updSwNames = () => {
    view.querySelector("#c-sw1n").textContent = S.names.switches[Number(view.querySelector("#c-sw1").value)] || "";
    view.querySelector("#c-sw2n").textContent = S.names.switches[Number(view.querySelector("#c-sw2").value)] || "";
    view.querySelector("#c-varn").textContent = S.names.variables[Number(view.querySelector("#c-var").value)] || "";
  };
  updSwNames();
  ["#c-sw1", "#c-sw2", "#c-var"].forEach((s) => (view.querySelector(s).oninput = updSwNames));

  // preview sprite
  const paintSpr = async () => {
    try {
      const img = await FS.readImage(`Graphics/Characters/${pg.graphic.charName}.png`);
      drawCharacterPreview(view.querySelector("#spr-prev"), img, Number(view.querySelector("#f-dir").value), Number(view.querySelector("#f-pat").value));
    } catch { /* sin preview */ }
  };
  paintSpr();
  view.querySelector("#f-dir").onchange = paintSpr;
  view.querySelector("#f-pat").onchange = paintSpr;

  view.querySelector("#ev-map").onclick = () => mapPickerModal("Mapa", (id) => { S.currentMap = id; S.currentEvent = null; renderEventsTab(view); });
  view.querySelector("#ev-ev").onclick = () => eventPickerModal(S.currentMap, (id) => { S.currentEvent = id; S.currentPage = 0; renderEventsTab(view); });
  view.querySelectorAll("[data-pg]").forEach((b) => (b.onclick = () => { S.currentPage = Number(b.dataset.pg); renderEventsTab(view); }));
  view.querySelector("#f-spr").onclick = () => spritePickerModal("Sprite del NPC", pg.graphic?.charName || "", async (n) => {
    const mapId = Number(S.currentMap);
    try {
      await runUndoableEdit(`Cambiar sprite de Ev.${ev.id}`, { kind: "map", id: mapId }, () => {
        pg.graphic.obj.setIvar("character_name", RString.fromText(n));
        pg.graphic.obj.setIvar("tile_id", 0);
        markMapDirty(mapId);
      });
      dirty(); renderEventsTab(view);
    } catch (e) { toast(e.message, "error"); }
  });

  const applyAndSave = async () => {
    const mapId = Number(S.currentMap);
    try {
      await runUndoableEdit(`Editar Ev.${ev.id}`, { kind: "map", id: mapId }, async () => {
        evObj.setIvar("name", RString.fromText(view.querySelector("#f-name").value));
        evObj.setIvar("x", Number(view.querySelector("#f-x").value));
        evObj.setIvar("y", Number(view.querySelector("#f-y").value));
        const c = pg.condition?.obj;
        if (c) {
          c.setIvar("switch1_valid", view.querySelector("#c-sw1v").checked);
          c.setIvar("switch1_id", Number(view.querySelector("#c-sw1").value));
          c.setIvar("switch2_valid", view.querySelector("#c-sw2v").checked);
          c.setIvar("switch2_id", Number(view.querySelector("#c-sw2").value));
          c.setIvar("variable_valid", view.querySelector("#c-varv").checked);
          c.setIvar("variable_id", Number(view.querySelector("#c-var").value));
          c.setIvar("variable_value", Number(view.querySelector("#c-varval").value));
          c.setIvar("self_switch_valid", view.querySelector("#c-selfv").checked);
          c.setIvar("self_switch_ch", RString.fromText(view.querySelector("#c-self").value));
        }
        pg.obj.setIvar("trigger", Number(view.querySelector("#f-trig").value));
        pg.obj.setIvar("move_type", Number(view.querySelector("#f-mv").value));
        view.querySelectorAll("[data-opt]").forEach((chk) => {
          pg.obj.setIvar(chk.dataset.opt === "walkAnime" ? "walk_anime" : chk.dataset.opt === "stepAnime" ? "step_anime" : chk.dataset.opt === "dirFix" ? "direction_fix" : chk.dataset.opt === "alwaysTop" ? "always_on_top" : "through", chk.checked);
        });
        if (pg.graphic) {
          pg.graphic.obj.setIvar("direction", Number(view.querySelector("#f-dir").value));
          pg.graphic.obj.setIvar("pattern", Number(view.querySelector("#f-pat").value));
        }
        markMapDirty(mapId);
        await saveMap(mapId);
      });
      toast("Evento guardado [OK]");
      dirty();
    } catch (e) { toast(e.message, "error"); }
  };
  view.querySelector("#ev-save").onclick = applyAndSave;

  // --- lista de comandos
  const listEl = view.querySelector("#cmdlist");
  const drawCmds = () => {
    const seen = new Set();
    listEl.innerHTML = pg.list.map((o, i) => {
      const { code, indent, params } = cmdOf(o);
      const h = humanizeCommand(code, params);
      // Los diálogos ocupan un bloque (101 + 401): se dibujan una sola vez, con
      // el texto completo, para que no parezca que el texto es la "cara" del NPC.
      if (code === 101 || code === 401) {
        const block = messageBlockOf(pg.list, i);
        if (block && !seen.has(block[0].i)) {
          seen.add(block[0].i);
          for (const b of block) seen.add(b.i);
          const texto = messageTextOf(block);
          const sp = speakerOf(texto);
          const lineas = wrapMessage(sp.rest, 53);
          return `<div class="cmdrow dlg" data-i="${block[0].i}" data-dlg="1" style="margin-left:${indent * 16}px">
            <span class="mono muted">#101</span>
            <span class="cmd-t"><b>Diálogo</b>${sp.name ? ` <span class="chip-n">${esc(sp.name)}</span>` : ""}
              <span class="muted">${esc(lineas.join(" / ").slice(0, 90))}</span>
              <span class="muted small">· ${lineas.length} línea${lineas.length === 1 ? "" : "s"}${block.length > 1 ? ` · ${block.length} comandos` : ""}</span></span>
            <button class="iconbtn mini" data-mv="-1" title="Subir">▲</button>
            <button class="iconbtn mini" data-mv="1" title="Bajar">▼</button>
          </div>`;
        }
        if (block && seen.has(block[0].i) && block[0].i !== i) return ""; // continuación: ya dibujada
      }
      return `<div class="cmdrow${h.known ? "" : " unknown"}" data-i="${i}" style="margin-left:${indent * 16}px">
        <span class="mono muted">#${code}</span>
        <span class="cmd-t"><b>${esc(h.title)}</b> <span class="muted">${esc(h.detail)}</span></span>
        <button class="iconbtn mini" data-mv="-1" title="Subir">▲</button>
        <button class="iconbtn mini" data-mv="1" title="Bajar">▼</button>
      </div>`;
    }).join("");
    listEl.querySelectorAll(".cmdrow").forEach((row) => {
      row.onclick = async (e) => {
        if (e.target.dataset.mv) {
          e.stopPropagation();
          const i = Number(row.dataset.i), j = i + Number(e.target.dataset.mv);
          if (j < 0 || j >= pg.list.length) return;
          const command = cmdOf(pg.list[i]);
          try {
            await runUndoableEdit(`Mover comando #${command.code}`, { kind: "map", id: S.currentMap }, () => {
              const [it] = pg.list.splice(i, 1);
              pg.list.splice(j, 0, it);
              markMapDirty(S.currentMap);
            });
            dirty(); drawCmds();
          } catch (error) { toast(error.message, "error"); }
          return;
        }
        if (row.dataset.dlg) openDialogueEditor(view, rec, pg, Number(row.dataset.i), drawCmds);
        else openCommandEditor(view, rec, pg, Number(row.dataset.i), drawCmds);
      };
    });
  };
  drawCmds();
  view.querySelector("#cmd-add").onclick = () => openInsertMenu(view, rec, pg, drawCmds);
}

function newCmd(code, params, indent = 0) {
  return new RObject("RPG::EventCommand", [["@code", code], ["@indent", indent], ["@parameters", params]]);
}

function openInsertMenu(view, rec, pg, redraw) {
  const T = (label, make) => `<button class="pickrow" data-t="${label}">${label}</button>`;
  const wrap = document.createElement("div");
  wrap.innerHTML = `<div class="picklist">
    ${T("Texto", 0)}${T("Opciones (Sí/No)", 0)}${T("Script", 0)}${T("Comentario", 0)}
    ${T("Control switch", 0)}${T("Control variable", 0)}${T("Teletransportar", 0)}
    ${T("Condición (switch)", 0)}${T("Sonido SE", 0)}${T("Tienda", 0)}
  </div><p class="muted small">Se inserta al final (antes del Fin).</p>`;
  wrap.querySelectorAll("[data-t]").forEach((b) => {
    b.onclick = async () => {
      const cmds = [];
      const t = b.dataset.t;
      if (t.startsWith("Texto")) cmds.push(newCmd(101, [RString.fromText("Nuevo diálogo…")]));
      else if (t.startsWith("Opciones")) {
        cmds.push(newCmd(102, [[RString.fromText("Sí"), RString.fromText("No")], 4]));
        cmds.push(newCmd(402, [0, RString.fromText("Sí")], 1), newCmd(101, [RString.fromText("Elegiste SÍ")], 2), newCmd(404, [], 1));
        cmds.push(newCmd(402, [1, RString.fromText("No")], 1), newCmd(101, [RString.fromText("Elegiste NO")], 2), newCmd(404, [], 1));
        cmds.push(newCmd(404, []));
      }
      else if (t.startsWith("Script")) cmds.push(newCmd(355, [RString.fromText("pbMessage(\"Hola\")")]));
      else if (t.startsWith("Comentario")) cmds.push(newCmd(108, [RString.fromText("Nota…")]));
      else if (t.startsWith("Control switch")) cmds.push(newCmd(121, [1, 1, 1]));
      else if (t.startsWith("Control variable")) cmds.push(newCmd(122, [1, 1, 0, 0, 0]));
      else if (t.startsWith("Teletransportar")) cmds.push(newCmd(201, [0, S.currentMap, 0, 0, 2, 0]));
      else if (t.startsWith("Condición")) cmds.push(newCmd(111, [0, 1, 1]), newCmd(412, []));
      else if (t.startsWith("Sonido")) cmds.push(newCmd(247, [new RObject("RPG::AudioFile", [["@name", RString.fromText("")], ["@volume", 80], ["@pitch", 100]])]));
      else if (t.startsWith("Tienda")) cmds.push(newCmd(302, [[]]));
      let at = pg.list.length;
      if (at > 0 && Number(pg.list[at - 1].getIvar("code")) === 0) at--;
      try {
        await runUndoableEdit(`Añadir comando: ${t}`, { kind: "map", id: S.currentMap }, () => {
          pg.list.splice(at, 0, ...cmds);
          markMapDirty(S.currentMap);
        });
        dirty(); closeModal(); redraw();
        toast("Comando añadido (guarda el mapa).");
      } catch (error) { toast(error.message, "error"); }
    };
  });
  openModal({ title: "Añadir comando", body: wrap });
}

// ============================================================================
// EDITOR DE DIÁLOGO — Fire Ash guarda la primera línea en el comando 101 y el
// resto en los 401 siguientes; el motor las une con un espacio. Aquí el usuario
// edita el mensaje COMPLETO (y su caja de nombre) con vista previa de la caja
// real, así los diálogos dejan de verse partidos o a nombre del NPC equivocado.
// ============================================================================
function openDialogueEditor(view, rec, pg, index, redraw) {
  const list = pg.list;
  const block = messageBlockOf(list, index);
  if (!block) { openCommandEditor(view, rec, pg, index, redraw); return; }
  const original = messageTextOf(block);
  const sp = speakerOf(original);
  const extras = block.slice(1).filter((b) => b.obj);

  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="row wrap">
      <label>Habla (caja del nombre) <input id="dlg-who" class="inp" value="${esc(sp.name)}" placeholder="(sin nombre)" /></label>
      <label>Caja <select id="dlg-box" class="inp">
        <option value="53,2">2 líneas (normal)</option>
        <option value="53,4">4 líneas (mensaje largo)</option>
        <option value="40,2">2 líneas estrechas</option>
      </select></label>
      <button class="btn small" id="dlg-fit">Ajustar a la caja</button>
    </div>
    <textarea id="dlg-text" class="inp mono" rows="6"></textarea>
    <p class="muted small">Códigos del juego: <span class="mono">\n</span> salto de línea ·
      <span class="mono">\b</span> azul · <span class="mono">\r</span> rojo ·
      <span class="mono">\c[n]</span> color · <span class="mono">\v[n]</span> variable.
      Si escribes mucho texto, usa <b>Ajustar a la caja</b>: la caja del juego no crece sola.</p>
    <div class="dlgpreview" id="dlg-preview"></div>
    <p class="muted small" id="dlg-info"></p>`;
  const ta = wrap.querySelector("#dlg-text");
  const who = wrap.querySelector("#dlg-who");
  const sel = wrap.querySelector("#dlg-box");
  ta.value = sp.rest;

  let pagina = 0;
  const opts = () => {
    const [c, l] = sel.value.split(",").map(Number);
    return { cols: c, lines: l };
  };
  const paint = () => {
    const { cols, lines } = opts();
    const texto = ta.value;
    const paginas = [];
    const all = wrapMessage(texto, cols);
    for (let i = 0; i < all.length; i += lines) paginas.push(all.slice(i, i + lines));
    if (!paginas.length) paginas.push([""]);
    if (pagina >= paginas.length) pagina = paginas.length - 1;
    const nombre = who.value.trim();
    wrap.querySelector("#dlg-preview").innerHTML = paginas.map((pg, k) => `
      <div class="dlgframe${k === pagina ? " sel" : ""}" data-p="${k}">
        ${nombre ? `<div class="dlgname">${esc(nombre)}</div>` : `<div class="dlgname none">(sin nombre — el juego usará el del evento)</div>`}
        <div class="dlgbox">${pg.map((l) => `<div class="dlgline">${esc(l) || "&nbsp;"}</div>`).join("")}</div>
      </div>`).join("");
    wrap.querySelectorAll(".dlgframe").forEach((f) => {
      f.onclick = () => { pagina = Number(f.dataset.p); paint(); };
    });
    const largos = all.filter((l) => visibleWidth(l) > cols).length;
    wrap.querySelector("#dlg-info").textContent =
      `${all.length} línea(s) · ${paginas.length} caja(s) · ${texto.length} caracteres` +
      (largos ? ` · ⚠ ${largos} línea(s) más larga(s) que la caja` : "") +
      ` · bloque: 1 comando 101${extras.length ? ` + ${extras.length} de continuación` : ""}`;
  };
  ta.oninput = () => { pagina = 0; paint(); };
  who.oninput = paint;
  sel.onchange = () => { pagina = 0; paint(); };
  wrap.querySelector("#dlg-fit").onclick = () => {
    const { cols } = opts();
    ta.value = reflowMessage(ta.value, cols).texto;
    pagina = 0;
    paint();
  };
  paint();

  const guardar = async (close) => {
    const { cols } = opts();
    const nuevo = ta.value;
    try {
      await runUndoableEdit(`Editar diálogo (Ev.${S.currentEvent})`, { kind: "map", id: S.currentMap }, () => {
        // 1) el 101 se queda con TODO el mensaje (mismo texto que unía el motor)
        const sobrantes = applyDialogueText(block, who.value, nuevo);
        // 2) fuera los 401 que ya no hacen falta (el motor no los necesita)
        if (sobrantes) {
          const quitar = new Set(block.slice(1).map((b) => b.obj));
          for (let i = list.length - 1; i >= 0; i--) if (quitar.has(list[i])) list.splice(i, 1);
        }
        markMapDirty(S.currentMap);
      });
      dirty();
      close();
      redraw();
      const { lines } = opts();
      const largas = wrapMessage(nuevo, cols).filter((l) => visibleWidth(l) > cols).length;
      toast(largas ? `Diálogo guardado (${largas} línea(s) se salen de la caja)` : "Diálogo guardado [OK]");
    } catch (e) { toast(e.message, "error"); }
  };

  openModal({
    title: `Diálogo del evento ${S.currentEvent}`,
    body: wrap,
    wide: true,
    actions: [
      { label: "Cancelar", onClick: (close) => close() },
      { label: "Guardar diálogo", cls: "primary", onClick: (close) => guardar(close) },
    ],
  });
}

function openCommandEditor(view, rec, pg, index, redraw) {
  const o = pg.list[index];
  const { code, params } = cmdOf(o);
  const h = humanizeCommand(code, params);
  const strings = getCommandStrings(code, params);
  let body;
  if (strings.length) {
    body = document.createElement("div");
    body.innerHTML = `<p class="muted">#${code} · ${esc(h.title)} — edita el texto (soporta saltos con <span class="mono">\\n</span> en diálogos):</p>` +
      strings.map((s, k) => `<textarea class="inp mono" rows="${code === 355 || code === 655 ? 4 : 2}" data-k="${k}">${esc(s.rs.text)}</textarea>`).join("");
  } else {
    body = document.createElement("div");
    body.innerHTML = `<p class="muted">#${code} · <b>${esc(h.title)}</b> ${esc(h.detail)}<br/>Edición avanzada (JSON). Los textos van como <span class="mono">{"$str":"…"}</span>. Si lo rompes, restaura desde Mods → Backups.</p>
      <textarea class="inp mono" rows="8" id="cmd-json">${esc(JSON.stringify(paramsToJson(params), null, 1))}</textarea>`;
  }
  openModal({
    title: `Comando #${code}: ${h.title}`,
    body, wide: true,
    actions: [
      { label: "Eliminar", cls: "danger", onClick: async (close) => {
        if (pg.list.length <= 1) { toast("No puedes borrar el único comando.", "error"); return; }
        if (await confirmDialog("Eliminar comando", "¿Borrar este comando? (se guarda con el mapa)")) {
          try {
            await runUndoableEdit(`Eliminar comando #${code}`, { kind: "map", id: S.currentMap }, () => {
              pg.list.splice(index, 1);
              markMapDirty(S.currentMap);
            });
            dirty(); close(); redraw();
          } catch (error) { toast(error.message, "error"); }
        }
      } },
      { label: "Guardar", cls: "primary", onClick: async (close) => {
        try {
          await runUndoableEdit(`Editar comando #${code}`, { kind: "map", id: S.currentMap }, () => {
            if (strings.length) {
              body.querySelectorAll("textarea").forEach((ta) => {
                strings[Number(ta.dataset.k)].rs.text = ta.value;
              });
            } else {
              let j;
              try { j = JSON.parse(body.querySelector("#cmd-json").value); }
              catch (error) { throw new Error("JSON inválido: " + error.message); }
              o.setIvar("parameters", jsonToParams(j));
            }
            markMapDirty(S.currentMap);
          });
          dirty(); close(); redraw();
          toast("Comando actualizado (guarda el mapa).");
        } catch (e) { toast(e.message, "error"); }
      } },
    ],
  });
}

function paramsToJson(params) {
  const toJ = (v) => {
    if (v instanceof RString) return { $str: v.text };
    if (v instanceof RSymbol) return { $sym: v.name };
    if (v instanceof RFloat) return { $float: v.raw };
    if (Array.isArray(v)) return v.map(toJ);
    if (v instanceof RObject) { const o = { $obj: v.className }; for (const [k, val] of v.ivars) o[k] = toJ(val); return o; }
    if (v instanceof RHash) return { $hash: v.pairs.map(([k, val]) => [toJ(k), toJ(val)]) };
    return v;
  };
  return params.map(toJ);
}
function jsonToParams(j) {
  const fromJ = (x) => {
    if (x && typeof x === "object") {
      if (Array.isArray(x)) return x.map(fromJ);
      if ("$str" in x) return RString.fromText(String(x.$str));
      if ("$sym" in x) return new RSymbol(String(x.$sym));
      if ("$float" in x) return new RFloat(parseFloat(x.$float), String(x.$float));
      if ("$hash" in x) return new RHash(x.$hash.map(([k, v]) => [fromJ(k), fromJ(v)]));
      if ("$obj" in x) { const o = new RObject(x.$obj); for (const k of Object.keys(x)) if (k !== "$obj") o.ivars.push([k, fromJ(x[k])]); return o; }
    }
    return x;
  };
  return j.map(fromJ);
}

// ============================================================================
// FLAGS (interruptores y variables)
// ============================================================================
let flagKind = "sw";
export function renderFlagsTab(view, { goTab }) {
  const names = flagKind === "sw" ? S.names.switches : S.names.variables;
  view.innerHTML = `
  <div class="wrap">
    <div class="card">
      <div class="row">
        <button class="chip${flagKind === "sw" ? " sel" : ""}" id="fk-sw">Interruptores</button>
        <button class="chip${flagKind === "var" ? " sel" : ""}" id="fk-var">Variables</button>
      </div>
      <p class="muted small">Los <b>nombres</b> viven en el juego (editables). Los <b>valores ON/OFF</b> viven en tu partida (PokeMod no toca partidas).</p>
      <input id="flag-search" class="inp" placeholder="Buscar por nombre o número…" />
      <div id="flag-list"></div>
    </div>
  </div>`;
  view.querySelector("#fk-sw").onclick = () => { flagKind = "sw"; renderFlagsTab(view, { goTab }); };
  view.querySelector("#fk-var").onclick = () => { flagKind = "var"; renderFlagsTab(view, { goTab }); };
  const listEl = view.querySelector("#flag-list");
  const draw = (filter = "") => {
    const f = filter.trim().toLowerCase();
    const rows = [];
    const max = Math.min(names.length - 1, 5000);
    for (let i = 1; i <= max && rows.length < 400; i++) {
      const n = names[i] || "";
      if (f && !n.toLowerCase().includes(f) && String(i) !== f && !String(i).includes(f)) continue;
      rows.push(`<div class="flagrow">
        <span class="mono muted">${i}</span>
        <input class="inp" data-id="${i}" value="${esc(n)}" placeholder="(sin nombre)" />
        <button class="btn small" data-uses="${i}">Usos</button>
      </div>`);
    }
    listEl.innerHTML = rows.join("") || `<p class="muted">Sin resultados.</p>`;
    listEl.querySelectorAll("input[data-id]").forEach((inp) => {
      inp.onchange = async () => {
        const id = Number(inp.dataset.id);
        const kind = flagKind === "sw" ? "Interruptor" : "Variable";
        try {
          await runUndoableEdit(`Renombrar ${kind} ${id}`, { kind: "system" }, async () => {
            setSystemName(S.systemObj, flagKind, id, inp.value);
            await saveSystem();
          });
          toast("Nombre guardado [OK]");
        } catch (e) { toast(e.message, "error"); }
      };
    });
    listEl.querySelectorAll("[data-uses]").forEach((b) => {
      b.onclick = () => showFlagUses(Number(b.dataset.uses), goTab);
    });
  };
  view.querySelector("#flag-search").oninput = debounce((e) => draw(e.target.value), 200);
  draw();
}

async function showFlagUses(id, goTab) {
  const prog = showProgress(`Buscando usos de ${flagKind === "sw" ? "Switch" : "Variable"}[${id}]…`);
  const results = await scanAllMaps((mapId, parsed, info) => {
    const uses = findFlagUsesInMap(parsed, flagKind, id);
    return uses.map((u) => ({ mapId, mapName: info?.name || "", ...u }));
  }, (i, total, m) => prog.update(i, total, `Mapa ${i}/${total}: ${m.name}`));
  prog.close();
  if (!results.length) { toast("Sin usos en eventos (puede usarse en scripts)."); return; }
  const wrap = document.createElement("div");
  wrap.innerHTML = `<div class="picklist">${results.slice(0, 500).map((r, k) =>
    `<button class="pickrow" data-k="${k}"><span class="mono muted">${r.mapId}</span><span>${esc(r.mapName)} · Ev.${r.evId} ${esc(r.evName)} · Pág ${r.page + 1}</span><span class="muted">${esc(r.where)}</span></button>`).join("")}</div>
    ${results.length > 500 ? `<p class="muted">…${results.length - 500} más</p>` : ""}`;
  wrap.querySelectorAll(".pickrow").forEach((b) => {
    b.onclick = () => {
      const r = results[Number(b.dataset.k)];
      S.currentMap = r.mapId;
      // buscar id de evento por nombre+id
      S.currentEvent = r.evId; S.currentPage = r.page;
      closeModal(); goTab("events");
    };
  });
  openModal({ title: `${results.length} usos`, body: wrap, wide: true });
}

// ============================================================================
// NPCS
// ============================================================================
let npcCache = [];
export function renderNpcsTab(view, { goTab }) {
  view.innerHTML = `
  <div class="wrap"><div class="card">
    <h3>Todos los NPCs del juego</h3>
    <p class="muted small">Escanea todos los mapas y lista cada evento con gráfico. Toca uno para moverlo o cambiar su sprite.</p>
    <div class="row"><button class="btn primary" id="npc-scan">Escanear mapas</button>
    <input id="npc-search" class="inp" placeholder="Filtrar…" style="flex:1" /></div>
    <div id="npc-list"></div>
  </div></div>`;
  const listEl = view.querySelector("#npc-list");
  let npcDrawToken = 0;
  const draw = (filter = "") => {
    const f = filter.trim().toLowerCase();
    const token = ++npcDrawToken;
    const rows = npcCache.filter((n) => !f || n.name.toLowerCase().includes(f) || n.charName.toLowerCase().includes(f) || n.mapName.toLowerCase().includes(f) || String(n.mapId) === f);
    const visibles = rows.slice(0, 250);
    // Se rellena una sola vez: con `innerHTML +=` el navegador volvía a construir
    // toda la lista y las previsualizaciones asíncronas podían acabar pintando en
    // filas de otra búsqueda (filas duplicadas o «solapadas» en la pestaña NPCs).
    listEl.innerHTML = "";
    const frag = document.createDocumentFragment();
    if (!visibles.length) {
      const p = document.createElement("p");
      p.className = "muted";
      p.textContent = npcCache.length ? "Sin coincidencias." : "Pulsa «Escanear mapas».";
      frag.appendChild(p);
    }
    for (const n of visibles) {
      const b = document.createElement("button");
      b.className = "npcrow";
      b.dataset.k = String(npcCache.indexOf(n));
      b.innerHTML = `<canvas width="40" height="40" data-spr="${esc(n.charName)}"></canvas>
        <span><b>${esc(n.name)}</b> <span class="muted">Ev.${n.evId} · Mapa ${n.mapId} ${esc(n.mapName)} · (${n.x},${n.y})</span></span>`;
      b.onclick = () => openNpcEditor(npcCache[Number(b.dataset.k)], goTab);
      frag.appendChild(b);
    }
    if (rows.length > visibles.length) {
      const p = document.createElement("p");
      p.className = "muted";
      p.textContent = `…${rows.length - visibles.length} más (filtra)`;
      frag.appendChild(p);
    }
    listEl.appendChild(frag);
    // previews (solo de la lista actual: si el usuario vuelve a buscar, se cortan)
    listEl.querySelectorAll("canvas[data-spr]").forEach(async (cv) => {
      const n = cv.dataset.spr;
      if (!n || esInvisible(n)) return;
      try {
        const img = await FS.readImage(`Graphics/Characters/${n}.png`);
        if (token !== npcDrawToken || !cv.isConnected) return;
        drawCharacterPreview(cv, img, 2, 1);
      } catch { /* sin vista previa */ }
    });
  };
  view.querySelector("#npc-search").oninput = debounce((e) => draw(e.target.value), 200);
  view.querySelector("#npc-scan").onclick = async () => {
    const prog = showProgress("Escaneando NPCs…");
    npcCache = await scanAllMaps((mapId, parsed, info) => {
      const out = [];
      for (const { id, obj } of parsed.events) {
        try {
          const ev = parseEvent(obj);
          const g = ev.pages[0]?.graphic;
          if (g && (g.charName || g.tileId)) {
            out.push({ mapId, mapName: info?.name || "", evId: id, name: ev.name, x: ev.x, y: ev.y, charName: g.charName || "", tileId: g.tileId, dir: g.direction, pat: g.pattern });
          }
        } catch { /* noop */ }
      }
      return out;
    }, (i, total, m) => prog.update(i, total, `Mapa ${i}/${total}`));
    prog.close();
    toast(`${npcCache.length} NPCs encontrados [OK]`);
    draw(view.querySelector("#npc-search").value);
  };
  draw();
}

async function openNpcEditor(n, goTab) {
  const rec = await loadMap(n.mapId);
  const evObj = rec.parsed.events.find((e) => e.id === n.evId)?.obj;
  if (!evObj) { toast("Evento no encontrado (¿mapa cambiado?)", "error"); return; }
  const ev = parseEvent(evObj);
  const pg = ev.pages[0];
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="row"><canvas id="npc-prev" width="72" height="72" class="sprprev"></canvas>
    <div><b>${esc(n.name)}</b><div class="muted small">Mapa ${n.mapId} · Ev.${n.evId}</div>
    <button class="btn small" id="npc-spr">Cambiar sprite</button></div></div>
    <div class="row wrap" style="margin-top:8px">
      <label>Nombre <input id="npc-name" class="inp" value="${esc(ev.name)}" /></label>
      <label>X <input id="npc-x" class="inp num" type="number" value="${ev.x}" /></label>
      <label>Y <input id="npc-y" class="inp num" type="number" value="${ev.y}" /></label>
      <label>Dir. <select id="npc-dir" class="inp">${[[2, "↓"], [4, "←"], [6, "→"], [8, "↑"]].map(([v, l]) => `<option value="${v}"${pg.graphic?.direction === v ? " selected" : ""}>${l}</option>`).join("")}</select></label>
    </div>`;
  const paint = async () => {
    try {
      const img = await FS.readImage(`Graphics/Characters/${pg.graphic.charName}.png`);
      drawCharacterPreview(wrap.querySelector("#npc-prev"), img, Number(wrap.querySelector("#npc-dir").value), 1);
    } catch { /* noop */ }
  };
  paint();
  wrap.querySelector("#npc-dir").onchange = paint;
  wrap.querySelector("#npc-spr").onclick = () => spritePickerModal("Sprite", pg.graphic?.charName || "", async (s) => {
    try {
      await runUndoableEdit(`Cambiar sprite de Ev.${n.evId}`, { kind: "map", id: n.mapId }, () => {
        pg.graphic.obj.setIvar("character_name", RString.fromText(s));
        pg.graphic.obj.setIvar("tile_id", 0);
        markMapDirty(n.mapId);
      });
      dirty(); paint();
    } catch (error) { toast(error.message, "error"); }
  });
  openModal({
    title: "Editar NPC", body: wrap,
    actions: [
      { label: "Ir al evento", onClick: (close) => { S.currentMap = n.mapId; S.currentEvent = n.evId; S.currentPage = 0; close(); goTab("events"); } },
      { label: "Guardar", cls: "primary", onClick: async (close) => {
        try {
          await runUndoableEdit(`Editar NPC Ev.${n.evId}`, { kind: "map", id: n.mapId }, async () => {
            evObj.setIvar("name", RString.fromText(wrap.querySelector("#npc-name").value));
            evObj.setIvar("x", Number(wrap.querySelector("#npc-x").value));
            evObj.setIvar("y", Number(wrap.querySelector("#npc-y").value));
            pg.graphic.obj.setIvar("direction", Number(wrap.querySelector("#npc-dir").value));
            markMapDirty(n.mapId);
            await saveMap(n.mapId);
          });
          toast("NPC guardado [OK]");
          dirty(); close();
          n.name = wrap.querySelector("#npc-name").value;
          n.x = Number(wrap.querySelector("#npc-x").value);
          n.y = Number(wrap.querySelector("#npc-y").value);
        } catch (e) { toast(e.message, "error"); }
      } },
    ],
  });
}

// ============================================================================
// POKEMON (PBS)
// ============================================================================
let pbsCurrent = "";
export async function renderPbsTab(view) {
  if (!S.pbsFiles.length) {
    view.innerHTML = `<div class="wrap"><div class="card"><h3>Sin PBS</h3><p class="muted">No se encontró carpeta PBS/ en este proyecto.</p></div></div>`;
    return;
  }
  if (!pbsCurrent || !S.pbsFiles.includes(pbsCurrent)) {
    pbsCurrent = S.pbsFiles.find((f) => /pokemon\.txt$/i.test(f)) || S.pbsFiles[0];
  }
  const rec = await loadPBS(pbsCurrent);
  const schema = schemaFor(pbsCurrent);
  const sections = pbsSections(rec.lines);
  view.innerHTML = `
  <div class="wrap"><div class="card">
    <h3>${esc(schema?.label || "PBS")}</h3>
    <div class="row wrap">
      <select id="pbs-file" class="inp">${S.pbsFiles.map((f) => `<option${f === pbsCurrent ? " selected" : ""}>${f}</option>`).join("")}</select>
      <button class="btn small primary" id="pbs-save">Guardar</button>
    </div>
    ${schema?.rawHint ? `<p class="muted small">${esc(schema.rawHint)}</p>` : ""}
    <input id="pbs-search" class="inp" placeholder="Buscar sección…" />
    <div id="pbs-list"></div>
  </div></div>`;
  view.querySelector("#pbs-file").onchange = (e) => { pbsCurrent = e.target.value; renderPbsTab(view); };
  view.querySelector("#pbs-save").onclick = async () => {
    const rel = pbsCurrent;
    try {
      await runUndoableEdit(`Editar ${rel}`, { kind: "pbs", path: rel }, async () => {
        collectPbsForm(view, rec);
        await savePBS(rel);
      });
      toast("PBS guardado [OK]"); dirty();
    } catch (e) { toast(e.message, "error"); }
  };
  const listEl = view.querySelector("#pbs-list");
  const draw = (filter = "") => {
    const f = filter.trim().toLowerCase();
    const secs = sections.filter((s) => !f || s.toLowerCase().includes(f)).slice(0, 120);
    if (schema?.fields?.length) {
      listEl.innerHTML = secs.map((s) => `
        <details class="pbssec" data-sec="${esc(s)}">
          <summary><b>${esc(s)}</b> <span class="muted">${esc(pbsGet(rec.lines, s, "Name") || "")}</span></summary>
          <div class="formgrid">
            ${schema.fields.map(([k, label, type, opts]) => {
              const v = pbsGet(rec.lines, s, k) ?? "";
              if (type === "select") return `<label>${esc(label)}</label><select class="inp" data-k="${esc(k)}"><option value="">(igual)</option>${opts.map((o) => `<option${o === v ? " selected" : ""}>${o}</option>`).join("")}</select><span></span>`;
              return `<label>${esc(label)}</label><input class="inp${type === "number" ? " num" : ""}" data-k="${esc(k)}" value="${esc(v)}" /><span class="muted small mono">${esc(k)}</span>`;
            }).join("")}
          </div>
        </details>`).join("") || `<p class="muted">Sin resultados.</p>`;
    } else {
      // modo crudo por sección
      listEl.innerHTML = secs.map((s) => {
        const body = rec.lines.filter((l) => l.section === s && l.kind !== "section").map((l) => l.kind === "kv" ? `${l.key} = ${l.value}` : l.raw).join("\n");
        return `<details class="pbssec" data-sec="${esc(s)}"><summary><b>[${esc(s)}]</b></summary>
          <textarea class="inp mono" rows="10" data-raw="${esc(s)}">${esc(body)}</textarea></details>`;
      }).join("") || `<p class="muted">Sin resultados.</p>`;
    }
    if (sections.length > 120 && !f) listEl.innerHTML += `<p class="muted">Mostrando 120 de ${sections.length} (filtra para ver más).</p>`;
  };
  view.querySelector("#pbs-search").oninput = debounce(async (e) => {
    const filter = e.target.value;
    try {
      await runUndoableEdit(`Editar ${pbsCurrent}`, { kind: "pbs", path: pbsCurrent }, () => collectPbsForm(view, rec));
      draw(filter);
    } catch (error) { toast(error.message, "error"); }
  }, 300);
  draw();
  // avisos de validación
  const issues = lintPBS(pbsCurrent, pbsToText(rec.lines));
  if (issues.length) {
    const d = document.createElement("div");
    d.className = "card";
    d.innerHTML = `<h3>[!] Revisión</h3>${issues.slice(0, 30).map((i) => `<div class="logrow ${i.level}">${esc(i.msg)}</div>`).join("")}`;
    view.querySelector(".wrap").appendChild(d);
  }
}

function collectPbsForm(view, rec) {
  // formularios con data-k dentro de details[data-sec]
  view.querySelectorAll("details.pbssec").forEach((det) => {
    const sec = det.dataset.sec;
    det.querySelectorAll("[data-k]").forEach((inp) => {
      if (inp.value !== "") pbsSet(rec.lines, sec, inp.dataset.k, inp.value);
    });
    const raw = det.querySelector("[data-raw]");
    if (raw) {
      // reconstruir sección desde crudo
      const other = rec.lines.filter((l) => l.section !== sec);
      const secIdx = other.findIndex((l) => l.kind === "section" && l.section === sec);
      const fresh = parsePBS(`[${sec}]\n` + raw.value).filter((l) => !(l.kind === "section"));
      if (secIdx >= 0) {
        // insertar tras la cabecera existente en `other`… (other ya no tiene la sección)
        other.push({ kind: "section", section: sec, raw: `[${sec}]` }, ...fresh.map((l) => ({ ...l, section: sec })));
        rec.lines.length = 0;
        rec.lines.push(...other);
      }
    }
  });
  rec.dirty = true;
  dirty();
}

// ============================================================================
// MODS (backups, Kirin, Sala, Scripts, exportar)
// ============================================================================
export function renderModsTab(view, { goTab }) {
  view.innerHTML = `
  <div class="wrap">
    <div class="card">
      <h3>Compatibilidad Kirin / Android</h3>
      <p class="muted small">Revisa estructura, cifrado, audio, caja de archivos y partidas.</p>
      <div class="row"><button class="btn primary" id="m-kirin">Chequeo rápido</button>
      <button class="btn" id="m-kirin-deep">Análisis profundo (tarda)</button></div>
      <div id="kirin-out"></div>
    </div>
    <div class="card">
      <h3>Sala PokeMod — acceso total a mapas</h3>
      <p class="muted small">Crea un mapa extra con una casilla por cada mapa del juego + una puerta en el mapa que elijas. <b>100% datos</b> (sin scripts), funciona en Kirin y es <b>reversible</b>. No toca partidas.</p>
      <div id="sala-status" class="muted small"></div>
      <div class="row wrap">
        <button class="btn small" id="sala-map">Mapa puerta: <b id="sala-mapn">${S.currentMap || S.tree[0]?.id}</b></button>
        <label>X <input id="sala-x" class="inp num" type="number" value="5" /></label>
        <label>Y <input id="sala-y" class="inp num" type="number" value="5" /></label>
        <button class="btn small" id="sala-spr">Sprite puerta</button>
      </div>
      <div class="row" style="margin-top:8px"><button class="btn primary" id="sala-build">Crear Sala PokeMod</button>
      <button class="btn danger" id="sala-un">Desinstalar</button></div>
      <div id="sala-out"></div>
    </div>
    <div class="card">
      <h3>Copias de seguridad</h3>
      <p class="muted small">PokeMod respalda automáticamente cada archivo antes de modificarlo. Aquí puedes respaldar o restaurar.</p>
      <div class="row"><button class="btn" id="bk-now">Backup ahora</button>
      <button class="btn" id="bk-list">Ver backups</button></div>
      <div id="bk-out"></div>
    </div>
    <div class="card">
      <h3>Scripts (avanzado)</h3>
      <p class="muted small">Ver/exportar/importar secciones de <span class="mono">Scripts.rxdata</span>. Solo para usuarios avanzados (siempre con backup).</p>
      <div class="row"><button class="btn" id="sc-load">Cargar scripts</button></div>
      <div id="sc-out"></div>
    </div>
    <div class="card">
      <h3>Exportar cambios</h3>
      <p class="muted small">Descarga un ZIP con los archivos modificados (para modo lectura o compartir).</p>
      <button class="btn" id="m-exp">Exportar ZIP</button>
    </div>
  </div>`;

  // --- Kirin
  const kOut = view.querySelector("#kirin-out");
  const runKirin = async (deep) => {
    kOut.innerHTML = `<p class="muted">Analizando…</p>`;
    const prog = deep ? showProgress("Análisis profundo…") : null;
    try {
      const res = await kirinCheck(deep, prog ? (i, t, m) => prog.update(i, t, `Mapa ${i}/${t}`) : null);
      if (prog) prog.close();
      kOut.innerHTML = res.map((r) => `<div class="logrow ${r.level}">${r.level === "ok" ? "[OK]" : r.level === "error" ? "[X]" : r.level === "warn" ? "[!]" : "[i]"} ${esc(r.msg)}</div>`).join("");
    } catch (e) { if (prog) prog.close(); kOut.innerHTML = `<p class="error">${esc(e.message)}</p>`; }
  };
  view.querySelector("#m-kirin").onclick = () => runKirin(false);
  view.querySelector("#m-kirin-deep").onclick = () => runKirin(true);

  // --- Sala
  let salaEntry = S.currentMap || S.tree[0]?.id || 1;
  let salaSpr = "";
  FS.readText("PokeModBackups/sala_meta.json").then((t) => {
    const m = JSON.parse(t);
    view.querySelector("#sala-status").innerHTML = `[OK] Instalada: mapa <b>${m.newId}</b> con ${m.targets} destinos (puerta en mapa ${m.entryId}).`;
  }).catch(() => { view.querySelector("#sala-status").textContent = "No instalada."; });
  view.querySelector("#sala-map").onclick = () => mapPickerModal("Mapa de la puerta", (id) => {
    salaEntry = id; view.querySelector("#sala-mapn").textContent = id;
  });
  view.querySelector("#sala-spr").onclick = () => spritePickerModal("Sprite de la puerta", salaSpr, (n) => {
    salaSpr = n; view.querySelector("#sala-spr").innerHTML = `${esc(n || "(invisible)")}`;
  });
  view.querySelector("#sala-build").onclick = async () => {
    const out = view.querySelector("#sala-out");
    const prog = showProgress("Creando Sala PokeMod…");
    try {
      const meta = await buildSalaMod({
        entryMapId: salaEntry,
        doorX: Number(view.querySelector("#sala-x").value),
        doorY: Number(view.querySelector("#sala-y").value),
        doorGraphic: salaSpr,
        onProgress: (i, t) => prog.update(i, t, `Buscando destinos ${i}/${t}`),
      });
      prog.close();
      out.innerHTML = `<p>[OK] Sala creada: mapa <b>${meta.newId}</b> (${meta.targets} destinos, ${meta.omitted.length} omitidos).</p>`;
      toast("Sala PokeMod lista");
    } catch (e) { prog.close(); out.innerHTML = `<p class="error">${esc(e.message)}</p>`; }
  };
  view.querySelector("#sala-un").onclick = async () => {
    if (!await confirmDialog("Desinstalar Sala", "¿Quitar la puerta y borrar el mapa de la Sala PokeMod?")) return;
    try { await uninstallSalaMod(); toast("Sala desinstalada [OK]"); renderModsTab(view, { goTab }); }
    catch (e) { toast(e.message, "error"); }
  };

  // --- Backups
  view.querySelector("#bk-now").onclick = async () => {
    try { const f = await backupNow(); toast("Backup en " + f + " [OK]"); } catch (e) { toast(e.message, "error"); }
  };
  view.querySelector("#bk-list").onclick = async () => {
    const out = view.querySelector("#bk-out");
    const folders = await listBackups();
    if (!folders.length) { out.innerHTML = `<p class="muted">Aún no hay backups.</p>`; return; }
    out.innerHTML = folders.map((f) => `<div class="flagrow"><span class="mono">${esc(f)}</span>
      <button class="btn small" data-bk="${esc(f)}">Ver / restaurar</button></div>`).join("");
    out.querySelectorAll("[data-bk]").forEach((b) => (b.onclick = () => openBackupFolder(b.dataset.bk)));
  };

  // --- Scripts
  view.querySelector("#sc-load").onclick = () => openScripts(view);

  // --- Export
  view.querySelector("#m-exp").onclick = async () => {
    try { await exportChangesZip(); } catch (e) { toast(e.message, "error"); }
  };
}

async function openBackupFolder(folder) {
  const files = await FS.walk(`PokeModBackups/${folder}`, 5000).catch(() => []);
  const wrap = document.createElement("div");
  wrap.innerHTML = `<div class="picklist">${files.map((f) => {
    const rel = f.replace(`PokeModBackups/${folder}/`, "");
    return `<div class="flagrow"><span class="mono small">${esc(rel)}</span><button class="btn small" data-r="${esc(rel)}">↩ Restaurar</button></div>`;
  }).join("") || "<p class=muted>Vacío.</p>"}</div>`;
  wrap.querySelectorAll("[data-r]").forEach((b) => {
    b.onclick = async () => {
      try { await restoreBackup(folder, b.dataset.r); toast("Restaurado [OK]"); }
      catch (e) { toast(e.message, "error"); }
    };
  });
  openModal({
    title: `Backup ${folder}`, body: wrap, wide: true,
    actions: [{ label: "Restaurar TODO", cls: "danger", onClick: async (close) => {
      if (!await confirmDialog("Restaurar todo", `¿Sobrescribir ${files.length} archivos con este backup?`)) return;
      for (const f of files) {
        try { await restoreBackup(folder, f.replace(`PokeModBackups/${folder}/`, "")); } catch (e) { toast(e.message, "error"); }
      }
      close(); toast("Backup restaurado [OK]");
    } }],
  });
}

let scriptsCache = null;
async function openScripts(view) {
  const out = view.querySelector("#sc-out");
  out.innerHTML = `<p class="muted">Cargando Scripts.rxdata…</p>`;
  try {
    if (!scriptsCache) {
      const raw = marshalLoad(await FS.readBytes("Data/Scripts.rxdata"));
      scriptsCache = raw.map((s) => ({ id: s[0], name: s[1]?.text ?? "?", code: s[2], obj: s, dirty: false }));
    }
    out.innerHTML = `<input id="sc-search" class="inp" placeholder="Buscar sección…" /><div id="sc-list" class="picklist" style="max-height:300px"></div>
      <div class="row" style="margin-top:8px"><button class="btn small primary" id="sc-save">Guardar Scripts.rxdata</button></div>`;
    const list = out.querySelector("#sc-list");
    const draw = (f = "") => {
      const fl = f.trim().toLowerCase();
      const items = scriptsCache.filter((s) => !fl || s.name.toLowerCase().includes(fl) || String(s.id) === fl).slice(0, 200);
      list.innerHTML = items.map((s) => `<div class="flagrow"><span class="mono muted">${s.id}</span><span>${esc(s.name)}</span>
        <span class="muted small">${fmtBytes(s.code.bytes.length)}</span>
        <button class="btn small" data-v="${s.id}">Ver</button><button class="btn small" data-e="${s.id}">↓</button><button class="btn small" data-i="${s.id}">↑</button></div>`).join("");
      list.querySelectorAll("[data-v]").forEach((b) => (b.onclick = () => viewScript(Number(b.dataset.v))));
      list.querySelectorAll("[data-e]").forEach((b) => (b.onclick = () => exportScript(Number(b.dataset.e))));
      list.querySelectorAll("[data-i]").forEach((b) => (b.onclick = () => importScript(Number(b.dataset.i))));
    };
    out.querySelector("#sc-search").oninput = debounce((e) => draw(e.target.value), 200);
    draw();
    out.querySelector("#sc-save").onclick = async () => {
      const arr = scriptsCache.map((s) => s.obj);
      await FS.writeBytes("Data/Scripts.rxdata", marshalDump(arr));
      toast("Scripts guardados [OK] (con backup)");
    };
  } catch (e) { out.innerHTML = `<p class="error">${esc(e.message)}</p>`; }
}

async function viewScript(id) {
  const s = scriptsCache.find((x) => x.id === id);
  try {
    const code = new TextDecoder().decode(await zlibInflate(s.code.bytes));
    const wrap = document.createElement("div");
    wrap.innerHTML = `<p class="muted">${code.split("\n").length} líneas · solo lectura (usa ↓/↑ para editar fuera)</p>
      <textarea class="inp mono" rows="16" readonly>${esc(code.slice(0, 60000))}</textarea>`;
    openModal({ title: `#${s.id} ${s.name}`, body: wrap, wide: true });
  } catch (e) { toast(e.message, "error"); }
}

async function exportScript(id) {
  const s = scriptsCache.find((x) => x.id === id);
  try {
    const code = new TextDecoder().decode(await zlibInflate(s.code.bytes));
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([code], { type: "text/plain" }));
    a.download = `${String(s.id).padStart(3, "0")}_${s.name}.rb`;
    a.click();
  } catch (e) { toast(e.message, "error"); }
}

function importScript(id) {
  const s = scriptsCache.find((x) => x.id === id);
  const inp = document.createElement("input");
  inp.type = "file";
  inp.accept = ".rb,.txt";
  inp.onchange = async () => {
    const f = inp.files[0];
    if (!f) return;
    if (!await confirmDialog("Importar script", `¿Reemplazar la sección #${s.id} ${s.name} con ${f.name}? (se guarda con backup)`)) return;
    try {
      const text = await f.text();
      s.code.bytes = await zlibDeflate(new TextEncoder().encode(text));
      s.dirty = true;
      toast("Sección importada (pulsa Guardar Scripts) [OK]");
    } catch (e) { toast(e.message, "error"); }
  };
  inp.click();
}// ============================================================================
// fs.js — Acceso a los archivos del juego (4 modos)
// ----------------------------------------------------------------------------
// 1) android  → la APK expone la carpeta del juego (SAF) vía PokeModBridge.
// 2) browser  → File System Access API (Chrome/Edge escritorio).
// 3) fallback→ <input webkitdirectory> (solo lectura) + exportar cambios en ZIP.
// 4) demo    → proyecto procedural en memoria (para probar sin el juego).
//
// TODAS las escrituras pasan por writeBytes(), que:
//   a) rechaza tocar partidas guardadas (Save*, Game.rxdata, *.sav),
//   b) avisa a onBeforeWrite para copia de seguridad automática.
// ============================================================================
import { bytesToBase64, base64ToBytes } from "./util.js";

// --- Archivos PROTEGIDOS: nunca se escriben ni borran ------------------------------
// (Partidas de Essentials/RMXP y nuestros propios backups.)
export const PROTECTED = [
  /^save[\s_.-]*\d*\.rxdata$/i,
  /^game\.rxdata$/i,
  /\.sav$/i,
  /^pokemodbackups\//i,
  /\.bak$/i,
];

export function isProtected(rel) {
  const n = rel.replace(/\\/g, "/").replace(/^\.\//, "");
  const base = n.split("/").pop();
  return PROTECTED.some((re) => re.test(base) || re.test(n));
}

export function normalizeRel(p) {
  return String(p).replace(/\\/g, "/").replace(/^\.\//, "").replace(/^\/+/, "");
}

// --- API -----------------------------------------------------------------------
export const FS = {
  mode: "none",
  folderName: "",
  onBeforeWrite: null, // async (rel, newBytes) => void — backup automático
  pendingWrites: new Map(), // fallback/demo: rel -> Uint8Array pendiente
  pendingDeletes: new Set(), // fallback: rels borrados pendientes
  _backupMem: new Map(), // fallback: backups en memoria (PokeModBackups/...)
  _handles: new Map(), // browser: path dir -> handle
  _files: new Map(), // fallback: rel -> File
  _mem: new Map(), // demo: rel -> Uint8Array
  _imgCache: new Map(),
  _indexLower: null, // índice minúsculas → ruta real

  reset() {
    this.mode = "none";
    this.folderName = "";
    this._handles.clear();
    this._files.clear();
    this._mem.clear();
    this._imgCache.clear();
    this._indexLower = null;
    this.pendingWrites.clear();
    this.pendingDeletes.clear();
    this._backupMem.clear();
  },

  get isAndroid() { return typeof window !== "undefined" && !!window.PokeModBridge; },
  get canWrite() { return this.mode === "android" || this.mode === "browser" || this.mode === "demo"; },

  // -- Conexión ------------------------------------------------------------------
  async connectAndroid() {
    const b = window.PokeModBridge;
    if (!b) throw new Error("Sin puente Android");
    const has = await this._bridge("pmHasFolder");
    if (has !== "1") {
      const name = await this._pickAndroidFolder();
      if (!name) throw new Error("No se eligió carpeta");
    }
    this.mode = "android";
    this.folderName = await this._bridge("pmFolderName");
    await this.rebuildIndex();
  },

  _pickAndroidFolder() {
    return new Promise((resolve) => {
      window.__pmResolveFolder = (name) => { window.__pmResolveFolder = null; resolve(name); };
      window.PokeModBridge.pmPickFolder();
      setTimeout(() => { if (window.__pmResolveFolder) { window.__pmResolveFolder = null; resolve(""); } }, 120000);
    });
  },

  _bridge(method, ...args) {
    return new Promise((resolve, reject) => {
      try {
        const r = window.PokeModBridge[method](...args);
        resolve(r);
      } catch (e) { reject(e); }
    });
  },

  async connectBrowser(dirHandle) {
    this._handles.set("", dirHandle);
    this.mode = "browser";
    this.folderName = dirHandle.name || "carpeta";
    await this.rebuildIndex();
  },

  async connectFallback(fileList) {
    this._files.clear();
    for (const f of fileList) {
      const rel = normalizeRel(f.webkitRelativePath || f.name);
      // Quitar el primer segmento (nombre de la carpeta raíz elegida)
      const parts = rel.split("/");
      parts.shift();
      this._files.set(parts.join("/"), f);
    }
    this.mode = "fallback";
    const first = fileList[0]?.webkitRelativePath?.split("/")[0] || "carpeta";
    this.folderName = first + " (solo lectura)";
    await this.rebuildIndex();
  },

  connectDemo(memMap, name = "Proyecto demo") {
    this._mem = memMap;
    this.mode = "demo";
    this.folderName = name;
    return this.rebuildIndex();
  },

  // -- Índice insensible a mayúsculas (¡clave en Android/Kirin!) -------------------
  async rebuildIndex() {
    this._indexLower = new Map();
    try {
      const all = await this.walk("", 30000);
      for (const p of all) {
        const l = p.toLowerCase();
        if (!this._indexLower.has(l)) this._indexLower.set(l, p);
      }
    } catch (e) {
      console.warn("rebuildIndex:", e);
    }
  },

  resolve(rel) {
    // Devuelve la ruta REAL conservando mayúsculas del FS.
    const n = normalizeRel(rel);
    if (!this._indexLower) return n;
    return this._indexLower.get(n.toLowerCase()) || n;
  },

  caseMismatches(wantedList) {
    // Para el chequeo Kirin: referencias cuya caja no coincide con el archivo.
    const out = [];
    for (const w of wantedList) {
      const real = this.resolve(w);
      if (real !== normalizeRel(w)) {
        const exists = this._indexLower?.has(normalizeRel(w).toLowerCase());
        out.push({ wanted: w, found: exists ? real : null });
      }
    }
    return out;
  },

  // -- Operaciones ------------------------------------------------------------------
  async list(relDir) {
    const rel = normalizeRel(relDir);
    if (this.mode === "android") {
      const j = await this._bridge("pmList", this.resolve(rel));
      return JSON.parse(j).map((e) => ({ name: e.n, path: (rel ? rel + "/" : "") + e.n, isDir: !!e.d, size: e.s || 0 }));
    }
    if (this.mode === "browser") {
      const h = await this._dirHandle(rel, false);
      const out = [];
      for await (const [name, entry] of h.entries()) {
        let size = 0;
        if (entry.kind === "file") {
          try { size = (await entry.getFile()).size; } catch { /* noop */ }
        }
        out.push({ name, path: (rel ? rel + "/" : "") + name, isDir: entry.kind === "directory", size });
      }
      return out.sort((a, b) => Number(b.isDir) - Number(a.isDir) || a.name.localeCompare(b.name));
    }
    if (this.mode === "fallback" || this.mode === "demo") {
      const map = this.mode === "fallback"
        ? new Map([...this._files, ...this.pendingWrites, ...this._backupMem])
        : new Map([...this._mem, ...this.pendingWrites]);
      const prefix = rel ? rel.toLowerCase() + "/" : "";
      const seen = new Map();
      for (const key of map.keys()) {
        const lk = key.toLowerCase();
        if (!lk.startsWith(prefix)) continue;
        const rest = key.slice(prefix.length);
        if (!rest) continue;
        const slash = rest.indexOf("/");
        if (slash < 0) {
          const v = map.get(key);
          seen.set(rest, { name: rest, path: key, isDir: false, size: v.size ?? v.length ?? 0 });
        } else {
          const d = rest.slice(0, slash);
          if (!seen.has(d)) seen.set(d, { name: d, path: (rel ? rel + "/" : "") + d, isDir: true, size: 0 });
        }
      }
      return [...seen.values()].sort((a, b) => Number(b.isDir) - Number(a.isDir) || a.name.localeCompare(b.name));
    }
    throw new Error("Sin carpeta conectada");
  },

  async walk(relDir, max = 30000) {
    const rel = normalizeRel(relDir);
    if (this.mode === "android") {
      const j = await this._bridge("pmWalk", this.resolve(rel), Math.min(max, 100000));
      return JSON.parse(j);
    }
    const out = [];
    const rec = async (dir, depth) => {
      if (out.length >= max || depth > 12) return;
      const items = await this.list(dir);
      for (const it of items) {
        if (out.length >= max) return;
        if (it.isDir) await rec(it.path, depth + 1);
        else out.push(it.path);
      }
    };
    if (this.mode === "browser") await rec(rel, 0);
    else {
      const map = this.mode === "fallback" ? this._files : this._mem;
      const prefix = rel ? rel.toLowerCase() + "/" : "";
      for (const key of map.keys()) {
        if (out.length >= max) break;
        if (!rel || key.toLowerCase().startsWith(prefix)) out.push(key);
      }
    }
    return out;
  },

  async exists(rel) {
    const n = normalizeRel(rel);
    if (this._indexLower?.has(n.toLowerCase())) return true;
    if (this.mode === "android") return (await this._bridge("pmExists", n)) === "1";
    if (this.mode === "browser") {
      try { await this._fileHandle(n, false); return true; }
      catch { return false; }
    }
    if (this.mode === "fallback") return this._files.has(n);
    if (this.mode === "demo") return this._mem.has(n);
    return false;
  },

  async readBytes(rel) {
    const n = this.resolve(rel);
    if (this.mode === "android") {
      // Lectura por bloques de 1 MB (Scripts.rxdata y mapas grandes).
      try {
        const size = parseInt(await this._bridge("pmSize", n), 10);
        if (Number.isFinite(size) && size >= 0 && size <= 256 * 1024 * 1024) {
          const CH = 1024 * 1024;
          const parts = [];
          for (let off = 0; off < size; off += CH) {
            parts.push(base64ToBytes(await this._bridge("pmReadChunk", n, off, Math.min(CH, size - off))));
          }
          const out = new Uint8Array(size);
          let o = 0;
          for (const p of parts) { out.set(p, o); o += p.length; }
          return out;
        }
      } catch (e) {
        console.warn("lectura por bloques falló, intento directa:", e);
      }
      return base64ToBytes(await this._bridge("pmRead", n));
    }
    if (this.mode === "browser") {
      const h = await this._fileHandle(n, false);
      return new Uint8Array(await (await h.getFile()).arrayBuffer());
    }
    if (this.mode === "fallback") {
      if (this.pendingWrites.has(n)) return this.pendingWrites.get(n);
      if (this._backupMem.has(n)) return this._backupMem.get(n);
      const f = this._files.get(n);
      if (!f) throw new Error("No existe: " + rel);
      return new Uint8Array(await f.arrayBuffer());
    }
    if (this.mode === "demo") {
      // pendingWrites tiene prioridad (ver cambios sin "guardar")
      if (this.pendingWrites.has(n)) return this.pendingWrites.get(n);
      const v = this._mem.get(n);
      if (!v) throw new Error("No existe: " + rel);
      return v;
    }
    throw new Error("Sin carpeta conectada");
  },

  async readText(rel) {
    const b = await this.readBytes(rel);
    try { return new TextDecoder("utf-8", { fatal: true }).decode(b); }
    catch { return new TextDecoder("windows-1252").decode(b); }
  },

  async writeBytes(rel, u8, opts = {}) {
    const n = normalizeRel(rel);
    const internal = !!opts.internal;
    if (!internal && isProtected(n)) throw new Error("[X] Protegido (partida o backup): no se puede escribir " + n);
    if (this.onBeforeWrite && this.mode !== "demo" && !internal && !opts.skipBackup) {
      await this.onBeforeWrite(n, u8);
    }
    if (internal && this.mode === "fallback") {
      this._backupMem.set(n, u8);
      this._indexLower?.set(n.toLowerCase(), n);
      return { written: true, memory: true };
    }
    if (internal && this.mode === "demo") {
      this._mem.set(n, u8);
      this.pendingWrites.delete(n);
      this._indexLower?.set(n.toLowerCase(), n);
      this._imgCache.delete(n.toLowerCase());
      return { written: true };
    }
    if (this.mode === "android") {
      await this._bridge("pmWrite", n, bytesToBase64(u8));
      this._indexLower?.set(n.toLowerCase(), n);
      this._imgCache.delete(n.toLowerCase());
      return { written: true };
    }
    if (this.mode === "browser") {
      const h = await this._fileHandle(n, true);
      const w = await h.createWritable();
      await w.write(u8);
      await w.close();
      this._indexLower?.set(n.toLowerCase(), n);
      this._imgCache.delete(n.toLowerCase());
      return { written: true };
    }
    // fallback/demo: se guarda como pendiente (descargar ZIP o aplicar en demo)
    this.pendingWrites.set(n, u8);
    this._imgCache.delete(n.toLowerCase());
    return { written: false, pending: true };
  },

  async writeText(rel, text) {
    return this.writeBytes(rel, new TextEncoder().encode(text));
  },

  async deleteFile(rel) {
    const n = normalizeRel(rel);
    if (isProtected(n)) throw new Error("[X] Protegido: no se puede borrar " + n);
    const real = this.resolve(n);
    if (this.mode === "android") {
      await this._bridge("pmDelete", real);
    } else if (this.mode === "browser") {
      const parts = real.split("/");
      const name = parts.pop();
      const dir = await this._dirHandle(parts.join("/"), false);
      // nombre con caja exacta
      let exact = name;
      for await (const [fname, entry] of dir.entries()) {
        if (entry.kind === "file" && fname.toLowerCase() === name.toLowerCase()) { exact = fname; break; }
      }
      await dir.removeEntry(exact);
    } else if (this.mode === "fallback") {
      this._files.delete(n);
      this.pendingWrites.delete(n);
      this.pendingDeletes.add(n);
    } else if (this.mode === "demo") {
      this._mem.delete(n);
      this.pendingWrites.delete(n);
    } else {
      throw new Error("Sin carpeta conectada");
    }
    this._indexLower?.delete(n.toLowerCase());
    this._imgCache.delete(n.toLowerCase());
    return true;
  },

  async readImage(rel) {
    const n = this.resolve(rel);
    const key = n.toLowerCase();
    if (this._imgCache.has(key)) return this._imgCache.get(key);
    const b = await this.readBytes(n);
    const blob = new Blob([b], { type: "image/png" });
    try {
      const bmp = await createImageBitmap(blob);
      this._imgCache.set(key, bmp);
      return bmp;
    } catch {
      // WebView antiguos: vía <img>
      const url = URL.createObjectURL(blob);
      const img = await new Promise((res, rej) => {
        const el = new Image();
        el.onload = () => res(el);
        el.onerror = rej;
        el.src = url;
      });
      this._imgCache.set(key, img);
      return img;
    }
  },

  // -- Interno (browser) ----------------------------------------------------------------
  async _dirHandle(rel, create) {
    const parts = normalizeRel(rel).split("/").filter(Boolean);
    let h = this._handles.get("");
    let cur = "";
    for (const p of parts) {
      cur = cur ? cur + "/" + p : p;
      if (!this._handles.has(cur)) {
        // buscar con caja exacta o aproximada
        let next = null;
        if (!create) {
          for await (const [name, entry] of h.entries()) {
            if (entry.kind === "directory" && name.toLowerCase() === p.toLowerCase()) { next = entry; break; }
          }
          if (!next) throw new Error("No existe carpeta: " + rel);
        } else {
          next = await h.getDirectoryHandle(p, { create: true });
        }
        this._handles.set(cur, next);
      }
      h = this._handles.get(cur);
    }
    return h;
  },

  async _fileHandle(rel, create) {
    const n = normalizeRel(rel);
    const parts = n.split("/");
    const name = parts.pop();
    const dir = await this._dirHandle(parts.join("/"), create);
    if (!create) {
      for await (const [fname, entry] of dir.entries()) {
        if (entry.kind === "file" && fname.toLowerCase() === name.toLowerCase()) return entry;
      }
      throw new Error("No existe: " + rel);
    }
    return dir.getFileHandle(name, { create: true });
  },
};// ============================================================================
// helpers.js — UI compartida: toast, modales, progreso, selectores
// ============================================================================
import { S, loadMap } from "./app.js";
import { FS } from "./fs.js";
import { parseEvent } from "./rmxp.js";
import { drawCharacterPreview } from "./render.js";
import { esc } from "./util.js";

// --- Toast -------------------------------------------------------------------------
export function toast(msg, kind = "info", ms = 3500) {
  const box = document.getElementById("toast");
  const d = document.createElement("div");
  d.className = "toast " + kind;
  d.textContent = msg;
  box.appendChild(d);
  setTimeout(() => d.classList.add("show"));
  setTimeout(() => { d.classList.remove("show"); setTimeout(() => d.remove(), 400); }, ms);
}

// --- Modal ---------------------------------------------------------------------------
export function openModal({ title, body, actions = [], wide = false }) {
  closeModal();
  const ov = document.createElement("div");
  ov.id = "modal-ov";
  ov.className = "modal-ov";
  ov.innerHTML = `<div class="modal${wide ? " wide" : ""}" role="dialog">
    <div class="modal-h"><b>${esc(title)}</b><button class="iconbtn" data-x>X</button></div>
    <div class="modal-b"></div>
    <div class="modal-f"></div>
  </div>`;
  const b = ov.querySelector(".modal-b");
  if (typeof body === "string") b.innerHTML = body;
  else b.appendChild(body);
  const f = ov.querySelector(".modal-f");
  for (const a of actions) {
    const btn = document.createElement("button");
    btn.className = "btn " + (a.cls || "");
    btn.textContent = a.label;
    btn.onclick = () => a.onClick?.(closeModal, ov);
    f.appendChild(btn);
  }
  if (!actions.length) f.remove();
  ov.querySelector("[data-x]").onclick = closeModal;
  ov.addEventListener("mousedown", (e) => { if (e.target === ov) closeModal(); });
  document.body.appendChild(ov);
  return ov;
}

export function closeModal() {
  document.getElementById("modal-ov")?.remove();
}

export function confirmDialog(title, message, okLabel = "Confirmar") {
  return new Promise((resolve) => {
    openModal({
      title,
      body: `<p>${esc(message)}</p>`,
      actions: [
        { label: "Cancelar", onClick: (close) => { close(); resolve(false); } },
        { label: okLabel, cls: "danger", onClick: (close) => { close(); resolve(true); } },
      ],
    });
  });
}

// --- Progreso con cancelación --------------------------------------------------------------
export function showProgress(title) {
  const ov = openModal({
    title,
    body: `<div class="prog"><div class="prog-bar"><div class="prog-fill"></div></div><div class="prog-label">…</div></div>`,
    actions: [{ label: "Cancelar", onClick: () => { st.cancelled = true; } }],
  });
  const fill = ov.querySelector(".prog-fill");
  const label = ov.querySelector(".prog-label");
  const st = { cancelled: false };
  return {
    update(i, total, text) {
      fill.style.width = total ? Math.round((i / total) * 100) + "%" : "0%";
      label.textContent = text || `${i}/${total}`;
      if (st.cancelled) S.scanCancel = true;
    },
    close: closeModal,
    get cancelled() { return st.cancelled; },
  };
}

// --- Selector de mapa (modal con buscador + árbol) ---------------------------------------------
export function mapPickerModal(title, onPick) {
  const wrap = document.createElement("div");
  wrap.innerHTML = `<input class="inp" placeholder="Buscar mapa por nombre o ID…" />
    <div class="picklist"></div>`;
  const inp = wrap.querySelector("input");
  const list = wrap.querySelector(".picklist");
  const draw = (filter = "") => {
    const f = filter.trim().toLowerCase();
    const items = S.tree.filter((m) =>
      !f || m.name.toLowerCase().includes(f) || String(m.id) === f || String(m.id).includes(f));
    list.innerHTML = items.slice(0, 400).map((m) =>
      `<button class="pickrow" data-id="${m.id}">
        <span class="mono muted">${m.id}</span>
        <span style="margin-left:${m.depth * 14}px">${esc(m.name)}</span>
      </button>`).join("") || `<p class="muted">Sin resultados.</p>`;
    if (items.length > 400) list.innerHTML += `<p class="muted">…${items.length - 400} más (afina la búsqueda)</p>`;
    list.querySelectorAll(".pickrow").forEach((b) => {
      b.onclick = () => { closeModal(); onPick(Number(b.dataset.id)); };
    });
  };
  inp.oninput = () => draw(inp.value);
  draw();
  openModal({ title, body: wrap, wide: true });
  setTimeout(() => inp.focus(), 100);
}

// --- Selector de sprite de personaje --------------------------------------------------------------
export async function spritePickerModal(title, current, onPick) {
  const wrap = document.createElement("div");
  wrap.innerHTML = `<input class="inp" placeholder="Buscar sprite…" /><div class="spritegrid"></div>`;
  const grid = wrap.querySelector(".spritegrid");
  const inp = wrap.querySelector("input");
  const draw = async (filter = "") => {
    const f = filter.trim().toLowerCase();
    const files = S.characters.filter((n) => !f || n.toLowerCase().includes(f)).slice(0, 120);
    grid.innerHTML = `<button class="sprrow${!current ? " sel" : ""}" data-n="">
      <span class="sprnone">∅</span><span>Sin gráfico</span></button>` +
      files.map((n) => `<button class="sprrow${n.replace(/\.[^.]+$/, "") === current ? " sel" : ""}" data-n="${esc(n)}">
        <canvas width="48" height="48"></canvas><span>${esc(n)}</span></button>`).join("");
    grid.querySelectorAll(".sprrow").forEach((b) => {
      b.onclick = () => {
        const n = b.dataset.n;
        closeModal();
        onPick(n ? n.replace(/\.[^.]+$/, "") : "");
      };
    });
    // previews perezosas
    for (const b of grid.querySelectorAll(".sprrow[data-n]:not([data-n=''])")) {
      try {
        const img = await FS.readImage("Graphics/Characters/" + b.dataset.n);
        const cv = b.querySelector("canvas");
        if (cv) drawCharacterPreview(cv, img, 2, 1);
      } catch { /* noop */ }
    }
  };
  inp.oninput = () => draw(inp.value);
  openModal({ title, body: wrap, wide: true });
  draw();
}

// --- Selector de evento de un mapa -------------------------------------------------------------------
export async function eventPickerModal(mapId, onPick) {
  const rec = await loadMap(mapId);
  const rows = [];
  for (const { id, obj } of rec.parsed.events) {
    let name = "";
    try { name = parseEvent(obj).name; } catch { name = "?"; }
    const x = obj.getIvar?.("x") ?? "?", y = obj.getIvar?.("y") ?? "?";
    rows.push(`<button class="pickrow" data-id="${id}"><span class="mono muted">${id}</span><span>${esc(name)}</span><span class="muted">(${x},${y})</span></button>`);
  }
  const wrap = document.createElement("div");
  wrap.innerHTML = `<div class="picklist">${rows.join("") || "<p class=muted>Sin eventos.</p>"}</div>`;
  wrap.querySelectorAll(".pickrow").forEach((b) => {
    b.onclick = () => { closeModal(); onPick(Number(b.dataset.id)); };
  });
  openModal({ title: `Eventos del mapa ${mapId}`, body: wrap, wide: true });
}

export function debounce(fn, ms = 250) {
  let t = null;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}// Historial transaccional pequeño para los editores de PokeMod Studio.
// Guarda snapshots antes/después y mantiene acotado el uso de memoria.
function snapshotEquals(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b || a == null || b == null) return false;
  if (typeof a !== "object") return false;
  if (a instanceof Uint8Array || b instanceof Uint8Array) {
    if (!(a instanceof Uint8Array) || !(b instanceof Uint8Array) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
    return true;
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((v, i) => snapshotEquals(v, b[i]));
  }
  const ak = Object.keys(a), bk = Object.keys(b);
  return ak.length === bk.length && ak.every((k) => Object.prototype.hasOwnProperty.call(b, k) && snapshotEquals(a[k], b[k]));
}

function snapshotSize(value) {
  if (typeof value === "string") return value.length * 2;
  if (value instanceof Uint8Array) return value.byteLength;
  if (Array.isArray(value)) return value.reduce((n, x) => n + snapshotSize(x), 0);
  if (value && typeof value === "object") return Object.values(value).reduce((n, x) => n + snapshotSize(x), 0);
  return 8;
}

export function createHistory({ maxEntries = 40, maxBytes = 24 * 1024 * 1024, onChange = () => {} } = {}) {
  const undoStack = [];
  const redoStack = [];
  let bytes = 0;
  let busy = false;

  const state = () => ({
    canUndo: undoStack.length > 0 && !busy,
    canRedo: redoStack.length > 0 && !busy,
    busy,
    undoLabel: undoStack.length ? undoStack[undoStack.length - 1].label : "",
    redoLabel: redoStack.length ? redoStack[redoStack.length - 1].label : "",
    undoCount: undoStack.length,
    redoCount: redoStack.length,
    bytes,
  });
  const notify = () => {
    try { onChange(state()); } catch { /* la UI no debe romper el historial */ }
  };
  const discard = (stack) => {
    while (stack.length) bytes -= stack.pop().size;
  };
  const clear = () => {
    undoStack.length = 0;
    redoStack.length = 0;
    bytes = 0;
    notify();
  };

  function record({ label, before, after, restore, equals = snapshotEquals, measure = snapshotSize }) {
    if (busy) throw new Error("El historial está ocupado.");
    if (equals(before, after)) return false;
    if (typeof restore !== "function") throw new TypeError("La entrada del historial necesita una función restore.");

    // Una edición nueva descarta la rama de rehacer.
    discard(redoStack);
    const size = Math.max(0, measure(before)) + Math.max(0, measure(after));
    if (maxEntries < 1 || size > maxBytes) {
      // No dejamos que Deshacer salte una operación que no pudo registrarse.
      discard(undoStack);
      notify();
      return false;
    }
    undoStack.push({ label: String(label || "Edición"), before, after, restore, equals, measure, size });
    bytes += size;
    while (undoStack.length + redoStack.length > maxEntries || bytes > maxBytes) {
      const oldest = undoStack.shift();
      if (!oldest) break;
      bytes -= oldest.size;
    }
    notify();
    return true;
  }

  async function move(from, to, snapshot, direction) {
    if (busy || !from.length) return null;
    const entry = from.pop();
    busy = true;
    notify();
    try {
      await entry.restore(entry[snapshot], direction);
      to.push(entry);
      return entry;
    } catch (error) {
      from.push(entry);
      throw error;
    } finally {
      busy = false;
      notify();
    }
  }

  return {
    record,
    clear,
    undo: () => move(undoStack, redoStack, "before", "undo"),
    redo: () => move(redoStack, undoStack, "after", "redo"),
    get state() { return state(); },
  };
}import { createHistory } from "./history.js";

let pass = 0, fail = 0;
const ok = (condition, message) => {
  if (condition) pass++;
  else { fail++; console.error("FALLA:", message); }
};

let value = "base";
const h = createHistory({ maxEntries: 3, maxBytes: 1024 });
const recordValue = (label, before, after) => h.record({
  label,
  before,
  after,
  restore: async (next) => { value = next; },
});

ok(!h.state.canUndo && !h.state.canRedo, "inicia vacío");
value = "uno";
recordValue("cambiar a uno", "base", "uno");
ok(h.state.canUndo && !h.state.canRedo, "registra una edición");
let entry = await h.undo();
ok(entry?.label === "cambiar a uno" && value === "base", "deshace el último valor");
ok(!h.state.canUndo && h.state.canRedo, "mueve entrada a rehacer");
entry = await h.redo();
ok(entry?.label === "cambiar a uno" && value === "uno", "rehace el valor");

value = "dos";
recordValue("cambiar a dos", "uno", "dos");
await h.undo();
value = "alternativo";
recordValue("nueva rama", "uno", "alternativo");
ok(!h.state.canRedo, "una edición nueva descarta la rama de rehacer");
ok(!h.record({ label: "sin cambio", before: "igual", after: "igual", restore() {} }), "omite snapshots idénticos");

let changedDuringFailure = false;
const failed = createHistory();
failed.record({
  label: "falla reversible",
  before: 0,
  after: 1,
  restore: async () => { changedDuringFailure = true; throw new Error("fallo de prueba"); },
});
try { await failed.undo(); } catch { /* fallo esperado */ }
ok(changedDuringFailure && failed.state.canUndo && !failed.state.canRedo, "si falla restore conserva la entrada para reintentar");

const limited = createHistory({ maxEntries: 1, maxBytes: 1024 });
limited.record({ label: "primera", before: "a", after: "b", restore() {} });
limited.record({ label: "segunda", before: "b", after: "c", restore() {} });
ok(limited.state.undoCount === 1 && limited.state.undoLabel === "segunda", "respeta el máximo de entradas");

const oversized = createHistory({ maxEntries: 4, maxBytes: 4 });
oversized.record({ label: "demasiado grande", before: "larguísimo", after: "otro texto", restore() {} });
ok(!oversized.state.canUndo && oversized.state.bytes === 0, "no retiene snapshots que exceden el límite de memoria");

console.log(`\nhistorial: ${pass} OK, ${fail} fallos`);
process.exit(fail ? 1 : 0);// Prueba de integración del núcleo SIN navegador (stub de canvas/DOM).
