export function humanizeCommand(code, params) {
  const c = COMMANDS[code];
  if (!c) return { title: `Comando ${code}`, detail: "", known: false };
  let detail = "";
  try { detail = c.d(params) || ""; } catch { detail = ""; }
  return { title: c.t, detail, known: true };
}

function trunc(s, n = 60) {
  s = String(s ?? "");
  return s.length > n ? s.slice(0, n) + "…" : s;
}
/**
 * Fire Ash usa Pokémon Essentials v19: el comando 101 lleva UN parámetro que es
 * la primera línea del diálogo y los 401 siguientes se le añaden con un espacio
 * (Data/Scripts → Interpreter_Commands#command_101). El formato RMXP clásico
 * (4 parámetros: cara, índice, lado, fondo) casi no aparece en este juego.
 * Antes el editor mostraba esa línea como si fuera la CARA del NPC, así que los
 * diálogos parecían salir a nombre del NPC equivocado.
 */
export function isFireAshText101(params) {
  const p = params || [];
  if (p.length === 1) return true;
  // 4+ params: si el primero no es una cara conocida y el cuarto es un número
  // de fondo (0..2), sigue siendo formato RMXP.
  return false;
}

/** El mensaje completo de un diálogo: 101 + sus 401 de continuación. */
export function messageBlockOf(list, index) {
  const first = list[index];
  if (!first) return null;
  const code = Number(first.getIvar ? first.getIvar("code") : first.code);
  if (code !== 101 && code !== 401) return null;
  // Un bloque = el 101 más los 401 que le siguen. Un 101 nuevo abre OTRA caja
  // (en el motor pone message_end = "\1" y el texto sale en otra ventana).
  let start = index;
  const codeAt = (k) => Number(list[k].getIvar ? list[k].getIvar("code") : list[k].code);
  if (codeAt(index) === 401) {
    while (start > 0 && codeAt(start) === 401) start--;
  }
  const out = [];
  for (let i = start; i < list.length; i++) {
    const o = list[i];
    const c = codeAt(i);
    if (c === 401 && !out.length) continue;
    if (c !== 401 && c !== 101) break;
    if (c === 101 && out.length) break; // nueva caja
    const params = o.getIvar ? o.getIvar("parameters") : o.parameters;
    out.push({ i, obj: o, code: c, params, rs: params?.[0] instanceof RString ? params[0] : null });
  }
  return out.length ? out : null;
}

/** Junta el texto del bloque con el MISMO algoritmo que el motor del juego. */
export function messageTextOf(block) {
  let msg = "";
  const head = block[0];
  if (head?.code === 101) {
    if (isFireAshText101(head.params)) msg = rstr(head.params[0]);
    else {
      // formato RMXP: la primera línea real está en el 401 siguiente
      msg = "";
    }
  }
  for (const part of block) {
    if (part.code !== 401) continue;
    const t = rstr(part.params[0]);
    if (msg !== "" && t !== "" && !msg.endsWith(" ")) msg += " ";
    msg += t;
  }
  return msg;
}

/** ¿El texto lleva un nombre de personaje («Nombre: …» o «\sp[Nombre]»)? */
export function speakerOf(text) {
  const s = String(text ?? "");
  const sp = s.match(/^\\sp\[([^\]]{1,28})\]\s*/);
  if (sp) return { name: sp[1], rest: s.slice(sp[0].length) };
  const m = s.match(/^\s*([^:\n]{2,28}?)\s*[:—]\s+/);
  if (m && !/^[0-9]/.test(m[1]) && m[1].split(/\s+/).length <= 4) {
    return { name: m[1].trim(), rest: s.slice(m[0].length) };
  }
  return { name: "", rest: s };
}

/**
 * Ancho visible de un texto de Essentials (los códigos \b \r \c[n] \v[n] \PN
 * no ocupan lugar en la caja).
 */
export function visibleWidth(text) {
  return String(text ?? "")
    .replace(/\\sp\[[^\]]*\]/g, "")
    .replace(/\\[cv]\[\d+\]/g, "")
    .replace(/\\[a-zA-Z]+/g, "").length;
}

/**
 * Envuelve el texto como lo hará la caja del juego (ancho en caracteres).
 * Devuelve las líneas que se verán, respetando los saltos explícitos (\n).
 */
export function wrapMessage(text, cols = 53, maxLines = Infinity) {
  const out = [];
  for (const raw of String(text ?? "").split(/\\n/)) {
    const words = raw.split(/ +/);
    let line = "";
    for (const w of words) {
      if (!line.length) { line = w; continue; }
      if (visibleWidth(line) + 1 + visibleWidth(w) <= cols) line += " " + w;
      else { out.push(line); line = w; }
    }
    out.push(line);
  }
  return maxLines === Infinity ? out : out.slice(0, maxLines);
}

/**
 * Reajusta el texto a la caja con saltos explícitos (\n), de forma que el juego
 * muestre exactamente lo que enseña la vista previa del editor. Devuelve
 * { texto, lineas, paginas }.
 */
export function reflowMessage(text, cols = 53, linesPerBox = 2) {
  const lines = wrapMessage(text, cols);
  const paginas = [];
  for (let i = 0; i < lines.length; i += linesPerBox) paginas.push(lines.slice(i, i + linesPerBox));
  return { texto: lines.join("\\n"), lineas: lines, paginas };
}

/**
 * Escribe el diálogo de vuelta al mapa.
 * Fire Ash une el parámetro 0 del 101 con los 401 siguientes: por eso el editor
 * guarda TODO el mensaje en el 101 y retira los 401 sobrantes (mismo texto, sin
 * riesgo de que el motor añada espacios raros). Devuelve cuántos comandos quitó.
 */
export function applyDialogueText(block, speaker, body) {
  if (!block?.length) return 0;
  const name = String(speaker ?? "").trim();
  const full = (name ? `\\sp[${name}]` : "") + String(body ?? "");
  const head = block[0];
  const params = head.params;
  if (params?.[0] instanceof RString) params[0].text = full;
  else if (params) params[0] = RString.fromText(full);
  else return 0;
  const extras = block.slice(1).map((b) => b.obj).filter(Boolean);
  return extras.length;
}

/** Texto troceado en líneas de caja (lo que el jugador verá, "\n" incluidos). */
export function pageMessage(text, cols = 53, linesPerBox = 2) {
  const lines = wrapMessage(text, cols);
  const pages = [];
  for (let i = 0; i < lines.length; i += linesPerBox) pages.push(lines.slice(i, i + linesPerBox));
  return pages;
}

function faceInfo(p) {
  const bits = [];
  if (rstr(p[0])) bits.push("cara: " + rstr(p[0]));
  if (p[2] === 1) bits.push("tenue");
  if (p[2] === 2) bits.push("transparente");
  if (p[3] === 0) bits.push("arriba");
  if (p[3] === 1) bits.push("medio");
  return bits.join(" · ");
}
function swRange(p) {
  const a = p[0], b = p[1], v = p[2] ? "ON" : "OFF";
  return a === b ? `Interruptor[${a}] = ${v}` : `Interruptores[${a}-${b}] = ${v}`;
}
function operand(p, i) {
  if (p[i] === 0) return String(p[i + 1]);
  if (p[i] === 1) return `Variable[${p[i + 1]}]`;
  return "?";
}
function varText(p) {
  const ops = ["=", "+=", "−=", "×=", "÷=", "%="];
  const rng = p[0] === p[1] ? `Variable[${p[0]}]` : `Variables[${p[0]}-${p[1]}]`;
  const op = ops[p[2]] ?? "?";
  let rhs = "?";
  const t = p[3];
  if (t === 0) rhs = String(p[4]);
  else if (t === 1) rhs = `Variable[${p[4]}]`;
  else if (t === 2) rhs = `azar(${p[4]}..${p[5]})`;
  else if (t === 3) rhs = `ítem ${p[4]}`;
  else if (t === 4) rhs = `actor ${p[4]} dato ${p[5]}`;
  else if (t === 5) rhs = `enemigo ${p[4]} dato ${p[5]}`;
  else if (t === 6) rhs = `personaje ${p[4]} dato ${p[5]}`;
  else if (t === 7) rhs = "otros…";
  return `${rng} ${op} ${rhs}`;
}
function itemChange(p) {
  return `id ${p[0]} ${p[1] ? "−" : "+"} ${operand(p, 2)}`;
}
function transferText(p) {
  if (p[0] === 0) return `Mapa ${p[1]} (${p[2]},${p[3]}) ${DIR_NAMES[p[4]] || ""}`;
  return `Mapa V[${p[1]}] (V[${p[2]}],V[${p[3]}])`;
}
function setEventLocText(p) {
  if (p[1] === 0) return `ev ${p[0]} → (${p[2]},${p[3]})`;
  if (p[1] === 1) return `ev ${p[0]} ⇄ ev ${p[2]}`;
  return `ev ${p[0]} → V[${p[2]}],V[${p[3]}]`;
}
function audioName(o) {
  if (!o || typeof o.getIvar !== "function") return "";
  return rstr(o.getIvar("name"));
}
function battleText(p) {
  if (p[0] === 0) return `tropa ${p[1]}`;
  if (p[1] === 0) return `mapa ${p[1]}`;
  return `V[${p[1]}]`;
}
function charStat(p, what) {
  return `${what} obj ${p[0]} ${p[2] ? "−" : "+"} ${operand(p, 3)}`;
}
function condBranchText(p) {
  const t = p[0];
  try {
    switch (t) {
      case 0: return `Interruptor[${p[1]}] ${p[2] ? "ON" : "OFF"}`;
      case 1: {
        const ops = ["==", "≥", "≤", ">", "<", "≠"];
        return `Variable[${p[1]}] ${ops[p[2]] ?? "?"} ${p[3] === 0 ? p[4] : "V[" + p[4] + "]"}`;
      }
      case 2: return `Self-switch ${rstr(p[1])} ${p[2] ? "ON" : "OFF"}`;
      case 3: return `Temporizador ${p[2] ? "≤" : "≥"} ${p[1]}s`;
      case 4: return `Actor ${p[1]}…`;
      case 5: return `Enemigo ${p[1]}…`;
      case 6: return `Personaje ${p[1]} mira ${DIR_NAMES[p[2]] || p[2]}`;
      case 7: return `Dinero ${p[2] ? "≤" : "≥"} ${p[1]}`;
      case 8: return `Tiene ítem ${p[1]}`;
      case 9: return `Tiene arma ${p[1]}`;
      case 10: return `Tiene armadura ${p[1]}`;
      case 11: return `Botón ${["", "abajo", "izq.", "der.", "arriba", "A", "B", "C", "X", "Y", "Z", "L", "R"][p[1]] || p[1]}`;
      case 12: return `Script: ${trunc(rstr(p[1]), 50)}`;
      default: return `tipo ${t}`;
    }
  } catch { return ""; }
}

// --- Texto editable de un comando -----------------------------------------------
export const EDITABLE_TEXT = new Set([101, 401, 102, 402, 108, 408, 355, 655, 118, 119, 320, 122]);
export function getCommandStrings(code, params) {
  // Devuelve lista de {i, sub, rstring} editables dentro de params (normalmente 1)
  const out = [];
  const push = (i, sub = -1) => {
    const v = sub >= 0 ? params[i]?.[sub] : params[i];
    if (v instanceof RString) out.push({ i, sub, rs: v });
  };
  switch (code) {
    case 101:
      // Fire Ash: el parámetro 0 es la PRIMERA LÍNEA del diálogo (editable).
      if (isFireAshText101(params)) push(0);
      break;
    case 401: case 108: case 408: case 355: case 655: case 118: case 119: case 320:
      push(code === 320 ? 2 : 0); break;
    case 102:
      (params[0] || []).forEach((_, s) => push(0, s));
      break;
    case 402: push(1); break;
  }
  return out;
}

// --- Tilesets ----------------------------------------------------------------------
export function parseTileset(tsObj) {
  const passages = tableFromUserDef(tsObj.getIvar("passages"));
  const priorities = tableFromUserDef(tsObj.getIvar("priorities"));
  let terrain = null;
  try { terrain = tableFromUserDef(tsObj.getIvar("terrain_tags")); } catch { /* algunos juegos no lo usan igual */ }
  return {
    obj: tsObj,
    id: Number(tsObj.getIvar("id")),
    name: rstr(tsObj.getIvar("name")),
    tilesetName: rstr(tsObj.getIvar("tileset_name")),
    autotiles: (tsObj.getIvar("autotile_names") || []).map(rstr),
    passages, priorities, terrain,
  };
}

// --- System (nombres de interruptores/variables) -----------------------------------
export function systemNames(sysObj) {
  const sw = (sysObj.getIvar("switches") || []).map((s) => rstr(s));
  const va = (sysObj.getIvar("variables") || []).map((s) => rstr(s));
  return { switches: sw, variables: va };
}
export function setSystemName(sysObj, kind, id, name) {
  const arr = sysObj.getIvar(kind === "sw" ? "switches" : "variables");
  if (!arr || !arr[id]) return false;
  if (arr[id] instanceof RString) arr[id].text = name;
  else arr[id] = RString.fromText(name);
  return true;
}

// --- Búsqueda de usos de flags en un mapa ------------------------------------------
export function findFlagUsesInMap(parsedMap, kind, id) {
  // kind: "sw" | "var" | "self"
  const uses = [];
  for (const { id: evId, obj: evObj } of parsedMap.events) {
    const ev = parseEvent(evObj);
    for (const page of ev.pages) {
      const c = page.condition;
      if (c) {
        if (kind === "sw" && (c.switch1 === id || c.switch2 === id)) {
          uses.push({ evId, evName: ev.name, page: page.index, where: "Condición de página" });
        }
        if (kind === "var" && c.variable && c.variable.id === id) {
          uses.push({ evId, evName: ev.name, page: page.index, where: "Condición de página (variable)" });
        }
      }
      for (const cmdObj of page.list) {
        const { code, params } = cmdOf(cmdObj);
        if (kind === "sw" && code === 121 && id >= params[0] && id <= params[1]) {
          uses.push({ evId, evName: ev.name, page: page.index, where: `Control: Switch[${id}]` });
        }
        if (kind === "sw" && code === 111 && params[0] === 0 && params[1] === id) {
          uses.push({ evId, evName: ev.name, page: page.index, where: `Condición: Switch[${id}]` });
        }
        if (kind === "var" && code === 122 && id >= params[0] && id <= params[1]) {
          uses.push({ evId, evName: ev.name, page: page.index, where: `Control: Variable[${id}]` });
        }
        if (kind === "var" && code === 111 && params[0] === 1 && params[1] === id) {
          uses.push({ evId, evName: ev.name, page: page.index, where: `Condición: Variable[${id}]` });
        }
      }
    }
  }
  return uses;
}// ============================================================================
